%% Audio_DSP_GUI.m 
% - 需要外部文件：handle 对象 类DSPState()（DSPState.m），S 的默认值已在类DSPState()中定义 
% - 需要外部文件：handle 对象 类GUIHandles()（GUIHandles.m），handles 的句柄接收/默认值已在类GUIHandles()中定义 
% - 需要外部文件：cfirpm示例频率响应函数(cfirpm_fresp_example.m)；firpm示例频率响应函数(firpm_fresp_example.m)；最小二乘法firls多带中校验部分的函数(firchk_local.m)
% - 需要外部文件：说明文档：README.md（需要外部文件夹 "assets"，用于 README.md 中流程图显示）
% - 需要外部文件夹：firpm/cfirpm 的示例频率响应函数的UI界面预览，本地html显示，需要 "matlab_prism_offline"文件夹
%
% 说明：主GUI界面全屏时，左侧“控制面板”可能会出现 大部分留白/控件显示不全等问题，此时可以调节：
%       (1) heightErrorCorrection = 54;   % 高度误差修正（正负值均可）。可通过查找该参数赋值处（1处）然后进行修改。
%       (2) 对于“截止频率滑块”控件的显示可以调节： 
%            1) ctlRowHgtSld  = ctlRowHgtAvg * 1.25; %  1.25可以进行修改，理论上应该大于1，因为"截止频率滑块"行高度需要的多一些。可通过查找该参数赋值处（1处）然后进行修改。
%            2) gF_RowHgtSld =  gF_RowHgtAvg * 1.16; %  1.16可以进行修改，理论上应该大于1，因为"截止频率滑块"行高度需要的多一些。可通过查找该参数赋值处（1处）然后进行修改。  
%

%% 主函数
function Audio_DSP_GUI

    %% ================= 初始状态 =================
    S = DSPState();  % handle 对象，默认值已在类DSPState()中定义


    %% ================= 主界面 =================
    fig_GUI = createCenteredUIFigure('Name','数字滤波器设计与应用','Position',[50 50 1280 760]);

    % ------------------- 用显示器尺寸动态计算行高 -------------------
    % 选取显示器（优先鼠标在的显示器）
    [monitorLeft, monitorBottom, monitorWidth, monitorHeight, monitorUsedIdx] = pickMonitorByPointerFirst([]);
    screenHeight = monitorHeight;            % 取显示器高度（像素）

    % 主网格：前3行高度由 mainRowH 决定，第4行固定 noteRowH
    monitorTaskbarH = 60;        % 显示器底部任务栏高度（像素）
    noteRowH = 150;              % GUI 信息显示栏（备注栏）高度（像素）
    gl_GUI_RowSpacing = 10;      % GUI 主网格4行的行间距（像素）
    gl_GUI_udPadding = 3;        % GUI 主网格上下（顶部/底部）间距（像素）
    gl_GUI_titleH = 16;          % GUI 主网格标题高度（像素）
    % % GUI 主网格4行 前3行的高度
    mainRowH = (screenHeight - noteRowH - monitorTaskbarH - gl_GUI_RowSpacing*3 - gl_GUI_udPadding*2 - gl_GUI_titleH) / 3;
    
    % 左侧控件网格 ctl：前27行平均为 ctlRowHgtAvg ，第28行固定 ctlStatusBarRowH
    numelCtlRow = 27;       % 左侧操作面板 除“状态显示栏”外总共的行数
    ctlStatusBarRowH = 27;  % 左侧操作面板 状态显示栏高度（像素）
    ctlTitleH = 16;         % 左侧操作面板 各子面板标题高度（像素）
    ctlUdPadding = 3;       % 左侧操作面板 各子面板上下（顶部/底部）间距（像素）
    ctlRowSpacing = 2;      % 左侧操作面板 28行的行间距（像素）
    heightErrorCorrection = 54; % 高度误差修正

    % 27行 每行行高平均值
    ctlRowHgtAvg = (screenHeight - gl_GUI_udPadding*2 - gl_GUI_titleH ...
        - monitorTaskbarH - ctlStatusBarRowH - heightErrorCorrection) / numelCtlRow;

    ctlRowHgtSld  = ctlRowHgtAvg * 1.25;                                               % 27行 截止频率滑块控件这几行的行高。可以调节，另一个调节点见 gF_RowHgtSld 赋值处。
    ctlRowHgtBase = (ctlRowHgtAvg * numelCtlRow - ctlRowHgtSld*4)/ (numelCtlRow - 4);  % 27行 除了截止频率滑块控件这几行外的其他行的行高


    % 调整行高分配，增加图形区域高度；主网格改为3列（原为5列）
    gl_GUI = uigridlayout(fig_GUI,[4 3]); % 改为3列
    gl_GUI.RowHeight = {mainRowH,mainRowH,mainRowH,noteRowH}; %主网格前3行使用mainRowH，第4行使用固定值noteRowH
    gl_GUI.ColumnWidth = {400,'1x','1x'};
    gl_GUI.Padding = [5, gl_GUI_udPadding, 8, gl_GUI_udPadding];
    gl_GUI.RowSpacing = gl_GUI_RowSpacing;
    gl_GUI.ColumnSpacing = 12;
    
    %% ================= 左侧操作面板 =================
    pnl = uipanel(gl_GUI);
    pnl.Layout.Row = [1 4]; % 调整为1-4行
    pnl.Layout.Column = 1;

    % 在左侧面板内使用子网格，并用小的子面板明确分区
    ctl = uigridlayout(pnl,[28 1]); % 修改：从27行到28行
    % 前27行 分为“截止频率滑块高度”（4行）和“其他控件高度”（23行），第28行固定27像素
    ctl.RowHeight = [repmat({ctlRowHgtBase},1,11), repmat({ctlRowHgtSld},1,4), repmat({ctlRowHgtBase},1,12), {27}]; 
    ctl.Padding = [3, ctlUdPadding, 3, ctlUdPadding];
    ctl.RowSpacing = ctlRowSpacing;

    % =========================== 子面板：数据 I/O ===========================
    gIO_Height = ctlRowHgtBase * 4;  % 数据 I/O 子面板占28行的[1 4]行
    gIO_RowSpacing = 6;           % 数据 I/O 子面板4行行间距
    % 数据 I/O 子面板4行每行行高
    gIO_RowH = (gIO_Height - gIO_RowSpacing*3 - ctlTitleH - ctlUdPadding*2) / 4;


    pIO = uipanel(ctl,'Title','数据 I/O','FontWeight','bold');  
    pIO.Layout.Row = [1 4]; pIO.Layout.Column = 1;
    % 扩展为更多行和列以容纳数据来源与多频正弦控件
    gIO = uigridlayout(pIO,[4 4]); % 4行4列
    gIO.RowHeight = repmat({gIO_RowH}, 1, 4);
    gIO.ColumnWidth = {'1x','1x','1x','1x'};
    gIO.Padding = [6, ctlUdPadding, 6, ctlUdPadding];
    gIO.RowSpacing = gIO_RowSpacing;

    % 数据来源下拉
    lblDataSource = uilabel(gIO,'Text','数据来源：','HorizontalAlignment','left');
    lblDataSource.Layout.Row = 1; lblDataSource.Layout.Column = 1;
    ddDataSource = uidropdown(gIO,'Items',{'音频信号','多频正弦','导入工作区数据'},'Value','音频信号');
    ddDataSource.Layout.Row = 1; ddDataSource.Layout.Column = 2;
    ddDataSource.ValueChangedFcn = @onDataSourceChange;

    % 多频正弦相关控件
    btnMT_Gen = uibutton(gIO,'push','Text','生成多频正弦','ButtonPushedFcn',@onMTGenerate);
    btnMT_Gen.Layout.Row = 2; btnMT_Gen.Layout.Column = [3 4];

    % 采样率
    lblFs_GUI = uilabel(gIO,'Text','采样率Fs(Hz):','HorizontalAlignment','left', 'Tooltip','采样率来源于音频数据，非用户自定义，如需自定义，请点击"重采样"');
    lblFs_GUI.Layout.Row = 1; lblFs_GUI.Layout.Column = 3;
    % 改为文本显示（只读信息）
    lblFsValue = uilabel(gIO, 'Text', '44100', 'HorizontalAlignment', 'center', 'FontWeight', 'bold', 'Tooltip','采样率来源于音频数据，非用户自定义，如需自定义，请点击"重采样"');
    lblFsValue.Layout.Row = 1; lblFsValue.Layout.Column = 4;
    % 注：不再把 ValueChangedFcn 直接绑定到 user edit 操作（改由按钮触发）

    % ---- 绘图设置 按钮（替代原绘图模式下拉） ----
    % 注：点击后弹出严格模态的绘图设置窗口（openPlotSettingsWindow）
    btnPlotSettings = uibutton(gIO, 'push', ...
        'Text', '绘图设置', ...
        'ButtonPushedFcn', @openPlotSettingsWindow, ...
        'Tooltip','点击设置时域/频谱绘图模式与频谱显示选项');
    btnPlotSettings.Layout.Row = 4;
    btnPlotSettings.Layout.Column = 3;  

    % 录音模式下拉：默认非定时录音
    lblRecMode = uilabel(gIO,'Text','录音模式：','HorizontalAlignment','left');
    lblRecMode.Layout.Row = 2; lblRecMode.Layout.Column = 1;
    ddRecMode = uidropdown(gIO,'Items',{'非定时录音','定时录音'},'Value','非定时录音');
    ddRecMode.Layout.Row = 2; ddRecMode.Layout.Column = 2;
    ddRecMode.ValueChangedFcn = @onRecModeChange;

    % 自定义时长输入（秒）
    lblRecDur = uilabel(gIO,'Text','录音时长 (s):','HorizontalAlignment','left');
    lblRecDur.Layout.Row = 3; lblRecDur.Layout.Column = 1;
    edtRecDuration = uieditfield(gIO,'numeric','Value',10,'Limits',[0.1 3600]);
    edtRecDuration.Layout.Row = 3; edtRecDuration.Layout.Column = 2;

    % 将三个录音按钮合并为一个
    btnRec = uibutton(gIO,'push','Text','开始录音','ButtonPushedFcn',@onRecButton, 'Tooltip','支持定时录音/非定时录音');
    btnRec.Layout.Row = 4; btnRec.Layout.Column = 1;
    btnRec.Tag = 'start'; % 用于标识按钮状态

    % 加载音频按钮
    btnLoadAudio = uibutton(gIO,'push','Text','加载音频','ButtonPushedFcn',@onLoadAudio,'Tooltip','支持wav,mp3,flac,m4a等格式');
    btnLoadAudio.Layout.Row = 4; btnLoadAudio.Layout.Column = 2;

    %  编辑采样率 / 重采样 按钮
    btnEditFs = uibutton(gIO,'push', ...
        'Text','重采样', ...
        'ButtonPushedFcn',@onEditFsButton, ...
        'Enable','on','Tooltip',sprintf('- 无数据时，点击"重采样"按钮可以修改采样率。\n - 有数据时，"重采样"按钮可以对数据重采样，同样会修改采样率。但是除某些场景外，通常不必为"纯粹的数字滤波器设计"对原始信号做重采样。'));
    btnEditFs.Layout.Row = 4;
    btnEditFs.Layout.Column = 4;

    %  导入工作区数据 按钮
    btnImportWS = uibutton(gIO,'push', ...
        'Text','导入工作区数据', ...
        'ButtonPushedFcn',@onImportWorkspace, ...
        'Enable','off', ...
        'Tooltip','从 MATLAB workspace 导入时间 t 和信号 y（点击弹出变量选择窗口）');
    btnImportWS.Layout.Row = 3;
    btnImportWS.Layout.Column = [3 4];


    % =========================== 子面板：滤波器设计 ===========================
    gD_Height = ctlRowHgtBase * 4;  % 滤波器设计 子面板占28行的[5 8]行
    gD_RowSpacing = 6;           % 滤波器设计 子面板4行行间距
    % 滤波器设计 子面板4行每行行高
    gD_RowH = (gD_Height - gD_RowSpacing*3 - ctlTitleH - ctlUdPadding*2) / 4;

    pDesign = uipanel(ctl,'Title','滤波器设计','FontWeight','bold');
    pDesign.Layout.Row = [5 8]; pDesign.Layout.Column = 1; % 行数（从[5 8]）
    gD = uigridlayout(pDesign,[4 4]); % 减少行数（从6行 2列改为4行 4列）
    gD.RowHeight = repmat({gD_RowH}, 1, 4);
    gD.ColumnWidth = {60,'1x','1x','1x'};
    gD.Padding = [6, ctlUdPadding, 6, ctlUdPadding];
    gD.RowSpacing = gD_RowSpacing;

    % 设计方法 下拉框
    lblMethod_GUI = uilabel(gD,'Text','设计方法:');
    lblMethod_GUI.Layout.Row = 1; lblMethod_GUI.Layout.Column = 1;
    ddDesignMethod = uidropdown(gD, ...
        'Items', {'IIR','FIR窗函数法','FIR频率采样法','FIR优化设计法','FIRintfilt插值','FIRgaussdesign脉冲整形','FIRrcosdesign脉冲整形','Savitzky-Golay','陷波','峰值滤波'}, ...
        'Value', 'IIR', ...
        'ValueChangedFcn', @onDesignMethodChange);
    ddDesignMethod.Layout.Row = 1; ddDesignMethod.Layout.Column = 2;

    % 当前选择的设计方法提示
    lblDesignSelected = uilabel(gD,'Text','当前选择：IIR - Butterworth');
    lblDesignSelected.Layout.Row = 4; lblDesignSelected.Layout.Column = [1 4]; 

    % FIR 优化设计法 下拉
    lblFIRMethod = uilabel(gD,'Text','FIR 优化设计法：');
    lblFIRMethod.Layout.Row = 2; lblFIRMethod.Layout.Column = 3;   
    ddFIRMethod = uidropdown(gD, ...
        'Items', {'Parks-McClellan','Cplx-Parks-McClellan','最小二乘(firls)','约束最小二乘(fircls)','约束最小二乘1(fircls1)'}, ...
        'Value', 'Parks-McClellan', ...
        'ValueChangedFcn', @onFIRMethodChange);
    ddFIRMethod.Layout.Row = 2; ddFIRMethod.Layout.Column = 4;
    % 初始状态下仅当选择 FIR 优化设计法 时启用此下拉（默认禁用）
    ddFIRMethod.Enable = 'off';

    % IIR 原型 下拉框
    lblIIRProto = uilabel(gD,'Text','IIR 原型:');
    lblIIRProto.Layout.Row = 2; lblIIRProto.Layout.Column = 1; 
    ddIIRProto = uidropdown(gD,'Items',{'Butterworth','Chebyshev I','Chebyshev II','Elliptic','Yule-Walker','maxflat'},'Value','Butterworth');
    ddIIRProto.Layout.Row = 2; ddIIRProto.Layout.Column = 2; 
    ddIIRProto.ValueChangedFcn = @onIIRProtoChange;

    % IIR 阶数 输入框
    lblIIROrder = uilabel(gD,'Text','IIR 阶数:');
    lblIIROrder.Layout.Row = 3; lblIIROrder.Layout.Column = 1; 
    edtIIROrder = uieditfield(gD,'numeric','Value',4,'Limits',[-Inf 60],'RoundFractionalValues','on', 'ValueChangedFcn', @onOrderChange, 'Tooltip','除 Yule-Walker/maxflat 外，阶数输入 ≤ 0 时将自动估算阶数');
    edtIIROrder.Layout.Row = 3; edtIIROrder.Layout.Column = 2;

    % FIR 窗函数类型 下拉框
    lblWindow = uilabel(gD,'Text','FIR 窗函数类型：');
    lblWindow.Layout.Row = 1; lblWindow.Layout.Column = 3; 
    ddWindow = uidropdown(gD,'Items',{'Rectwin','Triang','Hann','Hamming','Blackman','Kaiser'},'Value','Hamming');
    ddWindow.Layout.Row = 1; ddWindow.Layout.Column = 4; 
    ddWindow.Enable = 'off';
    ddWindow.ValueChangedFcn = @onWindowChange;

    % FIR 阶数 输入框
    lblFIROrder = uilabel(gD,'Text','FIR 阶数:');
    lblFIROrder.Layout.Row = 3; lblFIROrder.Layout.Column = 3; 
    edtFIROrder = uieditfield(gD,'numeric','Value',64,'Limits',[-Inf 2000],'RoundFractionalValues','on', 'ValueChangedFcn', @onOrderChange, 'Tooltip','对于Kaiser和Parks-McClellan，阶数输入 ≤ 0 时将自动估算阶数');
    edtFIROrder.Layout.Row = 3; edtFIROrder.Layout.Column = 4; 
    edtFIROrder.Enable = 'off';


    % ============================== 子面板：滤波器技术指标 ==============================
    gF_Height = ctlRowHgtBase * 3 + ctlRowHgtSld * 4;   % 滤波器技术指标 子面板占28行的[9 15]行。分为“截止频率滑块高度”（4行）和“其他控件高度”（3行）
    gF_RowSpacing = 6;                                 % 滤波器技术指标 子面板7行行间距
    % 滤波器技术指标 子面板7行每行行高
    gF_RowHgtAvg = (gF_Height - gF_RowSpacing*6 - ctlTitleH - ctlUdPadding*2) / 7;
    gF_RowHgtSld =  gF_RowHgtAvg * 1.16;              % "截止频率滑块高度"（4行）可以调节，另一个调节点见 ctlRowHgtSld 赋值处。
    gF_RowHgtBase = (gF_RowHgtAvg * 7 - gF_RowHgtSld * 4) / 3;

    pFreq = uipanel(ctl,'Title','滤波器技术指标','FontWeight','bold');
    pFreq.Layout.Row = [9 15]; pFreq.Layout.Column = 1; % 调整行范围
    % 将原有 2 列改为 4 列布局，每一行放置标签、输入框、滑块在同一行
    gF = uigridlayout(pFreq,[7 4]); % 7行 4列
    gF.RowHeight = [repmat({gF_RowHgtBase}, 1, 3), repmat({gF_RowHgtSld}, 1, 4)];
    gF.ColumnWidth = {'1x',68,'1x',68};
    gF.Padding = [6, ctlUdPadding, 6, ctlUdPadding];
    gF.RowSpacing = gF_RowSpacing;
    gF.ColumnSpacing = 1;

    % --- 陷波/峰值滤波 控件（放在滤波器技术指标面板第一行）
    lblNotchPeak = uilabel(gF, 'Text', '陷波 / 峰值滤波:', 'HorizontalAlignment','left');
    lblNotchPeak.Layout.Row = 1; lblNotchPeak.Layout.Column = 1;
    
    btnNotchPeakParams = uibutton(gF, 'push', ...
        'Text', '陷波 / 峰值滤波参数', ...
        'Enable', 'off', ...   % 默认灰显
        'Tooltip', '点击设置陷波/峰值滤波的具体参数（单频/多频/梳状）', ...
        'ButtonPushedFcn', @onNotchPeakParams);
    btnNotchPeakParams.Layout.Row = 1; btnNotchPeakParams.Layout.Column = [2 4];


    % 滤波类型 下拉框
    lblType_GUI = uilabel(gF,'Text','滤波类型：','HorizontalAlignment','left');
    lblType_GUI.Layout.Row = 2; lblType_GUI.Layout.Column = 1 ;
    ddType = uidropdown(gF,'Items',{'低通','高通','带通','带阻','多带/高级'},'Value','带通');
    ddType.Layout.Row = 2; ddType.Layout.Column = 2 ;
    ddType.ValueChangedFcn = @onTypeChange;

    % 多带/高级按钮（初始禁用）
    btnMultiBand = uibutton(gF,'push', ...
        'Text','多带 / 高级滤波参数', ...
        'Enable','off', ...
        'Tooltip','FIR频率采样法、FIR优化设计法、IIR-YuleWalker、IIR-maxflat、FIR-intfilt、FIRgaussdesign、FIRrcosdesign、Savitzky-Golay (即fir2/cfirpm/firpm/firls/fircls/fircls1/yulewalk/my_maxflat/intfilt/gaussdesign/rcosdesign/sgolay)支持多带/高级滤波，点击设置参数', ...
        'ButtonPushedFcn',@onMultiBandAdvancedParams);
    btnMultiBand.Layout.Row = 2;
    btnMultiBand.Layout.Column = [3 4];

    % Rp/Rs(As)控件
    lblRp = uilabel(gF,'Text','通带最大衰减Rp(dB):' ,'HorizontalAlignment','left');
    lblRp.Layout.Row = 3; lblRp.Layout.Column = 1;
    edtRp = uieditfield(gF,'numeric','Value',1,'Limits',[0.1 10]);
    edtRp.Layout.Row = 3; edtRp.Layout.Column = 2 ;
    edtRp.ValueChangedFcn = @onRpChanged;

    lblRs = uilabel(gF,'Text','阻带最小衰减As(dB):' ,'HorizontalAlignment','left' );
    lblRs.Layout.Row = 3; lblRs.Layout.Column = 3;
    edtRs = uieditfield(gF,'numeric','Value',40,'Limits',[1 200]);
    edtRs.Layout.Row = 3; edtRs.Layout.Column = 4;
    edtRs.ValueChangedFcn = @onRsChanged;

    % 通带截止 - 左侧
    lblPb1 = uilabel(gF,'Text','通带截止fp1 (Hz):','HorizontalAlignment','left');
    lblPb1.Layout.Row = 4; lblPb1.Layout.Column = 1;
    edtPb1 = uieditfield(gF,'numeric','Value',round(S.fs/147),'Limits',[1e-6, S.fs/2], 'Tooltip','对于Butterworth，IIR阶数输入框数值大于0时，此项用于设置-3dB截止频率；对于FIR窗函数法，FIR阶数输入框数值大于0时，此项用于设置-6dB截止频率');
    edtPb1.Layout.Row = 4; edtPb1.Layout.Column = 2;
    edtPb1.ValueChangedFcn = @onPb1Edit;

    sldPb1 = uislider(gF,'Limits',[1e-6, S.fs/2],'Value',edtPb1.Value);
    sldPb1.Layout.Row = 4; sldPb1.Layout.Column = [3 4];
    addlistener(sldPb1,'ValueChanging',@(src,event) onSliderPb1Changing(src,event));
    sldPb1.ValueChangedFcn = @onSliderPb1Changed;

    % 阻带截止 - 左侧
    lblSb1 = uilabel(gF,'Text','阻带截止fst1 (Hz):','HorizontalAlignment','left');
    lblSb1.Layout.Row = 5; lblSb1.Layout.Column = 1;
    edtSb1 = uieditfield(gF,'numeric','Value',round(S.fs/176),'Limits',[1e-6, S.fs/2]);
    edtSb1.Layout.Row = 5; edtSb1.Layout.Column = 2;
    edtSb1.ValueChangedFcn = @onSb1Edit;

    sldSb1 = uislider(gF,'Limits',[1e-6, S.fs/2],'Value',edtSb1.Value);
    sldSb1.Layout.Row = 5; sldSb1.Layout.Column = [3 4];
    addlistener(sldSb1,'ValueChanging',@(src,event) onSliderSb1Changing(src,event));
    sldSb1.ValueChangedFcn = @onSliderSb1Changed;

    % 通带截止 - 右侧
    lblPb2 = uilabel(gF,'Text','通带截止fp2 (Hz):','HorizontalAlignment','left');
    lblPb2.Layout.Row = 6; lblPb2.Layout.Column = 1;
    edtPb2 = uieditfield(gF,'numeric','Value',round(S.fs/13),'Limits',[1e-6, S.fs/2], 'Tooltip','对于Butterworth，IIR阶数输入框数值大于0时，此项用于设置-3dB截止频率；对于FIR窗函数法，FIR阶数输入框数值大于0时，此项用于设置-6dB截止频率');
    edtPb2.Layout.Row = 6; edtPb2.Layout.Column = 2;
    edtPb2.ValueChangedFcn = @onPb2Edit;

    sldPb2 = uislider(gF,'Limits',[1e-6, S.fs/2],'Value',edtPb2.Value);
    sldPb2.Layout.Row = 6; sldPb2.Layout.Column = [3 4];
    addlistener(sldPb2,'ValueChanging',@(src,event) onSliderPb2Changing(src,event));
    sldPb2.ValueChangedFcn = @onSliderPb2Changed;

    % 阻带截止 - 右侧
    lblSb2 = uilabel(gF,'Text','阻带截止fst2 (Hz):','HorizontalAlignment','left');
    lblSb2.Layout.Row = 7; lblSb2.Layout.Column = 1;
    edtSb2 = uieditfield(gF,'numeric','Value',round(S.fs/12),'Limits',[1e-6, S.fs/2]);
    edtSb2.Layout.Row = 7; edtSb2.Layout.Column = 2;
    edtSb2.ValueChangedFcn = @onSb2Edit;

    sldSb2 = uislider(gF,'Limits',[1e-6, S.fs/2],'Value',edtSb2.Value);
    sldSb2.Layout.Row = 7; sldSb2.Layout.Column = [3 4];
    addlistener(sldSb2,'ValueChanging',@(src,event) onSliderSb2Changing(src,event));
    sldSb2.ValueChangedFcn = @onSliderSb2Changed;

    % 初始时根据默认 IIR 原型 Butterworth 禁用 Rp/Rs
    edtRp.Enable = 'off'; edtRs.Enable = 'off';


    % ==================== 子面板：噪声仿真（总开关 + 多种噪声类型） ====================
    gN_Height = ctlRowHgtBase * 7;  % 噪声仿真 子面板占28行的[16 22]行
    gN_RowSpacing = 6;           % 噪声仿真 子面板7行行间距
    % 噪声仿真 子面板7行每行行高
    gN_RowH = (gN_Height - gN_RowSpacing*6 - ctlTitleH - ctlUdPadding*2) / 7;

    pNoise = uipanel(ctl,'Title','噪声仿真','FontWeight','bold');
    pNoise.Layout.Row = [16 22]; pNoise.Layout.Column = 1;
    % 使用 7 行 3 列布局
    gN = uigridlayout(pNoise,[7 3]);   % 7 行 3 列
    gN.RowHeight = repmat({gN_RowH}, 1, 7);
    gN.ColumnWidth = {'1x', '1x' , '1x'};
    gN.Padding = [6, ctlUdPadding, 6, ctlUdPadding];
    gN.RowSpacing = gN_RowSpacing;
    gN.ColumnSpacing = 8;

    % 总开关：启用噪声仿真
    cbAddNoise = uicheckbox(gN,'Text','启用噪声仿真','Value',false,'ValueChangedFcn',@onNoiseToggle);
    cbAddNoise.Layout.Row = 1; cbAddNoise.Layout.Column = 1;

    % 确定按钮放右侧
    btnNoiseConfirm = uibutton(gN,'push','Text','确定','ButtonPushedFcn',@onNoiseConfirm,'Enable','off', 'Tooltip','支持多种噪声类型叠加');
    btnNoiseConfirm.Layout.Row = 1; btnNoiseConfirm.Layout.Column = [2 3];

    % 噪声类型：白噪声（按 SNR）
    cbWhiteNoise = uicheckbox(gN,'Text','白噪声','Value',false,'ValueChangedFcn',@onNoiseTypeToggle , 'Enable', 'off');
    cbWhiteNoise.Layout.Row = 2; cbWhiteNoise.Layout.Column = 1;
    lblNoiseSNR = uilabel(gN,'Text','目标 SNR (dB):','HorizontalAlignment','left');
    lblNoiseSNR.Layout.Row = 2; lblNoiseSNR.Layout.Column = 2;
    edtNoiseSNR = uieditfield(gN,'numeric','Value',20,'Limits',[-60 60],'Enable','off' , 'Tooltip','基于原信号的平均功率，结合目标SNR计算噪声方差');
    edtNoiseSNR.Layout.Row = 2; edtNoiseSNR.Layout.Column = 3;

    % 单频噪声：频率 & 振幅（相对原始信号峰值）
    cbToneNoise = uicheckbox(gN,'Text','单频噪声','Value',false,'ValueChangedFcn',@onNoiseTypeToggle, 'Enable', 'off');
    cbToneNoise.Layout.Row = 3; cbToneNoise.Layout.Column = 1;
    lblToneFreq = uilabel(gN,'Text','频率 (Hz):','HorizontalAlignment','left');
    lblToneFreq.Layout.Row = 3; lblToneFreq.Layout.Column = 2;
    edtToneFreq = uieditfield(gN,'numeric','Value',round(S.fs/10),'Limits',[1e-6 S.fs/2],'Enable','off');
    edtToneFreq.Layout.Row = 3; edtToneFreq.Layout.Column = 3;
    % 振幅输入（0~1，相对原始信号最大值）
    lblToneAmp = uilabel(gN,'Text','幅值比 (0~1):','HorizontalAlignment','left');
    lblToneAmp.Layout.Row = 4; lblToneAmp.Layout.Column = 2;
    edtToneAmp = uieditfield(gN,'numeric','Value',0.1,'Limits',[0 5],'Enable','off', 'Tooltip','噪声的幅值由用户设定的幅值比与原始信号峰值相乘得到');
    edtToneAmp.Layout.Row = 4; edtToneAmp.Layout.Column = 3;

    % 高斯噪声：按标准差比例
    cbGaussNoise = uicheckbox(gN,'Text','高斯噪声','Value',false,'ValueChangedFcn',@onNoiseTypeToggle, 'Enable', 'off');
    cbGaussNoise.Layout.Row = 5; cbGaussNoise.Layout.Column = 1; 
    % 高斯参数
    lblGaussStd = uilabel(gN,'Text','Std 比 (相对 RMS):','HorizontalAlignment','left');
    lblGaussStd.Layout.Row = 5; lblGaussStd.Layout.Column = 2;
    edtGaussStd = uieditfield(gN,'numeric','Value',0.05,'Limits',[0 10],'Enable','off', 'Tooltip','基于原信号的平均功率，乘以用户设定的比例系数得到噪声的标准差');
    edtGaussStd.Layout.Row = 5; edtGaussStd.Layout.Column = 3;

    % 多频噪声：频率列表 & 振幅比列表
    cbMultiTone = uicheckbox(gN,'Text','多频噪声','Value',false,'ValueChangedFcn',@onNoiseTypeToggle, 'Enable', 'off');
    cbMultiTone.Layout.Row = 6; cbMultiTone.Layout.Column = 1;
    lblMultiFreqs = uilabel(gN,'Text','频率列表 (Hz):','HorizontalAlignment','left');
    lblMultiFreqs.Layout.Row = 6; lblMultiFreqs.Layout.Column = 2;
    edtMultiFreqs = uieditfield(gN,'text','Value',sprintf('%d, %d, %d',round(S.fs/147),round(S.fs/74),round(S.fs/44)),'Enable','off','Tooltip','输入请用半角逗号分隔');
    edtMultiFreqs.Layout.Row = 6; edtMultiFreqs.Layout.Column = 3;
    % 修改：将幅值比从单个数值改为列表格式
    lblMultiAmp = uilabel(gN,'Text','幅值比列表 (0~1):','HorizontalAlignment','left');
    lblMultiAmp.Layout.Row = 7; lblMultiAmp.Layout.Column = 2;
    edtMultiAmp = uieditfield(gN,'text','Value','0.08,0.05,0.03','Enable','off','Tooltip','输入请用半角逗号分隔。对每个频率成分，噪声的幅值由用户设定的对应幅值比与原始信号峰值相乘得到'); % 修改为文本输入
    edtMultiAmp.Layout.Row = 7; edtMultiAmp.Layout.Column = 3;

    % 初始禁用：参数输入与确定按钮
    edtNoiseSNR.Enable = 'off';
    edtToneFreq.Enable = 'off'; edtToneAmp.Enable = 'off';
    edtGaussStd.Enable = 'off';
    edtMultiFreqs.Enable = 'off'; edtMultiAmp.Enable = 'off';
    btnNoiseConfirm.Enable = 'off';


    % =========================== 子面板：操作按钮 ===========================
    gA_Height = ctlRowHgtBase * 5;  % 操作按钮 子面板占28行的[23 27]行
    gA_RowSpacing = 6;           % 操作按钮 子面板5行行间距
    % 操作按钮 子面板5行每行行高
    gA_RowH = (gA_Height - gA_RowSpacing*4 - ctlTitleH - ctlUdPadding*2) / 5;

    pActions = uipanel(ctl,'Title','操作','FontWeight','bold');
    pActions.Layout.Row = [23 27]; 
    pActions.Layout.Column = 1;
    gA = uigridlayout(pActions,[5 3]); % 改为5行3列
    gA.RowHeight = repmat({gA_RowH}, 1, 5);
    gA.ColumnWidth = {'1x','1x','1x'};
    gA.Padding = [6, ctlUdPadding, 6, ctlUdPadding];
    gA.RowSpacing = gA_RowSpacing;

    % 播放原始/加噪 按钮
    btnPlayOrig = uibutton(gA,'push','Text','播放原始/加噪','ButtonPushedFcn',@onPlayOriginal);
    btnPlayOrig.Layout.Row = 3; btnPlayOrig.Layout.Column = 1;

    % 保存录制或生成的音频
    btnSaveOrigGen = uibutton(gA,'push', ...
        'Text','保存非加载音频', ...        % 初始显示文本（默认不可用）
        'ButtonPushedFcn',@onSaveOrigGen, ...
        'Enable','off');                     % 初始不可操作（规则将由 updateSaveOrigGenButton(S, handles) 控制）
    btnSaveOrigGen.Layout.Row = 4; 
    btnSaveOrigGen.Layout.Column = 2;

    % 继续滤波 按钮
    btnContinue = uibutton(gA,'push', ...
        'Text','继续滤波', ...
        'ButtonPushedFcn',@onContinueFilter, ...
        'Enable','off', ...
        'Tooltip','将上次滤波后数据继续滤波。最多允许3次滤波。');
    btnContinue.Layout.Row = 2;
    btnContinue.Layout.Column = 1;

    % 设计滤波器 按钮
    btnDesign = uibutton(gA,'push','Text','设计滤波器','ButtonPushedFcn',@onDesignFilter);
    btnDesign.Layout.Row = 1; btnDesign.Layout.Column = 1;
    
    % 将多个滤波器分析选项合并为下拉 + 查看按钮 
    % 合并"滤波器指标 / 单位冲激响应 / 滤波器单位阶跃响应 / 群延迟 / 滤波器相位延迟 / 滤波器零极点图"等
    ddFilterAnalysis = uidropdown(gA, ...
        'Items', {'滤波器指标', '使用滤波器分析器', '滤波器单位冲激响应', '滤波器单位阶跃响应', '滤波器群延迟', '滤波器相位延迟', '滤波器零极点图'}, ...
        'Value', '滤波器指标', ...
        'Enable', 'off', ...
        'Tooltip', '选择要查看的滤波器分析类型');
    ddFilterAnalysis.Layout.Row = 1;
    ddFilterAnalysis.Layout.Column = 2;

    % "查看滤波器分析"按钮（初始灰显）
    btnViewFilterAnalysis = uibutton(gA,'push', ...
        'Text','查看滤波器分析', ...
        'ButtonPushedFcn', @onViewFilterAnalysis, ...
        'Enable','off', ...                      % 初始灰显（不可操作）
        'Tooltip','点击查看滤波器的相关分析');
    btnViewFilterAnalysis.Layout.Row = 1;
    btnViewFilterAnalysis.Layout.Column = 3;

    % 选择前向-后向滤波函数（内置 or 自定义）实现下拉 
    ddFilterFunction = uidropdown(gA, ...
        'Items', {'filter','filtfilt','fftfilt','my_filtfilt'}, ...
        'Value', 'filter', ...
        'Enable', 'off', ...    % 初始灰显，直到用户点击"设计滤波器"
        'Tooltip', '选择内置滤波函数或者自定义滤波函数');
    ddFilterFunction.Layout.Row = 2;
    ddFilterFunction.Layout.Column = 2;

    % 应用滤波器 按钮
    btnApply = uibutton(gA,'push','Text','应用滤波器','ButtonPushedFcn',@onApplyFilter,'Enable','off','Tooltip', '继续滤波满3次后，按钮将被禁用');
    btnApply.Layout.Row = 2; btnApply.Layout.Column = 3;
    
    % 显示比较图（新窗口） 按钮
    btnShowCompare = uibutton(gA,'push','Text','显示比较图（新窗口）','ButtonPushedFcn',@onShowCompare,'Enable','off');
    btnShowCompare.Layout.Row = 3; btnShowCompare.Layout.Column = 2;

    % "播放滤波后音频"按钮
    btnPlayFilt = uibutton(gA,'push','Text','播放滤波后音频','ButtonPushedFcn',@onPlayFiltered,'Enable','off');
    btnPlayFilt.Layout.Row = 4; btnPlayFilt.Layout.Column = 1;
    
    % "保存滤波后音频"按钮
    btnSaveFiltered = uibutton(gA,'push','Text','保存滤波后音频','ButtonPushedFcn',@onSaveFiltered,'Enable','off','Tooltip','支持wav,mp3,flac,m4a等格式');
    btnSaveFiltered.Layout.Row = 4; btnSaveFiltered.Layout.Column = 3;
    
    % 保存图像 按钮，弹出严格模态设置窗口
    btnSaveFigs = uibutton(gA,'push', ...
        'Text', '保存图像', ...
        'ButtonPushedFcn', @onOpenSaveFiguresDialog, ...
        'Enable','off');
    btnSaveFigs.Layout.Row = 3; btnSaveFigs.Layout.Column = 3;

    % 按钮'导出数据到工作区'
    btnExportDataToWS = uibutton(gA,'push','Text','导出数据到工作区','ButtonPushedFcn',@onExportDataToWorkspace,'Enable','off','Tooltip','将 滤波器及滤波后数据 导出到MATLAB的Workspace');
    btnExportDataToWS.Layout.Row = 5; btnExportDataToWS.Layout.Column = 1;


    % =========================== 状态栏 (左侧面板底部) ===========================
    statusBar = uilabel(ctl, 'Text', '状态：准备就绪', ...
        'HorizontalAlignment', 'left', ...
        'FontAngle', 'italic'); 
    statusBar.Layout.Row = 28; % 放在最后一行
    statusBar.Layout.Column = 1;


    %% ================= 右侧绘图区域 =================
    axOrigTime = uiaxes(gl_GUI); 
    axOrigTime.Layout.Row = 1; 
    axOrigTime.Layout.Column = 2;
    title(axOrigTime,'原始/加噪：时域波形');
    
    axOrigSpec = uiaxes(gl_GUI); 
    axOrigSpec.Layout.Row = 1; 
    axOrigSpec.Layout.Column = 3;
    title(axOrigSpec,'原始/加噪：频谱');
    
    axFiltTime = uiaxes(gl_GUI); 
    axFiltTime.Layout.Row = 2; 
    axFiltTime.Layout.Column = 2;
    title(axFiltTime,'滤波后：时域波形');
    
    axFiltSpec = uiaxes(gl_GUI); 
    axFiltSpec.Layout.Row = 2; 
    axFiltSpec.Layout.Column = 3;
    title(axFiltSpec,'滤波后：频谱');
    
    axFilterResp = uiaxes(gl_GUI); 
    axFilterResp.Layout.Row = 3; 
    axFilterResp.Layout.Column = 2;
    title(axFilterResp,'滤波器幅频特性');
    
    axFilterPhase = uiaxes(gl_GUI); 
    axFilterPhase.Layout.Row = 3; 
    axFilterPhase.Layout.Column = 3;
    title(axFilterPhase,'滤波器相频特性');

    %% =========================== 备注信息 + 帮助文档按钮 ===========================
    % "无边框"容器，位置为主网格的第4行、跨列 [2 3]
    bottomPanel = uipanel(gl_GUI, 'BorderType', 'none'); 
    bottomPanel.Layout.Row = 4;
    bottomPanel.Layout.Column = [2 3];
    
    % 在容器内建立一个 1x2 的子网格：左侧自适应（备注），右侧固定像素（帮助按钮）
    bgl = uigridlayout(bottomPanel, [1, 2]);
    bgl.Padding = [6 6 6 6];
    bgl.RowHeight = {noteRowH - 6*2}; % 高度为 noteRowH - 顶/底间距
    % 右侧固定宽度（像素），左侧占剩余空间
    bgl.ColumnWidth = {'1x', 50};   % 这里 50 表示按钮宽度（像素），需要固定时可调整
    bgl.ColumnSpacing = 8;
    
    % 备注（左侧，自适应）
    ta_GUI = uitextarea(bgl, ...
        'Value', {'准备就绪。请录制或加载语音样本（>=10s），或选择 多频正弦 并生成。'}, ...
        'Editable', 'off', ...
        'FontAngle', 'normal', ...
        'HorizontalAlignment','left');
    ta_GUI.Layout.Row = 1;
    ta_GUI.Layout.Column = 1;
    
    % 帮助文档按钮（右侧，固定宽度）
    btnHelp = uibutton(bgl, 'push', ...
        'Text', sprintf('说明\n\n文档'), ...
        'ButtonPushedFcn', @onHelpDoc, ...
        'Tooltip','将打开"README.md"');
    btnHelp.Layout.Row = 1;
    btnHelp.Layout.Column = 2;



    %% ---------------- 保存句柄 ----------------
    handles = GUIHandles(); % handle 对象，接收存放 fig_GUI 句柄/参数设置，


    % ---------------------- 数据 I/O ----------------------
    handles.ddDataSource = ddDataSource;          % 数据来源
    handles.lblFsValue = lblFsValue;              % 采样率
    handles.btnRec = btnRec;                      % 录音按钮
    handles.ddRecMode = ddRecMode;                % 录音模式
    handles.edtRecDuration = edtRecDuration;      % 自定义录音时长输入（秒）
    handles.btnLoadAudio = btnLoadAudio;          % 加载音频按钮
    handles.btnEditFs = btnEditFs;                % "编辑采样率/重采样"按钮
    handles.btnMT_Gen = btnMT_Gen;                % “生成多频正弦”按钮
    handles.btnImportWS = btnImportWS;            % "导入工作区数据" 按钮
    % 绘图设置（由"绘图设置"模态窗口控制）
    handles.btnPlotSettings = btnPlotSettings;   
    % 默认设置
    handles.plotSettings = struct( ...
        'signalPlotMode', 'plot', ...           % 'plot' or 'stem'  （默认 plot）
        'specFreqNormalized', false, ...        % false: 非归一化；true: 归一化 （默认 非归一化）
        'specFreqScale', 'linear', ...          % 'linear' or 'log' （默认 'linear'）
        'specFreqSide', 'single', ...           % 'single' or 'double' （默认 'single'）
        'specMagMode', 'dB', ...                % 'dB' or 'linear' （默认 'dB'）
        'specMagNormalized', false, ...         % 是否归一化幅值（默认 否）
        'filterSpecNFFT', 8192 ...              % 滤波器频谱分析点数（整数，默认 8192）
    );


    % ---------------------- 滤波器设计 ----------------------
    handles.ddDesignMethod = ddDesignMethod;        % 滤波器设计方法
    handles.ddIIRProto = ddIIRProto;                % IIR 原型
    handles.edtIIROrder = edtIIROrder;              % IIR 阶数
    handles.edtFIROrder = edtFIROrder;              % FIR 阶数
    handles.ddFIRMethod = ddFIRMethod;              % FIR 优化设计法方法
    handles.ddWindow = ddWindow;                    % FIR 窗函数法方法
    handles.lblDesignSelected = lblDesignSelected;  % 滤波器设计'当前选择：XXX'文本标签


    % ---------------------- 滤波器技术指标 ----------------------
    handles.ddType = ddType;                      % 滤波类型（低通/高通/带通/带阻/ 多带/高级）
    handles.edtRp = edtRp;                        % 通带最大衰减Rp
    handles.edtRs = edtRs;                        % 阻带最小衰减Rs（As）
    handles.edtPb1 = edtPb1;                      % 通带截止频率fp1 数值输入框
    handles.edtPb2 = edtPb2;                      % 通带截止频率fp2 数值输入框
    handles.sldPb1 = sldPb1;                      % 通带截止频率fp1 滑块
    handles.sldPb2 = sldPb2;                      % 通带截止频率fp2 滑块
    handles.edtSb1 = edtSb1;                      % 阻带截止频率fst1 数值输入框           
    handles.edtSb2 = edtSb2;                      % 阻带截止频率fst2 数值输入框
    handles.sldSb1 = sldSb1;                      % 阻带截止频率fst1 滑块
    handles.sldSb2 = sldSb2;                      % 阻带截止频率fst2 滑块
    %%%%%%%%%%%%%%%%%%% 多带/高级滤波参数 %%%%%%%%%%%%%%%%%%%
    handles.btnMultiBand = btnMultiBand;          % "多带/高级滤波参数"按钮
    handles.multiBandParams = [];                 % 初始化 multiBandParams 存储（空表示尚未设置）
    handles.multiBandParamsHistory = [];          % 初始化 multiBandParamsHistory 存储（空表示尚未设置）
    % 保存 IIR - yulewalk 多带/高级参数占位
    handles.yuleWalkParams = [];
    handles.yuleWalkParamsHistory =  {};
    % 保存 IIR - maxflat 的多带/高级参数占位
    handles.maxflatParams = [];
    handles.maxflatParamsHistory = {}; 
    % 保存 频率采样法(fir2) 多带/高级参数占位
    handles.fir2Params = [];
    handles.fir2ParamsHistory = {};
    % 保存 Parks-McClellan 多带/高级参数占位
    handles.firpmParams = [];
    handles.firpmParamsHistory = {};
    handles.firpmMBPaHistory =  [];
    handles.firpmMBPaCal =  [];
    % 保存 cfirpm 多带/高级参数占位
    handles.cfirpmParams = [];
    handles.cfirpmParamsHistory  = {};
    % 保存 最小二乘(firls) 多带/高级参数占位
    handles.firlsParams = [];
    handles.firlsParamsHistory = {};
    % 保存 约束最小二乘(fircls) 多带/高级参数占位
    handles.firclsParams = [];
    handles.firclsParamsHistory = {};
    % 保存 约束最小二乘1(fircls1) 多带/高级参数占位
    handles.fircls1Params = [];   
    handles.fircls1ParamsHistory = {};
    % 保存 FIRintfilt插值 多带/高级参数占位
    handles.intfiltParams = [];          
    handles.intfiltParamsHistory = {};   
    % 保存 gaussdesign 多带/高级参数占位
