    %% ---- “数据来源”切换回调 ----
    function onDataSourceChange(src,~)
        % 首先停止任何当前播放
        try
            if ~isempty(S.playerOrig) && isplaying(S.playerOrig)
                stop(S.playerOrig);
            end
            if ~isempty(S.playerFilt) && isplaying(S.playerFilt)
                stop(S.playerFilt);
            end
        catch ME
            % 如果停止播放出错，记录错误但不中断流程
            fprintf('停止播放时出错: %s\n', ME.message);
        end
        
        % 重置播放器对象
        S.playerOrig = [];
        S.playerFilt = [];
        
        % 清除滤波后的数据（加噪和滤波）
        S.noisy = [];
        % 清除继续滤波状态的数据
        clearContinueFilterState(S, handles);
        
        % 保存旧的采样率用于比较
        oldFs = S.fs;
        
        val = src.Value;
        switch val
            case '音频信号'
                % 设置当前信号为音频信号
                S.currentSignal = S.audioSignal;
                S.fs = S.audioFs;  % 使用音频信号采样率
                S.timeDim = [];

                % 启用音频相关控件
                handles.btnLoadAudio.Enable = 'on';
                if ~isempty(S.currentSignal)
                    handles.btnPlayOrig.Enable = 'on';
                    % 启动保存图像按钮
                    handles.btnSaveFigs.Enable = 'on';
                else
                    handles.btnPlayOrig.Enable = 'off';
                end
                handles.btnRec.Enable = 'on';
                handles.ddRecMode.Enable = 'on';
                if strcmp(handles.ddRecMode.Value,'定时录音')
                    handles.edtRecDuration.Enable='on'; 
                else
                    handles.edtRecDuration.Enable='off'; 
                end
                % 禁用多频正弦控件
                handles.btnMT_Gen.Enable = 'off';
                % 禁用导入工作区数据相关控件（不可操作）
                handles.btnImportWS.Enable = 'off';

                % 更新播放按钮文本为音频模式
                handles.btnPlayOrig.Text = '播放原始/加噪';
                setStatus(handles,'数据来源：音频信号（可加载/录制）');
                
            case '多频正弦'
                % 设置当前信号为多频正弦信号
                S.currentSignal = S.multiToneSignal;
                S.fs = S.mtFs;  % 使用多频正弦采样率
                S.timeDim = [];

                % 禁用音频相关控件（不可操作）
                handles.btnLoadAudio.Enable = 'off';
                if ~isempty(S.currentSignal)
                    handles.btnPlayOrig.Enable = 'on';
                    handles.btnSaveOrigGen.Enable = 'on';
                    % 启动保存图像按钮
                    handles.btnSaveFigs.Enable = 'on';
                else
                    handles.btnPlayOrig.Enable = 'off';
                    handles.btnSaveOrigGen.Enable = 'off';
                end
                handles.btnRec.Enable = 'off';
                handles.ddRecMode.Enable = 'off';
                handles.edtRecDuration.Enable = 'off';
                % 启用多频正弦控件
                handles.btnMT_Gen.Enable = 'on';
                % 禁用导入工作区数据相关控件（不可操作）
                handles.btnImportWS.Enable = 'off';

                % 更新播放按钮文本为多频正弦模式
                handles.btnPlayOrig.Text = '播放生成/加噪';
                setStatus(handles,'数据来源：多频正弦（请设置参数并点击 生成 多频正弦）');
    
            case '导入工作区数据'
                % 选择导入工作区数据：只启用导入按钮，其余与文件/录音相关控件禁用
                % 注意：不覆盖 S.audioSignal / S.audioFs 等已有来源
                handles.btnImportWS.Enable = 'on';
                
                % 禁用与加载/录音/多频相关的控件
                handles.btnLoadAudio.Enable = 'off';
                handles.btnRec.Enable = 'off';
                handles.ddRecMode.Enable = 'off';
                handles.edtRecDuration.Enable = 'off';
                handles.btnMT_Gen.Enable = 'off';
                
                % 播放/保存按钮：若已有导入数据则允许播放
                if ~isempty(S.wsSignal)
                    handles.btnPlayOrig.Enable = 'on';
                    handles.btnSaveOrigGen.Enable = 'on';
                    % 启动保存图像按钮
                    handles.btnSaveFigs.Enable = 'on';
                else
                    handles.btnPlayOrig.Enable = 'off';
                    handles.btnSaveOrigGen.Enable = 'off';
                end
                % 处理采样率（临时显示）
                if ~isempty(S.wsSignal)
                    S.currentSignal = S.wsSignal;  % 设置当前用于处理的信号（不覆盖其它来源）
                    S.fs = S.wsFs;
                    S.timeDim = S.wsTimeDim;
                else
                    % 还未导入，保持 S.currentSignal 为空
                    S.currentSignal = [];
                    S.timeDim = S.wsTimeDim;
                    % 不改变 S.audioFs 或 S.mtFs，避免干扰其它来源
                end
                
                % 更新播放按钮文本
                handles.btnPlayOrig.Text = '播放导入/加噪';
                setStatus(handles,'数据来源：导入工作区数据（点击 导入工作区数据 按钮进行选择）');


            otherwise
                % 默认恢复音频可操作
                S.currentSignal = S.audioSignal;
                S.fs = S.audioFs;  % 使用音频信号采样率
                S.timeDim = [];

                handles.btnLoadAudio.Enable = 'on'; 
                handles.btnPlayOrig.Enable = 'on';
                handles.btnRec.Enable = 'on'; 
                handles.ddRecMode.Enable = 'on'; 
                handles.edtRecDuration.Enable = 'off';
                handles.btnMT_Gen.Enable = 'off';
                
                % 恢复播放按钮文本为音频模式
                handles.btnPlayOrig.Text = '播放原始/加噪';
                setStatus(handles,'数据来源：未知，已回退为 音频信号');
                fprintf('调试点1：数据来源：未知，已回退为 音频信号\n');
    
        end
        
        % 更新处理采样率显示
        handles.lblFsValue.Text = num2str(S.fs);
        
        % 关键修改：手动调用频率范围更新函数
        updateFrequencyLimits(S.fs, handles);
        
        % 禁用滤波后音频相关按钮（因为切换数据源后需要重新处理）
        handles.btnPlayFilt.Enable = 'off';
        handles.btnSaveFiltered.Enable = 'off';
        handles.btnShowCompare.Enable = 'off';
        % 统一刷新按钮状态
        updateApplyButtonEnable(S.filterIsDesigned, S.allowApplyFilter, handles);
    
        % 更新图形显示
        updatePlotsAndAnalysis(S, handles);
        updateNote(S, handles);
        updateSaveOrigGenButton(S, handles);
        setStatus(handles,sprintf('数据来源切换为：%s',val));
    end

    %% ---- 更新"保存录制或生成的音频或导入的信号"按钮状态与文本 ----
    function updateSaveOrigGenButton(S, handles)
    % 传入的 handle类 S, handles;
    % 对 S 的对象内容有 "读" 操作, 无 "写" 操作
    % 对 handles 的对象内容有 “读/写” 操作
    

        % 优先：噪声被启用并已确认（保存加噪后的音频）
        try
            if handles.cbAddNoise.Value && S.noiseConfirmed && ~isempty(S.noisy)
                handles.btnSaveOrigGen.Enable = 'on';
                handles.btnSaveOrigGen.Text = '保存加噪后的音频';
                return;
            end
        catch
            % 如果 cbAddNoise 尚未建立或访问失败，忽略
        end
    
        % 否则根据数据来源决定（音频信号 / 多频正弦）
        src = handles.ddDataSource.Value;
        switch src
            case '多频正弦'
                if ~isempty(S.multiToneSignal)
                    handles.btnSaveOrigGen.Enable = 'on';
                else
                    handles.btnSaveOrigGen.Enable = 'off';
                end
                handles.btnSaveOrigGen.Text = '保存生成的信号';
    
            case '音频信号'
                % 如果用户是通过"录制"得到（录制完成） -> 可保存录制的音频
                if S.hasRecorded && ~isempty(S.audioSignal)
                    handles.btnSaveOrigGen.Enable = 'on';
                    handles.btnSaveOrigGen.Text = '保存录制的音频';
                else
                    % 如果只是"加载"了文件（未录制），不可操作（灰显）
                    handles.btnSaveOrigGen.Enable = 'off';
                    handles.btnSaveOrigGen.Text = '保存非加载音频';
                end
    
            case '导入工作区数据'
                if ~isempty(S.wsSignal)
                    handles.btnSaveOrigGen.Enable = 'on';
                    handles.btnSaveOrigGen.Text = '保存导入的信号';
                else
                    handles.btnSaveOrigGen.Enable = 'off';
                    handles.btnSaveOrigGen.Text = '保存导入的信号';
                end

            otherwise
                handles.btnSaveOrigGen.Enable = 'off';
                handles.btnSaveOrigGen.Text = '保存非加载音频';
        end
    end

    %% ---- “录音模式”切换回调 ----
    function onRecModeChange(src,~)
        val = src.Value;
        switch val
            case '非定时录音'
                handles.edtRecDuration.Enable = 'off';
                % 修改：设置录音按钮为开始状态
                handles.btnRec.Text = '开始录音';
                handles.btnRec.Tag = 'start';
                handles.btnRec.Enable = 'on';
                setStatus(handles,'已切换到非定时录音模式。点击 "开始录音" 开始。');
            case '定时录音'
                handles.edtRecDuration.Enable = 'on';
                % 修改：设置录音按钮为开始状态
                handles.btnRec.Text = '开始录音';
                handles.btnRec.Tag = 'start';
                handles.btnRec.Enable = 'on';
                setStatus(handles,'已切换到定时录音模式。输入时长并点击 "开始录音"。');
            otherwise
                handles.edtRecDuration.Enable = 'off';
                % 修改：设置录音按钮为开始状态
                handles.btnRec.Text = '开始录音';
                handles.btnRec.Tag = 'start';
                handles.btnRec.Enable = 'on';
                setStatus(handles,'已切换到未知录音模式（回退为非定时）。');
        end
        updateNote(S, handles);
    end

    %% ---- “录音”按钮回调 ----
    function onRecButton(~,~)
        if S.isRecording
            % 如果在录音中，应该是非定时录音模式下的停止操作
            if strcmp(handles.ddRecMode.Value, '非定时录音')
                onRecStop(S, handles, fig_GUI);
            end
            return;
        end
        
        % 根据录音模式执行不同操作
        if strcmp(handles.ddRecMode.Value, '定时录音')
            onRecTimed(S, handles, fig_GUI);
        else
            onRecStart(S, handles, fig_GUI);
        end
    end

    %% ---- 非定时录音：开始 ----
    function onRecStart(S, handles, fig_GUI)
    % 传入的 handle类 S, handles; 主界面 fig_GUI
    % 对 S 的对象内容有 "读/写" 操作
    % 对 handles 的对象内容有 "读/写" 操作
    % fig_GUI 用于uialert_safe()在主界面弹提醒窗口

        if S.isRecording
            setStatus(handles,'已在录音中。');
            return;
        end
        try
            rec = audiorecorder(S.fs,16,1);
            S.recorder = rec;
            record(rec);
            S.isRecording = true;
            % 修改：更新按钮状态
            handles.btnRec.Text = '停止录音';
            handles.btnRec.Tag = 'stop';
            setStatus(handles,sprintf('非定时录音开始（%d Hz）。点击停止以结束录音。',S.fs));
        catch ME
            setStatus(handles,['录音开始失败：',ME.message]);
            fprintf('调试点2：录音开始失败\n');
            uialert_safe(fig_GUI,['无法开始录音：',ME.message],'录音错误');

        end
    end

    %% ---- 非定时录音：停止 ----
    function onRecStop(S, handles, fig_GUI)
    % 传入的 handle类 S, handles; 主界面 fig_GUI
    % 对 S 的对象内容有 "读/写" 操作
    % 对 handles 的对象内容有 "读/写" 操作
    % fig_GUI 用于uialert_safe()在主界面弹提醒窗口

        if ~S.isRecording || isempty(S.recorder)
            setStatus(handles,'当前未在录音。');
            return;
        end
        try
            stop(S.recorder);
            y = getaudiodata(S.recorder,'double');
            if isempty(y) || length(y) < 0.5*S.fs
                setStatus(handles,'警告：录音很短或为空，请重试或加载文件。');
                fprintf('调试点3：警告：录音很短或为空，请重试或加载文件。\n');
            end

            % 确定时间维 tdim（优先使用 S.timeDim，否则回退至第一个非单例维）             
            tdim = [];
            useTimeDim = false;
            if  ~isempty(S.timeDim) && S.timeDim==round(S.timeDim) && S.timeDim>=1
                tdim = S.timeDim;
                useTimeDim = true;
            else
                szx = size(y);
                tdim = find(szx~=1,1,'first');
                if ~isempty(tdim) && tdim>=1
                    useTimeDim = true;
                else
                    tdim = 1; % fallback
                end
            end  
            % 处理数据中Nan/Inf等非有限数值
            y = fillNonfinite(y,tdim);

            S.audioSignal = y(:);  % 保存到音频信号源
            S.audioFs = S.fs;      % 存储录音采样率
            
            % ---------- 新增：保存音频文件元信息（便于导出） ----------
            try
                S.audioOrigFs = S.fs;           % 文件原始采样率（在后续重采样前的记录）
                S.audioOrignalSignal = y(:);
            catch
                % 容错：如果 scope 等问题导致异常，不影响主流程
            end

            if strcmp(handles.ddDataSource.Value, '音频信号')
                S.currentSignal = S.audioSignal;  % 如果当前是音频信号模式，更新当前信号
            end
            
            S.noisy = []; 
            % 清除继续滤波状态的数据
            clearContinueFilterState(S, handles);
            S.isRecording = false; 
            S.recorder = [];
    
            % 标记为录制产生的音频
            S.hasRecorded = true;
            S.loadedFromFile = false;
            S.hasGenerated = false;
            % 录音完成后清除噪声确认（用户可能需要重新确认）
            S.noiseConfirmed = false;
            updateSaveOrigGenButton(S, handles);
            % 启用播放原始/加噪按钮
            handles.btnPlayOrig.Enable = 'on';
            % 启动保存图像按钮
            handles.btnSaveFigs.Enable = 'on';
            
            % 修改：更新按钮状态
            handles.btnRec.Text = '开始录音';
            handles.btnRec.Tag = 'start';
            setStatus(handles,'非定时录音完成。');
            updatePlotsAndAnalysis(S, handles);
            % 启用导出数据到工作区按钮（如果先前被禁用）
            handles.btnExportDataToWS.Enable = 'on';
        catch ME
            setStatus(handles,['停止录音失败：',ME.message]);
            fprintf('调试点4：停止录音失败\n');
            uialert_safe(fig_GUI,['停止录音失败：',ME.message],'录音错误');

        end
    end
    
    %% ---- 定时录音（自定义时长） ----
    function onRecTimed(S, handles, fig_GUI)
    % 传入的 handle类 S, handles; 主界面 fig_GUI
    % 对 S 的对象内容有 "读/写" 操作
    % 对 handles 的对象内容有 "读/写" 操作
    % fig_GUI 用于uialert_safe()在主界面弹提醒窗口

        if S.isRecording
            setStatus(handles,'当前正在录音，无法开始定时录音。');
            return;
        end
        try
            dur = double(handles.edtRecDuration.Value);
            if dur <= 0
                setStatus(handles,'定时录音失败：时长参数错误'); 
                fprintf('调试点5：定时录音失败：时长参数错误\n');
                uialert_safe(fig_GUI,'录音时长必须大于 0。','参数错误'); 
                return;
            end
        catch ME
            setStatus(handles,'定时录音失败：读取参数错误'); 
            fprintf('调试点6：定时录音失败：读取参数错误\n');
            uialert_safe(fig_GUI,['参数读取失败：',ME.message],'参数错误'); 
            return;
        end
        try
            rec = audiorecorder(S.fs,16,1);
            S.recorder = rec;
            S.isRecording = true;
            % 修改：禁用录音按钮
            handles.btnRec.Enable = 'off';
            handles.ddRecMode.Enable = 'off';
            setStatus(handles,sprintf('定时录音开始：%.2f s（%d Hz）。正在录音......',dur,S.fs)); 
            % drawnow;
           
            recordblocking(rec,dur);
            y = getaudiodata(rec,'double');

            % 确定时间维 tdim（优先使用 S.timeDim，否则回退至第一个非单例维）             
            tdim = [];
            useTimeDim = false;
            if  ~isempty(S.timeDim) && S.timeDim==round(S.timeDim) && S.timeDim>=1
                tdim = S.timeDim;
                useTimeDim = true;
            else
                szx = size(y);
                tdim = find(szx~=1,1,'first');
                if ~isempty(tdim) && tdim>=1
                    useTimeDim = true;
                else
                    tdim = 1; % fallback
                end
            end  
            % 处理数据中Nan/Inf等非有限数值
            y = fillNonfinite(y,tdim);

            S.audioSignal = y(:);  % 保存到音频信号源
            S.audioFs = S.fs;      % 存储录音采样率
            
            % ---------- 新增：保存音频文件元信息（便于导出） ----------
            try
                S.audioOrigFs = S.fs;           % 文件原始采样率（在后续重采样前的记录）
                S.audioOrignalSignal = y(:);
            catch
                % 容错：如果 scope 等问题导致异常，不影响主流程
            end

            if strcmp(handles.ddDataSource.Value, '音频信号')
                S.currentSignal = S.audioSignal;  % 如果当前是音频信号模式，更新当前信号
            end
            
            S.noisy = []; 
            % 清除继续滤波状态的数据
            clearContinueFilterState(S, handles);
            S.isRecording = false; 
            S.recorder = [];
    
            S.hasRecorded = true;
            S.loadedFromFile = false;
            S.hasGenerated = false;
            S.noiseConfirmed = false;
            updateSaveOrigGenButton(S, handles);
    
            handles.ddRecMode.Enable = 'on';
            % 修改：恢复录音按钮
            handles.btnRec.Enable = 'on';
            handles.btnRec.Text = '开始录音';
            handles.btnRec.Tag = 'start';
            onRecModeChange(handles.ddRecMode);
            handles.btnPlayFilt.Enable = 'off'; handles.btnSaveFiltered.Enable = 'off'; handles.btnShowCompare.Enable = 'off';
            setStatus(handles,sprintf('定时录音完成，时长 %.2f s。',dur));
            updatePlotsAndAnalysis(S, handles);
            % 启用播放原始/加噪按钮
            handles.btnPlayOrig.Enable = 'on';
            % 启用导出数据到工作区按钮（如果先前被禁用）
            handles.btnExportDataToWS.Enable = 'on';
            % 启动保存图像按钮
            handles.btnSaveFigs.Enable = 'on';

        catch ME
            handles.ddRecMode.Enable = 'on';
            % 修改：恢复录音按钮
            handles.btnRec.Enable = 'on';
            handles.btnRec.Text = '开始录音';
            handles.btnRec.Tag = 'start';
            onRecModeChange(handles.ddRecMode);
            setStatus(handles,['定时录音失败：',ME.message]);
            fprintf('调试点7：定时录音失败\n');
            uialert_safe(fig_GUI,['定时录音失败：',ME.message],'录音错误');

            S.isRecording = false; S.recorder = [];
        end
    end

    %% ---- “加载音频”按钮回调 ----
    function onLoadAudio(~,~)
        [file,path] = uigetfile({'*.wav;*.mp3;*.flac;*.m4a','音频文件';'*.*','所有文件'},'选择音频文件');
        if isequal(file,0), return; end
        filename = fullfile(path,file);
        try [y,fs] = audioread(filename); catch ME; uialert_safe(fig_GUI,['无法读取：',ME.message],'载入错误'); setStatus(handles,'载入失败'); fprintf('调试点8：载入失败\n');return; end
       
        % % 替换原来的简单均值处理
        % if size(y,2) > 1
        %     % 提供多种处理方式，让用户选择或使用更智能的方法
        %     if size(y,2) == 2
        %         % 立体声：可以选择混合策略
        %         y = 0.5 * (y(:,1) + y(:,2));  % 等权重混合
        %         % 或者：y = sqrt(0.5) * (y(:,1) + y(:,2)); % 保持能量
        %     else
        %         % 多声道：使用加权平均或选择主要声道
        %         y = mean(y, 2);  % 保持原来的简单平均作为默认
        %     end
        % end
        
        % 保存旧的采样率用于比较
        oldFs = S.fs;
                
        % 确定时间维 tdim（优先使用 S.timeDim，否则回退至第一个非单例维）             
        tdim = [];
        useTimeDim = false;
        if  ~isempty(S.timeDim) && S.timeDim==round(S.timeDim) && S.timeDim>=1
            tdim = S.timeDim;
            useTimeDim = true;
        else
            szx = size(y);
            tdim = find(szx~=1,1,'first');
            if ~isempty(tdim) && tdim>=1
                useTimeDim = true;
            else
                tdim = 1; % fallback
            end
        end  
        % 处理数据中Nan/Inf等非有限数值
        y = fillNonfinite(y,tdim);

        S.audioSignal = y;  % 保存到音频信号源
        S.audioFs = fs;        % 存储音频信号采样率
        
        % ---------- 新增：保存音频文件元信息（便于导出） ----------
        try
            S.audioFileName = file;      % 例如 'speech.wav'
            S.audioFilePath = path;      % 文件所在路径
            S.audioOrigFs = fs;          % 文件原始采样率（在后续重采样前的记录）
            S.audioOrignalSignal = y;
        catch
            % 容错：如果 scope 等问题导致异常，不影响主流程
        end


        if strcmp(handles.ddDataSource.Value, '音频信号')
            S.currentSignal = S.audioSignal;  % 如果当前是音频信号模式，更新当前信号
            S.fs = S.audioFs;          % 更新当前处理采样率
        end
        
        S.noisy = []; 
        % 清除继续滤波状态的数据
        clearContinueFilterState(S, handles);
    
        % 标记为从文件加载（非录制）
        S.loadedFromFile = true;
        S.hasRecorded = false;
        S.hasGenerated = false;
        % 加载后没有加噪（S.noisy 已被清空），清除噪声确认标志
        S.noiseConfirmed = false;
        % 更新保存按钮状态
        updateSaveOrigGenButton(S, handles);
    
        handles.btnPlayFilt.Enable = 'off'; 
        handles.btnSaveFiltered.Enable = 'off'; 
        handles.btnShowCompare.Enable = 'off';
        
        % 更新处理采样率显示（但不触发onFsChange回调）
        handles.lblFsValue.Text = num2str(S.fs);

        
        % 关键修改：如果采样率发生变化，更新频率限制和图形
        if oldFs ~= S.fs
            % 更新频率限制范围
            updateFrequencyLimits(S.fs, handles);
        end

        % 启用播放原始/加噪按钮
        handles.btnPlayOrig.Enable = 'on';
        % 启用导出数据到工作区按钮（如果先前被禁用）
        handles.btnExportDataToWS.Enable = 'on';
        % 启动保存图像按钮
        handles.btnSaveFigs.Enable = 'on';

        % 更新绘图和分析
        updatePlotsAndAnalysis(S, handles);
        setStatus(handles,sprintf('已加载：%s，时长 %.2f s，采样率 %d Hz', file, length(S.currentSignal)/S.fs, S.fs));

    end

    %% ---- “生成多频正弦”按钮回调：读取参数并生成多频正弦信号（严格模态窗口） ----
    function onMTGenerate(~,~)
        % 停止任何当前播放（复用原有逻辑）
        try
            if ~isempty(S.playerOrig) && isplaying(S.playerOrig); stop(S.playerOrig); end
            if ~isempty(S.playerFilt) && isplaying(S.playerFilt); stop(S.playerFilt); end
        catch ME
            fprintf('停止播放时出错: %s\n', ME.message);
        end
    
        % 弹出模态对话框用于严格参数输入（5 行 × 6 列布局）
        dlg_MT = createCenteredUIFigure('Name','生成多频正弦 - 参数设置','Position',[560,500,620,280],'WindowStyle','modal');
    
        gl_MT = uigridlayout(dlg_MT,[5,6]);
        gl_MT.RowHeight = {'fit','1x','1x','1x','1x'};
        gl_MT.ColumnWidth = repmat({'1x'},1,6);
        gl_MT.Padding = [10 10 10 10];
        gl_MT.RowSpacing = 6;
        gl_MT.ColumnSpacing = 6;
    
        txtIntro = sprintf([ ...
            '1. 频率向量（Hz）：实数向量，例如：300, 600, 1000, 3000。', '\n', ...
            '2. 幅值向量：实数向量，与频率向量一一对应，元素个数须与频率向量相等，示例：1, 0.8, 0.6, 0.4。', '\n', ...
            '3. 采样频率（Hz）：正整数标量，取值范围 [100, 192000]。注意：最大信号频率必须小于采样率的一半（奈奎斯特定理）。', '\n', ...
            '4. 采样点数（N）：正整数标量，取值范围 [100, 10000000]，决定信号时长 T = N / fs。过大 N 会占用更多内存/计算时间。', '\n', ...
            '5. 输入各向量时，使用由空格或半角逗号分隔，请勿包含方括号 \"[ ]\"。' ...
        ]);
        
        lblIntro = uilabel(gl_MT, 'Text', txtIntro, 'WordWrap', 'on', 'HorizontalAlignment', 'left');
        lblIntro.Layout.Row = 1;
        lblIntro.Layout.Column = [1 6];

        % 第二行：频率向量
        lblF = uilabel(gl_MT,'Text','频率向量（Hz）：','HorizontalAlignment','left');
        lblF.Layout.Row = 2; lblF.Layout.Column = 1;
        edtFreq = uieditfield(gl_MT,'text','Value','300, 600, 1000, 3000');
        edtFreq.Layout.Row = 2; edtFreq.Layout.Column = [2 6];
    
        % 第三行：幅值向量
        lblA = uilabel(gl_MT,'Text','幅值向量：','HorizontalAlignment','left');
        lblA.Layout.Row = 3; lblA.Layout.Column = 1;
        edtAmp = uieditfield(gl_MT,'text','Value','1, 0.8, 0.6, 0.4');
        edtAmp.Layout.Row = 3; edtAmp.Layout.Column = [2 6];
    
        % 第四行：采样率与采样点数（分列）
        lblFsDlg = uilabel(gl_MT,'Text','采样频率（Hz）：','HorizontalAlignment','left');
        lblFsDlg.Layout.Row = 4; lblFsDlg.Layout.Column = 1;
        edtFsDlg = uieditfield(gl_MT,'numeric','Value',44100,'Limits',[100 192000]);
        edtFsDlg.RoundFractionalValues = true;
        edtFsDlg.Layout.Row = 4; edtFsDlg.Layout.Column = [2 3];
    
        lblNDlg = uilabel(gl_MT,'Text','采样点数（N）：','HorizontalAlignment','left');
        lblNDlg.Layout.Row = 4; lblNDlg.Layout.Column = 4;
        edtNDlg = uieditfield(gl_MT,'numeric','Value',44100,'Limits',[100 1e7]);
        edtNDlg.RoundFractionalValues = true;
        edtNDlg.Layout.Row = 4; edtNDlg.Layout.Column = [5 6];
    
        % 第五行：确认 / 取消
        btnConfirm = uibutton(gl_MT,'push','Text','确认','ButtonPushedFcn',@(src,event) onConfirm());
        btnConfirm.Layout.Row = 5; btnConfirm.Layout.Column = [1 3];
        btnCancel  = uibutton(gl_MT,'push','Text','取消','ButtonPushedFcn',@(src,event) delete(dlg_MT));
        btnCancel.Layout.Row = 5; btnCancel.Layout.Column = [4 6];
    
        % 等待用户交互（uiwait 不是必须，但使函数行为清晰）
        uiwait(dlg_MT);
    
        % 内部确认回调（局部函数）
        function onConfirm()
            % 读取原始文本
            fStr = strtrim(edtFreq.Value);
            aStr = strtrim(edtAmp.Value);
    
            % 1) 不允许包含方括号
            if contains(fStr,'[') || contains(fStr,']')
                uialert_safe(dlg_MT,'频率向量 f 解析失败：请不要在输入中包含方括号 "[" 或 "]"。仅输入以空格或逗号分隔的 Hz 数值列表。','参数错误');
                return;
            end
            if contains(aStr,'[') || contains(aStr,']')
                uialert_safe(dlg_MT,'幅值向量 a 解析失败：请不要在输入中包含方括号 "[" 或 "]"。仅输入以空格或逗号分隔的数值列表。','参数错误');
                return;
            end
    
            % 2) 解析为数值向量（支持逗号或空格分隔）
            try
                freqs = str2num(['[', strrep(fStr,',',' '), ']']); %#ok<ST2NM>
            catch
                freqs = [];
            end
            try
                amps = str2num(['[', strrep(aStr,',',' '), ']']); %#ok<ST2NM>
            catch
                amps = [];
            end
    
            % 3) 解析并校验采样率与 N（整数）
            fs_mt = round(double(edtFsDlg.Value));
            N = round(double(edtNDlg.Value));
    
            % 校验：非空 / 有效 / 长度匹配 / 有限 / 正值 / max(freq) < fs/2
            if isempty(freqs) || any(~isfinite(freqs))
                uialert_safe(dlg_MT,'频率向量 f 解析失败：请确保输入有效的 Hz 数值列表（非空，数值且有限）。','参数错误');
                return;
            end
            if isempty(amps) || any(~isfinite(amps))
                uialert_safe(dlg_MT,'幅值向量 a 解析失败：请确保输入有效的数值列表（非空，数值且有限）。','参数错误');
                return;
            end
            if any(freqs <= 0) || any(~isfinite(freqs))
                uialert_safe(dlg_MT,'频率向量包含非正或非法值，请检查。','参数错误');
                return;
            end
            if any(amps < 0) || any(~isfinite(amps))
                uialert_safe(dlg_MT,'幅值向量包含负值或非法值，请检查。','参数错误');
                return;
            end
            if length(amps) ~= length(freqs)
                uialert_safe(dlg_MT,'幅值向量长度与频率向量长度不一致：请保证两者元素个数相同。','参数错误');
                return;
            end
            if ~isscalar(fs_mt) || fs_mt < 100 || fs_mt > 192000
                uialert_safe(dlg_MT,'采样率不合法：请输入整数，范围 [100, 192000]。','参数错误');
                return;
            end
            if ~isscalar(N) || N < 100 || N > 1e7
                uialert_safe(dlg_MT,'采样点数 N 不合法：请输入整数，范围 [100, 10000000]。','参数错误');
                return;
            end
 
            % 频率必须为正且小于奈奎斯特
            nyq = fs_mt/2;
            if max(freqs) >= nyq
                uialert_safe(dlg_MT,sprintf('频率超出奈奎斯特限制：最大允许频率 < %d Hz（采样率的一半）。请降低频率或提高采样率。',floor(nyq)),'参数错误');
                return;
            end
    
            % 通过校验 -> 生成多频正弦信号（和原逻辑保持一致）
            t = (0:N-1)'/fs_mt;
            x = zeros(N,1);
            for kk = 1:length(freqs)
                x = x + double(amps(kk)) * sin(2*pi*double(freqs(kk)) * t);
            end
            x = x / (max(abs(x))+eps);  % 归一化到[-1,1]
    
            % 处理非有限（保守，使用已有 fillNonfinite）
            try
                x = fillNonfinite(x,1);
            catch
                % 如果出错，仍继续但告知
                fprintf('fillNonfinite 在生成多频正弦时出错（可忽略）：%s\n',lasterror.message);
            end
    
            % 写回 S（保留原有元信息字段）
            S.multiToneSignal = x;
            S.mtFs = fs_mt;
            S.mtFreqs = double(freqs(:));
            S.mtAmps  = double(amps(:));
            S.mtN     = double(N);
            S.mtOrigFs = fs_mt;
            S.multiToneOrignalSignal = x;
            S.hasGenerated = true;
            S.loadedFromFile = false;
            S.hasRecorded = false;
            S.noiseConfirmed = false;
            S.noisy = [];
            % 启用导出数据到工作区按钮（如果先前被禁用）
            handles.btnExportDataToWS.Enable = 'on';
    
    
            % 保存旧的采样率用于比较
            oldFs = S.fs;
            % 关键修改：如果采样率发生变化，更新频率限制和图形
            if oldFs ~= S.fs
                % 更新频率限制范围
                updateFrequencyLimits(S.fs, handles);
            end
    
            % 更新界面与状态（与原 onMTGenerate 保持一致）
            if strcmp(handles.ddDataSource.Value, '多频正弦')
                S.currentSignal = S.multiToneSignal;
                S.fs = S.mtFs;
                % 更新处理采样率显示（但不触发onFsChange回调）
                handles.lblFsValue.Text = num2str(S.fs);
                handles.btnPlayOrig.Text = '播放生成/加噪';
            end
            
            % 清除继续滤波状态的数据
            clearContinueFilterState(S, handles);
            updateSaveOrigGenButton(S, handles);
            updatePlotsAndAnalysis(S, handles);   
            % 启动保存图像按钮
            handles.btnSaveFigs.Enable = 'on';
            setStatus(handles,sprintf('已生成多频正弦（%d 点, %d Hz）。', N, fs_mt));
    
            % 结束 uiwait 并关闭对话框
            try
                if isvalid(dlg_MT)
                    uiresume(dlg_MT); 
                    delete(dlg_MT); 
                end
            catch
                try delete(dlg_MT); catch; end
            end
        end
    
    end

    %% ---- “导入工作区数据”按钮回调（严格模态窗口） ----
    function onImportWorkspace(~, ~)
    % onImportWorkspace  导入 workspace 数据
    % ========== 变更说明 ==========
    % 1) UI: 将原来的对话框改为 6x6 网格，放置字段与控件（采样率设置、时间向量、采样率输入、
    %    信号选择、维度选择、确认/取消）。使用 uibuttongroup+uiradiobutton 实现互斥单选。
    % 2) 采样率设置: 默认使用 "导入时间向量"，此时时间向量下拉启用，采样率 editfield 禁用；切换到 "设置采样率" 则相反。
    % 3) 维度选择: 提供"不指定/一维/二维/N 维"，当"不指定"时程序会自动选择第一个非单例维度作为时间维。
    % 4) 支持 y 为向量/矩阵/N 维数组：通过 to2DtimeMajor 将 y 重塑为 [N x channels] 以便沿时间维进行 NaN 检测、删除和逐通道插值，
    %    最终用 restoreFn 恢复成与原始形状一致（只是时间维长度可能改变）。
    % 5) 保留并扩展原有逻辑：读取变量、检查长度、一致性校验、uiwait 模式与关闭处理、状态更新等。
    % 6) 该函数假定全局 S, handles 可写；请将原工程中的 setStatus, clearContinueFilterState, updateFrequencyLimits, updatePlotsAndAnalysis
    %    等函数保持可用。
    %
    % 需要的附加：本函数用到 to2DtimeMajor（用户原本提供）且接口保持兼容。
    % 代码中对部分细节做了容错处理（例如工作区中无一维向量时禁止选择 t）。
    % 若需要把导入后的 Y2（[N x channels]）直接用于后续处理（例如画图或播放），可在保存 S 时同时保存 S.wsSignal2D = Y2 并记录 channels 信息。
    
    
        % ---------- 1) 读取 workspace 变量列表 ----------
        try
            ws = evalin('base','whos');
        catch
            errordlg('无法访问 base workspace 变量。','导入错误');
            setStatus(handles,'导入失败：无法访问 workspace');
            fprintf('调试点9：导入失败：无法访问 workspace\n');
            return;
        end
    
        % 筛选时间向量（严格一维向量）和数据候选（向量、矩阵、N 维数组，任何非标量数值类型）
        vecNames = {};          % 一维向量名称（时间向量候选）
        dataNames = {};         % 任意非标量数值变量（信号候选）
        numericClasses = {'double','single','int8','int16','int32','int64',... 
                          'uint8','uint16','uint32','uint64'};
        for k = 1:length(ws)
            cls = ws(k).class;
            if any(strcmp(cls, numericClasses))
                sz = ws(k).size;
                % 一维向量：size 为 [1 n] 或 [n 1]
                if numel(sz)==2 && ((sz(1)==1 && sz(2)>1) || (sz(2)==1 && sz(1)>1))
                    vecNames{end+1} = ws(k).name; %#ok<AGROW>
                end
                % 任意非标量数值变量
                if prod(sz) > 1
                    dataNames{end+1} = ws(k).name; %#ok<AGROW>
                end
            end
        end
    
        if isempty(dataNames)
            errordlg('在 workspace 中未找到可用的数值变量用于导入（非标量）。','导入提示');
            setStatus(handles,'导入失败：workspace 中无可用数据变量');
            fprintf('调试点10：导入失败：workspace 中无可用数据变量\n');
            return;
        end
    
        % ---------- 2) 创建模态对话框（6 行 x 6 列） ----------
        try
            dlg_ImWS = createCenteredUIFigure('Name','导入工作区数据','Position',[520 350 730 500], 'WindowStyle','modal');
        catch ME
            errmsg = ['当前 MATLAB 环境不支持创建模态 uifigure（WindowStyle=''modal''）。', newline, ...
                      '请在支持 uifigure 且支持 WindowStyle=''modal'' 的 MATLAB 版本中运行（或升级 MATLAB）。', newline, ...
                      '详细错误：', ME.message];
            errordlg(errmsg, '不支持模态窗口 - 导入中止');
            setStatus(handles,'导入失败：不支持模态 uifigure（请升级 MATLAB）');
            fprintf('调试点11：导入失败：不支持模态 uifigure（请升级 MATLAB）\n');
            return;
        end
    
        dlg_ImWS.CloseRequestFcn = @(src,evt) dlgCloseAndResume(src);
    
        gl_ImWS = uigridlayout(dlg_ImWS, [6,6]);
        gl_ImWS.RowHeight = {'fit',32,'1x','1x',32,'1x'};
        gl_ImWS.ColumnWidth = {'fit','1x','1x','1x','1x','1x'};
        gl_ImWS.Padding = [10 10 10 10]; 
    
        % 1 行 1 列：文本说明（跨 1:6）
        lblIntro = uilabel(gl_ImWS);
        lblIntro.Text = sprintf([
            '请选择要从 workspace 导入的时间/数据变量：\n', ...
            '1. 支持的数据类型：一维向量（作为时间向量）、向量/矩阵或 N 维数组（作为信号数据）。\n\n', ...
            '2. 采样率设置：选择"导入时间向量"（默认，使用 median(diff(t)) 估算）或"设置采样率"（手动输入，需大于 0）。\n\n', ...
            '3. 沿信号运算的维度 / 时间维（dim）：默认"不指定"。"不指定"时自动选择第一个非单例维；也可手动指定为 1/2/N（若选 N，请在右侧输入具体值）。例如信号为矩阵，指定时间维为 1 表示对信号每列进行操作；指定时间维为 2 表示对信号每行进行操作。\n\n', ...
            '4. NaN/Inf 处理：导入时会提示三种交互式处理方式——删除（同步删除含非有限样本）、插值（仅 y，按通道线性插值且不外推）、取消（请自行预处理）。\n\n', ...
            '5. 一致性检查：若选择"导入时间向量"，t 的长度必须与 y 在所选时间维上的长度一致，且 t 必须严格单调递增。\n\n', ...
            '6. 导入后：数据将保存到 S.wsSignal / S.wsFs / S.wsTime 等字段；若主界面当前数据源是"导入工作区数据"，界面会同时更新信号与采样率显示。\n\n', ...
            '7. 示例：t 为 [1000x1]，y 为 [1000x2] 表示两路通道、每通道 1000 个样本。\n\n']);
        lblIntro.WordWrap = 'on';   % 启用自动换行
        lblIntro.Layout.Row = 1; lblIntro.Layout.Column = [1 6];
    
        % 2 行：采样率设置（2 列单选按钮放在同一按钮组中）
        lblFsSet = uilabel(gl_ImWS);
        lblFsSet.Text = '采样率设置:'; lblFsSet.Layout.Row = 2; lblFsSet.Layout.Column = 1; lblFsSet.FontWeight = 'bold';
    
        bgFs = uibuttongroup(gl_ImWS, 'SelectionChangedFcn', @(src,evt) onFsModeChanged(src,evt));
        bgFs.Layout.Row = 2; bgFs.Layout.Column = [2 3];
        rbUseT = uiradiobutton(bgFs,'Position',[10 6 120 20]); rbUseT.Text = '导入时间向量'; rbUseT.Tag = 'useTime';
        rbSetFs = uiradiobutton(bgFs,'Position',[120 6 120 20]); rbSetFs.Text = '设置采样率'; rbSetFs.Tag = 'setFs';
        % 默认选择导入时间向量
        bgFs.SelectedObject = rbUseT;
    
        % 3 行：时间向量选择 + 采样率数值输入
        lblT = uilabel(gl_ImWS); lblT.Text = '时间向量 t（s）:'; lblT.Layout.Row = 3; lblT.Layout.Column = 1;lblT.FontWeight = 'bold';
        ddT = uidropdown(gl_ImWS);
        ddT.Items = vecNames;
        if ~isempty(vecNames)
            ddT.Value = vecNames{1};
        else
            ddT.Enable = 'off';
        end
        ddT.Layout.Row = 3; ddT.Layout.Column = [2 3];


        lblFs = uilabel(gl_ImWS); lblFs.Text = '采样率（Hz）:'; lblFs.Layout.Row = 3; lblFs.Layout.Column = 4;
        lblFs.FontWeight = 'bold';
        lblFs.Enable = 'off';
        efFs = uieditfield(gl_ImWS,'numeric'); efFs.Limits = [1e-6 Inf]; efFs.RoundFractionalValues = false; efFs.Value = 44100; efFs.Layout.Row = 3; efFs.Layout.Column = [5 6];
        % 初始状态：导入时间向量 => efFs 禁用
        efFs.Enable = 'off';
    
        % 4 行：信号数据 y 选择（允许向量/矩阵/ndarray）
        lblY = uilabel(gl_ImWS); lblY.Text = '信号数据 y:'; lblY.Layout.Row = 4; lblY.Layout.Column = 1;lblY.FontWeight = 'bold';
        ddY = uidropdown(gl_ImWS); ddY.Items = dataNames; ddY.Value = dataNames{1}; ddY.Layout.Row = 4; ddY.Layout.Column = [2 3];
    
        % 5 行：沿信号运算的维度选择
        lblDim = uilabel(gl_ImWS); lblDim.Text = '沿信号运算的维度 dim:'; lblDim.Layout.Row = 5; lblDim.Layout.Column = 1;lblDim.FontWeight = 'bold';
        bgDim = uibuttongroup(gl_ImWS, 'SelectionChangedFcn', @(src,evt) onDimModeChanged(src,evt));
        bgDim.Layout.Row = 5; bgDim.Layout.Column = [2 4];
        rbNotSpec = uiradiobutton(bgDim,'Position',[10 6 120 20]); rbNotSpec.Text = '不指定'; rbNotSpec.Tag = 'notSpecified';
        rbDim1 = uiradiobutton(bgDim,'Position',[92 6 120 20]); rbDim1.Text = '一维'; rbDim1.Tag = 'dim1';
        rbDim2 = uiradiobutton(bgDim,'Position',[174 6 120 20]); rbDim2.Text = '二维'; rbDim2.Tag = 'dim2';
        rbDimN = uiradiobutton(bgDim,'Position',[256 6 120 20]); rbDimN.Text = 'N 维'; rbDimN.Tag = 'dimN';
        % 布局微调：让它们水平排列
        % 默认不指定
        bgDim.SelectedObject = rbNotSpec;
    
        lblDimN = uilabel(gl_ImWS); lblDimN.Text = '请指定 N 维具体值:'; lblDimN.Layout.Row = 5; lblDimN.Layout.Column = 5;
        lblDimN.FontWeight = 'bold';
        lblDimN.Enable = 'off';
        efDimN = uieditfield(gl_ImWS,'numeric'); efDimN.Limits = [1 Inf]; efDimN.RoundFractionalValues = true; efDimN.Value = 3; efDimN.Layout.Row = 5; efDimN.Layout.Column = 6; efDimN.Enable = 'off';
    
        % 6 行：确认 / 取消 按钮
        btnConfirm = uibutton(gl_ImWS, 'push', 'Text', '确认', 'ButtonPushedFcn', @(~,~) onConfirm());
        btnConfirm.Layout.Row = 6; btnConfirm.Layout.Column = [1 3];
        btnCancel = uibutton(gl_ImWS, 'push', 'Text', '取消', 'ButtonPushedFcn', @(~,~) onCancel());
        btnCancel.Layout.Row = 6; btnCancel.Layout.Column = [4 6];
    
        % ---------- 3) 阻塞等待用户操作 ----------
        uiwait(dlg_ImWS);


        % -------- 回调：确认 --------
        function onConfirm()
            % 读取选择的变量
            try
                % 若选择导入时间向量但 workspace 中无 vecNames，则报错
                if bgFs.SelectedObject==rbUseT && isempty(vecNames)
                    uialert(dlg_ImWS,'工作区中不存在一维向量供选择作为时间向量，请选择"设置采样率"。','导入错误');
                    return;
                end
    
                y = evalin('base', ddY.Value);
                if bgFs.SelectedObject==rbUseT
                    t = evalin('base', ddT.Value);
                    t = t(:);
                else
                    t = [];
                end
            catch ME
                uialert(dlg_ImWS, ['读取变量失败：', ME.message], '读取错误');
                fprintf('调试点13：读取变量失败\n');
                return;
            end
    
            % 确定沿信号运算的时间维 tdim
            selDimTag = bgDim.SelectedObject.Tag;
            if strcmp(selDimTag,'notSpecified')
                % 自动选择第一个非单例维度
                szY = size(y);
                tdim = find(szY~=1,1,'first');
                if isempty(tdim) || tdim < 1
                    tdim = 1; 
                end
            elseif strcmp(selDimTag,'dim1')
                tdim = 1;
            elseif strcmp(selDimTag,'dim2')
                tdim = 2;
            else
                tdim = max(1, round(efDimN.Value));
            end

            if tdim > ndims(y)
               uialert(dlg_ImWS,sprintf('指定的沿信号运算的维度（%d）大于信号维度（%d），请重新指定。',tdim,ndims(y)),'维数错误');
               return;   
            end

            % 如果用户选择导入时间向量，则要求 t 与 y 在 tdim 上长度一致
            if bgFs.SelectedObject==rbUseT
                % 用 to2DtimeMajor 将 y 变为 [N x channels] 便于检查长度
                try
                    [Y2, rfn] = to2DtimeMajor(y, tdim);
                catch ME
                    uialert(dlg_ImWS,['处理导入数据时出错：', ME.message],'导入错误');
                    return;
                end
                N = size(Y2,1);
                if length(t) ~= N
                    uialert(dlg_ImWS,'t 与 y 在所选时间维上的长度不一致。请重新选择或调整维度设置。','长度不一致');
                    return;
                end
            end
    
            % 交互式处理 NaN/Inf：使用基于 time-dimension 的处理
            try
                if bgFs.SelectedObject==rbUseT
                    [t_proc, y_proc, cancelled] = handleImportedNaNInf(dlg_ImWS, t, y, tdim);
                else
                    % 没有 t 时，仅对 y 沿 tdim 检查和删除 NaN（或插值）
                    [t_proc, y_proc, cancelled] = handleImportedNaNInf(dlg_ImWS, [], y, tdim);
                end
                if cancelled
                    setStatus(handles,'已取消：用户选择自己预处理 NaN/Inf');
                    return;
                end
            catch ME
                uialert(dlg_ImWS,['处理 NaN/Inf 时出错：', ME.message],'导入错误');
                return;
            end
    
            % 采样率处理
            if bgFs.SelectedObject==rbUseT
                dt = diff(double(t_proc));
                if any(dt<=0)
                    uialert(dlg_ImWS,'t 必须严格单调递增。','时间向量错误');
                    return;
                end
                fs_calc = 1/median(dt);
                fs_use = round(fs_calc);
            else
                fs_use = round(efFs.Value);
                if ~(isfinite(fs_use) && fs_use>0)
                    uialert(dlg_ImWS,'请提供有效的采样率（>0）。','采样率错误');
                    return;
                end
            end
    
            % 保存到全局 S（保留原始形状与转换信息）
            try
                S.wsSignal = y_proc;         % 可能已被删除端点或插值后的数据（形状与原始保持一致 but time dim length may change）
                S.wsFs = fs_use;
                if exist('t_proc','var') && ~isempty(t_proc), S.wsTime = t_proc; S.wsTimeVarName = ddT.Value; end
                S.wsVarName = ddY.Value;
                S.wsOrigFs = S.wsFs;
                S.wsTimeDim = tdim;             % 沿其运算的维度
                S.fromWorkspaceOrignalSignal = y; % 原始从 workspace 读取的未修改数据
            catch
                % 容错
            end
    
            % 如果界面数据源为导入工作区则更新主界面信号
            try
                if isprop(handles,'ddDataSource') && strcmp(handles.ddDataSource.Value, '导入工作区数据')
                    % 将 y 按照默认处理（如需要可将 to2DtimeMajor 的结果作为 S.audio2D）
                    S.currentSignal = S.wsSignal;
                    S.fs = S.wsFs;
                    S.timeDim = S.wsTimeDim;
                    if isprop(handles,'lblFsValue'), handles.lblFsValue.Text = num2str(S.fs); end
                end
            catch
                % 忽略
            end
            
            % 清除继续滤波状态的数据
            clearContinueFilterState(S, handles);
       
            % 重置标志
            if isprop(S,'loadedFromFile'); S.loadedFromFile = false; end
            if isprop(S,'hasRecorded'); S.hasRecorded = false; end
            if isprop(S,'hasGenerated'); S.hasGenerated = false; end
    
            % 启用/禁用相关按钮（与 onDataSourceChange 保持一致）
            if isprop(handles,'btnPlayOrig'); handles.btnPlayOrig.Enable = 'on'; end
            if isprop(handles,'btnSaveOrigGen'); handles.btnSaveOrigGen.Enable = 'on'; end
            if isprop(handles,'btnPlayFilt'); handles.btnPlayFilt.Enable = 'off'; end
            if isprop(handles,'btnSaveFiltered'); handles.btnSaveFiltered.Enable = 'off'; end
    
            % 更新界面与分析
            try updateFrequencyLimits(S.fs, handles); catch; end
            try updatePlotsAndAnalysis(S, handles); catch; end
            % 在 onImportWorkspace -> onConfirm 成功分支中
            handles.btnExportDataToWS.Enable = 'on';
            % 启动保存图像按钮
            handles.btnSaveFigs.Enable = 'on';

            % 标记状态并关闭对话框
            setStatus(handles,sprintf('已从工作区导入：y=%s，采样率 %d Hz，time-dim=%d', ddY.Value, S.wsFs, S.wsTimeDim));
    
            % 结束 uiwait 并关闭对话框
            try
                if isvalid(dlg_ImWS), uiresume(dlg_ImWS); delete(dlg_ImWS); end
            catch
                try delete(dlg_ImWS); catch; end
            end

        end
    
        % -------- 回调：取消 --------
        function onCancel()
            setStatus(handles,'已取消导入工作区数据。');
            try
                if isvalid(dlg_ImWS), uiresume(dlg_ImWS); delete(dlg_ImWS); end
            catch
                try delete(dlg_ImWS); catch; end
            end
        end
    
        % -------- 回调：关闭窗口（X） --------
        function dlgCloseAndResume(src)
            setStatus(handles,'已关闭导入对话框。');
            try
                if isvalid(src), uiresume(src); delete(src); end
            catch
                try delete(src); catch; end
            end
        end
    
        % -------- 回调：采样率模式切换 --------
        function onFsModeChanged(~,evt)
            sel = evt.NewValue.Tag;
            switch sel
                case 'useTime'
                    ddT.Enable = 'on';
                    lblT.Enable = 'on';
                    efFs.Enable = 'off';
                    lblFs.Enable = 'off';
                case 'setFs'
                    ddT.Enable = 'off';
                    lblT.Enable = 'off';
                    efFs.Enable = 'on';
                    lblFs.Enable = 'on';
            end
        end
    
        % -------- 回调：维度模式切换 --------
        function onDimModeChanged(~,evt)
            sel = evt.NewValue.Tag;
            switch sel
                case 'notSpecified'
                    efDimN.Enable = 'off';
                    lblDimN.Enable = 'off';
                case 'dim1'
                    efDimN.Enable = 'off'; 
                    lblDimN.Enable = 'off';
                case 'dim2'
                    efDimN.Enable = 'off'; 
                    lblDimN.Enable = 'off';
                case 'dimN'
                    efDimN.Enable = 'on';
                    lblDimN.Enable = 'on';
            end
        end
    
        % -------- 交互式处理导入 t,y 中的 NaN/Inf（改写，支持多维 y） --------
        function [t_out, y_out, cancelled] = handleImportedNaNInf(dlgParent, t_in, y_in, tdim)
            cancelled = false;
            % 保持 original types until restoration
            y_orig = y_in;
            if isempty(y_in)
                y_out = y_in; t_out = t_in; return;
            end
    
            % 将 y 转换到 [N x channels] 以便对每个通道独立处理
            [Y2, rfn] = to2DtimeMajor(y_in, tdim);
            N = size(Y2,1);
    
            % t 处理：当提供 t 时，按 t 的非有限处理
            t_out = t_in;
            y_out = y_in;
            needT = ~isempty(t_in) && ~all(isfinite(t_in));
            needY = ~all(isfinite(Y2(:)));
            if ~(needT || needY)
                return;
            end
    
            if needT && needY
                targetStr = '检测到 t 和 y 中含有 NaN / Inf。';
            elseif needT
                targetStr = '检测到 t 中含有 NaN / Inf。';
            else
                targetStr = '检测到 y 中含有 NaN / Inf。';
            end
    
            msg = sprintf([targetStr, '\n\n请选择处理方式：\n', ...
                           '  • 删除：删除任何含 NaN/Inf 的样本（按时间维同步删除）。\n', ...
                           '  • 插值（仅 y）：对每个通道沿时间维对 y 做线性插值（不外推）；若 t 非有限样本存在，则先删除这些样本。\n', ...
                           '  • 取消：用户手工预处理后重试。']);
    
            try
                choice = uiconfirm(dlgParent, msg, '检测到 NaN/Inf', 'Options', {'删除','插值（仅 y）','取消'}, 'DefaultOption',1,'CancelOption',3);
            catch
                choice = questdlg(msg, '检测到 NaN/Inf', '删除','插值（仅 y）','取消','删除');
            end
    
            if isempty(choice) || strcmp(choice,'取消')
                cancelled = true; return;
            end
    
            if strcmp(choice,'删除')
                % 找到在时间维任一通道为非有限的样点并删除（按行删除）
                bad = any(~isfinite(Y2),2);
                nRemoved = sum(bad);
                if nRemoved>0
                    Y2(bad,:) = [];
                    if ~isempty(t_in), t_out(bad) = []; end
                    try setStatus(handles,sprintf('已删除 %d 个包含 NaN/Inf 的时间样本（同步删除）。', nRemoved)); catch; end
                else
                    try setStatus(handles,'删除操作：未发现需删除的样本（可能已处理）'); catch; end
                end
                % 恢复原始形状
                y_out = rfn(Y2);
                return;
            end
    
            if strcmp(choice,'插值（仅 y）')
                % 若 t 存在且含非有限，先删除这些 t（及对应 y 行）
                if ~isempty(t_in)
                    idx_t_finite = isfinite(t_in);
                    if ~all(idx_t_finite)
                        t_temp = t_in(idx_t_finite);
                        Y2 = Y2(idx_t_finite,:);
                        try setStatus(handles,sprintf('已删除 %d 个 t 非有限样本（同步从 y 中删除）', sum(~idx_t_finite))); catch; end
                    else
                        t_temp = t_in;
                    end
                else
                    t_temp = (1:size(Y2,1))'; % synthetic x for interpolation if no t provided
                end
    
                % 对每列（每个通道）分别插值
                % 若某列有效点 < 2，则把该列的非有限样点删除（退回删除策略）
                Y2_interp = Y2; % will be modified
                nanMask = ~isfinite(Y2);
                for c = 1:size(Y2,2)
                    ycol = Y2(:,c);
                    known = isfinite(ycol);
                    if sum(known) < 2
                        % 不可插值—删除这些行（在所有列中同步删除）
                        keep = all(isfinite(Y2),2);
                        nRemoved2 = sum(~keep);
                        Y2 = Y2(keep,:);
                        if ~isempty(t_in), t_temp( ~keep ) = []; end
                        try setStatus(handles,'插值不可行（某通道有效点 < 2），已退回并删除所有包含 NaN/Inf 的样本。'); catch; end
                        Y2_interp = Y2; break;
                    else
                        % 在已知点上合并重复 t
                        [t_sorted, sIdx] = sort(t_temp);
                        y_sorted = ycol(sIdx);
                        knownMask = isfinite(y_sorted);
                        xk = t_sorted(knownMask);
                        yk = y_sorted(knownMask);
                        [xu, ~, ic] = unique(xk, 'stable');
                        if numel(xu) < numel(xk)
                            yk = accumarray(ic, yk, [], @mean);
                            xk = xu;
                        end
                        if numel(xk) < 2
                            % 退回删除策略
                            keep = all(isfinite(Y2),2);
                            Y2 = Y2(keep,:);
                            if ~isempty(t_in), t_temp( ~keep ) = []; end
                            try setStatus(handles,'插值失败（合并重复后有效点 < 2），已删除所有包含 NaN/Inf 的样本。'); catch; end
                            Y2_interp = Y2; break;
                        end
                        % 线性插值（不外推）：
                        y_interp_sorted = interp1(xk, yk, t_sorted, 'linear');
                        % 处理端点无法插值的情况：删除这些端点（同步）
                        nanAfter = ~isfinite(y_interp_sorted);
                        if any(nanAfter)
                            keepSorted = ~nanAfter;
                            t_sorted = t_sorted(keepSorted);
                            y_interp_sorted = y_interp_sorted(keepSorted);
                            % 重新构建 Y2 的行（更复杂的同步删除实现简化为：
                            % 使用通用 keep: 只保留所有通道在排序后均能插值的行）
                            % 在此实现中，后续循环将感知 Y2 的改变。
                        end
                        % 将插值结果写回对应列（先重建回原顺序）
                        y_interp = nan(size(ycol));
                        y_interp(sIdx) = y_interp_sorted;
                        % 若仍有 NaN（端点），在循环结束后再统一删除这些行
                        Y2_interp(:,c) = y_interp;
                    end
                end
    
                % 如果插值后仍有 NaN（可能出现在端点），则删除对应行（同步删除）
                if any(~isfinite(Y2_interp(:)))
                    keepAll = all(isfinite(Y2_interp),2);
                    nRemoved3 = sum(~keepAll);
                    Y2_interp = Y2_interp(keepAll,:);
                    if ~isempty(t_in), t_temp(~keepAll) = []; end
                    try setStatus(handles,sprintf('插值后端点无法填充，已删除 %d 个端点样本，其他用线性插值填充。', nRemoved3)); catch; end
                else
                    try setStatus(handles,'已用线性插值填充 y 中的 NaN/Inf（t 中非有限样本已删除）。'); catch; end
                end
    
                % 恢复回原始形状
                y_out = rfn(Y2_interp);
                if ~isempty(t_in), t_out = t_temp; end
                return;
            end
    
            % 兜底
            cancelled = true;
        end
    
    end

    %% ---- 噪声控制回调 ----
    % 噪声总开关回调 
    function onNoiseToggle(src,~)
        S.addNoise = src.Value;
        if S.addNoise
            % 启用各噪声类型选择（用户可多选）
            handles.cbWhiteNoise.Enable = 'on';
            handles.cbToneNoise.Enable = 'on';
            handles.cbGaussNoise.Enable = 'on';
            handles.cbMultiTone.Enable = 'on';
            % 保持参数域在各自 check 打开时启用（由 onNoiseTypeToggle 处理）
            % 清除继续滤波状态的数据
            clearContinueFilterState(S, handles);
            setStatus(handles,'噪声仿真已启用。请选择噪声类型并设置参数，点击 确定 叠加。');
        else
            % 关闭所有噪声选择与参数输入
            handles.cbWhiteNoise.Value = false; handles.cbWhiteNoise.Enable = 'off';
            handles.cbToneNoise.Value = false; handles.cbToneNoise.Enable = 'off';
            handles.cbGaussNoise.Value = false; handles.cbGaussNoise.Enable = 'off';
            handles.cbMultiTone.Value = false; handles.cbMultiTone.Enable = 'off';
            handles.edtNoiseSNR.Enable = 'off';
            handles.edtToneFreq.Enable = 'off'; handles.edtToneAmp.Enable = 'off';
            handles.edtGaussStd.Enable = 'off';
            handles.edtMultiFreqs.Enable = 'off'; handles.edtMultiAmp.Enable = 'off';
            handles.btnNoiseConfirm.Enable = 'off';
            S.noisy = [];
            updatePlotsAndAnalysis(S, handles);
            S.noiseConfirmed = false;
            updateSaveOrigGenButton(S, handles);
            % 清除继续滤波状态的数据
            clearContinueFilterState(S, handles);
            setStatus(handles,'仿真噪声已禁用');
        end
        updateNote(S, handles);
    end

    % 噪声类型 checkbox 状态变化（联调参数输入使能 + 确认按钮可用性） 
    function onNoiseTypeToggle(~,~)
        % 白噪声参数
        if handles.cbWhiteNoise.Value
            handles.edtNoiseSNR.Enable = 'on';
        else
            handles.edtNoiseSNR.Enable = 'off';
        end
        % 单频
        if handles.cbToneNoise.Value
            handles.edtToneFreq.Enable = 'on';
            handles.edtToneAmp.Enable = 'on';
        else
            handles.edtToneFreq.Enable = 'off';
            handles.edtToneAmp.Enable = 'off';
        end
        % 高斯
        if handles.cbGaussNoise.Value
            handles.edtGaussStd.Enable = 'on';
        else
            handles.edtGaussStd.Enable = 'off';
        end
        % 多频
        if handles.cbMultiTone.Value
            handles.edtMultiFreqs.Enable = 'on';
            handles.edtMultiAmp.Enable = 'on';
        else
            handles.edtMultiFreqs.Enable = 'off';
            handles.edtMultiAmp.Enable = 'off';
        end
        % 确认按钮：仅在总开关打开且至少选择一种类型时可用
        if handles.cbAddNoise.Value && (handles.cbWhiteNoise.Value || handles.cbToneNoise.Value || handles.cbGaussNoise.Value || handles.cbMultiTone.Value)
            handles.btnNoiseConfirm.Enable = 'on';
        else
            handles.btnNoiseConfirm.Enable = 'off';
        end
        updateNote(S, handles);
    end

    % 点击"确定"生成并叠加所选噪声
    function onNoiseConfirm(~,~)
        if isempty(S.currentSignal)
            uialert_safe(fig_GUI,'请先录制/加载音频或生成信号或导入信号数据，然后再生成噪声。','无信号数据');
            setStatus(handles,'生成噪声失败：无信号数据');
            return;
        end
        x_use = S.currentSignal;
        fs_local = S.fs;
         
        % --- 找到时间维（优先使用用户在 GUI 中指定的 dim） ---
        sz = size(x_use);
        nd = ndims(x_use);
        
        % 1) 先尝试从状态或控件读取用户指定的 dim（示例：S.timeDim ）
        userDim = [];
        if  ~isempty(S.timeDim)
            userDim = double(S.timeDim); 
        end
        
        % 2) 验证 userDim 是否有效：标量、整数
        validUserDim = false;
        if ~isempty(userDim) && isscalar(userDim) && userDim==round(userDim) && userDim>=1 
            validUserDim = true;
        end
        
        if validUserDim
            tdim = userDim;
        else
            % 回退：自动检测第一个非单例维度（原有行为）
            tdim = find(sz~=1,1,'first');
            if isempty(tdim)
                tdim = 1;
            end
            if ~isempty(userDim) && ~validUserDim
                setStatus(handles,sprintf('警告：指定的时间维 dim=%d 无效，已使用自动检测 dim=%d。', userDim, tdim));
            end
        end
        
    
        if isempty(tdim)
            % 全是 singleton，视为向量长度为1的时间轴
            tdim = 1;
        end
    
        % ----------------------------
        % 使用 to2DtimeMajor 将数据转换为 [N x channels] 形式，便于统一处理
        % 注意：to2DtimeMajor 必须在路径上
        [X2, restoreFn] = to2DtimeMajor(x_use, tdim);   % X2: [N x C]
        [N, C] = size(X2);
        
        % 构造时间向量（列向量 Nx1）
        tvec = (0:N-1)'/fs_local; 
    
        % 计算每个通道的信号功率（沿时间维求均方），忽略 NaN
        % X2.^2 是 [N x C]，mean(...,1) -> [1 x C]
        psig_ch = mean(X2.^2, 1, 'omitnan');   % 1 x C
    
        % 预分配噪声（2D 形式，与 X2 同尺寸，保持类型）
        noise_total2 = zeros(N, C, 'like', X2);
    
        % ----------------------------
        % 1) 白噪声（按目标 SNR）
        if handles.cbWhiteNoise.Value
            try
                snr_dB = double(handles.edtNoiseSNR.Value);
            catch
                snr_dB = 20;
            end
            % 支持 snr_dB 为标量或按通道向量（长度 C）
            if isscalar(snr_dB)
                noiseVar_ch = psig_ch ./ (10.^(snr_dB/10));   % 1 x C
            else
                snr_dB = double(snr_dB(:)'); % make row
                if numel(snr_dB) ~= C
                    % 尝试广播或截断
                    if isscalar(snr_dB)
                        noiseVar_ch = psig_ch ./ (10.^(snr_dB/10));
                    else
                        % 截断或填充
                        nrep = ceil(C/numel(snr_dB));
                        snr_vec = repmat(snr_dB,1,nrep);
                        snr_vec = snr_vec(1:C);
                        noiseVar_ch = psig_ch ./ (10.^(snr_vec/10));
                    end
                else
                    noiseVar_ch = psig_ch ./ (10.^(snr_dB/10));
                end
            end
            noiseStd_ch = sqrt(noiseVar_ch);   % 1 x C
            % expand to N x C
            noiseStd2 = repmat(noiseStd_ch, N, 1);
            noise_total2 = noise_total2 + noiseStd2 .* randn(N, C, 'like', X2);
        end
    
        % ----------------------------
        % 2) 高斯噪声（按 RMS 比例）
        if handles.cbGaussNoise.Value
            try
                gstd_ratio = double(handles.edtGaussStd.Value); % 比例 * RMS
            catch
                gstd_ratio = 0.05;
            end
            % gstd_ratio 可以是标量或通道向量
            if isscalar(gstd_ratio)
                gauss_std_ch = gstd_ratio .* sqrt(psig_ch);  % 1 x C
            else
                gr = double(gstd_ratio(:)');
                if numel(gr) ~= C
                    gr = repmat(gr(1), 1, C); % fallback：用第一个值扩展
                end
                gauss_std_ch = gr .* sqrt(psig_ch);
            end
            gauss_std2 = repmat(gauss_std_ch, N, 1);
            noise_total2 = noise_total2 + gauss_std2 .* randn(N, C, 'like', X2);
        end
    
        % ----------------------------
        % 3) 单频噪声（正弦）
        if handles.cbToneNoise.Value
            try
                f0 = double(handles.edtToneFreq.Value);
            catch
                f0 = round(S.fs/110);
            end
            try
                amp_ratio = double(handles.edtToneAmp.Value);
            catch
                amp_ratio = 0.1;
            end
        
            % 限制频率在奈奎斯特以下
            f0 = min(f0, max(1e-6, fs_local/2 * 0.999999));
        
            % 每个通道的峰值（沿时间维）
            peak_ch = max(abs(X2) + eps, [], 1, 'omitnan');   % 1 x C
            amp_scale_ch = amp_ratio .* peak_ch;   % 1 x C
            % tone: outer product of sin(t) and amp_scale_ch
            s = sin(2*pi*f0 .* tvec);    % N x 1
            tone2 = s * amp_scale_ch;    % N x C  (broadcast)
            noise_total2 = noise_total2 + tone2;
        end
    
        % ----------------------------
        % 4) 多频噪声（逗号分隔的频率列表和幅值比列表）
        if handles.cbMultiTone.Value
            try
                freqStr = handles.edtMultiFreqs.Value;
                freqs = sscanf(freqStr,'%f',inf);
                if isempty(freqs); freqs = [300,600,1000]; end
            catch
                freqs = [round(S.fs/147),round(S.fs/74),round(S.fs/44)];
            end
        
            try
                ampStr = handles.edtMultiAmp.Value;
                amps = sscanf(ampStr,'%f',inf);
                if isempty(amps); amps = [0.08,0.05,0.03]; end
            catch
                amps = [0.08,0.05,0.03];
            end
        
            % 补齐或截断 amps
            if length(amps) < length(freqs)
                amps = [amps; repmat(amps(end),length(freqs)-length(amps),1)];
            elseif length(amps) > length(freqs)
                amps = amps(1:length(freqs));
            end
            amps = double(amps(:)');
    
            % 每通道峰值
            peak_ch = max(abs(X2) + eps, [], 1, 'omitnan');   % 1 x C
    
            for k = 1:length(freqs)
                fk = min(freqs(k), max(1e-6, fs_local/2 * 0.999999));
                amp_scale_ch = amps(k) .* peak_ch;               % 1 x C
                s_k = sin(2*pi*fk .* tvec);                      % N x 1
                tone_k = s_k * amp_scale_ch;                     % N x C
                noise_total2 = noise_total2 + tone_k;
            end
        end
    
        % 合成：原始信号 + 噪声总和（使用 restoreFn 恢复原始形状）
        noisy2 = X2 + noise_total2;   % N x C

        % 处理数据中Nan/Inf等非有限数值
        noisy2 = fillNonfinite(noisy2,1);

        S.noisy = restoreFn(noisy2);  % restoreFn 会返回与 x_use 同样形状（时间维变为 N）
        S.addNoise = true;
        % 保持原 SNR 值（如果 edtNoiseSNR 存在）
        try
            S.noiseTargetSNR = handles.edtNoiseSNR.Value;
        catch
            % ignore
        end
        
        % 启用播放带噪音按钮（如果先前被禁用）
        handles.btnPlayOrig.Enable = 'on';
        % 启用导出数据到工作区按钮（如果先前被禁用）
        handles.btnExportDataToWS.Enable = 'on';
    
        % 记录噪声已确认（用于保存按钮使能）
        S.noiseConfirmed = true;
        updateSaveOrigGenButton(S, handles);
        % 清除继续滤波状态的数据
        clearContinueFilterState(S, handles);
    
        % 根据数据源更新按钮文本
        if strcmp(handles.ddDataSource.Value, '多频正弦')
            handles.btnPlayOrig.Text = '播放生成/加噪';
        elseif strcmp(handles.ddDataSource.Value, '导入工作区数据')
            handles.btnPlayOrig.Text = '播放导入/加噪';
        else
            handles.btnPlayOrig.Text = '播放原始/加噪';
        end
    
        % 更新图形（原有 updatePlotsAndAnalysis 会在 ax 上叠加带噪曲线）
        updatePlotsAndAnalysis(S, handles);
        % 启动保存图像按钮
        handles.btnSaveFigs.Enable = 'on';
        setStatus(handles,'已生成并叠加所选噪声。绘图与分析已更新');
    end

    %% ---- “播放音频”按钮回调 ----
    function onPlayOriginal(~,~)
        if ~isempty(S.playerOrig) && isplaying(S.playerOrig)
            stop(S.playerOrig);
            % 根据数据源更新按钮文本
            if strcmp(handles.ddDataSource.Value, '多频正弦')
                handles.btnPlayOrig.Text = '播放生成/加噪';
            elseif strcmp(handles.ddDataSource.Value, '导入工作区数据')
                handles.btnPlayOrig.Text = '播放导入/加噪';
            else
                handles.btnPlayOrig.Text = '播放原始/加噪';
            end
            setStatus(handles,'已停止播放');
            return;
        end
        
        if isempty(S.currentSignal)
            uialert_safe(fig_GUI,'没有原始/生成音频/导入信号。','播放错误'); 
            setStatus(handles,'播放失败：无原始/生成音频/导入信号'); 
            fprintf('调试点14：播放失败：无原始/生成音频/导入信号\n');
            return; 
        end
        
        try
            if S.addNoise && ~isempty(S.noisy)
                audioToPlay = S.noisy;
                % 根据数据源更新状态消息
                if strcmp(handles.ddDataSource.Value, '多频正弦')
                    statusMsg = '正在播放：已加噪多频正弦';
                elseif strcmp(handles.ddDataSource.Value, '导入工作区数据')
                    statusMsg = '正在播放：已加噪导入信号';                
                else
                    statusMsg = '正在播放：已加噪音频';
                end
            else
                audioToPlay = S.currentSignal;
                if strcmp(handles.ddDataSource.Value, '多频正弦')
                    statusMsg = '正在播放：生成的多频正弦';
                elseif strcmp(handles.ddDataSource.Value, '导入工作区数据')
                    statusMsg = '正在播放：导入的信号';
                else
                    statusMsg = '正在播放：原始音频';
                end
            end

            % ===  播放前范围检查（兼容向量/矩阵/多声道） ===
            audioToPlay = double(audioToPlay);
                 
            % 确定时间维 tdim（优先使用 S.timeDim，否则回退至第一个非单例维）             
            tdim = [];
            useTimeDim = false;
            if  ~isempty(S.timeDim) && S.timeDim==round(S.timeDim) && S.timeDim>=1
                tdim = S.timeDim;
                useTimeDim = true;
            else
                szx = size(audioToPlay);
                tdim = find(szx~=1,1,'first');
                if ~isempty(tdim) && tdim>=1
                    useTimeDim = true;
                else
                    tdim = 1; % fallback
                end
            end  
            % 处理数据中Nan/Inf等非有限数值
            audioToPlay = fillNonfinite(audioToPlay,tdim);

            % 把行向量转换为列向量，保证 samples x channels
            if isvector(audioToPlay)
                audioToPlay = audioToPlay(:);  % 变为 N x 1
            end
            
            % 如果是高维（>2）尝试 squeeze 成 2D，否则报错返回
            if ndims(audioToPlay) > 2
                tmp = squeeze(audioToPlay);
                if ismatrix(tmp)
                    audioToPlay = tmp;
                else
                    uialert_safe(fig_GUI, '音频数据维度超过2维，无法播放。请转换为 samples x channels 的二维矩阵。', '播放错误');
                    setStatus(handles,'播放失败：音频维度不支持');
                    fprintf('调试点15：播放失败：音频维度不支持\n');
                    return;
                end
            end
            
            % 检查包含 NaN / Inf
            if ~all(isfinite(audioToPlay), 'all')
                uialert_safe(fig_GUI, '音频包含 NaN 或 Inf，无法播放。', '播放错误');
                setStatus(handles,'播放失败：音频包含 NaN/Inf');
                fprintf('调试点15：播放失败：音频包含 NaN/Inf\n');
                return;
            end
            
            % 按通道查找是否有超过 1 的通道（samples x channels -> max over rows）
            channel_max = max(abs(audioToPlay), [], 1);   % 1 x C 向量
            
            % 仅对超过 1 的通道做缩放（保留 0.99 余量）
            over = channel_max > 1;
            if any(over)
                scale = ones(1, size(channel_max, 2));        % 默认不缩放
                scale(over) = 1 ./ channel_max(over);      % 仅对超限通道设缩放因子
                audioToPlay = audioToPlay .* scale;           % 隐式扩展：samples x channels .* 1 x channels
                setStatus(handles,'警告：部分声道幅度超过范围，已按通道调整');
                fprintf('调试点15：警告：部分声道幅度超过范围，已按通道调整\n');
            end
            % === 结束播放前检查 ===

            S.playerOrig = audioplayer(audioToPlay, S.fs);
            S.playerOrig.StopFcn = @(src,~) onOrigPlaybackComplete(src);
            play(S.playerOrig);
            % 根据数据源更新按钮文本
            if strcmp(handles.ddDataSource.Value, '多频正弦')
                handles.btnPlayOrig.Text = '停止播放生成信号';
            elseif strcmp(handles.ddDataSource.Value, '导入工作区数据')
                handles.btnPlayOrig.Text = '停止播放导入信号';
            else
                handles.btnPlayOrig.Text = '停止播放原始音频';
            end
            setStatus(handles,statusMsg);
        catch ME
            uialert_safe(fig_GUI,['音频播放失败：', ME.message],'播放错误'); 
            setStatus(handles,['播放失败：', ME.message]);
            fprintf('调试点16：播放失败\n');
        end
    end
    
    function onPlayFiltered(~,~)
        if ~isempty(S.playerFilt) && isplaying(S.playerFilt)
            stop(S.playerFilt);
            handles.btnPlayFilt.Text = '播放滤波后音频';
            setStatus(handles,'已停止播放滤波后音频');
            return;
        end
        
        if isempty(S.filtered)
            uialert_safe(fig_GUI,'没有滤波后音频。','播放错误'); 
            setStatus(handles,'播放失败：无滤波后音频'); 
            fprintf('调试点17：播放失败：无滤波后音频\n');
            return; 
        end
        
        try
            % ===  播放前范围检查（兼容向量/矩阵/多声道） ===
            audioToPlay = double(S.filtered);
            
            % 确定时间维 tdim（优先使用 S.timeDim，否则回退至第一个非单例维）             
            tdim = [];
            useTimeDim = false;
            if  ~isempty(S.timeDim) && S.timeDim==round(S.timeDim) && S.timeDim>=1
                tdim = S.timeDim;
                useTimeDim = true;
            else
                szx = size(audioToPlay);
                tdim = find(szx~=1,1,'first');
                if ~isempty(tdim) && tdim>=1
                    useTimeDim = true;
                else
                    tdim = 1; % fallback
                end
            end  
            % 处理数据中Nan/Inf等非有限数值
            audioToPlay = fillNonfinite(audioToPlay,tdim);

            % 把行向量转换为列向量，保证 samples x channels
            if isvector(audioToPlay)
                audioToPlay = audioToPlay(:);  % 变为 N x 1
            end
            
            % 如果是高维（>2）尝试 squeeze 成 2D，否则报错返回
            if ndims(audioToPlay) > 2
                tmp = squeeze(audioToPlay);
                if ismatrix(tmp)
                    audioToPlay = tmp;
                else
                    uialert_safe(fig_GUI, '音频数据维度超过2维，无法播放。请转换为 samples x channels 的二维矩阵。', '播放错误');
                    setStatus(handles,'播放失败：音频维度不支持');
                    fprintf('调试点16：播放失败：音频维度不支持\n');
                    return;
                end
            end
            
            % 检查包含 NaN / Inf
            if ~all(isfinite(audioToPlay), 'all')
                uialert_safe(fig_GUI, '音频包含 NaN 或 Inf，无法播放。', '播放错误');
                setStatus(handles,'播放失败：音频包含 NaN/Inf');
                fprintf('调试点16：播放失败：音频包含 NaN/Inf\n');
                return;
            end
            
            % 按通道查找是否有超过 1 的通道（samples x channels -> max over rows）
            channel_max = max(abs(audioToPlay), [], 1);   % 1 x C 向量
            
            % 仅对超过 1 的通道做缩放（保留 0.99 余量）
            over = channel_max > 1;
            if any(over)
                scale = ones(1, size(channel_max, 2));        % 默认不缩放
                scale(over) = 1 ./ channel_max(over);      % 仅对超限通道设缩放因子
                audioToPlay = audioToPlay .* scale;           % 隐式扩展：samples x channels .* 1 x channels
                setStatus(handles,'警告：部分声道幅度超过范围，已按通道调整');
                fprintf('调试点15：警告：部分声道幅度超过范围，已按通道调整\n');
            end
            % === 结束播放前检查 ===

            S.playerFilt = audioplayer(audioToPlay, S.fs);
            S.playerFilt.StopFcn = @(src,~) onFiltPlaybackComplete(src);
            play(S.playerFilt);
            handles.btnPlayFilt.Text = '停止放滤波后';
            setStatus(handles,'正在播放：滤波后音频');
        catch ME
            uialert_safe(fig_GUI,['音频播放失败：',ME.message],'播放错误');
            setStatus(handles,['播放失败：',ME.message]);
            fprintf('调试点19：播放失败\n');
        end
    end
   
    %% ---- 播放音频完成回调 ----
    function onOrigPlaybackComplete(~)
        if isvalid(handles.btnPlayOrig)
            % 根据当前数据源设置按钮文本
            if strcmp(handles.ddDataSource.Value, '多频正弦')
                handles.btnPlayOrig.Text = '播放生成/加噪';
            elseif strcmp(handles.ddDataSource.Value, '导入工作区数据')
                handles.btnPlayOrig.Text = '播放导入/加噪';
            else
                handles.btnPlayOrig.Text = '播放原始/加噪';
            end
        end
        
        if strcmp(handles.ddDataSource.Value, '多频正弦')
            setStatus(handles,'生成信号播放完成');
        elseif strcmp(handles.ddDataSource.Value, '导入工作区数据')
            setStatus(handles,'导入信号播放完成');
        else
            setStatus(handles,'原始/加噪音频播放完成');
        end
    end

    function onFiltPlaybackComplete(~)
        if isvalid(handles.btnPlayFilt)
            handles.btnPlayFilt.Text = '播放滤波后音频';
        end
        setStatus(handles,'滤波后音频播放完成');
    end

    %% ---- “重采样”按钮回调：编辑采样率/重采样 ----
    function onEditFsButton(~, ~)
        % 是否有效重采样标志
        S.hasResampled = false;
        % 弹出输入框请求新的采样率，然后确认是否重采样（弹窗逻辑在此）
        try
            oldFs = S.fs;
        catch
            oldFs = 44100;
        end
    
        % 创建自定义对话框获取新采样率
        dlg_EditFsButton = createCenteredUIFigure('Name', '编辑采样率/重采样', ...
                       'Position', [700, 500, 400, 160], ...
                       'WindowStyle', 'modal');
        
        % 创建网格布局
        gl_EditFsButton = uigridlayout(dlg_EditFsButton, [3, 2]);
        gl_EditFsButton.RowHeight = {'1x', '1x', '1x'};
        gl_EditFsButton.ColumnWidth = {'1x', '1x'};
        gl_EditFsButton.Padding = [20, 20, 20, 20];
        
        % 添加提示文本
        infoText = uilabel(gl_EditFsButton, 'Text', sprintf('当前采样率: %d Hz', oldFs));
        infoText.Layout.Row = 1;
        infoText.Layout.Column = 1;
        infoText.HorizontalAlignment = 'left';
        infoText.FontWeight = 'bold';
        
        % 添加输入标签
        lblFs_EditFsButton = uilabel(gl_EditFsButton, 'Text', '输入新的采样率 (Hz):');
        lblFs_EditFsButton.Layout.Row = 2;
        lblFs_EditFsButton.Layout.Column = 1;
        
        % 添加数值输入框
        edtNewFs = uieditfield(gl_EditFsButton, 'numeric', 'Value', oldFs, 'Limits', [1e-6, Inf]);
        edtNewFs.Layout.Row = 2;
        edtNewFs.Layout.Column = 2;
        
        % 添加范围提示
        rangeText = uilabel(gl_EditFsButton, 'Text', '有效范围: (1e-6, Inf) Hz');
        rangeText.Layout.Row = 1;
        rangeText.Layout.Column = 2;
        rangeText.HorizontalAlignment = 'left';
        rangeText.FontAngle = 'italic';
        
        % 添加确认和取消按钮
        btnConfirm = uibutton(gl_EditFsButton, 'push', 'Text', '确认', ...
                             'ButtonPushedFcn', @(src,event) uiresume(dlg_EditFsButton));
        btnConfirm.Layout.Row = 3;
        btnConfirm.Layout.Column = 1;
        
        btnCancel = uibutton(gl_EditFsButton, 'push', 'Text', '取消', ...
                            'ButtonPushedFcn', @(src,event) delete(dlg_EditFsButton));
        btnCancel.Layout.Row = 3;
        btnCancel.Layout.Column = 2;
        
        % 等待用户响应
        uiwait(dlg_EditFsButton);
        
        % 检查对话框是否仍然存在（用户是否点击了确认）
        if isvalid(dlg_EditFsButton)
            newFs = round(edtNewFs.Value); 
            try
                close(dlg_EditFsButton);
            catch
                delete(dlg_EditFsButton);
            end
            % 如果采样率没有变化，直接返回
            if newFs == oldFs
                setStatus(handles,'采样率未改变。');
                return;
            end
        else
            setStatus(handles,'已取消采样率编辑。');
            return;
        end  
        
        % ===== 确认提示窗口 =====
        setStatus(handles,'准备弹出确认提示窗口...');
        % fprintf('调试: 准备弹出确认提示窗口，oldFs=%d, newFs=%d\n', oldFs, newFs);
        
        % 确认对话（优先 uiconfirm，降级到 questdlg）
        msg = sprintf(['您将把处理采样率从 %d Hz 改为 %d Hz。\n\n' ...
                       '选择"重采样到此采样率"将对当前数据执行带抗混叠的重采样并替换数据；\n' ...
                       '选择"取消"将放弃更改，保持原采样率。'], oldFs, newFs);
        
        choice = uiconfirm(fig_GUI, msg, '更改采样率', ...
                           'Options', {'重采样到此采样率','取消'}, ...
                           'DefaultOption', 2, 'CancelOption', 2);
        
        % fprintf('调试: 用户选择: %s\n', choice);
        
        if isempty(choice) 
            setStatus(handles,'已取消采样率更改（选择为空）。');
            % fprintf('调试: 选择为空，直接返回\n');
            return;
        elseif strcmp(choice, '取消')
            setStatus(handles,'已取消采样率更改。');
            % fprintf('调试: 用户选择取消，返回\n');
            return;
        end
        
        % fprintf('调试: 用户确认重采样，继续执行...\n');
        setStatus(handles,'用户确认重采样，开始执行...');
        
        % ========== 执行重采样 ==========
        
        try
            % 若没有数据，仅更新元数据
            if isempty(S.currentSignal)
                % fprintf('调试: 无音频数据，仅更新元数据\n');
                S.fs = newFs;
                ds = '';
                try 
                    ds = handles.ddDataSource.Value; 
                catch
                end
                if strcmp(ds, '音频信号')
                    S.audioFs = newFs;
                elseif strcmp(ds, '多频正弦')
                    S.mtFs = newFs;
                elseif strcmp(ds, '导入工作区数据')
                    S.wsFs = newFs;
                end
                % 抑制回调写回 UI
                handles.lblFsValue.Text = num2str(S.fs);
                updateFrequencyLimits(S.fs, handles);
                updatePlotsAndAnalysis(S, handles);
                setStatus(handles,sprintf('采样率设置为 %d Hz（无数据，无需重采样）。', S.fs));
                return;
            else
                % fprintf('调试: 有音频数据，开始重采样\n');
            end    
    
            % 有数据时进行带抗混叠重采样
            [p, q] = rat(double(newFs)/double(oldFs), 1e-12);
    
            % 如果 p/q 等于 1/1，无需重采样
            if p==1 && q==1
                % 无需改变数据
            else
                % 优先使用 S.timeDim（如果存在且有效），否则回退至第一个非单例维度
                if  ~isempty(S.timeDim) && S.timeDim==round(S.timeDim) && S.timeDim>=1
                    tdim_use = S.timeDim;
                else
                    tdim_use = find(size(S.currentSignal)~=1,1,'first');
                    if isempty(tdim_use) || tdim_use < 1
                        tdim_use = 1; 
                    end
                end
            
                % 当前信号信号（若存在）
                if ~isempty(S.currentSignal)
                    try
                        S.currentSignal = doResamplePreserveNaN(S.currentSignal, p, q, tdim_use);
                               
                        % 处理数据中Nan/Inf等非有限数值
                        S.currentSignal  = fillNonfinite(S.currentSignal ,tdim_use);

                    catch ME
                        uialert_safe(fig_GUI,['重采样主音频失败：',ME.message],'重采样错误');
                        % 保持原值（或置空视你的策略），这里保持原值
                    end
                end
            
                % % 同步重采样多频信号（若存在）
                % if isprop(S, 'multiToneSignal') && ~isempty(S.multiToneSignal)
                %     try
                %         S.multiToneSignal = doResamplePreserveNaN(S.multiToneSignal, p, q, tdim_use);
                % 
                %         % 处理数据中Nan/Inf等非有限数值
                %         S.multiToneSignal  = fillNonfinite(S.multiToneSignal ,tdim_use);
                % 
                %         if isprop(handles, 'ddDataSource') && strcmp(handles.ddDataSource.Value, '多频正弦')
                %             S.currentSignal = S.multiToneSignal;
                %         end
                %     catch ME
                %         uialert_safe(fig_GUI,['重采样 multiToneSignal 失败：',ME.message],'重采样错误'); 
                %         S.multiToneSignal = [];
                %     end
                % end
            
                % 同步重采样 noisy（若存在）
                if isprop(S, 'noisy') && ~isempty(S.noisy)
                    try
                        S.noisy = doResamplePreserveNaN(S.noisy, p, q, tdim_use);
                       
                        % 处理数据中Nan/Inf等非有限数值
                        S.noisy  = fillNonfinite(S.noisy ,tdim_use);

                    catch ME
                        uialert_safe(fig_GUI,['重采样 noisy 失败：',ME.message],'重采样错误');  
                        S.noisy = [];
                    end
                end
            end
    

            % 清除继续滤波状态的数据
            clearContinueFilterState(S, handles);
            
    
            % 更新 S 的采样率元数据
            S.fs = newFs;
            ds = '';
            try 
                ds = handles.ddDataSource.Value; 
            catch
            end
            if strcmp(ds, '音频信号')
                S.audioFs = newFs;
            elseif strcmp(ds, '多频正弦')
                S.mtFs = newFs;         
            elseif strcmp(ds, '导入工作区数据')
                S.wsFs = newFs;
            end
    
            % 更新 UI（抑制触发 ValueChanged 回调）
            handles.lblFsValue.Text = num2str(S.fs);
    
            % 按原逻辑禁用需重新应用的按钮
            try
                handles.btnPlayFilt.Enable = 'off';
                handles.btnSaveFiltered.Enable = 'off';
                handles.btnShowCompare.Enable = 'off';
                % 统一刷新按钮状态
                updateApplyButtonEnable(S.filterIsDesigned, S.allowApplyFilter, handles);
            catch
            end
            updateSaveOrigGenButton(S, handles);
    
            updateFrequencyLimits(S.fs, handles);
            updatePlotsAndAnalysis(S, handles);
            % 启动保存图像按钮
            handles.btnSaveFigs.Enable = 'on';
            setStatus(handles,sprintf('已重采样：%d Hz -> %d Hz（信号数据已更新）。', oldFs, newFs));
            S.hasResampled = true;

            % fprintf('调试: 重采样完成\n');
        catch ME
            % 重采样失败：恢复显示旧值
            errMsg = ['重采样失败：' ME.message];
            % fprintf('调试: 重采样错误: %s\n', ME.message);
            try
                if ~isempty(fig_GUI) && ishghandle(fig_GUI) && strcmp(get(fig_GUI, 'Type'), 'figure') && exist('uialert', 'file') == 2
                    uialert(fig_GUI, errMsg, '重采样错误');
                else
                    errordlg(errMsg, '重采样错误');
                end
            catch
            end
            handles.lblFsValue.Text = num2str(S.fs);
            setStatus(handles,'重采样失败，已恢复旧采样率显示。');
            fprintf('调试点21：重采样失败，已恢复旧采样率显示。\n');
        end
        % ========== 执行完毕 ==========

        % --- 重采样通用子例程 ---
        function Y = doResamplePreserveNaN(X, p, q, tdim)
            % 重采样通用子例程（重写：使用 to2DtimeMajor 以统一时间维处理）
            % - X: 任意维数组（time dimension = tdim）
            % - p, q: resample ratio
            % - 返回 Y：重采样后的数组（保持除时间维以外的维顺序不变）
            %
            % 处理策略：
            % 1) 把时间维 permute 到第 1 维
            % 2) 将数据展为 [N x channels] 矩阵（N=time length）
            % 3) 为每个通道生成 mask = ~isnan(x)，对 mask 和填充后的信号均进行 resample
            % 4) mask_resample < 0.5 处视作 NaN
            % 5) 尝试把结果转换回原始数据类型（如果失败则保留 double）
        
            % 早退保护
            if isempty(X)
                Y = X;
                return;
            end
        
            % 保存原始 class
            origClass = class(X);
        
            % 使用 to2DtimeMajor 将时间维移到第1维并展开为 [N x channels]
            [X2, restoreFn] = to2DtimeMajor(X, tdim);   % X2: N x channels
        
            N = size(X2,1);
            channels = size(X2,2);
        
            % 构建 mask（double，以便用 resample 处理）
            mask = double(~isnan(X2));
        
            % 填充 NaN（按列做线性插值，全部 NaN 列填 0）
            Xfilled = double(X2);  % 确保为 double
            tvec = (1:N)';
            for c = 1:channels
                v = X2(:,c);
                if all(isnan(v))
                    Xfilled(:,c) = 0;
                else
                    valid = ~isnan(v);
                    if any(~valid)
                        % linear interp, extrapolate by nearest (interp1 with 'extrap')
                        Xfilled(~valid,c) = interp1(tvec(valid), v(valid), tvec(~valid), 'linear', 'extrap');
                    end
                    % 若无 NaN，Xfilled 已是正确值
                end
            end
        
            % 调用 resample（支持矩阵输入：按列独立重采样）
            try
                sig_res = resample(Xfilled, p, q);   % newN x channels
                mask_res = resample(mask, p, q);     % newN x channels (fractional)
            catch ME
                % 若 resample 失败，向上抛出以便上层捕获并显示错误
                rethrow(ME);
            end
        
            % threshold mask_res -> boolean，<0.5 判为 NaN
            mask_bool = mask_res >= 0.5;
        
            % 将无效点设为 NaN
            sig_res(~mask_bool) = NaN;
        
            % 将结果转换回原来形状（通过 restoreFn）
            % restoreFn 接受 [newN x channels] 并返回形状与原 X 相同（时间维已替换为 newN）
            try
                Y = restoreFn(sig_res);
            catch
                % 如果 restoreFn 失败（非常罕见），退回为保守行为：reshape back to sensible shape
                % 但正常情况下不会进这里
                warning('doResamplePreserveNaN:restoreFailed', '恢复形状失败，返回重采样矩阵并保留 double 类型。');
                Y = sig_res;
            end
        
            % 尝试恢复原始数据类型（保守）
            if ~strcmp(origClass, 'double')
                try
                    % 仅在常见数值/逻辑类型下 cast，其他类型 best-effort
                    if isCommonNumericOrLogicalClass(origClass)
                        Y = cast(Y, origClass);
                    else
                        try
                            Y = cast(Y, origClass);
                        catch
                            % 保持 double
                        end
                    end
                catch
                    % 忽略任何 cast 错误，保持现状
                end
            end
        end

    end

    %% ---- 滤波器“设计方法”切换回调 ----
    function onDesignMethodChange(src,~)
        val = src.Value;
        safeEnableHan('ddType','on');           % 滤波器类型下拉
        switch val
            case 'IIR'
                % IIR：启用 IIR 原型相关，禁用 FIR 控件
                handles.ddIIRProto.Enable = 'on';
                handles.edtIIROrder.Enable = 'on';
                handles.edtFIROrder.Enable = 'off';
                handles.ddWindow.Enable = 'off';
                % 禁用 FIR 优化子方法下拉
                if isprop(handles,'ddFIRMethod'), handles.ddFIRMethod.Enable = 'off'; end
                % 先把 Rp/Rs 置为 off（applyIIRProtoEnables 会根据阶数/原型调整）
                handles.edtRp.Enable = 'off'; handles.edtRs.Enable = 'off';
    
                if ~any(strcmpi(handles.ddIIRProto.Value,{'yule-walker','yulewalk','yule-walker '})) && ~any(strcmpi(handles.ddIIRProto.Value,{'maxflat','maxflat '}))
                    % 切换到非 FIR优化设计法、FIR频率采样法 、 IIR-Yule-Walker、IIR-maxflat时，禁用多带/高级
                    try
                        if isprop(handles,'btnMultiBand'), handles.btnMultiBand.Enable = 'off'; end
                        if isprop(handles,'ddType') && strcmp(handles.ddType.Value,'多带/高级')
                            try
                                if exist('uialert_safe','file')
                                    uialert_safe(fig_GUI,'多带/高级仅在 FIR优化设计法、FIR频率采样法、IIR-Yule-Walker、IIR-maxflat、FIRintfilt插值、FIRgaussdesign脉冲整形、FIRrcosdesign脉冲整形、Savitzky-Golay 下支持。已自动切回为 "低通"。','不支持的操作');
                                else
                                    uialert(fig_GUI,'多带/高级仅在 FIR优化设计法、FIR频率采样法、IIR-Yule-Walker、IIR-maxflat、FIRintfilt插值、FIRgaussdesign脉冲整形、FIRrcosdesign脉冲整形、Savitzky-Golay 下支持。已自动切回为 "低通"。','不支持的操作');
                                end
                            catch
                            end
                            try handles.ddType.Value = '低通'; catch; end
                        end
                    catch
                    end
                elseif any(strcmpi(handles.ddIIRProto.Value,{'yule-walker','yulewalk','yule-walker '})) || any(strcmpi(handles.ddIIRProto.Value,{'maxflat','maxflat '}))
                    % 若当前类型已是 多带/高级，则启用多带/高级按钮
                    try
                        if strcmp(handles.ddType.Value,'多带/高级')
                            handles.btnMultiBand.Enable = 'on';
                        else
                            handles.btnMultiBand.Enable = 'off';
                        end
                    catch
                    end
                end
              
                % 在所有非 陷波/峰值 的分支末尾添加：
                safeEnableHan('btnNotchPeakParams','off');
                % safeEnableHan('lblNotchPeak','off');

                % IIR - Yule-Walker (yulewalk) 不支持自动估阶
                if round(double(handles.edtIIROrder.Value)) <= 0 && any(strcmpi(handles.ddIIRProto.Value,{'yule-walker','yulewalk','yule-walker '}))
                        uialert_safe(fig_GUI, ...
                           'IIR - Yule-Walker (yulewalk) 不支持自动估阶，阶数已更改为默认值 4。请在 "IIR 阶数" 输入框中输入正整数阶数。', ...
                           '参数错误');
                end

                % 特殊：如果当前 IIR 原型是 maxflat，要确保 ddType 合法并且阶数 > 0
                try
                    if isprop(handles,'ddIIRProto') && strcmpi(handles.ddIIRProto.Value,'maxflat')
                        allowed = {'低通','高通','多带/高级'};
                        if ~any(strcmp(handles.ddType.Value, allowed))
                            if exist('uialert_safe','file')
                                uialert_safe(fig_GUI,'IIR 原型为 maxflat 时仅支持：低通 / 高通 / 多带/高级。已自动切回为 低通。','不支持的滤波类型');
                            else
                                uialert(fig_GUI,'IIR 原型为 maxflat 时仅支持：低通 / 高通 / 多带/高级。已自动切回为 低通。','不支持的滤波类型');
                            end
                            handles.ddType.Value = '低通';
                        end
                        % 检查阶数
                        if round(double(handles.edtIIROrder.Value)) <= 0
                            if exist('uialert_safe','file')
                                uialert_safe(fig_GUI, 'maxflat 不支持自动估阶。阶数已更改为默认值 4。请在 "IIR 阶数" 输入框中输入正整数阶数。', '参数错误');
                            else
                                uialert(fig_GUI, 'maxflat 不支持自动估阶。阶数已更改为默认值 4。请在 "IIR 阶数" 输入框中输入正整数阶数。', '参数错误');
                            end
                            handles.edtIIROrder.Value = 4;
                        end
                    end
                catch
                end


                % 更新设计方法提示标签并同步状态栏
                updateDesignLabel(S, handles);
    
                % 统一让 applyIIRProtoEnables 根据 proto/type/order 处理控件启用状态
                % （applyIIRProtoEnables :当 order<=0 时不灰显 Rp/Rs/...）
                applyIIRProtoEnables(S, handles, fig_GUI, handles.ddIIRProto.Value, handles.ddType.Value);
                onTypeChange(handles.ddType);

            case 'FIR窗函数法'
                % 窗函数法：启用窗与阶数，禁用优化子方法（但不要直接覆盖 type/阶数决定的控件）
                handles.ddIIRProto.Enable = 'off';
                handles.edtIIROrder.Enable = 'off';
                handles.edtFIROrder.Enable = 'on';
                handles.ddWindow.Enable = 'on';
                if isprop(handles,'ddFIRMethod'), handles.ddFIRMethod.Enable = 'off'; end
    

                % 切换到非 FIR 优化法时，禁用多带/高级
                try
                    if isprop(handles,'btnMultiBand'), handles.btnMultiBand.Enable = 'off'; end
                    if isprop(handles,'ddType') && strcmp(handles.ddType.Value,'多带/高级')
                        try
                            if exist('uialert_safe','file')
                                uialert_safe(fig_GUI,'多带/高级仅在 FIR优化设计法、FIR频率采样法、IIR-Yule-Walker、IIR-maxflat、FIRintfilt插值、FIRgaussdesign脉冲整形、FIRrcosdesign脉冲整形、Savitzky-Golay 下支持。已自动切回为 "低通"。','不支持的操作');
                            else
                                uialert(fig_GUI,'多带/高级仅在 FIR优化设计法、FIR频率采样法、IIR-Yule-Walker、IIR-maxflat、FIRintfilt插值、FIRgaussdesign脉冲整形、FIRrcosdesign脉冲整形、Savitzky-Golay 下支持。已自动切回为 "低通"。','不支持的操作');
                            end
                        catch
                        end
                        try handles.ddType.Value = '低通'; catch; end
                    end
                catch
                end

                % 在所有非 陷波/峰值 的分支末尾添加：
                safeEnableHan('btnNotchPeakParams','off');
                % safeEnableHan('lblNotchPeak','off');

                if round(double(handles.edtFIROrder.Value)) <= 0 && ~strcmpi(handles.ddWindow.Value,'Kaiser')
                    uialert_safe(fig_GUI, 'FIR窗函数法 - Rectwin/Triang/Hann/Hamming/Blackman不支持自动估阶，阶数已更改为默认值 64。请在 "FIR 阶数" 输入框中输入正整数。', '参数错误');
                    setStatus(handles,'设计失败：Rectwin/Triang/Hann/Hamming/Blackman 需要正整数阶数'); 
                        try
                            handles.edtFIROrder.Value = 64; % 默认 64
                        catch
                        end
                        return;
                end


                % 不要在这里直接决定 Rp/Rs 与 sb1/sb2 的 Enable（会与 type/阶数的逻辑冲突）
                % 统一由 onTypeChange 根据当前类型与 edtFIROrder 的值来设置控件状态。
                % 立即调用 onTypeChange 以使类型相关的控件状态（包括 Rp/Rs）被正确设置。

                onTypeChange(handles.ddType); % onTypeChange 会读取 edtFIROrder 并作出正确处理

                % 更新设计方法提示标签并同步状态栏
                updateDesignLabel(S, handles); 

            case 'FIR优化设计法'
                % 优化法：启用 FIR 优化下拉，启用阶数与 Rp/Rs 与阻带边界
                handles.ddIIRProto.Enable = 'off';
                handles.edtIIROrder.Enable = 'off'; % IIR 不用
                handles.edtFIROrder.Enable = 'on';  % 允许用户给阶数或设 0 自动估阶
                handles.ddWindow.Enable = 'off';    % 窗无关
                if isprop(handles,'ddFIRMethod')
                    handles.ddFIRMethod.Enable = 'on'; 
                    try onFIRMethodChange(handles.ddFIRMethod); catch; end
                end
    
                % 若当前类型已是 多带/高级，则启用多带/高级按钮
                try
                    if strcmp(handles.ddType.Value,'多带/高级')
                        handles.btnMultiBand.Enable = 'on';
                    else
                        handles.btnMultiBand.Enable = 'off';
                    end
                catch
                end

                % 在所有非 陷波/峰值 的分支末尾添加：
                safeEnableHan('btnNotchPeakParams','off');
                % safeEnableHan('lblNotchPeak','off');

                if round(double(handles.edtFIROrder.Value)) <= 0 && ~strcmpi(handles.ddFIRMethod.Value,'Parks-McClellan')
                    uialert_safe(fig_GUI, 'FIR优化设计法 - Cplx-Parks-McClellan/最小二乘(firls)/约束最小二乘(fircls)/约束最小二乘1(fircls1)不支持自动估阶，阶数已更改为默认值 64。请在 "FIR 阶数" 输入框中输入正整数。', '参数错误');
                    setStatus(handles,'设计失败：Cplx-Parks-McClellan/最小二乘(firls)/约束最小二乘(fircls)/约束最小二乘1(fircls1) 需要正整数阶数'); 
                        try
                            handles.edtFIROrder.Value = 64; % 默认 64
                        catch
                        end
                end

                % 优化法需要根据当前类型启用阻带/通带参数（调用 onTypeChange）
                onTypeChange(handles.ddType);

                % 更新设计方法提示标签并同步状态栏
                updateDesignLabel(S, handles);
    

            % === FIR 频率采样法 控件启用/禁用逻辑 ===
            case 'FIR频率采样法'
                handles.ddIIRProto.Enable = 'off';
                handles.edtIIROrder.Enable = 'off'; % IIR 不用
                % fir2 不做自动估阶 —— 仅启用 FIR 阶数输入（用户必须输入正整数）
                handles.edtFIROrder.Enable = 'on';
                % 禁用与 FIR 优化法 的子控件（这些对 fir2 没必要或冲突）
                handles.ddFIRMethod.Enable = 'off';
                handles.ddWindow.Enable = 'off'; % 窗可由多带/高级弹窗独立设置（或按需扩展）
                % 禁用 Rp/Rs（fir2 不需要 Rp/Rs 作为直接输入）
                handles.edtRp.Enable = 'off'; handles.edtRs.Enable = 'off';
                % 多带/高级按钮保留可点击（在多带/高级时需要设置 f/m）
                % 当选择多带/高级时 onTypeChange 会启用 btnMultiBand（原逻辑会处理）
                % 若当前类型已是 多带/高级，则启用多带/高级按钮
                try
                    if strcmp(handles.ddType.Value,'多带/高级')
                        handles.btnMultiBand.Enable = 'on';
                    else
                        handles.btnMultiBand.Enable = 'off';
                    end
                catch
                end
                    
                % 在所有非 陷波/峰值 的分支末尾添加：
                safeEnableHan('btnNotchPeakParams','off');
                % safeEnableHan('lblNotchPeak','off');

                if round(double(handles.edtFIROrder.Value)) <= 0
                    uialert_safe(fig_GUI, 'FIR频率采样法 不支持自动估阶，阶数已更改为默认值 64。请在 "FIR 阶数" 输入框中输入正整数。', '参数错误');
                    setStatus(handles,'设计失败：FIR频率采样法 需要正整数阶数'); 
                        try
                            handles.edtFIROrder.Value = 64; % 默认 64
                        catch
                        end
                end
                
                % 优化法需要根据当前类型启用阻带/通带参数（调用 onTypeChange）
                onTypeChange(handles.ddType);
                
                % 更新设计方法提示标签并同步状态栏
                updateDesignLabel(S, handles);

            case 'FIRintfilt插值'
                % 特殊插值方法：禁用大部分 IIR/FIR 常规模块控件
                safeEnableHan('ddIIRProto','off');    % 或 handles.ddIIRProto.Enable = 'off';
                safeEnableHan('edtIIROrder','off');
                safeEnableHan('ddWindow','off');
                if isprop(handles,'ddFIRMethod'), safeEnableHan('ddFIRMethod','off'); end
                safeEnableHan('edtFIROrder','off');
            
                % 直接切换为 多带/高级，并启用 多带按钮
                try
                    handles.ddType.Value = '多带/高级';
                catch
                end
                safeEnableHan('btnMultiBand','on');
            
                % 禁用单段频率/幅值输入，使用户只能用多带/高级参数窗设置
                handles.edtRp.Enable = 'off'; handles.edtRs.Enable = 'off';
                safeEnableHan('edtPb1','off'); safeEnableHan('sldPb1','off');
                safeEnableHan('edtPb2','off'); safeEnableHan('sldPb2','off');
                safeEnableHan('edtSb1','off'); safeEnableHan('sldSb1','off');
                safeEnableHan('edtSb2','off'); safeEnableHan('sldSb2','off');
                            
                % 在所有非 陷波/峰值 的分支末尾添加：
                safeEnableHan('btnNotchPeakParams','off');
                % safeEnableHan('lblNotchPeak','off');

                % 滤波函数选择下拉框禁用，因为FIRintfilt插值应用滤波器时使用filter（已在单独分支中应用filter）
                if strcmp(handles.ddDesignMethod.Value,'FIRintfilt插值')
                    try handles.ddFilterFunction.Value = 'filter'; catch; end
                    handles.ddFilterFunction.Enable = 'off';
                end

                % 提示与状态更新
                setStatus(handles,'已选择 FIRintfilt 插值 — 请通过 多带 / 高级滤波参数 设置 intfilt 参数。');
                updateNote(S, handles);
                updateDesignLabel(S, handles);

            case 'FIRgaussdesign脉冲整形'
                % --- 禁用不适用控件（IIR 原型 / IIR 阶数 / FIR 窗口 / FIR 优化子方法 / FIR 阶数）
                safeEnableHan('ddIIRProto','off');
                safeEnableHan('edtIIROrder','off');
                safeEnableHan('ddWindow','off');
                if isprop(handles,'ddFIRMethod'), safeEnableHan('ddFIRMethod','off'); end
                safeEnableHan('edtFIROrder','off');
            
                % 直接切换为 多带/高级，并启用 多带按钮（用户通过多带按钮设置 bt/span/sps）
                try
                    handles.ddType.Value = '多带/高级';
                catch
                end
                safeEnableHan('btnMultiBand','on'); % 多带按钮用于打开 gauss 参数窗口
            
                % 禁用单段技术指标输入（Rp, Rs, fp1, fp2, fst1, fst2）
                handles.edtRp.Enable = 'off';
                handles.edtRs.Enable = 'off';
                safeEnableHan('edtPb1','off'); safeEnableHan('sldPb1','off');
                safeEnableHan('edtPb2','off'); safeEnableHan('sldPb2','off');
                safeEnableHan('edtSb1','off'); safeEnableHan('sldSb1','off');
                safeEnableHan('edtSb2','off'); safeEnableHan('sldSb2','off');
                            
                % 在所有非 陷波/峰值 的分支末尾添加：
                safeEnableHan('btnNotchPeakParams','off');
                % safeEnableHan('lblNotchPeak','off');

                % 提示用户
                setStatus(handles,'已选择 FIRgaussdesign脉冲整形 — 请点击 多带 / 高级滤波参数 并设置 bt, span, sps。');
                updateNote(S, handles);
                updateDesignLabel(S, handles);

            case 'FIRrcosdesign脉冲整形'
                % --- 禁用不适用控件（IIR 原型 / IIR 阶数 / FIR 窗口 / FIR 优化子方法 / FIR 阶数）
                safeEnableHan('ddIIRProto','off');
                safeEnableHan('edtIIROrder','off');
                safeEnableHan('ddWindow','off');
                if isprop(handles,'ddFIRMethod'), safeEnableHan('ddFIRMethod','off'); end
                safeEnableHan('edtFIROrder','off');
            
                % 直接切换为 多带/高级，并启用 多带按钮（用户通过多带按钮设置 beta/span/sps）
                try
                    handles.ddType.Value = '多带/高级';
                catch
                end
                safeEnableHan('btnMultiBand','on'); % 多带按钮用于打开 rcos 参数窗口
            
                % 禁用单段技术指标输入（Rp, Rs, fp1, fp2, fst1, fst2）
                handles.edtRp.Enable = 'off';
                handles.edtRs.Enable = 'off';
                safeEnableHan('edtPb1','off'); safeEnableHan('sldPb1','off');
                safeEnableHan('edtPb2','off'); safeEnableHan('sldPb2','off');
                safeEnableHan('edtSb1','off'); safeEnableHan('sldSb1','off');
                safeEnableHan('edtSb2','off'); safeEnableHan('sldSb2','off');
            
                % 在所有非 陷波/峰值 的分支末尾添加：
                safeEnableHan('btnNotchPeakParams','off');
                % safeEnableHan('lblNotchPeak','off');

                % 提示用户
                setStatus(handles,'已选择 FIRrcosdesign脉冲整形 — 请点击 多带 / 高级滤波参数 并设置 rolloff/beta, span, sps，以及滤波器用途（发射/接收/常规）。');
                updateNote(S, handles);
                updateDesignLabel(S, handles);




            case 'Savitzky-Golay'
                % 1) 禁用 IIR 原型 和 FIR 常规控件
                safeEnableHan('ddIIRProto','off');
                safeEnableHan('edtIIROrder','off');
                safeEnableHan('ddWindow','off');
                if isprop(handles,'ddFIRMethod'), safeEnableHan('ddFIRMethod','off'); end
                safeEnableHan('edtFIROrder','off');
            
                % 2) 直接切换为 多带/高级，并启用 多带按钮（多带按钮将打开 SG 窗口）
                try
                    handles.ddType.Value = '多带/高级';
                catch
                end
                safeEnableHan('btnMultiBand','on'); % 多带按钮用于打开 SG 参数窗口
            
                % 3) 禁用单段技术指标输入（Rp, Rs, fp1, fp2, fst1, fst2）
                handles.edtRp.Enable = 'off';
                handles.edtRs.Enable = 'off';
                safeEnableHan('edtPb1','off'); safeEnableHan('sldPb1','off');
                safeEnableHan('edtPb2','off'); safeEnableHan('sldPb2','off');
                safeEnableHan('edtSb1','off'); safeEnableHan('sldSb1','off');
                safeEnableHan('edtSb2','off'); safeEnableHan('sldSb2','off');
            

                % 滤波函数选择下拉框禁用，因为Savitzky-Golay应用滤波器时不使用filter、filtfilt、my_filtfilt
                if strcmp(handles.ddDesignMethod.Value,'Savitzky-Golay')
                    handles.ddFilterFunction.Enable = 'off';
                end

                % 在所有非 陷波/峰值 的分支末尾添加：
                safeEnableHan('btnNotchPeakParams','off');
                % safeEnableHan('lblNotchPeak','off');

                % 4) 由于 SG 需要通过多带参数按钮设置，更新提示并刷新备注
                setStatus(handles,'已选择 Savitzky-Golay — 请点击 多带 / 高级滤波参数 并设置参数。');
                updateNote(S, handles);
                updateDesignLabel(S, handles);
                




            case {'陷波','峰值滤波'}
                % 当选择 陷波 或 峰值滤波 时：
                % 1) 使除了设计方法下拉外的设计子面板控件全部禁用（灰显）
                safeEnableHan('ddIIRProto','off');
                safeEnableHan('edtIIROrder','off');
                safeEnableHan('edtFIROrder','off');
                safeEnableHan('ddWindow','off');
                if isprop(handles,'ddFIRMethod'), safeEnableHan('ddFIRMethod','off'); end

                % 2) 在"滤波器技术指标"面板中：禁用大多数控件，只启用我们新加的按钮
                % 先禁用常用控件（用 safeEnableHan 保证健壮）
                safeEnableHan('ddType','off');           % 滤波器类型下拉
                safeEnableHan('btnMultiBand','off');     % 多带/高级按钮
                safeEnableHan('edtRp','off'); safeEnableHan('edtRs','off');
                safeEnableHan('edtPb1','off'); safeEnableHan('sldPb1','off');
                safeEnableHan('edtPb2','off'); safeEnableHan('sldPb2','off');
                safeEnableHan('edtSb1','off'); safeEnableHan('sldSb1','off');
                safeEnableHan('edtSb2','off'); safeEnableHan('sldSb2','off');

                % 3) 启用"陷波or峰值滤波参数"按钮
                safeEnableHan('btnNotchPeakParams','on');
                % safeEnableHan('lblNotchPeak','on');

                % 4) 更新提示标签
                % 更新设计方法提示标签并同步状态栏
                updateDesignLabel(S, handles);

                % 5) 更新状态栏
                setStatus(handles,sprintf('设计方法已切换为 %s（请点击"陷波or峰值滤波参数"设置具体参数）', src.Value));


            otherwise
                % 兜底（回退为 IIR 行为）
                handles.ddIIRProto.Enable = 'on';
                handles.edtIIROrder.Enable = 'on';
                handles.edtFIROrder.Enable = 'off';
                handles.ddWindow.Enable = 'off';
                if isprop(handles,'ddFIRMethod'), handles.ddFIRMethod.Enable = 'off'; end
                handles.lblDesignSelected.Text = '当前选择：未知';


                % 切换到非 FIR 优化法等时，禁用多带/高级
                try
                    if isprop(handles,'btnMultiBand'), handles.btnMultiBand.Enable = 'off'; end
                    if isprop(handles,'ddType') && strcmp(handles.ddType.Value,'多带/高级')
                        try
                            if exist('uialert_safe','file')
                                uialert_safe(fig_GUI,'多带/高级仅在 FIR优化设计法、FIR频率采样法、IIR-Yule-Walker、IIR-maxflat、FIRintfilt插值、FIRgaussdesign脉冲整形、FIRrcosdesign脉冲整形、Savitzky-Golay 下支持。已自动切回为 "低通"。','不支持的操作');
                            else
                                uialert(fig_GUI,'多带/高级仅在 FIR优化设计法、FIR频率采样法、IIR-Yule-Walker、IIR-maxflat、FIRintfilt插值、FIRgaussdesign脉冲整形、FIRrcosdesign脉冲整形、Savitzky-Golay 下支持。已自动切回为 "低通"。','不支持的操作');
                            end
                        catch
                        end
                        try handles.ddType.Value = '低通'; catch; end
                    end
                catch
                end

                % 在所有非 陷波/峰值 的分支末尾添加：
                safeEnableHan('btnNotchPeakParams','off');
                % safeEnableHan('lblNotchPeak','off');

                setStatus(handles,'已切换到未知设计方法（回退）。');
                fprintf('调试点46：已切换到未知设计方法（回退）。\n');
        end
        updateNote(S, handles);
    end

    %% ---- “IIR原型”切换提示/状态回调 ----
    function onIIRProtoChange(src,~)
        proto = src.Value;
        % 更新设计方法提示标签并同步状态栏
        updateDesignLabel(S, handles);
        
        % 只有在当前设计方法是IIR时才更新控件状态和标签
        if strcmpi(handles.ddDesignMethod.Value, 'IIR')
            ftype = handles.ddType.Value;
            if ~strcmp(ftype,'多带/高级')

                applyIIRProtoEnables(S, handles, fig_GUI, proto, ftype);
                

                % 如果切换到 maxflat，需要限制滤波类型并检查阶数
                if strcmpi(proto,'maxflat')
                    % 允许的类型集合
                    allowed = {'低通','高通','多带/高级'};
                    try
                        curType = handles.ddType.Value;
                    catch
                        curType = '';
                    end
                    if ~any(strcmp(curType, allowed))
                        % 弹窗并自动切回低通
                        try
                            uialert_safe(fig_GUI, 'IIR 原型为 maxflat 时仅支持：低通 / 高通 / 多带/高级。已自动切回为 低通。', '不支持的滤波类型');
                        catch
                            uialert(fig_GUI, 'IIR 原型为 maxflat 时仅支持：低通 / 高通 / 多带/高级。已自动切回为 低通。', '不支持的滤波类型');
                        end
                        try handles.ddType.Value = '低通'; catch; end
                    end
            
                    % maxflat 不支持自动估阶（edtIIROrder <=0），若<=0 则强制改为默认 4
                    try
                        ordVal = round(double(handles.edtIIROrder.Value));
                    catch
                        ordVal = NaN;
                    end
                    if isempty(ordVal) || ordVal <= 0
                        try
                            if exist('uialert_safe','file')
                                uialert_safe(fig_GUI,'maxflat 不支持自动估阶。阶数已更改为默认值 4。请在 "IIR 阶数" 输入框中输入正整数阶数。','参数错误');
                            else
                                uialert(fig_GUI,'maxflat 不支持自动估阶。阶数已更改为默认值 4。请在 "IIR 阶数" 输入框中输入正整数阶数。','参数错误');
                            end
                        catch
                        end
                        try handles.edtIIROrder.Value = 4; catch; end
                    end
                end


            elseif strcmp(ftype,'多带/高级')
                onTypeChange(handles.ddType);
            end
            % 更新设计方法提示标签并同步状态栏
            updateDesignLabel(S, handles);

        end
        updateNote(S, handles);
    end

    %% ---- “IIR原型”切换提示/状态与控件启用/禁用回调 ----
    function applyIIRProtoEnables(S, handles, fig_GUI, proto, ftype)
    % 传入的 handle类 S, handles; 主界面 fig_GUI; IIR原型 proto; 滤波类型 ftype
    % 对 S 的对象内容有 "读" 操作
    % 对 handles 的对象内容有 "读/写" 操作
    % fig_GUI 用于uialert_safe()在主界面弹提醒窗口

        % 说明：
        %  - 当 IIR 阶数 <= 0 时：除yulewalk、maxflat外，认为是"自动估阶"模式 -> 所有规格参数可编辑（Rp/Rs/fp/fs）。
        %  - 当 IIR 阶数 > 0 时：认为用户已指定阶数 -> 根据原型决定哪些参数用于直接调用设计函数。
        %
        % 典型规则（当 order>0）：
        %  - Butterworth: 只需要 Wp（通带截止）；不需要 Rp/Rs/Wst -> 禁用 Rp/Rs 与 阻带 fs。
        %  - Chebyshev I: 需要 Rp + Wp -> 启用 Rp 与 通带 fp；禁用 Rs 与 阻带 fs。
        %  - Chebyshev II: 需要 Rs + Wst -> 启用 Rs 与 阻带 fs；禁用 Rp 与 通带 fp。
        %  - Elliptic: 需要 Rp & Rs & Wp -> 启用 Rp, Rs, 通带 fp；禁用 阻带 fs。
        %
        % 注意：若你把阶数设为 <=0（自动估阶），上面所有控件都会被打开以便计算 ord/规范化。

        orderValue = round(double(handles.edtIIROrder.Value));

        % 先把所有相关控件统一设为可用/不可用的"基线"，以避免残留状态
        if orderValue <= 0
            

            % 自动估阶：全部打开
            safeEnableHan('edtRp','on'); safeEnableHan('edtRs','on');
            safeEnableHan('edtPb1','on'); safeEnableHan('sldPb1','on');
            safeEnableHan('edtPb2','on'); safeEnableHan('sldPb2','on');
            safeEnableHan('edtSb1','on'); safeEnableHan('sldSb1','on');
            safeEnableHan('edtSb2','on'); safeEnableHan('sldSb2','on');
            switch ftype
                case {'低通','高通'}
                    safeEnableHan('edtPb2','off'); safeEnableHan('sldPb2','off');
                    safeEnableHan('edtSb2','off'); safeEnableHan('sldSb2','off');  
                otherwise
                    safeEnableHan('edtPb2','on'); safeEnableHan('sldPb2','on');
                    safeEnableHan('edtSb2','on'); safeEnableHan('sldSb2','on');
            end
            if any(strcmpi(proto,{'yule-walker','yulewalk','yule-walker '}))
              safeEnableHan('edtRp','off'); safeEnableHan('edtRs','off');
              % 这里用安全弹窗提示并强制用户修改阶数（或设置一个默认）
                try
                    uialert_safe(fig_GUI, ...
                       'IIR - Yule-Walker (yulewalk) 不支持自动估阶，阶数已更改为默认值 4。请在 "IIR 阶数" 输入框中输入正整数阶数。', ...
                       '参数错误');
                catch
                    uialert(fig_GUI, ...
                       'IIR - Yule-Walker (yulewalk) 不支持自动估阶，阶数已更改为默认值 4。。请在 "IIR 阶数" 输入框中输入正整数阶数。', ...
                       '参数错误');
                end
                % 给一个温和的默认（便于继续操作）——也可以只提示让用户手动改为正整数
                try
                    handles.edtIIROrder.Value = max(1, round(4)); % 默认 4
                catch
                end
            end
            % 阶数输入框保持可编辑
            handles.edtIIROrder.Enable = 'on';
            % 更新设计方法提示标签并同步状态栏
            updateDesignLabel(S, handles);
            updateNote(S, handles);

            return;
        end

        % 如果到这里，说明 orderValue > 0（用户指定阶数），按原型/类型选择启用项
        % 先把所有都先禁用（保守策略），再按需要启用
        safeEnableHan('edtIIROrder','on');
        safeEnableHan('edtRp','off'); safeEnableHan('edtRs','off');
        safeEnableHan('edtPb1','off'); safeEnableHan('sldPb1','off');
        safeEnableHan('edtPb2','off'); safeEnableHan('sldPb2','off');
        safeEnableHan('edtSb1','off'); safeEnableHan('sldSb1','off');
        safeEnableHan('edtSb2','off'); safeEnableHan('sldSb2','off');

        % 辅助：按滤波类型启用左右通/阻带（只对通带/阻带决定启用哪些侧）
        function enable_pass_or_stop(which)
            switch which
                case '低通'
                    % 左侧通带有效（pb1），左侧阻带（sb1）是否启用取决于 proto
                    safeEnableHan('edtPb1','on'); safeEnableHan('sldPb1','on');
                    if any(strcmpi(proto,{'yule-walker','yulewalk','yule-walker '}))
                        safeEnableHan('edtSb1','on'); safeEnableHan('sldSb1','on');
                    end
                case '高通'
                    % 左侧通带有效（pb1 表示高通 cutoff），左侧阻带（sb1）是否启用取决于 proto
                    safeEnableHan('edtPb1','on'); safeEnableHan('sldPb1','on');
                    if any(strcmpi(proto,{'yule-walker','yulewalk','yule-walker '}))
                        safeEnableHan('edtSb1','on'); safeEnableHan('sldSb1','on');
                    end
                case '带通'
                    % 两侧通带有效（pb1,pb2）
                    safeEnableHan('edtPb1','on'); safeEnableHan('sldPb1','on');
                    safeEnableHan('edtPb2','on'); safeEnableHan('sldPb2','on');
                    if any(strcmpi(proto,{'yule-walker','yulewalk','yule-walker '}))
                        safeEnableHan('edtSb1','on'); safeEnableHan('sldSb1','on');
                        safeEnableHan('edtSb2','on'); safeEnableHan('sldSb2','on');
                    end
                case '带阻'
                    % 两侧通带有效（pb1,pb2）
                    safeEnableHan('edtPb1','on'); safeEnableHan('sldPb1','on');
                    safeEnableHan('edtPb2','on'); safeEnableHan('sldPb2','on');
                    if any(strcmpi(proto,{'yule-walker','yulewalk','yule-walker '}))
                        safeEnableHan('edtSb1','on'); safeEnableHan('sldSb1','on');
                        safeEnableHan('edtSb2','on'); safeEnableHan('sldSb2','on');
                    end
                otherwise
                    % 兜底：启用通带
                    safeEnableHan('edtPb1','on'); safeEnableHan('sldPb1','on');
            end
        end

        switch lower(proto)
            case {'butterworth','butterworth '} % 容错空格/大小写
                % butter(n, Wn, ftype) 直接使用通带截止 Wn（Wp），不使用 Rp/Rs/Wst -> 禁用 Rp/Rs/阻带（fs）；
                % 启用通带 cutoff（fp）按滤波类型左右侧
                %（即用户给定阶数时，阻带频率对直接调用 butter 不必填）
                enable_pass_or_stop(ftype);
                % 确保阻带 fst 被禁用（butter 不需要传 stopband）
                safeEnableHan('edtSb1','off'); safeEnableHan('sldSb1','off');
                safeEnableHan('edtSb2','off'); safeEnableHan('sldSb2','off');

            case {'chebyshev i','chebyshev i ','cheby1','chebyshev1'}
                % cheby1(n, Rp, Wp, ftype) -> 需要 Rp + 通带截止 Wp
                safeEnableHan('edtRp','on'); % passband ripple required
                enable_pass_or_stop(ftype);
                % 不需要 Rs/阻带（Ws）作为设计输入（已知阶数时）
                safeEnableHan('edtRs','off');
                safeEnableHan('edtSb1','off'); safeEnableHan('sldSb1','off');
                safeEnableHan('edtSb2','off'); safeEnableHan('sldSb2','off');

            case {'chebyshev ii','chebyshev ii ','cheby2','chebyshev2'}
                % cheby2(n, Rs, Wst, ftype) -> 需要 Rs + 阻带截止 Wst
                safeEnableHan('edtRs','on');  % stopband attenuation required
                % 阻带 Wst -> 启用 sb 控件（左右取决于 ftype）
                switch ftype
                    case {'低通','高通'}
                        safeEnableHan('edtSb1','on'); safeEnableHan('sldSb1','on');
                    case {'带通','带阻'}
                        safeEnableHan('edtSb1','on'); safeEnableHan('sldSb1','on');
                        safeEnableHan('edtSb2','on'); safeEnableHan('sldSb2','on');
                end
                % cheby2 不使用 Rp（pass ripple）
                safeEnableHan('edtRp','off');
                safeEnableHan('edtPb1','off'); safeEnableHan('sldPb1','off');
                safeEnableHan('edtPb2','off'); safeEnableHan('sldPb2','off');
                % keep passband disabled because cheby2 uses Wst
                % （如果你希望同时打开通带以便用户也能看到 Wp，可在此调整）

            case {'elliptic','ellip','elliptic '}
                % ellip(n, Rp, Rs, Wp, ftype) -> 需要 Rp, Rs, 通带 Wp
                safeEnableHan('edtRp','on'); safeEnableHan('edtRs','on');
                enable_pass_or_stop(ftype);
                % 不需要额外启用阻带 Ws（ellip 不强制要求 Wst 当 n 已知）
                safeEnableHan('edtSb1','off'); safeEnableHan('sldSb1','off');
                safeEnableHan('edtSb2','off'); safeEnableHan('sldSb2','off');

            case {'yule-walker','yulewalk','yule-walker '}
                % Yule-Walker (yulewalk) 使用 [b,a] = yulewalk(n, f, m)
                % - 不使用 Rp/Rs，故禁用相关控件（灰显）
                safeEnableHan('edtRp','off'); safeEnableHan('edtRs','off');

                % Yule-walker 需要用户提供频率/幅值点 -> 启用通/阻带截止控件以便用户输入
                enable_pass_or_stop(ftype);    % 保持与 butter 等相同的通/阻带启用规则
                if strcmp(handles.ddType.Value,'多带/高级')
                    onTypeChange(handles.ddType);
                end

            case {'maxflat','maxflat '}
                % my_maxflat: 仅支持 Low/High (和多带/高级 弹窗模式)
                % 规则：
                %  - 禁用 Rp, Rs（不使用通带/阻带衰减规格）
                %  - 对于 低通/高通，仅使用 fp1（edtPb1）作为截止
                %  - 禁用 fp2, fst1, fst2（保守策略），除非用户选择 '多带/高级'（那时启用 multi-band 按钮）
                safeEnableHan('edtRp','off'); safeEnableHan('edtRs','off');

                switch ftype
                    case {'低通','高通'}
                        % 低/高通使用 fp1
                        safeEnableHan('edtPb1','on'); safeEnableHan('sldPb1','on');
                        safeEnableHan('edtPb2','off'); safeEnableHan('sldPb2','off');
                        safeEnableHan('edtSb1','off'); safeEnableHan('sldSb1','off');
                        safeEnableHan('edtSb2','off'); safeEnableHan('sldSb2','off');
                        % 由于 maxflat 不能自动估阶（我们要求手工阶数>0），强制让 edtIIROrder 可编辑
                        safeEnableHan('edtIIROrder','on');
                    case '多带/高级'
                        % 允许多带/高级（但设计将需要打开 multi-band 参数窗口）
                        safeEnableHan('edtPb1','off'); safeEnableHan('sldPb1','off');
                        safeEnableHan('edtPb2','off'); safeEnableHan('sldPb2','off');
                        safeEnableHan('edtSb1','off'); safeEnableHan('sldSb1','off');
                        safeEnableHan('edtSb2','off'); safeEnableHan('sldSb2','off');
                        safeEnableHan('edtIIROrder','off');
                        % 多段使用专门对话框
                        try handles.btnMultiBand.Enable = 'on'; catch; end
                        setStatus(handles,'IIR-maxflat: 多带/高级 模式，请点击多带/高级滤波参数设置。');
                    otherwise
                        % 若用户意外选了其它类型（我们不支持），在外层处理会自动回退为低通
                        safeEnableHan('edtPb1','on'); safeEnableHan('sldPb1','on');
                end


            otherwise
                % 兜底策略：启用通带控件（保守），禁用阻带与 Rp/Rs（除非你希望默认打开）
                enable_pass_or_stop(ftype);
                safeEnableHan('edtRp','off'); safeEnableHan('edtRs','off');
                safeEnableHan('edtSb1','off'); safeEnableHan('sldSb1','off');
                safeEnableHan('edtSb2','off'); safeEnableHan('sldSb2','off');
        end
       

        % 确保阶数输入框保持可编辑
        handles.edtIIROrder.Enable = 'on';

        % 更新设计方法提示标签并同步状态栏
        updateDesignLabel(S, handles);
        % 更新备注/状态
        updateNote(S, handles);
    end


    %% ---- “FIR窗函数法”切换提示/状态回调 ----
    function onWindowChange(src,~)
        wndName = src.Value;
        % Kaiser窗时，用户自定义阶数时的beta根据Rp,Rs计算
        if strcmpi(wndName,'Kaiser')
            handles.edtRp.Enable = 'on'; handles.edtRs.Enable = 'on';
        else 
            handles.edtRp.Enable = 'off'; handles.edtRs.Enable = 'off';
        end

        if round(double(handles.edtFIROrder.Value)) <= 0 && ~strcmpi(handles.ddWindow.Value,'Kaiser')
            uialert_safe(fig_GUI, 'FIR窗函数法 - Rectwin/Triang/Hann/Hamming/Blackman不支持自动估阶，阶数已更改为默认值 64。请在 "FIR 阶数" 输入框中输入正整数。', '参数错误');
            setStatus(handles,'设计失败：Rectwin/Triang/Hann/Hamming/Blackman 需要正整数阶数'); 
                try
                    handles.edtFIROrder.Value = 64; % 默认 64
                catch
                end
        end

        % 窗函数类型变化时在onTypeChange实现相关控件的限制
        onTypeChange(handles.ddType);

        % 更新设计方法提示标签并同步状态栏
        updateDesignLabel(S, handles);

        updateNote(S, handles);
    end

    %% ---- "FIR优化设计法"切换提示/状态与控件启用/禁用回调 ----
    function onFIRMethodChange(src,~)
        method = src.Value;
    
        % 优化法下通常需要 fp/fst 与 Rp/Rs（允许用户指定阶数或设为 0 以自动估阶）
        switch method
            case 'Parks-McClellan'
                handles.ddWindow.Enable = 'off';
                handles.edtRp.Enable = 'on'; handles.edtRs.Enable = 'on';
                handles.edtSb1.Enable = 'on'; handles.sldSb1.Enable = 'on';
                % <-- 添加此行：在启用/切换 FIR 优化法 后重新应用"滤波类型"逻辑，
                % 以便根据当前（低通/高通/带通/带阻）禁用或启用 fst1/fst2。
                onTypeChange(handles.ddType);
                setStatus(handles,'FIR 优化法: Parks-McClellan（firpm）。');
            case 'Cplx-Parks-McClellan'
                % cfirpm：不使用 Rp/As（灰显）；阶数由用户输入决定（启用 edtFIROrder）
                handles.ddWindow.Enable = 'off';      % 窗函数项无关
                handles.edtFIROrder.Enable = 'on';    % 用户必须输入正整数阶数
                handles.edtRp.Enable = 'on'; handles.edtRs.Enable = 'on';
                % 启用通/阻带截止控件（与其它 FIR 优化法保持一致）
                handles.edtSb1.Enable = 'on'; handles.sldSb1.Enable = 'on';

                setStatus(handles,'FIR 优化法: Complex-Parks-McClellan（cfirpm）。');
                if round(double(handles.edtFIROrder.Value)) <= 0 && strcmpi(handles.ddFIRMethod.Value,'Cplx-Parks-McClellan')
                    uialert_safe(fig_GUI, 'FIR优化设计法 - Cplx-Parks-McClellan不支持自动估阶，阶数已更改为默认值 64。请在 "FIR 阶数" 输入框中输入正整数。', '参数错误');
                    setStatus(handles,'设计失败：Cplx-Parks-McClellan 需要正整数阶数'); 
                        try
                            handles.edtFIROrder.Value = 64; % 默认 64
                        catch
                        end
                end
                % 依据当前滤波类型启用/禁用 fp1/fp2/fst1/fst2（复用已有逻辑）
                onTypeChange(handles.ddType);

            case '最小二乘(firls)'
                handles.ddWindow.Enable = 'off';
                handles.edtRp.Enable = 'on'; handles.edtRs.Enable = 'on';
                handles.edtSb1.Enable = 'on'; handles.sldSb1.Enable = 'on';


                setStatus(handles,'FIR 优化法: 最小二乘 (firls)。');
                if round(double(handles.edtFIROrder.Value)) <= 0 && strcmpi(handles.ddFIRMethod.Value,'最小二乘(firls)')
                    uialert_safe(fig_GUI, 'FIR优化设计法 - 最小二乘(firls)不支持自动估阶，阶数已更改为默认值 64。请在 "FIR 阶数" 输入框中输入正整数。', '参数错误');
                    setStatus(handles,'设计失败：最小二乘(firls) 需要正整数阶数'); 
                        try
                            handles.edtFIROrder.Value = 64; % 默认 64
                        catch
                        end
                end
                % <-- 添加此行：在启用/切换 FIR 优化法 后重新应用"滤波类型"逻辑，
                % 以便根据当前（低通/高通/带通/带阻）禁用或启用 fst1/fst2。
                onTypeChange(handles.ddType);

            case '约束最小二乘(fircls)'
                handles.ddWindow.Enable = 'off';
                handles.edtRp.Enable = 'on'; handles.edtRs.Enable = 'on';
                handles.edtSb1.Enable = 'on'; handles.sldSb1.Enable = 'on';

                setStatus(handles,'FIR 优化法: 约束最小二乘 (fircls)。');
                if round(double(handles.edtFIROrder.Value)) <= 0 && strcmpi(handles.ddFIRMethod.Value,'约束最小二乘(fircls)')
                    uialert_safe(fig_GUI, 'FIR优化设计法 - 约束最小二乘(fircls)不支持自动估阶，阶数已更改为默认值 64。请在 "FIR 阶数" 输入框中输入正整数。', '参数错误');
                    setStatus(handles,'设计失败：约束最小二乘(fircls) 需要正整数阶数'); 
                        try
                            handles.edtFIROrder.Value = 64; % 默认 64
                        catch
                        end
                end

                % <-- 添加此行：在启用/切换 FIR 优化法 后重新应用"滤波类型"逻辑，
                % 以便根据当前（低通/高通/带通/带阻）禁用或启用 fst1/fst2。
                onTypeChange(handles.ddType);
           
            case '约束最小二乘1(fircls1)'
                % fircls1 特殊逻辑：直接切换为 多带/高级 并启用多带按钮；禁用单段频率与 Rp/Rs
                handles.ddWindow.Enable = 'off';
                handles.edtFIROrder.Enable = 'on';    % 阶数使用用户输入（不能自动估阶）
                % 强制把 滤波类型 切为 多带/高级，并启用多带按钮
                try
                    handles.ddType.Value = '多带/高级';
                catch
                end
                safeEnableHan('btnMultiBand','on');  % 使用已有 safeEnableHan/启用逻辑（或直接 handles.btnMultiBand.Enable='on'）
                % 禁用通/阻带规格控件
                handles.edtRp.Enable = 'off'; handles.edtRs.Enable = 'off';
                safeEnableHan('edtPb1','off'); safeEnableHan('sldPb1','off');
                safeEnableHan('edtPb2','off'); safeEnableHan('sldPb2','off');
                safeEnableHan('edtSb1','off'); safeEnableHan('sldSb1','off');
                safeEnableHan('edtSb2','off'); safeEnableHan('sldSb2','off');
            
                setStatus(handles,'FIR 优化法: 约束最小二乘1 (fircls1)。');
                % 阶数必须 > 0
                if round(double(handles.edtFIROrder.Value)) <= 0 && strcmpi(handles.ddFIRMethod.Value,'约束最小二乘1(fircls1)')
                    uialert_safe(fig_GUI, 'FIR优化设计法 - 约束最小二乘1(fircls1)不支持自动估阶，阶数已更改为默认值 64。请在 "FIR 阶数" 输入框中输入正整数。', '参数错误');
                    try handles.edtFIROrder.Value = 64; catch; end
                end
            
                % 不做 onTypeChange，因为我们已把类型设置为 多带/高级（但还是调用以统一界面）
                try onTypeChange(handles.ddType); catch; end

            otherwise
                % 默认启用基本频率输入
                handles.edtRp.Enable = 'on'; handles.edtRs.Enable = 'on';
                handles.edtSb1.Enable = 'on'; handles.sldSb1.Enable = 'on';
                handles.edtSb2.Enable = 'on'; handles.sldSb2.Enable = 'on';
                setStatus(handles,'FIR 优化法已选择（未知子方法）。');
        end
        % 更新设计方法提示标签并同步状态栏
        updateDesignLabel(S, handles);
        updateNote(S, handles);

    end


    %% ---- 滤波器“阶数”（IIR/FIR阶数）变化回调 ----
    function onOrderChange(src, ~)
        % 获取当前设计方法
        method = handles.ddDesignMethod.Value;
        
        % 获取阶数值
        orderValue = src.Value;
        
        % 获取FIR窗函数类型
        wndName = handles.ddWindow.Value;

        if strcmpi(method, 'IIR')
            proto = handles.ddIIRProto.Value;
            % 如果自动估阶（<=0），确保 Rp/Rs/fp/fst 全都可编辑
            if orderValue <= 0
                handles.edtRp.Enable = 'on'; handles.edtRs.Enable = 'on';
                handles.edtPb1.Enable = 'on'; handles.sldPb1.Enable = 'on';
                handles.edtPb2.Enable = 'on'; handles.sldPb2.Enable = 'on';
                handles.edtSb1.Enable = 'on'; handles.sldSb1.Enable = 'on';
                handles.edtSb2.Enable = 'on'; handles.sldSb2.Enable = 'on';
                ftype = handles.ddType.Value;
                switch ftype
                    case {'低通','高通'}
                        handles.edtPb2.Enable = 'off'; handles.sldPb2.Enable = 'off';
                        handles.edtSb2.Enable = 'off'; handles.sldSb2.Enable = 'off';
                    otherwise
                        handles.edtPb2.Enable = 'on'; handles.sldPb2.Enable = 'on';
                        handles.edtSb2.Enable = 'on'; handles.sldSb2.Enable = 'on';
                end

                if any(strcmpi(proto,{'yule-walker','yulewalk','yule-walker '}))
                  handles.edtRp.Enable = 'off'; handles.edtRs.Enable = 'off';
                  % 这里用安全弹窗提示并强制用户修改阶数（或设置一个默认）
                    try
                        uialert_safe(fig_GUI, ...
                           'IIR - Yule-Walker (yulewalk) 不支持自动估阶，阶数已更改为默认值 4。请在 "IIR 阶数" 输入框中输入正整数阶数。', ...
                           '参数错误');
                    catch
                        uialert(fig_GUI, ...
                           'IIR - Yule-Walker (yulewalk) 不支持自动估阶，阶数已更改为默认值 4。。请在 "IIR 阶数" 输入框中输入正整数阶数。', ...
                           '参数错误');
                    end
                    
                    try
                        handles.edtIIROrder.Value = max(1, round(4)); % 默认 4
                        applyIIRProtoEnables(S, handles, fig_GUI, proto, handles.ddType.Value);
                    catch
                    end
                end

                 % 强制 maxflat 阶数 > 0
                try
                    if strcmpi(handles.ddDesignMethod.Value,'IIR') && isprop(handles,'ddIIRProto') && strcmpi(handles.ddIIRProto.Value,'maxflat')
                        if round(double(handles.edtIIROrder.Value)) <= 0
                            if exist('uialert_safe','file')
                                uialert_safe(fig_GUI,'maxflat 不支持自动估阶。阶数已更改为默认值 4。请在 "IIR 阶数" 输入框中输入正整数阶数。','参数错误')
                            else 
                                uialert(fig_GUI,'maxflat 不支持自动估阶。阶数已更改为默认值 4。请在 "IIR 阶数" 输入框中输入正整数阶数。','参数错误')
                            end
                            handles.edtIIROrder.Value = 4;
                            applyIIRProtoEnables(S, handles, fig_GUI, proto, handles.ddType.Value);
                        end
                    end
                catch
                end

                % 更新设计方法提示标签并同步状态栏
                updateDesignLabel(S, handles);
            else
                % 用户自定义阶数：走按原型的控件启用规则
                applyIIRProtoEnables(S, handles, fig_GUI, proto, handles.ddType.Value);
                setStatus(handles,sprintf('IIR %s: 自定义阶数设置为 %d', proto, orderValue));
            end
        
        elseif strcmpi(method, 'FIR窗函数法')
            % 对于 FIR 窗函数法：若用户给了正阶数（>0），则 Rp/Rs/阻带边界通常无用，可以灰显；
            % 若阶数 <=0（自动估阶），则需要 Rp/Rs/fp/fst 等输入可编辑（以便自动估阶，比如 Kaiser）
            if orderValue > 0
                % 用户指定阶数：禁用与误差规格相关的控件（保留截止频率 fp 必需项）
                handles.edtRp.Enable = 'off'; handles.edtRs.Enable = 'off';
                % 阻带边界由 window 法通常不需要：禁用
                handles.edtSb1.Enable = 'off'; handles.sldSb1.Enable = 'off';
                handles.edtSb2.Enable = 'off'; handles.sldSb2.Enable = 'off';

                % Kaiser窗时，用户自定义阶数时的beta根据Rp,Rs计算
                
                if strcmpi(wndName,'Kaiser')
                    handles.edtRp.Enable = 'on'; handles.edtRs.Enable = 'on';
                else 
                    handles.edtRp.Enable = 'off'; handles.edtRs.Enable = 'off';
                end

                % 阶数变化时在onTypeChange实现相关控件的限制
                onTypeChange(handles.ddType);

                % 更新设计方法提示标签并同步状态栏
                updateDesignLabel(S, handles);
               
            elseif orderValue <= 0 && strcmpi(wndName,'Kaiser')
                % 自动估阶（需要 Rp/Rs/截止频率）
                handles.edtRp.Enable = 'on'; handles.edtRs.Enable = 'on';
                handles.edtSb1.Enable = 'on'; handles.sldSb1.Enable = 'on';
                handles.edtSb2.Enable = 'on'; handles.sldSb2.Enable = 'on';
                
                % 阶数变化时在onTypeChange实现相关控件的限制
                onTypeChange(handles.ddType);
               
                % 更新设计方法提示标签并同步状态栏
                updateDesignLabel(S, handles);

            elseif orderValue <= 0 && ~strcmpi(wndName,'Kaiser')

                % 用户指定阶数：禁用与误差规格相关的控件（保留截止频率 fp 必需项）
                handles.edtRp.Enable = 'off'; handles.edtRs.Enable = 'off';
                % 阻带边界由 window 法通常不需要：禁用
                handles.edtSb1.Enable = 'off'; handles.sldSb1.Enable = 'off';
                handles.edtSb2.Enable = 'off'; handles.sldSb2.Enable = 'off';
                handles.edtRp.Enable = 'off'; handles.edtRs.Enable = 'off';


                if orderValue <= 0 && ~strcmpi(wndName,'Kaiser')
                    uialert_safe(fig_GUI, 'FIR窗函数法 - Rectwin/Triang/Hann/Hamming/Blackman不支持自动估阶，阶数已更改为默认值 64。请在 "FIR 阶数" 输入框中输入正整数。', '参数错误');
                    setStatus(handles,'设计失败：Rectwin/Triang/Hann/Hamming/Blackman 需要正整数阶数'); 
                        try
                            handles.edtFIROrder.Value = 64; % 默认 64
                        catch
                        end
                end

                % 阶数变化时在onTypeChange实现相关控件的限制
                onTypeChange(handles.ddType);
                % 更新设计方法提示标签并同步状态栏
                updateDesignLabel(S, handles);

            end

        elseif strcmpi(method, 'FIR优化设计法')
            if orderValue <= 0 && strcmpi(handles.ddFIRMethod.Value,'Cplx-Parks-McClellan')
                uialert_safe(fig_GUI, 'FIR优化设计法 - Cplx-Parks-McClellan不支持自动估阶，阶数已更改为默认值 64。请在 "FIR 阶数" 输入框中输入正整数。', '参数错误');
                setStatus(handles,'设计失败：Cplx-Parks-McClellan 需要正整数阶数'); 
                    try
                        handles.edtFIROrder.Value = 64; % 默认 64
                    catch
                    end
            end
            if orderValue <= 0 && strcmpi(handles.ddFIRMethod.Value,'最小二乘(firls)')
                uialert_safe(fig_GUI, 'FIR优化设计法 - 最小二乘(firls)不支持自动估阶，阶数已更改为默认值 64。请在 "FIR 阶数" 输入框中输入正整数。', '参数错误');
                setStatus(handles,'设计失败：最小二乘(firls) 需要正整数阶数'); 
                    try
                        handles.edtFIROrder.Value = 64; % 默认 64
                    catch
                    end
            end
            if orderValue <= 0 && strcmpi(handles.ddFIRMethod.Value,'约束最小二乘(fircls)')
                uialert_safe(fig_GUI, 'FIR优化设计法 - 约束最小二乘(fircls)不支持自动估阶，阶数已更改为默认值 64。请在 "FIR 阶数" 输入框中输入正整数。', '参数错误');
                setStatus(handles,'设计失败：约束最小二乘(fircls) 需要正整数阶数'); 
                    try
                        handles.edtFIROrder.Value = 64; % 默认 64
                    catch
                    end
            end
            if orderValue <= 0 && strcmpi(handles.ddFIRMethod.Value,'约束最小二乘1(fircls1)')
                uialert_safe(fig_GUI, 'FIR优化设计法 - 约束最小二乘1(fircls1)不支持自动估阶，阶数已更改为默认值 64。请在 "FIR 阶数" 输入框中输入正整数。', '参数错误');
                setStatus(handles,'设计失败：约束最小二乘1(fircls1) 需要正整数阶数');
                try handles.edtFIROrder.Value = 64; catch; end
            end



            % 更新设计方法提示标签并同步状态栏
            updateDesignLabel(S, handles);

        elseif strcmpi(method, 'FIR频率采样法')
            if orderValue <= 0 
                uialert_safe(fig_GUI, 'FIR频率采样法 不支持自动估阶，阶数已更改为默认值 64。请在 "FIR 阶数" 输入框中输入正整数。', '参数错误');
                setStatus(handles,'设计失败：FIR频率采样法 需要正整数阶数'); 
                    try
                        handles.edtFIROrder.Value = 64; % 默认 64
                    catch
                    end
            end
            % 更新设计方法提示标签并同步状态栏
            updateDesignLabel(S, handles);
        end
        
        % 更新备注
        updateNote(S, handles);
    end

    %% ---- “滤波类型”切换（低通、高通、带通、带阻、多带/高级）回调 ----
    function onTypeChange(src,~)
        % onTypeChange：根据滤波类型启用/禁用控件，并在必要时自动修正频率顺序
        method = handles.ddDesignMethod.Value;
        ftype = src.Value;
        nyq = max(1e-6, S.fs/2);
        minGapHz = 1e-6; % 最小安全间隔（Hz），可按需调整
    
        % 读取阶数（关键改动：在判定控件启用时考虑阶数）
        % iirOrder = getSafe('edtIIROrder', 0);   % IIR 阶数输入框的当前值
        firOrder = getSafeHanVal('edtFIROrder', 0);   % FIR 阶数输入框的当前值
         
        % 获取FIR窗函数类型
        wndName = handles.ddWindow.Value;

        % 记录调整信息
        adjustedParams = {};
        oldValues = [];
        newValues = [];
    
    
        % 如果当前 IIR 原型为 maxflat，限制类型
        try
            if strcmpi(handles.ddDesignMethod.Value,'IIR') && isprop(handles,'ddIIRProto') && strcmpi(handles.ddIIRProto.Value,'maxflat')
                if isprop(handles,'ddType') && strcmp(handles.ddType.Value,'多带/高级')
                    handles.edtIIROrder.Enable = 'off';
                else
                    % 其它情况恢复为由原逻辑决定（如果要强制启用则设 'on'）
                    handles.edtIIROrder.Enable = 'on';
                end

                allowed = {'低通','高通','多带/高级'};
                newType = src.Value;
                if ~any(strcmp(newType, allowed))
                    % 弹窗提示并自动切换为低通
                    try
                        uialert_safe(fig_GUI, '当前 IIR 原型为 maxflat，仅支持 低通 / 高通 / 多带/高级。已自动切换为 低通。', '不支持的滤波类型');
                    catch
                        uialert(fig_GUI, '当前 IIR 原型为 maxflat，仅支持 低通 / 高通 / 多带/高级。已自动切换为 低通。', '不支持的滤波类型');
                    end
                    try handles.ddType.Value = '低通'; catch; end
                    % 由于我们修改了 ddType.Value，递归 onTypeChange 会被触发，但那是期望的行为
                    return;
                end
            end
        catch
            % 安全兜底，不影响其它逻辑
        end

        % 当 handles.ddDesignMethod.Value 为 'FIRintfilt插值' 且 ddType.Value 不是 '多带/高级'，弹窗提醒并恢复
        try
            if isprop(handles,'ddDesignMethod') && strcmp(handles.ddDesignMethod.Value,'FIRintfilt插值') && ~strcmp(src.Value,'多带/高级')
                if exist('uialert_safe','file')
                    uialert_safe(fig_GUI, 'FIRintfilt插值 需要通过"多带 / 高级滤波参数"按钮设置参数', '操作受限');
                else
                    uialert(fig_GUI, 'FIRintfilt插值 需要通过"多带 / 高级滤波参数"按钮设置参数', '操作受限');
                end
                % 强制回滚为 多带/高级
                try handles.ddType.Value = '多带/高级'; catch; end
                safeEnableHan('btnMultiBand','on');
                return;
            end
        catch
            % 忽略错误，保持鲁棒
        end

        % 如果当前设计方法为 FIRgaussdesign 脉冲整形，则强制保持 多带/高级
        try
            if isprop(handles,'ddDesignMethod') && strcmpi(handles.ddDesignMethod.Value, 'FIRgaussdesign脉冲整形') && ~strcmp(handles.ddType.Value, '多带/高级')
                if exist('uialert_safe','file')
                    uialert_safe(fig_GUI, 'FIRgaussdesign脉冲整形 需要通过"多带 / 高级滤波参数"按钮设置参数。已自动切回 多带/高级。', '操作受限');
                else
                    uialert(fig_GUI, 'FIRgaussdesign脉冲整形 需要通过"多带 / 高级滤波参数"按钮设置参数。已自动切回 多带/高级。', '操作受限');
                end
                try handles.ddType.Value = '多带/高级'; catch; end
                safeEnableHan('btnMultiBand','on');
                return;
            end
        catch
            % 忽略异常
        end

        % 如果当前设计方法为 FIRrcosdesign脉冲整形，则强制保持 多带/高级
        try 
            if isprop(handles,'ddDesignMethod') && strcmpi(handles.ddDesignMethod.Value,'FIRrcosdesign脉冲整形') && ~strcmp(handles.ddType.Value, '多带/高级')
                % 只有多带/高级被允许
                % 仅当用户在 rcos 设计模式下手动切换才弹窗
                if exist('uialert_safe','file')
                    uialert_safe(fig_GUI,'FIRrcosdesign脉冲整形需要通过"多带 / 高级滤波参数"按钮设置参数，已自动切回为 "多带/高级".','操作受限');
                else
                    uialert(fig_GUI,'FIRrcosdesign脉冲整形需要通过"多带 / 高级滤波参数"按钮设置参数，已自动切回为 "多带/高级".','操作受限');
                end
                try handles.ddType.Value = '多带/高级'; catch; end
                safeEnableHan('btnMultiBand','on');
                return; % 终止后续 onTypeChange 中对非多带的设置
            end
        catch
            % 忽略异常
        end

        % 特殊保护：如果当前设计方法是 Savitzky-Golay，则强制类型为 '多带/高级'
        try
            if isprop(handles,'ddDesignMethod') && strcmp(handles.ddDesignMethod.Value,'Savitzky-Golay')
                if ~strcmp(src.Value,'多带/高级')
                    % 只在当前设计方法为 Savitzky-Golay 且用户切换为 非多带/高级 时弹窗并恢复
                    if exist('uialert_safe','file')
                        uialert_safe(fig_GUI, 'Savitzky-Golay 需要通过"多带 / 高级滤波参数"按钮设置参数。已自动切回 多带/高级。', '参数约束');
                    else
                        uialert(fig_GUI, 'Savitzky-Golay 需要通过"多带 / 高级滤波参数"按钮设置参数。已自动切回 多带/高级。', '参数约束');
                    end
                    handles.ddType.Value = '多带/高级';
                    safeEnableHan('btnMultiBand','on'); % 确保按钮可用
                    return;
                end
            end
        catch
        end

        % 如果当前 FIR 子方法为 fircls1，则强制保持 多带/高级，禁止切换为其它类型
        try
            if strcmpi(handles.ddDesignMethod.Value, 'FIR优化设计法') && isprop(handles,'ddFIRMethod') && strcmpi(handles.ddFIRMethod.Value,'约束最小二乘1(fircls1)') ...
                    && ~strcmp(handles.ddType.Value, '多带/高级')
                % 只有在当前子方法为 fircls1 并且用户试图切换出 多带/高级 时才弹窗
                if exist('uialert_safe','file')
                    uialert_safe(fig_GUI, '约束最小二乘1(fircls1)需要通过"多带 / 高级滤波参数"按钮设置参数', '操作受限');
                else
                    uialert(fig_GUI, '约束最小二乘1(fircls1)需要通过"多带 / 高级滤波参数"按钮设置参数', '操作受限');
                end
                % 强制回滚选择为 多带/高级
                try handles.ddType.Value = '多带/高级'; catch; end
                return;
            end
        catch
            % 忽略任何意外（保持鲁棒）
        end

        % ==== 多带/高级支持逻辑 ====
        if strcmp(ftype, '多带/高级')
            allowMulti = false;
            if strcmpi(handles.ddDesignMethod.Value,'FIR优化设计法') || strcmpi(handles.ddDesignMethod.Value,'FIR频率采样法')
                allowMulti = true;
            end
            if strcmpi(handles.ddDesignMethod.Value,'IIR') && isprop(handles,'ddIIRProto') && strcmpi(handles.ddIIRProto.Value,'Yule-Walker')
                allowMulti = true;
            end
            if strcmpi(handles.ddDesignMethod.Value,'IIR') && isprop(handles,'ddIIRProto') && strcmpi(handles.ddIIRProto.Value,'maxflat')
                allowMulti = true;
            end

            % 如果当前设计方法不是 FIR 优化设计法或FIR频率采样法 或 IIR Yule-Walker -> 弹窗并回退为 低通（避免无限弹窗）
            if ~allowMulti
                try
                    if exist('uialert_safe','file')
                        uialert_safe(fig_GUI,'多带/高级仅在 FIR 优化法、FIR 频率采样法、IIR-Yule-Walker、IIR-maxflat、FIRintfilt插值、FIRgaussdesign脉冲整形、FIRrcosdesign脉冲整形、Savitzky-Golay 下支持。已自动切回为 "低通"。','不支持的操作');
                    else
                        uialert(fig_GUI,'多带/高级仅在 FIR 优化法、FIR 频率采样法、IIR-Yule-Walker、IIR-maxflat、FIRintfilt插值、FIRgaussdesign脉冲整形、FIRrcosdesign脉冲整形、Savitzky-Golay 下支持。已自动切回为 "低通"。','不支持的操作');
                    end
                catch
                end
                % 回退选择，直接修改控件值（避免再次触发无限弹窗）
                try src.Value = '低通'; catch; end
                % 禁用多带/高级按钮
                safeEnableHan('btnMultiBand','off');
                % ensure frequency controls 恢复为普通逻辑，直接 return 让原逻辑后续处理
                try handles.ddType.Value = '低通'; catch; end
                ftype = '低通';
                % 更新设计方法提示标签并同步状态栏
                updateDesignLabel(S, handles);  
            else
                % 当前为 FIR 优化法 或 FIR频率采样法 或 IIR Yule-Walker且 选择 多带/高级：启用 多带/高级 按钮，并禁用单段频率输入控件
                safeEnableHan('btnMultiBand','on');
                handles.edtRp.Enable = 'off'; handles.edtRs.Enable = 'off';
                safeEnableHan('edtPb1','off'); safeEnableHan('sldPb1','off');
                safeEnableHan('edtPb2','off'); safeEnableHan('sldPb2','off');
                safeEnableHan('edtSb1','off'); safeEnableHan('sldSb1','off');
                safeEnableHan('edtSb2','off'); safeEnableHan('sldSb2','off');
                % 更新状态并返回（无需原有单段频率修正逻辑）
                setStatus(handles,'已选择多带/高级（多段）模式，请点击"多带/高级滤波参数"设置具体带参数。');
                updateNote(S, handles);
                % 更新设计方法提示标签并同步状态栏
                updateDesignLabel(S, handles);  
                return;
            end
        else
            % 如果不是多带/高级，确保多带/高级按钮禁用（防止残留）
            safeEnableHan('btnMultiBand','off');

        end


        % 读取当前 values（安全读取）
        fp1 = getSafeHanVal('edtPb1', NaN); fp2 = getSafeHanVal('edtPb2', NaN);
        fst1 = getSafeHanVal('edtSb1', NaN); fst2 = getSafeHanVal('edtSb2', NaN);
    
        % ----------------------------
        % 关键逻辑说明（实现要点）：
        % - 任何时候都首先尊重"是否自动估阶"的设置：
        %     * IIR: if iirOrder <= 0 -> 自动估阶，Rp/Rs 和 所有截止频率应可编辑（ord 需要）
        %     * IIR: if iirOrder  > 0 -> 用户自定义阶数，按原型（applyIIRProtoEnables）决定 Rp/Rs 是否灰显
        %     * FIR: if firOrder <= 0 -> 自动估阶，Rp/Rs 和截止频率都可编辑
        %     * FIR: if firOrder  > 0 -> 手动阶数，窗函数法通常禁用 Rp/Rs
        % - 在此基础上再按具体 ftype（低/高/带/带阻）来启/禁左右通带、阻带控件；
        % - 只在自动估阶模式下强制启用 Rp/Rs，避免切换类型时被原型逻辑意外禁用（这是之前 bug 的根源）
        % ----------------------------
    
        % 依据类型设置 enable 状态（保持原逻辑但更明确）
        switch ftype
            case {'低通','高通'}
                % 左侧有效，右侧禁用
                safeEnableHan('edtPb2','off'); safeEnableHan('sldPb2','off');
                safeEnableHan('edtSb2','off'); safeEnableHan('sldSb2','off');
    
                % ---------- IIR 分支 ----------
                if strcmpi(method, 'IIR')
                    try proto = handles.ddIIRProto.Value; catch ; proto = ''; end
                    % applyIIRProtoEnables 已处理，所以applyIIRProtoEnables(proto, ftype);后面注释掉了
                    applyIIRProtoEnables(S, handles, fig_GUI, proto, ftype);
                    % if iirOrder <= 0
                    %     % 自动估阶：确保 Rp/Rs/（以及当前类型所需的频率）可编辑
                    %     handles.edtRp.Enable = 'on'; handles.edtRs.Enable = 'on';
                    %     % 对低/高通，阻带 sb1 都应可编辑（ord 需要）
                    %     safeEnableHan('edtSb1','on'); safeEnableHan('sldSb1','on');
                    %     setStatus(handles,'IIR: 自动估阶模式，规格全部可编辑。');
                    % else
                    %     % 用户手工阶数：委托 applyIIRProtoEnables 来按 proto 做灰显（保持原有行为）
                    %     applyIIRProtoEnables(S, handles, fig_GUI, proto, ftype);
                    %     setStatus(handles,sprintf('IIR: 自定义阶数 %d，按原型 %s 设置控件。', iirOrder, proto));
                    %     % applyIIRProtoEnables 已处理 edtSb1 的启用/禁用，此处不重复覆盖
                    % end
    
                % ---------- FIR 窗函数法 ----------
                elseif strcmpi(method, 'FIR窗函数法')
                    if firOrder <= 0 && strcmpi(wndName,'Kaiser')
                        % 自动估阶：需要 Rp/Rs（用于估算）以及 sb1 可编辑（即不要灰显）
                        handles.edtRp.Enable = 'on'; handles.edtRs.Enable = 'on';
                        safeEnableHan('edtPb1','on'); safeEnableHan('sldPb1','on');
                        safeEnableHan('edtSb1','on'); safeEnableHan('sldSb1','on');

                        setStatus(handles,'FIR 窗函数法：自动估阶，规格可编辑。');
                    else
                        % 手动阶数：窗口法通常不需要 Rp/Rs；禁用阻带 sb1
                        handles.edtRp.Enable = 'off'; handles.edtRs.Enable = 'off';
                        safeEnableHan('edtPb1','on'); safeEnableHan('sldPb1','on');
                        safeEnableHan('edtPb2','off'); safeEnableHan('sldPb2','off');
                        safeEnableHan('edtSb1','off'); safeEnableHan('sldSb1','off');
                        safeEnableHan('edtSb2','off'); safeEnableHan('sldSb2','off');

                        % Kaiser窗时，用户自定义阶数时的beta根据Rp,Rs计算

                        if strcmpi(wndName,'Kaiser')
                            handles.edtRp.Enable = 'on'; handles.edtRs.Enable = 'on';
                        else 
                            handles.edtRp.Enable = 'off'; handles.edtRs.Enable = 'off';
                        end

                        setStatus(handles,sprintf('FIR 窗函数法：自定义阶数 %d。', firOrder));
                    end

    
                % ---------- FIR 优化设计法 ----------
                elseif strcmpi(method, 'FIR优化设计法')
                    % 优化法通常需要 sb1 作为规格（即启用）
                    if firOrder <= 0
                        handles.edtRp.Enable = 'on'; handles.edtRs.Enable = 'on';
                        safeEnableHan('edtPb1','on'); safeEnableHan('sldPb1','on');
                        safeEnableHan('edtSb1','on'); safeEnableHan('sldSb1','on');
                        setStatus(handles,'FIR 优化设计法：自动估阶，规格可编辑。');
                    else
                        handles.edtRp.Enable = 'on'; handles.edtRs.Enable = 'on';
                        safeEnableHan('edtPb1','on'); safeEnableHan('sldPb1','on');
                        safeEnableHan('edtSb1','on'); safeEnableHan('sldSb1','on');
                        setStatus(handles,sprintf('FIR 优化设计法：自定义阶数 %d。', firOrder));
                    end

                % ---------- FIR 频率采样法 ----------
                elseif strcmpi(method, 'FIR频率采样法')
                    handles.edtRp.Enable = 'off'; handles.edtRs.Enable = 'off';
                    safeEnableHan('edtPb1','on'); safeEnableHan('sldPb1','on');
                    safeEnableHan('edtSb1','on'); safeEnableHan('sldSb1','on');
                    setStatus(handles,sprintf('FIR 频率采样法：自定义阶数 %d。', firOrder));
                    
    
                else
                    % 兜底：让 sb1 可编辑，Rp/Rs 保持可编辑以便用户修正
                    handles.edtRp.Enable = 'on'; handles.edtRs.Enable = 'on';
                    safeEnableHan('edtSb1','on'); safeEnableHan('sldSb1','on');
                end
    
            case {'带通', '带阻'}
                % 需要左右两侧的通带截止（pb2）并根据设计方法启用/禁用阻带边界
                safeEnableHan('edtPb2','on'); safeEnableHan('sldPb2','on');
                
                % ---------- IIR 分支 ----------    
                if strcmpi(method, 'IIR')
                    try proto = handles.ddIIRProto.Value; catch ; proto = ''; end
                    % applyIIRProtoEnables 已处理
                    applyIIRProtoEnables(S, handles, fig_GUI, proto, ftype);
                    % if iirOrder <= 0
                    %     % 自动估阶：Rp/Rs 与左右阻带边界都可编辑（ord 需要）
                    %     handles.edtRp.Enable = 'on'; handles.edtRs.Enable = 'on';
                    %     safeEnableHan('edtSb1','on'); safeEnableHan('sldSb1','on');
                    %     safeEnableHan('edtSb2','on'); safeEnableHan('sldSb2','on');
                    %     setStatus(handles,'IIR: 自动估阶模式（带通/带阻），规格全部可编辑。');
                    % else
                    %     % 用户手工阶数：交由 applyIIRProtoEnables 决定（保持原有基于 proto 的规则）
                    %     applyIIRProtoEnables(S, handles, fig_GUI, proto, ftype);
                    %     setStatus(handles,sprintf('IIR: 自定义阶数 %d，按原型 %s 设置控件。', iirOrder, proto));
                    % end

                % ---------- FIR 窗函数法 ----------
                elseif strcmpi(method, 'FIR窗函数法')
                    if firOrder <= 0 && strcmpi(wndName,'Kaiser')
                        % 自动估阶：启用阻带规格以便某些窗/估算使用
                        handles.edtRp.Enable = 'on'; handles.edtRs.Enable = 'on';
                        safeEnableHan('edtPb1','on'); safeEnableHan('sldPb1','on');
                        safeEnableHan('edtSb1','on'); safeEnableHan('sldSb1','on');
                        safeEnableHan('edtSb2','on'); safeEnableHan('sldSb2','on');
                        setStatus(handles,'FIR 窗函数法：自动估阶（带通/带阻），规格可编辑。');
                    else
                        % 手动阶数：窗口法通常不使用阻带规格 -> 禁用
                        handles.edtRp.Enable = 'off'; handles.edtRs.Enable = 'off';
                        safeEnableHan('edtPb1','on'); safeEnableHan('sldPb1','on');
                        safeEnableHan('edtPb2','on'); safeEnableHan('sldPb2','on');
                        safeEnableHan('edtSb1','off'); safeEnableHan('sldSb1','off');
                        safeEnableHan('edtSb2','off'); safeEnableHan('sldSb2','off');

                        % Kaiser窗时，用户自定义阶数时的beta根据Rp,Rs计算
                        wndName = handles.ddWindow.Value;
                        if strcmpi(wndName,'Kaiser')
                            handles.edtRp.Enable = 'on'; handles.edtRs.Enable = 'on';
                        else 
                            handles.edtRp.Enable = 'off'; handles.edtRs.Enable = 'off';
                        end

                        setStatus(handles,sprintf('FIR 窗函数法：自定义阶数 %d。', firOrder));
                    end
                    
                % ---------- FIR 优化设计法 ----------
                elseif strcmpi(method, 'FIR优化设计法')
                    % 优化法：一般需要 fst1/fst2 -> 启用
                    handles.edtRp.Enable = 'on'; handles.edtRs.Enable = 'on';
                    safeEnableHan('edtPb1','on'); safeEnableHan('sldPb1','on');
                    safeEnableHan('edtPb2','on'); safeEnableHan('sldPb2','on');
                    safeEnableHan('edtSb1','on'); safeEnableHan('sldSb1','on');
                    safeEnableHan('edtSb2','on'); safeEnableHan('sldSb2','on');
                    setStatus(handles,'FIR 优化设计法：带通/带阻，启用阻带规格。');

                % ---------- FIR 频率采样法 ----------
                elseif strcmpi(method, 'FIR频率采样法')
                    handles.edtRp.Enable = 'off'; handles.edtRs.Enable = 'off';
                    safeEnableHan('edtPb1','on'); safeEnableHan('sldPb1','on');
                    safeEnableHan('edtPb2','on'); safeEnableHan('sldPb2','on');
                    safeEnableHan('edtSb1','on'); safeEnableHan('sldSb1','on');
                    safeEnableHan('edtSb2','on'); safeEnableHan('sldSb2','on');
                    setStatus(handles,'FIR 频率采样法：带通/带阻，启用阻带规格。');

                else
                    % 兜底
                    handles.edtRp.Enable = 'on'; handles.edtRs.Enable = 'on';
                    safeEnableHan('edtSb1','on'); safeEnableHan('sldSb1','on');
                    safeEnableHan('edtSb2','on'); safeEnableHan('sldSb2','on');
                end
    
            otherwise
                % 其它情况：禁用右侧及阻带边界（保守策略）
                safeEnableHan('edtPb2','off'); safeEnableHan('sldPb2','off');
                safeEnableHan('edtSb1','off'); safeEnableHan('sldSb1','off');
                safeEnableHan('edtSb2','off'); safeEnableHan('sldSb2','off');
        end
    
        % ----------------------------
        % 频率顺序与自动修正（与原逻辑一致，保留您原来的最小改动策略）
        % ----------------------------
        % 读取最新（可能被 UI 其它回调修改过）
        fp1 = getSafeHanVal('edtPb1', fp1); fp2 = getSafeHanVal('edtPb2', fp2);
        fst1 = getSafeHanVal('edtSb1', fst1); fst2 = getSafeHanVal('edtSb2', fst2);
    
        % clamp 到 [1e-6, nyq]
        fp1 = clampHz(fp1, nyq);
        fp2 = clampHz(fp2, nyq);
        fst1 = clampHz(fst1, nyq);
        fst2 = clampHz(fst2, nyq);
    
        switch ftype
            case '低通'
                % 需要： 0 < fp1 < fst1 < Nyq  (阻带在高频一侧)
                if fp1 >= fst1 - minGapHz
                    adjustedParams{end+1} = '阻带截止 fst1';
                    oldValues(end+1) = fst1;
                    fst1 = min(fp1 + minGapHz, nyq);
                    newValues(end+1) = fst1;
                    safeSetValPair('edtSb1','sldSb1',fst1);
                end
    
            case '高通'
                % 需要： 0 < fst1 < fp1 < Nyq  (阻带在低频一侧)
                if fst1 >= fp1 - minGapHz
                    adjustedParams{end+1} = '阻带截止 fst1';
                    oldValues(end+1) = fst1;
                    fst1 = max(fp1 - minGapHz, 1e-6);
                    newValues(end+1) = fst1;
                    safeSetValPair('edtSb1','sldSb1',fst1);
                end
    
            case '带通'
                % 需要： 0 < fst1 < fp1 < fp2 < fst2 < Nyq
                if fp1 >= fp2 - minGapHz
                    adjustedParams{end+1} = '通带截止 fp2';
                    oldValues(end+1) = fp2;
                    fp2 = min(fp1 + minGapHz, nyq);
                    newValues(end+1) = fp2;
                    safeSetValPair('edtPb2','sldPb2',fp2);
                end
                if fst1 >= fp1 - minGapHz
                    adjustedParams{end+1} = '阻带截止 fst1';
                    oldValues(end+1) = fst1;
                    fst1 = max(fp1 - minGapHz, 1e-6);
                    newValues(end+1) = fst1;
                    safeSetValPair('edtSb1','sldSb1',fst1);
                end
                if fst2 <= fp2 + minGapHz
                    adjustedParams{end+1} = '阻带截止 fst2';
                    oldValues(end+1) = fst2;
                    fst2 = min(fp2 + minGapHz, nyq);
                    newValues(end+1) = fst2;
                    safeSetValPair('edtSb2','sldSb2',fst2);
                end
                if ~(fst1 < fp1 && fp1 < fp2 && fp2 < fst2)
                    [fp1, fp2, fst1, fst2] = redistributeBand(fp1, fp2, fst1, fst2, nyq, minGapHz);
                    adjustedParams = {'通带/阻带 重新分配（带通）'};
                    oldValues = [getSafeHanVal('edtPb1',NaN), getSafeHanVal('edtPb2',NaN), getSafeHanVal('edtSb1',NaN), getSafeHanVal('edtSb2',NaN)];
                    newValues = [fp1, fp2, fst1, fst2];
                    safeSetValPair('edtPb1','sldPb1',fp1); safeSetValPair('edtPb2','sldPb2',fp2);
                    safeSetValPair('edtSb1','sldSb1',fst1); safeSetValPair('edtSb2','sldSb2',fst2);
                end
    
            case '带阻'
                % 需要： 0 < fp1 < fst1 < fst2 < fp2 < Nyq
                if fp1 >= fst1 - minGapHz
                    adjustedParams{end+1} = '阻带截止 fst1';
                    oldValues(end+1) = fst1;
                    fst1 = min(fp1 + minGapHz, nyq);
                    newValues(end+1) = fst1;
                    safeSetValPair('edtSb1','sldSb1',fst1);
                end
                if fst1 >= fst2 - minGapHz
                    adjustedParams{end+1} = '阻带截止 fst2';
                    oldValues(end+1) = fst2;
                    fst2 = min(fst1 + minGapHz, nyq);
                    newValues(end+1) = fst2;
                    safeSetValPair('edtSb2','sldSb2',fst2);
                end
                if fst2 >= fp2 - minGapHz
                    adjustedParams{end+1} = '通带截止 fp2';
                    oldValues(end+1) = fp2;
                    fp2 = min(fst2 + minGapHz, nyq);
                    newValues(end+1) = fp2;
                    safeSetValPair('edtPb2','sldPb2',fp2);
                end
                if ~(fp1 < fst1 && fst1 < fst2 && fst2 < fp2)
                    [fp1, fp2, fst1, fst2] = redistributeStop(fp1, fp2, fst1, fst2, nyq, minGapHz);
                    adjustedParams = {'通带/阻带 重新分配（带阻）'};
                    oldValues = [getSafeHanVal('edtPb1',NaN), getSafeHanVal('edtPb2',NaN), getSafeHanVal('edtSb1',NaN), getSafeHanVal('edtSb2',NaN)];
                    newValues = [fp1, fp2, fst1, fst2];
                    safeSetValPair('edtPb1','sldPb1',fp1); safeSetValPair('edtPb2','sldPb2',fp2);
                    safeSetValPair('edtSb1','sldSb1',fst1); safeSetValPair('edtSb2','sldSb2',fst2);
                end
        end
    
        % 如有调整，弹提示（保留"不再提示"选项）
        if ~isempty(adjustedParams)
            try
                showAutoAdjustAlert(oldValues, newValues, adjustedParams);
            catch
                setStatus(handles,'参数自动调整提示显示失败，但参数已调整');
                fprintf('调试点47：参数自动调整提示显示失败，但参数已调整\n');
            end
        end
    
        setStatus(handles,sprintf('滤波类型设置为：%s', ftype));
        updateNote(S, handles);
 
    
        % ========== 内部辅助函数 ==========
        function x = clampHz(x0, nyqLocal)
            x = max(1e-6, min(x0, nyqLocal));
        end
    
        function [a,b,c,d] = redistributeBand(fp1_,fp2_,~,~,nyqLocal,gap)
            lo = 1 + gap;
            hi = nyqLocal - gap;
            width = max(gap*4, min(hi-lo, (hi-lo) * 0.5));
            mid = (lo + hi) / 2;
            a = max(lo, min(mid - width/2, fp1_));   % fp1
            b = min(hi, max(mid + width/2, fp2_));   % fp2
            c = max(1, a - gap);                     % fst1
            d = min(nyqLocal, b + gap);              % fst2
        end
    
        function [a,b,c,d] = redistributeStop(fp1_,fp2_,fst1_,fst2_,nyqLocal,gap)
            a = max(1, min(fp1_, floor(nyqLocal*0.2)));
            b = max(a+gap*2, min(fp2_, ceil(nyqLocal*0.8)));
            c = max(a+gap, min(fst1_, a + gap*1.5));
            d = max(c+gap, min(fst2_, b - gap*1.5));
        end
    end

    %% ---- 更新所有频率控件/滑块频率限制范围 ----
    function updateFrequencyLimits(fs_local, handles)
    % 传入的 handle类 handles;
    % 对 handles 的对象内容有 "读/写" 操作

        % 获取当前奈奎斯特频率
        nyq = max(1e-6, fs_local/2);
        
        % 更新所有频率控件的限制范围
        handles.sldPb1.Limits = [1e-6, nyq];
        handles.sldPb2.Limits = [1e-6, nyq];
        handles.sldSb1.Limits = [1e-6, nyq];
        handles.sldSb2.Limits = [1e-6, nyq];
        
        handles.edtPb1.Limits = [1e-6, nyq];
        handles.edtPb2.Limits = [1e-6, nyq];
        handles.edtSb1.Limits = [1e-6, nyq];
        handles.edtSb2.Limits = [1e-6, nyq];
        
        % clamp helper函数
        clamp = @(x, lim) max(lim(1), min(x, lim(2)));
        
        % 保证当前值在限制范围内
        try
            handles.sldPb1.Value = clamp(handles.sldPb1.Value, handles.sldPb1.Limits);
            handles.edtPb1.Value = clamp(handles.edtPb1.Value, handles.edtPb1.Limits);
        catch
        end
        
        try
            handles.sldPb2.Value = clamp(handles.sldPb2.Value, handles.sldPb2.Limits);
            handles.edtPb2.Value = clamp(handles.edtPb2.Value, handles.edtPb2.Limits);
        catch
        end
        
        try
            handles.sldSb1.Value = clamp(handles.sldSb1.Value, handles.sldSb1.Limits);
            handles.edtSb1.Value = clamp(handles.edtSb1.Value, handles.edtSb1.Limits);
        catch
        end
        
        try
            handles.sldSb2.Value = clamp(handles.sldSb2.Value, handles.sldSb2.Limits);
            handles.edtSb2.Value = clamp(handles.edtSb2.Value, handles.edtSb2.Limits);
        catch
        end
        
        % 更新状态提示
        setStatus(handles,sprintf('频率范围已更新为 1-%d Hz (奈奎斯特频率)', floor(nyq)));
    end

    %% ---- 滤波器 Rp / Rs(As) 值变化回调 -----
    function onRpChanged(src,~)
        try val = double(src.Value); catch ; val = handles.edtRp.Value; end
        val = max(0, min(val, 100));
        src.Value = val;
        setStatus(handles,sprintf('通带最大衰减 Rp 设置为 %.2f dB', val));
        updateNote(S, handles);
    end

    function onRsChanged(src,~)
        try val = double(src.Value); catch ; val = handles.edtRs.Value; end
        val = max(0, min(val, 200));
        src.Value = val;
        setStatus(handles,sprintf('阻带最小衰减 Rs 设置为 %.2f dB', val));
        updateNote(S, handles);
    end
   
    %% ---- 滤波器截止频率编辑框回调 ----
    % 显示自动修正提示（带"不再提示"选项）
    function showAutoAdjustAlert(oldValues, newValues, adjustedParams)
        try
            % 检查用户是否已选择不再提示
            if isprop(S, 'disableAdjustAlert') && S.disableAdjustAlert
                return;
            end
            
            % 构建消息为单元格数组
            msgLines = {};
            msgLines{end+1} = '为了满足滤波器设计规范，已自动调整以下参数：';
            msgLines{end+1} = '';
            
            for i = 1:length(adjustedParams)
                paramName = adjustedParams{i};
                oldVal = oldValues(i);
                newVal = newValues(i);
                msgLines{end+1} = sprintf('• %s: %.1f Hz → %.1f Hz', paramName, oldVal, newVal);
            end
            
            msgLines{end+1} = '';
            msgLines{end+1} = sprintf('滤波器类型：%s', handles.ddType.Value);
            msgLines{end+1} = '';
            msgLines{end+1} = sprintf('设计方法：%s', handles.ddDesignMethod.Value);
            msgLines{end+1} = '';
    
            % 根据滤波器类型添加调整策略说明
            switch handles.ddType.Value
                case '低通'
                    strategy = '低通滤波器要求: 阻带频率 > 通带频率';
                case '高通' 
                    strategy = '高通滤波器要求: 阻带频率 < 通带频率';
                case '带通'
                    strategy = '带通滤波器要求: fst1 < fp1 < fp2 < fst2';
                case '带阻'
                    strategy = '带阻滤波器要求: fp1 < fst1 < fst2 < fp2';               

                otherwise
                    strategy = '滤波器设计要求特定的频率关系';
            end
            
            msgLines{end+1} = sprintf('调整策略: %s', strategy);
    
            % 计算动态高度 based on number of lines
            numLines = length(msgLines);
            dlgHeight = min(400, max(320, 20 * numLines + 100)); % 动态调整高度
    
            % 创建自定义对话框
            dlg_AutoAdjustAlert = createCenteredUIFigure('Name', '参数自动调整提示', ...
                          'Position', [700, 450, 400, dlgHeight-90], ...
                          'Resize', 'off', ...
                          'WindowStyle', 'modal'); % 浅色背景提高可读性
            
            % 创建网格布局
            gl_AutoAdjustAlert = uigridlayout(dlg_AutoAdjustAlert, [3, 4]);
            gl_AutoAdjustAlert.RowHeight = {'1x', 1, 25};
            gl_AutoAdjustAlert.ColumnWidth = {'1x', '1x', '1x', '1x'};
            gl_AutoAdjustAlert.Padding = [10, 10, 10, 10];
            gl_AutoAdjustAlert.RowSpacing = 5;
            gl_AutoAdjustAlert.ColumnSpacing = 5;
            
            % 使用 uitextarea 显示消息（直接使用单元格数组）
            txtMsg = uitextarea(gl_AutoAdjustAlert, ...
                               'Value', msgLines, ...
                               'Editable', 'off', ...
                               'WordWrap', 'on');
            txtMsg.Layout.Row = 1;
            txtMsg.Layout.Column = [1 4];
            
            % 分隔线
            sepLine = uilabel(gl_AutoAdjustAlert, 'Text', '');
            sepLine.Layout.Row = 2;
            sepLine.Layout.Column = [1 4];
            
            % 不再提示复选框
            cbDontShow = uicheckbox(gl_AutoAdjustAlert, ...
                                   'Text', '以后不再显示', ...
                                   'Value', false);
            cbDontShow.Layout.Row = 3;
            cbDontShow.Layout.Column = [1 3];
            
            % 确定按钮
            btnOk = uibutton(gl_AutoAdjustAlert, ...
                            'Text', '确定', ...
                            'ButtonPushedFcn', @(src,event) onAdjustAlertOk(src, event, cbDontShow.Value, dlg_AutoAdjustAlert));
            btnOk.Layout.Row = 3;
            btnOk.Layout.Column = 4;
            
            % 等待用户响应
            uiwait(dlg_AutoAdjustAlert);
        catch ME
            % 错误处理：回退到状态栏提示
            setStatus(handles,'参数已自动调整（详细提示显示失败）');
            fprintf('自动调整提示错误: %s\n', ME.message);
        end
    end

    function onAdjustAlertOk(src, event, dontShow, dlg_AutoAdjustAlert)
        % 保存用户选择
        S.disableAdjustAlert = dontShow;
        
        % 记录用户选择（可选，用于调试）
        if dontShow
            setStatus(handles,'用户选择不再显示参数调整提示');
        else
            setStatus(handles,'参数已调整，用户仍希望接收提示');
        end
        
        % 关闭对话框
        try
            close(dlg_AutoAdjustAlert);
        catch
            delete(dlg_AutoAdjustAlert);
        end
      
    end
    
    function onPb1Edit(src,~)
        % 编辑 fp1（通带左侧）：统一校验、自动修正并记录提示
        try val = double(src.Value); catch ; val = handles.sldPb1.Value; end
        nyq = max(1e-6, S.fs/2);
        minGapHz = 1e-6;
    
        % clamp 到合法范围
        val = max(1e-6, min(val, nyq));
    
        adjustedParams = {}; oldValues = []; newValues = [];
    
        ftype = handles.ddType.Value;
    
        switch ftype
            case '低通'
                % 要求 0 < fp1 < fst1
                fst1cur = getSafeHanVal('edtSb1', NaN);
                if val >= fst1cur - minGapHz
                    adjustedParams{end+1} = '阻带截止 fst1';
                    oldValues(end+1) = fst1cur;
                    newfst1 = min(val + minGapHz, nyq);
                    newValues(end+1) = newfst1;
                    safeSetValPair('edtSb1', 'sldSb1', newfst1);
                end
    
            case '高通'
                % 要求 0 < fst1 < fp1
                fst1cur = getSafeHanVal('edtSb1', NaN);
                if fst1cur >= val - minGapHz
                    adjustedParams{end+1} = '阻带截止 fst1';
                    oldValues(end+1) = fst1cur;
                    newfst1 = max(val - minGapHz, 1e-6);
                    newValues(end+1) = newfst1;
                    safeSetValPair('edtSb1', 'sldSb1', newfst1);
                end
    
            case '带通'
                % 要求 fst1 < fp1 < fp2 < fst2
                % 1) 若 fp2 <= fp1，提升 fp2 到 fp1 + gap（最小修改）
                fp2cur = getSafeHanVal('edtPb2', NaN);
                if fp2cur <= val + 0
                    adjustedParams{end+1} = '通带截止 fp2';
                    oldValues(end+1) = fp2cur;
                    newFp2 = min(val + minGapHz, nyq);
                    newValues(end+1) = newFp2;
                    safeSetValPair('edtPb2','sldPb2', newFp2);
                end
                % 2) 若 fst1 >= fp1，则压低 fst1
                fst1cur = getSafeHanVal('edtSb1', NaN);
                if fst1cur >= val - minGapHz
                    adjustedParams{end+1} = '阻带截止 fst1';
                    oldValues(end+1) = fst1cur;
                    newfst1 = max(val - minGapHz, 1e-6);
                    newValues(end+1) = newfst1;
                    safeSetValPair('edtSb1','sldSb1', newfst1);
                end
                % 3) 若 fp2 >= fst2（不合法），微调 fst2
                fst2cur = getSafeHanVal('edtSb2', NaN);
                fp2cur = getSafeHanVal('edtPb2', NaN);
                if fp2cur >= fst2cur - minGapHz
                    adjustedParams{end+1} = '阻带截止 fst2';
                    oldValues(end+1) = fst2cur;
                    newfst2 = min(fp2cur + minGapHz, nyq);
                    newValues(end+1) = newfst2;
                    safeSetValPair('edtSb2','sldSb2', newfst2);
                end
    
            case '带阻'
                % 要求 fp1 < fst1 < fst2 < fp2
                % 若 fp1 >= fst1，则将 fst1 向右移
                fst1cur = getSafeHanVal('edtSb1', NaN);
                if val >= fst1cur - minGapHz
                    adjustedParams{end+1} = '阻带截止 fst1';
                    oldValues(end+1) = fst1cur;
                    newfst1 = min(val + minGapHz, nyq);
                    newValues(end+1) = newfst1;
                    safeSetValPair('edtSb1','sldSb1', newfst1);
                end
                fst2cur = getSafeHanVal('edtSb2', NaN);
                if val >= fst2cur - minGapHz
                    adjustedParams{end+1} = '阻带截止 fst2';
                    oldValues(end+1) = fst2cur;
                    newfst2 = min(val + minGapHz, nyq);
                    newValues(end+1) = newfst2;
                    safeSetValPair('edtSb2','sldSb2', newfst2);
                end
                fp2cur = getSafeHanVal('edtPb2', NaN);
                if fp2cur <= val + 0
                    adjustedParams{end+1} = '通带截止 fp2';
                    oldValues(end+1) = fp2cur;
                    newFp2 = min(val + minGapHz, nyq);
                    newValues(end+1) = newFp2;
                    safeSetValPair('edtPb2','sldPb2', newFp2);
                end
        end
    
        % 最终把 fp1 写回并同步 slider
        safeSetValPair('edtPb1','sldPb1', val);
    
        if ~isempty(adjustedParams)
            try
                showAutoAdjustAlert(oldValues, newValues, adjustedParams);
            catch
                setStatus(handles,'参数自动调整提示显示失败，但参数已调整');
                fprintf('调试点48：参数自动调整提示显示失败，但参数已调整\n');
            end
        end
    
        setStatus(handles,sprintf('通带截止 fp1 设置为 %.2f Hz', val));
        updateNote(S, handles);
        
    end

    function onPb2Edit(src,~)
        % 编辑 fp2（通带右侧）：校验并自动修正
        try val = double(src.Value); catch ; val = handles.sldPb2.Value; end
        nyq = max(1e-6, S.fs/2);
        minGapHz = 1e-6;
    
        val = max(1e-6, min(val, nyq));
    
        adjustedParams = {}; oldValues = []; newValues = [];
    
        ftype = handles.ddType.Value;
    
        switch ftype
            case '带通'
                % 需要 fst1 < fp1 < fp2 < fst2
                fp1cur = getSafeHanVal('edtPb1', NaN);
                if val <= fp1cur + 0
                    adjustedParams{end+1} = '通带截止 fp2';
                    oldValues(end+1) = val;
                    val = max(fp1cur + minGapHz, min(val + minGapHz, nyq));
                    newValues(end+1) = val;
                end
                % 若 fst2 <= fp2，则提升 fst2
                fst2cur = getSafeHanVal('edtSb2', NaN);
                if fst2cur <= val + minGapHz
                    adjustedParams{end+1} = '阻带截止 fst2';
                    oldValues(end+1) = fst2cur;
                    newfst2 = min(val + minGapHz, nyq);
                    newValues(end+1) = newfst2;
                    safeSetValPair('edtSb2','sldSb2', newfst2);
                end
                % 若 fst1 >= fp1（可能因用户先改后续值），做最小修正
                fst1cur = getSafeHanVal('edtSb1', NaN);
                fp1cur = getSafeHanVal('edtPb1', NaN);
                if fst1cur >= fp1cur - minGapHz
                    adjustedParams{end+1} = '阻带截止 fst1';
                    oldValues(end+1) = fst1cur;
                    newfst1 = max(fp1cur - minGapHz, 1e-6);
                    newValues(end+1) = newfst1;
                    safeSetValPair('edtSb1','sldSb1', newfst1);
                end
    
            case '带阻'
                % 带阻: 需要 fp1 < fst1 < fst2 < fp2
                % 保证 fp2 > fst2
                fst2cur = getSafeHanVal('edtSb2', NaN);
                if val <= fst2cur + minGapHz
                    adjustedParams{end+1} = '阻带截止 fst2';
                    oldValues(end+1) = fst2cur;
                    newfst2 = max(1e-6, min(val - minGapHz, nyq));
                    newValues(end+1) = newfst2;
                    safeSetValPair('edtSb2','sldSb2', newfst2);
                end
                % 保证 fp2 > fst1
                fst1cur = getSafeHanVal('edtSb1', NaN);
                if val <= fst1cur + minGapHz
                    adjustedParams{end+1} = '阻带截止 fst1';
                    oldValues(end+1) = fst1cur;
                    newfst1 = max(1e-6, min(val - minGapHz, nyq));
                    newValues(end+1) = newfst1;
                    safeSetValPair('edtSb1','sldSb1', newfst1);
                end
                % 保证 fp2 > fp1
                fp1cur = getSafeHanVal('edtPb1', NaN);
                if val <= fp1cur + minGapHz
                    adjustedParams{end+1} = '通带截止 fp1';
                    oldValues(end+1) = fp1cur;
                    newfp1 = max(1e-6, min(val - minGapHz, nyq));
                    newValues(end+1) = newfp1;
                    safeSetValPair('edtPb1','sldPb1', newfp1);
                   
                end
        end
    
        % 写回 fp2 至编辑框与滑块
        safeSetValPair('edtPb2','sldPb2', val);
    
        if ~isempty(adjustedParams)
            try
                showAutoAdjustAlert(oldValues, newValues, adjustedParams);
            catch
                setStatus(handles,'参数自动调整提示显示失败，但参数已调整');
                fprintf('调试点49：参数自动调整提示显示失败，但参数已调整\n');
            end
        end
    
        setStatus(handles,sprintf('通带截止 fp2 设置为 %.2f Hz', val));
        updateNote(S, handles);

    end

    function onSb1Edit(src,~)
        % 编辑 fst1（阻带低/左边界）时的严格校验与自动修正
        try val = double(src.Value); catch; val = handles.sldSb1.Value; end
        nyq = max(1e-6, S.fs/2);
        minGapHz = 1e-6;
    
        % clamp
        val = max(1e-6, min(val, nyq));
    
        adjustedParams = {}; oldValues = []; newValues = [];
    
        ftype = handles.ddType.Value;
    
        switch ftype
            case '低通'
                % 需要 0 < fp1 < fst1 < Nyq
                fp1cur = getSafeHanVal('edtPb1', NaN);
                if fp1cur >= val - minGapHz
                    adjustedParams{end+1} = '通带截止 fp1';
                    oldValues(end+1) = fp1cur;
                    newFp1 = max(1e-6, val - minGapHz);
                    newValues(end+1) = newFp1;
                    safeSetValPair('edtPb1','sldPb1', newFp1);
                end
    
            case '高通'
                % 需要 0 < fst1 < fp1 < Nyq
                fp1cur = getSafeHanVal('edtPb1', NaN);
                if val >= fp1cur - minGapHz
                    adjustedParams{end+1} = '通带截止 fp1';
                    oldValues(end+1) = fp1cur;
                    newFp1 = min(nyq, val + minGapHz);
                    newValues(end+1) = newFp1;
                    safeSetValPair('edtPb1','sldPb1', newFp1);
                end
    
            case '带通'
                % 需要 fst1 < fp1 < fp2 < fst2
                fp1cur = getSafeHanVal('edtPb1', NaN);
                fp2cur = getSafeHanVal('edtPb2', NaN);
                fst2cur = getSafeHanVal('edtSb2', NaN);
    
                % 若 fst1 >= fp1 -> 把 fp1 提升到 fst1 + gap
                if val >= fp1cur - minGapHz
                    adjustedParams{end+1} = '通带截止 fp1';
                    oldValues(end+1) = fp1cur;
                    newFp1 = min(nyq, val + minGapHz);
                    newValues(end+1) = newFp1;
                    safeSetValPair('edtPb1','sldPb1', newFp1);
                    fp1cur = newFp1;
                end
                % 若 fp1 >= fp2 -> 提升 fp2
                if fp1cur >= fp2cur - minGapHz
                    adjustedParams{end+1} = '通带截止 fp2';
                    oldValues(end+1) = fp2cur;
                    newFp2 = min(nyq, fp1cur + minGapHz);
                    newValues(end+1) = newFp2;
                    safeSetValPair('edtPb2','sldPb2', newFp2);
                    fp2cur = newFp2;
                end
                % 若 fp2 >= fst2 -> 提升 fst2
                if fp2cur >= fst2cur - minGapHz
                    adjustedParams{end+1} = '阻带截止 fst2';
                    oldValues(end+1) = fst2cur;
                    newfst2 = min(nyq, fp2cur + minGapHz);
                    newValues(end+1) = newfst2;
                    safeSetValPair('edtSb2','sldSb2', newfst2);
                end
    
            case '带阻'
                % 需要 fp1 < fst1 < fst2 < fp2
                fp1cur = getSafeHanVal('edtPb1', NaN);
                fst2cur = getSafeHanVal('edtSb2', NaN);
                fp2cur = getSafeHanVal('edtPb2', NaN);
    
                % 若 fp1 >= fst1 -> 把 fp1 下移到 fst1 - gap（尽量保留用户 fst1）
                if fp1cur >= val - minGapHz
                    adjustedParams{end+1} = '通带截止 fp1';
                    oldValues(end+1) = fp1cur;
                    newFp1 = max(1e-6, val - minGapHz);
                    newValues(end+1) = newFp1;
                    safeSetValPair('edtPb1','sldPb1', newFp1);
                end
                % 若 fst1 >= fst2 -> 把 fst2 推到 fst1 + gap
                if val >= fst2cur - minGapHz
                    adjustedParams{end+1} = '阻带截止 fst2';
                    oldValues(end+1) = fst2cur;
                    newfst2 = min(nyq, val + minGapHz);
                    newValues(end+1) = newfst2;
                    safeSetValPair('edtSb2','sldSb2', newfst2);
                    fst2cur = newfst2;
                end
                % 若 fst2 >= fp2 -> 推高 fp2
                if fst2cur >= fp2cur - minGapHz
                    adjustedParams{end+1} = '通带截止 fp2';
                    oldValues(end+1) = fp2cur;
                    newFp2 = min(nyq, fst2cur + minGapHz);
                    newValues(end+1) = newFp2;
                    safeSetValPair('edtPb2','sldPb2', newFp2);
                end
        end
    
        % 写回 fst1（编辑框+滑块）
        safeSetValPair('edtSb1','sldSb1', val);
    
        if ~isempty(adjustedParams)
            try
                showAutoAdjustAlert(oldValues, newValues, adjustedParams);
            catch
                setStatus(handles,'参数自动调整提示出错（fst1），但参数已调整');
                fprintf('调试点50：参数自动调整提示出错（fst1），但参数已调整\n');
            end
        end
    
        setStatus(handles,sprintf('阻带截止 fst1 设置为 %.2f Hz', val));
        updateNote(S, handles);
    
    end
    
    function onSb2Edit(src,~)
        % 编辑 fst2（阻带高/右边界）时的严格校验与自动修正
        try val = double(src.Value); catch; val = handles.sldSb2.Value; end
        nyq = max(1e-6, S.fs/2);
        minGapHz = 1e-6;
    
        % clamp
        val = max(1e-6, min(val, nyq));
    
        adjustedParams = {}; oldValues = []; newValues = [];
    
        ftype = handles.ddType.Value;
    
        switch ftype
            case '低通'
                % 低通一般只有 fst1 有意义，但容错处理：若 fst2 存在，确保 fst2 > fp1
                fp1cur = getSafeHanVal('edtPb1', NaN);
                if val <= fp1cur + minGapHz
                    adjustedParams{end+1} = '通带截止 fp1';
                    oldValues(end+1) = fp1cur;
                    newFp1 = max(1e-6, val - minGapHz);
                    newValues(end+1) = newFp1;
                    safeSetValPair('edtPb1','sldPb1', newFp1);
                end
    
            case '高通'
                % 高通通常只用 fst1/ fp1，fst2 容错：确保 fst2 < Nyq（已 clamp）
                % 无额外动作（保守）
    
            case '带通'
                % 需要 fst1 < fp1 < fp2 < fst2
                fp2cur = getSafeHanVal('edtPb2', NaN);
                fp1cur = getSafeHanVal('edtPb1', NaN);
                fst1cur = getSafeHanVal('edtSb1', NaN);
    
                % 若 fp2 >= fst2 -> 把 fp2 下调到 fst2 - gap
                if fp2cur >= val - minGapHz
                    adjustedParams{end+1} = '通带截止 fp2';
                    oldValues(end+1) = fp2cur;
                    newFp2 = max(1e-6, val - minGapHz);
                    newValues(end+1) = newFp2;
                    safeSetValPair('edtPb2','sldPb2', newFp2);
                    fp2cur = newFp2;
                end
                % 若 fp1 >= fp2 -> 把 fp1 下调到 fp2 - gap
                if fp1cur >= fp2cur - minGapHz
                    adjustedParams{end+1} = '通带截止 fp1';
                    oldValues(end+1) = fp1cur;
                    newFp1 = max(1e-6, fp2cur - minGapHz);
                    newValues(end+1) = newFp1;
                    safeSetValPair('edtPb1','sldPb1', newFp1);
                end
                % 若 fst1 >= fst2 -> 把 fst1 下调到 fst2 - gap（尽量保留 fp1）
                if fst1cur >= val - minGapHz
                    adjustedParams{end+1} = '阻带截止 fst1';
                    oldValues(end+1) = fst1cur;
                    newfst1 = max(1e-6, val - minGapHz);
                    newValues(end+1) = newfst1;
                    safeSetValPair('edtSb1','sldSb1', newfst1);
                end
    
            case '带阻'
                % 需要 fp1 < fst1 < fst2 < fp2
                fp2cur = getSafeHanVal('edtPb2', NaN);
                fst1cur = getSafeHanVal('edtSb1', NaN);
                fp1cur = getSafeHanVal('edtPb1', NaN);
    
                % 若 fst2 >= fp2 -> 提升 fp2
                if val >= fp2cur - minGapHz
                    adjustedParams{end+1} = '通带截止 fp2';
                    oldValues(end+1) = fp2cur;
                    newFp2 = min(nyq, val + minGapHz);
                    newValues(end+1) = newFp2;
                    safeSetValPair('edtPb2','sldPb2', newFp2);
                end
                % 若 fst1 >= fst2 -> 把 fst1 下调到 fst2 - gap（尽量保留 fp1）
                if fst1cur >= val - minGapHz
                    adjustedParams{end+1} = '阻带截止 fst1';
                    oldValues(end+1) = fst1cur;
                    newfst1 = max(1e-6, val - minGapHz);
                    newValues(end+1) = newfst1;
                    safeSetValPair('edtSb1','sldSb1', newfst1);
                end
                % 若 fp1 >= fst1（可能因上面调整），确保 fp1 < fst1
                fst1cur = getSafeHanVal('edtSb1', NaN); % 重新读
                if fp1cur >= fst1cur - minGapHz
                    adjustedParams{end+1} = '通带截止 fp1';
                    oldValues(end+1) = fp1cur;
                    newFp1 = max(1e-6, fst1cur - minGapHz);
                    newValues(end+1) = newFp1;
                    safeSetValPair('edtPb1','sldPb1', newFp1);
                end
        end
    
        % 写回 fst2
        safeSetValPair('edtSb2','sldSb2', val);
    
        if ~isempty(adjustedParams)
            try
                showAutoAdjustAlert(oldValues, newValues, adjustedParams);
            catch
                setStatus(handles,'参数自动调整提示出错（fst2），但参数已调整');
                fprintf('调试点51：参数自动调整提示出错（fst2），但参数已调整\n');
            end
        end
    
        setStatus(handles,sprintf('阻带截止 fst2 设置为 %.2f Hz', val));
        updateNote(S, handles);
    
    end

    %% ---- 安全设置 handles 中控件的 Enable，交给类GUIHandles()中 method safeSetEnable()处理 ----
    % onDesignMethodChange()、applyIIRProtoEnables()、onFIRMethodChange()、onTypeChange()中使用
    function safeEnableHan(name, state)
        try 
            handles.safeSetEnable(name, state); 
        catch
        end
    end

    %% ---- 安全读取 handles 中控件的 Value，交给类GUIHandles()中 method getValueSafe()处理 ----
    % onTypeChange()、onPb1Edit()、onPb2Edit()、onSb1Edit()、onSb2Edit()中使用
    function v = getSafeHanVal(name, defaultVal)
        try
            v = handles.getValueSafe(name, defaultVal);
        catch
            v = defaultVal;
        end
    end
    
    %% ---- 安全设置 handles 中控件的 ValuePair，交给类GUIHandles()中 method safeSetValPair()处理 ----
    % onTypeChange()、onPb1Edit()、onPb2Edit()、onSb1Edit()、onSb2Edit()中使用
    function safeSetValPair(edtName, sldName, Value)
        try
            handles.safeSetValPair(edtName, sldName, Value);
        catch
        end
    end

