    function onSliderPb1Changed(src,~)
        val = double(src.Value);
        nyq = max(1e-6,S.fs/2);
        val = max(1e-6, min(val, nyq));
        try src.Value = max(src.Limits(1), min(val, src.Limits(2))); catch; end
        
        
        try
        handles.edtPb1.Value = max(handles.edtPb1.Limits(1), min(val, handles.edtPb1.Limits(2)));
        catch
        end
        
        
        try
        onPb1Edit(handles.edtPb1, []);
