    %% ---- “多带 / 高级滤波参数”按钮回调（严格模态窗口） ---- 
    function onMultiBandAdvancedParams(~,~)
        FIR_Opt_Design_Method = handles.ddFIRMethod.Value; % 'Parks-McClellan' / '最小二乘(firls)' / '约束最小二乘(fircls)'等
        nyq = max(1e-6, S.fs/2);
        IIROrder = round(double(handles.edtIIROrder.Value));
        FIROrder = round(double(handles.edtFIROrder.Value));


        if (isempty(IIROrder) || IIROrder <= 0) && isprop(handles,'ddType') && strcmp(handles.ddType.Value,'多带/高级')
            if strcmpi(handles.ddDesignMethod.Value,'IIR') && isprop(handles,'ddIIRProto') 
                if strcmpi(handles.ddIIRProto.Value,'Yule-Walker') 
                    uialert_safe(fig_GUI, 'IIR - Yule-Walker不支持自动估阶。请在 "IIR 阶数" 输入框中输入正整数，然后进行多带/高级滤波参数设置。', '参数错误');
                    setStatus(handles,'设计失败：Yule-Walker 多带/高级需要正整数阶数');
                    return;
                end
                if strcmpi(handles.ddIIRProto.Value,'maxflat') 
                    uialert_safe(fig_GUI, 'IIR -maxflat不支持自动估阶。请在 "IIR 阶数" 输入框中输入正整数，然后进行多带/高级滤波参数设置。', '参数错误');
                    setStatus(handles,'设计失败：maxflat 多带/高级需要正整数阶数');
                    return;
                end
            end
        end

        if (isempty(FIROrder) || FIROrder <= 0)  && isprop(handles,'ddType') && strcmp(handles.ddType.Value,'多带/高级')
            if strcmpi(handles.ddDesignMethod.Value, 'FIR频率采样法')
                uialert_safe(fig_GUI, 'FIR频率采样法不支持自动估阶。请在 "FIR 阶数" 输入框中输入正整数，然后进行多带/高级滤波参数设置。', '参数错误');
                setStatus(handles,'设计失败：FIR频率采样法 需要正整数阶数'); return;
            end
            if strcmpi(handles.ddDesignMethod.Value, 'FIR优化设计法')
                % 对 Cplx-Parks-McClellan/其他不支持自动估阶的，提醒用户
                if strcmpi(FIR_Opt_Design_Method,'Cplx-Parks-McClellan') 
                    uialert_safe(fig_GUI, sprintf('FIR 优化设计法 - %s 不支持自动估阶。请在 "FIR 阶数" 输入框中输入正整数，然后进行多带/高级滤波参数设置。', FIR_Opt_Design_Method), '参数错误');
                    setStatus(handles,['多带/高级参数设置取消：', FIR_Opt_Design_Method, ' 需要正整数阶数']);
                    return;
                end
                if strcmpi(FIR_Opt_Design_Method,{'最小二乘(firls)'})
                    uialert_safe(fig_GUI, 'FIR优化设计法 - 最小二乘(firls)不支持自动估阶。请在 "FIR 阶数" 输入框中输入正整数，然后进行多带/高级滤波参数设置。', '参数错误');
                    setStatus(handles,'设计失败：FIR优化设计法 - 最小二乘(firls) 需要正整数阶数'); return;
                end
                if strcmpi(FIR_Opt_Design_Method,{'约束最小二乘(fircls)'})
                    uialert_safe(fig_GUI, 'FIR优化设计法 - 约束最小二乘(fircls)不支持自动估阶。请在 "FIR 阶数" 输入框中输入正整数，然后进行多带/高级滤波参数设置。', '参数错误');
                    setStatus(handles,'设计失败：FIR优化设计法 - 约束最小二乘(fircls) 需要正整数阶数'); return;   
                end
                if strcmpi(FIR_Opt_Design_Method,{'约束最小二乘1(fircls1)'})
                    uialert_safe(fig_GUI, 'FIR优化设计法 - 约束最小二乘1(fircls1)不支持自动估阶。请在 "FIR 阶数" 输入框中输入正整数，然后进行多带/高级滤波参数设置。', '参数错误');
                    setStatus(handles,'设计失败：FIR优化设计法 - 约束最小二乘(fircls) 需要正整数阶数'); return;   
                end
            end
        end
        

        % ---------------------------------------------------------------- IIR - Yule-Walker 弹窗 -------------------------------------------------------------------
        if strcmpi(handles.ddDesignMethod.Value,'IIR') && isprop(handles,'ddIIRProto') && strcmpi(handles.ddIIRProto.Value,'Yule-Walker') && isprop(handles,'ddType') && strcmp(handles.ddType.Value,'多带/高级')
            IIROrder = round(double(handles.edtIIROrder.Value));
            % 打开并阻塞，返回 params 结构或空
            params = openYulewalkMultiBandWindow(fig_GUI, handles, S, IIROrder);
            if isempty(params)
                setStatus(handles,'多带/高级 / 高级参数设置已取消或未保存。');
                return;
            end
            % 保存到 handles（以便后续设计使用）
            handles.yuleWalkParams = params;
            handles.yuleWalkParamsHistory{end+1} = params;
            % guidata(fig_GUI, handles);  % 把参数写回主界面 handles
            % 当前选择的设计方法与阶数
            updateDesignLabel(S, handles);
            % 将参数在备注栏显示
            updateNote(S, handles);
            setStatus(handles,'已保存 Yule-Walker 多带/高级/高级参数。');
            return;
        end


        % ---------------------------------------------------------------- IIR - maxflat 弹窗 -------------------------------------------------------------------
        if strcmpi(handles.ddDesignMethod.Value,'IIR') && isprop(handles,'ddIIRProto') ...
                && strcmpi(handles.ddIIRProto.Value,'maxflat') && isprop(handles,'ddType') ...
                && strcmp(handles.ddType.Value,'多带/高级')
            % 注意：maxflat 不支持自动估阶 -> 但这里窗体会要求 n 可填写（默认取 edtIIROrder）
            IIROrder = round(double(handles.edtIIROrder.Value));
          
            % 打开 maxflat 专用窗口（严格模态）
            params = openMaxflatAdvancedWindow(fig_GUI, handles, S, IIROrder);
            if isempty(params)
                setStatus(handles,'maxflat 多带/高级参数设置已取消或未保存。');
                return;
            end
            % 保存到 handles
            handles.maxflatParams = params;
            handles.maxflatParamsHistory{end+1} = params;
            % try guidata(fig_GUI, handles); catch; end
            % 当前选择的设计方法与阶数
            updateDesignLabel(S, handles);
            updateNote(S, handles);
            setStatus(handles,'已保存 maxflat 多带/高级参数。');
            return;
        end


        % ---------------------------------------------------------------- FIR 频率采样法 多带/高级 / 高级弹窗 --------------------------------------------------------------------
        if strcmpi(handles.ddDesignMethod.Value, 'FIR频率采样法') && isprop(handles,'ddType') && strcmp(handles.ddType.Value,'多带/高级')
            % 打开并阻塞，返回 params 结构或空
            FIROrder = round(double(handles.edtFIROrder.Value));
            params = openFir2MultiBandWindow(fig_GUI, handles, S, FIROrder);
            if isempty(params)
                setStatus(handles,'多带/高级 / 高级参数设置已取消或未保存。');
                return;
            end
            % 保存到 handles（以便后续设计使用）
            handles.fir2Params = params;
            handles.fir2ParamsHistory{end+1} = params;
        
            if isfield(params,'newFIROrder') && ~isempty(params.newFIROrder) && isnumeric(params.newFIROrder)
                handles.edtFIROrder.Value = params.newFIROrder;
            end

            % guidata(fig_GUI, handles);  % 把参数写回主界面 handles
            % 当前选择的设计方法与阶数
            updateDesignLabel(S, handles);
            % 将参数在备注栏显示
            updateNote(S, handles);
            setStatus(handles,'已保存 FIR频率采样法 多带/高级/高级参数。');
            return;
        end

        % ---------------------------------------------------------------- Parks-McClellan 多带/高级 / 高级弹窗 --------------------------------------------------------------------
        if strcmpi(handles.ddDesignMethod.Value,'FIR优化设计法') && strcmpi(handles.ddFIRMethod.Value, 'Parks-McClellan') && strcmp(handles.ddType.Value,'多带/高级')
            % 打开并阻塞，返回 params 结构或空
            FIROrder = round(double(handles.edtFIROrder.Value));
            params = openFirpmMultiBandWindow(fig_GUI, handles, S, FIROrder);
            if isempty(params)
                setStatus(handles,'多带/高级 / 高级参数设置已取消或未保存。');
                return;
            end
            % 保存到 handles（以便后续设计使用）
            handles.firpmParams = params;
            handles.firpmMBPaHistory = params;
            handles.firpmParamsHistory{end+1} = params;
            if isfield(params,'newFIROrder') && ~isempty(params.newFIROrder) && isnumeric(params.newFIROrder)
                handles.edtFIROrder.Value = params.newFIROrder;
            end

            % guidata(fig_GUI, handles);  % 把参数写回主界面 handles
            % 当前选择的设计方法与阶数
            updateDesignLabel(S, handles);
            % 将参数在备注栏显示
            updateNote(S, handles);
            setStatus(handles,'已保存 Parks-McClellan 多带/高级/高级参数。');
            return;
        end


        % ---------------------------------------------------------------- Cplx-Parks-McClellan 多带/高级弹窗 -------------------------------------------------------------------
        % 如果是 Cplx-Parks-McClellan，则打开 "多带/高级 / 高级滤波参数设置" 窗口（严格模态）
        if strcmpi(handles.ddDesignMethod.Value,'FIR优化设计法') && strcmpi(FIR_Opt_Design_Method,'Cplx-Parks-McClellan') && isprop(handles,'ddType') && strcmp(handles.ddType.Value,'多带/高级')
            % 打开并阻塞，返回 params 结构或空
            params = openCfirpmAdvancedWindow(fig_GUI, handles, S, FIROrder);
            if isempty(params)
                setStatus(handles,'多带/高级 / 高级参数设置已取消或未保存。');
                return;
            end
            % 保存到 handles（以便后续设计使用）
            handles.cfirpmParams = params;
            handles.cfirpmParamsHistory{end+1} = params;
            
            % guidata(fig_GUI, handles);  % 把参数写回主界面 handles
            % 当前选择的设计方法与阶数
            updateDesignLabel(S, handles);
            % 将参数在备注栏显示
            updateNote(S, handles);
            setStatus(handles,'已保存 cfirpm 多带/高级/高级参数。');
            return;
        end


        % ---------------------------------------------------------------- firls最小二乘法 多带/高级 / 高级弹窗 --------------------------------------------------------------------
        if strcmpi(handles.ddDesignMethod.Value,'FIR优化设计法') && strcmpi(handles.ddFIRMethod.Value,'最小二乘(firls)') && strcmp(handles.ddType.Value,'多带/高级')
            % 打开并阻塞，返回 params 结构或空
            FIROrder = round(double(handles.edtFIROrder.Value));
            params = openFirlsMultiBandWindow(fig_GUI, handles, S, FIROrder);
            if isempty(params)
                setStatus(handles,'多带/高级 / 高级参数设置已取消或未保存。');
                return;
            end
            % 保存到 handles（以便后续设计使用）
            handles.firlsParams = params;
            handles.firlsParamsHistory{end+1} = params;
                     
            if isfield(params,'newFIROrder') && ~isempty(params.newFIROrder) && isnumeric(params.newFIROrder)
                handles.edtFIROrder.Value = params.newFIROrder;
            end
            % guidata(fig_GUI, handles);  % 把参数写回主界面 handles
            % 当前选择的设计方法与阶数
            updateDesignLabel(S, handles);
            % 将参数在备注栏显示
            updateNote(S, handles);
            setStatus(handles,'已保存 最小二乘(firls) 多带/高级/高级参数。');
            return;
        end

        % ---------------------------------------------------------------- fircls约束最小二乘法 多带/高级 / 高级弹窗 --------------------------------------------------------------------
        if strcmpi(handles.ddDesignMethod.Value,'FIR优化设计法') && strcmpi(handles.ddFIRMethod.Value,'约束最小二乘(fircls)') && strcmp(handles.ddType.Value,'多带/高级')
            % 打开并阻塞，返回 params 结构或空
            FIROrder = round(double(handles.edtFIROrder.Value));
            params = openFirclsMultiBandWindow(fig_GUI, handles, S, FIROrder);
            if isempty(params)
                setStatus(handles,'多带/高级 / 高级参数设置已取消或未保存。');
                return;
            end
            % 保存到 handles（以便后续设计使用）
            handles.firclsParams = params;
            handles.firclsParamsHistory{end+1} = params;
            
            if isfield(params,'newFIROrder') && ~isempty(params.newFIROrder) && isnumeric(params.newFIROrder)
                handles.edtFIROrder.Value = params.newFIROrder;
            end

            % guidata(fig_GUI, handles);  % 把参数写回主界面 handles
            % 当前选择的设计方法与阶数
            updateDesignLabel(S, handles);
            % 将参数在备注栏显示
            updateNote(S, handles);
            setStatus(handles,'已保存 约束最小二乘(fircls) 多带/高级/高级参数。');
            return;
        end


        % ---------------------------------------------------------------- 约束最小二乘1(fircls1) 多带/高级 / 高级弹窗 -------------------------------------------------------------------
        if strcmpi(handles.ddDesignMethod.Value,'FIR优化设计法') && strcmpi(FIR_Opt_Design_Method,'约束最小二乘1(fircls1)') && isprop(handles,'ddType') && strcmp(handles.ddType.Value,'多带/高级')
            % 检查阶数是否有效（fircls1 不支持自动估阶）
            FIROrder = round(double(handles.edtFIROrder.Value));
            if isempty(FIROrder) || FIROrder <= 0
                uialert_safe(fig_GUI, 'FIR优化设计法 - 约束最小二乘1(fircls1)不支持自动估阶。请在 "FIR 阶数" 输入框中输入正整数，然后进行多带/高级滤波参数设置。', '参数错误');
                setStatus(handles,'多带/高级参数设置取消：约束最小二乘1(fircls1) 需要正整数阶数'); 
                return;
            end
            % 打开并阻塞，返回 params 结构或空
            params = openFircls1AdvancedWindow(fig_GUI, handles, S, FIROrder);
            if isempty(params)
                setStatus(handles,'约束最小二乘1(fircls1) 参数设置已取消或未保存。');
                return;
            end
            % 保存到 handles（以便后续设计使用）
            handles.fircls1Params = params;
            % guidata(fig_GUI, handles);  % 把参数写回主界面 handles
            handles.fircls1ParamsHistory{end+1} = params;  % optional 保存历史
            setStatus(handles,'已保存 约束最小二乘1(fircls1) 多带/高级参数。');
            % 当前选择的设计方法与阶数
            updateDesignLabel(S, handles);
            updateNote(S, handles);
            return;
        end


        % ---------------------------------------------------------------- intfilt 弹窗 -------------------------------------------------------------------
        if strcmpi(handles.ddDesignMethod.Value,'FIRintfilt插值') && isprop(handles,'ddType') && strcmp(handles.ddType.Value,'多带/高级')
            % no order required; 直接打开参数窗口
            params = openIntfiltAdvancedWindow(fig_GUI, handles, S);
            if isempty(params)
                setStatus(handles,'intfilt 参数设置已取消或未保存。');
                return;
            end
            % 保存到 handles
            handles.intfiltParams = params;
            handles.intfiltParamsHistory{end+1} = params;
            % guidata(fig_GUI, handles);
            % 当前选择的设计方法与阶数
            updateDesignLabel(S, handles);
            updateNote(S, handles);
            setStatus(handles,'已保存 intfilt 插值参数。');
            return;
        end

                
        % ---------------------------------------------------------------- FIRgaussdesign脉冲整形 多带/高级弹窗 -------------------------------------------------------------------
        if strcmpi(handles.ddDesignMethod.Value,'FIRgaussdesign脉冲整形') && isprop(handles,'ddType') && strcmp(handles.ddType.Value,'多带/高级')
            % 打开并阻塞，返回 params 结构或空
            params = openGaussdesignAdvancedWindow(fig_GUI, handles, S);
            if isempty(params)
                setStatus(handles,'gaussdesign 参数设置已取消或未保存。');
                return;
            end
            % 保存到 handles（以便后续设计使用）
            handles.gaussdesignParams = params;
            handles.gaussdesignParamsHistory{end+1} = params;
            % guidata(fig_GUI, handles);
            % 当前选择的设计方法与阶数
            updateDesignLabel(S, handles);
            updateNote(S, handles);
            setStatus(handles,'已保存 gaussdesign 脉冲整形参数。');
            return;
        end


        % ---------------------------------------------------------------- FIRrcosdesign脉冲整形 多带/高级弹窗 -------------------------------------------------------------------
        if strcmpi(handles.ddDesignMethod.Value,'FIRrcosdesign脉冲整形') && isprop(handles,'ddType') && strcmp(handles.ddType.Value,'多带/高级')
            params = openRcosdesignAdvancedWindow(fig_GUI, handles, S);
            if isempty(params)
                setStatus(handles,'rcosdesign 参数设置已取消或未保存。');
                return;
            end
            % 保存到 handles（以便后续设计/应用使用）
            handles.rcosdesignParams = params;
            handles.rcosdesignParamsHistory{end+1} = params;
            % guidata(fig_GUI, handles);
            % 当前选择的设计方法与阶数
            updateDesignLabel(S, handles);
            updateNote(S, handles);
            setStatus(handles,'已保存 rcosdesign 脉冲整形参数。');
            return;
        end


        % ----------------------------------------------------------- Savitzky-Golay 多带参数窗口 ----------------------------------------------------------------
        if isprop(handles,'ddDesignMethod') && strcmp(handles.ddDesignMethod.Value,'Savitzky-Golay') && isprop(handles,'ddType') && strcmp(handles.ddType.Value,'多带/高级')
            % 打开 SG 参数设置窗口（严格模态）
            params = openSgolayAdvancedWindow(fig_GUI, handles, S);
            if isempty(params)
                setStatus(handles,'Savitzky-Golay 参数设置已取消或未保存。');
                return;
            end
            % 保存到 handles
            handles.sgolayParams = params;
            handles.sgolayParamsHistory{end+1} = params;
            % 把 handles 写回（项目内可能使用 guidata 或 setappdata）
            % try guidata(fig_GUI, handles); catch; end
            % 当前选择的设计方法与阶数
            updateDesignLabel(S, handles);
            updateNote(S, handles);
            setStatus(handles,'已保存 Savitzky-Golay 参数。');
            return;
        end


    end

    %% ---- “陷波 / 峰值滤波参数”按钮回调（严格模态窗口） ---- 
    function onNotchPeakParams(~,~)
        % 弹出严格模态窗口，mode 来自设计方法下拉
        modeStr = handles.ddDesignMethod.Value; % '陷波' 或 '峰值滤波'
        % 统一内部 mode 标识
        if contains(modeStr,'峰')
            mode = 'peak';
            uiWord = '峰值滤波';
        else
            mode = 'notch';
            uiWord = '陷波';
        end
    
        % Nyquist
        nyq = S.fs/2;
    
        % 创建模态窗口
        dlg_NotchPeak = createCenteredUIFigure('Name', sprintf('%s参数设置', uiWord), 'Position',[500 200 700 700], 'WindowStyle','modal');
        gl_NotchPeak = uigridlayout(dlg_NotchPeak, [9 6]);
        gl_NotchPeak.RowHeight = {'fit','1x','1x','1x','1x','1x','1x','1x','1x'};
        gl_NotchPeak.ColumnWidth = {140,'1x','1x','1x','1x',140};
        gl_NotchPeak.Padding = [10 10 10 10];
        
        % 说明文本（示例/格式提示）
        ExplanatoryText = sprintf(['%s参数设置说明（详细信息请参阅MATLAB帮助文档）：\n \n' ...
            '1. %s类型：支持单频率%s、多频率%s、梳状%s。根据不同类型启用或禁用后续相关的输入框。\n \n' ...
            '2. 滤波器阶数 N：2(默认)。必须为偶数非负整数。高阶数通常意味着更陡峭的过渡带。单频率%s、多频率%s将使用该参数。\n \n' ...
            '3. 单频中心频率 (Hz)：标量。若使用3dB带宽 bw 参数，则范围为[0, Nyq]；若使用品质因数 Q 参数，则范围为(0, Nyq]。其中Nyq为奈奎斯特频率。\n \n' ...
            '4. 多频中心频率 (Hz)：向量。若使用3dB带宽 bw 参数，则范围为[0, Nyq]；若使用品质因数 Q 参数，则范围为(0, Nyq]。\n  \n' ...
            '5. 梳状中心频率 (Hz)：标量。范围为(0, Nyq)。\n  \n' ...
            '6. 品质因数 Q：2.5(默认)|标量。Q = ω₀ / bw ，Q 值越高，陷波或峰值越窄。ω₀为陷波或峰值的中心频率(rad)。 \n  \n' ...
            '7. 滤波器带宽 bw：无默认值。品质因数 Q 和滤波器带宽 bw 只需指定其中一个，因为它们通过 Q = ω₀ / bw关联。指定更高的 Q 值会产生更窄的带宽。对于单频率%s、多频率%s，bw 为3dB带宽，范围为[0, Nyq]；对于梳状%s，bw 指衰减 ab dB处的带宽，范围为(0, Nyq)，默认为3dB带宽，可通过设置"衰减 ab"自定义。\n  \n' ...
            '8. （可选）衰减 ab：-3(默认)|标量。指定带宽 bw所对应的幅度响应衰减水平（单位：dB）。例如，若设置 ab=6，则 bw表示的是衰减-6dB处的带宽。设计梳状滤波器时可选择使用该参数。\n  \n' ...
            '9. 输入各个参数向量时，不要加方括号[]，使用半角逗号或空格分隔。\n  \n' ...
            '10. 退出设置窗口后，设置好的参数可以在下方参数显示栏查看。'],uiWord,uiWord,uiWord,uiWord,uiWord,uiWord,uiWord,uiWord,uiWord,uiWord);
        % 说明文本
        lblTitle = uilabel(gl_NotchPeak, 'Text',ExplanatoryText);
        lblTitle.Layout.Row = 1; lblTitle.Layout.Column = [1 6];
        lblTitle.WordWrap = 'on';
                    
        S_Fs_Text = sprintf('采样率：%d Hz', S.fs);      
        lblS_Fs = uilabel(gl_NotchPeak,'Text',S_Fs_Text,'FontWeight','bold'); lblS_Fs.Layout.Row = 2; lblS_Fs.Layout.Column = [1 3];     
        Nyq_Text = sprintf('Nyq：%d Hz', nyq);     
        lblNyq = uilabel(gl_NotchPeak,'Text',Nyq_Text,'FontWeight','bold'); lblNyq.Layout.Row = 2; lblNyq.Layout.Column = [4 6];

        % 类型下拉：按 mode 改变显示文本
        lblType_NotchPeak = uilabel(gl_NotchPeak,'Text', sprintf('%s类型:', uiWord),'FontWeight','bold'); lblType_NotchPeak.Layout.Row=3; lblType_NotchPeak.Layout.Column=1;
        items = {sprintf('单频率%s', uiWord), sprintf('多频率%s', uiWord), sprintf('梳状%s', uiWord)};
        ddNPType = uidropdown(gl_NotchPeak, 'Items', items, 'Value', items{1});
        ddNPType.Layout.Row = 3; ddNPType.Layout.Column = [2 3];
    
        % 阶数
        lblOrder = uilabel(gl_NotchPeak,'Text','滤波器阶数 N:','FontWeight','bold'); lblOrder.Layout.Row=3; lblOrder.Layout.Column=4;
        edtOrder = uieditfield(gl_NotchPeak,'numeric','Value',2,'Limits',[1 200],'RoundFractionalValues','on');
        edtOrder.Layout.Row=3; edtOrder.Layout.Column=[5 6];
        if strcmpi(mode,'peak')
            handles.PeakOrder = edtOrder;
        elseif strcmpi(mode,'notch')
            handles.NotchOrder = edtOrder;
        end


        % 单频中心频率（Hz）
        lblCF = uilabel(gl_NotchPeak,'Text',sprintf('单频中心频率 (Hz):'),'FontWeight','bold'); lblCF.Layout.Row=4; lblCF.Layout.Column=1;
        edtCF = uieditfield(gl_NotchPeak,'numeric','Value',nyq/10,'Limits',[1e-6, nyq]);
        edtCF.Layout.Row=4; edtCF.Layout.Column=[2 3];
    
        % 多频中心频率（文本向量，逗号分隔）
        lblCFs = uilabel(gl_NotchPeak,'Text',sprintf('多频中心频率 (Hz):'),'FontWeight','bold'); lblCFs.Layout.Row=5; lblCFs.Layout.Column=1;
        edtCFs = uieditfield(gl_NotchPeak,'text','Value',sprintf('%d, %d',round(S.fs/88),round(S.fs/44)),'Tooltip',sprintf('例如：%d, %d',round(S.fs/88),round(S.fs/44)));
        edtCFs.Layout.Row=5; edtCFs.Layout.Column=[2 6];
    
        % 梳状中心频率（Hz）
        lblCombCF = uilabel(gl_NotchPeak,'Text',sprintf('梳状中心频率 (Hz):'),'FontWeight','bold'); lblCombCF.Layout.Row=6; lblCombCF.Layout.Column=1;
        edtCombCF = uieditfield(gl_NotchPeak,'numeric','Value',nyq/10,'Limits',[1e-6, nyq]);
        edtCombCF.Layout.Row=6; edtCombCF.Layout.Column=[2 3];
    
        % ---------- 新：Bandwidth 设置（替代原来的单一 Q 控件） ----------
        lblBW = uilabel(gl_NotchPeak,'Text','滤波器带宽 bw 设置：','FontWeight','bold'); lblBW.Layout.Row=7; lblBW.Layout.Column=1;
        ddBWMode = uidropdown(gl_NotchPeak,'Items',{'直接指定 bw (Hz)','设置品质因数 Q'}, 'Value','设置品质因数 Q');
        ddBWMode.Layout.Row=7; ddBWMode.Layout.Column=[2 3];
        % 使用 text 类型以便能显示空白（当用户切换到直接指定 bw 时置为空）
        edtBWValue = uieditfield(gl_NotchPeak,'text','Value','2.5','Tooltip','若选择 Q 请填写 Q（>0）；若选择 bw 请填写 bw(Hz)（示例：50）');
        edtBWValue.Layout.Row=7; edtBWValue.Layout.Column=[4 6];
    
        % Q/bw 解析与启用由 ddBWMode 控制（在后面设置回调）
    
        % Q（兼容历史）—— 保留但隐藏/禁用（不在 UI 出现），以免破坏旧代码读取
        % lblQ = uilabel(gl_NotchPeak,'Text','品质因数 Q:','FontWeight','bold'); lblQ.Layout.Row=7; lblQ.Layout.Column=1;
        % edtQ = uieditfield(gl_NotchPeak,'numeric','Value',2.5,'Limits',[0.01 1e5]);
        % edtQ.Layout.Row=7; edtQ.Layout.Column=[2 3];
    
        % 可选 衰减 ab(dB)（用于梳状 iircomb）
        cbUseAb = uicheckbox(gl_NotchPeak,'Text','衰减 ab(dB)(仅梳状):','Value',false,'FontWeight','bold');
        cbUseAb.Layout.Row=8; cbUseAb.Layout.Column=1;
        edtAb = uieditfield(gl_NotchPeak,'numeric','Value',-3,'Limits',[-200 0],'Enable','off');
        edtAb.Layout.Row=8; edtAb.Layout.Column=[2 3];
    
        % 确认 / 取消
        btnConfirm = uibutton(gl_NotchPeak,'push','Text','确认','ButtonPushedFcn',@(~,~) onConfirm());
        btnConfirm.Layout.Row=9; btnConfirm.Layout.Column=[1 3];
        btnCancel = uibutton(gl_NotchPeak,'push','Text','取消','ButtonPushedFcn',@(~,~) onCancel());
        btnCancel.Layout.Row=9; btnCancel.Layout.Column=[4 6];
       
        % 下拉改变时更新启用状态
        ddNPType.ValueChangedFcn = @(src,evt) updateEnableStates();
    
        % ddBWMode 切换回调（Q->bw 自动填充/清空）
        ddBWMode.ValueChangedFcn = @(src,evt) onBWModeChanged(src);

        % 复选框控制 edtAb
        cbUseAb.ValueChangedFcn = @(src,evt) setAbEnable(src);

        % 窗口创建完成后调用一次以保证初始状态正确
        updateEnableStates();
        onBWModeChanged(ddBWMode);

        % 阻塞直到窗口关闭（严格模态）
        uiwait(dlg_NotchPeak);
        updateNote(S, handles);        
            
       % ---------------- 启用/禁用逻辑 ----------------
        function updateEnableStates()
            typVal = ddNPType.Value;
            % 识别类型
            isSingle = contains(typVal,'单');
            isMulti  = contains(typVal,'多');
            isComb   = contains(typVal,'梳');
    
            % 顺序控制
            if isSingle
                edtOrder.Enable = 'on';
                lblOrder.Enable = 'on';
                edtCF.Enable = 'on';
                lblCF.Enable = 'on';
                edtCFs.Enable = 'off';
                lblCFs.Enable = 'off';
                edtCombCF.Enable = 'off';
                lblCombCF.Enable = 'off';
                ddBWMode.Enable = 'on';
                lblBW.Enable = 'on';
                edtBWValue.Enable = 'on';
                cbUseAb.Enable = 'off';
                edtAb.Enable = 'off';
            elseif isMulti
                edtOrder.Enable = 'on';
                lblOrder.Enable = 'on';
                edtCF.Enable = 'off';
                lblCF.Enable = 'off';
                edtCFs.Enable = 'on';
                lblCFs.Enable = 'on';
                edtCombCF.Enable = 'off';
                lblCombCF.Enable = 'off';
                ddBWMode.Enable = 'on';
                lblBW.Enable = 'on';
                edtBWValue.Enable = 'on';
                cbUseAb.Enable = 'off';
                edtAb.Enable = 'off';
            elseif isComb
                edtOrder.Enable = 'off';
                lblOrder.Enable = 'off';
                edtCF.Enable = 'off';
                lblCF.Enable = 'off';
                edtCFs.Enable = 'off';
                lblCFs.Enable = 'off';
                edtCombCF.Enable = 'on';
                lblCombCF.Enable = 'on';
                ddBWMode.Enable = 'on';
                lblBW.Enable = 'on';
                edtBWValue.Enable = 'on';
                cbUseAb.Enable = 'on';
                % cbUseAb 控制 edtAb
                if cbUseAb.Value
                    edtAb.Enable = 'on';
                else
                    edtAb.Enable = 'off';
                end
            else
                % 兜底：全部禁用
                edtOrder.Enable = 'off';
                lblOrder.Enable = 'off';
                edtCF.Enable = 'off';
                lblCF.Enable = 'off';
                edtCFs.Enable = 'off';
                lblCFs.Enable = 'off';
                edtCombCF.Enable = 'off';
                lblCombCF.Enable = 'off';
                ddBWMode.Enable = 'off';
                lblBW.Enable = 'off';
                edtBWValue.Enable = 'off';
                cbUseAb.Enable = 'off';
                edtAb.Enable = 'off';
            end
        end
    
        function onBWModeChanged(src)
            if strcmpi(src.Value, '设置品质因数 Q')
                edtBWValue.Value = '2.5'; % 默认 Q
            else
                edtBWValue.Value = '';    % 置空，供用户填写 bw(Hz)
            end
        end
    
        function setAbEnable(src)
            if src.Value
                edtAb.Enable = 'on';
            else
                edtAb.Enable = 'off';
            end
        end
    
        % ----------------- 确认回调 -----------------
        function onConfirm()
            typVal = ddNPType.Value;
            % map type
            if contains(typVal,'单'), typeKey = 'single';
            elseif contains(typVal,'多'), typeKey = 'multi';
            else; typeKey = 'comb';
            end
    
            % 基本数值
            order = round(double(edtOrder.Value));
    
            % 解析频率向量
            try
                switch typeKey
                    case 'single'
                        fvec = double(edtCF.Value);
                    case 'multi'
                        s = strtrim(edtCFs.Value);
                        if isempty(s), error('多频中心频率为空'); end
                        if contains(s, '[') || contains(s, ']')
                            uialert(dlg_NotchPeak,'多频中心频率 f 解析失败，请不要在输入中包含方括号"["或"]"，直接输入数字列表（用半角逗号或空格分隔）。','参数错误'); 
                            return; 
                        end
                        fvec =  str2num(['[', strrep(s,',',' '), ']']); %#ok<ST2NM>
                        if isempty(fvec), uialert(dlg_NotchPeak,'多频中心频率 f 解析失败，请按示例输入（半角逗号或空格分隔的数字列表）。','参数错误'); return; end
                    case 'comb'
                        fvec = double(edtCombCF.Value);
                    otherwise
                        uialert(dlg_NotchPeak,'未知类型','错误'); return;
                end
            catch
                uialert(dlg_NotchPeak,'多频中心频率解析失败，请用半角逗号分隔数值，例如 50,60','参数错误'); return;
            end
    
            % 带宽模式解析（文本输入先转数值）
            bwMode = 'Q'; bwVal = NaN;
            if strcmpi(ddBWMode.Value, '设置品质因数 Q')
                % 解析为 Q（必须 > 0）
                qstr = strtrim(edtBWValue.Value);
                qnum = str2double(qstr);
                if isnan(qnum) || ~(qnum>0)
                    uialert(dlg_NotchPeak,'请为品质因数 Q 输入一个大于0的数值（例如 2.5）','参数错误'); return;
                end
                bwMode = 'Q'; bwVal = qnum;
            else
                % 直接指定 bw (Hz)
                bstr = strtrim(edtBWValue.Value);
                bnum = str2double(bstr);
                if isnan(bnum)
                    uialert(dlg_NotchPeak,'请为带宽 bw(Hz) 输入数值（例如 50）','参数错误'); return;
                end
                bwMode = 'bw'; bwVal = bnum;
            end
    
            % 验证数值合理性（通用）
            if any(~isfinite(fvec)) || any(fvec<0) || any(fvec>nyq + eps)
                % 对 single/multi 的要求稍后根据 bwMode 再细化
                if ~strcmpi(typeKey,'comb')
                    % single/multi 初步检测：若使用 Q 则允许 f==Nyq，若使用 bw 则允许 f==0..Nyq（按你的要求）
                    uialert(dlg_NotchPeak, sprintf('中心频率至少需要满足 0 <= f <= %g (Nyquist)。', nyq),'参数错误'); return;
                else
                    uialert(dlg_NotchPeak, sprintf('梳状中心频率必须满足 0 < f < %g (Nyquist)。', nyq),'参数错误'); return;
                end
            end
    
            % 阶数校验：单/多频必须为偶数正整数；（你要求单/多时 N 为偶数非负整数）
            if any(strcmpi(typeKey, {'single','multi'}))
                if order < 1 || order > 200
                    uialert(dlg_NotchPeak, '阶数不合理（应在 1..200）','参数错误'); return;
                end
                if rem(order,2)~=0
                    uialert(dlg_NotchPeak, '阶数 N 必须为偶数。','参数错误'); return;
                end
            else
                % comb 模式不使用 order（忽略）
                % 还是做个防护
                if ~(order >= 0 && order <= 200)
                    % 允许 0 但在 comb 模式下不使用
                    order = max(0, min(200, order));
                end
            end
    
            % 根据 typeKey 与 bwMode 做更详细的校验（满足你提出的规则）
            if strcmpi(typeKey,'single') || strcmpi(typeKey,'multi')
                % 若 bwMode == 'bw'，中心频率范围允许 [0, Nyq]（边界可取等）
                if strcmpi(bwMode,'bw')
                    if bwVal < 0 || bwVal > nyq
                        uialert(dlg_NotchPeak, sprintf('当选择直接指定 bw(Hz) 时，bw 必须在 [0, %g] 范围内。', nyq),'参数错误'); return;
                    end
                    
                    if any(fvec < 0) || any(fvec > nyq)
                        uialert(dlg_NotchPeak, sprintf('当选择直接指定 bw(Hz) 时，中心频率必须满足 0 <= f <= %g (Nyquist)。', nyq),'参数错误'); return;
                    end
                else
                    % bwMode == 'Q'，Q 必须 > 0；中心频率范围为 (0, Nyq]（左边界不可取等）
                    if bwVal <= 0
                        uialert(dlg_NotchPeak, '品质因数 Q 必须大于 0','参数错误'); return;
                    end
                    if any(fvec <= 0) || any(fvec > nyq)
                        uialert(dlg_NotchPeak, sprintf('当选择 Q 时，中心频率必须满足 0 < f <= %g (Nyquist)。', nyq),'参数错误'); return;
                    end
                end
            else
                % comb 模式的校验 (5.1)-(5.4)
                fcomb = fvec(1);
                if ~(isfinite(fcomb) && fcomb>0 && fcomb<nyq)
                    uialert(dlg_NotchPeak, sprintf('梳状中心频率必须满足 0 < f < %g (Nyquist)。', nyq),'参数错误'); return;
                end
                Ncomb_real = S.fs / fcomb;
                if Ncomb_real > 512
                    uialert(dlg_NotchPeak, sprintf('由fs/f计算得到的滤波器阶数过大：%g > 512。请调整采样率或者中心频率，使得滤波器阶数小于512。', Ncomb_real),'参数错误'); return;
                end
                if strcmpi(bwMode,'bw')
                    if ~(bwVal>0 && bwVal<nyq)
                        uialert(dlg_NotchPeak, sprintf('梳状模式下直接指定 bw(Hz) 时，bw 必须在 (0, %g) 范围内（边界不可取）。', nyq),'参数错误'); return;
                    end
                else
                    if bwVal <= 0
                        uialert(dlg_NotchPeak, '梳状模式下选择 Q 时，Q 必须 > 0','参数错误'); return;
                    end
                end
                if cbUseAb.Value
                    abVal = double(edtAb.Value);
                    if ~(isfinite(abVal) && abVal < 0)
                        uialert(dlg_NotchPeak, '若勾选 衰减 ab，则 ab(dB) 必须小于 0','参数错误'); return;
                    end
                end
            end
    
            % 如果一切通过 -> 统一保存参数结构（mode: 'notch' 或 'peak'）
            p = struct();
            p.mode = mode;        % 'notch' or 'peak'
            p.type = typeKey;     % 'single' / 'multi' / 'comb'
            p.typeLabel = typVal;
            p.order = order;
            p.f = double(fvec(:).');   % 行向量
            p.bwMode = bwMode;        % 'bw' or 'Q'
            p.bwValue = double(bwVal);
            p.useAb = cbUseAb.Value;
            if p.useAb
                p.ab = double(edtAb.Value);
            else
                p.ab = [];
            end
    
            % 保留历史
            if ~isprop(handles,'notchPeakParamsHistory') || isempty(handles.notchPeakParamsHistory)
                handles.notchPeakParamsHistory = {};
            end
            handles.notchPeakParamsHistory{end+1} = p;
            handles.notchPeakParams = p;
    
            % % 尝试用 guidata 写回（若你的 GUI 使用 guidata）
            % try
            %     guidata(parentFig, handles);   % 将修改写回主界面 handles
            % catch
            % 
            % end
    
            setStatus(handles,sprintf('%s 参数已保存（%s）', uiWord, typVal));
            % 刷新界面、绘图等
            updateDesignLabel(S, handles);
            updateNote(S, handles);
                
            % 结束 uiwait 并关闭对话框
            try
                if isvalid(dlg_NotchPeak)
                    uiresume(dlg_NotchPeak); 
                    delete(dlg_NotchPeak); 
                end
            catch
                try delete(dlg_NotchPeak); catch; end
            end
         
        end
    
        % ----------------- 取消回调 -----------------
        function onCancel()
            close(dlg_NotchPeak);
        end
    end

    %% ---- “设计滤波器”按钮回调 ----
    function onDesignFilter(~,~)
        method = handles.ddDesignMethod.Value; type = handles.ddType.Value;
        % 获取通带/阻带值
        fp1 = handles.edtPb1.Value; fp2 = handles.edtPb2.Value;
        fst1 = handles.edtSb1.Value; fst2 = handles.edtSb2.Value;
        nyq = S.fs/2;

        % ================================================================== 处理 陷波 / 峰值滤波 ============================================================================================
        if strcmp(method, '陷波') || strcmp(method, '峰值滤波')
            % 检查是否已设置参数
            if isempty(handles.notchPeakParams)
                uialert(fig_GUI, '请先点击"陷波or峰值滤波参数"并设置参数。','参数缺失');
                setStatus(handles,'设计失败：缺少陷波/峰值参数'); return;
            end
            % ===== 在 onDesignFilter 中，取出保存的参数 p =====
            p = handles.notchPeakParams;
            if isempty(p)
                uialert(fig_GUI, '请先点击"陷波or峰值滤波参数"并设置参数。','参数缺失');
                return;
            end

            if strcmp(method, '陷波') && ~strcmpi(p.mode,'notch') 
                if exist('uialert_safe','file'), uialert_safe(fig_GUI,'请先点击"陷波or峰值滤波参数"并设置参数。','参数缺失'); else; uialert(fig_GUI,'请先点击"陷波or峰值滤波参数"并设置参数。','参数缺失'); end
                setStatus(handles,'设计失败：缺少陷波参数'); return;
            end

            if strcmp(method, '峰值滤波') && ~strcmpi(p.mode,'peak') 
                if exist('uialert_safe','file'), uialert_safe(fig_GUI,'请先点击"陷波or峰值滤波参数"并设置参数。','参数缺失'); else; uialert(fig_GUI,'请先点击"陷波or峰值滤波参数"并设置参数。','参数缺失'); end
                setStatus(handles,'设计失败：缺少峰值滤波参数'); return;
            end

            % resp 用于 designNotchPeakIIR
            if isfield(p,'mode') && strcmpi(p.mode,'peak') 
                resp = 'peak';
            else
                resp = 'notch';
            end
            
            % 初始化总系数
            b_total = 1; a_total = 1;
            
            % 在获取 p = handles.notchPeakParams 后，进入 switch p.type
            switch p.type
                case 'single'
                    f0 = double(p.f(1));
                    cf_norm = f0 / (S.fs/2);  % CenterFrequency 相对于 Nyquist (0..1)
                    try
                        if strcmpi(p.bwMode,'Q')
                            % 使用 Q
                            Quse = double(p.bwValue);
                            if ~(isfinite(Quse) && Quse>0)
                                uialert(fig_GUI,'品质因数 Q 不合法，请检查输入','参数错误'); return;
                            end
                            % 调用 designNotchPeakIIR 使用 QualityFactor
                            [Bsec,Asec,sv] = designNotchPeakIIR(Response=resp, ...
                                                               FilterOrder=p.order, ...
                                                               CenterFrequency=cf_norm, ...
                                                               QualityFactor=Quse, ...
                                                               HasScaleValues=true);
                        else
                            % 使用 Bandwidth（用户以 Hz 指定），需归一化到 [0,1]（相对于 Nyquist）
                            bwHz = double(p.bwValue);
                            bw_norm = bwHz / (S.fs/2); % Bandwidth 文档要求的归一化值
                            % 校验（bw_norm 必须在 [0,1] 才能合理传入 designNotchPeakIIR）
                            if ~(isfinite(bw_norm) && bw_norm>=0 && bw_norm<=1)
                                uialert(fig_GUI, sprintf('带宽 bw(Hz) 转换得到的归一化值 bw_norm=%.6g 不合法（需在 [0,1]）。请检查 bw 输入与采样率。', bw_norm), '参数错误');
                                return;
                            end
                            % 直接使用 Bandwidth 参数（3-dB 带宽，归一化）
                            [Bsec,Asec,sv] = designNotchPeakIIR(Response=resp, ...
                                                               FilterOrder=p.order, ...
                                                               CenterFrequency=cf_norm, ...
                                                               Bandwidth=bw_norm, ...
                                                               HasScaleValues=true);
                        end
                    catch ME
                        uialert(fig_GUI, sprintf('designNotchPeakIIR 失败：%s', ME.message), '错误'); return;
                    end
            
                    % 处理返回（保持你原来的 sos / tf 兼容）
                    if size(Bsec,1) == 1
                        bseg = Bsec(:).';
                        aseg = Asec(:).';
                    else
                        sos = [Bsec Asec];
                        [bseg, aseg] = sos2tf(sos, sv);
                    end
                    b_total = conv(b_total, bseg);
                    a_total = conv(a_total, aseg);
                    % === 在 case 'single' 中，确保 bk_cell/ak_cell 可用（统一格式） ===
                    bk_cell = { real(trim_poly(bseg)) };   % 单节也用 cell 存放
                    ak_cell = { real(trim_poly(aseg)) };

            
                case 'multi'
                    K = length(p.f);
                    % 为每个中心频率设计 b_k, a_k（与之前相同）
                    bk_cell = cell(1,K);
                    ak_cell = cell(1,K);
            
                    for k = 1:K
                        f0 = double(p.f(k));
                        cf_norm = f0 / (S.fs/2);
                        try
                            if strcmpi(p.bwMode,'Q')
                                Quse = double(p.bwValue);
                                if ~(isfinite(Quse) && Quse>0)
                                    uialert(fig_GUI, sprintf('第 %d 个频点：品质因数 Q 不合法，请检查输入', k),'参数错误'); return;
                                end
                                [Bsec,Asec,sv] = designNotchPeakIIR(Response=resp, ...
                                                                   FilterOrder=p.order, ...
                                                                   CenterFrequency=cf_norm, ...
                                                                   QualityFactor=Quse, ...
                                                                   HasScaleValues=true);
                            else
                                bwHz = double(p.bwValue);
                                bw_norm = bwHz / (S.fs/2);
                                if ~(isfinite(bw_norm) && bw_norm>0 && bw_norm<=1)
                                    uialert(fig_GUI, sprintf('第 %d 个频点：带宽 bw(Hz) 转化得到 bw_norm=%.6g 不合法（需在 (0,1]）。', k, bw_norm),'参数错误'); return;
                                end
                                [Bsec,Asec,sv] = designNotchPeakIIR(Response=resp, ...
                                                                   FilterOrder=p.order, ...
                                                                   CenterFrequency=cf_norm, ...
                                                                   Bandwidth=bw_norm, ...
                                                                   HasScaleValues=true);
                            end
                        catch ME
                            uialert(fig_GUI, sprintf('designNotchPeakIIR 第 %d 个频率失败：%s', k, ME.message), '错误'); return;
                        end
            
                        % 将 SOS 或单节转换为 b,a
                        if size(Bsec,1) == 1
                            bseg = Bsec(:).';
                            aseg = Asec(:).';
                        else
                            sos = [Bsec Asec];
                            [bseg, aseg] = sos2tf(sos, sv);
                        end
                        bk_cell{k} = real(trim_poly(bseg));
                        ak_cell{k} = real(trim_poly(aseg));
                    end
            
                    % notch：级联（原有逻辑）
                    if strcmpi(p.mode,'notch')
                        b_total = 1; a_total = 1;
                        for k = 1:K
                            b_total = conv(b_total, bk_cell{k});
                            a_total = conv(a_total, ak_cell{k});
                        end
                        % 归一化并清理
                        [b_total, a_total] = normalize_and_trim(b_total, a_total);
            
                    else
                    % peak：并联合成 H_total = 1 + sum_k (Hk - 1) = sum_k(Hk) - (K-1)
                        % 优先使用用户提供的 combine_parallel_filters_tf（需 Control System Toolbox）
                        use_combine = exist('combine_parallel_filters_tf','file') == 2;
                        if use_combine
                            try
                                [b_sum, a_sum] = combine_parallel_filters_tf(bk_cell, ak_cell); % sum(Hk)
                                % H_total = sum(Hk) - (K-1)
                                % => b_total / a_total = (b_sum / a_sum) - (K-1) = (b_sum - (K-1)*a_sum) / a_sum
                                b_total = b_sum - (K-1) * a_sum;
                                a_total = a_sum;
                                [b_total, a_total] = normalize_and_trim(b_total, a_total);
                            catch ME
                                % 若 combine 出问题，降级到纯代数合成（见下）
                                warning('onDesignFilter:combine_parallel_filters_tfFailed','combine_parallel_filters_tf 运行失败，改用代数合成法：%s', ME.message);
                                use_combine = false;
                            end
                        end
            
                        if ~use_combine
                            % 代数合成（严格等价 H_total = prod A + sum_k ((B_k-A_k)*prod_{j~=k} A_j)） 
                            % 与之前我给出的代数实现相同（作为回退）
                            denom = 1;
                            for k = 1:K
                                denom = conv(denom, ak_cell{k});
                            end
            
                            sum_terms = zeros(1, length(denom));
                            for k = 1:K
                                others = 1;
                                for j = 1:K
                                    if j~=k
                                        others = conv(others, ak_cell{j});
                                    end
                                end
            
                                bk = bk_cell{k}; ak = ak_cell{k};
                                L = max(length(bk), length(ak));
                                bkP = [zeros(1, L-length(bk)), bk];
                                akP = [zeros(1, L-length(ak)), ak];
                                diffBA = bkP - akP;
                                term = conv(diffBA, others);
            
                                if length(term) < length(denom)
                                    term = [zeros(1, length(denom)-length(term)), term];
                                elseif length(term) > length(denom)
                                    sum_terms = [zeros(1, length(term)-length(sum_terms)), sum_terms];
                                    denom = [zeros(1, length(term)-length(denom)), denom];
                                end
                                sum_terms = sum_terms + term;
                            end
            
                            if length(denom) > length(sum_terms)
                                sum_terms = [zeros(1, length(denom)-length(sum_terms)), sum_terms];
                            elseif length(sum_terms) > length(denom)
                                denom = [zeros(1, length(sum_terms)-length(denom)), denom];
                            end
                            num_total = denom + sum_terms; % = prod A_k + sum_terms
                            % 但上面得到的 num_total/denom 实际等于 sum_k Hk - (K-1)
                            b_total = num_total;
                            a_total = denom;
                            [b_total, a_total] = normalize_and_trim(b_total, a_total);
                        end
                    end

            
                case 'comb'
                    % comb 分支保持原有 iircomb 逻辑（不变）
                    fcomb = double(p.f(1));
                    Ncomb_real = S.fs / fcomb;
                    Ncomb = max(1, round(Ncomb_real));
                    if abs(Ncomb - Ncomb_real) > 1e-6
                        warndlg(sprintf('fs/fo = %.4f，已取整 N=%d。若需严格对齐，请保证 fs/fo 为整数', Ncomb_real, Ncomb), 'iircomb 警告');
                    end
                    if strcmpi(p.bwMode,'Q')
                        Qval = double(p.bwValue);
                        bw_norm = (fcomb / (S.fs/2)) / Qval;  % 保留原逻辑
                    else
                        bwHz = double(p.bwValue);
                        bw_norm = bwHz / (S.fs/2);
                    end
                    if ~(bw_norm>0 && bw_norm<1)
                        uialert(fig_GUI, sprintf('计算得到 bw_norm=%.6g 不合法，请检查 Q 或 bw', bw_norm), '参数错误'); return;
                    end
                    try
                        if isfield(p,'useAb') && p.useAb && ~isempty(p.ab)
                            [num,den] = iircomb(Ncomb, bw_norm, p.ab, resp); % resp -> 'notch'/'peak'
                        else
                            [num,den] = iircomb(Ncomb, bw_norm, resp);
                        end
                    catch ME
                        uialert(fig_GUI, sprintf('iircomb 失败：%s', ME.message),'错误'); return;
                    end
                    b_total = conv(b_total, num);
                    a_total = conv(a_total, den);
            
                otherwise
                    uialert(fig_GUI,'未知的陷波/峰值类型','错误'); return;
            end

            % === 新增：将每节系数保存到 handles.notchPeakFilters（供 onApplyFilter 优先逐节应用） ===
            try
                nf = [];
                if exist('bk_cell','var') && exist('ak_cell','var') && ~isempty(bk_cell)
                    nf.bk = bk_cell;
                    nf.ak = ak_cell;
                    % 记录模式：p.mode 在 multi/peak/notch 分支中有意义
                    if isfield(p,'mode')
                        nf.mode = p.mode;   % 'notch' 或 'peak'
                    else
                        % single 情况下，保持 p.type 用意，mode 也可设为 'notch'（或根据 UI 设定）
                        nf.mode = 'notch';
                    end
                    nf.K = numel(bk_cell);
                elseif exist('bseg','var') && exist('aseg','var')
                    % 兜底：若只产生 bseg/aseg （single 情况），也包装成 cell
                    nf.bk = { real(trim_poly(bseg)) };
                    nf.ak = { real(trim_poly(aseg)) };
                    nf.mode = 'notch';
                    nf.K = 1;
                end
            
                if ~isempty(nf)
                    % 默认不使用合并的单一传递函数来 apply（满足你的要求）
                    nf.useCombinedForApply = false;
                    % 将结构写回 handles（并持久化）
                    handles.notchPeakFilters = nf;
                    % try
                    %     guidata(fig_GUI, handles);  % 若你用 guidata 管理 handles
                    % catch
                    %     % 若不使用 guidata，可改为：setappdata(fig_GUI,'handles',handles); 或你的项目写回方式
                    %     % setappdata(fig_GUI, 'handles', handles);
                    % end
                end
            catch ME
                warning('onDesignFilter:SavenotchPeakFiltersFailed','保存 notchPeakFilters 失败: %s', ME.message);
            end

    
            % 保存最终系数供后续分析
            S.filter_b = b_total(:).';
            S.filter_a = a_total(:).';

            % 启用应用按钮
            S.filterIsDesigned = true;
            % 设计滤波器成功后，启用 下拉 + 查看 按钮
            handles.ddFilterAnalysis.Enable = 'on';
            handles.btnViewFilterAnalysis.Enable = 'on';
            % 启用前后向滤波选项
            handles.ddFilterFunction.Enable = 'on';
            % 启动保存图像按钮
            handles.btnSaveFigs.Enable = 'on';

            updateApplyButtonEnable(S.filterIsDesigned, S.allowApplyFilter, handles);

            % 更新设计方法提示标签并同步状态栏
            updateDesignLabel(S, handles);  
            % 刷新界面、绘图等（复用原逻辑）
            updateNote(S, handles);
            % 更新滤波器响应绘图与状态
            updateFilterResponsePlots(S, handles);
            setStatus(handles,sprintf('%s 设计完成（%s）', method, p.type));
            return; % 处理完成，跳过原有设计分支
        end



        % ================================================================================== 处理多带/高级设计 ===============================================================================================
        if strcmp(type, '多带/高级')
            nyq = S.fs/2;
            % 允许情况：
            allowMulti = false;
            if strcmpi(method, 'FIR优化设计法') || strcmpi(method, 'FIR频率采样法') || strcmpi(method, 'FIRintfilt插值') || strcmp(method, 'FIRgaussdesign脉冲整形') || ...
                strcmp(method, 'FIRrcosdesign脉冲整形') || strcmp(method, 'Savitzky-Golay')

                allowMulti = true;
            end

            % 允许 IIR + Yule-Walker
            if strcmpi(method,'IIR') && isprop(handles,'ddIIRProto') && strcmpi(handles.ddIIRProto.Value,'Yule-Walker')
                allowMulti = true;
            end

            % 允许 IIR + maxflat
            if strcmpi(method,'IIR') && isprop(handles,'ddIIRProto') && strcmpi(handles.ddIIRProto.Value,'maxflat')
                allowMulti = true;
            end

            if ~allowMulti
                if exist('uialert_safe','file')
                    uialert_safe(fig_GUI,'多带/高级仅在 FIR优化设计法、FIR频率采样法、IIR-Yule-Walker、IIR-maxflat、FIRintfilt插值、FIRgaussdesign脉冲整形、FIRrcosdesign脉冲整形、Savitzky-Golay 下支持。','参数错误');
                else
                    uialert(fig_GUI,'多带/高级仅在 FIR优化设计法、FIR频率采样法、IIR-Yule-Walker、IIR-maxflat、FIRintfilt插值、FIRgaussdesign脉冲整形、FIRrcosdesign脉冲整形、Savitzky-Golay 下支持。','参数错误'); 
                end
                setStatus(handles,'设计失败：多带/高级不支持此方法'); 
                return;
            end

            % % 检查是否存在已保存参数
            % allowMultiParams = (strcmpi(method, 'FIR优化设计法') && ~strcmpi(handles.ddFIRMethod.Value,'约束最小二乘1(fircls1)')) ;
            % if  allowMultiParams && isprop(handles,'multiBandParams') && isempty(handles.multiBandParams) 
            %     if strcmpi(method, 'FIR优化设计法') 
            %         if exist('uialert_safe','file'), uialert_safe(fig_GUI,sprintf('请先点击"多带/高级滤波参数"并设置 %s 的参数。',handles.ddFIRMethod.Value),'参数缺失'); else; uialert(fig_GUI,sprintf('请先点击"多带/高级滤波参数"并设置 %s 的参数。',handles.ddFIRMethod.Value),'参数缺失'); end
            %     else
            %          if exist('uialert_safe','file'), uialert_safe(fig_GUI,sprintf('请先点击"多带/高级滤波参数"并设置 %s 的参数。',method),'参数缺失'); else; uialert(fig_GUI,sprintf('请先点击"多带/高级滤波参数"并设置参数。'),'参数缺失'); end
            %     end
            %     setStatus(handles,'设计滤波器失败：缺少多带/高级参数'); 
            %     return;
            % end
            
            % ----- IIR+yulewalk：检查是否存在已保存参数 -----
            if strcmp(method,'IIR') && isprop(handles,'ddIIRProto') && strcmpi(handles.ddIIRProto.Value,'Yule-Walker') && isprop(handles,'yuleWalkParams') && isempty(handles.yuleWalkParams)
                if exist('uialert_safe','file')
                    uialert_safe(fig_GUI,sprintf('请先点击"多带/高级滤波参数"并设置 %s 的参数。',handles.ddIIRProto.Value),'参数缺失'); 
                else
                    uialert(fig_GUI,sprintf('请先点击"多带/高级滤波参数"并设置 %s 的参数。',handles.ddIIRProto.Value),'参数缺失'); 
                end
                   setStatus(handles,'设计滤波器失败：缺少多带/高级参数'); 
                return;
            end

            % ----- IIR+maxflat：检查是否存在已保存参数 -----
            if strcmp(method,'IIR') && isprop(handles,'ddIIRProto') && strcmpi(handles.ddIIRProto.Value,'maxflat') && isprop(handles,'maxflatParams') && isempty(handles.maxflatParams)
                if exist('uialert_safe','file')
                    uialert_safe(fig_GUI,sprintf('请先点击"多带/高级滤波参数"并设置 %s 的参数。',handles.ddIIRProto.Value),'参数缺失'); 
                else
                    uialert(fig_GUI,sprintf('请先点击"多带/高级滤波参数"并设置 %s 的参数。',handles.ddIIRProto.Value),'参数缺失'); 
                end
                   setStatus(handles,'设计滤波器失败：缺少多带/高级参数'); 
                return;
            end

            % ----- FIR频率采样法：检查是否存在已保存参数 -----
            if strcmpi(method, 'FIR频率采样法')  && isprop(handles,'fir2Params') && isempty(handles.fir2Params)
                if exist('uialert_safe','file')
                    uialert_safe(fig_GUI,sprintf('请先点击"多带/高级滤波参数"并设置 %s 的参数。',method),'参数缺失'); 
                else
                    uialert(fig_GUI,sprintf('请先点击"多带/高级滤波参数"并设置 %s 的参数。',method),'参数缺失'); 
                end
                   setStatus(handles,'设计滤波器失败：缺少多带/高级参数'); 
                return;
            end
  
            % ----- Parks-McClellan：检查是否存在已保存参数 -----
            if strcmpi(handles.ddDesignMethod.Value, 'FIR优化设计法') &&  strcmpi(handles.ddFIRMethod.Value, 'Parks-McClellan') && isprop(handles,'firpmParams') && isempty(handles.firpmParams)  
                if exist('uialert_safe','file')
                    uialert_safe(fig_GUI,sprintf('请先点击"多带/高级滤波参数"并设置 %s 的参数。',handles.ddFIRMethod.Value),'参数缺失'); 
                else
                    uialert(fig_GUI,sprintf('请先点击"多带/高级滤波参数"并设置 %s 的参数。',handles.ddFIRMethod.Value),'参数缺失'); 
                end
                setStatus(handles,'设计滤波器失败：缺少多带/高级参数'); 
                return;
            end

            % ----- Cplx-Parks-McClellan：检查是否存在已保存参数 -----
            if strcmpi(handles.ddDesignMethod.Value, 'FIR优化设计法') &&  strcmpi(handles.ddFIRMethod.Value, 'Cplx-Parks-McClellan') && isprop(handles,'cfirpmParams') && isempty(handles.cfirpmParams)  
                if exist('uialert_safe','file')
                    uialert_safe(fig_GUI,sprintf('请先点击"多带/高级滤波参数"并设置 %s 的参数。',handles.ddFIRMethod.Value),'参数缺失'); 
                else
                    uialert(fig_GUI,sprintf('请先点击"多带/高级滤波参数"并设置 %s 的参数。',handles.ddFIRMethod.Value),'参数缺失'); 
                end
                setStatus(handles,'设计滤波器失败：缺少多带/高级参数'); 
                return;
            end

            % ----- 最小二乘(firls)：检查是否存在已保存参数 -----
            if strcmpi(handles.ddDesignMethod.Value, 'FIR优化设计法') &&  strcmpi(handles.ddFIRMethod.Value, '最小二乘(firls)') && isprop(handles,'firlsParams') && isempty(handles.firlsParams)  
                if exist('uialert_safe','file')
                    uialert_safe(fig_GUI,sprintf('请先点击"多带/高级滤波参数"并设置 %s 的参数。',handles.ddFIRMethod.Value),'参数缺失'); 
                else
                    uialert(fig_GUI,sprintf('请先点击"多带/高级滤波参数"并设置 %s 的参数。',handles.ddFIRMethod.Value),'参数缺失'); 
                end
                setStatus(handles,'设计滤波器失败：缺少多带/高级参数'); 
                return;
            end

            % ----- 约束最小二乘(fircls)：检查是否存在已保存参数 -----
            if strcmpi(handles.ddDesignMethod.Value, 'FIR优化设计法') &&  strcmpi(handles.ddFIRMethod.Value, '约束最小二乘(fircls)') && isprop(handles,'firclsParams') && isempty(handles.firclsParams)  
                if exist('uialert_safe','file')
                    uialert_safe(fig_GUI,sprintf('请先点击"多带/高级滤波参数"并设置 %s 的参数。',handles.ddFIRMethod.Value),'参数缺失'); 
                else
                    uialert(fig_GUI,sprintf('请先点击"多带/高级滤波参数"并设置 %s 的参数。',handles.ddFIRMethod.Value),'参数缺失'); 
                end
                setStatus(handles,'设计滤波器失败：缺少多带/高级参数'); 
                return;
            end
          
            % ----- 约束最小二乘1(fircls1)：检查是否存在已保存参数 -----
            if strcmpi(handles.ddDesignMethod.Value, 'FIR优化设计法') &&  strcmpi(handles.ddFIRMethod.Value,'约束最小二乘1(fircls1)') && isprop(handles,'fircls1Params') && isempty(handles.fircls1Params)  
                if exist('uialert_safe','file')
                    uialert_safe(fig_GUI,sprintf('请先点击"多带/高级滤波参数"并设置 %s 的参数。',handles.ddFIRMethod.Value),'参数缺失'); 
                else
                    uialert(fig_GUI,sprintf('请先点击"多带/高级滤波参数"并设置 %s 的参数。',handles.ddFIRMethod.Value),'参数缺失'); 
                end
                setStatus(handles,'设计滤波器失败：缺少多带/高级参数'); 
                return;
            end

            % ----- FIRintfilt插值：检查是否存在已保存参数 -----
            if strcmp(method,'FIRintfilt插值')  && isprop(handles,'intfiltParams') && isempty(handles.intfiltParams)
                if exist('uialert_safe','file')
                    uialert_safe(fig_GUI,sprintf('请先点击"多带/高级滤波参数"并设置 %s 的参数。',method),'参数缺失'); 
                else
                    uialert(fig_GUI,sprintf('请先点击"多带/高级滤波参数"并设置 %s 的参数。',method),'参数缺失'); 
                end
                   setStatus(handles,'设计滤波器失败：缺少多带/高级参数'); 
                return;
            end

            % ----- FIRgaussdesign脉冲整形：检查是否存在已保存参数 -----
            if strcmp(method, 'FIRgaussdesign脉冲整形') && isprop(handles,'gaussdesignParams') && isempty(handles.gaussdesignParams)
                if exist('uialert_safe','file'), uialert_safe(fig_GUI, '请先通过"多带 / 高级滤波参数"按钮设置 gaussdesign 参数。', '参数缺失');
                else; uialert(fig_GUI, '请先通过"多带 / 高级滤波参数"按钮设置 gaussdesign 参数。', '参数缺失'); end
                setStatus(handles,'设计滤波器失败：缺少多带/高级参数');
                return;
            end

            % ----- FIRrcosdesign脉冲整形：检查是否存在已保存参数 -----
            if strcmp(method, 'FIRrcosdesign脉冲整形') && isprop(handles,'rcosdesignParams') && isempty(handles.rcosdesignParams)
                if exist('uialert_safe','file'), uialert_safe(fig_GUI, '请先通过"多带 / 高级滤波参数"按钮设置 gaussdesign 参数。', '参数缺失');
                else; uialert(fig_GUI, '请先通过"多带 / 高级滤波参数"按钮设置 rcosdesign 参数。', '参数缺失'); end
                setStatus(handles,'设计滤波器失败：缺少多带/高级参数');
                return;
            end


            % ----- Savitzky-Golay：检查是否存在已保存参数 -----
            if strcmp(method,'Savitzky-Golay')  && isprop(handles,'sgolayParams') && isempty(handles.sgolayParams)
                if exist('uialert_safe','file')
                    uialert_safe(fig_GUI,sprintf('请先点击"多带/高级滤波参数"并设置 %s 的参数。',method),'参数缺失'); 
                else
                    uialert(fig_GUI,sprintf('请先点击"多带/高级滤波参数"并设置 %s 的参数。',method),'参数缺失'); 
                end
                   setStatus(handles,'设计滤波器失败：缺少多带/高级参数'); 
                return;
            end


            try
                % ===================================== FIR优化设计法 多带/高级设计 =====================================
                if strcmpi(method, 'FIR优化设计法')
                    % 获取 n（FIR阶数）: 使用"FIR阶数"输入框的值
                    n = round(double(handles.edtFIROrder.Value));
                    nyq = S.fs/2;
                    
                    switch handles.ddFIRMethod.Value
                        case {'Parks-McClellan'}
                            % n > 0 ，正常设计流程
                            if n > 0
                                % 获取已保存的参数（onConfirm 存放在 handles.firpmParams）
                                if isprop(handles,'firpmParams') && ~isempty(handles.firpmParams)
                                    params = handles.firpmParams;
                                else
                                    params = struct();
                                end
                                freq = params.f;
                        
                                % 准备归一化频率 F（firpm 期望 0..1，1 为 Nyquist）
                                if isfield(params,'f_norm') && ~isempty(params.f_norm)
                                    F = params.f_norm;
                                elseif isfield(params,'f') 
                                    F = params.f ./ nyq;
                                elseif exist('freq','var') && ~isempty(freq)
                                    % 兼容旧代码中的局部变量 freq（假如存在）
                                    F = freq ./ nyq;
                                else
                                    error('没有可用的频率向量（归一化）。请先从 onConfirm() 保存参数或使用本地变量 freq。');
                                end
                            
                                % 构造 firpm 的参数 cell 列表
                                firpmArgs = { n, F };
                            
                                % 第三个参数：幅值向量 a 或者 函数句柄/函数单元 ( {@fresp, P1, ...} )
                                if isfield(params,'a') && ~isempty(params.a) && isfield(params,'selMode') && strcmpi(params.selMode,'a')
                                    % 使用幅值向量
                                    thirdArg = params.a;
                                elseif isfield(params,'fresp') && ~isempty(params.fresp) && isfield(params,'selMode') && strcmpi(params.selMode,'fresp')
                                    % params.fresp 期望结构体，至少包含 name（函数名字符串）
                                    % 将字符串转换为函数句柄
                                    try
                                        frespName = params.fresp.name;
                                        if isa(frespName,'function_handle')
                                            frespHandle = frespName;
                                        elseif ischar(frespName) || isstring(frespName)
                                            frespHandle = str2func(char(frespName));
                                        else
                                            error('Unsupported fresp.name type.');
                                        end
                                    catch
                                        error('无法解析保存的 fresp 函数。请检查 params.fresp.name 是否正确并在路径上。');
                                    end

                                    % --- 构造函数第三个参数（支持 Positional / Name-Value / Both） ---
                                    if isfield(params.fresp,'A') && ~isempty(params.fresp.A)
                                        extra = params.fresp.A;  % 期望为数值向量或其他单一值
                                    
                                        % 获取保存的传参风格（在 onConfirm 中应保存为 params.fresp.paramStyle，值为 'pos'/'nv'/'both'）
                                        paramStyle = '';
                                        if isfield(params.fresp,'paramStyle') && ~isempty(params.fresp.paramStyle)
                                            paramStyle = lower(char(params.fresp.paramStyle));
                                        end
                                    
                                        switch paramStyle
                                            case 'pos'
                                                % Positional 风格：将 extra 以 positional 方式展开为多个额外参数
                                                if ~iscell(extra)
                                                    extraCell = { extra };
                                                else
                                                    extraCell = extra(:)';  % 确保行向量形式
                                                end
                                                thirdArg = [{frespHandle}, extraCell{:}];  % {fhandle, extra1, extra2, ...}
                                    
                                            case {'nv','both'}
                                                % Name-Value（或 Both 时同样以 Name-Value 形式传递）
                                                if isfield(params.fresp,'paramName') && ~isempty(params.fresp.paramName)
                                                    pname = char(params.fresp.paramName);
                                                    % 将 name-value 作为一对参数传入：{fhandle, 'pname', value}
                                                    % 这里将 extra 作为 value（通常是向量 A）
                                                    thirdArg = [{frespHandle}, pname, extra];
                                                else
                                                    % 缺少 paramName：回退到 positional 并给出警告（保守策略）
                                                    warning('firpm:MissingFrespParamName', ...
                                                        'fresp paramName 缺失，已回退为 positional 传参风格。');
                                                    if ~iscell(extra)
                                                        extraCell = { extra };
                                                    else
                                                        extraCell = extra(:)';
                                                    end
                                                    thirdArg = [{frespHandle}, extraCell{:}];
                                                end
                                    
                                            otherwise
                                                % 未指定或未知风格 -> 默认使用 positional（与原实现兼容）
                                                if ~iscell(extra)
                                                    extraCell = { extra };
                                                else
                                                    extraCell = extra(:)';
                                                end
                                                thirdArg = [{frespHandle}, extraCell{:}];
                                        end
                                    else
                                        % 无 A 的情况，只有函数句柄
                                        thirdArg = {frespHandle};
                                    end  % 构造函数第三个参数 频率响应函数的幅值向量A（支持 Positional / Name-Value / Both）结束

                                else
                                    error('既没有幅值向量 a 也没有 fresp 函数，请先在 onConfirm 中保存参数。');
                                end % 幅值向量 a 或者 函数句柄调用判断结束
                            
                                firpmArgs{end+1} = thirdArg;  % 添加第三个必需参数
                            
                                % 可选：权重 W
                                if isfield(params,'w') && ~isempty(params.w)
                                    firpmArgs{end+1} = params.w;
                                end
                            
                                % 可选：奇对称 / 类型标志（Hilbert 或 differentiator）
                                % 在 onConfirm 我们保存为 tmp.oddType = 'hilbert' 或 'differentiator'（tag）
                                if isfield(params,'oddType') && ~isempty(params.oddType)
                                    switch lower(params.oddType)
                                        case 'hilbert'
                                            typeFlag = 'hilbert';          % 与 firpm 帮助文档一致
                                        case 'differentiator'
                                            typeFlag = 'differentiator';
                                        otherwise
                                            typeFlag = params.oddType;     % 直接传递（保守策略）
                                    end
                                    firpmArgs{end+1} = typeFlag;
                                end
                            
                                % 可选：LGRID，firpm 期望是一个单元素 cell（{LGRID}）
                                if isfield(params,'lgrid') && ~isempty(params.lgrid)
                                    % 确保 lgrid 为整数
                                    lval = round(params.lgrid);
                                    firpmArgs{end+1} = { lval };  % 注意：这里是单元素 cell
                                end
                            
                                % 最后一次性调用 firpm
                                try
                                     outputOpt = params.outputOpt;
                                     if strcmpi(outputOpt,'b')
                                        b = firpm(firpmArgs{:});
                                     elseif strcmpi(outputOpt,'b, err')
                                        [b,err] = firpm(firpmArgs{:});
                                     else
                                        [b,err,res] = firpm(firpmArgs{:});
                                     end
                                catch ME
                                    % 友好地把错误显示给用户并保留原始异常信息以便 debug
                                    uialert(fig_GUI, ['firpm 设计失败：' ME.message], 'firpm Error');
                                    rethrow(ME);
                                end

                            % n <= 0 进行自动估阶 
                            elseif n <= 0
                                params = handles.firpmParams;
                                freq = params.f;
                                a = params.a;
                                dev = params.dev;
                                [nCalc, fo, ao, wpm] = firpmord(freq(2:end-1), a, dev, S.fs); % freq(2,end-1)取这个是为了去除0和nyq处的频率点。以符合firpmord输入参数要求
                                                                    
                                % 构造 firpm 的参数 cell 列表
                                firpmArgs = { nCalc, fo, ao, wpm };   

                                % 可选：奇对称 / 类型标志（Hilbert 或 differentiator）
                                % 在 onConfirm 我们保存为 oddType = 'hilbert' 或 'differentiator'（tag）
                                if isfield(params,'oddType') && ~isempty(params.oddType)
                                    switch lower(params.oddType)
                                        case 'hilbert'
                                            typeFlag = 'hilbert';          % 与 firpm 帮助文档一致
                                        case 'differentiator'
                                            typeFlag = 'differentiator';
                                        otherwise
                                            typeFlag = params.oddType;     % 直接传递（保守策略）
                                    end
                                    firpmArgs{end+1} = typeFlag;
                                end
                            
                                % 可选：LGRID，firpm 期望是一个单元素 cell（{LGRID}）
                                if isfield(params,'lgrid') && ~isempty(params.lgrid)
                                    % 确保 lgrid 为整数
                                    lval = round(params.lgrid);
                                    firpmArgs{end+1} = { lval };  % 注意：这里是单元素 cell
                                end
                                
                                % 最后一次性调用 firpm
                                try
                                     outputOpt = params.outputOpt;
                                     if strcmpi(outputOpt,'b')
                                        b = firpm(firpmArgs{:});
                                     elseif strcmpi(outputOpt,'b, err')
                                        [b,err] = firpm(firpmArgs{:});
                                     else
                                        [b,err,res] = firpm(firpmArgs{:});
                                     end
                                catch ME
                                    % 友好地把错误显示给用户并保留原始异常信息以便 debug
                                    uialert(fig_GUI, ['firpm 设计失败：' ME.message], 'firpm Error');
                                    rethrow(ME);
                                end
                                
                                handles.firpmMBPaCal = struct('method',method,'f',fo*nyq,'a',ao,'w',wpm, 'dev',dev);
                            end
    
                            acoef = 1;
    
                        case 'Cplx-Parks-McClellan'
                            setStatus(handles,'cfirpm 多带/高级滤波器正在设计中......');
                            N = round(double(handles.edtFIROrder.Value));
                            params = handles.cfirpmParams;
                        
                            % 1) 频率向量 fHz -> 规范化到 [-1,1] (相对于 Nyquist)
                            nf_pos = double(params.fHz) ./ (S.fs/2);  % -1..1
                        
                            % 校验：nf_pos 单调且长度为偶数 - 如果不满足，报错
                            if any(diff(nf_pos) <= 0) || mod(numel(nf_pos),2) ~= 0
                                error('保存的 cfirpmParams 中 fHz 不满足 cfirpm 要求（必须严格递增且偶数长度）。');
                            end
                        
                            f_c = nf_pos;  
                        
                            % 计算带数（nf_pos 节点数为偶数，每 2 个节点构成 1 个带）
                            numBands = numel(nf_pos) / 2;
                            if mod(numBands,1) ~= 0
                                error('fHz 节点数不能被2整除，无法确定带数。');
                            end
                        
                            % 2) 权重 W_c 检查与构造（长度应等于带数）
                            if isfield(params,'w') && ~isempty(params.w)
                                W_c = params.w;
                                if numel(W_c) ~= numBands
                                    uialert_safe(fig_GUI, sprintf('权重向量 w 长度应等于带数 (%d)。', numBands), '参数错误');
                                    setStatus(handles,'设计失败：权重长度错误');
                                    return;
                                end
                            else
                                W_c = ones(1, numBands); % 默认权重
                            end
                        
                            % 3) sym / lgrid / output 选项读取
                            
                            if isfield(params,'sym') && ~isempty(params.sym) 
                                symOpt = params.sym; % 例如 'real'等（按你原代码中可接受值）
                            else
                                symOpt = '';
                            end
                        
                            if isfield(params,'lgrid')
                                lgridOpt = params.lgrid; % 可能为 []（表示未启用）或数字
                            else
                                lgridOpt = [];
                            end
                        
                            if isfield(params,'output') && ~isempty(params.output)
                                outputOpt = params.output;
                            else
                                outputOpt = 'b';
                            end
                        
                            % 4) 选择路径：优先使用 params.a（如果存在）——完全不使用 fresp 路径
                            pdir = ''; % 若临时添加路径，记录以便清理
                            try
                                if strcmpi(params.InputSel, '幅值向量a') && isfield(params,'a') && ~isempty(params.a)
                                    % ================================== A 路径：用户选择"幅值向量 a" ==================================
                                    targetA = double(params.a(:))'; % 行向量
                                    % 校验 targetA 长度必须等于 nf_pos 的长度（每个节点一个幅值）
                                    if numel(targetA) ~= numel(nf_pos)
                                        uialert_safe(fig_GUI, '幅值向量 a 的长度必须等于频率节点向量 fHz 的长度。', '参数错误');
                                        setStatus(handles,'设计失败：幅值向量长度不匹配');
                                        return;
                                    end
                        
                                    % ------------------ 构造按位置传入的可选参数（sym, skip_stage2, debug, lgrid） ------------------
                                    % 规范化 sym（可能为空）
                                    if exist('symOpt','var') && ~isempty(symOpt)
                                        slotSym = char(symOpt);
                                    else
                                        slotSym = []; % 未指定
                                    end
                        
                                    % skip_stage2
                                    if isfield(params,'skip_stage2') && isequal(params.skip_stage2,true)
                                        slotSkip = 'skip_stage2';
                                    else
                                        slotSkip = [];
                                    end
                        
                                    % debug（仅在用户启用时写入；如果用户显式选择 'off' 且你不想传入 'off' 可改为不传）
                                    if isfield(params,'debugOpt') && ~isempty(params.debugOpt)
                                        % 如果用户选择 'off' 并且你不希望传 'off'，可在此处过滤掉：
                                        if ~strcmpi(params.debugOpt,'off')
                                            slotDebug = params.debugOpt;
                                        else
                                            slotDebug = []; % 不传 'off'（更安全）
                                        end
                                    else
                                        slotDebug = [];
                                    end
                        
                                    % lgridOpt 已在上面准备（可能为 numeric 或 cell）
                                    if exist('lgridOpt','var') && ~isempty(lgridOpt)
                                        if iscell(lgridOpt)
                                            slotLgrid = lgridOpt{1}; % numeric inside cell
                                        else
                                            slotLgrid = double(lgridOpt);
                                        end
                                    else
                                        slotLgrid = [];
                                    end
                        
                                    % 现在按顺序把真正要传的位置参数压入 finalArgs
                                    finalArgs = {};
                                    % If any of the later slots are used, we must provide sym slot (or 'none') as first positional argument
                                    if ~isempty(slotSym) || ~isempty(slotSkip) || ~isempty(slotDebug) || ~isempty(slotLgrid)
                                        if ~isempty(slotSym)
                                            finalArgs{end+1} = slotSym;
                                        end
                                        % skip_stage2 (flag)
                                        if ~isempty(slotSkip)
                                            finalArgs{end+1} = slotSkip;
                                        end
                                        % debug option (string)
                                        if ~isempty(slotDebug)
                                            finalArgs{end+1} = slotDebug;
                                        end
                                        % lgrid：需要以 cell 形式传递，如 {25}
                                        if ~isempty(slotLgrid)
                                            finalArgs{end+1} = {slotLgrid};
                                        end
                                    end
                        
                                    % ------------------ 调用 cfirpm（按 outputOpt 区分返回值） ------------------
                                    if strcmpi(outputOpt,'b')
                                        if isempty(finalArgs)
                                            b = cfirpm(N, f_c, targetA, W_c);
                                        else
                                            b = cfirpm(N, f_c, targetA, W_c, finalArgs{:});
                                        end
                                    elseif strcmpi(outputOpt,'b, delta')
                                        if isempty(finalArgs)
                                            [b, delta] = cfirpm(N, f_c, targetA, W_c);
                                        else
                                            [b, delta] = cfirpm(N, f_c, targetA, W_c, finalArgs{:});
                                        end
                                    else
                                        if isempty(finalArgs)
                                            [b, delta, res] = cfirpm(N, f_c, targetA, W_c);
                                        else
                                            [b, delta, res] = cfirpm(N, f_c, targetA, W_c, finalArgs{:});
                                        end
                                    end
                        
                                    acoef = 1; 
                        
                                elseif strcmpi(params.InputSel, '频率响应函数fresp')
                                    % =============================== B 路径：使用 fresp（包括内置或 user_defined_function） ====================
                                    % 若 params.fresp 为空 -> 报错
                                    if ~isfield(params,'fresp') || isempty(params.fresp)
                                        uialert_safe(fig_GUI, '未指定频率响应函数 fresp。无法设计。', '参数错误');
                                        setStatus(handles,'设计失败：缺少 fresp');
                                        return;
                                    end
                        
                                    % 处理 user_defined_function：若存在 user_fresp_file，则临时 addpath 并使用 str2func
                                    if isfield(params,'user_fresp_file') && ~isempty(params.user_fresp_file) && strcmpi(params.fresp,'user_defined_function')
                                        [pdir, fname_noext] = fileparts(params.user_fresp_file);
                                        if isempty(fname_noext)
                                            uialert_safe(fig_GUI,'选择的自定义 fresp 文件名无效。','参数错误');
                                            setStatus(handles,'设计失败：自定义 fresp 无效');
                                            return;
                                        end
                                        addpath(pdir);
                                        fresp_handle = str2func(fname_noext);
                                        % 标记需在结束时清理该路径
                                    else
                                        % 内置 fresp 字符串通常写为 '@lowpass' 或直接 'lowpass' / 'myFresp' 等
                                        if ischar(params.fresp) && startsWith(params.fresp,'@')
                                            fresp_handle = str2func(strrep(params.fresp,'@',''));
                                        else
                                            % 直接尝试转为函数名
                                            fresp_handle = str2func(params.fresp);
                                        end
                                    end
                        
                                    % ------------------------ 构造 fresp_args（处理 @multiband/@differentiator/@invsinc和user_defined_function）-------------------
                                    fresp_args = {};
                                    fresp_nv_pairs = {}; % 用于存放尾部的 Name-Value 对（例如 'a', a）

                                    % ---------- 改进：优先使用 params.user_fresp_param_style 决定是否用 Name-Value ----------
                                    % 优先依据保存的风格字段（向后兼容：若无则保留原有 user_fresp_use_nv / 自动探测）
                                    if isfield(params,'user_fresp_param_style') && ~isempty(params.user_fresp_param_style)
                                        styleStr = params.user_fresp_param_style;
                                        useNameValue = any(strcmpi(styleStr, {'Name-Value','Both'}));
                                    else
                                        % 原有判定（保持向后兼容）
                                        useNameValue = false;
                                        if isfield(params,'user_fresp_use_nv') && isequal(params.user_fresp_use_nv,true)
                                            useNameValue = true;
                                        else
                                            try
                                                fhname = func2str(fresp_handle);
                                                if contains(lower(fhname),'cfirpm_fresp_example')
                                                    useNameValue = true;
                                                end
                                            catch
                                                % ignore
                                            end
                                        end
                                    end

                                    % 如果 params.fresp 是带 '@' 的内置指定，优先按指定处理
                                    if ischar(params.fresp) 
                                        fresp_name = strrep(params.fresp,'@','');
                                        switch fresp_name
                                            case 'multiband'
                                                % multiband 需要 amb（向量，长度 = nf_pos 节点数）
                                                if ~isfield(params,'amb') || isempty(params.amb)
                                                    uialert_safe(fig_GUI, 'fresp=@multiband 时必须提供 amb（幅值向量）。请返回参数窗口设置 amb。', '参数错误');
                                                    setStatus(handles,'设计失败：缺少 multiband amb');
                                                    return;
                                                end
                                                ambVec = double(params.amb(:))';
                                                % 校验 amb 长度与 nf_pos 长度一致
                                                if numel(ambVec) ~= numel(nf_pos)
                                                    uialert_safe(fig_GUI, 'multiband 幅值向量 amb 的长度必须等于频率节点向量 fHz 的长度。', '参数错误');
                                                    setStatus(handles,'设计失败：amb 长度不匹配');
                                                    return;
                                                end
                                                fresp_args{end+1} = ambVec;
                        
                                            case 'differentiator'
                                                % differentiator 需要 fs（标量），默认 1
                                                if isfield(params,'differentiator_fs') && ~isempty(params.differentiator_fs)
                                                    fs_val = double(params.differentiator_fs);
                                                else
                                                    fs_val = 1;
                                                end
                                                if ~isnumeric(fs_val) || ~isfinite(fs_val) || fs_val <= 0
                                                    uialert_safe(fig_GUI, 'differentiator 采样率 fs 必须为正数（默认 1）。', '参数错误');
                                                    setStatus(handles,'设计失败：differentiator fs 无效');
                                                    return;
                                                end
                                                fresp_args{end+1} = fs_val;
                        
                                            case 'invsinc'
                                                % invsinc 需要 ainvsinc（标量），默认 1
                                                if isfield(params,'ainvsinc') && ~isempty(params.ainvsinc)
                                                    ai_val = double(params.ainvsinc);
                                                else
                                                    ai_val = 1;
                                                end
                                                if ~isnumeric(ai_val) || ~isfinite(ai_val)
                                                    uialert_safe(fig_GUI, 'invsinc 增益 ainvsinc 必须为有效数值（默认 1）。', '参数错误');
                                                    setStatus(handles,'设计失败：invsinc ainvsinc 无效');
                                                    return;
                                                end
                                                fresp_args{end+1} = ai_val;

                                            case 'user_defined_function' 
                                                % user_defined_function 可选设置 幅度向量A（向量，长度 = nf_pos 节点数）
                                                % ---------- 幅值向量 A 的处理（使用用户指定的 Name 或回退到 'a'） ----------
                                                if isfield(params,'user_fresp_A') && ~isempty(params.user_fresp_A)
                                                    frespAVec = double(params.user_fresp_A(:))';
                                                    if numel(frespAVec) ~= numel(nf_pos)
                                                        uialert_safe(fig_GUI, '频率响应函数 fresp 的幅值向量 A 的长度必须等于频率节点向量 fHz 的长度。', '参数错误');
                                                        setStatus(handles,'设计失败：幅值向量 A 长度不匹配');
                                                        return;
                                                    end
                                                
                                                    if useNameValue
                                                        % 获取用户在 GUI 中填写的名称（优先），合法性检查，否则回退默认 'a'
                                                        nameA = 'a';
                                                        if isfield(params,'user_fresp_A_name') && ischar(params.user_fresp_A_name) && ~isempty(strtrim(params.user_fresp_A_name))
                                                            cand = strtrim(params.user_fresp_A_name);
                                                            if isvarname(cand)
                                                                nameA = cand;
                                                            else
                                                                % 非法标识符，警告并使用默认 'a'
                                                                try
                                                                    uialert_safe(fig_GUI, sprintf('用户指定的幅值向量 A 名称 "%s" 不是合法的 MATLAB 标识符，已使用默认名称 ''a''。', cand), '参数警告');
                                                                catch
                                                                    % 如果 uialert_safe 本身不可用则静默继续
                                                                end
                                                                nameA = 'a';
                                                            end
                                                        end
                                                        % 将 Name-Value 对追加到 fresp_nv_pairs
                                                        fresp_nv_pairs = [fresp_nv_pairs, {nameA, frespAVec}];
                                                    else
                                                        fresp_args{end+1} = frespAVec;
                                                    end
                                                else
                                                    % 没有提供 A 向量 —— 按原逻辑不做处理
                                                end
                                            
                                             
                                        end % switch fresp_name end
                                    end
                        
                                    % group_delay 仅在 fresp 模式下有效（如果存在且非 0 则传入）
                                    % ---------- 群延迟 d 的处理（使用用户指定的 Name 或回退到 'd'） ----------
                                    if isfield(params,'group_delay') && ~isempty(params.group_delay) && params.group_delay ~= 0
                                        if useNameValue
                                            nameD = 'd';
                                            if isfield(params,'user_fresp_d_name') && ischar(params.user_fresp_d_name) && ~isempty(strtrim(params.user_fresp_d_name))
                                                candD = strtrim(params.user_fresp_d_name);
                                                if isvarname(candD)
                                                    nameD = candD;
                                                else
                                                    try
                                                        uialert_safe(fig_GUI, sprintf('用户指定的群延迟 d 名称 "%s" 不是合法的 MATLAB 标识符，已使用默认名称 ''d''。', candD), '参数警告');
                                                    catch
                                                    end
                                                    nameD = 'd';
                                                end
                                            end
                                            fresp_nv_pairs = [fresp_nv_pairs, {nameD, params.group_delay}];
                                        else
                                            fresp_args{end+1} = params.group_delay;
                                        end
                                    end
                                    % --------------------------------- fresp_args 构造完毕 -------------------------------------------
                        
                        
                                    % ------------------ 构造按位置传入的可选参数（sym, skip_stage2, debug, lgrid） ------------------
                                    % 规范化 sym（可能为空）
                                    if exist('symOpt','var') && ~isempty(symOpt)
                                        slotSym = char(symOpt);
                                    else
                                        slotSym = []; % 未指定
                                    end
                        
                                    % skip_stage2
                                    if isfield(params,'skip_stage2') && isequal(params.skip_stage2,true)
                                        slotSkip = 'skip_stage2';
                                    else
                                        slotSkip = [];
                                    end
                        
                                    % debug（仅在用户启用时写入；如果用户显式选择 'off' 且你不想传入 'off' 可改为不传）
                                    if isfield(params,'debugOpt') && ~isempty(params.debugOpt)
                                        % 如果用户选择 'off' 并且你不希望传 'off'，可在此处过滤掉：
                                        if ~strcmpi(params.debugOpt,'off')
                                            slotDebug = params.debugOpt;
                                        else
                                            slotDebug = []; % 不传 'off'（更安全）
                                        end
                                    else
                                        slotDebug = [];
                                    end
                                    
                                    % lgridOpt 已在上面准备（可能为 numeric 或 cell）
                                    if exist('lgridOpt','var') && ~isempty(lgridOpt)
                                        if iscell(lgridOpt)
                                            slotLgrid = lgridOpt{1}; % numeric inside cell
                                        else
                                            slotLgrid = double(lgridOpt);
                                        end
                                    else
                                        slotLgrid = [];
                                    end
                                    
                                    % 现在按顺序把真正要传的位置参数压入 finalArgs
                                    finalArgs = {};
                                    % If any of the later slots are used, we must provide sym slot (or 'none') as first positional argument
                                    if ~isempty(slotSym) || ~isempty(slotSkip) || ~isempty(slotDebug) || ~isempty(slotLgrid)
                                        if ~isempty(slotSym)
                                            finalArgs{end+1} = slotSym;
                                        end
                                        % skip_stage2 (flag)
                                        if ~isempty(slotSkip)
                                            finalArgs{end+1} = slotSkip;
                                        end
                                        % debug option (string)
                                        if ~isempty(slotDebug)
                                            finalArgs{end+1} = slotDebug;
                                        end
                                        % lgrid：需要以 cell 形式传递，如 {25}
                                        if ~isempty(slotLgrid)
                                            finalArgs{end+1} = {slotLgrid};
                                        end
                                    end
                        
                                    % ------------------ 调用 cfirpm：若 fresp_args 为空则直接传
                                    % fresp_handle，否则使用 cell {fresp_handle, fresp_args... , fresp_nv_pairs...}  ------------------ 
                                    if isempty(fresp_args) && isempty(fresp_nv_pairs)
                                        % 直接用 fresp_handle
                                        if strcmpi(outputOpt,'b')
                                            if isempty(finalArgs)
                                                b = cfirpm(N, f_c, fresp_handle, W_c);
                                            else
                                                b = cfirpm(N, f_c, fresp_handle, W_c, finalArgs{:});
                                            end
                                        elseif strcmpi(outputOpt,'b, delta')
                                            if isempty(finalArgs)
                                                [b, delta] = cfirpm(N, f_c, fresp_handle, W_c);
                                            else
                                                [b, delta] = cfirpm(N, f_c, fresp_handle, W_c, finalArgs{:});
                                            end
                                        else
                                            if isempty(finalArgs)
                                                [b, delta, res] = cfirpm(N, f_c, fresp_handle, W_c);
                                            else
                                                [b, delta, res] = cfirpm(N, f_c, fresp_handle, W_c, finalArgs{:});
                                            end
                                        end
                              
                                    else
                                        % fresp_handle，否则使用 cell {fresp_handle, fresp_args... , fresp_nv_pairs...}  ------------------ 
                                        % 将位置参数与尾部 Name-Value 对合并（保证 Name-Value 在最后）
                                        fresp_cell = [{fresp_handle}, fresp_args, fresp_nv_pairs];
                                        if strcmpi(outputOpt,'b')
                                            if isempty(finalArgs)
                                                b = cfirpm(N, f_c, fresp_cell, W_c); 
                                            else
                                                b = cfirpm(N, f_c, fresp_cell, W_c, finalArgs{:});
                                            end
                                        elseif strcmpi(outputOpt,'b, delta')
                                            if isempty(finalArgs)
                                                [b, delta] = cfirpm(N, f_c, fresp_cell, W_c);
                                            else
                                                [b, delta] = cfirpm(N, f_c, fresp_cell, W_c, finalArgs{:});
                                            end
                                        else
                                            if isempty(finalArgs)
                                                [b, delta, res] = cfirpm(N, f_c, fresp_cell, W_c);
                                            else
                                                [b, delta, res] = cfirpm(N, f_c, fresp_cell, W_c, finalArgs{:});
                                            end
                                        end
                                    
                                    end
                        
                                    acoef = 1;
                                end
                        
                            catch ME
                                % 发生错误时：若临时添加了路径则移除，报告错误并返回
                                if exist('pdir','var') && ~isempty(pdir)
                                    try rmpath(pdir); catch; end
                                end
                                fprintf('cfirpm (使用 handles.cfirpmParams) 设计失败：%s\n', ME.message);
                                uialert_safe(fig_GUI, sprintf('cfirpm 设计失败（cfirpmParams）：%s', ME.message), '设计失败');
                                setStatus(handles,'设计失败：cfirpm cfirpmParams 运行出错');
                                return;
                            end
                        
                            % 5) 清理：如果临时添加了路径，移除它（可选）
                            if exist('pdir','var') && ~isempty(pdir)
                                try rmpath(pdir); catch; end
                            end


                        case {'最小二乘(firls)'}
                            params = handles.firlsParams;
                            if isempty(n) || n <= 0
                                uialert_safe(fig_GUI, 'FIR优化设计法 - 最小二乘(firls)不支持自动估阶。请在 "FIR 阶数" 输入框中输入正整数。', '参数错误');
                                setStatus(handles,'设计失败：约束最小二乘(fircls) 需要正整数阶数'); return;
                            end
                        
                            f_norm = double(params.f) / double(nyq);
                            a = double(params.a);
                        
                            % 参数容器
                            args = {double(n), f_norm, a};
                        
                            % 权重检查：必须为数值向量且长度为 length(f)/2（界面已校验过，此处可强化）
                            if isfield(params,'w') && ~isempty(params.w)
                                w = double(params.w);
                                if ~isnumeric(w) || ~isvector(w)
                                    uialert_safe(fig_GUI,'权重 w 必须为数值向量。','参数错误'); setStatus(handles,'设计失败：权重格式错误'); return;
                                end
                                args{end+1} = w;
                            end
                        
                            % 奇对称类型检查
                            if isfield(params,'oddSymmetric') && ~isempty(params.oddSymmetric) && params.oddSymmetric
                                if isfield(params,'oddType') && ~isempty(params.oddType)
                                    ftype = lower(char(params.oddType));
                                    if ~ismember(ftype, {'hilbert','differentiator'})
                                        uialert_safe(fig_GUI,'奇对称类型应为 ''hilbert'' 或 ''differentiator''。','参数错误'); setStatus(handles,'设计失败：奇对称类型错误'); return;
                                    end
                                    args{end+1} = ftype;
                                else
                                    uialert_safe(fig_GUI, '已选择设计奇对称滤波器，但未指定类型（hilbert 或 differentiator）。', '参数错误');
                                    setStatus(handles,'设计失败：未指定奇对称类型'); return;
                                end
                            end
                        
                            % 最终调用
                            b = firls(args{:});
                            acoef = 1;


                        case {'约束最小二乘(fircls)'}
                            params = handles.firclsParams;
                            if isempty(n) || n <= 0
                                uialert_safe(fig_GUI, 'FIR优化设计法 - 约束最小二乘(fircls)不支持自动估阶。请在 "FIR 阶数" 输入框中输入正整数。', '参数错误');
                                setStatus(handles,'设计失败：约束最小二乘(fircls) 需要正整数阶数'); return;
                            end
                            f_norm = params.f / nyq;
                            amp = params.amp; up = params.up; lo = params.lo;
                            if isfield(params,'designflag') && ~isempty(params.designflag)
                                designflag = lower(params.designflag);
                                b = fircls(n, f_norm, amp, up, lo, designflag); 
                            else
                                b = fircls(n, f_norm, amp, up, lo); 
                            end
                            acoef = 1;


                        case {'约束最小二乘1(fircls1)'}
                            setStatus(handles,'fircls1 多带/高级滤波器正在设计中......');
                            % 读取已保存参数并验阶
                            N = round(double(handles.edtFIROrder.Value));
                            params = handles.fircls1Params;
                            if isempty(N) || N <= 0
                                uialert_safe(fig_GUI, '约束最小二乘1(fircls1) 不支持自动估阶。请在 "FIR 阶数" 输入框中输入正整数。', '参数错误');
                                setStatus(handles,'设计失败：约束最小二乘1(fircls1) 需要正整数阶数'); return;
                            end
                            if isempty(params)
                                uialert_safe(fig_GUI, '请先通过"多带 / 高级滤波参数"设置 fircls1 的参数。', '参数缺失');
                                setStatus(handles,'设计失败：缺少 fircls1 参数'); return;
                            end
                        
                            % 基本参数（归一化到 Nyquist）
                            wo = double(params.fircls1_fo) / nyq;
                            dp = double(params.fircls1_dp);
                            ds = double(params.fircls1_ds);
                        
                            % 构造参数 cell 数组
                            args = {N, wo, dp, ds};
                        
                            % 可选：ft（优先）或 L2 (wp,ws,k)
                            if isfield(params,'fircls1_use_ft') && params.fircls1_use_ft && isfield(params,'fircls1_ft') && ~isempty(params.fircls1_ft)
                                args{end+1} = double(params.fircls1_ft) / nyq;    % wt
                            elseif isfield(params,'fircls1_use_L2') && params.fircls1_use_L2
                                % 假定 fp, fs, k 已经校验存在且有效
                                args{end+1} = double(params.fircls1_fp) / nyq;    % wp
                                args{end+1} = double(params.fircls1_fs) / nyq;    % ws
                                args{end+1} = double(params.fircls1_k);           % k
                            end
                        
                            % 若为高通，在参数后追加 'high'
                            if isfield(params,'fircls1_FirType') && strcmp(params.fircls1_FirType,'高通')
                                args{end+1} = 'high';
                            end
                        
                            % 若用户保存了 designDisplay，则追加（否则不传）
                            if isfield(params,'fircls1_designDisplay') && ~isempty(params.fircls1_designDisplay)
                                args{end+1} = params.fircls1_designDisplay;
                            end
                        
                            % 调用并捕获异常
                            try
                                b = fircls1(args{:});
                                acoef = 1;
                            catch ME
                                % 输出并以弹窗提示（与之前风格一致）
                                fprintf('fircls1 设计失败：%s\n', ME.message);
                                uialert_safe(fig_GUI, sprintf('fircls1 设计失败：%s', ME.message), '设计失败');
                                setStatus(handles,'设计失败：fircls1 运行出错');
                                return;
                            end


                        otherwise
                            uialert_safe(fig_GUI, '当前 FIR 子方法不支持多带/高级设计。','方法错误');
                            setStatus(handles,'设计失败：FIR 子方法错误'); return;
                    end

                    % 更新设计方法提示标签并同步状态栏
                    updateDesignLabel(S, handles);

                % ===================================== FIR 频率采样法 (fir2) 多带/高级设计 =====================================
                elseif strcmpi(method, 'FIR频率采样法')
                    % 1) 获取阶数并强校验（fir2 不支持自动估阶）
                    n = round(double(handles.edtFIROrder.Value));
                    if isempty(n) || n <= 0
                        if exist('uialert_safe','file')
                            uialert_safe(fig_GUI, 'FIR频率采样法 (fir2) 不支持自动估阶。请在 "FIR 阶数" 输入框中输入正整数。', '参数错误');
                        else
                            uialert(fig_GUI, 'FIR频率采样法 (fir2) 不支持自动估阶。请在 "FIR 阶数" 输入框中输入正整数。', '参数错误');
                        end
                        setStatus(handles,'设计失败：fir2 需要正整数阶数'); return;
                    end

                    params = handles.fir2Params;
                    % 验证并归一化 f (params.f 存为 Hz)
                    fHz = double(params.f(:))';
                    mVec = double(params.m(:))';
                    % 归一化
                    f_norm = fHz / nyq;
                    % build fir2 arguments
                    % optional npt / lap
                    args = {};
                    if isfield(params, 'npt') && ~isempty(params.npt) && params.npt>0
                        args{end+1} = params.npt;
                        if isfield(params,'lap') && ~isempty(params.lap) && params.lap>0
                            args{end+1} = params.lap;
                        end
                    end
                    % optional window
                    if isfield(params,'windowSelected') && params.windowSelected
                        % create window vector of length n+1 based on user choice
                        wtype = params.windowName;
                        switch wtype
                            case 'Rectwin', windowVec = rectwin(n+1);
                            case 'Triang',  windowVec = triang(n+1);
                            case 'Hann',    windowVec = hann(n+1);
                            case 'Hamming', windowVec = hamming(n+1);
                            case 'Blackman',windowVec = blackman(n+1);
                            case 'Kaiser'
                                % require kaiserBeta
                                if ~isfield(params,'kaiserBeta') || isempty(params.kaiserBeta)
                                    uialert_safe(fig_GUI,'Kaiser 窗时需设置形状参数 (beta)。','参数错误'); setStatus(handles,'设计失败：缺少 Kaiser beta'); return;
                                end
                                windowVec = kaiser(n+1, params.kaiserBeta);
                            otherwise
                                windowVec = []; % fallback: let fir2 use default (hamming)
                        end
                        if ~isempty(windowVec)
                            args{end+1} = windowVec;
                        end
                    end
                    % finally call fir2 with dynamic args
                    if isempty(args)
                        b = fir2(n, f_norm, mVec);
                    elseif isscalar(args)
                        b = fir2(n, f_norm, mVec, args{1});
                    elseif numel(args)==2
                        b = fir2(n, f_norm, mVec, args{1}, args{2});
                    elseif numel(args)==3
                        b = fir2(n, f_norm, mVec, args{1}, args{2}, args{3});
                    else
                        error('内部错误：fir2 可选参数超过预期。');
                    end
                    acoef = 1;

                    % 更新设计方法提示标签并同步状态栏
                    updateDesignLabel(S, handles);
                
                % ====================================== 若为 yulewalk 多带/高级 =========================================
                elseif strcmpi(method,'IIR') && isprop(handles,'ddIIRProto') && strcmpi(handles.ddIIRProto.Value,'Yule-Walker')
                    % n: 使用 IIR 阶数框
                    n = round(double(handles.edtIIROrder.Value));
                    params = handles.yuleWalkParams;

                    if isempty(n) || n <= 0
                        if exist('uialert_safe','file'), uialert_safe(fig_GUI,'Yule-Walker 不支持自动估阶。请在 "IIR 阶数" 输入框中输入正整数。','参数错误'); else; uialert(fig_GUI,'Yule-Walker 不支持自动估阶。请在 "IIR 阶数" 输入框中输入正整数。','参数错误'); end
                        setStatus(handles,'设计失败：Yule-Walker 需要正整数阶数'); return;
                    end
            
                    f_hz = double(params.f(:).');   % Hz
                    m = double(params.m(:).');      % linear
            
                    % 规范化到 0..1（相对于 Nyq）
                    f_norm = f_hz ./ (S.fs/2);
                    % 检查 f_norm 在 0..1
                    if any(f_norm < 0) || any(f_norm > 1) || any(diff(f_norm) < 0)
                        uialert(fig_GUI,'多带/高级参数 f 必须递增并位于 [0, Nyq]。','参数错误'); setStatus(handles,'设计失败：多带/高级 f 错误'); return;
                    end
            
                    try
                        [b,a] = yulewalk(n, f_norm, m);
                    catch ME
                        uialert_safe(fig_GUI, sprintf('Yule-Walker 设计失败：%s', ME.message), '设计错误');
                        setStatus(handles,'设计失败：Yule-Walker 调用失败'); return;
                    end
                    acoef = a;
                    % 更新设计方法提示标签并同步状态栏
                    updateDesignLabel(S, handles);

                % ================================================= 处理 IIR-maxflat 多带/高级 =================================================
                elseif strcmp(method,'IIR') && isprop(handles,'ddIIRProto') && strcmpi(handles.ddIIRProto.Value,'maxflat')  && strcmp(type,'多带/高级')
                
                    params = handles.maxflatParams;
                    n_order = params.maxflat_n;
                
                    % 转换 fn(Hz) -> 归一化 Wn (0..1)
                    nyq = S.fs/2;
                    Wn = params.maxflat_fn / nyq;
                    if ~(isnumeric(Wn) && isfinite(Wn) && Wn>0 && Wn<=1)
                        uialert_safe(fig_GUI, '保存的截止频率不合法，请重新设置。','参数错误');
                        setStatus(handles,'设计失败：maxflat 参数错误');
                        return;
                    end
                
                    % ---------- 构造 my_maxflat 的参数列表（cell） ----------
                    args = {};                      % 将按 my_maxflat 的解析规则顺序填入
                    isSym = isfield(params,'maxflat_sym') && params.maxflat_sym;
                
                    if isSym
                        % sym 模式：第一个可选参数为 'sym'
                        args{end+1} = 'sym';
                    else
                        % 非 sym：需要 m（分母阶数）
                        if isfield(params,'maxflat_m') && ~isempty(params.maxflat_m)
                            m_order = params.maxflat_m;
                            args{end+1} = m_order;
                        else
                            uialert_safe(fig_GUI, '缺少分母阶数 m（非 sym 模式必需）。','参数错误');
                            setStatus(handles,'设计失败：maxflat 参数缺失 m');
                            return;
                        end
                    end
                
                    % Wn 总是紧随在上述参数之后
                    args{end+1} = Wn;
                
                    % 可选 designflag（'trace'/'plots'/'both'）
                    if isfield(params,'maxflat_designflag') && ~isempty(params.maxflat_designflag)
                        args{end+1} = params.maxflat_designflag;
                    end
                
                    % 可选 'high'（my_maxflat 支持把 'high' 放在任意位置）
                    if isfield(params,'maxflat_isHigh') && params.maxflat_isHigh
                        args{end+1} = 'high';
                    end
                
                    % ---------- 统一调用 my_maxflat ----------
                    try
                        if isSym
                            % sym 模式：my_maxflat 仅返回 b（若请求更多输出会报错），保持 a = 1（FIR）
                            b = my_maxflat(n_order, args{:});
                            a = 1;
                            b1 = []; b2 = []; sos = []; g = [];
                        else
                            % 非 sym：请求完整输出（与原逻辑保持一致）
                            [b,a,b1,b2,sos,g] = my_maxflat(n_order, args{:});
                        end
                    catch ME
                        uialert_safe(fig_GUI, ['maxflat 设计失败：', ME.message], '设计失败');
                        setStatus(handles,'maxflat 设计失败');
                        return;
                    end
                
                    % 备份系数以供后续使用
                    acoef = a;
                
                    % 更新 UI 文本与状态
                    updateDesignLabel(S, handles);

                
                % ================================================= 处理 FIRintfilt插值 多带/高级 =================================================
                elseif strcmpi(handles.ddDesignMethod.Value,'FIRintfilt插值')
                    if isempty(handles.intfiltParams)
                        uialert_safe(fig_GUI, '请先通过"多带 / 高级滤波参数"按钮设置 intfilt 参数。', '参数缺失');
                        setStatus(handles,'设计失败：intfilt 参数未设置'); 
                        return;
                    end
                    p_intfilt = handles.intfiltParams;
                    try
                        if strcmp(p_intfilt.intfilt_mode,'bandlimited')
                            b = intfilt(p_intfilt.intfilt_l, p_intfilt.intfilt_p, p_intfilt.intfilt_alpha);
                        else
                            b = intfilt(p_intfilt.intfilt_l, p_intfilt.intfilt_n, 'Lagrange');
                        end
                    catch ME
                        uialert_safe(fig_GUI, ['intfilt 设计失败：', ME.message], '设计错误');
                        setStatus(handles,'intfilt 设计失败');
                        return;
                    end

                    acoef = 1;

                    % 更新 UI 文本与状态
                    updateDesignLabel(S, handles);


                % ================================================= FIR gaussdesign 脉冲整形 =================================================
                elseif strcmpi(handles.ddDesignMethod.Value, 'FIRgaussdesign脉冲整形')
                    % 必须先设置参数
                    if isempty(handles.gaussdesignParams)
                        if exist('uialert_safe','file'), uialert_safe(fig_GUI, '请先通过"多带 / 高级滤波参数"按钮设置 gaussdesign 参数。', '参数缺失');
                        else; uialert(fig_GUI, '请先通过"多带 / 高级滤波参数"按钮设置 gaussdesign 参数。', '参数缺失'); end
                        setStatus(handles,'设计失败：缺少 gaussdesign 参数');
                        return;
                    end
                    p_gauss = handles.gaussdesignParams;
                    % 再次校验（保险）
                    if ~isfield(p_gauss,'bt') || ~isfield(p_gauss,'span') || ~isfield(p_gauss,'sps')
                        if exist('uialert_safe','file'), uialert_safe(fig_GUI, 'gaussdesign 参数不完整。', '参数错误'); else; uialert(fig_GUI, 'gaussdesign 参数不完整。', '参数错误'); end
                        return;
                    end
                    try
                        % 调用 MATLAB 内置 gaussdesign
                        b = gaussdesign(p_gauss.bt, p_gauss.span, p_gauss.sps);
                        acoef = 1;
                    catch ME
                        if exist('uialert_safe','file'), uialert_safe(fig_GUI, ['gaussdesign 设计失败：', ME.message], '设计错误'); else; uialert(fig_GUI, ['gaussdesign 设计失败：', ME.message], '设计错误'); end
                        setStatus(handles,'gaussdesign 设计失败');
                        return;
                    end

                    % 更新 UI 文本与状态
                    updateDesignLabel(S, handles);


                % ================================================= FIR rcosdesign脉冲整形 脉冲整形 =================================================
                elseif strcmpi(handles.ddDesignMethod.Value, 'FIRrcosdesign脉冲整形')
                    % 必须先设置参数
                    if isempty(handles.rcosdesignParams)
                        if exist('uialert_safe','file'), uialert_safe(fig_GUI, '请先通过"多带 / 高级滤波参数"按钮设置 rcosdesign 参数。', '参数缺失');
                        else; uialert(fig_GUI, '请先通过"多带 / 高级滤波参数"按钮设置 rcosdesign 参数。', '参数缺失'); end
                        setStatus(handles,'设计失败：缺少 rcosdesign 参数');
                        return;
                    end
                    p_rcos = handles.rcosdesignParams;
                    % 再次校验（保险）
                    if ~isfield(p_rcos,'beta') || ~isfield(p_rcos,'span') || ~isfield(p_rcos,'sps') || ~isfield(p_rcos,'shape')
                        if exist('uialert_safe','file'), uialert_safe(fig_GUI, 'rcosdesign 参数不完整。', '参数错误'); else; uialert(fig_GUI, 'rcosdesign 参数不完整。', '参数错误'); end
                        return;
                    end
                    try
                        % 调用 MATLAB 内置 rcosdesign
                        b = rcosdesign(p_rcos.beta, p_rcos.span, p_rcos.sps, p_rcos.shape);
                        acoef = 1;
                    catch ME
                        if exist('uialert_safe','file'), uialert_safe(fig_GUI, ['rcosdesign 设计失败：', ME.message], '设计错误'); else; uialert(fig_GUI, ['rcosdesign 设计失败：', ME.message], '设计错误'); end
                        setStatus(handles,'rcosdesign 设计失败');
                        return;
                    end

                    % 更新 UI 文本与状态
                    updateDesignLabel(S, handles);


                % ================================================= Savitzky-Golay 多带/高级 =================================================
                elseif strcmp(handles.ddDesignMethod.Value, 'Savitzky-Golay')
                    % 需要先设置参数
                    if isempty(handles.sgolayParams)
                        if exist('uialert_safe','file'), uialert_safe(fig_GUI,'请先通过 多带 / 高级滤波参数 按钮设置 Savitzky-Golay 参数。','参数缺失');
                        else; uialert(fig_GUI,'请先通过 多带 / 高级滤波参数 按钮设置 Savitzky-Golay 参数。','参数缺失');
                        end
                        setStatus(handles,'设计失败：缺少 Savitzky-Golay 参数'); 
                        return;
                    end
                    p_sgolay = handles.sgolayParams;
                    % 校验再次确认（可选）
                    if ~isfield(p_sgolay,'m') || ~isfield(p_sgolay,'fl')
                        if exist('uialert_safe','file'), uialert_safe(fig_GUI,'Savitzky-Golay 参数不完整。','参数错误');
                        else; uialert(fig_GUI,'Savitzky-Golay 参数不完整。','参数错误'); end
                        return;
                    end

                    try
                        % 准备权重变量：优先使用数值向量 p_sgolay.w（若存在且非空）
                        useW = isfield(p_sgolay,'w') && ~isempty(p_sgolay.w);
                        if useW
                            w_for_call = p_sgolay.w;
                            % 额外校验：长度必须等于 fl，且全 >0
                            if numel(w_for_call) ~= p_sgolay.fl || any(~isreal(w_for_call)) || any(w_for_call <= 0)
                                if exist('uialert_safe','file'), uialert_safe(fig_GUI,'Savitzky-Golay 权重向量 w 无效（长度或正定性不符）。','参数错误');
                                else; uialert(fig_GUI,'Savitzky-Golay 权重向量 w 无效（长度或正定性不符）。','参数错误'); end
                                return;
                            end
                        end

                        % 若是平滑滤波器：只用 sgolay 返回 B 的中心行
                        if strcmp(p_sgolay.filterType,'smooth')
                            if useW
                                B = sgolay(p_sgolay.m, p_sgolay.fl, w_for_call);
                            else
                                B = sgolay(p_sgolay.m, p_sgolay.fl);
                            end
                            % 检查 B 尺寸是否合理
                            if size(B,1) < (p_sgolay.fl+1)/2
                                if exist('uialert_safe','file'), uialert_safe(fig_GUI,'Savitzky-Golay 返回系数矩阵尺寸异常。','设计错误');
                                else; uialert(fig_GUI,'Savitzky-Golay 返回系数矩阵尺寸异常。','设计错误'); end
                                return;
                            end
                            h_center = B((p_sgolay.fl+1)/2, :);
                            b = h_center(:).';
                            a = 1;
                            % 保存完整矩阵以便需要时调用微分核
                            handles.sgolay_Bmatrix = B;
                            handles.sgolay_Gmatrix = []; % 清空
                        else
                            % 微分滤波器：需要 [B,G] = sgolay(...)
                            if useW
                                [B,G] = sgolay(p_sgolay.m, p_sgolay.fl, w_for_call);
                            else
                                [B,G] = sgolay(p_sgolay.m, p_sgolay.fl);
                            end
                            % 检查 diff_N 字段与可用阶数
                            if ~isfield(p_sgolay,'diff_N') || isempty(p_sgolay.diff_N)
                                if exist('uialert_safe','file'), uialert_safe(fig_GUI,'未指定微分阶数 diff_N。','参数错误');
                                else; uialert(fig_GUI,'未指定微分阶数 diff_N。','参数错误'); end
                                return;
                            end
                            diffN = p_sgolay.diff_N;
                            % G 的列数应该为 m+1（列索引 1..m+1 对应 p=0..m）
                            if diffN > size(G,2)-1
                                if exist('uialert_safe','file'), uialert_safe(fig_GUI,'所选微分阶数超过可得阶数，请修改 m 或 diff_N。','参数错误');
                                else; uialert(fig_GUI,'所选微分阶数超过可得阶数，请修改 m 或 diff_N。','参数错误'); end
                                return;
                            end
                            % 采样间隔 dt 校验
                            if ~isprop(S,'fs') || isempty(S.fs) || S.fs <= 0
                                if exist('uialert_safe','file'), uialert_safe(fig_GUI,'采样率 S.fs 无效，无法计算微分核。','参数错误');
                                else; uialert(fig_GUI,'采样率 S.fs 无效，无法计算微分核。','参数错误'); end
                                return;
                            end
                            dt = 1 / S.fs;
                            % 正确的缩放公式： kernel = factorial(diffN) / (-dt)^diffN * G(:, diffN+1)
                            kernel = factorial(diffN) / ((-dt)^diffN) * G(:, diffN+1);
                            b = kernel(:).';
                            a = 1;
                            handles.sgolay_Bmatrix = B;
                            handles.sgolay_Gmatrix = G;
                        end

                    catch ME
                        if exist('uialert_safe','file'), uialert_safe(fig_GUI, ['Savitzky-Golay 设计出错: ' ME.message], '设计错误');
                        else; uialert(fig_GUI, ['Savitzky-Golay 设计出错: ' ME.message], '设计错误'); end
                        setStatus(handles,'设计失败：Savitzky-Golay 设计出错');
                        return;
                    end
                    acoef = a;
                    % 更新 UI 文本与状态
                    updateDesignLabel(S, handles);


                    

              
                end % FIR优化设计法还是FIR频率设计法、IIR-yulewalk、IIR-maxflat、FIRintfilt插值判断结束

            catch ME
                % 设计失败
                try
                    if exist('uialert_safe','file'), uialert_safe(fig_GUI, sprintf('多带/高级设计失败：%s', ME.message),'设计失败'); else; uialert(fig_GUI, sprintf('多带/高级设计失败：%s', ME.message),'设计失败'); end
                catch
                end
                setStatus(handles,'多带/高级滤波器设计失败'); fprintf('多带/高级滤波器设计调试点: 多带/高级设计失败: %s\n', ME.message);
                return;
            end
    
            % 设计成功：写回 S 并继续后续统一逻辑（和原有流程一致）
            S.filter_b = b; S.filter_a = acoef;
            % 启用应用按钮
            S.filterIsDesigned = true;
            % 设计滤波器成功后，启用 下拉 + 查看 按钮
            handles.ddFilterAnalysis.Enable = 'on';
            handles.btnViewFilterAnalysis.Enable = 'on';
            % 启用前后向滤波选项
            % 滤波函数选择下拉框禁用，因为FIRintfilt插值应用滤波器时使用filter（已在单独分支中应用filter）
            % 滤波函数选择下拉框禁用，因为Savitzky-Golay应用滤波器时不使用filter、filtfilt、my_filtfilt
            if any(strcmp(handles.ddDesignMethod.Value,{'FIRintfilt插值','Savitzky-Golay'}))
                try handles.ddFilterFunction.Value = 'filter'; catch; end
                handles.ddFilterFunction.Enable = 'off';
            else
                handles.ddFilterFunction.Enable = 'on';
            end
                        
            % 启动保存图像按钮
            handles.btnSaveFigs.Enable = 'on';

            updateApplyButtonEnable(S.filterIsDesigned, S.allowApplyFilter, handles);

            if round(double(handles.edtFIROrder.Value)) <= 0
                % 若使用自动估阶逻辑，此处可能需要保存实际阶数到 S.actualFIROrder（保持原逻辑）
                S.actualFIROrder = length(b)-1;
            end
            
            % 更新设计方法提示标签并同步状态栏
            updateDesignLabel(S, handles);  
            % 刷新界面、绘图等（复用原逻辑）
            updateNote(S, handles);
            updateFilterResponsePlots(S, handles);


            setStatus(handles,'多带/高级滤波器设计成功（已保存系数）');
            return; % 多带/高级走完后退出设计流程（避免后续原逻辑重复）
        end


        % ================================================================================= 一般滤波流程 =================================================================================
        % 基本参数校验
        if any([fp1<=0, fp1>=nyq])
            uialert_safe(fig_GUI,'通带截止 fp1 必须在 (0, Fs/2)。','参数错误'); setStatus(handles,'设计失败：fp1 参数错误'); fprintf('调试点22：设计失败：fp1 参数错误\n');return; end
        if any(strcmp(type,{'带通','带阻'}))
            if fp2<=fp1 || fp2>=nyq, uialert_safe(fig_GUI,'带通/带阻需满足 0 < fp1 < fp2 < Fs/2。','参数错误'); setStatus(handles,'设计失败：fp2 参数错误'); fprintf('调试点23：设计失败：fp2 参数错误\n');return; end
        end
        % 检查阻带/通带相对位置并自动修正（尽量避免用户输入导致设计失败）
        switch type
            case '低通'
                if fst1 <= fp1 % 阻带应在通带外
                    setStatus(handles,'警告：阻带 fst1 应 > 通带 fp1，自动调整 fst1 = min(fp1+1, Nyq)');
                    fst1 = min(fp1+1e-6, nyq); handles.edtSb1.Value = fst1; handles.sldSb1.Value = fst1;
                end
            case '高通'
                if fst1 >= fp1
                    setStatus(handles,'警告：阻带 fst1 应 < 通带 fp1，自动调整 fst1 = max(fp1-1,1)');
                    fst1 = max(fp1-1e-6,1e-6); handles.edtSb1.Value = fst1; handles.sldSb1.Value = fst1;
                end
            case '带通'
                % 期望关系： fst1 < fp1 < fp2 < fst2
                if ~(fst1 < fp1 && fp1 < fp2 && fp2 < fst2)
                    % 尝试自动修正为合理关系
                    fst1 = max(1e-6, min(fst1, fp1-1e-6));
                    fst2 = min(nyq, max(fst2, fp2+1e-6));
                    handles.edtSb1.Value = fst1; handles.sldSb1.Value = fst1;
                    handles.edtSb2.Value = fst2; handles.sldSb2.Value = fst2;
                    setStatus(handles,'警告：阻带/通带边界关系不合理，已尝试自动修正。');
                end
            case '带阻'
                % 期望关系： fp1 < fst1 < fst2 < fp2 （阻带位于通带之间）
                if ~(fp1 < fst1 && fst1 < fst2 && fst2 < fp2)
                    % 尝试自动修正为合理关系：把 fst1 拉到 fp1 右侧（>fp1），把 fst2 拉到 fp2 左侧 (<fp2)
                    % 同时确保在 Nyq 与 1 范围内，并保证 fst1 < fst2
                    fst1 = max(fp1 + 1e-6, min(fst1, fp2 - 1e-6));
                    fst2 = min(fp2 - 1e-6, max(fst2, fp1 + 1e-6));
                    % 若修正后发生交叉，再做最小安全修正
                    if fst1 >= fst2
                        mid = floor((fp1 + fp2) / 2);
                        fst1 = max(fp1 + 1e-6, mid - 1e-6);
                        fst2 = min(fp2 - 1e-6, mid + 1e-6);
                    end
                    handles.edtSb1.Value = fst1; handles.sldSb1.Value = fst1;
                    handles.edtSb2.Value = fst2; handles.sldSb2.Value = fst2;
                    setStatus(handles,'警告：带阻规格应为 fp1 < fst1 < fst2 < fp2，已尝试自动修正。');
                end
        end
    
        setStatus(handles,'开始设计滤波器...'); 
        % drawnow;
        try
            if strcmpi(method,'IIR')
                % ----------------- IIR 设计（自动估阶或用户阶数） -----------------
                userOrder = round(double(handles.edtIIROrder.Value));
                proto = strtrim(handles.ddIIRProto.Value);    % 规范化字符串
                proto_low = lower(proto);
                Rp = double(handles.edtRp.Value);
                Rs = double(handles.edtRs.Value);
                % 重新从 UI 读取频率（以防 UI 状态刚被 applyIIRProtoEnables 改变）
                fp1 = double(handles.edtPb1.Value); fp2 = double(handles.edtPb2.Value);
                fst1 = double(handles.edtSb1.Value); fst2 = double(handles.edtSb2.Value);
                nyq = S.fs/2;
    
                % 归一化 helper（0 < freq/nyq < 1，但避免 0/1 边界）
                norm_safe = @(freq) max(eps, min(0.999999, (freq./nyq)));
    
                % 构造规范化 Wp / Ws（按类型）
                switch type
                    case '低通'
                        Wp = norm_safe(fp1); Wst = norm_safe(fst1);
                    case '高通'
                        Wp = norm_safe(fp1); Wst = norm_safe(fst1);
                    case '带通'
                        Wp = [norm_safe(fp1) norm_safe(fp2)]; Wst = [norm_safe(fst1) norm_safe(fst2)];
                    case '带阻'
                        Wp = [norm_safe(fp1) norm_safe(fp2)]; Wst = [norm_safe(fst1) norm_safe(fst2)];
                    otherwise
                        uialert_safe(fig_GUI,'未知滤波类型','参数错误'); setStatus(handles,'设计失败：未知滤波类型'); fprintf('调试点24：设计失败：未知滤波类型\n');return;
                end
    
                % ------------ 自动估阶（userOrder <= 0）：使用 ord 函数 ------------
                if userOrder <= 0
                    try
                        % 先做基本的规格检查（顺序校验）
                        switch type
                            case '低通'
                                if ~(Wp < Wst)
                                    uialert_safe(fig_GUI,'低通规格需满足 fp < fst','规格错误'); setStatus(handles,'设计失败：低通规格错误'); fprintf('调试点25：设计失败：低通规格错误\n');return;
                                end
                            case '高通'
                                if ~(Wp > Wst)
                                    uialert_safe(fig_GUI,'高通规格需满足 fp > fst','规格错误'); setStatus(handles,'设计失败：高通规格错误');fprintf('调试点26：设计失败：高通规格错误\n'); return;
                                end
                            case '带通'
                                if ~(Wst(1) < Wp(1) && Wp(1) < Wp(2) && Wp(2) < Wst(2))
                                    uialert_safe(fig_GUI,'带通需满足 fst1 < fp1 < fp2 < fst2','规格错误'); setStatus(handles,'设计失败：带通规格错误'); fprintf('调试点27：设计失败：带通规格错误\n');return;
                                end
                            case '带阻'
                                if ~(Wp(1) < Wst(1) && Wst(1) < Wst(2) && Wst(2) < Wp(2))
                                    uialert_safe(fig_GUI,'带阻需满足 fp1 < fst1 < fst2 < fp2','规格错误'); setStatus(handles,'设计失败：带阻规格错误'); fprintf('调试点28：设计失败：带阻规格错误\n');return;
                                end
                        end
    
                        % 调用对应 ord 函数：取回 nCalc 与 WnCalc（WnCalc 可直接供设计函数使用）
                        switch lower(proto_low)
                            case 'butterworth'
                                [nCalc, WnCalc] = buttord(Wp, Wst, Rp, Rs);   % buttord 返回 [n,Wn]
                            case {'chebyshev i','cheby1','chebyshev1'}
                                [nCalc, WnCalc] = cheb1ord(Wp, Wst, Rp, Rs);  % cheb1ord 返回 [n,Wp]（可直接给 cheby1）
                            case {'chebyshev ii','cheby2','chebyshev2'}
                                [nCalc, WnCalc] = cheb2ord(Wp, Wst, Rp, Rs);  % cheb2ord 返回 [n,Wst]（可直接给 cheby2）
                            case {'elliptic','ellip','elliptic '}
                                [nCalc, WnCalc] = ellipord(Wp, Wst, Rp, Rs);  % ellipord 返回 [n,Wn]
                            case {'yule-walker','yulewalk'}
                                % ----------------- Yule-Walker (yulewalk) 设计 -----------------
                                % 注意：yulewalk 需要显式给出阶数（不支持自动估阶）
                                if userOrder <= 0
                                    if exist('uialert_safe','file')
                                        uialert_safe(fig_GUI, 'IIR - Yule-Walker (yulewalk) 不支持自动估阶。请在 "IIR 阶数" 输入框中输入正整数。', '参数错误');
                                    else
                                        uialert(fig_GUI, 'IIR - Yule-Walker (yulewalk) 不支持自动估阶。请在 "IIR 阶数" 输入框中输入正整数。', '参数错误');
                                    end
                                    setStatus(handles,'设计失败：Yule-Walker 需要正整数阶数');
                                    return;
                                end

                            case {'maxflat','maxflat '}
                                % 注意：maxflat 需要显式给出阶数（不支持自动估阶）
                                if userOrder <= 0
                                    if exist('uialert_safe','file')
                                        uialert_safe(fig_GUI,'maxflat 不支持自动估阶。请在 "IIR 阶数" 输入框中输入正整数。','参数错误');
                                    else
                                        uialert(fig_GUI,'maxflat 不支持自动估阶。请在 "IIR 阶数" 输入框中输入正整数。','参数错误'); 
                                    end
                                    setStatus(handles,'设计失败：maxflat 需要正整数阶数');
                                    return;
                                end

                            otherwise
                                error('未知 IIR 原型：%s', proto);
                        end

                       
                        % 阶数安全阈值检查
                        if (max(double(nCalc)) > 60)
                            setStatus(handles,sprintf('计算得到阶数 n=%d（过大）。', nCalc));
                            fprintf('调试点29：计算得到阶数过大\n');
                            uialert_safe(fig_GUI, sprintf('计算得到阶数过大 (n = %d)。请放宽规格或改用 FIR / SOS 实现。', nCalc), '高阶警告',"Icon","warning");

                            return;
                        end
                        
                        % 记录并用 ord 输出设计滤波器（使用 WnCalc）
                        order = max(1, round(nCalc));
                        S.actualIIROrder = order;
                        % 更新设计方法提示标签并同步状态栏
                        updateDesignLabel(S, handles);
                        
    
                        % 使用 WnCalc 调用设计函数（按滤波类型）
                        switch lower(proto_low)
                            case 'butterworth'
                                switch type
                                    case '低通',  [b,a] = butter(order, WnCalc, 'low');
                                    case '高通',  [b,a] = butter(order, WnCalc, 'high');
                                    case '带通',  [b,a] = butter(order, WnCalc, 'bandpass');
                                    case '带阻',  [b,a] = butter(order, WnCalc, 'stop');
                                end
                            case {'chebyshev i','cheby1'}
                                switch type
                                    case '低通',  [b,a] = cheby1(order, Rp, WnCalc, 'low');
                                    case '高通',  [b,a] = cheby1(order, Rp, WnCalc, 'high');
                                    case '带通',  [b,a] = cheby1(order, Rp, WnCalc, 'bandpass');
                                    case '带阻',  [b,a] = cheby1(order, Rp, WnCalc, 'stop');
                                end
                            case {'chebyshev ii','cheby2'}
                                switch type
                                    case '低通',  [b,a] = cheby2(order, Rs, WnCalc, 'low');
                                    case '高通',  [b,a] = cheby2(order, Rs, WnCalc, 'high');
                                    case '带通',  [b,a] = cheby2(order, Rs, WnCalc, 'bandpass');
                                    case '带阻',  [b,a] = cheby2(order, Rs, WnCalc, 'stop');
                                end
                            case {'elliptic','ellip'}
                                switch type
                                    case '低通',  [b,a] = ellip(order, Rp, Rs, WnCalc, 'low');
                                    case '高通',  [b,a] = ellip(order, Rp, Rs, WnCalc, 'high');
                                    case '带通',  [b,a] = ellip(order, Rp, Rs, WnCalc, 'bandpass');
                                    case '带阻',  [b,a] = ellip(order, Rp, Rs, WnCalc, 'stop');
                                end
                            case {'yule-walker','yulewalk'}
                                % ----------------- Yule-Walker (yulewalk) 设计 -----------------
                                % 注意：yulewalk 需要显式给出阶数（不支持自动估阶）
                                if userOrder <= 0
                                    if exist('uialert_safe','file')
                                        uialert_safe(fig_GUI, 'IIR - Yule-Walker (yulewalk) 不支持自动估阶。请在 "IIR 阶数" 中输入正整数。', '参数错误');
                                    else
                                        uialert(fig_GUI, 'IIR - Yule-Walker (yulewalk) 不支持自动估阶。请在 "IIR 阶数" 中输入正整数。', '参数错误');
                                    end
                                    setStatus(handles,'设计失败：Yule-Walker 需要正整数阶数'); return;
                                end
                            case {'maxflat','maxflat '}
                                % 注意：maxflat 需要显式给出阶数（不支持自动估阶）
                                if userOrder <= 0
                                    if exist('uialert_safe','file')
                                        uialert_safe(fig_GUI,'maxflat 不支持自动估阶。请在 "IIR 阶数" 输入框中输入正整数。','参数错误');
                                    else
                                        uialert(fig_GUI,'maxflat 不支持自动估阶。请在 "IIR 阶数" 输入框中输入正整数。','参数错误'); 
                                    end
                                    setStatus(handles,'设计失败：maxflat 需要正整数阶数');
                                    return;
                                end
                        end
    
                    catch ME
                        uialert_safe(fig_GUI, ['滤波器自动阶数估算或设计失败：', ME.message], '设计错误');
                        setStatus(handles,['设计失败：', ME.message]);
                        fprintf('调试点30：滤波器自动阶数估算或设计失败\n');
                        return;
                    end
    
                % ------------ 用户指定阶数（userOrder > 0）：按原有逻辑直接设计 ------------
                else
                    try
                        order = max(1, round(userOrder));
                        % 更新设计方法提示标签并同步状态栏
                        updateDesignLabel(S, handles);
    
                        % 准备传给设计函数的 W 值（按类型）
                        if strcmp(type,'低通') || strcmp(type,'高通')
                            % 单值
                            Wn = norm_safe(fp1);  
                            Wp = norm_safe(fp1); 
                            Wst = norm_safe(fst1);
                        else
                            % 双侧频率
                            Wn = [norm_safe(fp1) norm_safe(fp2)]; 
                            Wp = [norm_safe(fp1) norm_safe(fp2)]; 
                            Wst = [norm_safe(fst1) norm_safe(fst2)];
                        end
    
                        switch lower(proto_low)
                            case 'butterworth'
                                switch type
                                    case '低通',  [b,a] = butter(order, Wn, 'low');
                                    case '高通',  [b,a] = butter(order, Wn, 'high');
                                    case '带通',  [b,a] = butter(order, Wn, 'bandpass');
                                    case '带阻',  [b,a] = butter(order, Wn, 'stop');
                                end
                            case {'chebyshev i','cheby1'}
                                switch type
                                    case '低通',  [b,a] = cheby1(order, Rp, Wp, 'low');
                                    case '高通',  [b,a] = cheby1(order, Rp, Wp, 'high');
                                    case '带通',  [b,a] = cheby1(order, Rp, Wp, 'bandpass');
                                    case '带阻',  [b,a] = cheby1(order, Rp, Wp, 'stop');
                                end
                            case {'chebyshev ii','cheby2'}
                                % 注意：cheby2 设计需要 Rs 与 Ws
                                switch type
                                    case '低通',  [b,a] = cheby2(order, Rs, Wst, 'low');
                                    case '高通',  [b,a] = cheby2(order, Rs, Wst, 'high');
                                    case '带通',  [b,a] = cheby2(order, Rs, Wst, 'bandpass');
                                    case '带阻',  [b,a] = cheby2(order, Rs, Wst, 'stop');
                                end
                            case {'elliptic','ellip'}
                                switch type
                                    case '低通',  [b,a] = ellip(order, Rp, Rs, Wp, 'low');
                                    case '高通',  [b,a] = ellip(order, Rp, Rs, Wp, 'high');
                                    case '带通',  [b,a] = ellip(order, Rp, Rs, Wp, 'bandpass');
                                    case '带阻',  [b,a] = ellip(order, Rp, Rs, Wp, 'stop');
                                end
                            case {'yule-walker','yulewalk'}
                                % ----------------- Yule-Walker (yulewalk) 设计 -----------------
                                % 注意：yulewalk 需要显式给出阶数（不支持自动估阶）
                                % 构建归一化频率向量 f_norm（0..1），与幅值 m（线性）
                                switch type
                                    case '低通'
                                        f_norm = [0, Wp, Wst, 1];
                                        m_vec  = [1, 1, 0, 0];
                                    case '高通'
                                        f_norm = [0, Wst, Wp, 1];
                                        m_vec  = [0, 0, 1, 1];
                                    case '带通'
                                        % 结构：0 ... fst1 fp1 fp2 fst2 ... 1
                                        f_norm = [0, norm_safe(fst1), norm_safe(fp1), norm_safe(fp2), norm_safe(fst2), 1];
                                        m_vec  = [0, 0, 1, 1, 0, 0];
                                    case '带阻'
                                        % 结构：0 ... fp1 fst1 fst2 fp2 ... 1
                                        f_norm = [0, norm_safe(fp1), norm_safe(fst1), norm_safe(fst2), norm_safe(fp2), 1];
                                        m_vec  = [1, 1, 0, 0, 1, 1];
                                    otherwise
                                        uialert_safe(fig_GUI, '未知滤波类型（yulewalk）。', '参数错误'); setStatus(handles,'设计失败：未知滤波类型'); return;
                                end
                              
                                [b,a] = yulewalk(order, f_norm, m_vec);

                                % 可选稳定性检查（若极点半径 >= 1 则警告）
                                try
                                    pz = roots(a);
                                    if any(abs(pz) >= 1)
                                        % 警告但仍保存系数（你也可以在这里把滤波器稳定化）
                                        if exist('uialert_safe','file')
                                            uialert_safe(fig_GUI,'警告：设计得到的 IIR 可能不稳定（存在极点在或超出单位圆）。请尝试降低阶数或改用其它原型。','设计告警',"Icon","warning");
                                        else
                                            uialert(fig_GUI,'警告：设计得到的 IIR 可能不稳定（存在极点在或超出单位圆）。请尝试降低阶数或改用其它原型。','设计告警');
                                        end
                                    end
                                catch
                                end

                            case {'maxflat','maxflat '}
                                m = order; % 简单使 n=m。若需要分子阶数与分母阶数不同，需要通过"多带/高级滤波参数"按钮设置
                                switch type
                                    case '低通'
                                        [b, a] = my_maxflat(order, m, Wn); % 低通
                                    case '高通'
                                        [b, a] = my_maxflat(order, m, Wn, 'high'); % 高通
                                    otherwise
                                        uialert_safe(fig_GUI, '不支持该滤波类型或未知滤波类型（maxflat）。', '参数错误'); setStatus(handles,'设计失败：不支持或未知滤波类型'); 
                                        return;
                                end


                            otherwise
                                error('未知 IIR 原型：%s', proto);
                        end
                        % 设计成功后可执行后续处理（图形/频响应等）


                    catch ME
                        uialert_safe(fig_GUI, ['手动阶数设计失败：' ME.message], '设计错误');
                        setStatus(handles,['设计失败：', ME.message]);
                        fprintf('调试点31：手动阶数设计失败\n');
                        return;
                    end
                end % IIR设计分支结束

    
            elseif strcmpi(method,'FIR窗函数法')
                % ----------------- FIR 窗函数法（fir1） - 支持 Kaiser & 自动估阶 -----------------
                N = round(double(handles.edtFIROrder.Value));
                wndName = handles.ddWindow.Value;

                % --- 强制兼容 fir1 的偶数阶要求（高通 & 带阻需偶数阶）
                % 仅在用户给定了明确阶数（N>0）或我们在后续分支把 N 设为默认值后有效地使用时生效。
                % 这里做一次通用安全检查（对于之后每个分支也会再次保障）。
                if exist('N','var') && isscalar(N)
                    % 不在此处改动 N<=0 的自动估阶语义；但若 N>0 且为奇数且类型是高通/带阻，则调整为偶数
                    if N > 0 && any(strcmp(type, {'高通','带阻'})) && rem(N,2) == 1
                        N = N + 1; % 使为偶数
                        setStatus(handles,sprintf('为兼容 fir1 高通/带阻约束，将阶数调整为偶数 N=%d', N));
                        warning('为兼容 fir1 高通/带阻约束，将阶数调整为偶数 N=%d', N);
                    end
                end


                % 频率、规格读取（注意 nyq 与 fp/fst 单侧值的处理需与主设计保持一致）
                fp1 = double(handles.edtPb1.Value); fp2 = double(handles.edtPb2.Value);
                fst1 = double(handles.edtSb1.Value); fst2 = double(handles.edtSb2.Value);
                Rp_val = max(0, double(handles.edtRp.Value)); Rs_val = max(0, double(handles.edtRs.Value));
                dp = max(eps, (10^(Rp_val/20)-1) / (10^(Rp_val/20)+1));% 通带线性误差
                ds = max(eps, 10^(-Rs_val/20));
                
                switch wndName
                    case 'Rectwin'
                        if isempty(N) || N <= 0
                            uialert_safe(fig_GUI, 'FIR窗函数法 - Rectwin不支持自动估阶。请在 "FIR 阶数" 输入框中输入正整数。', '参数错误');
                            setStatus(handles,'设计失败：FIR窗函数法 - Rectwin 需要正整数阶数'); return;
                        end
                        if any(strcmp(type, {'高通','带阻'})) && rem(N,2)==1, N = N+1; end
                        wnd = rectwin(N+1);
                        switch type
                            case '低通', Wn = max(eps, min(1-eps, fp1/nyq)); b = fir1(N,Wn,wnd);
                            case '高通', Wn = max(eps, min(1-eps, fp1/nyq)); b = fir1(N,Wn,'high',wnd);
                            case '带通', Wn = max(eps, min(1-eps, [fp1 fp2]/nyq)); b = fir1(N,Wn,wnd);
                            case '带阻', Wn = max(eps, min(1-eps, [fp1 fp2]/nyq)); b = fir1(N,Wn,'stop',wnd);
                        end
                    case 'Triang'
                        if isempty(N) || N <= 0
                            uialert_safe(fig_GUI, 'FIR窗函数法 - Triang不支持自动估阶。请在 "FIR 阶数" 输入框中输入正整数。', '参数错误');
                            setStatus(handles,'设计失败：FIR窗函数法 - Triang 需要正整数阶数'); return;
                        end
                        if any(strcmp(type, {'高通','带阻'})) && rem(N,2)==1, N = N+1; end
                        wnd = triang(N+1);
                        switch type
                            case '低通', Wn = max(eps, min(1-eps, fp1/nyq)); b = fir1(N,Wn,wnd);
                            case '高通', Wn = max(eps, min(1-eps, fp1/nyq)); b = fir1(N,Wn,'high',wnd);
                            case '带通', Wn = max(eps, min(1-eps, [fp1 fp2]/nyq)); b = fir1(N,Wn,wnd);
                            case '带阻', Wn = max(eps, min(1-eps, [fp1 fp2]/nyq)); b = fir1(N,Wn,'stop',wnd);
                        end
                    case 'Hann'
                        if isempty(N) || N <= 0
                            uialert_safe(fig_GUI, 'FIR窗函数法 - Hann不支持自动估阶。请在 "FIR 阶数" 输入框中输入正整数。', '参数错误');
                            setStatus(handles,'设计失败：FIR窗函数法 - Hann 需要正整数阶数'); return;
                        end
                        if any(strcmp(type, {'高通','带阻'})) && rem(N,2)==1, N = N+1; end
                        wnd = hann(N+1); 
                        switch type
                            case '低通', Wn = max(eps, min(1-eps, fp1/nyq)); b = fir1(N,Wn,wnd);
                            case '高通', Wn = max(eps, min(1-eps, fp1/nyq)); b = fir1(N,Wn,'high',wnd);
                            case '带通', Wn = max(eps, min(1-eps, [fp1 fp2]/nyq)); b = fir1(N,Wn,wnd);
                            case '带阻', Wn = max(eps, min(1-eps, [fp1 fp2]/nyq)); b = fir1(N,Wn,'stop',wnd);
                        end
                    case 'Hamming'
                        if isempty(N) || N <= 0
                            uialert_safe(fig_GUI, 'FIR窗函数法 - Hamming不支持自动估阶。请在 "FIR 阶数" 输入框中输入正整数。', '参数错误');
                            setStatus(handles,'设计失败：FIR窗函数法 - Hamming 需要正整数阶数'); return;
                        end
                        % 高通/带阻需偶数阶（与 fir1 要求一致）
                        if any(strcmp(type, {'高通','带阻'})) && rem(N,2)==1, N = N+1; end
                        wnd = hamming(N+1);
                        switch type
                            case '低通'
                                Wn = max(eps, min(1-eps, fp1/nyq)); b = fir1(N, Wn, wnd);
                            case '高通'
                                Wn = max(eps, min(1-eps, fp1/nyq)); b = fir1(N, Wn, 'high', wnd);
                            case '带通'
                                Wn = max(eps, min(1-eps, [fp1 fp2]/nyq)); b = fir1(N, Wn, wnd);
                            case '带阻'
                                Wn = max(eps, min(1-eps, [fp1 fp2]/nyq)); b = fir1(N, Wn, 'stop', wnd);
                        end
                    case 'Blackman'
                        if isempty(N) || N <= 0
                            uialert_safe(fig_GUI, 'FIR窗函数法 - Blackman不支持自动估阶。请在 "FIR 阶数" 输入框中输入正整数。', '参数错误');
                            setStatus(handles,'设计失败：FIR窗函数法 - Blackman 需要正整数阶数'); return;
                        end
                        if any(strcmp(type, {'高通','带阻'})) && rem(N,2)==1, N = N+1; end
                        wnd = blackman(N+1);
                        switch type
                            case '低通', Wn = max(eps, min(1-eps, fp1/nyq)); b = fir1(N,Wn,wnd);
                            case '高通', Wn = max(eps, min(1-eps, fp1/nyq)); b = fir1(N,Wn,'high',wnd);
                            case '带通', Wn = max(eps, min(1-eps, [fp1 fp2]/nyq)); b = fir1(N,Wn,wnd);
                            case '带阻', Wn = max(eps, min(1-eps, [fp1 fp2]/nyq)); b = fir1(N,Wn,'stop',wnd);
                        end
                    case 'Kaiser'
                        % kaiserord 在 R2025b 支持带 fs 参数（我们传 S.fs）并返回 Wn（Hz）和 beta。因此把 WnK 除以 (S.fs/2) 成为 fir1 的 0–1 归一化值（如上所示）。
                        % 我已在代码里加入对阶数过大（>2000）或负值的保护与提示。
                        % 若您想让用户能设置 beta（Kaiser 的形状参数），可以在 GUI 上新增 edtKaiserBeta 输入框；目前用 kaiserord 返回的 beta（自动估算）在自动模式下可用；在用户手动给定 N 时，我用了 beta = 0 作示例（可改为默认 3 或让用户输入）。
                        % 如果用户提供阶数 (>0)，使用用户阶数并尝试用默认 beta (可改进为允许输入 beta)
                        if N > 0

                            % 用户指定阶数：先确保高通/带阻为偶数
                            if any(strcmp(type, {'高通','带阻'})) && rem(N,2)==1, N = N+1; end

                            
                            % 根据Rs_val计算Beta
                            % Rs_val 应为阻带衰减（dB）
                            if Rs_val <= 21
                                beta = 0;
                            elseif Rs_val < 50
                                beta = 0.5842*(Rs_val - 21)^0.4 + 0.07886*(Rs_val - 21);
                            else
                                beta = 0.1102*(Rs_val - 8.7);
                            end

                            wnd = kaiser(N+1, beta);
                                switch type
                                    case '低通',  Wn = max(eps, min(1-eps, fp1/nyq)); b = fir1(N,Wn,wnd,"noscale");
                                    case '高通',  Wn = max(eps, min(1-eps, fp1/nyq)); b = fir1(N,Wn,'high',wnd,"noscale");
                                    case '带通',  Wn = max(eps, min(1-eps, [fp1 fp2]/nyq)); b = fir1(N,Wn,wnd,"noscale");
                                    case '带阻',  Wn = max(eps, min(1-eps, [fp1 fp2]/nyq)); b = fir1(N,Wn,'stop',wnd,"noscale");
                                end
                
                        else
                            % 自动估阶：利用 kaiserord 需要 freq, a, dev（并传入 fs）
                            try
                                switch type
                                    case '低通'
                                        freq = [fp1 fst1]; a = [1 0]; dev = [dp ds];
                                    case '高通'
                                        freq = [fst1 fp1]; a = [0 1]; dev = [ds dp];
                                    case '带通'
                                        freq = [fst1 fp1 fp2 fst2]; a = [0 1 0]; dev = [ds dp ds];
                                    case '带阻'
                                        freq = [fp1 fst1 fst2 fp2]; a = [1 0 1]; dev = [dp ds dp];
                                end
                                % 使用采样率 S.fs 让 kaiserord 的频率以 Hz 为单位
                                [nCalc, WnK, beta, ~] = kaiserord(freq, a, dev, S.fs);
                                if nCalc < 1, nCalc = 1; end
                                if nCalc > 2000
                                    uialert_safe(fig_GUI, sprintf('Kaiser 自动估阶得到非常高阶数 n=%d，建议放宽规格或改用 FIR 优化法。', nCalc), '高阶警告',"Icon","warning");
                                    setStatus(handles,sprintf('Kaiser：估算阶数 n=%d（过大）', nCalc));
                                    fprintf('调试点32：Kaiser：估算阶数过大\n');
                                    return;
                                end
                                % 使用 kaiser 得到窗再设计
                                N = nCalc;
                                % 自动估阶时也需保证高通/带阻为偶数
                                if any(strcmp(type, {'高通','带阻'})) && rem(N,2)==1, N = N + 1; end
                                wnd = kaiser(N+1, beta);
                                S.actualFIROrder = N;

                                % kaiserord 返回归一化的 Wn，可直接给 fir1
                                Wn_norm = WnK;  % kaiserord 返回 0..1 归一化频率
                                % 设计
                                switch type
                                    case '低通',  b = fir1(N, Wn_norm, wnd, "noscale");
                                    case '高通',  b = fir1(N, Wn_norm, 'high', wnd, "noscale");
                                    case '带通',  b = fir1(N, Wn_norm, wnd, "noscale");
                                    case '带阻',  b = fir1(N, Wn_norm, 'stop', wnd, "noscale");
                                end
                            catch ME
                                uialert_safe(fig_GUI, ['Kaiser 窗自动估阶失败：' ME.message], '设计错误');
                                setStatus(handles,['Kaiser 估阶失败：', ME.message]);
                                fprintf('调试点33：Kaiser 窗自动估阶失败\n');
                                return;
                            end
                        end
                end
                a = 1; % FIR 的 a
    
            elseif strcmpi(method,'FIR优化设计法')
                % -----------------  FIR 优化设计法（根据 ddFIRMethod 选择具体算法） -----------------
                N = round(double(handles.edtFIROrder.Value));
                if N < 0, N = 0; end  % N=0 表示希望自动估阶
    
                % 添加状态栏提示
                if N <= 0
                    setStatus(handles,'FIR优化设计法：自动估算阶数中...');
                else
                    setStatus(handles,sprintf('FIR优化设计法：使用指定阶数 %d', N));
                end
    
                firSub = handles.ddFIRMethod.Value;
                % 频率归一化函数
                normf = @(x) max(0, min(1, double(x) / max(eps, nyq)));
                % 将 Rp/Rs 转为线性误差（供 firpmord/firpm 使用）
                Rp_val = max(0, double(handles.edtRp.Value));
                Rs_val = max(0, double(handles.edtRs.Value));
                dp = (10^(Rp_val/20)-1) / (10^(Rp_val/20)+1);
                ds = 10^(-Rs_val/20);
    
                switch firSub
                    case 'Parks-McClellan'
                        % 使用 firpmord 优先自动估阶（注意 freq 的顺序必须严格递增）
                        try
                            switch type
                                case '低通'
                                    % freq = [fp, fst] (Hz)，a = [1 0]，dev = [dp ds]
                                    [nCalc, fo, ao, wpm] = firpmord([fp1 fst1], [1 0], [dp ds], S.fs);
                                case '高通'
                                    % freq = [fst, fp] (Hz)，a = [0 1]，dev = [ds dp]
                                    [nCalc, fo, ao, wpm] = firpmord([fst1 fp1], [0 1], [ds dp], S.fs);
                                case '带通'
                                    % freq = [fst1 fp1 fp2 fst2]，a = [0 1 0]，dev = [ds dp ds]
                                    % （要求 fst1 < fp1 < fp2 < fst2）
                                    [nCalc, fo, ao, wpm] = firpmord([fst1 fp1 fp2 fst2], [0 1 0], [ds dp ds], S.fs);
                                case '带阻'
                                    % **修正点**：带阻应使用递增的边界向量 [fp1 fst1 fst2 fp2]
                                    % 这对应三段：通(低) / 阻 / 通(高)，幅值 a = [1 0 1]
                                    % 对应 dev = [dp ds dp]（通带允许 dp，阻带允许 ds）
                                    [nCalc, fo, ao, wpm] = firpmord([fp1 fst1 fst2 fp2], [1 0 1], [dp ds dp], S.fs);
                                otherwise
                                    fprintf('调试点34：未知类型（Parks-McClellan）\n');
                                    error('未知类型（Parks-McClellan）：%s', type);
                                    
                            end
                                                      
    
                            % 静态阈值
                            warning_threshold = 300; % 警告阈值
                            error_threshold = 900; % 报错阈值
                            
                            % 如果返回的阶数异常大，提醒用户
                            if (N <= 0) && (nCalc > error_threshold)
                                % 提供具体建议
                                msg = sprintf(['计算阶数: %d (> %d，过大)\n'...
                                               '可能原因: 过渡带太窄或容差要求过严\n'...
                                               '建议: 1. 增加过渡带宽度\n'...
                                               '      2. 放宽Rp/Rs要求\n'...
                                               '      3. 考虑使用IIR滤波器'], ...
                                               nCalc, error_threshold);
                                
                                uialert_safe(fig_GUI, msg, '高阶滤波器警告',"Icon","warning");
                                setStatus(handles,sprintf('阶数过大：%d (> %d)，请调整滤波器参数', nCalc, error_threshold));
                                fprintf('调试点35：Parks-McClellan自动估阶阶数过大，请调整滤波器参数\n');
                                return;
                            end
                            
                            % 对于中等阶数，可以警告但不阻止
                            if (N <= 0) && (nCalc > warning_threshold)
                                setStatus(handles,sprintf('注意: 滤波器阶数较高：%d (> %d)，可能影响处理速度', nCalc, warning_threshold));
                                fprintf('调试点36：警告： Parks-McClellan滤波器自动估阶阶数较高，可能影响处理速度\n');
                            end
    
                            % 如果设置的阶数异常大，提醒用户降低设置值
                            if N > error_threshold
                                % 提供具体建议
                                msg = sprintf('设置阶数过大：%d (> %d)，请降低设置阶数', N, error_threshold);
                                uialert_safe(fig_GUI, msg, '高阶滤波器警告',"Icon","warning");
                                setStatus(handles,sprintf('设置阶数过大：%d (> %d)，请降低设置阶数', N, error_threshold));
                                fprintf('调试点37：Parks-McClellan滤波器自定义设置阶数过大，请降低设置阶数\n');
                                return;
                            end
                            
                            % 对于中等阶数，可以警告但不阻止
                            if N > warning_threshold
                                setStatus(handles,sprintf('注意: 滤波器阶数较高：%d (> %d)，可能影响处理速度', N, warning_threshold));
                                fprintf('调试点38：警告：Parks-McClellan滤波器自定义设置阶数过大，可能影响处理速度\n');
                            end
                            
                            % if N <= 0, N = nCalc; end
                            if N <= 0
                                N = nCalc;
                                % 更新状态栏提示
                                setStatus(handles,sprintf('FIR优化设计法：自动估算阶数为 %d', N));
                            end
    
                            b = firpm(N, fo, ao, wpm);
                            a = 1;
                        catch ME
                            fprintf('调试点39_0：firpmord 自动估算阶数不可用，正使用手工构造的 freq/amp/weight... \n');
                            % 回退：若 firpmord 不可用，则用手工构造 freq/amp/weight 后调用 firpm
                            try
                                switch type
                                    case '低通'
                                        fvec = [0 normf(fp1) normf(fst1) 1];
                                        Avec = [1 1 0 0];
                                        wgt = [1 max(eps, dp/ds)];
                                    case '高通'
                                        fvec = [0 normf(fst1) normf(fp1) 1];
                                        Avec = [0 0 1 1];
                                        wgt = [max(eps, ds/dp) 1];
                                    case '带通'
                                        fvec = [0 normf(fst1) normf(fp1) normf(fp2) normf(fst2) 1];
                                        Avec = [0 0 1 1 0 0];
                                        wgt = [1 max(eps, dp/ds) 1];
                                    case '带阻'
                                        % 正确的递增顺序： 0 < fp1 < fst1 < fst2 < fp2 < Nyq(=1)
                                        fvec = [0, normf(fp1), normf(fst1), normf(fst2), normf(fp2), 1];
                                        % 对应的理想幅度点（6点）：两侧通带=1，中间阻带=0
                                        Avec = [1, 1, 0, 0, 1, 1];
                                        % 权重：通常对通带、阻带分别指定；这里保持与其它情况类似的策略
                                        wgt = [1, max(eps, dp/ds), 1];  % 3 bands -> length(wgt)=3
                                    otherwise
                                        error('Parks-McClellan 不支持的滤波类型：%s', type);

                                end

                                % 确保 fvec 非递减、长度为偶数、与 Avec 长度一致
                                if any(diff(fvec) < 0)
                                    error('构造的 fvec 不是非递减序列，请检查 fp/fst 参数顺序。');
                                end
                                if numel(fvec) ~= numel(Avec) || mod(numel(fvec),2) ~= 0
                                    error('firls 要求 freq 和 a 长度相同且为偶数。');
                                end
                                 
                                if N <= 0
                                    % 自动估阶（一种简单启发式）：以过渡带宽为依据
                                    N = max(1, round(4*nyq/min([abs(fp1-fst1), abs(fst2-fp2), nyq/10]))); 
                                    % 更新状态栏提示
                                    setStatus(handles,sprintf('FIR优化设计法：自动估算阶数为 %d', N));
                                end
                                b = firpm(max(1,N), fvec, Avec, wgt);
                                a = 1;
                            catch ME2
                                fprintf('调试点39：Parks-McClellan 设计失败\n');
                                error(['Parks-McClellan 设计失败：', ME.message]);
                            end
                        end


                    % ==========================  使用 -1..1的写法，使用MATLAB预定义的 @lowpass / @highpass / @bandpass / @bandstop；b = cfirpm(n, f, fresp, w)===========================================
                    case 'Cplx-Parks-McClellan'
                        % ------------- cfirpm 设计（统一使用 -1..1 写法，fresp 使用 MATLAB 内置句柄）-------------
                        % 必须从 UI 读取当前滤波类型
                        type = handles.ddType.Value;
                    
                        % 阶数读取与检查（cfirpm 不支持自动估阶——要求正整数阶）
                        N = round(double(handles.edtFIROrder.Value));
                        if isempty(N) || N <= 0
                            if exist('uialert_safe','file')
                                uialert_safe(fig_GUI, 'FIR 优化设计法 Complex-Parks-McClellan 不支持自动估阶。请在 "FIR 阶数" 输入框中填写正整数后重试。', '参数错误');
                            else
                                uialert(fig_GUI, 'FIR 优化设计法 Complex-Parks-McClellan 不支持自动估阶。请在 "FIR 阶数" 输入框中填写正整数后重试。', '参数错误');
                            end
                            setStatus(handles,'设计取消：无效的 FIR 阶数');
                            return;
                        end
                    
                        % 归一化映射函数（物理频率 [0, Fs/2] -> [0,1]）
                        normf = @(fHz) (fHz ./ (S.fs/2));   % 之后在构造 -1..1 向量时手动镜像负频
                    
                        % 读取频率参数（UI）
                        fp1 = double(handles.edtPb1.Value); fp2 = double(handles.edtPb2.Value);
                        fst1 = double(handles.edtSb1.Value); fst2 = double(handles.edtSb2.Value);
                    
                        % 基本检查：NaN / 范围
                        allFreqs = [fp1, fp2, fst1, fst2];
                        if any(isnan(allFreqs))
                            if exist('uialert_safe','file')
                                uialert_safe(fig_GUI, '请填写全部频率参数（不能为 NaN）。', '参数错误');
                            else
                                uialert(fig_GUI, '请填写全部频率参数（不能为 NaN）。', '参数错误');
                            end
                            setStatus(handles,'设计取消：频率参数缺失');
                            return;
                        end
                        if any(allFreqs < 0) || any(allFreqs > S.fs/2)
                            if exist('uialert_safe','file')
                                uialert_safe(fig_GUI, '请确认 fp/fst 值在 [0, Fs/2] 范围内。', '频率超出范围');
                            else
                                uialert(fig_GUI, '请确认 fp/fst 值在 [0, Fs/2] 范围内。', '频率超出范围');
                            end
                            setStatus(handles,'设计取消：频率超出范围');
                            return;
                        end
                    
                        % 读取 Rp/Rs 并转为线性误差 dp, ds（用于权重估算）
                        Rp_val = max(0, double(handles.edtRp.Value));   % dB
                        Rs_val = max(0, double(handles.edtRs.Value));   % dB
                        dp = (10^(Rp_val/20) - 1) / (10^(Rp_val/20) + 1);  % 通带允许线性幅度偏差
                        ds = 10^(-Rs_val/20);                              % 阻带线性幅度目标
                        if ds <= 0, ds = eps; end
                        if dp <= 0, dp = eps; end
                    
                        % 权重上下限保护（避免发生极端权重）
                        Wmin = 1e-3; Wmax = 1e5;
                    
                        % 初始化将传递给 cfirpm 的变量
                        f_c = []; W_c = []; fresp_handle = []; fresp_args = [];
                    
                        try
                            switch type
                                % ----------------- 低通 -----------------
                                case '低通'
                                    if ~(fp1 < fst1)
                                        uialert_safe(fig_GUI, '低通模式要求 fp1 < fst1（通带截止 < 阻带起点）。', '参数错误');
                                        setStatus(handles,'设计取消：低通参数错误'); return;
                                    end
                                    p1n = normf(fp1); s1n = normf(fst1);
                                    % -1..1 写法：外侧阻带，中间通带（镜像负频）
                                    f_c = [-1, -s1n, -p1n, p1n, s1n, 1];
                                    % 目标幅度点：用 0/1 标记（按 abs(f) 属于通带）
                                    A_c = arrayfun(@(x) double(abs(x) <= p1n), f_c);
                                    numBands = numel(f_c)/2;
                                    W_c = ones(1,numBands);
                                    ws = min(max(dp/ds, Wmin), Wmax);
                                    for bi = 1:numBands
                                        idxL = 2*bi-1; idxR = 2*bi;
                                        meanAmp = mean(A_c(idxL:idxR));
                                        W_c(bi) = (meanAmp >= 0.5) * 1 + (meanAmp < 0.5) * ws;
                                    end
                                    fresp_handle = @lowpass;
                    
                                % ----------------- 高通 -----------------
                                case '高通'
                                    if ~(fst1 < fp1)
                                        uialert_safe(fig_GUI, '高通模式要求 fst1 < fp1（阻带上限 < 通带起点）。', '参数错误');
                                        setStatus(handles,'设计取消：高通参数错误'); return;
                                    end
                                    p1n = normf(fp1); s1n = normf(fst1);
                                    f_c = [-1, -p1n, -s1n, s1n, p1n, 1];
                                    A_c = arrayfun(@(x) double(abs(x) >= p1n), f_c);
                                    numBands = numel(f_c)/2;
                                    W_c = ones(1,numBands);
                                    ws = min(max(dp/ds, Wmin), Wmax);
                                    for bi = 1:numBands
                                        idxL = 2*bi-1; idxR = 2*bi;
                                        meanAmp = mean(A_c(idxL:idxR));
                                        W_c(bi) = (meanAmp >= 0.5) * 1 + (meanAmp < 0.5) * ws;
                                    end
                                    fresp_handle = @highpass;
                    
                                % ----------------- 带通 -----------------
                                case '带通'
                                    if ~(fst1 < fp1 && fp1 < fp2 && fp2 < fst2)
                                        uialert_safe(fig_GUI, '带通模式要求 fst1 < fp1 < fp2 < fst2。', '参数错误');
                                        setStatus(handles,'设计取消：带通参数错误'); return;
                                    end
                                    p1n = normf(fp1); p2n = normf(fp2);
                                    s1n = normf(fst1); s2n = normf(fst2);
                                    % -1..1 写法（镜像）：stop / pass / stop
                                    f_c = [-1, -s2n, -p2n, -p1n, -s1n, s1n, p1n, p2n, s2n, 1];
                                    A_c = arrayfun(@(x) double( (abs(x) >= p1n) && (abs(x) <= p2n) ), f_c);
                                    numBands = numel(f_c)/2;
                                    W_c = ones(1,numBands);
                                    ws = min(max(dp/ds, Wmin), Wmax);
                                    for bi = 1:numBands
                                        idxL = 2*bi-1; idxR = 2*bi;
                                        meanAmp = mean(A_c(idxL:idxR));
                                        W_c(bi) = (meanAmp >= 0.5) * 1 + (meanAmp < 0.5) * ws;
                                    end
                                    fresp_handle = @bandpass;
                    
                                % ----------------- 带阻 -----------------
                                case '带阻'
                                    if ~(fp1 < fst1 && fst1 < fst2 && fst2 < fp2)
                                        uialert_safe(fig_GUI, '带阻模式要求 fp1 < fst1 < fst2 < fp2。', '参数错误');
                                        setStatus(handles,'设计取消：带阻参数错误'); return;
                                    end
                                    p1n = normf(fp1); p2n = normf(fp2);
                                    s1n = normf(fst1); s2n = normf(fst2);
                                    % -1..1 写法（镜像）
                                    f_c = [-1, -p2n, -s2n, -s1n, -p1n, p1n, s1n, s2n, p2n, 1];
                                    % 判定阻带（在 abs(f) 属于 [s1,s2] 时为阻带）
                                    A_c = arrayfun(@(x) double( ~((abs(x) >= s1n) && (abs(x) <= s2n)) ), f_c);
                                    numBands = numel(f_c)/2;
                                    W_c = ones(1,numBands);
                                    ws = min(max(dp/ds, Wmin), Wmax);
                                    for bi = 1:numBands
                                        idxL = 2*bi-1; idxR = 2*bi;
                                        meanAmp = mean(A_c(idxL:idxR));
                                        W_c(bi) = (meanAmp >= 0.5) * 1 + (meanAmp < 0.5) * ws;
                                    end
                                    fresp_handle = @bandstop;
                    
                                otherwise
                                    uialert_safe(fig_GUI, sprintf('cfirpm: 不支持的滤波类型 %s', type), '类型错误');
                                    setStatus(handles,'设计取消：不支持的滤波类型');
                                    return;
                            end
                    
                            % --- 检查频率向量单调性（cfirpm 要求 f 是递增向量并且长度为偶数） ---
                            if isempty(f_c) || isempty(fresp_handle) || isempty(W_c)
                                setStatus(handles,'设计取消：频率/响应/权重未正确构造');
                                return;
                            end
                            if any(diff(f_c) <= 0)
                                error('构造的频率向量 f_c 必须严格递增。请检查 fp/fst 的输入顺序与数值。');
                            end
                            if mod(numel(f_c),2) ~= 0
                                error('构造的频率向量 f_c 长度必须为偶数。');
                            end
                    
                            % --- 调用 cfirpm ---
                    
                            b = cfirpm(N, f_c, fresp_handle, W_c);
                            a = 1;
                    
                            % 去除微小虚部（数值噪声）
                            if max(abs(imag(b))) < 1e-8
                                b = real(b);
                            else
                                % 如果得到明显复系数，给用户可见提示（保持系数不修改）
                                if exist('uialert_safe','file')
                                    uialert_safe(fig_GUI, '设计得到复系数 FIR（非严格实系数）。如需实系数，请调整对称性或目标响应。', '注意',"Icon","warning");
                                else
                                    uialert(fig_GUI, '设计得到复系数 FIR（非严格实系数）。如需实系数，请调整对称性或目标响应。', '注意');
                                end
                            end
                    
                            setStatus(handles,'设计完成（Cplx-Parks-McClellan）');
                    
                        catch ME
                            fprintf('cfirpm 设计失败：%s\n', ME.message);
                            if exist('uialert_safe','file')
                                uialert_safe(fig_GUI, sprintf('cfirpm 设计失败：%s', ME.message), '设计失败');
                            else
                                uialert(fig_GUI, sprintf('cfirpm 设计失败：%s', ME.message), '设计失败');
                            end
                            setStatus(handles,'设计失败：cfirpm 运行出错');
                            return;
                        end
                        % ------------ 结束 cfirpm 设计 ------------


                    case '最小二乘(firls)'
                        % 使用 firls（最小二乘）设计
                        if isempty(N) || N <= 0
                            uialert_safe(fig_GUI, 'FIR优化设计法 - 最小二乘(firls)不支持自动估阶。请在 "FIR 阶数" 输入框中输入正整数。', '参数错误');
                            setStatus(handles,'设计失败：最小二乘(firls) 需要正整数阶数'); return;
                        end
                        try
                            switch type
                                case '低通'
                                    fvec = [0, normf(fp1), normf(fst1), 1];
                                    Avec = [1, 1, 0, 0];
                                    w = [1, max(eps, dp/ds)];   % weight: [passband stopband]
                                case '高通'
                                    fvec = [0, normf(fst1), normf(fp1), 1];
                                    Avec = [0, 0, 1, 1];
                                    w = [max(eps, dp/ds), 1];
                                case '带通'
                                    % 保证顺序 0 < fst1 < fp1 < fp2 < fst2 < Nyq
                                    fvec = [0, normf(fst1), normf(fp1), normf(fp2), normf(fst2), 1];
                                    Avec = [0, 0, 1, 1, 0, 0];
                                    % 三带： stop / pass / stop -> weights 长度 = 3
                                    w = [1, max(eps, dp/ds), 1];
                                case '带阻'
                                    % 带阻的频率点必须严格递增
                                    % 期望关系： 0 < fp1 < fst1 < fst2 < fp2 < Nyq
                                    fvec = [0, normf(fp1), normf(fst1), normf(fst2), normf(fp2), 1];
                                    Avec = [1, 1, 0, 0, 1, 1];
                                    % 三带： pass / stop / pass
                                    w = [1, max(eps, dp/ds), 1];
                                otherwise
                                    error('firls 不支持的滤波类型：%s', type);
                            end
                    
                            % 确保 fvec 非递减、长度为偶数、与 Avec 长度一致
                            if any(diff(fvec) < 0)
                                error('构造的 fvec 不是非递减序列，请检查 fp/fst 参数顺序。');
                            end
                            if numel(fvec) ~= numel(Avec) || mod(numel(fvec),2) ~= 0
                                error('firls 要求 freq 和 a 长度相同且为偶数。');
                            end
                    
                            % 调用 firls，传入权重 w（如果你不想使用权重可以去掉最后一参数）
                            b = firls(N, fvec, Avec, w);
                            a = 1;
                        catch ME
                            fprintf('调试点40:firls 设计失败：%s\n', ME.message);
                            error(['firls 设计失败：', ME.message]);
                        end
    
                    case '约束最小二乘(fircls)'
                        if isempty(N) || N <= 0
                            uialert_safe(fig_GUI, 'FIR优化设计法 - 约束最小二乘(fircls)不支持自动估阶。请在 "FIR 阶数" 输入框中输入正整数。', '参数错误');
                            setStatus(handles,'设计失败：约束最小二乘(fircls) 需要正整数阶数'); return;
                        end
                        try                    
                            switch type
                                case '低通'
                                    % 使用显式过渡带：bands = [0, fp, fst, Nyq]
                                    freq = [0, normf(fp1), normf(fst1), 1];
                                    % bands: pass / transition / stop  -> amp length = 3
                                    amp = [1, 1, 0];
                                    up  = [1+dp, 1+dp, ds];    % 对过渡带适当放宽（这里与通带上界相同）
                                    lo  = [1-dp, 1-dp, -ds];   % stop band lower 可为负，或设 0 获得非负响应
                                case '高通'
                                    freq = [0, normf(fst1), normf(fp1), 1];
                                    amp = [0, 1, 1];           % stop / transition / pass
                                    up  = [ds, 1+dp, 1+dp];
                                    lo  = [-ds, 1-dp, 1-dp];
                                case '带通'
                                    % 明确把过渡带点放入 f（0 < fst1 < fp1 < fp2 < fst2 < Nyq）
                                    % 递增顺序: 0 < fst1 < fp1 < fp2 < fst2 < Nyq
                                    freq = [0, normf(fst1), normf(fp1), normf(fp2), normf(fst2), 1];
                                    % 对应的理想幅度（5段）： stop / transition / pass / transition / stop
                                    amp = [0, 0, 1, 0, 0];
                                
                                    % 设计约束：
                                    % - 阻带段(stop): 期望 0，允许范围 [0, ds]
                                    % - 过渡段(transition): 不强约束，给一个宽松区间 [0, 1+dp]，让算法选择最优
                                    % - 通带(pass): 期望 1，严格范围 [1-dp, 1+dp]
                                    up  = [ds,      1+dp,   1+dp,   1+dp,   ds];
                                    lo  = [0,       0,      1-dp,   0,      0];
                                
                                    % 备注：这样保证对于每一段，都有 lo(i) <= Avec(i) <= up(i)。

                                case '带阻'
                                    % 递增顺序: 0 < fp1 < fst1 < fst2 < fp2 < Nyq
                                    freq = [0, normf(fp1), normf(fst1), normf(fst2), normf(fp2), 1];
                                    % bands: pass / transition / stop / transition / pass
                                    amp = [1, 1, 0, 1, 1];
                                    up  = [1+dp, 1+dp, ds, 1+dp, 1+dp];
                                    lo  = [1-dp, 1-dp, -ds, 1-dp, 1-dp];
                                otherwise
                                    error('fircls 不支持的滤波类型：%s', type);
                            end
                    
                            % 检查 freq 单调且位于 [0,1]
                            freq = max(0, min(1, freq));
                            if any(diff(freq) <= 0)
                                error('构造的 freq 向量必须严格递增，请检查 fp/fst 参数。');
                            end
                    
                            % 检查长度一致性
                            if ~(numel(amp) == numel(up) && numel(up) == numel(lo) && numel(amp) == numel(freq)-1)
                                error('fircls: amp/up/lo 长度必须等于 length(freq)-1。');
                            end
                    
                            % 调用 fircls（如需可加 'plots'/'trace' 参数）
                            b = fircls(N, freq, amp, up, lo);
                            a = 1;
                    
                        catch ME
                            fprintf('调试点42_modified：fircls 设计失败：%s\n', ME.message);
                            error(['fircls 设计失败：', ME.message]);
                        end

    
                    otherwise
                        fprintf('调试点43：未知的 FIR 优化子方法\n');
                        error('未知的 FIR 优化子方法：%s', firSub);
                end
    
                % 存储实际使用的阶数，用于备注显示
                S.actualFIROrder = N;
            
    
            elseif strcmpi(method, 'FIR频率采样法')
                n = round(double(handles.edtFIROrder.Value));
                if isempty(n) || n <= 0
                    uialert_safe(fig_GUI, 'FIR频率采样法不支持自动估阶。请在 "FIR 阶数" 输入框中输入正整数。', '参数错误');
                    setStatus(handles,'设计失败：FIR频率采样法 需要正整数阶数'); return;
                end
                % 标准低通/高通/带通/带阻 处理 -> 构造 f (Hz) 与 m，然后归一化并调用 fir2
                switch type
                    case '低通'
                        fHz = [0, fp1, fst1, nyq];
                        mVec = [1, 1, 0, 0];
                    case '高通'
                        fHz = [0, fst1, fp1, nyq];
                        mVec = [0, 0, 1, 1];
                    case '带通'
                        fHz = [0, fst1, fp1, fp2, fst2, nyq];
                        mVec = [0, 0, 1, 1, 0, 0];
                    case '带阻'
                        fHz = [0, fp1, fst1, fst2, fp2, nyq];
                        mVec = [1, 1, 0, 0, 1, 1];
                    otherwise
                        uialert_safe(fig_GUI, '不支持的滤波类型（FIR频率采样法）', '方法错误'); setStatus(handles,'设计失败：滤波类型错误'); return;
                end
                % 校验顺序及边界
                if any(diff(fHz) < 0)
                    uialert_safe(fig_GUI, '请确保所填频率满足升序关系（并位于 0..Nyq）。', '参数错误'); setStatus(handles,'设计失败：频率顺序错误'); return;
                end
                f_norm = fHz / nyq;
                % 调用 fir2 (无 npt/lap/window 简单调用)
                try
                    b = fir2(n, f_norm, mVec);
                    a = 1;
                catch ME
                    if exist('uialert_safe','file'), uialert_safe(fig_GUI, sprintf('fir2 设计失败：%s', ME.message),'设计失败'); else; uialert(fig_GUI, sprintf('fir2 设计失败：%s', ME.message),'设计失败'); end
                    setStatus(handles,'fir2 设计失败'); fprintf('fir2 标准带 失败: %s\n', ME.message); return;
                end

            else
                fprintf('调试点44：未知设计方法\n');
                error('未知设计方法：%s', method);
            end
    
        catch ME
            uialert_safe(fig_GUI,['滤波器设计失败：' ME.message],'设计错误'); setStatus(handles,['设计失败：',ME.message]); fprintf('调试点45：滤波器设计失败\n');return;
        end
    
        % ---------- 设计成功后写回 S 和启用应用按钮（保留原逻辑） ----------
        S.filter_b = b; S.filter_a = a;
        
        % 设计成功后标记并更新按钮状态
        S.filterIsDesigned = true;

        % 设计滤波器成功后，启用 下拉 + 查看 按钮
        handles.ddFilterAnalysis.Enable = 'on';
        handles.btnViewFilterAnalysis.Enable = 'on';
        % 启动保存图像按钮
        handles.btnSaveFigs.Enable = 'on';

        % 统一刷新按钮状态
        updateApplyButtonEnable(S.filterIsDesigned, S.allowApplyFilter, handles);
          
        % 更新设计方法提示标签并同步状态栏
        updateDesignLabel(S, handles);    
        
        %  更新备注栏
        updateNote(S, handles);
        updateFilterResponsePlots(S, handles);
        setStatus(handles,'滤波器设计完成，请点击"应用滤波器"按钮应用滤波器。');

    end

    %% ---- 集中控制 "应用滤波器" 按钮的函数 ---- 
    function updateApplyButtonEnable(filterIsDesigned, allowApplyFilter, handles)
    % 传入的 handle类 handles
    % 对 handles 的对象内容有 "读/写" 操作

        % 集中控制 Apply 按钮的启用状态
        % 启用条件 (示例)：S.allowApplyFilter == true 并且当前滤波器设计有效
        try
            % designOK 表示当前是否已有有效的滤波器设计（必须为 true 才能应用）
            designOK = false;
            if filterIsDesigned
                designOK = true;
            end
        
            % Apply 需满足两者：允许应用 && 设计已完成
            if allowApplyFilter && designOK
                handles.btnApply.Enable = 'on';
                % 同步滤波函数下拉（和 Apply 按钮一致）
                handles.ddFilterFunction.Enable = 'on';

                % 滤波函数选择下拉框禁用，因为FIRintfilt插值应用滤波器时使用filter（已在单独分支中应用filter）
                % 滤波函数选择下拉框禁用，因为Savitzky-Golay应用滤波器时不使用filter、filtfilt、my_filtfilt
                if any(strcmp(handles.ddDesignMethod.Value,{'FIRintfilt插值','Savitzky-Golay'}))
                    try handles.ddFilterFunction.Value = 'filter'; catch; end
                    handles.ddFilterFunction.Enable = 'off';
                else
                    handles.ddFilterFunction.Enable = 'on';
                end

            else
                handles.btnApply.Enable = 'off';
                handles.ddFilterFunction.Enable = 'off';
            end
        catch
            % 忽略 UI 错误，保持稳定
        end

        % drawnow;

    end


    %% ---- “应用滤波器”按钮回调 ----
    function onApplyFilter(~,~)
        if isempty(S.currentSignal), uialert_safe(fig_GUI,'请先录制/加载音频或生成/导入信号。','应用错误'); setStatus(handles,'应用失败：无信号数据'); return; end
        if isempty(S.filter_b) || isempty(S.filter_a), uialert_safe(fig_GUI,'请先设计滤波器。','应用错误'); setStatus(handles,'应用失败：无滤波器'); return; end
        % 读取选择的前/后向实现（若控件不存在则默认 filter）
        useNormalFilterPath = true;
        useFcn = 'filter';
        try useFcn = handles.ddFilterFunction.Value; catch; end

        % ----------------------------------- 某些设计方法应用滤波器时不走标准路径 判断开始 ----------------------------------- 
        if strcmpi(handles.ddDesignMethod.Value, 'IIR')
            useNormalFilterPath = false;
        end
        if strcmp(handles.ddDesignMethod.Value, '陷波') || strcmp(handles.ddDesignMethod.Value, '峰值滤波')
          if isprop(handles,'notchPeakFilters') && ~isempty(handles.notchPeakFilters) ...
                        && isstruct(handles.notchPeakFilters) && ~handles.notchPeakFilters.useCombinedForApply
                 useNormalFilterPath = false;
          end
        end
        if strcmpi(handles.ddDesignMethod.Value, 'FIR优化设计法') &&  strcmpi(handles.ddFIRMethod.Value, 'Cplx-Parks-McClellan') && isprop(handles,'cfirpmParams') && ~isempty(handles.cfirpmParams)  
            if strcmpi(handles.cfirpmParams.InputSel, '频率响应函数fresp')
                % 1) 从 handles.cfirpmParams 读取
                frespName = '';
                if  isprop(handles,'cfirpmParams') && isfield(handles.cfirpmParams,'fresp') && ~isempty(handles.cfirpmParams.fresp)
                    frespVal = handles.cfirpmParams.fresp;
                else
                    frespVal = '';
                end
                % 规范化（去掉可能的 '@'）
                if ischar(frespVal) && ~isempty(frespVal)
                    if startsWith(frespVal,'@')
                        frespName = strrep(frespVal,'@','');
                    else
                        frespName = frespVal;
                    end
                end
                frespName = char(frespName); % 规范字符串
                
                % 如果是三类特殊 fresp 之一，则走特殊路径
                if any(strcmpi(frespName, {'differentiator','hilbfilt','invsinc'}))
                    useNormalFilterPath = false;
                end
            end
        end

        isFirpmOddApply  = strcmpi(handles.ddDesignMethod.Value, 'FIR优化设计法') &&  strcmpi(handles.ddFIRMethod.Value, 'Parks-McClellan') && isprop(handles,'firpmParams') && ~isempty(handles.firpmParams);  
        isFirlsOddApply = strcmpi(handles.ddDesignMethod.Value, 'FIR优化设计法') &&  strcmpi(handles.ddFIRMethod.Value, '最小二乘(firls)') && isprop(handles,'firlsParams') && ~isempty(handles.firlsParams);    
        if isFirpmOddApply || isFirlsOddApply
            if isFirpmOddApply
                % 获取已保存的参数（onConfirm 存放在 handles.firpmParams）
                params = handles.firpmParams;
            elseif isFirlsOddApply
                params = handles.firlsParams;
            end
           
            oddType = '';
            if isfield(params,'oddType') && ~isempty(params.oddType)
                oddType = lower(char(params.oddType)); % 规范字符串
            end
            if any(strcmpi(oddType, {'differentiator','hilbert'}))
                useNormalFilterPath = false;
            end
        end
        if strcmpi(handles.ddDesignMethod.Value,'FIRintfilt插值') && isprop(handles,'intfiltParams') && ~isempty(handles.intfiltParams)
            useNormalFilterPath = false;
        end
        if isprop(handles,'gaussdesignParams') && strcmp(handles.ddDesignMethod.Value,'FIRgaussdesign脉冲整形')
            useNormalFilterPath = false;
        end
        if isprop(handles,'rcosdesignParams') && strcmp(handles.ddDesignMethod.Value,'FIRrcosdesign脉冲整形')
            useNormalFilterPath = false;
        end
        if isprop(handles,'sgolayParams') && strcmp(handles.ddDesignMethod.Value,'Savitzky-Golay') 
            useNormalFilterPath = false;
        end

        % ----------------------------------- 某些设计方法应用滤波器时不走标准路径 判断结束 ----------------------------------- 


        % 保护：如果当前不允许应用滤波（如继续次数已到上限），阻止继续
        if isprop(S,'allowApplyFilter') && ~S.allowApplyFilter
            uialert_safe(fig_GUI, '已达到继续滤波上限（3 次），当前不允许再应用滤波器。请切换数据或重新生成信号以解锁。', '操作受限');
            setStatus(handles,'应用被阻止：继续滤波已达到上限。');
            fprintf('调试点56：已达到继续滤波上限（3 次），当前不允许再应用滤波器。请切换数据或重新生成信号以解锁。\n');
            return;
        end


        % ------------------------------------------- 开始：选择要滤波的输入 --------------------------------------------
        % 1) 若处于 continue 基准模式 (S.continueFilterMode==true)
        %    -> 使用 S.continueFilterBase 作为输入（始终），产生的 y 写入 S.continueTempLatest（不入历史）。
        %    -> 绘图：不叠加临时结果到历史上；仅显示最新临时结果（覆盖前一个临时）。
        %
        % 2) 若未处于 continue 基准模式：
        %    -> 使用原始/加噪信号作为输入；本次结果写入 history（覆盖历史，仅显示本次）。
        %
        if S.continueFilterMode
            % 基准模式：始终以 base 作为输入
            if isempty(S.continueFilterBase)
                % 回退兼容：若 base 为空但 history 非空，设 base 为最后一条
                if ~isempty(S.filteredHistory)
                    S.continueFilterBase = S.filteredHistory{end};
                    S.continueBaseIndex = numel(S.filteredHistory);
                else
                    uialert_safe(fig_GUI,'没有可用于继续滤波的基准数据。','操作错误');
                    setStatus(handles,'应用失败：继续滤波基准不存在。');
                    fprintf('调试点57：应用失败：继续滤波基准不存在。\n');
                    return;
                end
            end
            x_use = S.continueFilterBase;
        else
            % 原始路径：使用 currentSignal 或 noisy（若噪声确认）
            x_use = S.currentSignal;
            if handles.cbAddNoise.Value && ~isempty(S.noisy)
                x_use = S.noisy;
            end
        end
        

        % ---------------------------------------------------- 常规滤波路径 ----------------------------------------------------
        if useNormalFilterPath
            % 常规滤波路径（支持向量/矩阵/任意维，优先使用 S.timeDim）
            try
                % 将原来 try 内的滤波逻辑封装为函数（只返回 y 和 aborted 标志）
                [y, aborted] = applyNormalFilter(S, x_use, useFcn, fig_GUI);
                if aborted
                    % 封装内部决定要直接退出（原代码内部用了 return）
                    return;
                end
            catch ME
                % 出错回退到单次 filter（沿默认方向应用，使用与上面相同的 dim 语义）
                try
                    % 确定 time dim（优先 S.timeDim）
                    useTimeDim = false;
                    if  ~isempty(S.timeDim) && S.timeDim==round(S.timeDim) && S.timeDim>=1
                        tdim = S.timeDim;
                        useTimeDim = true;
                    end
                    if useTimeDim
                        y = filter(S.filter_b, S.filter_a, x_use, [], tdim);
                    else
                        y = filter(S.filter_b, S.filter_a, x_use);
                    end
                    setStatus(handles,sprintf('常规滤波路径 %s 失败，已回退使用 filter（存在相位畸变）。', useFcn));
                    fprintf('调试点61：注意：常规滤波路径 %s 失败，已回退使用 filter（存在相位畸变）。\n', useFcn);
                    uialert_safe(fig_GUI,sprintf('常规滤波路径 %s 失败，已回退使用 filter（存在相位畸变）。', useFcn),'应用错误');
                catch ME2
                    % 如果连回退都失败，则清理并通知
                    setStatus(handles,sprintf('滤波失败：%s', ME2.message));
                    uialert_safe(fig_GUI,sprintf('滤波失败：%s', ME2.message),'应用错误');
                end
            end
        end


        % ----------------------------------------------如果是 IIR ，先检查阶数是否过高，高阶提示与 SOS 选择 ---------------------------------------------------
        IIR_ORDER_THRESHOLD = 8; % 阈值
        useSOS = false; 
        % 仅当当前设计方法为 IIR 时做检查
        isIIR = strcmpi(handles.ddDesignMethod.Value, 'IIR'); 
        if isIIR
            % 计算实际系统阶数（以系数向量长度为准）
            if ~isempty(S.filter_b) && ~isempty(S.filter_a)
                ord_b = length(S.filter_b) - 1;
                ord_a = length(S.filter_a) - 1;
                iirOrder = max(ord_b, ord_a);
            else
                iirOrder = 0;
            end 
            % 直接使用界面中的滤波器类型下拉框值
            filterTopology = handles.ddType.Value; 
            % 判断类型
            isBand = any(strcmp(filterTopology, {'带通', '带阻'}));
            isLowHigh = any(strcmp(filterTopology, {'低通', '高通'})); 
            % 若系统阶数超阈值且滤波器系数有效，弹出改进提示
            if iirOrder > IIR_ORDER_THRESHOLD && iirOrder > 0
                if isBand
                    protoOrder = ceil(iirOrder/2); % 带通/带阻系统阶数通常为原型阶数的两倍
                    msg = sprintf(['检测到 IIR %s滤波器系统阶数为 %d（对应原型阶数约 %d）。\n\n', ...
                                   '注：带通/带阻滤波器在从原型转换时常使阶数翻倍（MATLAB 这样处理）。\n\n', ...
                                   '较高的系统阶数可能导致数值不稳定，推荐使用 SOS 结构或改用 FIR 优化法。\n\n', ...
                                   '请选择：\n - 继续：仍使用当前滤波函数（可能失败/不稳定）\n - 使用SOS：将 IIR 转为二阶节（SOS）并使用 sosfilt（默认）或 filtfilt \n - 取消：放弃本次应用滤波器'], ...
                                   filterTopology, iirOrder, protoOrder);
                elseif isLowHigh
                    % 对于低通/高通，系统阶数与原型阶数一般相同
                    msg = sprintf(['检测到 IIR %s滤波器系统阶数为 %d（系统阶数与原型阶数相同）。\n\n', ...
                                   '较高的阶数可能导致数值不稳定，推荐使用 SOS 结构或改用 FIR 优化法。\n\n', ...
                                   '请选择：\n - 继续：仍使用当前滤波函数（可能失败/不稳定）\n - 使用SOS：将 IIR 转为二阶节（SOS）并使用 sosfilt（默认）或 filtfilt \n - 取消：放弃本次应用滤波器'], ...
                                   filterTopology, iirOrder);
                else
                    % 未知类型：仍显示系统阶数并给出原型阶数提示（保守显示一半）
                    protoOrder = ceil(iirOrder/2);
                    msg = sprintf(['检测到 IIR %s滤波器系统阶数为 %d（可能对应原型阶数约 %d）。\n\n', ...
                                   '较高的阶数可能导致数值不稳定，推荐使用 SOS 结构或改用 FIR 优化法。\n\n', ...
                                   '请选择：\n - 继续：仍使用当前滤波函数（可能失败/不稳定）\n - 使用SOS：将 IIR 转为二阶节（SOS）并使用 sosfilt（默认）或 filtfilt \n - 取消：放弃本次应用滤波器'], ...
                                   filterTopology, iirOrder, protoOrder);
                end
        
                % 弹窗：优先使用 uiconfirm（uifigure），若不可用回退 questdlg
                try
                    choice = uiconfirm(fig_GUI, msg, '高阶 IIR 提示', ...
                                       'Options', {'继续','使用SOS','取消'}, ...
                                       'DefaultOption', 2, 'CancelOption', 3);
                catch
                    choice = questdlg(msg, '高阶 IIR 提示', '继续','使用SOS','取消','使用SOS');
                end
        
                if isempty(choice) || strcmp(choice,'取消')
                    setStatus(handles,'已取消：用户在高阶 IIR 提示中选择取消。');
                    return;
                elseif strcmpi(choice,'使用SOS')
                    useSOS = true;
                else
                    useSOS = false;
                end
            end
            % ---- 如果是 IIR ，根据 useSOS 决定实际 IIR 应用：SOS 优先 / 否则 filtfilt -> filter 回退 ----
            if useSOS
                try
                    % 确定 time dim（优先 S.timeDim）
                    useTimeDim = false;
                    if  ~isempty(S.timeDim) && S.timeDim==round(S.timeDim) && S.timeDim>=1
                        tdim = S.timeDim;
                        useTimeDim = true;
                    end 
                    % 将传递函数转换为二阶节 (SOS) 结构
                    [sos, g] = tf2sos(S.filter_b, S.filter_a);
                    if strcmpi(useFcn, 'filtfilt')
                        % 如果指定了 time-dim，则先把任意维重排为 [N x channels]
                        if useTimeDim
                            [X2, restoreFcn] = to2DtimeMajor(x_use, tdim); %#ok<NASGU>
                            % 直接调用 filtfilt（不做 NaN/Inf 预处理；让 MATLAB 抛出任何异常）
                            y2 = filtfilt(sos, g, X2);
                            % 还原维度/类型
                            y = restoreFcn(y2);
                        else
                            y = filtfilt(sos, g, x_use);
                        end
                    else
                        uialert_safe(fig_GUI,sprintf('SOS结构不支持滤波函数 %s 。SOS结构默认使用 sosfilt，支持使用 filtfilt 。已自动使用sosfilt', useFcn),'应用警告',"Icon","warning");
                        if useTimeDim
                            y = sosfilt(sos, x_use, tdim);
                        else
                            y = sosfilt(sos, x_use);
                        end
                    end
                    
                    % 更新状态：显示 SOS 滤波信息
                    setStatus(handles,sprintf('已使用 SOS 结构（系统阶数 %d）应用 %s 滤波。', iirOrder, filterTopology));
                catch ME
                    fprintf('调试点58：尝试使用 SOS 结构失败\n');
                    uialert_safe(fig_GUI,sprintf('尝试使用 SOS 结构失败。正在尝试使用原始传递函数的 %s ', useFcn),'使用 SOS 结构失败');
                    % SOS 转换或应用失败：回退到传统传递函数方式的 filtfilt/filter
                    error_msg = sprintf('尝试使用 SOS 结构失败：%s', ME.message);
                    
                    % 输出警告信息
                    if isfield(ME, 'identifier') && ~isempty(ME.identifier)
                        warning(ME.identifier, '%s', error_msg);
                    else
                        warning('%s', error_msg);
                    end
                    
                    % 尝试使用原始传递函数的 filtfilt
                    try
                        % 将原来 try 内的滤波逻辑封装为函数（只返回 y 和 aborted 标志）
                        [y, aborted] = applyNormalFilter(S, x_use, useFcn, fig_GUI);
                        if aborted
                            % 封装内部决定要直接退出（原代码内部用了 return）
                            return;
                        end
                        setStatus(handles,sprintf('SOS路径失败，已使用 %s ', useFcn));
                        fprintf('调试点59：注意：SOS路径失败，已使用 %s \n', useFcn);
                    catch ME2
                        % 出错回退到单次 filter（沿默认方向应用，使用与上面相同的 dim 语义）
                        try
                            % 确定 time dim（优先 S.timeDim）
                            useTimeDim = false;
                            if  ~isempty(S.timeDim) && S.timeDim==round(S.timeDim) && S.timeDim>=1
                                tdim = S.timeDim;
                                useTimeDim = true;
                            end
                            if useTimeDim
                                y = filter(S.filter_b, S.filter_a, x_use, [], tdim);
                            else
                                y = filter(S.filter_b, S.filter_a, x_use);
                            end
                            setStatus(handles,sprintf('尝试使用原始传递函数的 %s 失败，已回退使用 filter（存在相位畸变）。', useFcn));
                            fprintf('调试点60：注意：尝试使用原始传递函数的 %s 失败，已回退使用 filter（存在相位畸变）。\n', useFcn);
                            uialert_safe(fig_GUI,sprintf('尝试使用原始传递函数的 %s 失败，已回退使用 filter（存在相位畸变）。', useFcn),'应用错误');
                        catch ME3
                            % 如果连回退都失败，则清理并通知
                            setStatus(handles,sprintf('滤波失败：%s', ME3.message));
                            uialert_safe(fig_GUI,sprintf('滤波失败：%s', ME3.message),'应用错误');
                        end 
                    end
                end
            else 
                % 不使用 SOS结构，则走常规滤波路径
                try
                    % 将原来 try 内的滤波逻辑封装为函数（只返回 y 和 aborted 标志）
                    [y, aborted] = applyNormalFilter(S, x_use, useFcn, fig_GUI);
                    if aborted
                        % 封装内部决定要直接退出（原代码内部用了 return）
                        return;
                    end
                catch ME
                    % 出错回退到单次 filter（沿默认方向应用，使用与上面相同的 dim 语义）
                    try
                        % 确定 time dim（优先 S.timeDim）
                        useTimeDim = false;
                        if  ~isempty(S.timeDim) && S.timeDim==round(S.timeDim) && S.timeDim>=1
                            tdim = S.timeDim;
                            useTimeDim = true;
                        end
                        if useTimeDim
                            y = filter(S.filter_b, S.filter_a, x_use, [], tdim);
                        else
                            y = filter(S.filter_b, S.filter_a, x_use);
                        end
                        setStatus(handles,sprintf('常规滤波路径 %s 失败，已回退使用 filter（存在相位畸变）。', useFcn));
                        fprintf('调试点61：注意：常规滤波路径 %s 失败，已回退使用 filter（存在相位畸变）。\n', useFcn);
                        uialert_safe(fig_GUI,sprintf('常规滤波路径 %s 失败，已回退使用 filter（存在相位畸变）。', useFcn),'应用错误');
                    catch ME2
                        % 如果连回退都失败，则清理并通知
                        setStatus(handles,sprintf('滤波失败：%s', ME2.message));
                        uialert_safe(fig_GUI,sprintf('滤波失败：%s', ME2.message),'应用错误');
                    end
                end

            end % 是否使用SOS结构判断结束
        end % 设计方法为IIR判断结束



        % ---------------------------------- 如果是 陷波/峰值 并保存了子节系数，逐节应用 ---------------------------------------------------
        DesignMethod_1 = handles.ddDesignMethod.Value;
        if strcmp(DesignMethod_1, '陷波') || strcmp(DesignMethod_1, '峰值滤波')
            try
                if isprop(handles,'notchPeakFilters') && ~isempty(handles.notchPeakFilters) ...
                        && isstruct(handles.notchPeakFilters) && ~handles.notchPeakFilters.useCombinedForApply
                    nf = handles.notchPeakFilters;
                    % Sanity
                    if isfield(nf,'bk') && isfield(nf,'ak') && isfield(nf,'mode')
                        bk_cell = nf.bk; ak_cell = nf.ak; K = nf.K;
                        modeNP = nf.mode; % 'notch' 或 'peak'
            
                        % 保留原始 x_use 形状（不要强制列向量）
                        x_in = x_use;
            
                        % 逐节应用（优先 filtfilt / my_filtfilt；失败回退至 filter）
                        try
                            if strcmpi(modeNP,'notch')
                                % 级联：依次用每个节滤波
                                ytmp = x_in;
                                for kk = 1:K
                                    bkk = bk_cell{kk}; akk = ak_cell{kk};
                
                                    % 构造局部 S_local 以传递系数给 applyNormalFilter
                                    S_local = S;
                                    S_local.filter_b = bkk;
                                    S_local.filter_a = akk;
                
                                    % 调用封装的常规滤波器路径（统一处理多维/tdim/fftfilt）
                                    [ytmp_next, aborted] = applyNormalFilter(S_local, ytmp, useFcn, fig_GUI);
                                    if aborted
                                        % applyNormalFilter 决定要直接退出（与原 return 语义一致）
                                        return;
                                    end
                                    ytmp = ytmp_next;
                                end
                                y = ytmp;
                            else
                                % peak（并联）： y = sum_k Hk(x) - (K-1)*x
                                % 保持 x_in 的形状用于最后的减法
                                Ysum = zeros(size(x_in),'like',x_in);
                                for kk = 1:K
                                    bkk = bk_cell{kk}; akk = ak_cell{kk};
                
                                    % 构造局部 S_local 以传递系数给 applyNormalFilter
                                    S_local = S;
                                    S_local.filter_b = bkk;
                                    S_local.filter_a = akk;
                
                                    [yk, aborted] = applyNormalFilter(S_local, x_in, useFcn, fig_GUI);
                                    if aborted
                                        return;
                                    end
                
                                    % 累加。注意：若类型上导致提升（int -> double）为 MATLAB 行为，不在这里强行转换。
                                    Ysum = Ysum + yk;
                                end
                                % 并联输出根据定义需要减去 (K-1)*原信号
                                y = Ysum - (K-1) * x_in;
                                % 尝试把并联计算的结果恢复为输入的原始数据类型（避免类型提升）
                                try
                                    y = cast(y, class(x_in));
                                catch
                                    % 若 cast 失败则保留已计算的结果类型（不抛错，保持原行为）
                                end
                            end

                            setStatus(handles,sprintf('已按子节方式应用 %s（%d 节）。', modeNP, K));
                        catch ME1
                            % 若逐节 filtfilt 出错（数值 / 边界），记录并回退
                            warning('onApplyFilter:Applynotch_peakFailed','逐节应用 notch/peak 失败，回退到合并传递函数：%s', ME1.message);
                            uialert_safe(fig_GUI, ['逐节应用 notch/peak 失败，回退到合并传递函数走常规滤波路径：' ME1.message], '逐节应用错误');
                            setStatus(handles,'逐节应用 notch/peak 失败，回退到合并传递函数，走常规滤波路径');
                            
                            % 退到合并传递函数
                            % 常规滤波路径
                            try
                                % 将原来 try 内的滤波逻辑封装为函数（只返回 y 和 aborted 标志）
                                [y, aborted] = applyNormalFilter(S, x_use, useFcn, fig_GUI);
                                if aborted
                                    % 封装内部决定要直接退出（原代码内部用了 return）
                                    return;
                                end
                            catch ME
                                % 出错回退到单次 filter（沿默认方向应用，使用与上面相同的 dim 语义）
                                try
                                    % 确定 time dim（优先 S.timeDim）
                                    useTimeDim = false;
                                    if  ~isempty(S.timeDim) && S.timeDim==round(S.timeDim) && S.timeDim>=1
                                        tdim = S.timeDim;
                                        useTimeDim = true;
                                    end
                                    if useTimeDim
                                        y = filter(S.filter_b, S.filter_a, x_use, [], tdim);
                                    else
                                        y = filter(S.filter_b, S.filter_a, x_use);
                                    end
                                    setStatus(handles,sprintf('常规滤波路径 %s 失败，已回退使用 filter（存在相位畸变）。', useFcn));
                                    fprintf('调试点61：注意：常规滤波路径 %s 失败，已回退使用 filter（存在相位畸变）。\n', useFcn);
                                    uialert_safe(fig_GUI,sprintf('常规滤波路径 %s 失败，已回退使用 filter（存在相位畸变）。', useFcn),'应用错误');
                                catch ME2
                                    % 如果连回退都失败，则清理并通知
                                    setStatus(handles,sprintf('滤波失败：%s', ME2.message));
                                    uialert_safe(fig_GUI,sprintf('滤波失败：%s', ME2.message),'应用错误');
                                end
                            end
                        end
                    end
                end
            catch ME_outer
                warning('onApplyFilter:ChecknotchPeakFiltersFailed','检查 notchPeakFilters 时出错：%s', ME_outer.message);
                uialert_safe(fig_GUI, ['检查 notchPeakFilters 时出错：' ME_outer.message], '应用错误');
                setStatus(handles,'应用失败：检查 notchPeakFilters 时出错');
                return;
            end
        end
        
        % ------------------------------------- 如果是 FIR优化设计法-cfirpm-频率响应函数fresp 三类特殊频率响应函数'differentiator','hilbfilt','invsinc' ；则进行相应的细化的滤波器应用操作  ------------------------------------- 
        if strcmpi(handles.ddDesignMethod.Value, 'FIR优化设计法') &&  strcmpi(handles.ddFIRMethod.Value, 'Cplx-Parks-McClellan') && isprop(handles,'cfirpmParams') && ~isempty(handles.cfirpmParams)  
            if strcmpi(handles.cfirpmParams.InputSel, '频率响应函数fresp')
                % 1) 从 handles.cfirpmParams 读取
                cfirpmParams = handles.cfirpmParams;
               
                frespName = '';
                if isfield(cfirpmParams,'fresp') && ~isempty(cfirpmParams.fresp)
                    frespVal = cfirpmParams.fresp;
                else
                    frespVal = '';
                end
                % 规范化（去掉可能的 '@'）
                if ischar(frespVal) && ~isempty(frespVal)
                    if startsWith(frespVal,'@')
                        frespName = strrep(frespVal,'@','');
                    else
                        frespName = frespVal;
                    end
                end
                frespName = lower(char(frespName)); % 规范字符串
                
                % 如果是三类特殊 fresp 之一，则走特殊路径
                if any(strcmpi(frespName, {'differentiator','hilbfilt','invsinc'}))
                    try
                        switch frespName
                            case 'differentiator'
                                % ---- differentiator: 单向应用（保持相位），不要 filtfilt ----
                                if ~strcmpi(useFcn,'filter')
                                    % warn user and override / or ask
                                    try
                                        choice = uiconfirm(fig_GUI, ...
                                            '设计为 differentiator 的滤波器不应使用 filtfilt（前后向会破坏微分器的相位/符号）。要改为单向 filter 吗？', ...
                                            'Differentiator 使用提示', 'Options', {'使用 filter','取消'}, 'DefaultOption', 1);
                                    catch
                                        % 若 UI 不可用则默认改用 filter
                                        choice = '使用 filter';
                                    end
                                    if strcmp(choice,'取消')
                                        return; % 用户取消应用
                                    else
                                        useFcn = 'filter'; % 强制使用单向 filter
                                        handles.ddFilterFunction.Value = 'filter'; % 修改使用的滤波函数
                                    end
                             
                                end 
 
                                % 确定 time dim（优先 S.timeDim）
                                useTimeDim = false;
                                if  ~isempty(S.timeDim) && S.timeDim==round(S.timeDim) && S.timeDim>=1
                                    tdim = S.timeDim;
                                    useTimeDim = true;
                                end
                                if useTimeDim
                                    y = filter(S.filter_b, S.filter_a, x_use, [], tdim);
                                else
                                    y = filter(S.filter_b, S.filter_a, x_use);
                                end
                                 
                            case 'hilbfilt'
                                % ---- hilbfilt: 单向应用以保留 +/-90deg 相移；可选合成解析信号 ----
                                if ~strcmpi(useFcn,'filter')
                                    try
                                        choice = uiconfirm(fig_GUI, ...
                                            'Hilbert 变换器(@hilbfilt) 需要单向滤波以保留 ±90° 相位差。是否改为使用单向 filter？', ...
                                            'Hilbert 使用提示', 'Options', {'使用 filter','取消'}, 'DefaultOption', 1);
                                    catch
                                        choice = '使用 filter';
                                    end
                                    if strcmp(choice,'取消')
                                        return;
                                    else
                                        useFcn = 'filter'; % 强制使用单向 filter
                                        handles.ddFilterFunction.Value = 'filter'; % 修改使用的滤波函数
                                    end
                                end 
                                % 确定 time dim（优先 S.timeDim）
                                useTimeDim = false;
                                if  ~isempty(S.timeDim) && S.timeDim==round(S.timeDim) && S.timeDim>=1
                                    tdim = S.timeDim;
                                    useTimeDim = true;
                                end
                                if useTimeDim
                                    y_h = filter(S.filter_b, S.filter_a, x_use, [], tdim);
                                else
                                    y_h = filter(S.filter_b, S.filter_a, x_use);
                                end
                                % 如果 GUI 有"返回解析信号"选项，则合成复数解析信号
                                wantAnalytic = false;
                                if isfield(cfirpmParams,'hilbfilt_return') && strcmpi(cfirpmParams.hilbfilt_return,'analytic')
                                    wantAnalytic = true;
                                end
                                
                                if wantAnalytic
                                    % 更明确地构造复数信号（与 double(...) 等价，但更语义化）
                                    y = complex(double(x_use), double(y_h));
                                    setStatus(handles,'已应用 @hilbfilt 并返回解析信号 x + j*H{x}');
                                else
                                    y = y_h;
                                    setStatus(handles,'已应用 @hilbfilt（单向 filter）');
                                end
                
                            case 'invsinc'
                                % invsinc：线性幅度补偿。filtfilt 会导致幅度变为 |H|^2 —— 要求用户确认
                                if strcmpi(useFcn,'filtfilt') || strcmpi(useFcn,'my_filtfilt')
                                    try
                                        choice = uiconfirm(fig_GUI, ...
                                            ['你选择了 filtfilt（零相位）来应用 invsinc 滤波器。注意：forward-then-backward 相当于系统幅度取平方（|H|^2），', ...
                                             '这通常会改变你期望的幅度补偿。是否仍然继续使用 filtfilt？'], ...
                                            'invsinc 使用提示', 'Options', {'继续使用 filtfilt','改用单向 filter','取消'}, 'DefaultOption', 2);
                                    catch
                                        choice = '改用单向 filter';
                                    end
                                    if strcmp(choice,'取消')
                                        return;
                                    elseif strcmp(choice,'改用单向 filter')
                                        useFcn = 'filter';
                                        handles.ddFilterFunction.Value = 'filter'; % 修改使用的滤波函数
                                    else
                                        % 保持使用 filtfilt，继续
                                    end
                                end
                                % ---- invsinc: 优先使用零相位（filtfilt），但先检查增益风险 ----
                                % 先评估最大增益
                                try
                                    H = freqz(S.filter_b, S.filter_a, 2048, S.fs);
                                    maxGainDB = 20*log10(max(abs(H))+eps);
                                catch
                                    maxGainDB = NaN;
                                end
                                if ~isnan(maxGainDB) && maxGainDB > 60
                                    % 高增益风险：提示用户是否继续
                                    choice = uiconfirm(fig_GUI, sprintf('invsinc 设计最大增益约为 %.1f dB，可能严重放大高频噪声，是否继续应用？', maxGainDB), '高增益提示', 'Options', {'继续','取消'}, 'DefaultOption', 2, 'CancelOption', 2);
                                    if strcmp(choice,'取消')
                                        setStatus(handles,'已取消：invsinc 高增益风险用户拒绝应用。');
                                        return;
                                    end
                                end
                                % 根据用户选择的 useFcn（my_filtfilt / filtfilt / filter）来执行
                                % 常规滤波路径（支持向量/矩阵/任意维，优先使用 S.timeDim）
                                try
                                    % 将原来 try 内的滤波逻辑封装为函数（只返回 y 和 aborted 标志）
                                    [y, aborted] = applyNormalFilter(S, x_use, useFcn, fig_GUI);
                                    if aborted
                                        % 封装内部决定要直接退出（原代码内部用了 return）
                                        return;
                                    end
                                catch ME
                                    % 出错回退到单次 filter（沿默认方向应用，使用与上面相同的 dim 语义）
                                    try
                                        % 确定 time dim（优先 S.timeDim）
                                        useTimeDim = false;
                                        if  ~isempty(S.timeDim) && S.timeDim==round(S.timeDim) && S.timeDim>=1
                                            tdim = S.timeDim;
                                            useTimeDim = true;
                                        end
                                        if useTimeDim
                                            y = filter(S.filter_b, S.filter_a, x_use, [], tdim);
                                        else
                                            y = filter(S.filter_b, S.filter_a, x_use);
                                        end
                                        setStatus(handles,sprintf('invsinc %s 失败，已回退使用 filter（存在相位畸变）。', useFcn));
                                        fprintf('调试点61_invsinc：注意：invsinc %s 失败，已回退使用 filter（存在相位畸变）。\n', useFcn);
                                        uialert_safe(fig_GUI,sprintf('invsinc %s 失败，已回退使用 filter（存在相位畸变）。', useFcn),'应用错误');
                                    catch ME2
                                        % 如果连回退都失败，则清理并通知
                                        setStatus(handles,sprintf('滤波失败：%s', ME2.message));
                                        uialert_safe(fig_GUI,sprintf('滤波失败：%s', ME2.message),'应用错误');
                                    end
                                end
                        end
                    catch ME
                        % 若特殊分支出错：记录并继续到标准路径（保留原回退能力）
                        uialert_safe(fig_GUI, ['应用 cfirpm 出错：' ME.message], '应用错误');
                        setStatus(handles,'应用失败：cfirpm 出错');
                        return;
                    end
        
                end
            end
        end

                        
        % ------------------------------------- 如果是 FIR优化设计法-firpm 或 firls-选择设计奇对称滤波器'differentiator','hilbert' ；则进行相应的细化的滤波器应用操作  ------------------------------------- 
        isFirpmOddApply  = strcmpi(handles.ddDesignMethod.Value, 'FIR优化设计法') &&  strcmpi(handles.ddFIRMethod.Value, 'Parks-McClellan') && isprop(handles,'firpmParams') && ~isempty(handles.firpmParams);  
        isFirlsOddApply = strcmpi(handles.ddDesignMethod.Value, 'FIR优化设计法') &&  strcmpi(handles.ddFIRMethod.Value, '最小二乘(firls)') && isprop(handles,'firlsParams') && ~isempty(handles.firlsParams);    
        if isFirpmOddApply || isFirlsOddApply
            if isFirpmOddApply
                % 获取已保存的参数（onConfirm 存放在 handles.firpmParams）
                params = handles.firpmParams;
            elseif isFirlsOddApply
                params = handles.firlsParams;
            end

            oddType = '';
            if isfield(params,'oddType') && ~isempty(params.oddType)
                oddType = lower(char(params.oddType)); % 规范字符串
            end
            if any(strcmpi(oddType, {'differentiator','hilbert'}))
                switch oddType
                    case 'differentiator'
                        % ---- differentiator: 单向应用（保持相位），不要 filtfilt ----
                        if ~strcmpi(useFcn,'filter')
                            % warn user and override / or ask
                            try
                                choice = uiconfirm(fig_GUI, ...
                                    '设计为 differentiator 的滤波器不应使用 filtfilt（前后向会破坏微分器的相位/符号）。要改为单向 filter 吗？', ...
                                    'Differentiator 使用提示', 'Options', {'使用 filter','取消'}, 'DefaultOption', 1);
                            catch
                                % 若 UI 不可用则默认改用 filter
                                choice = '使用 filter';
                            end
                            if strcmp(choice,'取消')
                                return; % 用户取消应用
                            else
                                useFcn = 'filter'; % 强制使用单向 filter
                                handles.ddFilterFunction.Value = 'filter'; % 修改使用的滤波函数
                            end
                        
                        end 
                        % 确定 time dim（优先 S.timeDim）
                        useTimeDim = false;
                        if  ~isempty(S.timeDim) && S.timeDim==round(S.timeDim) && S.timeDim>=1
                            tdim = S.timeDim;
                            useTimeDim = true;
                        end
                        if useTimeDim
                            y = filter(S.filter_b, S.filter_a, x_use, [], tdim);
                        else
                            y = filter(S.filter_b, S.filter_a, x_use);
                        end
                    
                    case 'hilbert'
                        % ---- hilbert: 单向应用以保留 +/-90deg 相移；可选合成解析信号 ----
                        if ~strcmpi(useFcn,'filter')
                            try
                                choice = uiconfirm(fig_GUI, ...
                                    'Hilbert 变换器 需要单向滤波以保留 ±90° 相位差。是否改为使用单向 filter？', ...
                                    'Hilbert 使用提示', 'Options', {'使用 filter','取消'}, 'DefaultOption', 1);
                            catch
                                choice = '使用 filter';
                            end
                            if strcmp(choice,'取消')
                                return;
                            else
                                useFcn = 'filter'; % 强制使用单向 filter
                                handles.ddFilterFunction.Value = 'filter'; % 修改使用的滤波函数
                            end
                        end
                         
                        % 确定 time dim（优先 S.timeDim）
                        useTimeDim = false;
                        if  ~isempty(S.timeDim) && S.timeDim==round(S.timeDim) && S.timeDim>=1
                            tdim = S.timeDim;
                            useTimeDim = true;
                        end
                        if useTimeDim
                            y_h = filter(S.filter_b, S.filter_a, x_use, [], tdim);
                        else
                            y_h = filter(S.filter_b, S.filter_a, x_use);
                        end

                        % 如果 GUI 有"返回解析信号"选项，则合成复数解析信号
                        wantAnalytic = false;
                        if isfield(params,'hilbert_return') && strcmpi(params.hilbert_return,'analytic')
                            wantAnalytic = true;
                        end
                        
                        if wantAnalytic
                            % 更明确地构造复数信号（与 double(...) 等价，但更语义化）
                            y = complex(double(x_use), double(y_h));
                            setStatus(handles,'已应用 hilbert 并返回解析信号 x + j*H{x}');
                        else
                            y = y_h;
                            setStatus(handles,'已应用 hilbert（单向 filter）');
                        end
                end
            end
        end


        % ------------------------------------- 如果是 FIRintfilt插值 则根据用户"应用滤波器时是否补偿相位延迟"的选择来进行相应的操作  ------------------------------------- 
        if strcmpi(handles.ddDesignMethod.Value,'FIRintfilt插值')
            if isempty(S.filter_b)
                uialert_safe(fig_GUI,'请先设计滤波器（设计后再应用）。','未设计滤波器');
                return;
            end

            b = S.filter_b; 
            a = S.filter_a;
  

            % 确保存在 intfilt 参数
            if ~isprop(handles,'intfiltParams') || isempty(handles.intfiltParams)
                uialert_safe(fig_GUI,'缺少 intfilt 参数（handles.intfiltParams）。','参数缺失');
                return;
            end
            p_intfilt = handles.intfiltParams;

            % ------------------ 准备：把 time-dim 移到第一维（兼容向量/矩阵/ND） ------------------
            % 与 applyNormalFilter 保持一致：优先使用 S.timeDim
            useTimeDim = false;
            % 优先使用 S.timeDim（如果存在且有效），否则回退至第一个非单例维度
            if  ~isempty(S.timeDim) && S.timeDim==round(S.timeDim) && S.timeDim>=1
                tdim = S.timeDim;
                useTimeDim = true;
            else
                tdim = find(size(x_use)~=1,1,'first');
                if ~isempty(tdim) && tdim>=1
                    useTimeDim = true;
                end
            end
            
            if useTimeDim
                try
                    % 始终把时间维移动到第1维，返回 [N x channels] 和 restoreFn
                    [X2, restoreFn] = to2DtimeMajor(x_use, tdim);  % X2 is double? 保留原类型，下面转换
                catch ME
                    uialert_safe(fig_GUI, ['准备输入（to2DtimeMajor）失败：' ME.message], '运行错误');
                    return;
                end
            else
                % 未指定 timeDim：只在 x_use 为向量或 2D 矩阵时按列处理（保持与标准路径一致）
                if ndims(x_use) > 2
                    uialert_safe(fig_GUI, 'FIRintfilt 插值：输入为多维数组但未指定 S.timeDim。请设置 S.timeDim 或使用常规滤波路径。', '参数缺失');
                    return;
                else
                    % --- 针对向量/矩阵的鲁棒处理（为行向量做特殊处理） ---
                    origSize = size(x_use);
                    if isvector(x_use)
                        % 若为向量，强制为列向量
                        wasRow = isrow(x_use);
                        X2 = x_use(:);  % [N x 1]
                
                        % 生成恢复函数：保证最终输出维度与原始 x_use 一致（如果原为行向量则恢复为行）
                        if wasRow
                            % Y2 是 [N*l x 1]，恢复为 1 x (N*l)
                            restoreFn = @(Y2) reshape(Y2.', origSize);
                        else
                            % 原为列向量，恢复为 (N*l) x 1
                            restoreFn = @(Y2) reshape(Y2, origSize);
                        end
                    else
                        % 已是 2D 矩阵（N x channels），保持原样处理并简单恢复
                        X2 = x_use;
                        restoreFn = @(Y2) reshape(Y2, size(x_use));
                    end
                end
            end
            
            % 兼容性：确保 X2 为 double（upsample/filter 在 double 下更稳健）
            origClass_X = class(X2);
            if ~isa(X2,'double')
                X2_proc = double(X2);
            else
                X2_proc = X2;
            end

            % --- 上采样（沿每一列，上采样函数要求时间在行方向）
            try
                lval = p_intfilt.intfilt_l;
                if ~(isnumeric(lval) && isscalar(lval) && lval==round(lval) && lval>=1)
                    error('intfilt_l 必须为正整数');
                end
                % X2_proc: [N x channels]
                xr2 = upsample(X2_proc, lval);   % upsample 作用于列（时间在行）
            catch ME
                uialert_safe(fig_GUI, ['上采样失败：', ME.message], '运行错误');
                return;
            end

            % --- 滤波（按列自动处理），但先校验 b 的列数是否与通道匹配
            try
                % b_for 可能为向量或 [M x channels] 或 [M x 1]
                b_for = S.filter_b;
                a_for = S.filter_a;
                channels = size(xr2, 2);
                if ~ (isvector(b_for) || size(b_for,2) == channels || size(b_for,2) == 1)
                    uialert_safe(fig_GUI, sprintf('滤波器系数维度与通道数不匹配：数据通道=%d，滤波器列=%d', channels, size(b_for,2)), '应用错误');
                    return;
                end
            
                y2 = filter(b_for, a_for, xr2);   % y2: [N*l x channels]
            catch ME
                uialert_safe(fig_GUI, ['滤波失败：', ME.message], '运行错误');
                return;
            end

            % --- 补偿相位延迟（operate on y2） ---
            try
                % 是否补偿相位延迟（仅在用户设置了补偿且滤波器支持线性相位时才尽力补偿）
                compensate = isfield(p_intfilt,'intfilt_compensate') && p_intfilt.intfilt_compensate;
                if compensate
                    % 需要滤波器长度来计算延迟
                    if isfield(p_intfilt,'intfilt_filterLength') && ~isempty(p_intfilt.intfilt_filterLength)
                        filtlen = p_intfilt.intfilt_filterLength;
                    else
                        % 兜底：若没有保存，使用 length(b)
                        filtlen = length(b_for);  % fallback
                    end
            
                    % 检查是否为线性相位的安全判断：
                    %   - bandlimited 方法产生的 FIR 为线性相位（设计方式是对称系数）
                    %   - Lagrange 当 n 和 l 均为偶数时，滤波器**不是**线性相位（参考文档）
                    isLinearPhase = true;
                    if isfield(p_intfilt,'intfilt_mode') && strcmp(p_intfilt.intfilt_mode,'lagrange')
                        % 若 n 和 l 同时为偶数 -> 非线性相位
                        nval = 0;
                        if isfield(p_intfilt,'intfilt_n'), nval = p_intfilt.intfilt_n; end
                        if mod(nval,2) == 0 && mod(lval,2) == 0
                            isLinearPhase = false;
                        end
                    end
            
                    if ~isLinearPhase
                        % 非线性相位：提供三种选择：跳过 / 强制补偿 / 取消
                        choice = uiconfirm(fig_GUI, ...
                            ['检测到 Lagrange 模式且 n 与 l 均为偶数，滤波器不是线性相位。' newline ...
                             '自动补偿可能无法正确恢复相位，可能引入不可预期的相位或幅度失真。' newline newline ...
                             '请选择：跳过补偿（推荐）、强制补偿或取消操作。'], ...
                            '非线性相位 - 补偿选项', ...
                            'Options', {'跳过补偿','强制补偿','取消'}, 'DefaultOption', 1);
            
                        if strcmp(choice,'取消')
                            setStatus(handles,'已取消：用户在非线性相位情形下取消补偿操作');
                            return;
                        elseif strcmp(choice,'跳过补偿')
                            uialert_safe(fig_GUI, '已跳过延迟补偿（非线性相位情形）。', '跳过补偿',"Icon","info");
                            y2_final = y2;   % 不改动
                        else
                            % 用户选择强制补偿：尝试用群时延估算代表延迟（用中位数更鲁棒）
                            try
                                gd_vals = grpdelay(b_for); % 返回随频率的群时延向量
                                % 若 grpdelay 返回空或单一值，则按 length(b) 回退
                                if isempty(gd_vals)
                                    error('grpdelay 返回空');
                                end
                                d = round(median(gd_vals(:)));% 取中位数并四舍五入
                            catch
                                % 回退到基于滤波器长度的常用公式（尽管对非线性相位不严格）
                                d = round((filtlen - 1) / 2);
                            end
                            if d < 0, d = 0; end
            
                            % 应用按 d 的样本级移位补偿（多列支持）
                            [origRows2, origCols2] = size(y2);
                            if origRows2 > d
                                y2_trimmed = y2((d+1):end, :);
                                padRows = origRows2 - size(y2_trimmed,1);
                                if padRows > 0
                                    y2_final = [y2_trimmed; zeros(padRows, origCols2)];
                                else
                                    y2_final = y2_trimmed;
                                end
                            else
                                % 罕见情况：长度不足以移位 -> 返回全零并提示
                                y2_final = zeros(size(y2));
                                uialert_safe(fig_GUI, '滤波结果长度不足以执行强制延迟补偿，已返回零向量。','补偿失败');
                            end
            
                            % 提示用户已强制补偿并提醒风险
                            uialert_safe(fig_GUI, ...
                                sprintf('已按估算群时延 %d 样本强制补偿（中位数群时延）。注意：这可能引入相位或幅度畸变。', d), ...
                                '强制补偿已应用',"Icon","warning");
                            setStatus(handles,sprintf('强制补偿：已按 %d 样本移位（非线性相位）', d));
                        end
            
                    else
                        % 线性相位：使用对称 FIR 的常见延迟公式 floor((N-1)/2)
                        d = floor((filtlen - 1) / 2);
                        if d < 0, d = 0; end
            
                        % 保持信号维度（若进行截断则用零填充尾部以恢复原长度）
                        [origRows2, origCols2] = size(y2);
                        if origRows2 > d
                            y2_trimmed = y2((d+1):end, :);
                            padRows = origRows2 - size(y2_trimmed,1);
                            if padRows > 0
                                y2_final = [y2_trimmed; zeros(padRows, origCols2)];
                            else
                                y2_final = y2_trimmed;
                            end
                        else
                            % 如果滤波后长度不大于 d（罕见），则直接返回全零并提示
                            y2_final = zeros(size(y2));
                            uialert_safe(fig_GUI, '滤波结果长度不足以执行延迟补偿，返回零向量。','补偿失败');
                        end
                    end % 非线性相位：提供三种选择：跳过 / 强制补偿 / 取消。线性相位：使用对称 FIR 的常见延迟公式 floor((N-1)/2)
                else
                    % 不补偿：直接输出滤波结果
                    y2_final = y2;
                end % 是否补偿相位延迟
            catch ME
                uialert_safe(fig_GUI, ['补偿相位延迟 出错：' ME.message], '应用错误');
                setStatus(handles,'应用失败：补偿相位延迟 出错');
                return;
            end
            
            % --- 恢复原始维度与类型 ---
            try
                y_restored = restoreFn(y2_final);  % 恢复到与 x_use 相同的 shape（time 在原来的 tdim）
                % 尝试将类型转换回原始 x_use 类型（保守尝试）
                try
                    if ~isa(y_restored, origClass_X)
                        if isCommonNumericOrLogicalClass(origClass_X)
                            y = cast(y_restored, origClass_X);
                        else
                            % 非常规类：尽量 cast，否则保留 numeric
                            try
                                y = cast(y_restored, origClass_X);
                            catch
                                y = y_restored;
                            end
                        end
                    else
                        y = y_restored;
                    end
                catch
                    y = y_restored;
                end
            catch ME
                uialert_safe(fig_GUI, ['恢复输出形状失败：' ME.message], '运行错误');
                return;
            end
        end


        % ------------------------------------- 如果是 FIRgaussdesign脉冲整形 则根据用户"滤波器应用"的用途（发射端滤波、接收端滤波、常规滤波）选择来进行相应的操作  ------------------------------------- 
        if isprop(handles,'gaussdesignParams') && strcmp(handles.ddDesignMethod.Value,'FIRgaussdesign脉冲整形')
            % 对通用函数的调用
            p_gauss = handles.gaussdesignParams; % 或 handles.rcosdesignParams
            b = S.filter_b;
            a = S.filter_a; % 一般为 1
            [x_y, err] = applyShapingFilter(b, a, p_gauss, x_use, S, handles, fig_GUI);
            if ~isempty(err)
                % applyShapingFilter 已经用 uialert_safe/ uialert 提示过用户，按旧逻辑返回
                setStatus(handles,'滤波失败'); % 如果你有 setStatus，保持原逻辑
                return;
            else
                y = x_y; % 使用返回值
            end
        end


        % ------------------------------------- 如果是 FIRrcosdesign脉冲整形 则根据用户"滤波器应用"的用途（发射端滤波、接收端滤波、常规滤波）选择来进行相应的操作  ------------------------------------- 
        if isprop(handles,'rcosdesignParams') && strcmp(handles.ddDesignMethod.Value,'FIRrcosdesign脉冲整形')
            p_rcos = handles.rcosdesignParams;
            b = S.filter_b;
            a = S.filter_a; % 一般为 1
            [x_y, err] = applyShapingFilter(b, a, p_rcos, x_use, S, handles, fig_GUI);
            if ~isempty(err)
                % applyShapingFilter 已经用 uialert_safe/ uialert 提示过用户，按旧逻辑返回
                setStatus(handles,'滤波失败'); % 如果你有 setStatus，保持原逻辑
                return;
            else
                y = x_y; % 使用返回值
            end
           
        end



        % ------------------------------------- 如果是 Savitzky-Golay 则根据用户"平滑滤波器 / 微分滤波器"的选择来进行相应的操作  ------------------------------------- 
        if isprop(handles,'sgolayParams') && strcmp(handles.ddDesignMethod.Value,'Savitzky-Golay') 
            p_sgolay = handles.sgolayParams;

            try
                if strcmp(p_sgolay.filterType,'smooth')
                    % 使用 B 矩阵的中心行按 sgolayfilt 的做法处理（稳态 + 启动/终止瞬变）
                    % 获取或重算 B 矩阵
                    if isprop(handles,'sgolay_Bmatrix') && ~isempty(handles.sgolay_Bmatrix)
                        Bmat = handles.sgolay_Bmatrix;
                        % 如果 B 的尺寸异常，尝试重算
                        if size(Bmat,1) < (p_sgolay.fl+1)/2 || size(Bmat,2) ~= p_sgolay.fl
                            if exist('uialert_safe','file'), uialert_safe(fig_GUI,'保存的 Savitzky-Golay B 矩阵尺寸异常，尝试重新计算。','应用警告',"Icon","warning");
                            else; uialert(fig_GUI,'保存的 Savitzky-Golay B 矩阵尺寸异常，尝试重新计算。','应用警告'); end
                            if isfield(p_sgolay,'w') && ~isempty(p_sgolay.w)
                                Bmat = sgolay(p_sgolay.m, p_sgolay.fl, p_sgolay.w);
                            else
                                Bmat = sgolay(p_sgolay.m, p_sgolay.fl);
                            end
                        end
                    else
                        % 兜底重算 B
                        if isfield(p_sgolay,'w') && ~isempty(p_sgolay.w)
                            Bmat = sgolay(p_sgolay.m, p_sgolay.fl, p_sgolay.w);
                        else
                            Bmat = sgolay(p_sgolay.m, p_sgolay.fl);
                        end
                    end

                    % 中心行和 m 值
                    m = (p_sgolay.fl - 1) / 2;           % 帧两侧长度
                    center_row = Bmat(m+1, :);           % 中心行（长度 = fl）

                    % ---------- 统一支持向量 / 矩阵 / N-D 数组的处理（使用 to2DtimeMajor） ----------
                    % 先计算/保证 Bmat, m, center_row 已存在
                    
                    % 1) 决定是否使用 timeDim（优先 S.timeDim；若未指定且 ndims>2，则假设 tdim=1）
                    useTimeDim = false;
                    % 优先使用 S.timeDim（如果存在且有效），否则回退至第一个非单例维度
                    if  ~isempty(S.timeDim) && S.timeDim==round(S.timeDim) && S.timeDim>=1
                        tdim = S.timeDim;
                        useTimeDim = true;
                   else
                        tdim = find(size(x_use)~=1,1,'first');
                        if ~isempty(tdim) && tdim>=1
                            useTimeDim = true;
                        end
                    end
                    
                    if useTimeDim
                        try
                            % 将任意维转成 [N x channels]，获得恢复函数
                            [X2, restoreFn] = to2DtimeMajor(x_use, tdim);
                        catch ME
                            uialert_safe(fig_GUI, ['准备输入（to2DtimeMajor）失败：' ME.message], '运行错误');
                            return;
                        end
                    else
                        % 未指定 timeDim：只在 x_use 为向量或 2D 矩阵时按列处理（保持与标准路径一致）
                        if ndims(x_use) > 2
                            uialert_safe(fig_GUI, 'Savitzky-Golay：输入为多维数组但未指定 S.timeDim。请设置 S.timeDim 或使用常规滤波路径。', '参数缺失');
                            return;
                        else
                            % 对于纯 1D/2D 情形：保持原策略（保证 X2 为 [N x channels]）
                            if isvector(x_use)
                                % 保证列向量
                                X2 = x_use(:);
                                % 生成简单 restoreFn，保持行向量/列向量形式
                                origIsRow = isrow(x_use);
                                origSize = size(x_use);
                                if origIsRow
                                    restoreFn = @(Y2) reshape(Y2.', origSize);
                                else
                                    restoreFn = @(Y2) reshape(Y2, origSize);
                                end
                            else
                                % x_use 已是 2D 矩阵（n x c）或 (n x 1)
                                X2 = x_use;
                                restoreFn = @(Y2) reshape(Y2, size(x_use));
                            end
                        end
                    end
                    
                    % 准备输出容器，保持数据类型（若 X2 是 GPU/double 等则保留 same 'like'）
                    [nSamples, nChannels] = size(X2);
                    Y2 = zeros(nSamples, nChannels, 'like', X2);
                    
                    % parameters
                    fl = p_sgolay.fl;
                    m_local = (fl - 1) / 2;   % 同你原来命名的 m
                    center_row = Bmat(m_local+1, :);  % 保证 row vector length fl
                    
                    % 对每个 channel 应用原来的列处理逻辑（steady + ybeg + yend；若短信号按策略处理）
                    for c = 1:nChannels
                        xc = X2(:, c);
                        lx = numel(xc);
                    
                        if lx >= fl
                            % 启动瞬变
                            steady = conv(xc, center_row, 'same');
                            ybeg = Bmat(1:m_local, :) * xc(1:fl);
                            % 终止瞬变
                            yend = Bmat(fl - m_local + 1 : fl, :) * xc(lx - fl + 1 : lx);
                            tmp = steady;
                            tmp(1:m_local) = ybeg;
                            tmp(lx - m_local + 1 : lx) = yend;
                            Y2(:, c) = tmp;
                        else
                            % 信号长度小于帧长度 -> 使用更复杂的短信号处理策略
                            % 策略来源于 p_sgolay.shortSignalMethod，默认 'pad'（镜像填充）
                            method = 'pad';
                            if isfield(p_sgolay,'shortSignalMethod') && ~isempty(p_sgolay.shortSignalMethod)
                                method = p_sgolay.shortSignalMethod;
                            end
                            switch lower(method)
                                case 'pad'
                                    % ======= 镜像填充（mirror padding）到至少 fl 长 =======
                                    needed = fl - lx;
                                    % 对称镜像两端（先左后右，尽量均匀）
                                    leftPad = floor(needed/2);
                                    rightPad = needed - leftPad;
                                    if leftPad > 0
                                        leftSegment = xc(1:min(lx, leftPad));
                                        leftPadVals = flipud(leftSegment);
                                    else
                                        leftPadVals = [];
                                    end
                                    if rightPad > 0
                                        rightSegment = xc(max(1,lx-rightPad+1):lx);
                                        rightPadVals = flipud(rightSegment);
                                    else
                                        rightPadVals = [];
                                    end
                                    x_ext = [leftPadVals; xc; rightPadVals];
                    
                                    % 现在对扩展信号使用同样的 steady+ybeg+yend 处理
                                    steady_ext = conv(x_ext, center_row, 'same');
                                    lx_ext = numel(x_ext);
                                    if lx_ext >= fl
                                        ybeg_ext = Bmat(1:m_local, :) * x_ext(1:fl);
                                        yend_ext = Bmat(fl - m_local + 1 : fl, :) * x_ext(lx_ext - fl + 1 : lx_ext);
                                        y_ext = steady_ext;
                                        y_ext(1:m_local) = ybeg_ext;
                                        y_ext(lx_ext - m_local + 1 : lx_ext) = yend_ext;
                                    else
                                        % 极端情形（理论上不会发生）：退化到 conv
                                        y_ext = conv(x_ext, center_row, 'same');
                                    end
                                    % 裁剪回原长度（注意左Pad长度）
                                    startIdx = leftPad + 1;
                                    Y2(:, c) = y_ext(startIdx : startIdx + lx - 1);
                                    % 提示
                                    if exist('uialert_safe','file')
                                        uialert_safe(fig_GUI, sprintf('第 %d 通道长度小于 fl，采用镜像填充处理。', c), '应用信息', "Icon", "info");
                                    else
                                        uialert(fig_GUI, sprintf('第 %d 通道长度小于 fl，采用镜像填充处理。', c), '应用信息');
                                    end
                    
                                case 'ls'
                                    % ======= 局部最小二乘滑动拟合（每点用可用邻域做多项式拟合） =======
                                    ytmp = zeros(lx,1, 'like', xc);
                                    halfW = floor(fl/2);
                                    for i = 1:lx
                                        % local window indices
                                        left = max(1, i - halfW);
                                        right = min(lx, i + halfW);
                                        xi = (left:right).';
                                        yi = xc(left:right);
                                        % local degree: 不超过 m, 也不超过样本数-1
                                        deg = min(p_sgolay.m, numel(xi)-1);
                                        % 构造 Vandermonde with positions relative to center
                                        tpos = (xi - i); % relative positions so evaluate at 0
                                        V = ones(numel(tpos), deg+1);
                                        for dd = 1:deg
                                            V(:, dd+1) = tpos.^dd;
                                        end
                                        % 支持权重切片（如果 p_sgolay.w 可用）
                                        if isfield(p_sgolay,'w') && ~isempty(p_sgolay.w)
                                            % map full weight vector indices to local window positions
                                            % full window centers on i would be indices (i-halfW : i+halfW)
                                            fullLeft = i - halfW;
                                            fullRight = i + halfW;
                                            % compute overlap between [fullLeft, fullRight] and [1,lx]
                                            overlapLeft = max(1, fullLeft);
                                            overlapRight = min(lx, fullRight);
                                            % slice from p_sgolay.w accordingly (centered)
                                            % compute corresponding indices in p_sgolay.w
                                            wStart = 1 + (overlapLeft - fullLeft);
                                            wEnd = wStart + (overlapRight - overlapLeft);
                                            try
                                                wsub = p_sgolay.w(wStart:wEnd);
                                                if numel(wsub) ~= numel(tpos), wsub = []; end
                                            catch
                                                wsub = [];
                                            end
                                        else
                                            wsub = [];
                                        end
                    
                                        if isempty(wsub)
                                            % ordinary LS
                                            coeff = V \ yi;
                                        else
                                            % weighted LS: solve (W*V) coeff = W*yi  -> use sqrt weights
                                            Ws = diag(sqrt(wsub(:)));
                                            coeff = (Ws*V) \ (Ws*yi);
                                        end
                                        % evaluate at center (t=0) -> just coeff(1)
                                        ytmp(i) = coeff(1);
                                    end
                                    Y2(:, c) = ytmp;
                                    if exist('uialert_safe','file')
                                        uialert_safe(fig_GUI, sprintf('第 %d 通道长度小于 fl，采用局部最小二乘处理（计算量较大）。', c), '应用信息', "Icon", "info");
                                    else
                                        uialert(fig_GUI, sprintf('第 %d 通道长度小于 fl，采用局部最小二乘处理（计算量较大）。', c), '应用信息');
                                    end
                    
                                otherwise
                                    % fallback：用 center_row conv
                                    Y2(:, c) = conv(xc, center_row, 'same');
                                    if exist('uialert_safe','file')
                                        uialert_safe(fig_GUI, sprintf('第 %d 通道未知短信号处理方法，退回到中心行 conv。', c), '应用警告', "Icon", "warning");
                                    else
                                        uialert(fig_GUI, sprintf('第 %d 通道未知短信号处理方法，退回到中心行 conv。', c), '应用警告');
                                    end
                            end % switch method
                        end % if lx >= fl
                    end % for channels
                    
                    % 还原回原始形状/类型
                    y = restoreFn(Y2);
                    % -------------------------------------------------------------------------

                else % diff
                    % 优先使用已保存的 G 矩阵；若不存在，则用与设计时相同的权重/参数重新计算 G
                    if isprop(handles,'sgolay_Gmatrix') && ~isempty(handles.sgolay_Gmatrix)
                        G = handles.sgolay_Gmatrix;
                    else
                        % 尝试重算（注意：重算必须使用相同的权重）
                        if isfield(p_sgolay,'w') && ~isempty(p_sgolay.w)
                            [~, G] = sgolay(p_sgolay.m, p_sgolay.fl, p_sgolay.w);
                        else
                            [~, G] = sgolay(p_sgolay.m, p_sgolay.fl);
                        end
                    end

                    % 检查 G 与 diff_N 合法性
                    if ~isfield(p_sgolay,'diff_N') || isempty(p_sgolay.diff_N)
                        if exist('uialert_safe','file'), uialert_safe(fig_GUI,'未指定微分阶数 diff_N，无法应用微分滤波器。','参数错误');
                        else; uialert(fig_GUI,'未指定微分阶数 diff_N，无法应用微分滤波器。','参数错误'); end
                        setStatus(handles,'应用失败：缺少 diff_N'); return;
                    end
                    dN = p_sgolay.diff_N;
                    if dN > size(G,2)-1
                        if exist('uialert_safe','file'), uialert_safe(fig_GUI,'所选微分阶数超过可得阶数，请修改 m 或 diff_N。','参数错误');
                        else; uialert(fig_GUI,'所选微分阶数超过可得阶数，请修改 m 或 diff_N。','参数错误'); end
                        setStatus(handles,'应用失败：diff_N 越界'); return;
                    end
                    if ~isprop(S,'fs') || isempty(S.fs) || S.fs <= 0
                        if exist('uialert_safe','file'), uialert_safe(fig_GUI,'采样率 S.fs 无效，无法计算微分核。','参数错误');
                        else; uialert(fig_GUI,'采样率 S.fs 无效，无法计算微分核。','参数错误'); end
                        setStatus(handles,'应用失败：采样率无效'); return;
                    end

                    dt = 1 / S.fs;
                    kernel = factorial(dN) / ((-dt)^dN) * G(:, dN+1);

                    % --- diff 分支：统一支持 N-D ---
                    % 1) 检查/计算 G 与 kernel 已完成（你原来已有）
                    % kernel 已经计算为列向量 (fl x 1)
                    
                    % 2) 同样决定 timeDim
                    useTimeDim = false;
                    % 优先使用 S.timeDim（如果存在且有效），否则回退至第一个非单例维度
                    if  ~isempty(S.timeDim) && S.timeDim==round(S.timeDim) && S.timeDim>=1
                        tdim = S.timeDim; 
                        useTimeDim = true;
                    else
                        tdim = find(size(x_use)~=1,1,'first');
                        if ~isempty(tdim) && tdim>=1
                            useTimeDim = true;
                        end
                    end
                    
                    if useTimeDim
                        [X2, restoreFn] = to2DtimeMajor(x_use, tdim);
                    else
                        if isvector(x_use)
                            X2 = x_use(:);
                            origIsRow = isrow(x_use);
                            origSize = size(x_use);
                            if origIsRow
                                restoreFn = @(Y2) reshape(Y2.', origSize);
                            else
                                restoreFn = @(Y2) reshape(Y2, origSize);
                            end
                        else
                            X2 = x_use;
                            restoreFn = @(Y2) reshape(Y2, size(x_use));
                        end
                    end
                    
                    [nSamples, nChannels] = size(X2);
                    Y2 = zeros(nSamples, nChannels, 'like', X2);
                    
                    for c = 1:nChannels
                        xc = X2(:, c);
                        Y2(:, c) = conv(xc, kernel(:), 'same');
                    end
                    
                    y = restoreFn(Y2);

                end

            catch ME
                if exist('uialert_safe','file'), uialert_safe(fig_GUI, ['应用 Savitzky-Golay 出错：' ME.message], '应用错误');
                else; uialert(fig_GUI, ['应用 Savitzky-Golay 出错：' ME.message], '应用错误'); end
                setStatus(handles,'应用失败：Savitzky-Golay 出错');
                return;
            end
        end


        

        % ============================ 在计算出 y（滤波结果）后 ===================================
        % 确定时间维 tdim（优先使用 S.timeDim，否则回退至第一个非单例维）             
        tdim = [];
        useTimeDim = false;
        if  ~isempty(S.timeDim) && S.timeDim==round(S.timeDim) && S.timeDim>=1
            tdim = S.timeDim;
            useTimeDim = true;
        else
            szx = size(y);
            tdim = find(szx~=1,1,'first');
            if ~isempty(tdim) && tdim>=1
                useTimeDim = true;
            else
                tdim = 1; % fallback
            end
        end  
        % 处理数据中Nan/Inf等非有限数值
        y = fillNonfinite(y,tdim);

        % 保存最近一次结果（向后兼容）
        S.filtered = y;

        handles.btnPlayFilt.Enable = 'on'; 
        handles.btnSaveFiltered.Enable = 'on'; 
        handles.btnShowCompare.Enable = 'on';
        % 启用导出数据到工作区按钮（如果先前被禁用）
        handles.btnExportDataToWS.Enable = 'on';
        updatePlotsAndAnalysis(S, handles);
        setStatus(handles,'滤波已完成，图像与分析结果已更新');
        
    end

    %% ---- "继续滤波"按钮回调 ----
    function onContinueFilter(~,~)
        % 如果历史为空，不能开始
        if isempty(S.filteredHistory)
            uialert_safe(fig_GUI,'没有上一次的滤波结果可继续。','操作错误');
            setStatus(handles,'继续滤波失败：无历史滤波数据');
            fprintf('调试点64：继续滤波失败：无历史滤波数据\n');
            return;
        end
    
        % --- 确定时间维 tdim（优先使用 S.timeDim，否则回退至第一个非单例维） ---
        tdim = [];
        if  ~isempty(S.timeDim) && S.timeDim==round(S.timeDim) && S.timeDim>=1
            tdim = S.timeDim;
            useTimeDim = true;
        else
            template = [];
            if isprop(S,'continueFilterBase') && ~isempty(S.continueFilterBase)
                template = S.continueFilterBase;
            elseif isprop(S,'filtered') && ~isempty(S.filtered)
                template = S.filtered;
            else
                template = S.filteredHistory{end};
            end
            sz = size(template);
            tdim = find(sz~=1,1,'first');
            if ~isempty(tdim) && tdim>=1
                useTimeDim = true;
            else
                tdim = 1; useTimeDim = false; % 兜底
            end
        end
    
        % ---------- 还没进入基准模式：进入基准模式的处理 ----------
        if ~isprop(S,'continueFilterMode') || ~S.continueFilterMode
            S.continueFilterMode = true;
            S.continueFilterPending = false; % 取消老的 pending 语义
            S.continueBaseIndex = numel(S.filteredHistory);
            S.continueFilterBase = S.filteredHistory{S.continueBaseIndex}; % 基准复制（N 维或向量/矩阵）
            S.continueTempLatest = []; % 无临时试验结果
            setStatus(handles,sprintf('已进入继续滤波基准模式：以第 %d 次滤波结果为基准（可多次重新设计并 Apply，产生临时结果）。', S.continueBaseIndex));
            % 统一刷新按钮状态
            try updateApplyButtonEnable(S.filterIsDesigned, S.allowApplyFilter, handles); catch; end
            return;
        end
    
        % ---------- 已在基准模式：此次点击为提交当前临时结果 ----------
        % 只有当存在临时试验结果时，才能提交
        if isempty(S.continueTempLatest)
            uialert_safe(fig_GUI,'没有临时试验结果可提交。请先重新设计并应用一次滤波器以产生临时结果（不会入历史）。','操作提示',"Icon","warning");
            setStatus(handles,'继续滤波提交失败：无临时结果。请先 Apply 产生临时结果。');
            fprintf('调试点65：继续滤波提交失败：无临时结果。请先 Apply 产生临时结果。\n');
            return;
        end
    
        % ----------  提交临时结果到历史（成为新的已提交 filtered） ----------
        S.filteredHistory{end+1} = S.continueTempLatest; 
        S.filterHistory{end+1} = struct('b', S.filter_b, 'a', S.filter_a);
        S.continueFilterCount = S.continueFilterCount + 1;
        
    
        % 更新基准到最新已提交项
        S.continueBaseIndex = numel(S.filteredHistory);
        S.continueFilterBase = S.filteredHistory{S.continueBaseIndex};
    
        % 清除临时
        S.continueTempLatest = [];
    
        % ---------- 控制继续模式是否结束（计数/上限） ----------
        if ~isprop(S,'continueFilterMax') || isempty(S.continueFilterMax)
            S.continueFilterMax = Inf; % 若未设置则认为无限
        end
    
        if S.continueFilterCount >= S.continueFilterMax
            S.continueFilterMode = false;
            S.allowEnableContinueOnApply = false;   % 禁止 Apply 恢复 Continue
            S.allowApplyFilter = false;             % 禁止应用滤波
            try handles.btnContinue.Enable = 'off'; catch; end
            updateContinueButtonEnable(S, handles);
            updateApplyButtonEnable(S.filterIsDesigned, S.allowApplyFilter, handles);
            setStatus(handles,sprintf('已提交并完成第 %d 次继续滤波（达到上限 %d），继续滤波/应用已被禁用。', S.continueFilterCount, S.continueFilterMax));
        else
            % 仍然需参考集中函数决定是否启用（以便在 edge case 一致）
            updateContinueButtonEnable(S, handles);
            updateApplyButtonEnable(S.filterIsDesigned, S.allowApplyFilter, handles);
        end
    
        % ---------------- 将刚提交的历史以"叠加"方式绘出（依据 plotSettings） ----------------
        try
            latest = S.filteredHistory{end};
    
            % 处理数据中Nan/Inf等非有限数值
            latest = fillNonfinite(latest,tdim); 
    
            % 为绘图统一转为 [N x channels]
            [Y2, ~] = to2DtimeMajor(latest, tdim, false);
    
            Nplot = size(Y2,1);
            nch = size(Y2,2);
            t_y = (0:Nplot-1)/S.fs;
    
            % 读取绘图设置（优先使用 handles.plotSettings）
            plotSettings = handles.plotSettings;
    
            axes(handles.axFiltTime);
            hold(handles.axFiltTime,'on');
            if ~isreal(Y2)
                plotData = abs(Y2);
            else
                plotData = Y2;
            end
    
            % 如果 plotTimeWave 可直接使用也可，但这里逐通道绘制以便管理返回句柄
            if strcmpi(plotSettings.signalPlotMode, 'stem')
                hnew = gobjects(1,nch);
                for ch = 1:nch
                    hnew(ch) = stem(handles.axFiltTime, t_y, plotData(:,ch), 'filled','Marker','o','MarkerSize',3);
                    try set(hnew(ch), 'DisplayName', sprintf('第%d次滤波-ch%d', numel(S.filteredHistory), ch)); catch; end
                end
            else
                hnew = gobjects(1,nch);
                for ch = 1:nch
                    hnew(ch) = plot(handles.axFiltTime, t_y, plotData(:,ch));
                    try set(hnew(ch), 'DisplayName', sprintf('第%d次滤波-ch%d', numel(S.filteredHistory), ch)); catch; end
                end
            end
    
            % 将句柄追加到 S.filteredPlotHandlesTime（保持 cell 数组）
            if ~isprop(S,'filteredPlotHandlesTime') || isempty(S.filteredPlotHandlesTime)
                S.filteredPlotHandlesTime = {hnew};
            else
                S.filteredPlotHandlesTime{end+1} = hnew;
            end
    
            % 频域绘制：使用 computeSpecForPlot + plotSpectrum，遵循 plotSettings
            axes(handles.axFiltSpec);
            hold(handles.axFiltSpec,'on');
            % 计算频谱（computeSpecForPlot 会使用 plotSettings.filterSpecNFFT 或自动选择）
            [freq_t, mag_t] = computeSpecForPlot(Y2, S.fs, plotSettings);
    
            % 选择绘制的通道索引（与其它函数保持一致，最多绘制4通道以避免界面拥挤）
            maxPlotChannels = 4;
            plotCh = 1:min(nch, maxPlotChannels);
    
            % plotSpectrum 的最后一个参数 clearFirst 设置为 false（叠加）
            hnewSpec = plotSpectrum(handles.axFiltSpec, freq_t, mag_t, plotSettings, plotCh, sprintf('第%d次滤波', numel(S.filteredHistory)), false);
            % 设置 xlim（按归一化与单/双边）
            if plotSettings.specFreqNormalized
                if strcmpi(plotSettings.specFreqSide,'double')
                    xlim(handles.axFiltSpec, [0, 2]);
                else
                    xlim(handles.axFiltSpec, [0, 1]);
                end
            else
                if strcmpi(plotSettings.specFreqSide,'double')
                    xlim(handles.axFiltSpec, [0, S.fs]);
                else
                    xlim(handles.axFiltSpec, [0, S.fs/2]);
                end
            end
    
            if ~isprop(S,'filteredPlotHandlesSpec') || isempty(S.filteredPlotHandlesSpec)
                S.filteredPlotHandlesSpec = {hnewSpec};
            else
                S.filteredPlotHandlesSpec{end+1} = hnewSpec;
            end
    
            % 更新 legend，确保已提交历史叠加并被列入 legend
            updateFilteredLegends(S, handles.axFiltTime, handles.axFiltSpec);
        catch ME
            % 提交已完成，但绘图可能出错 -> 记录调试信息但不阻塞流程
            fprintf('调试点66：继续滤波模式下绘图错误（但提交已完成）： %s\n', ME.message);
            warning('onContinueFilter:plotFail','继续滤波提交后绘图失败：%s', ME.message);
        end
    
    end

    %% ---- 继续滤波模式时，legend更新函数 ---- 
    function updateFilteredLegends(S, axFiltTime, axFiltSpec)
    % 传入的 handle类 S
    % 对 S 的对象内容有 "读" 操作，无 "写" 操作

        % -------- 时域 legend --------
        try
            hTimeList = gobjects(0);
            labelsTime = {};
    
            % Collect history entries in order
            if isprop(S,'filteredPlotHandlesTime') && ~isempty(S.filteredPlotHandlesTime)
                for i = 1:numel(S.filteredPlotHandlesTime)
                    entry = S.filteredPlotHandlesTime{i};
                    hArr = flattenHandlesEntry(entry);
                    if isempty(hArr), continue; end
                    if isscalar(hArr)
                        % single handle for this history entry
                        if ~any(hTimeList == hArr)
                            hTimeList(end+1) = hArr; %#ok<AGROW>
                            labelsTime{end+1} = sprintf('第%d次滤波', i);
                        end
                    else
                        % multiple handles (channels) for this history entry
                        for ch = 1:numel(hArr)
                            if ~any(hTimeList == hArr(ch))
                                hTimeList(end+1) = hArr(ch); %#ok<AGROW>
                                labelsTime{end+1} = sprintf('第%d次滤波-ch%d', i, ch);
                            end
                        end
                    end
                end
            end
    
            % Handle temporary time handle(s)
            if isprop(S,'continueTempHandleTime') && ~isempty(S.continueTempHandleTime)
                tempEntry = S.continueTempHandleTime;
                tempArr = flattenHandlesEntry(tempEntry);
                if ~isempty(tempArr)
                    % For each temp handle: if already in hTimeList -> mark that label as (临时)
                    for k = 1:numel(tempArr)
                        th = tempArr(k);
                        idx = find(hTimeList == th, 1);
                        if ~isempty(idx)
                            labelsTime{idx} = sprintf('%s (临时)', labelsTime{idx});
                        else
                            % not existing -> append at end; label with base index and maybe channel
                            baseIdx = 0;
                            if isprop(S,'continueBaseIndex') && ~isempty(S.continueBaseIndex)
                                baseIdx = S.continueBaseIndex + 1; % show next index as in original logic
                            else
                                baseIdx = numel(S.filteredPlotHandlesTime) + 1;
                            end
                            % If only one temp handle or multiple, try label as ch number if multiple
                            if isscalar(tempArr)
                                lbl = sprintf('第%d次滤波 (临时)', baseIdx);
                            else
                                lbl = sprintf('第%d次滤波-ch%d (临时)', baseIdx, k);
                            end
                            hTimeList(end+1) = th; %#ok<AGROW>
                            labelsTime{end+1} = lbl;
                        end
                    end
                end
            end
    
            % Apply legend (or turn off)
            if ~isempty(hTimeList)
                legend(axFiltTime, hTimeList, labelsTime, 'Interpreter','none');
            else
                legend(axFiltTime, 'off');
            end
        catch
            fprintf('调试点69：第k次滤波时域legend添加错误\n');
        end
    
        % -------- 频域 legend --------
        try
            hSpecList = gobjects(0);
            labelsSpec = {};
    
            if isprop(S,'filteredPlotHandlesSpec') && ~isempty(S.filteredPlotHandlesSpec)
                for i = 1:numel(S.filteredPlotHandlesSpec)
                    entry = S.filteredPlotHandlesSpec{i};
                    hArr = flattenHandlesEntry(entry);
                    if isempty(hArr), continue; end
                    if isscalar(hArr)
                        if ~any(hSpecList == hArr)
                            hSpecList(end+1) = hArr; %#ok<AGROW>
                            labelsSpec{end+1} = sprintf('第%d次滤波', i);
                        end
                    else
                        for ch = 1:numel(hArr)
                            if ~any(hSpecList == hArr(ch))
                                hSpecList(end+1) = hArr(ch); %#ok<AGROW>
                                labelsSpec{end+1} = sprintf('第%d次滤波-ch%d', i, ch);
                            end
                        end
                    end
                end
            end
    
            % 临时频域句柄
            if isprop(S,'continueTempHandleSpec') && ~isempty(S.continueTempHandleSpec)
                tempEntry = S.continueTempHandleSpec;
                tempArr = flattenHandlesEntry(tempEntry);
                if ~isempty(tempArr)
                    for k = 1:numel(tempArr)
                        th = tempArr(k);
                        idx = find(hSpecList == th, 1);
                        if ~isempty(idx)
                            labelsSpec{idx} = sprintf('%s (临时)', labelsSpec{idx});
                        else
                            baseIdx = 0;
                            if isprop(S,'continueBaseIndex') && ~isempty(S.continueBaseIndex)
                                baseIdx = S.continueBaseIndex + 1;
                            else
                                baseIdx = numel(S.filteredPlotHandlesSpec) + 1;
                            end
                            if isscalar(tempArr)
                                lbl = sprintf('第%d次滤波 (临时)', baseIdx);
                            else
                                lbl = sprintf('第%d次滤波-ch%d (临时)', baseIdx, k);
                            end
                            hSpecList(end+1) = th; %#ok<AGROW>
                            labelsSpec{end+1} = lbl;
                        end
                    end
                end
            end
    
            if ~isempty(hSpecList)
                legend(axFiltSpec, hSpecList, labelsSpec, 'Interpreter','none');
            else
                legend(axFiltSpec, 'off');
            end
        catch
            fprintf('调试点70：第k次滤波频域legend添加错误\n');
        end
                
        
    end

    %% ---- 统一清除继续滤波状态的辅助函数 ----
    function clearContinueFilterState(S, handles)
    % 传入的 handle类 S, handles
    % 对 S 的对象内容有 "读/写" 操作
    % 对 handles 的对象内容有 "读/写" 操作

        % 清除 S 内部历史
        S.resetContinueFilterState();

        % 如果存在已打开的滤波器指标窗口，关闭并清空保存句柄
        try
            if isprop(handles,'filterMetricsFig') && ~isempty(handles.filterMetricsFig) && isvalid(handles.filterMetricsFig)
                close(handles.filterMetricsFig);
            end
        catch
        end
        handles.filterMetricsFig = [];
        handles.filterMetricsComponents = struct();
        
        % 关闭并清空群延迟窗口（与 filterMetrics 一致）
        try
            if isprop(handles, 'groupDelayFig') && ~isempty(handles.groupDelayFig) && isvalid(handles.groupDelayFig)
                close(handles.groupDelayFig);
            end
        catch
        end
        handles.groupDelayFig = [];
        handles.groupDelayComponents = struct();

        % 关闭并清空单位冲激响应窗口（与 filterMetrics / 群延迟 一致）
        try
            if isprop(handles, 'impulseFig') && ~isempty(handles.impulseFig) && isvalid(handles.impulseFig)
                close(handles.impulseFig);
            end
        catch
        end
        handles.impulseFig = [];
        handles.impulseComponents = struct();

        % 关闭并清空相位延迟窗口（与群延迟 一致）
        try
            if isprop(handles, 'phaseDelayFig') && ~isempty(handles.phaseDelayFig) && isvalid(handles.phaseDelayFig)
                close(handles.phaseDelayFig);
            end
        catch
        end
        handles.phaseDelayFig = [];
        handles.phaseDelayComponents = struct();

        % 关闭并清空零极点图窗口（与群延迟 一致）
        try
            if isprop(handles, 'pzFig') && ~isempty(handles.pzFig) && isvalid(handles.pzFig)
                close(handles.pzFig);
            end
        catch
        end
        handles.pzFig = [];
        handles.pzComponents = struct();

        % 关闭并清空单位阶跃响应窗口（与群延迟 一致）
        try
            if isprop(handles, 'stepRespFig') && ~isempty(handles.stepRespFig) && isvalid(handles.stepRespFig)
                close(handles.stepRespFig);
            end
        catch
        end
        handles.stepRespFig = [];
        handles.stepRespComponents = struct();



        % 关闭 filterAnalyzer（若打开）
        try
            if isprop(handles,'filterAnalyzerApp') && ~isempty(handles.filterAnalyzerApp)
                % filterAnalyzer 返回的对象在不同 MATLAB 版本上可能是 app window 或者一个 handle
                try
                    close(handles.filterAnalyzerApp);
                catch
                    % 若不能直接 close（例如返回的是 matlab.graphics GraphicsPlaceholder），忽略
                end
            end
        catch
        end
        handles.filterAnalyzerApp = [];

        % % 设计失效后关闭相应按钮
        % try
        %     handles.ddFilterAnalysis.Enable = 'off';  % 禁用滤波器分析下拉框
        %     handles.btnViewFilterAnalysis.Enable = 'off';  % 禁用查看滤波器分析按钮
        % catch
        % end

        % 更新 UI 状态
        updateContinueButtonEnable(S, handles);
        updateApplyButtonEnable(S.filterIsDesigned, S.allowApplyFilter, handles);


        % 关闭 legend
        try
            legend(handles.axFiltTime, 'off');
            legend(handles.axFiltSpec, 'off');
        catch
        end


        % 禁用继续滤波与与滤波后相关的操作按钮
        try
            handles.btnContinue.Enable = 'off';
            handles.btnPlayFilt.Enable = 'off';
            handles.btnSaveFiltered.Enable = 'off';
            handles.btnShowCompare.Enable = 'off';
        catch
        end

        % 清除滤波后绘图（当用户重新加载原始数据或重新加噪时，
        % 滤波后图像应被清除以重新开始）
        try
            cla(handles.axFiltTime); cla(handles.axFiltSpec);
        catch
        end
        drawnow;pause(0.01);
        setStatus(handles,'继续滤波流程已重置（历史数据已清除）。');
    end

    %% ---- 集中判断/控制继续滤波按钮可用性的函数 ---- 
    function updateContinueButtonEnable(S, handles)
    % 传入的 handle类 S, handles
    % 对 S 的对象内容有 "读" 操作，无 "写" 操作
    % 对 handles 的对象内容有 "写" 操作

        % 控制何时启用/禁用 btnContinue（集中判断）
        % 启用条件：
        %  - 存在已提交的滤波后历史（S.filteredHistory 非空）
        %  - 当前继续计数未达到上限 (S.continueFilterCount < S.continueFilterMax)
        %  - 且允许由 Apply 启用（S.allowEnableContinueOnApply == true）
        try
            if ~isempty(S.filteredHistory) && (S.continueFilterCount < S.continueFilterMax) && S.allowEnableContinueOnApply
                handles.btnContinue.Enable = 'on';
            else
                handles.btnContinue.Enable = 'off';
            end
        catch
            % 忽略 UI 控制错误，避免阻塞
        end
    end

    %% ---- “绘图设置”按钮回调（严格模态窗口） ---- 
    function openPlotSettingsWindow(~, ~)
        % 严格模态绘图设置窗口（N行6列）
        dlg_pm = createCenteredUIFigure('Name','绘图设置','WindowStyle','modal','Position',[400 300 690 430]);
    
        gl_pm = uigridlayout(dlg_pm, [7, 6]);
        gl_pm.RowHeight = {'fit',32,32,32,32,32,'1x'};
        gl_pm.ColumnWidth =  {125,'1x','1x',125,'1x','1x'};
        gl_pm.Padding = [10 10 10 10];
    
        % 1行 [1 6] 文本说明区域
        ExplanatoryText = sprintf(['绘图设置说明：\n'...
        '1. 绘图模式：选择信号的时域/频谱显示方式（plot 或 stem）。默认：plot。注意：使用 stem 在数据量大或多通道时会显著降低绘图性能。\n'...
        '2. 频谱频率归一化：是否以归一化频率 f/Fs 显示频谱（归一化）或以实际频率（Hz）显示（非归一化）。默认：非归一化。\n'...
        '3. 频谱频率刻度：线性或对数（对数刻度适用于宽带或对数频率分析）。默认：线性。\n'...
        '4. 频谱频率范围：单边（0 — Fs/2）或双边（0 — Fs）。单边适用于实值信号的常见显示。默认：单边。\n'...
        '5. 频谱幅值模式：以 dB 或 线性幅值显示（dB 便于观察大动态范围）。默认：dB。\n'...
        '6. 频谱归一化幅值：是否将幅值归一化到最大值 1（便于不同信号间比较）。默认：非归一化。\n'...
        '7. 滤波器频谱分析点数：用于滤波器频谱计算的 NFFT，必须为整数且 ≥ 1（默认 8192）。数值越大频谱越平滑但计算更耗时。\n'...
        '提示：滤波器的频谱始终使用 plot 绘制；点击"应用"将把当前设置写回并立即更新主界面与比较窗口的相关图形。\n']);
        lblEx = uilabel(gl_pm,'Text',ExplanatoryText);
        lblEx.Layout.Row = 1; lblEx.Layout.Column = [1 6];
        lblEx.WordWrap = 'on';

        % 2行: 绘图模式（plot / stem）
        lbl1 = uilabel(gl_pm, 'Text', '绘图模式：', 'HorizontalAlignment','left','FontWeight','bold');
        lbl1.Layout.Row = 2; lbl1.Layout.Column = 1;
    
        bgPlotMode = uibuttongroup(gl_pm, 'SelectionChangedFcn', @(bg,event) []); % 我们稍后读值
        bgPlotMode.Layout.Row = 2; bgPlotMode.Layout.Column = [2 3];
        rPlot = uiradiobutton(bgPlotMode,'Text','plot','Tag','plot', 'Position', [10 6 120 20]);
        rStem = uiradiobutton(bgPlotMode,'Text','stem','Tag','stem', 'Position', [120 6 120 20]);
        % 默认选择 plot
        if strcmpi(handles.plotSettings.signalPlotMode,'stem')
            bgPlotMode.SelectedObject = rStem;
        else
            bgPlotMode.SelectedObject = rPlot;
        end
    
        % 3行: 频谱频率归一化
        lbl2 = uilabel(gl_pm,'Text','频谱频率归一化：','FontWeight','bold');
        lbl2.Layout.Row = 3; lbl2.Layout.Column = 1;
        bgFreqNorm = uibuttongroup(gl_pm); bgFreqNorm.Layout.Row = 3; bgFreqNorm.Layout.Column = [2 3];
        rFreqNormYes = uiradiobutton(bgFreqNorm,'Text','归一化','Tag','yes', 'Position', [10 6 120 20]);
        rFreqNormNo  = uiradiobutton(bgFreqNorm,'Text','非归一化','Tag','no', 'Position', [120 6 120 20]);
        if handles.plotSettings.specFreqNormalized
            bgFreqNorm.SelectedObject = rFreqNormYes;
        else
            bgFreqNorm.SelectedObject = rFreqNormNo;
        end
    
        % 4行: 频率刻度 & 频率范围(单边/双边)
        lbl3 = uilabel(gl_pm,'Text','频谱频率刻度：','FontWeight','bold'); lbl3.Layout.Row = 4; lbl3.Layout.Column = 1;
        bgFreqScale = uibuttongroup(gl_pm); bgFreqScale.Layout.Row = 4; bgFreqScale.Layout.Column = [2 3];
        rLin = uiradiobutton(bgFreqScale,'Text','线性','Tag','linear', 'Position', [10 6 120 20]);
        rLog = uiradiobutton(bgFreqScale,'Text','对数','Tag','log', 'Position', [120 6 120 20]);
        if strcmpi(handles.plotSettings.specFreqScale,'log'), bgFreqScale.SelectedObject = rLog; else; bgFreqScale.SelectedObject = rLin; end
    
        lbl4 = uilabel(gl_pm,'Text','频谱频率范围：','FontWeight','bold'); lbl4.Layout.Row = 4; lbl4.Layout.Column = 4;
        bgFreqSide = uibuttongroup(gl_pm); bgFreqSide.Layout.Row = 4; bgFreqSide.Layout.Column = [5 6];
        rSingle = uiradiobutton(bgFreqSide,'Text','单边','Tag','single', 'Position', [10 6 120 20]);
        rDouble = uiradiobutton(bgFreqSide,'Text','双边','Tag','double', 'Position', [120 6 120 20]);
        if strcmpi(handles.plotSettings.specFreqSide,'double'), bgFreqSide.SelectedObject = rDouble; else; bgFreqSide.SelectedObject = rSingle; end
    
        % 5行: 幅值模式 和 归一化幅值
        lbl5 = uilabel(gl_pm,'Text','频谱幅值模式：','FontWeight','bold'); lbl5.Layout.Row = 5; lbl5.Layout.Column = 1;
        bgMagMode = uibuttongroup(gl_pm); bgMagMode.Layout.Row = 5; bgMagMode.Layout.Column = [2 3];
        rDb = uiradiobutton(bgMagMode,'Text','dB','Tag','dB', 'Position', [10 6 120 20]);
        rLinear = uiradiobutton(bgMagMode,'Text','线性','Tag','linear', 'Position', [120 6 120 20]);
        if strcmpi(handles.plotSettings.specMagMode,'linear'), bgMagMode.SelectedObject = rLinear; else; bgMagMode.SelectedObject = rDb; end
    
        lbl6 = uilabel(gl_pm,'Text','频谱归一化幅值：','FontWeight','bold'); lbl6.Layout.Row = 5; lbl6.Layout.Column = 4;
        bgMagNorm = uibuttongroup(gl_pm); bgMagNorm.Layout.Row = 5; bgMagNorm.Layout.Column = [5 6];
        rMagYes = uiradiobutton(bgMagNorm,'Text','归一化','Tag','yes', 'Position', [10 6 120 20]);
        rMagNo  = uiradiobutton(bgMagNorm,'Text','非归一化','Tag','no', 'Position', [120 6 120 20]);
        if handles.plotSettings.specMagNormalized, bgMagNorm.SelectedObject = rMagYes; else; bgMagNorm.SelectedObject = rMagNo; end
    
        % 6行: 滤波器频谱分析点数（数值输入）
        lbl7 = uilabel(gl_pm,'Text','滤波器频谱分析点数：','FontWeight','bold'); lbl7.Layout.Row = 6; lbl7.Layout.Column = 1;
        edtNFFT = uieditfield(gl_pm,'numeric','Value',handles.plotSettings.filterSpecNFFT,'Limits',[1 1048576],'RoundFractionalValues','on');
        edtNFFT.Layout.Row = 6; edtNFFT.Layout.Column = [2 3];
    
        % 7行: 应用 / 取消
        btnApply = uibutton(gl_pm,'push','Text','应用','ButtonPushedFcn',@onApplyPlotSettings);
        btnApply.Layout.Row = 7; btnApply.Layout.Column = [1 3];
        btnCancel = uibutton(gl_pm,'push','Text','取消','ButtonPushedFcn',@(src,event) close(dlg_pm));
        btnCancel.Layout.Row = 7; btnCancel.Layout.Column = [4 6];
    
        uiwait(dlg_pm)

        % 内部回调：应用设置
        function onApplyPlotSettings(~,~)
            % 读取各项设置并写回 handles.plotSettings
            try
                % 绘图模式
                if isvalid(bgPlotMode) && ~isempty(bgPlotMode.SelectedObject)
                    handles.plotSettings.signalPlotMode = bgPlotMode.SelectedObject.Tag;
                else
                    handles.plotSettings.signalPlotMode = 'plot';
                end
                % 频谱频率归一化
                handles.plotSettings.specFreqNormalized = strcmp(bgFreqNorm.SelectedObject.Tag,'yes');
                % 频率刻度
                handles.plotSettings.specFreqScale = bgFreqScale.SelectedObject.Tag;
                % 频率范围 单边/双边
                handles.plotSettings.specFreqSide = bgFreqSide.SelectedObject.Tag;
                % 幅值模式
                handles.plotSettings.specMagMode = bgMagMode.SelectedObject.Tag;
                % 幅值归一化
                handles.plotSettings.specMagNormalized = strcmp(bgMagNorm.SelectedObject.Tag,'yes');
                % nfft
                valn = round(edtNFFT.Value);
                if isempty(valn) || ~isfinite(valn) || valn<1, valn = 8192; end
                handles.plotSettings.filterSpecNFFT = valn;
    
                % 应用到绘图：先更新主绘图
                updatePlotsAndAnalysis(S, handles);
                updatePlotSettingsOnly(S, handles); % 滤波后专用切换（保持原逻辑）
                % 如果比较窗口存在，更新
                if isprop(handles,'figCompare') && ~isempty(handles.figCompare) && isvalid(handles.figCompare)
                    onShowCompare([],[]);
                end
    
                % 结束 uiwait 并关闭对话框
                try
                    if isvalid(dlg_pm)
                        uiresume(dlg_pm); 
                        delete(dlg_pm); 
                    end
                catch
                    try delete(dlg_pm); catch; end
                end
                setStatus(handles,'绘图设置已应用。');
    
            catch ME
                % 出错时给出提示但不阻止关闭
                warning('applyPlotSettingsFail:ApplyPlotSettingsFail','应用绘图设置失败：%s', ME.message);
                setStatus(handles,['应用绘图设置失败：', ME.message]);
                % 结束 uiwait 并关闭对话框
                try
                    if isvalid(dlg_pm)
                        uiresume(dlg_pm); 
                        delete(dlg_pm); 
                    end
                catch
                    try delete(dlg_pm); catch; end
                end
            end
        end
    
    end

    %% ---- 绘图与分析 ----
    function updatePlotsAndAnalysis(S, handles)
    % 传入的 handle类 S, handles
    % 对 S 的对象内容有 "读/写" 操作
    % 对 handles 的对象内容有 "读" 操作，无 "写" 操作

    % updatePlotsAndAnalysis  更新界面上的时域/频谱/滤波器响应等图形与注记
    % 将绘图部分根据 handles.plotSettings 系统化重构。

        % 原始/加噪：时域 和 频谱绘图
        axOrigT = handles.axOrigTime; 
        axOrigS = handles.axOrigSpec; 
        
        % 滤波后：时域 和 频谱绘图
        axFiltT = handles.axFiltTime;
        axFiltS = handles.axFiltSpec;

        % 先清理轴
        cla(axOrigT); cla(axOrigS);   

        % 检查音频数据
        if isempty(S.currentSignal)
            updateNote(S, handles);
            return;
        end

        % 数据及绘图参数
        fs = S.fs;                            % 采样率
        x_use = S.currentSignal;              % 当前使用的信号(未加噪的原始信号；若有加噪，加噪的信号存放在 S.noisy）
        plotSettings = handles.plotSettings;  % 获取绘图参数

        % --- 确定时间维 tdim（优先使用 S.timeDim） ---
        tdim = [];
        useTimeDim = false;
        if  ~isempty(S.timeDim) && S.timeDim==round(S.timeDim) && S.timeDim>=1
            tdim = S.timeDim;
            useTimeDim = true;
        else
            szx = size(x_use);
            tdim = find(szx~=1,1,'first');
            if ~isempty(tdim) && tdim>=1
                useTimeDim = true;
            else
                tdim = 1; % fallback
            end
        end
    
        % 处理数据中 NaN/Inf 等非有限数值
        x_use = fillNonfinite(x_use, tdim);
    
    
        % --- 将数据转换为 [N x channels] 格式（使用 to2DtimeMajor） ---
        try
            [X2, restoreX] = to2DtimeMajor(x_use, tdim, false); % 非严格模式
        catch ME
            error('updatePlotsAndAnalysis:to2Dfail','to2DtimeMajor failed, falling back to column vector: %s', ME.message);
        end
        N = size(X2,1);
        channels = size(X2,2);
        t = (0:N-1)/fs;
    
        % 绘图通道上限（避免过多曲线造成拥挤）
        maxPlotChannels = 8;
        plotChannels = 1:min(channels, maxPlotChannels);
    
        % 复数信号取幅度显示
        if ~isreal(X2)
            plotData = abs(X2);
            plotYLabel = '|y| (复数信号幅度)';
            plotAbsY = true;
        else
            plotData = X2;
            plotYLabel = '振幅';
            plotAbsY = false;
        end
    
        % ======================================= 绘制原始/加噪：时域波形 =======================================
        try
            if ~isempty(S.noisy)
                % 将 noisy 转为 [Nn x channels_n]
                [Xn2, restoreN] = to2DtimeMajor(S.noisy, tdim, false);
                Xn2 = fillNonfinite(Xn2, 1);
                Nn = size(Xn2,1);
                tn = (0:Nn-1)/fs;
                if plotAbsY
                    plotDataNoisy = abs(Xn2);
                else
                    plotDataNoisy = Xn2;
                end
    
                % 使用统一的绘图函数
                plotTimeWave(axOrigT, t, plotData, plotSettings, plotChannels, '原始');
                % 叠加带噪（使用虚线）
                axes(axOrigT);
                hold(axOrigT,'on');
                if strcmpi(plotSettings.signalPlotMode,'stem')
                    stem(axOrigT, tn, plotDataNoisy(:, min(size(plotDataNoisy,2),plotChannels)), '--','filled','Marker','o','MarkerSize',3);
                else
                    plot(axOrigT, tn, plotDataNoisy(:, min(size(plotDataNoisy,2),plotChannels)), '--');
                end
                % 构造 legend
                leg1 = arrayfun(@(c) sprintf('原始-ch%d',c), plotChannels, 'uni', false);
                leg2 = arrayfun(@(c) sprintf('带噪-ch%d',c), plotChannels, 'uni', false);
                legend(axOrigT, [leg1, leg2], 'Interpreter','none');
                hold(axOrigT,'off');
            else
                % 未加噪，直接绘制原始信号
                plotTimeWave(axOrigT, t, plotData, plotSettings, plotChannels, '原始');
            end
            title(axOrigT,'原始/加噪：时域波形');
            xlabel(axOrigT,'时间 (s)'); 
            ylabel(axOrigT,plotYLabel);
            grid(axOrigT,'on');
        catch ME
            setStatus(handles,['绘制原始/加噪时域波形出错：' ME.message]);
            fprintf('绘制原始/加噪时域波形出错：%s \n', ME.message);
        end
    
        % ======================================= 原始/加噪：频谱 (dB or linear) =================================
        % --------------------------- 原始信号频谱 ---------------------------
        try
            % 原始信号频谱
            [freq, mag] = computeSpecForPlot(X2, fs, plotSettings);
            plotSpectrum(axOrigS, freq, mag, plotSettings, plotChannels, '原始');
    
            % 设置 xlim（按归一化与单/双边）
            if plotSettings.specFreqNormalized
                if strcmpi(plotSettings.specFreqSide,'double')
                    xlim(axOrigS, [0, 2]);
                else
                    xlim(axOrigS, [0, 1]);
                end
            else
                if strcmpi(plotSettings.specFreqSide,'double')
                    xlim(axOrigS, [0, fs]);
                else
                    xlim(axOrigS, [0, fs/2]);
                end
            end
        catch ME
            setStatus(handles,['绘制原始频谱 出错：' ME.message]);
            fprintf('调试点62_2：绘制原始频谱 出错：%s \n', ME.message);
        end
    
        % --------------------------- 若存在带噪频谱，则叠加 ---------------------------
        if ~isempty(S.noisy)
            try
                [Xn2, ~] = to2DtimeMajor(S.noisy, tdim, false);
                Xn2 = fillNonfinite(Xn2,1);
                [freqN, magN] = computeSpecForPlot(Xn2, fs, plotSettings);
                axes(axOrigS);
                hold(axOrigS,'on');
                % 绘制带噪（虚线）
                if strcmpi(plotSettings.specFreqScale,'log')
                    % 保证无 0 点
                    freqPlot = freqN;
                    if any(freqPlot==0)
                        idx0 = freqPlot==0;
                        freqPlot(idx0) = []; magN(idx0,:) = [];
                    end
                    if strcmpi(plotSettings.signalPlotMode,'stem')
                        stem(axOrigS, freqPlot, magN(:, min(size(magN,2),plotChannels)), '--','filled','Marker','o','MarkerSize',3);
                    else
                        plot(axOrigS, freqPlot, magN(:, min(size(magN,2),plotChannels)), '--');
                    end
                    set(axOrigS,'XScale','log');
                else
                    if strcmpi(plotSettings.signalPlotMode,'stem')
                        stem(axOrigS, freqN, magN(:, min(size(magN,2),plotChannels)), '--','filled','Marker','o','MarkerSize',3);
                    else
                        plot(axOrigS, freqN, magN(:, min(size(magN,2),plotChannels)), '--');
                    end
                    set(axOrigS,'XScale','linear');
                end
                % 更新 legend：把带噪放在后面
                leg1 = arrayfun(@(c) sprintf('原始-ch%d',c), plotChannels, 'uni', false);
                leg2 = arrayfun(@(c) sprintf('带噪-ch%d',c), plotChannels, 'uni', false);
                legend(axOrigS, [leg1, leg2], 'Interpreter','none');
                hold(axOrigS,'off');
            catch ME
                setStatus(handles,['绘制原始/加噪频谱出错：' ME.message]);
                fprintf('调试点62_3：绘制原始/加噪频谱出错：%s \n', ME.message);
            end
        end
    
        % ======================================= 滤波后 时域 与 频谱（S.filtered） =======================================
        if isempty(S.filtered)
            cla(axFiltT);
            title(axFiltT, '滤波后：时域波形');
            text(axFiltT, 0.5, 0.5, '未应用滤波器', 'HorizontalAlignment', 'center');
    
            cla(axFiltS);
            title(axFiltS, '滤波后：频谱');
            text(axFiltS, 0.5, 0.5, '未应用滤波器', 'HorizontalAlignment', 'center');
        end
    
        if ~isempty(S.filtered)
            % y 可能为任意维度
            [Y2, restoreY] = to2DtimeMajor(S.filtered, tdim, false);
            Y2 = fillNonfinite(Y2,1);
    
            % continue 基准模式（临时显示，不入历史）
            if isprop(S,'continueFilterMode') && S.continueFilterMode
                S.continueTempLatest = S.filtered;
                % 删除之前临时绘图
                try delete(findobj(axFiltT, '-regexp', 'Tag', '^continueTemp$'));catch; end
                try delete(findobj(axFiltS, '-regexp', 'Tag', '^continueTemp$'));catch; end
    
                try
                    % 删除之前保存的临时句柄
                    try
                        if ~isempty(S.continueTempHandleTime) && isvalid(S.continueTempHandleTime)
                            delete(S.continueTempHandleTime);
                        end
                        if ~isempty(S.continueTempHandleSpec) && isvalid(S.continueTempHandleSpec)
                            delete(S.continueTempHandleSpec);
                        end
                    catch
                    end
    
                    % --------------------------- 时域 - 临时（保留历史） ---------------------------
                    t_y = (0:size(Y2,1)-1)/fs;
                    axes(axFiltT); 
                    hold(axFiltT,'on');
                    if ~isreal(Y2)
                        plotDataY = abs(Y2);
                    else
                        plotDataY = Y2;
                    end
    
                    if strcmpi(plotSettings.signalPlotMode, 'stem')
                        hTimeTmp = stem(axFiltT, t_y, plotDataY(:,plotChannels), 'filled','Marker','o','MarkerSize',3);
                    else
                        hTimeTmp = plot(axFiltT, t_y, plotDataY(:,plotChannels));
                    end
                    % 设置 Tag 与 DisplayName（多个 handle 时设相同 Tag/DisplayName）
                    set(hTimeTmp, 'Tag', 'continueTemp');
                    % DisplayName 用单一名字（图例会合并多条曲线）
                    for k = 1:numel(hTimeTmp)
                        set(hTimeTmp(k), 'DisplayName', sprintf('第%d次滤波 (临时)-ch%d', S.continueBaseIndex+1, plotChannels(min(k,numel(plotChannels)))));
                    end
                    S.continueTempHandleTime = hTimeTmp;
    

                    % --------------------------- 频域 - 临时（用 computeSpecForPlot） ---------------------------
                    [freq_tmp, mag_tmp] = computeSpecForPlot(Y2, fs, plotSettings);
                    axes(axFiltS);
                    hold(axFiltS,'on');
                    if strcmpi(plotSettings.specFreqScale,'log')
                        % 保证无 0 点
                        freqPlot = freq_tmp;
                        if any(freqPlot==0)
                            idx0 = freqPlot==0;
                            freqPlot(idx0) = []; mag_tmp(idx0,:) = [];
                        end
                    
                        if strcmpi(plotSettings.signalPlotMode, 'stem')
                            hSpecTmp = stem(axFiltS, freqPlot, mag_tmp(:,plotChannels), 'filled','Marker','o','MarkerSize',3);
                        else
                            hSpecTmp = plot(axFiltS, freqPlot, mag_tmp(:,plotChannels));
                        end
                        set(hSpecTmp, 'Tag', 'continueTemp');
                        set(axFiltS,'XScale','log');
                    else
                        if strcmpi(plotSettings.signalPlotMode, 'stem')
                            hSpecTmp = stem(axFiltS, freq_tmp, mag_tmp(:,plotChannels), 'filled','Marker','o','MarkerSize',3);
                        else
                            hSpecTmp = plot(axFiltS, freq_tmp, mag_tmp(:,plotChannels));
                        end
                        set(hSpecTmp, 'Tag', 'continueTemp');
                        set(axFiltS,'XScale','linear');
                    end
                    for k = 1:numel(hSpecTmp)
                        set(hSpecTmp(k), 'DisplayName', sprintf('第%d次滤波 (临时)-ch%d', S.continueBaseIndex+1, plotChannels(min(k,numel(plotChannels)))));
                    end
                    S.continueTempHandleSpec = hSpecTmp;
    
                    % --------------------------- 更新 legend 并刷新 ---------------------------
                    updateFilteredLegends(S, axFiltT, axFiltS);
                    drawnow; pause(0.01);

                catch ME
                    setStatus(handles,['绘制滤波后图像出错（继续基准临时路径）：' ME.message]);
                    fprintf('调试点62：绘制滤波后图像出错（继续基准临时路径）\n');
                end
    
                updateContinueButtonEnable(S, handles);
                setStatus(handles,'已应用滤波（继续基准模式下的临时结果，仅显示最新临时）。');
    
            else
                % 非 continue：把此次结果作为唯一历史（覆盖旧历史）
                S.filteredHistory = { S.filtered }; % 原始对象保留
                S.filterHistory = { struct('b', S.filter_b, 'a', S.filter_a) };
    
                % 清除 continue 状态
                S.continueFilterCount = 0;
                S.continueFilterMode = false;
                S.continueFilterPending = false;
                S.continueFilterBase = [];
                S.continueTempLatest = [];
                S.continueBaseIndex = 0;
    
                % 清除滤波后绘图
                try
                    cla(axFiltT); cla(axFiltS);
                catch
                end
    
                try
                    % --------------------------- 非 continue 滤波后：时域 ---------------------------
                    t_y = (0:size(Y2,1)-1)/fs;
                    axes(axFiltT);
                    if ~isreal(Y2)
                        plotDataY = abs(Y2); 
                        plotYLabel2 = '|y| (复数信号幅度)';
                    else
                        plotDataY = Y2; 
                        plotYLabel2 = '振幅';
                    end
    
                    if strcmpi(plotSettings.signalPlotMode, 'stem')
                        hTime = stem(axFiltT, t_y, plotDataY(:,plotChannels), 'filled','Marker','o','MarkerSize',3);
                    else
                        hTime = plot(axFiltT, t_y, plotDataY(:,plotChannels));
                    end
                    % 为每条曲线设置 DisplayName（用于 legend）
                    for k = 1:numel(hTime)
                        set(hTime(k), 'DisplayName', sprintf('第%d次滤波-ch%d', 1, plotChannels(min(k,numel(plotChannels)))));
                    end
                    grid(axFiltT,'on');
                    title(axFiltT,'滤波后：时域波形');
                    xlabel(axFiltT,'时间 (s)');
                    ylabel(axFiltT,plotYLabel2);
    
                    % --------------------------- 非 continue 滤波后：频域 ---------------------------
                    [freq, mag] = computeSpecForPlot(Y2, fs, plotSettings);
                    axes(axFiltS);
                    if strcmpi(plotSettings.specFreqScale,'log')
                        % 保证无 0 点
                        freqPlot = freq;
                        if any(freqPlot==0)
                            idx0 = freqPlot==0;
                            freqPlot(idx0) = []; mag(idx0,:) = [];
                        end
                    
                        if strcmpi(plotSettings.signalPlotMode, 'stem')
                            hSpec = stem(axFiltS, freqPlot, mag(:,plotChannels), 'filled','Marker','o','MarkerSize',3);
                        else
                            hSpec = plot(axFiltS, freqPlot, mag(:,plotChannels));
                        end
                        set(axFiltS,'XScale','log');
                    else
                        if strcmpi(plotSettings.signalPlotMode, 'stem')
                            hSpec = stem(axFiltS, freq, mag(:,plotChannels), 'filled','Marker','o','MarkerSize',3);
                        else
                            hSpec = plot(axFiltS, freq, mag(:,plotChannels));
                        end
                        set(axFiltS,'XScale','linear');
                    end

                    for k = 1:numel(hSpec)
                        set(hSpec(k), 'DisplayName', sprintf('第%d次滤波-ch%d', 1, plotChannels(min(k,numel(plotChannels)))));
                    end

                    grid(axFiltS,'on'); 
                    title(axFiltS, sprintf('滤波后：频谱 (%s)', plotSettings.specMagMode));
                    xlabel(axFiltS, getSpecXLabel(plotSettings));
                    ylabel(axFiltS, getSpecYLabel(plotSettings));

                    if plotSettings.specFreqNormalized
                        if strcmpi(plotSettings.specFreqSide,'double')
                            xlim(axFiltS, [0,2]);
                        else
                            xlim(axFiltS, [0,1]);
                        end
                    else
                        if strcmpi(plotSettings.specFreqSide,'double')
                            xlim(axFiltS, [0,fs]);
                        else
                            xlim(axFiltS, [0,fs/2]);
                        end
                    end
    
                    % 保存句柄到 S（覆盖旧的 history）
                    S.filteredPlotHandlesTime = { hTime };
                    S.filteredPlotHandlesSpec = { hSpec };
    
                    % 更新 legend
                    updateFilteredLegends(S, axFiltT, axFiltS);
    
                catch ME
                    setStatus(handles,['绘制滤波后图像出错（非继续路径）：' ME.message]);
                    fprintf('调试点63：绘制滤波后图像出错（非继续路径）\n');
                end
    
                updateContinueButtonEnable(S, handles);
                setStatus(handles,'已应用滤波（非继续模式），已清除之前滤波后图像，仅显示本次结果。');

            end
        end
    
        % ======================================= 绘制滤波器 幅频 和 相频 特性 =======================================
        updateFilterResponsePlots(S, handles);
        
        % ========== 更新备注与状态 ==========
        drawnow; pause(0.01);
        updateNote(S, handles);
        setStatus(handles,'绘图与分析已更新。');
    end
    
    %% ===== 绘图辅助函数 =====
    function [freq, mag] = computeSpecForPlot(X, fs_local, settings)
    % X: N x channels (时域)
    % settings: handles.plotSettings
    % 返回 freq (M x 1) 和 mag (M x channels)
        if isempty(X)
            freq = [];
            mag = [];
            return;
        end
        N = size(X,1);
        nfft = 2^nextpow2(N);
        nfft = max(nfft,1);
        Xf = fft(X, nfft);
        % 单/双边
        if strcmpi(settings.specFreqSide,'double')
            freq = makeFreqVector(nfft, fs_local, settings.specFreqNormalized, 'double');
            magRaw = abs(Xf);
        else
            freq = makeFreqVector(nfft, fs_local, settings.specFreqNormalized, 'single');
            magRaw = abs(Xf(1:floor(nfft/2),:));
        end
    
        % 幅值模式
        if strcmpi(settings.specMagMode,'dB')
            mag = 20*log10(magRaw + eps);
        else
            mag = magRaw;
        end
    
        if isfield(settings,'specMagNormalized') && settings.specMagNormalized
            % 按列归一化
            mv = max(mag,[],1);
            mv(mv==0) = 1;
            mag = bsxfun(@rdivide, mag, mv);
        end
    end
    
    function freq = makeFreqVector(nfft, fs_local, normalized, side)
    % makeFreqVector  构造频率向量
    % side: 'single' 或 'double'
        if nargin < 3, normalized = false; end
        if nargin < 4, side = 'single'; end
    
        if normalized
            Fs_val = 2; % 2*pi*f/fs；横坐标为归一化频率 (xπ rad/sample)
        else
            Fs_val = fs_local;
        end
    
        if strcmpi(side,'double')
            freq = (0:nfft-1)' * (Fs_val / nfft);
        else
            freq = (0:floor(nfft/2)-1)' * (Fs_val / nfft);
        end
    end
    
    function plotTimeWave(ax, tvec, data, settings, plotChannels, namePrefix)
    % plotTimeWave  在 ax 上绘制时域波形（支持 plot 或 stem）
    % data: N x channels
        axes(ax); hold(ax,'off');
        mode = settings.signalPlotMode;
        if strcmpi(mode,'stem')
            h = stem(ax, tvec, data(:,plotChannels), 'filled', 'Marker','o','MarkerSize',3);
        else
            h = plot(ax, tvec, data(:,plotChannels));
        end
        % DisplayName
        for k = 1:numel(h)
            try set(h(k),'DisplayName', sprintf('%s-ch%d', namePrefix, plotChannels(min(k,numel(plotChannels))))); catch; end
        end
        legend(ax,'show','Interpreter','none');
        grid(ax,'on');
    end
    
    function h = plotSpectrum(ax, freq, mag, settings, plotChannels, namePrefix, clearFirst)
    % plotSpectrum  在 ax 上绘制频谱（考虑线性/对数 x 轴与 plot/stem）
    % 返回句柄数组 h（可能为空）
    % clearFirst (optional, default true): 若 false 则不清除轴，便于叠加多次绘制
        if nargin < 7, clearFirst = true; end
        axes(ax);
        if clearFirst
            hold(ax,'off');
        end
        if isempty(freq) || isempty(mag)
            if clearFirst
                cla(ax);
                text(ax, 0.5, 0.5, '无频谱数据', 'HorizontalAlignment','center');
            end
            h = gobjects(0);
            return;
        end
    
        % 选择绘制通道索引（如果 mag 列少于 plotChannels，会自动截断）
        maxCh = size(mag,2);
        plotIdx = plotChannels(plotChannels <= maxCh);
        if isempty(plotIdx)
            h = gobjects(0);
            return;
        end
    
        % 绘制（考虑对数 x 轴）
        isLog = isfield(settings,'specFreqScale') && strcmpi(settings.specFreqScale,'log');
        if isLog
            % 去掉 0 频点
            freqPlot = freq;
            magPlot = mag;
            if any(freqPlot==0)
                idx0 = freqPlot==0;
                freqPlot(idx0) = [];
                magPlot(idx0,:) = [];
            end
            if isfield(settings,'signalPlotMode') && strcmpi(settings.signalPlotMode,'stem')
                h = stem(ax, freqPlot, magPlot(:,plotIdx), 'filled','Marker','o','MarkerSize',3);
            else
                h = plot(ax, freqPlot, magPlot(:,plotIdx));
            end
            set(ax,'XScale','log');
        else
            if isfield(settings,'signalPlotMode') && strcmpi(settings.signalPlotMode,'stem')
                h = stem(ax, freq, mag(:,plotIdx), 'filled','Marker','o','MarkerSize',3);
            else
                h = plot(ax, freq, mag(:,plotIdx));
            end
            set(ax,'XScale','linear');
        end
    
        xlabel(ax, getSpecXLabel(settings));
        ylabel(ax, getSpecYLabel(settings));
        title(ax, sprintf('%s：频谱 (%s)', namePrefix, settings.specMagMode));
    
        % DisplayName
        for k = 1:numel(h)
            try
                chIdx = plotIdx(min(k,numel(plotIdx)));
                set(h(k),'DisplayName', sprintf('%s-ch%d', namePrefix, chIdx));
            catch
            end
        end
    
        % 如果 clearFirst 为 true，我们显示 legend；若为 false 则保留外部最终调用者来做 legend 汇总
        if clearFirst
            legend(ax,'show','Interpreter','none');
        end
        grid(ax,'on');
    end


    function xl = getSpecXLabel(settings)
        isFreqNormalized = isfield(settings,'specFreqNormalized') && settings.specFreqNormalized;
        isFreqLog = isfield(settings,'specFreqScale') && strcmpi(settings.specFreqScale,'log');
        if isFreqNormalized
            if isFreqLog
                xl = '归一化频率 (xπ rad/sample, 对数刻度)';
            else
                xl = '归一化频率 (xπ rad/sample)';
            end
        else
            if isFreqLog
                xl = '频率 (Hz, 对数刻度)';
            else
                xl = '频率 (Hz)';
            end
        end
    end
    
    function yl = getSpecYLabel(settings)
        isMagDB = isfield(settings, 'specMagMode') && strcmpi(settings.specMagMode, 'dB');
        isMagNormalized = isfield(settings, 'specMagNormalized') && settings.specMagNormalized;
        if isMagNormalized
            if isMagDB
                yl = '归一化幅值 (dB)';
            else
                yl = '归一化幅值 (linear)';
            end
        else
            if isMagDB
                yl = '幅值 (dB)';
            else
                yl = '幅值 (linear)';
            end
        end
    end

    %% ---- 更新滤波器响应绘图 ---- 
    function updateFilterResponsePlots(S, handles)
    % 传入的 handle类 S, handles
    % 对 S 的对象内容有 "读" 操作，无 "写" 操作
    % 对 handles 的对象内容有 "读/写" 操作

        fs = S.fs;                            % 采样率
        plotSettings = handles.plotSettings;  % 获取绘图参数
        axFilterR = handles.axFilterResp; 
        axFilterP = handles.axFilterPhase;
        cla(axFilterR);
        cla(axFilterP);
        
        if isempty(S.filter_b) || isempty(S.filter_a)
            cla(axFilterR); title(axFilterR,'滤波器幅频特性');
            text(axFilterR, 0.5, 0.5, '未设计滤波器', 'HorizontalAlignment', 'center');
            
            cla(axFilterP); title(axFilterP,'滤波器相频特性');
            text(axFilterP, 0.5, 0.5, '未设计滤波器', 'HorizontalAlignment', 'center');
            return;
        end

        nfft_filt = max(1, plotSettings.filterSpecNFFT);
        % 使用 freqz 返回的频率向量 w（单位 Hz，当传入 fs 时）
        if strcmp(plotSettings.specFreqSide, 'double')
            [H,w] = freqz(S.filter_b, S.filter_a, nfft_filt, 'whole', fs);
        else
            [H,w] = freqz(S.filter_b, S.filter_a, nfft_filt, fs);
        end

        % 归一化频率（如果选了归一化显示）
        if isfield(plotSettings,'specFreqNormalized') && plotSettings.specFreqNormalized
            w = w / fs *2; % 2*pi*f/fs；横坐标为归一化频率 (xπ rad/sample)
        end

        % --------------------------- 幅频特性 ---------------------------
        try
            H_Res = H;
            w_Res = w;
            % 计算幅值并按模式处理
            if strcmpi(plotSettings.specMagMode,'dB')
                mag_plot = 20*log10(abs(H_Res) + eps);
            else
                mag_plot = abs(H_Res);
            end
    
            % 归一化幅值
            if isfield(plotSettings,'specMagNormalized') && plotSettings.specMagNormalized
                mv = max(mag_plot(:));
                if mv ~= 0
                    mag_plot = mag_plot / mv;
                end
            end
    
            % 绘图：处理 log 轴
            axes(axFilterR);
            if strcmpi(plotSettings.specFreqScale,'log')
                % 去掉 0 频点以避免 log(0)
                if any(w_Res==0)
                    idx0 = w_Res==0;
                    w_Res(idx0) = [];
                    mag_plot(idx0,:) = [];
                end 
                plot(axFilterR, w_Res, mag_plot); 
                set(axFilterR,'XScale','log');
            else
                plot(axFilterR, w_Res, mag_plot);
                set(axFilterR,'XScale','linear');
            end
    
            grid(axFilterR,'on'); title(axFilterR,'滤波器幅频特性');
            xlabel(axFilterR, getSpecXLabel(plotSettings));
            ylabel(axFilterR, getSpecYLabel(plotSettings));
            % xlim 根据归一化与单/双边设置
            if plotSettings.specFreqNormalized
                if strcmpi(plotSettings.specFreqSide,'double'), xlim(axFilterR,[0,2]); else; xlim(axFilterR,[0,1]); end
            else
                if strcmpi(plotSettings.specFreqSide,'double'), xlim(axFilterR,[0,fs]); else; xlim(axFilterR,[0,fs/2]); end
            end
        catch ME
            fprintf('调试点71：滤波器幅频特性响应计算错误: %s\n', ME.message);
            % 不再抛出，让 UI 继续工作，并显示占位
            cla(axFilterR);
            title(axFilterR, '滤波器幅频特性');
            text(axFilterR, 0.5, 0.5, '幅频响应计算错误', 'HorizontalAlignment', 'center');
        end
        
        % --------------------------- 相频特性 ---------------------------
        try
            H_Pha = H;
            w_Pha = w;
            % 相位 rad
            phase = unwrap(angle(H_Pha));

            % 绘图：处理 log 轴
            axes(axFilterP);
            if strcmpi(plotSettings.specFreqScale,'log')
                % 去掉 0 频点以避免 log(0)
                if any(w_Pha==0)
                    idx0 = w_Pha==0;
                    w_Pha(idx0) = [];
                    phase(idx0,:) = [];
                end 
                plot(axFilterP, w_Pha, phase);
                set(axFilterP,'XScale','log');
            else
                plot(axFilterP, w_Pha, phase);
                set(axFilterP,'XScale','linear');
            end
            grid(axFilterP,'on');
            title(axFilterP, '滤波器相频特性');
            xlabel(axFilterP, getSpecXLabel(plotSettings));
            ylabel(axFilterP, '相位 (rad)');
            if plotSettings.specFreqNormalized
                if strcmpi(plotSettings.specFreqSide,'double'), xlim(axFilterP,[0,2]); else; xlim(axFilterP,[0,1]); end
            else
                if strcmpi(plotSettings.specFreqSide,'double'), xlim(axFilterP,[0,fs]); else; xlim(axFilterP,[0,fs/2]); end
            end
        catch ME
            cla(axFilterP);
            title(axFilterP, '滤波器相频特性');
            text(axFilterP, 0.5, 0.5, '相位响应计算错误', 'HorizontalAlignment', 'center');
            fprintf('调试点72：滤波器相频特性，相位响应计算错误: %s\n', ME.message);
        end
 
    end

    %% ---- "显示比较图（新窗口）"按钮回调：信号处理前后时域、频域图形比较 ---- 
    function onShowCompare(~,~)
        % 打开比较图窗口
        showCompareFigure(S, handles, fig_GUI);
    end

    %% ---- 比较图：信号处理前后时域、频域图形比较 ---- 
    function showCompareFigure(S, handles, fig_GUI, isCompareVisible)
        if nargin < 4, isCompareVisible = true; end
        if isCompareVisible
            compareVisible = 'on';
        else
            compareVisible = 'off';
        end

        % 获取当前绘图设置
        plotSettings = handles.plotSettings;
    
        % 检查原始信号存在
        if isempty(S.currentSignal)
            uialert_safe(fig_GUI,'比较图需要原始信号。','提示');
            setStatus(handles,'无法显示比较图：缺少原始信号');
            fprintf('调试点78：无法显示比较图：缺少原始信号\n');
            return;
        end
    
        % 确定时间维 tdim（优先 S.timeDim，否则从数据推断）
        if  ~isempty(S.timeDim) && S.timeDim==round(S.timeDim) && S.timeDim>=1
            tdim = S.timeDim;
            useTimeDim = true;
        else
            % 尝试从已有数据推断时间维：优先 S.currentSignal, S.filtered, S.filteredHistory{end}
            template = [];
            if isprop(S,'currentSignal') && ~isempty(S.currentSignal)
                template = S.currentSignal;
            elseif isprop(S,'filtered') && ~isempty(S.filtered)
                template = S.filtered;
            elseif isprop(S,'filteredHistory') && ~isempty(S.filteredHistory)
                template = S.filteredHistory{end};
            end
            if ~isempty(template)
                tdim = find(size(template)~=1,1,'first');
                if ~isempty(tdim) && tdim>=1
                    useTimeDim = true;
                end
            else
                tdim = 1; useTimeDim = false;
            end
        end
    
        % 准备滤波历史：优先使用 S.filteredHistory（多个），若为空则退回到单次 S.filtered
        if isempty(S.filteredHistory)
            if ~isempty(S.filtered)
                filtList = { S.filtered };
            else
                uialert_safe(fig_GUI,'比较图需要至少一次滤波结果。','提示');
                setStatus(handles,'无法显示比较图：缺少滤波结果');
                fprintf('调试点79：无法显示比较图：缺少滤波结果\n');
                return;
            end
        else
            filtList = S.filteredHistory; % cell array
        end
    
        % 基准 base -> 转为 [N x channels]
        [base2, baseRestore] = to2DtimeMajor(S.currentSignal, tdim, false);
        
        % 处理数据中Nan/Inf等非有限数值
        base2 = fillNonfinite(base2,1);
    
        % 控制一次性绘制的通道数（避免界面拥挤）
        maxPlotChannels = 4; % 可调整或暴露为 GUI 控件
        nBaseChan = size(base2,2);
        plotBaseCh = 1:min(nBaseChan, maxPlotChannels);
    
        % 以 base 的第一维长度作为参考长度
        L_base = size(base2,1);
    
        % 检查并创建/重用比较窗口与子图句柄
        if isempty(handles.figCompare) || ~isvalid(handles.figCompare)
            handles.figCompare = createCenteredFigure('Name','信号比较分析','NumberTitle','off', 'Position', [100, 100, 1200, 800], 'Visible', compareVisible);
            % 创建子图并保存句柄
            handles.axCompare1 = subplot(2,2,1);
            handles.axCompare2 = subplot(2,2,2);
            handles.axCompare3 = subplot(2,2,3);
            handles.axCompare4 = subplot(2,2,4);
            % 调整子图间距
            set(handles.axCompare1, 'Position', [0.05, 0.55, 0.4, 0.35]);
            set(handles.axCompare2, 'Position', [0.55, 0.55, 0.4, 0.35]);
            set(handles.axCompare3, 'Position', [0.05, 0.1, 0.4, 0.35]);
            set(handles.axCompare4, 'Position', [0.55, 0.1, 0.4, 0.35]);
        else
            if isCompareVisible
                % 将现有窗口带到前台
                createCenteredFigure(handles.figCompare);
                handles.figCompare.Visible = 'on';
            end
        end
    
        % ============================ 1) 时域比较：base (原始) vs 每一次滤波结果 ============================
        axes(handles.axCompare1);
        cla(handles.axCompare1);
        % 时间向量以 base 长度为准
        tt_base = (0:L_base-1)/S.fs;
        if ~isreal(base2)
            plotData = abs(base2);
            plotYLabel = '|y| (复数信号幅度)';
            plotAbsY = true;
        else
            plotData = base2;
            plotYLabel = '振幅';
            plotAbsY = false;
        end
    
        % 用 plotTimeWave 辅助函数绘制 base（会自动用 plotSettings.signalPlotMode）
        plotTimeWave(handles.axCompare1, tt_base, plotData, plotSettings, plotBaseCh, '原始信号');
    
        legend_entries_time = {};
        for ch = plotBaseCh
            legend_entries_time{end+1} = sprintf('原始信号-ch%d', ch); %#ok<SAGROW>
        end
    
        % 绘制每次滤波结果（按序）；将每个 filtList{k} 转为 [N x channels] 并按通道绘制
        nFilt = numel(filtList);
        hold(handles.axCompare1,'on');
        for k = 1:nFilt
            yk_raw = filtList{k};
            % 处理数据中Nan/Inf等非有限数值
            yk_raw = fillNonfinite(yk_raw,tdim);
            [Yk2, ~] = to2DtimeMajor(yk_raw, tdim, false);
            if plotAbsY
                pdata = abs(Yk2);
            else
                pdata = Yk2;
            end
            for chIdx = 1:min(size(Yk2,2), numel(plotBaseCh))
                ch = chIdx; % match columns: use first columns
                Lk = min(size(Yk2,1), L_base);
                tt_k = (0:Lk-1)/S.fs;
                col = pdata(1:Lk, ch);
                if strcmpi(plotSettings.signalPlotMode,'stem')
                    stem(handles.axCompare1, tt_k, col, 'filled','Marker','o','MarkerSize',3);
                else
                    plot(handles.axCompare1, tt_k, col);
                end
                legend_entries_time{end+1} = sprintf('第%d次滤波-ch%d', k, ch); %#ok<SAGROW>
            end
        end
    
        % 临时结果（若有）
        if isprop(S,'continueTempLatest') && ~isempty(S.continueTempLatest)
            try
                [data2D_tmp, ~] = to2DtimeMajor(S.continueTempLatest, tdim, false);
                data2D_tmp = fillNonfinite(data2D_tmp,1);
                if plotAbsY, pdata = abs(data2D_tmp); else; pdata = data2D_tmp; end
                for ch = 1:min(size(data2D_tmp,2), maxPlotChannels)
                    Ltmp = size(data2D_tmp,1);
                    ttmp = (0:Ltmp-1)/S.fs;
                    col = pdata(:,ch);
                    if strcmpi(plotSettings.signalPlotMode,'stem')
                        stem(handles.axCompare1, ttmp, col, '--','filled','Marker','o','MarkerSize',3);
                    else
                        plot(handles.axCompare1, ttmp, col, '--');
                    end
                    legend_entries_time{end+1} = sprintf('第%d次滤波 (临时)-ch%d', S.continueBaseIndex+1, ch); %#ok<SAGROW>
                end
            catch
            end
        end
    
        hold(handles.axCompare1,'off');
        % 构建时域图例并美化
        if ~isempty(legend_entries_time)
            legend(handles.axCompare1, legend_entries_time, 'Interpreter','none');
        else
            legend(handles.axCompare1, 'off');
        end
        grid(handles.axCompare1,'on');
        title(handles.axCompare1, '时域比较: 原始 vs 每次滤波结果');
        xlabel(handles.axCompare1, '时间 (s)');
        ylabel(handles.axCompare1, plotYLabel);
    
        % =================================== 2) 频域比较：base vs 每一次滤波结果 ===================================
        axes(handles.axCompare2);
        cla(handles.axCompare2);
        % 对 base 计算频谱并作为第一个绘制（clearFirst = true）
        [freq_b, mag_b] = computeSpecForPlot(base2(1:min(end, L_base), :), S.fs, plotSettings);
        plotSpectrum(handles.axCompare2, freq_b, mag_b, plotSettings, plotBaseCh, '原始信号', false);
    
        % 依序绘制 filtList（clearFirst = false -> 叠加）
        hold(handles.axCompare2,'on');
        for k = 1:nFilt
            [Yk2, ~] = to2DtimeMajor(fillNonfinite(filtList{k}, tdim), tdim, false); % 注意调用顺序及 fillNonfinite
            [freq_k, mag_k] = computeSpecForPlot(Yk2(1:min(size(Yk2,1), L_base), :), S.fs, plotSettings);
            plotSpectrum(handles.axCompare2, freq_k, mag_k, plotSettings, plotBaseCh, sprintf('第%d次滤波', k), false);
        end
    
        % 临时（若有）
        if isprop(S,'continueTempLatest') && ~isempty(S.continueTempLatest)
            try
                [data2D_tmp, ~] = to2DtimeMajor(S.continueTempLatest, tdim, false);
                data2D_tmp = fillNonfinite(data2D_tmp,1);
                [freq_t, mag_t] = computeSpecForPlot(data2D_tmp(1:min(size(data2D_tmp,1), L_base), :), S.fs, plotSettings);
                plotSpectrum(handles.axCompare2, freq_t, mag_t, plotSettings, 1:min(size(data2D_tmp,2), maxPlotChannels), ...
                    sprintf('第%d次滤波 (临时)', S.continueBaseIndex+1), false);
            catch
            end
        end
        hold(handles.axCompare2,'off');
    
        % legend 与坐标美化
        try
            legend(handles.axCompare2,'show','Interpreter','none');
        catch
        end
        grid(handles.axCompare2,'on');
        title(handles.axCompare2, '频域比较: 原始 vs 每次滤波结果');
        % 设置 xlim（按归一化与单/双边）
        if plotSettings.specFreqNormalized
            if strcmpi(plotSettings.specFreqSide,'double')
                xlim(handles.axCompare2, [0, 2]);
            else
                xlim(handles.axCompare2, [0, 1]);
            end
        else
            if strcmpi(plotSettings.specFreqSide,'double')
                xlim(handles.axCompare2, [0, S.fs]);
            else
                xlim(handles.axCompare2, [0, S.fs/2]);
            end
        end


        % ================================ 3) 时域比较：若存在加噪信号，绘制 加噪 vs 每次滤波（否则提示） ================================
        axes(handles.axCompare3);
        cla(handles.axCompare3);
        if ~isempty(S.noisy)
            [noisy2, ~] = to2DtimeMajor(S.noisy, tdim, false);
            noisy2 = fillNonfinite(noisy2,1);
            L_noisy = size(noisy2,1);
            plotNoisyCh = 1:min(size(noisy2,2), maxPlotChannels);
            if plotAbsY
                pdata = abs(noisy2);
                plotYLabel2 = '|y| (复数信号幅度)';
            else
                pdata = noisy2;
                plotYLabel2 = '振幅';
            end
    
            plotTimeWave(handles.axCompare3, (0:L_noisy-1)/S.fs, pdata, plotSettings, plotNoisyCh, '加噪信号');
            legend_entries_noisy = {};
            for ch = plotNoisyCh
                legend_entries_noisy{end+1} = sprintf('加噪信号-ch%d', ch); %#ok<SAGROW>
            end
    
            hold(handles.axCompare3,'on');
            for k = 1:nFilt
                [Yk2, ~] = to2DtimeMajor(fillNonfinite(filtList{k}, tdim), tdim, false);
                if plotAbsY
                    pdata_k = abs(Yk2);
                else
                    pdata_k = Yk2;
                end
                for ch = 1:min(size(Yk2,2), numel(plotNoisyCh))
                    Lk = min(size(Yk2,1), L_noisy);
                    tt_k = (0:Lk-1)/S.fs;
                    col = pdata_k(1:Lk, ch);
                    if strcmpi(plotSettings.signalPlotMode,'stem')
                        stem(handles.axCompare3, tt_k, col, 'filled','Marker','o','MarkerSize',3);
                    else
                        plot(handles.axCompare3, tt_k, col);
                    end
                    legend_entries_noisy{end+1} = sprintf('第%d次滤波-ch%d', k, ch); %#ok<SAGROW>
                end
            end
    
            % 临时（若有）
            if isprop(S,'continueTempLatest') && ~isempty(S.continueTempLatest)
                try
                    [data2D_tmp, ~] = to2DtimeMajor(S.continueTempLatest, tdim, false);
                    data2D_tmp = fillNonfinite(data2D_tmp,1);
                    if plotAbsY
                        pdata = abs(data2D_tmp); 
                    else
                        pdata = data2D_tmp; 
                    end
                    for ch = 1:min(size(data2D_tmp,2), maxPlotChannels)
                        Ltmp = size(data2D_tmp,1);
                        ttmp = (0:Ltmp-1)/S.fs;
                        col = pdata(:,ch);
                        if strcmpi(plotSettings.signalPlotMode,'stem')
                            stem(handles.axCompare3, ttmp, col, '--','filled','Marker','o','MarkerSize',3);
                        else
                            plot(handles.axCompare3, ttmp, col, '--');
                        end
                        legend_entries_noisy{end+1} = sprintf('第%d次滤波 (临时)-ch%d', S.continueBaseIndex+1, ch); %#ok<SAGROW>
                    end
                catch
                end
            end
    
            hold(handles.axCompare3,'off');
            if ~isempty(legend_entries_noisy)
                legend(handles.axCompare3, legend_entries_noisy, 'Interpreter','none');
            else
                legend(handles.axCompare3, 'off');
            end
            grid(handles.axCompare3,'on');
            title(handles.axCompare3, '时域比较: 加噪信号 vs 每次滤波结果');
            xlabel(handles.axCompare3, '时间 (s)');
            ylabel(handles.axCompare3, plotYLabel2);
        else
            text(0.5, 0.5, '无加噪信号数据', 'HorizontalAlignment', 'center', 'Parent', handles.axCompare3);
            title(handles.axCompare3, '时域比较: 加噪信号 vs 滤波后信号 (无数据)');
            axis(handles.axCompare3, 'off');
        end
    
        % =============================== 4) 频域比较：若存在加噪信号，绘制 加噪 vs 每次滤波 的频谱 =============================
        axes(handles.axCompare4);
        cla(handles.axCompare4);
        if ~isempty(S.noisy)
            [noisy2, ~] = to2DtimeMajor(S.noisy, tdim, false);
            noisy2 = fillNonfinite(noisy2,1);
            plotNoisyCh = 1:min(size(noisy2,2), maxPlotChannels);
    
            % noisy 作为 base 绘制
            [freq_n, mag_n] = computeSpecForPlot(noisy2(1:min(size(noisy2,1), L_base), :), S.fs, plotSettings);
            plotSpectrum(handles.axCompare4, freq_n, mag_n, plotSettings, plotNoisyCh, '加噪信号', false);
    
            hold(handles.axCompare4,'on');
            % 每次滤波
            for k = 1:nFilt
                [Yk2, ~] = to2DtimeMajor(fillNonfinite(filtList{k}, tdim), tdim, false);
                [freq_k, mag_k] = computeSpecForPlot(Yk2(1:min(size(Yk2,1), L_base), :), S.fs, plotSettings);
                plotSpectrum(handles.axCompare4, freq_k, mag_k, plotSettings, plotNoisyCh, sprintf('第%d次滤波', k), false);
            end
    
            % 临时
            if isprop(S,'continueTempLatest') && ~isempty(S.continueTempLatest)
                try
                    [data2D_tmp, ~] = to2DtimeMajor(S.continueTempLatest, tdim, false);
                    data2D_tmp = fillNonfinite(data2D_tmp,1);
                    [freq_t, mag_t] = computeSpecForPlot(data2D_tmp(1:min(size(data2D_tmp,1), L_base), :), S.fs, plotSettings);
                    plotSpectrum(handles.axCompare4, freq_t, mag_t, plotSettings, 1:min(size(data2D_tmp,2), maxPlotChannels), ...
                        sprintf('第%d次滤波 (临时)', S.continueBaseIndex+1), false);
                catch
                end
            end
            hold(handles.axCompare4,'off');
    
            try
                legend(handles.axCompare4,'show','Interpreter','none');
            catch
            end
            grid(handles.axCompare4,'on');
            title(handles.axCompare4, '频域比较: 加噪信号 vs 每次滤波结果');
            % 设置 xlim（按归一化与单/双边）
            if plotSettings.specFreqNormalized
                if strcmpi(plotSettings.specFreqSide,'double')
                    xlim(handles.axCompare4, [0, 2]);
                else
                    xlim(handles.axCompare4, [0, 1]);
                end
            else
                if strcmpi(plotSettings.specFreqSide,'double')
                    xlim(handles.axCompare4, [0, S.fs]);
                else
                    xlim(handles.axCompare4, [0, S.fs/2]);
                end
            end

        else
            text(0.5, 0.5, '无加噪信号数据', 'HorizontalAlignment', 'center', 'Parent', handles.axCompare4);
            title(handles.axCompare4, '频域比较: 加噪信号 vs 滤波后信号 (无数据)');
            axis(handles.axCompare4, 'off');
        end
        if isCompareVisible
            % 刷新图形
            drawnow; pause(0.01);
        
            setStatus(handles,'已更新比较图窗口。');
            handles.btnSaveFigs.Enable = 'on';
        end
    end

    %% ---- 滤波后的时域、频域波形绘图参数更新应用 ----
    function updatePlotSettingsOnly(S, handles)
    % 传入的 handle类 S, handles
    % 对 S 的对象内容有 "读/写" 操作
    % 对 handles 的对象内容有  "读/写" 操作
    %
    % 本函数依据 handles.plotSettings 绘制：
    %   - 时域绘图模式: plotSettings.signalPlotMode ('plot'|'stem')
    %   - 频谱 单/双边: plotSettings.specFreqSide ('single'|'double')
    %   - 频谱 横轴: plotSettings.specFreqScale ('linear'|'log')
    %   - 幅值模式: plotSettings.specMagMode ('dB'|'linear')
    %   - 幅值归一化: plotSettings.specMagNormalized (logical)
    
        plotSettings = handles.plotSettings; % 获取绘图设置参数
        axFiltT = handles.axFiltTime;
        axFiltS = handles.axFiltSpec;
        maxPlotChannels = 4; % 控制一次性绘制的通道数（避免界面拥挤）
    
        % ---------------- 1) 确定时间维 tdim ----------------
        if  ~isempty(S.timeDim) && S.timeDim==round(S.timeDim) && S.timeDim>=1
            tdim = S.timeDim;
            useTimeDim = true;
        else
            % 优先使用已知数据模板推断
            template = [];
            if isprop(S,'filtered') && ~isempty(S.filtered)
                template = S.filtered;
            elseif isprop(S,'continueFilterBase') && ~isempty(S.continueFilterBase)
                template = S.continueFilterBase;
            elseif isprop(S,'filteredHistory') && ~isempty(S.filteredHistory)
                template = S.filteredHistory{end};
            end
            if ~isempty(template)
                tdim = find(size(template)~=1,1,'first');
                if ~isempty(tdim) && tdim>=1
                    useTimeDim = true;
                end
            else
                tdim = 1; useTimeDim = false;
            end
        end
    
        % ---------------- 2) 删除并重建时域历史句柄（先删除管理的句柄） ----------------
        try
            % 删除旧句柄（仅删除我们管理的句柄，避免影响其它对象）
            if isprop(S,'filteredPlotHandlesTime') && ~isempty(S.filteredPlotHandlesTime)
                for k = 1:numel(S.filteredPlotHandlesTime)
                    hTime = S.filteredPlotHandlesTime{k};
                    if ~isempty(hTime)
                        hvec = flattenHandlesEntry(hTime);
                        if ~isempty(hvec)
                            try delete(hvec); catch; end
                        end
                    end
                end
            end
            if isprop(S,'continueTempHandleTime') && ~isempty(S.continueTempHandleTime)
                try
                    tmp = flattenHandlesEntry(S.continueTempHandleTime);
                    if ~isempty(tmp), delete(tmp); end
                catch
                end
                S.continueTempHandleTime = [];
            end
    
            % 重新绘制历史曲线（如果 S.filteredHistory 存在）
            S.filteredPlotHandlesTime = {}; % 重建句柄列表
    
            % 如果没有历史则跳过重绘历史部分
            if isprop(S,'filteredHistory') && ~isempty(S.filteredHistory)
                % 清空由本模块管理的对象：先清图（但不删除其它 UI 对象）
                cla(axFiltT); hold(axFiltT,'on');
                for k = 1:numel(S.filteredHistory)
                    y = S.filteredHistory{k};
                    % 将任意 ND 数组转换为 [N x channels]
                    [Y2, ~] = to2DtimeMajor(y, tdim, false);
    
                    % 处理 NaN/Inf
                    Y2 = fillNonfinite(Y2,1);
    
                    Nrows = size(Y2,1);
                    nch = size(Y2,2);
    
                    t_y = (0:Nrows-1)/S.fs;
                    hArr = gobjects(1,nch);
                    if ~isreal(Y2)
                        plotData = abs(Y2);
                    else
                        plotData = Y2;
                    end
    
                    % 使用 plotTimeWave 辅助绘制单条历史（能处理 plot/stem）
                    % 但 plotTimeWave 期望完整通道数组 -> 我们逐通道调用以便管理句柄
                    for ch = 1:nch
                        col = plotData(:,ch);
                        if strcmpi(plotSettings.signalPlotMode,'stem')
                            hTime = stem(axFiltT, t_y, col, 'filled','Marker','o','MarkerSize',3);
                        else
                            hTime = plot(axFiltT, t_y, col);
                        end
                        if nch==1
                            try set(hTime, 'DisplayName', sprintf('第%d次滤波', k)); catch; end
                        else
                            try set(hTime, 'DisplayName', sprintf('第%d次滤波-ch%d', k, ch)); catch; end
                        end
                        hArr(ch) = hTime;
                    end
                    S.filteredPlotHandlesTime{end+1} = hArr;
                end
                hold(axFiltT,'off');
            end
        catch ME
            warning('updatePlotSettingsOnly:timeAxisFail','时域重绘失败：%s', ME.message);
            fprintf('调试点81：滤波后的时域重绘失败： %s\n', ME.message);
        end
    
        % ---------------- 3) 删除并重建频谱历史句柄（使用 computeSpecForPlot & plotSpectrum） ----------------
        try
            if isprop(S,'filteredPlotHandlesSpec') && ~isempty(S.filteredPlotHandlesSpec)
                for k = 1:numel(S.filteredPlotHandlesSpec)
                    hSpec = S.filteredPlotHandlesSpec{k};
                    if ~isempty(hSpec)
                        hvec = flattenHandlesEntry(hSpec);
                        if ~isempty(hvec)
                            try delete(hvec); catch; end
                        end
                    end
                end
            end
            if isprop(S,'continueTempHandleSpec') && ~isempty(S.continueTempHandleSpec)
                try
                    tmp = flattenHandlesEntry(S.continueTempHandleSpec);
                    if ~isempty(tmp), delete(tmp); end
                catch
                end
                S.continueTempHandleSpec = [];
            end
    
            S.filteredPlotHandlesSpec = {};
            if isprop(S,'filteredHistory') && ~isempty(S.filteredHistory)
                cla(axFiltS); hold(axFiltS,'on');
    
                for k = 1:numel(S.filteredHistory)
                    y = S.filteredHistory{k};
                    [Y2, ~] = to2DtimeMajor(y, tdim, false);
                    Y2 = fillNonfinite(Y2,1);
    
                    % 计算频谱（computeSpecForPlot 会使用 plotSettings 处理）
                    [freq_k, mag_k] = computeSpecForPlot(Y2, S.fs, plotSettings);
    
                    % 绘制（plotSpectrum 会基于 plotSettings 处理线性/对数、plot/stem、单/双边、dB/linear、归一化）
                    % false（叠加）
                    hSpec = plotSpectrum(axFiltS, freq_k, mag_k, plotSettings, 1:min(size(mag_k,2),maxPlotChannels), sprintf('第%d次滤波', k), false);
    
                    S.filteredPlotHandlesSpec{end+1} = hSpec;
                end
                hold(axFiltS,'off');
                % 设置 xlim（按归一化与单/双边）
                if plotSettings.specFreqNormalized
                    if strcmpi(plotSettings.specFreqSide,'double')
                        xlim(axFiltS, [0, 2]);
                    else
                        xlim(axFiltS, [0, 1]);
                    end
                else
                    if strcmpi(plotSettings.specFreqSide,'double')
                        xlim(axFiltS, [0, S.fs]);
                    else
                        xlim(axFiltS, [0, S.fs/2]);
                    end
                end
            end
        catch ME
            warning('updatePlotSettingsOnly:specAxisFail','频谱重绘失败：%s', ME.message);
            fprintf('调试点82：滤波后的频谱重绘失败： %s\n', ME.message);
        end
    
        % ---------------- 4) 绘制临时曲线（遵循 settings） ----------------
        try
            if isprop(S,'continueTempLatest') && ~isempty(S.continueTempLatest)
                [data2D, ~] = to2DtimeMajor(S.continueTempLatest, tdim, false);
                data2D = fillNonfinite(data2D,1);
    
                if ~isempty(data2D)
                    Nrows = size(data2D,1);
                    nch = size(data2D,2);
                    t_y = (0:Nrows-1)/S.fs;
    
                    % 时域临时
                    axes(axFiltT); hold(axFiltT,'on');
                    htmpArr = gobjects(1,nch);
                    if ~isreal(data2D)
                        plotData = abs(data2D);
                    else
                        plotData = data2D;
                    end
                    for ch = 1:nch
                        col = plotData(:,ch);
                        if strcmpi(plotSettings.signalPlotMode,'stem')
                            hTimeTmp = stem(axFiltT, t_y, col, 'filled','Marker','o','MarkerSize',3);
                        else
                            hTimeTmp = plot(axFiltT, t_y, col);
                        end
                        try set(hTimeTmp, 'Tag', 'continueTemp'); catch; end
                        if nch==1
                            try set(hTimeTmp, 'DisplayName', sprintf('第%d次滤波 (临时)', S.continueBaseIndex+1)); catch; end
                        else
                            try set(hTimeTmp, 'DisplayName', sprintf('第%d次滤波-ch%d (临时)', S.continueBaseIndex+1, ch)); catch; end
                        end
                        htmpArr(ch) = hTimeTmp;
                    end
                    S.continueTempHandleTime = htmpArr;
                    hold(axFiltT,'off');
    
                    % 频域临时（使用 computeSpecForPlot + plotSpectrum）
                    axes(axFiltS);
                    hold(axFiltS,'on');
                    [freq_t, mag_t] = computeSpecForPlot(data2D, S.fs, plotSettings);
                    hSpecTmp = plotSpectrum(axFiltS, freq_t, mag_t, plotSettings, 1:min(size(mag_t,2),maxPlotChannels), sprintf('第%d次滤波 (临时)', S.continueBaseIndex+1), false);
                    S.continueTempHandleSpec = hSpecTmp;
                    hold(axFiltS,'off');
                end
            end
        catch ME
            warning('updatePlotSettingsOnly:tempFail','临时绘图失败：%s', ME.message);
            fprintf('调试点83：临时绘图失败： %s\n', ME.message);
        end
    
        % ---- 5) 更新 legend ----
        try
            updateFilteredLegends(S, axFiltT, axFiltS);
        catch
            % 忽略 legend 更新错误
        end
    end

    %% ---- “查看滤波器分析”按钮回调：滤波器分析分发器--根据下拉选择调用对应的现有滤波器分析函数 ---- 
    function onViewFilterAnalysis(~,~)
        % 分发器：根据下拉选择调用对应的现有分析函数
        sel = handles.ddFilterAnalysis.Value;
        switch sel
            case '滤波器指标'
                % 调用现存的 onFilterMetrics 回调（保持原签名）
                try
                    onFilterMetrics(S, handles, fig_GUI);
                catch ME
                    uialert(fig_GUI, ['打开滤波器指标时出错：' ME.message], '错误');
                end
    
            case '使用滤波器分析器'
                % 使用 MATLAB 的 filterAnalyzer 可视化分析（R2024a+）
                % 我们会在 R2025a 及以后版本传入 SampleRates（若存在且有效），
                % 否则回退到不传 SampleRates 的调用以保证兼容性。

                % 1) 检查滤波器系数是否存在
                if  ~isprop(S,'filter_b') || isempty(S.filter_b) || ~isprop(S,'filter_a') || isempty(S.filter_a)
                    uialert(fig_GUI, '未找到已设计的滤波器系数，请先点击 "设计滤波器"。', '无滤波器');
                    return;
                end

                % 2) 检查 filterAnalyzer 函数可用性
                if ~(exist('filterAnalyzer','file')==2 || exist('filterAnalyzer','builtin')==5)
                    uialert(fig_GUI, '当前 MATLAB 环境不支持 filterAnalyzer。请确认已安装 Signal Processing Toolbox 且 MATLAB 版本支持该 app。', '不可用');
                    return;
                end

                % 3) 检查是否有有效采样率可用
                hasFs = isprop(S,'fs') && isnumeric(S.fs) && isfinite(S.fs) && (S.fs>0);

                % 4) 检查 MATLAB 版本是否支持传入 SampleRates 名-值（R2025a 新增该选项）
                %    使用 verLessThan 判断：如果 MATLAB >= R2025a 则支持 SampleRates。
                try
                    supportsSampleRates = ~verLessThan('matlab','R2025a'); 
                catch
                    % 若 verLessThan 出错（非常罕见），安全回退为不支持
                    supportsSampleRates = false;
                end

                % 5) 组合逻辑：若支持 SampleRates 且有有效采样率，则在调用时传入 SampleRates
                try
                    % 优先尝试把系数封装为 digitalFilter（若可用），这通常能让 app 显示更多元数据
                    try
                        dfiltObj = digitalFilter('Numerator', S.filter_b, 'Denominator', S.filter_a);
                    catch
                        dfiltObj = []; % 数字滤波器对象创建失败（回退到系数）
                    end

                    if supportsSampleRates && hasFs
                        % 传入 SampleRates 参数的首选调用（可接受 filter objects 或系数）
                        if ~isempty(dfiltObj)
                            fa = filterAnalyzer(dfiltObj, SampleRates=S.fs);
                        else
                            fa = filterAnalyzer(S.filter_b, S.filter_a, SampleRates=S.fs);
                        end
                    else
                        % 不传 SampleRates：向后兼容的调用
                        if ~isempty(dfiltObj)
                            fa = filterAnalyzer(dfiltObj);
                        else
                            fa = filterAnalyzer(S.filter_b, S.filter_a);
                        end
                    end

                    % 6) 保存 app 句柄以便后续管理/关闭
                    handles.filterAnalyzerApp = fa;
                    setStatus(handles,'已使用 filterAnalyzer 打开滤波器分析窗口');

                catch ME
                    % 如果传参导致异常（某些极端类型/版本），回退并提示
                    try
                        % 最后回退：不传 SampleRates 且用系数直接打开（最稳）
                        fa = filterAnalyzer(S.filter_b, S.filter_a);
                        handles.filterAnalyzerApp = fa;
                        setStatus(handles,'已使用 filterAnalyzer（回退路径）打开滤波器分析窗口');
                    catch
                        uialert(fig_GUI, ['打开 filterAnalyzer 时出错：' ME.message], '错误');
                    end
                end


            case '滤波器单位冲激响应'
                try
                    onImpulseResponse(S, handles, fig_GUI);
                catch ME
                    uialert(fig_GUI, ['打开单位冲激响应时出错：' ME.message], '错误');
                end

            case '滤波器单位阶跃响应'
                try
                    onStepResponse(S, handles, fig_GUI);
                catch ME
                    if exist('uialert_safe', 'file')
                        uialert_safe(fig_GUI, ['打开单位阶跃响应时出错：' ME.message], '错误');
                    else
                        uialert(fig_GUI, ['打开单位阶跃响应时出错：' ME.message], '错误');
                    end
                end

    
            case '滤波器群延迟'
                try
                    onGroupDelay(S, handles, fig_GUI);
                catch ME
                    uialert(fig_GUI, ['打开群延迟时出错：' ME.message], '错误');
                end

            case '滤波器相位延迟'
            try
                onPhaseDelay(S, handles, fig_GUI);
            catch ME
                uialert(fig_GUI, ['打开相位延迟时出错：' ME.message], '错误');
            end

            case '滤波器零极点图'
                try
                    onPoleZeroPlot(S, handles, fig_GUI);
                catch ME
                    if exist('uialert_safe', 'file')
                        uialert_safe(fig_GUI, ['打开零极点图时出错：' ME.message], '错误');
                    else
                        uialert(fig_GUI, ['打开零极点图时出错：' ME.message], '错误');
                    end
                end


            otherwise
                uialert(fig_GUI,'未识别的分析选项','错误');
        end
        setStatus(handles,sprintf('滤波器分析 - %s 已打开',sel));
    end


    %% ---- 显示/复用 "滤波器指标" 窗口（显示窗口 + 计算并展示"实际指标"） ---- 
    function onFilterMetrics(S, handles, fig_GUI)
    % 传入的 handle类 S, handles; 主界面 fig_GUI
    % 对 S 的对象内容有 "读" 操作，无 "写" 操作
    % 对 handles 的对象内容有 "读/写" 操作
    % fig_GUI 用于uialert_safe()在主界面弹提醒窗口

        % 只读显示：复用已有窗口（若存在），否则创建并保存窗口及内部控件到 handles.filterMetricsComponents
        % 读取预存系数 b,a 与设定的技术指标，计算实际指标（freqz），并在表格中显示"设定值 (数字角频率)" 与"实际值 (数字角频率)"
        if  ~isprop(S,'filter_b') || isempty(S.filter_b) || isempty(S.filter_a)
            uialert(fig_GUI, '未找到已设计的滤波器系数，请先点击 "设计滤波器"。', '无滤波器');
            return;
        end
    
        % ---- 如果窗口已存在且有效就复用（不重新 new） ----
        if isprop(handles,'filterMetricsFig') && ~isempty(handles.filterMetricsFig) && isvalid(handles.filterMetricsFig)
            figM = handles.filterMetricsFig;
            % Bring to front
            figM.Visible = 'on';
            createCenteredFigure(figM); % bring to front (works in App/desktop)
        else
            % 创建窗口并保存句柄
            figM = createCenteredUIFigure('Name','滤波器技术指标对比','Position',[200 120 900 620]);
            figM.Resize = 'on';
            handles.filterMetricsFig = figM;
            % 创建并记录内部控件到 handles.filterMetricsComponents（以便后续更新）
            comps = struct();
    
            comps.lblInfo = uilabel(figM,'Text','','FontWeight','bold','Position',[10 575 880 24],'HorizontalAlignment','left');
    
            comps.txtB = uitextarea(figM,'Value',{''}, 'Editable','off', 'Position',[10 520 880 40]);
            comps.txtA = uitextarea(figM,'Value',{''}, 'Editable','off', 'Position',[10 470 880 40]);
    
            % 用 uiaxes 来渲染 LaTeX（用于 H(z) 与 y(n)）
            comps.axLatex = uiaxes(figM, 'Position', [10 350 880 88]); % 留出合适高度
            % 关闭坐标轴显示，便于只显示 LaTeX 文本
            comps.axLatex.XTick = []; comps.axLatex.YTick = [];
            comps.axLatex.Box = 'off';
            comps.axLatex.Visible = 'on';
            % 设定坐标范围为 [0,1]x[0,1]，使用 normalized 风格的放置文本
            comps.axLatex.XLim = [0 1];
            comps.axLatex.YLim = [0 1];
    
            % 将表格扩展为 10 行（增加 Ifc1(-3dB)、Ifc2(-3dB) 与 Ffc1(-6dB)、Ffc2(-6dB)）
            % 创建表格（强制字符列，避免 MATLAB 自动将列识别为 numeric 并把字符串转换为 0）
            comps.tbl = uitable(figM, ...
                'Data', cell(10,3), ...
                'Position', [10 100 880 261], ...
                'ColumnName', {'技术指标','设定值','实际值'}, ...
                'ColumnEditable', [false false false], ...
                'ColumnFormat', {'char','char','char'} ...  % <-- 强制三列均为字符显示
                );


    
        % 底部说明（数字角频率计算方法），设置 WordWrap 以便多行显示
        comps.lblNote = uilabel(figM, ...
            'Text', '', ...
            'Position', [10 12 880 80], ...   % 高度留大一点以容纳多行
            'HorizontalAlignment','left', ...
            'WordWrap','on' ...
        );

            handles.filterMetricsComponents = comps;
        end
    
        % ---- 读取 b,a, 阶数，以及用户设定值 ----
        b = S.filter_b(:).'; a = S.filter_a(:).';
        nOrder = max(length(b)-1, length(a)-1);
    
        % 取采样率（若不存在则标注为 NaN）
        if isprop(S,'fs') && ~isempty(S.fs)
            Fs = S.fs;
        else
            Fs = NaN;
        end
    
        % 读用户窗口上设定的技术指标（稳健读取）
        try set_fp1 = handles.edtPb1.Value; catch; set_fp1 = NaN; end
        try set_fp2 = handles.edtPb2.Value; catch; set_fp2 = NaN; end
        try set_fst1 = handles.edtSb1.Value; catch; set_fst1 = NaN; end
        try set_fst2 = handles.edtSb2.Value; catch; set_fst2 = NaN; end
        try set_Rp  = handles.edtRp.Value; catch; set_Rp = NaN; end
        try set_Rs  = handles.edtRs.Value; catch; set_Rs = NaN; end
        % 取得设计方法/原型/滤波类型控件的可读字符串（稳健）
        try designMethodStr = handles.ddDesignMethod.Value; catch; designMethodStr = ''; end
        try ftype = handles.ddType.Value; catch; ftype = ''; end
        try protoName = handles.ddIIRProto.Value; catch; protoName = ''; end
        try wndName = handles.ddWindow.Value; catch; wndName = ''; end
        try firOptMethod = handles.ddFIRMethod.Value; catch; firOptMethod = ''; end

        % =====  针对 Butterworth 的设定 fc (−3 dB) 显示处理 =====
        % set_Ifc1/set_Ifc2: 设定值（Hz）——若是 IIR 且 proto=Butterworth：
        %   - iirOrderVal <= 0 (自动估阶): 使用 buttord() 得到 Wn，再转换为 Hz (fc = Wn * Nyq)
        %   - iirOrderVal > 0 (用户指定阶数): 直接把 fp1/fp2 当作 Ifc1/Ifc2（保持原有行为）
        
        % 先默认 NaN
        set_Ifc1 = NaN; set_Ifc2 = NaN;
        
        try
            % 读取一些必要变量（若缺失，保持 NaN）
            try iirOrderVal = round(double(handles.edtIIROrder.Value)); catch; iirOrderVal = -1; end
            try protoName = handles.ddIIRProto.Value; catch; protoName = ''; end
            try designMethodStr = handles.ddDesignMethod.Value; catch; designMethodStr = ''; end
            % 采样率保护
            if ~isnan(Fs) && Fs > 0
                nyq = Fs/2;
            else
                nyq = NaN;
            end
        
            if strcmpi(designMethodStr,'IIR') && ~isempty(protoName) && any(strcmpi(protoName,{'Butterworth','maxflat'}))
                % butterworth、maxflat 情况
                if iirOrderVal <= 0
                    % 自动估阶：按设计处的规范化方式构造 Wp, Wst 并调用 buttord（只作显示，不改变设计）
                    norm_safe = @(f) max(eps, min(0.999999, (double(f)./nyq)));
                    switch lower(ftype)
                        case '低通'
                            Wp = norm_safe(set_fp1); Wst = norm_safe(set_fst1);
                        case '高通'
                            Wp = norm_safe(set_fp1); Wst = norm_safe(set_fst1);
                        case '带通'
                            Wp = [norm_safe(set_fp1), norm_safe(set_fp2)]; Wst = [norm_safe(set_fst1), norm_safe(set_fst2)];
                        case '带阻'
                            Wp = [norm_safe(set_fp1), norm_safe(set_fp2)]; Wst = [norm_safe(set_fst1), norm_safe(set_fst2)];
                        otherwise
                            Wp = []; Wst = [];
                    end
                    % 调用 buttord（加 try 保护，避免抛错）
                    try
                        if ~isempty(Wp)
                            [~, WnCalc] = buttord(Wp, Wst, set_Rp, set_Rs); % WnCalc 为 0-1 归一化（相对于 Nyq）
                            if ~isnan(nyq)
                                if isscalar(WnCalc)
                                    set_Ifc1 = WnCalc * nyq;
                                else
                                    % 双边频率
                                    set_Ifc1 = WnCalc(1) * nyq;
                                    set_Ifc2 = WnCalc(2) * nyq;
                                end
                            end
                        end
                    catch
                        % 如果 buttord 失败则保持 NaN（显示 '-'）
                        set_Ifc1 = NaN; set_Ifc2 = NaN;
                    end
                else
                    % 用户指定阶数：保持现状 —— fp1, fp2 当作 Ifc1, Ifc2
                    set_Ifc1 = set_fp1;
                    set_Ifc2 = set_fp2;
                end
            end
        catch
            % 一旦有任何异常，不影响主流程：保持 NaN
            set_Ifc1 = NaN; set_Ifc2 = NaN;
        end

        % =====  针对 FIR 窗函数法显示 Ffc(-6dB) 的设定值处理（Rectwin,Triang,Hann,Hamming,Blackman,Kaiser） =====
        set_Ffc1 = NaN; set_Ffc2 = NaN;  % 预设
        try
            % 读取 FIR 相关控件信息（稳健读取）
            try firOrderVal = round(double(handles.edtFIROrder.Value)); catch; firOrderVal = -1; end
            try wndName = handles.ddWindow.Value; catch; wndName = ''; end
            try designMethodStr = handles.ddDesignMethod.Value; catch; designMethodStr = ''; end
            if strcmpi(designMethodStr, 'FIR窗函数法') && ~isempty(wndName) && any(strcmpi(wndName, {'Rectwin','Triang','Hann','Hamming','Blackman','Kaiser'}))
                % 如果用户指定阶数 (>0)，按要求把 fp1/fp2 当成 Ffc1/Ffc2（显示设定值）
                if firOrderVal > 0
                    set_Ffc1 = set_fp1;
                    set_Ffc2 = set_fp2;
                else
                    % 自动估阶（<=0）仅对 Kaiser 有自动估阶（调用 kaiserord 以显示 Wn）
                    if strcmpi(wndName, 'Kaiser')
                        % 构造 kaiserord 所需的 freq,a,dev（与设计处保持一致）
                        Rp_val = max(0, double(set_Rp));
                        Rs_val = max(0, double(set_Rs));
                        dp_tmp = max(eps, (10^(Rp_val/20)-1) / (10^(Rp_val/20)+1)); % 通带线性误差
                        ds_tmp = max(eps, 10^(-Rs_val/20));
                        switch lower(ftype)
                            case '低通'
                                freq_vec = [set_fp1 set_fst1]; a_vec = [1 0]; dev_vec = [dp_tmp ds_tmp];
                            case '高通'
                                freq_vec = [set_fst1 set_fp1]; a_vec = [0 1]; dev_vec = [ds_tmp dp_tmp];
                            case '带通'
                                freq_vec = [set_fst1 set_fp1 set_fp2 set_fst2]; a_vec = [0 1 0]; dev_vec = [ds_tmp dp_tmp ds_tmp];
                            case '带阻'
                                freq_vec = [set_fp1 set_fst1 set_fst2 set_fp2]; a_vec = [1 0 1]; dev_vec = [dp_tmp ds_tmp dp_tmp];
                            otherwise
                                freq_vec = []; a_vec = []; dev_vec = [];
                        end
                        if ~isempty(freq_vec) && ~isnan(Fs)
                            try
                                [~, WnK, ~, ~] = kaiserord(freq_vec, a_vec, dev_vec, Fs); % WnK 以 Hz 单位（归一化为 0..Nyq）
                                % kaiserord 在 MATLAb 中返回 Wn in Hz if fs provided; 统一转为相对于 Nyq 再乘以 Nyq 保证兼容性
                                % 若 WnK 是 0..1（归一化到 Nyq），则 *Nyq 转为 Hz
                                if ~isempty(WnK)
                                    if isscalar(WnK)
                                        set_Ffc1 = WnK * (Fs/2);
                                    else
                                        set_Ffc1 = WnK(1) * (Fs/2);
                                        set_Ffc2 = WnK(2) * (Fs/2);
                                    end
                                end
                            catch
                                set_Ffc1 = NaN; set_Ffc2 = NaN;
                            end
                        end
                    else
                        % 其他窗（非 Kaiser）自动估阶时不提供 set_Ffc（保持 NaN）
                        set_Ffc1 = NaN; set_Ffc2 = NaN;
                    end
                end
            end
        catch
            set_Ffc1 = NaN; set_Ffc2 = NaN;
        end



        % -------- 更新顶部信息行 --------     
        try
            % 尝试常见控件名（你可按实际控件名改）
            if strcmpi(designMethodStr,'IIR')
                infoStr = sprintf('设计方法: %s    原型: %s    滤波类型: %s    滤波器阶数: %d', designMethodStr, protoName, ftype, nOrder);
            elseif  strcmpi(designMethodStr,'FIR窗函数法')
                infoStr = sprintf('设计方法: %s    窗: %s    滤波类型: %s    滤波器阶数: %d', designMethodStr, wndName, ftype, nOrder);
            elseif  strcmpi(designMethodStr,'FIR优化设计法')
                infoStr = sprintf('设计方法: %s    优化设计法: %s    滤波类型: %s    滤波器阶数: %d', designMethodStr, firOptMethod, ftype, nOrder);
            elseif  strcmpi(designMethodStr,'FIR频率采样法')
                infoStr = sprintf('设计方法: %s    滤波类型: %s    滤波器阶数: %d', designMethodStr, ftype, nOrder);
                
            elseif  strcmp(designMethodStr, '陷波') || strcmp(designMethodStr, '峰值滤波')
                try
                    p = handles.notchPeakParams; % 结构体，参考 onNotchPeakParams 保存逻辑
                    % 基本行：方法 + 类型标签（single/multi/comb）
                    typeLabel = '';
                    if isfield(p,'typeLabel') && ~isempty(p.typeLabel)
                        typeLabel = sprintf(' - %s', p.typeLabel);
                    elseif isfield(p,'type') && ~isempty(p.type)
                        typeLabel = sprintf(' - %s', p.type);
                    end
                    infoStr = sprintf('设计方法：%s%s    滤波器阶数: %d', designMethodStr, typeLabel, nOrder);

                catch ME
                    % 若解析出现错误则退回到稳健的回退显示（避免抛错影响 GUI）
                    warning('updateNote:notchPeakDisplayFailed','显示 陷波/峰值 参数失败: %s', ME.message);
                    if strcmp(method,'陷波')
                        if isprop(handles, 'NotchOrder') && isobject(handles.NotchOrder) && isvalid(handles.NotchOrder) && handles.NotchOrder.Value > 0
                            infoStr = sprintf('设计方法：%s    阶数: %d', designMethodStr, nOrder);
                        else
                            infoStr = sprintf('设计方法：%s', designMethodStr);
                        end
                    else % 峰值滤波
                        if isprop(handles, 'PeakOrder') && isobject(handles.PeakOrder) && isvalid(handles.PeakOrder) && handles.PeakOrder.Value > 0
                            infoStr = sprintf('设计方法：%s    阶数: %d', designMethodStr, nOrder);
                        else
                            infoStr = sprintf('设计方法：%s', designMethodStr);
                        end
                    end
                end

            else
                  infoStr = sprintf('设计方法: %s    滤波器阶数: %d', designMethodStr, nOrder);
            end
        catch
        end
        % 显示顶部信息行
        handles.filterMetricsComponents.lblInfo.Text = infoStr;
    

        % 第二/三行：b, a 显示（只读）
        handles.filterMetricsComponents.txtB.Value = { ['b = ', mat2str(b,6)] };
        handles.filterMetricsComponents.txtA.Value = { ['a = ', mat2str(a,6)] };
    
        % 显示 H(z) / 差分方程：阶数阈值控制
        % ----------------- 用 LaTeX 渲染 H(z) 与差分方程 -----------------
        displayThreshold = 56; % 阈值：当阶数 <= 阈值时展开数值式，否则用求和符号表示
    
        % 先准备 LaTeX 字符串（改进显示：去掉 z^{-0}、分母为 1 时不显示分式、差分方程符号美化）
        try
            % 容差：小于该值视为零（可根据需要调大到 1e-9 等）
            tol = 1e-12;
            
            if nOrder <= displayThreshold
                % ---------------- 构造分子（num）和分母（den）的 LaTeX 字符串（跳过近似为0的项） ----------------
                % numerator
                numStr = '';
                firstTerm = true;
                for k = 0:(length(b)-1)
                    c = b(k+1);
                    if abs(c) <= tol
                        continue; % 跳过系数约等于 0 的项
                    end
                    if firstTerm
                        % 第一项不带前导符号（正负由系数本身决定）
                        if k == 0
                            numStr = sprintf('%.4g', c);
                        else
                            numStr = sprintf('%.4g\\,z^{-%d}', c, k);
                        end
                        firstTerm = false;
                    else
                        % 后续项带显式符号（将负号外置，使用绝对值显示系数）
                        if c < 0
                            if k == 0
                                numStr = sprintf('%s - %.4g', numStr, abs(c));
                            else
                                numStr = sprintf('%s - %.4g\\,z^{-%d}', numStr, abs(c), k);
                            end
                        else
                            if k == 0
                                numStr = sprintf('%s + %.4g', numStr, c);
                            else
                                numStr = sprintf('%s + %.4g\\,z^{-%d}', numStr, c, k);
                            end
                        end
                    end
                end
                if isempty(numStr)
                    numStr = '0'; % 若所有 b 都为 0，则显示 0
                end
            
                % denominator
                denStr = '';
                firstTerm = true;
                for k = 0:(length(a)-1)
                    c = a(k+1);
                    if abs(c) <= tol
                        continue; % 跳过近似 0 的项
                    end
                    if firstTerm
                        if k == 0
                            denStr = sprintf('%.4g', c);
                        else
                            denStr = sprintf('%.4g\\,z^{-%d}', c, k);
                        end
                        firstTerm = false;
                    else
                        if c < 0
                            if k == 0
                                denStr = sprintf('%s - %.4g', denStr, abs(c));
                            else
                                denStr = sprintf('%s - %.4g\\,z^{-%d}', denStr, abs(c), k);
                            end
                        else
                            if k == 0
                                denStr = sprintf('%s + %.4g', denStr, c);
                            else
                                denStr = sprintf('%s + %.4g\\,z^{-%d}', denStr, c, k);
                            end
                        end
                    end
                end
                if isempty(denStr)
                    denStr = '0'; % 极端情况（不应出现），但保证字符串不空
                end
            
                % ---------------- 构造 H(z) LaTeX：若分母近似 1 则不显示为分式 ----------------
                if isscalar(a) && abs(a(1) - 1) < tol
                    H_ltx = ['$H(z)=' numStr '$'];
                else
                    H_ltx = ['$H(z)=\frac{' numStr '}{' denStr '}$'];
                end
            
                % ---------------- 构造差分方程 LaTeX（系数为0的项不显示，a0==1 时省略 1/a0） ----------------
                % b 部分（x 项）
                bsum = '';
                firstTerm = true;
                for k = 0:(length(b)-1)
                    c = b(k+1);
                    if abs(c) <= tol
                        continue;
                    end
                    if firstTerm
                        % 第一项：直接显示（保留系数，避免前导 +）
                        if k == 0
                            bsum = sprintf('%.4g\\,x(n)', c);
                        else
                            bsum = sprintf('%.4g\\,x(n-%d)', c, k);
                        end
                        firstTerm = false;
                    else
                        if c < 0
                            if k == 0
                                bsum = sprintf('%s - %.4g\\,x(n)', bsum, abs(c));
                            else
                                bsum = sprintf('%s - %.4g\\,x(n-%d)', bsum, abs(c), k);
                            end
                        else
                            if k == 0
                                bsum = sprintf('%s + %.4g\\,x(n)', bsum, c);
                            else
                                bsum = sprintf('%s + %.4g\\,x(n-%d)', bsum, c, k);
                            end
                        end
                    end
                end
                if isempty(bsum)
                    bsum = '0';
                end
            
                % a 部分（y 项），只收集非零项（绝对值显示，并在外部作为被减项）
                asum_terms = {};
                for kk = 2:length(a)
                    ak = a(kk);
                    if abs(ak) > tol
                        asum_terms{end+1} = sprintf('%.4g\\,y(n-%d)', abs(ak), kk-1); %#ok<AGROW>
                    end
                end
                if isempty(asum_terms)
                    a_sum_str = '0';
                else
                    a_sum_str = strjoin(asum_terms, ' + ');
                end
            
                % 组合差分方程：若 a0 ~= 1 则保留 1/a0 前缀；若 a0 == 1 则省略
                if abs(a(1) - 1) < tol
                    % a0 == 1：不显示 1/a0
                    if strcmp(a_sum_str, '0')
                        diff_ltx = sprintf('$y(n)=%s$', bsum);
                    else
                        diff_ltx = sprintf('$y(n)=%s - (%s)$', bsum, a_sum_str);
                    end
                else
                    % a0 != 1：保留 1/a0
                    if strcmp(a_sum_str, '0')
                        diff_ltx = sprintf('$y(n)=\\frac{1}{%.4g}\\left(%s\\right)$', a(1), bsum);
                    else
                        diff_ltx = sprintf('$y(n)=\\frac{1}{%.4g}\\left(%s - (%s)\\right)$', a(1), bsum, a_sum_str);
                    end
                end
            else
                % 阶数太大，使用求和符号的紧凑 LaTeX 形式（不展开所有系数）
                H_ltx = sprintf('$H(z)=\\frac{\\sum_{k=0}^{%d} b_k z^{-k}}{\\sum_{k=0}^{%d} a_k z^{-k}}$', length(b)-1, length(a)-1);
                diff_ltx = sprintf('$y(n)=\\frac{1}{a_0}\\left(\\sum_{k=0}^{%d} b_k x(n-k) - \\sum_{k=1}^{%d} a_k y(n-k)\\right)$', length(b)-1, length(a)-1);
            end
            
                    
            % 在 UIAxes 上渲染 LaTeX（复用或创建 ax）
            if isfield(handles.filterMetricsComponents,'axLatex') && ~isempty(handles.filterMetricsComponents.axLatex) && isvalid(handles.filterMetricsComponents.axLatex)
                ax = handles.filterMetricsComponents.axLatex;
                % 清除以前的文本
                cla(ax);
            else
                % 如果 ax 不存在（万一创建环节被跳过），尝试创建并保存
                ax = uiaxes(figM, 'Position', [10 350 880 88]);
                ax.XTick = []; ax.YTick = []; ax.Box = 'off';
                ax.XLim = [0 1]; ax.YLim = [0 1];
                handles.filterMetricsComponents.axLatex = ax;
            end
        
            % 将 H(z) 放上方，差分方程放下方；使用 Interpreter='latex'
            text(ax, 0.01, 0.92, H_ltx, 'Interpreter', 'latex', 'FontSize', 13, 'HorizontalAlignment','left');
            text(ax, 0.01, 0.40, diff_ltx, 'Interpreter', 'latex', 'FontSize', 13, 'HorizontalAlignment','left');
            ax.Visible = 'off'; % 保持坐标轴视觉隐藏
        
        catch ME
            % 如果 LaTeX 渲染失败（版本/环境兼容问题），回退到用 uitextarea 显示普通文本（原样）
            warning('onFilterMetrics:LaTeXFail','LaTeX 渲染失败，退回到纯文本显示：%s', ME.message);
            try
                % 退回文本时尽量使用 human-readable 版（移除 $）
                handles.filterMetricsComponents.txtH.Value = { ['H(z): ', strrep(H_ltx,'$','')] };
                handles.filterMetricsComponents.txtDiff.Value = { strrep(diff_ltx,'$','') };
            catch
                % 若也没有 txtH/txtDiff 控件，则动态创建一对 uitextarea 以保证信息可见
                txtH = uitextarea(figM,'Value',{['H(z): ', strrep(H_ltx,'$','')]}, 'Editable','off', 'Position',[10 410 880 48]);
                txtDiff = uitextarea(figM,'Value',{['y(n): ', strrep(diff_ltx,'$','')]}, 'Editable','off', 'Position',[10 360 880 40]);
                % 保存（覆盖先前 comps，如果需要）
                handles.filterMetricsComponents.txtH = txtH;
                handles.filterMetricsComponents.txtDiff = txtDiff;
            end
        end

    
    
        % ---- 计算实际技术指标（用 freqz，改进版） ----
        actual_fp1 = NaN; actual_fp2 = NaN; actual_fst1 = NaN; actual_fst2 = NaN;
        actual_Rp = NaN; actual_Rs = NaN;
        try
            if ~isnan(Fs)
                % 更高分辨率的频率响应（保留 8192 点或更高）
                Nfft = 16384;
                [H, w] = freqz(b, a, Nfft, Fs); % w in Hz
                magdb = 20*log10(abs(H) + eps);
                freq = w(:);
                magdb = magdb(:);

                % 设定阈（dB）
                thr_Rp = -set_Rp; % 通带允许下限（dB）
                thr_Rs = -set_Rs; % 阻带目标上限（dB）

                % 根据滤波类型定义通带/阻带区间（保守选择，避免越界）
                Nyq = Fs/2;
                % 边界保护函数
                clip = @(x) max(0.0001, min(Nyq, double(x))); 

                switch lower(ftype)
                    case '低通'
                        % 通带: [0, set_fp1]; 阻带: [set_fst1, Nyq]
                        pass_idx = freq <= clip(set_fp1);
                        stop_idx = freq >= clip(set_fst1);
                    
                        % --- 避免 DC (0 Hz) 导致的伪 crossing：从第一个"明显大于 0"的频率点开始查找 ---
                        % 这里用一个小阈值保证不把 0 或数值误差当作通带边缘
                        tinyF = max(1e-9, Nyq*1e-9);          % 绝对/相对混合的小阈值
                        startIdx = find(freq > tinyF, 1, 'first');
                        if isempty(startIdx)
                            startIdx = 1; 
                        end
                    
                        % 在切片上查找 crossing（返回值是绝对频率）                  
                        % 注意：传入的 pass mask 必须和 freq(startIdx:end) 对齐
                        if exist('pass_idx','var') && numel(pass_idx)==numel(freq)
                            pass_mask_slice = pass_idx(startIdx:end);
                        else
                            pass_mask_slice = []; % 若不存在或长度不对则传空（interp_cross 会回退）
                        end
                        if exist('stop_idx','var') && numel(stop_idx)==numel(freq)
                            stop_mask_slice = stop_idx(startIdx:end);
                        else
                            stop_mask_slice = [];
                        end
                        try
                            % fp1：通带->阻带 过渡，优先靠近阻带
                            actual_fp1 = interp_cross(freq(startIdx:end), magdb(startIdx:end), thr_Rp, 'fall', pass_mask_slice, stop_mask_slice, 'stop');
                        catch
                            actual_fp1 = NaN;
                        end
                                            
                        % 若 interp_cross 返回 NaN，则用受限的兜底查找（**一定**排除 DC）
                        if isnan(actual_fp1)
                            idx = find(magdb >= thr_Rp & freq > freq(startIdx), 1, 'last'); % 注意 freq > freq(startIdx)
                            if ~isempty(idx)
                                actual_fp1 = freq(idx);
                            else
                                actual_fp1 = NaN;
                            end
                        end
                    
                        % fst1（阻带端）保持靠近通带的逻辑（prefer='pass'）
                        try
                            if exist('pass_idx','var') && numel(pass_idx)==numel(freq)
                                actual_fst1 = interp_cross(freq, magdb, thr_Rs, 'fall', pass_idx, stop_idx, 'pass');
                            else
                                actual_fst1 = interp_cross(freq, magdb, thr_Rs, 'fall');
                            end
                        catch
                            actual_fst1 = NaN;
                        end

                    case '高通'
                        % 通带: [set_fp1, Nyq]; 阻带: [0, set_fst1]
                        pass_idx = freq >= clip(set_fp1);
                        stop_idx = freq <= clip(set_fst1);
                        actual_fp1 = interp_cross(freq, magdb, thr_Rp, 'rise', pass_idx, stop_idx, 'stop');   % 从低向高穿越通带下限
                        actual_fst1 = interp_cross(freq, magdb, thr_Rs, 'rise', pass_idx, stop_idx, 'pass');
                    case '带通'
                        % 带通：通带在中间，阻带在两侧（原逻辑）
                        % 通带: [set_fp1, set_fp2]; 阻带: [0,set_fst1] U [set_fst2,Nyq]
                        pass_idx = (freq >= clip(set_fp1) & freq <= clip(set_fp2));
                        stop_idx = (freq <= clip(set_fst1)) | (freq >= clip(set_fst2));
                        % 通带两端 crossing：左侧由低到高，右侧由高到低
                        actual_fp1 = interp_cross(freq, magdb, thr_Rp, 'rise', pass_idx, stop_idx, 'stop');   % 左侧通带边缘
                        actual_fp2 = interp_cross(freq, magdb, thr_Rp, 'fall', pass_idx, stop_idx, 'stop');   % 右侧通带边缘
                        % 阻带边界（两侧）
                        actual_fst1 = interp_cross(freq, magdb, thr_Rs, 'rise', pass_idx, stop_idx, 'pass');   % 左阻带边界
                        actual_fst2 = interp_cross(freq, magdb, thr_Rs, 'fall', pass_idx, stop_idx, 'pass');   % 右阻带边界
                    
                    case '带阻'
                        % 带阻：阻带在中间，通带在两侧（注意与带通相反）
                        % 通带: [0,set_fp1] U [set_fp2, Nyq]; 阻带: [set_fst1, set_fst2]
                        pass_idx = (freq <= clip(set_fp1)) | (freq >= clip(set_fp2));
                        stop_idx = (freq >= clip(set_fst1) & freq <= clip(set_fst2));
                        % 通带两端 crossing（升序显示：actual_fp1 <= actual_fp2）
                        % 下列方向选择与带阻的频率走向相匹配：
                        actual_fp1 = interp_cross(freq, magdb, thr_Rp, 'fall', pass_idx, stop_idx, 'stop');   % 低频侧：通带向下穿越 -Rp（低频通带的上边缘）
                        actual_fp2 = interp_cross(freq, magdb, thr_Rp, 'rise', pass_idx, stop_idx, 'stop');   % 高频侧：通带由低到高穿越 -Rp（高频通带的下边缘）
                        % 阻带边界（中间带）：左侧上升，右侧下降（与通带方向对称处理）
                        actual_fst1 = interp_cross(freq, magdb, thr_Rs, 'fall', pass_idx, stop_idx, 'pass');   % 阻带左边缘（由高到低衰减边）
                        actual_fst2 = interp_cross(freq, magdb, thr_Rs, 'rise', pass_idx, stop_idx, 'pass');   % 阻带右边缘

                    otherwise
                        % 默认退化处理：尽量尝试定位 fp1
                        pass_idx = freq <= clip(set_fp1);
                        stop_idx = freq >= clip(set_fst1);
                        actual_fp1 = interp_cross(freq, magdb, thr_Rp, 'fall',pass_idx, stop_idx, 'stop');
                        actual_fst1 = interp_cross(freq, magdb, thr_Rs, 'fall',pass_idx, stop_idx, 'stop');
                end


                % ===== 计算实际 fc(-3dB)（用于 Butterworth 、maxflat显示） =====
                actual_Ifc1 = NaN; actual_Ifc2 = NaN;
                try
                    if ~isnan(Fs) && exist('magdb','var') && exist('freq','var')
                        % thr_3db = -3; % -3 dB 阈值（绝对 dB）
                        % 计算 thr_3db：以通带峰值为基准减 3 dB（更契合"归一化增益 -3dB"的定义）
                        if exist('pass_idx','var') && any(pass_idx)
                            thr_3db = max(magdb(pass_idx)) - 3;
                        else
                            thr_3db = max(magdb) - 3; % 兜底：用全谱峰值
                        end
                        proto_n = lower(strtrim(protoName));
                        if strcmpi(designMethodStr,'IIR') && ~isempty(proto_n) && any(strcmpi(proto_n,{'butterworth','maxflat'}))
                            % 根据滤波类型选择边界方向
                            switch lower(ftype)
                                case '低通'
                                    % 从通带方向找下降穿越 -3dB
                                    actual_Ifc1 = interp_cross(freq, magdb, thr_3db, 'fall', pass_idx, stop_idx, 'stop');
                                case '高通'
                                    actual_Ifc1 = interp_cross(freq, magdb, thr_3db, 'rise', pass_idx, stop_idx, 'stop');
                                case '带通'
                                    % 左侧由低到高穿过 -3dB，右侧由高到低穿过 -3dB
                                    actual_Ifc1 = interp_cross(freq, magdb, thr_3db, 'rise', pass_idx, stop_idx, 'stop');   % 左边缘
                                    actual_Ifc2 = interp_cross(freq, magdb, thr_3db, 'fall', pass_idx, stop_idx, 'stop');  % 右边缘
                                case '带阻'
                                    % 带阻：左边缘下降穿越 -3dB，右边缘上升穿越 -3dB
                                    actual_Ifc1 = interp_cross(freq, magdb, thr_3db, 'fall', pass_idx, stop_idx, 'stop');
                                    actual_Ifc2 = interp_cross(freq, magdb, thr_3db, 'rise', pass_idx, stop_idx, 'stop');
                                otherwise
                                    % 兜底：尝试找第一个和最后一个满足 magdb >= -3 的区域边界
                                    idx_ge = find(magdb >= thr_3db);
                                    if ~isempty(idx_ge)
                                        actual_Ifc1 = freq(idx_ge(1));
                                        actual_Ifc2 = freq(idx_ge(end));
                                    end
                            end
                
                            % 若 interp 未找到，尝试粗索引兜底（与其它指标的兜底策略一致）
                            if isnan(actual_Ifc1)
                                idx = find(magdb >= thr_3db, 1, 'first');
                                if ~isempty(idx), actual_Ifc1 = freq(idx); end
                            end
                            if isnan(actual_Ifc2)
                                idx = find(magdb >= thr_3db, 1, 'last');
                                if ~isempty(idx), actual_Ifc2 = freq(idx); end
                            end
                        end
                    end
                catch
                    actual_Ifc1 = NaN; actual_Ifc2 = NaN;
                end

                % =====  FIR 窗函数法的实际 -6dB 频点（Ffc）计算 =====
                actual_Ffc1 = NaN; actual_Ffc2 = NaN;
                try
                    % 仅当设计方法为 FIR 窗函数法 并且窗类型属于我们关心的集合时才计算
                    try wndName = handles.ddWindow.Value; catch; wndName = ''; end
                    try designMethodStr = handles.ddDesignMethod.Value; catch; designMethodStr = ''; end
                    if strcmpi(designMethodStr, 'FIR窗函数法') && any(strcmpi(wndName, {'Rectwin','Triang','Hann','Hamming','Blackman','Kaiser'}))
                        % 计算 thr_6db：以通带峰值为基准减 6 dB（更契合"归一化增益 -6dB"的定义）
                        if exist('pass_idx','var') && any(pass_idx)
                            thr_6db = max(magdb(pass_idx)) - 6;
                        else
                            thr_6db = max(magdb) - 6; % 兜底：用全谱峰值
                        end
                
                        % 根据滤波类型选择方向（与 -3dB 一致的方向规则）
                        switch lower(ftype)
                            case '低通'
                                actual_Ffc1 = interp_cross(freq, magdb, thr_6db, 'fall', pass_idx, stop_idx, 'stop');
                            case '高通'
                                actual_Ffc1 = interp_cross(freq, magdb, thr_6db, 'rise', pass_idx, stop_idx, 'stop');
                            case '带通'
                                actual_Ffc1 = interp_cross(freq, magdb, thr_6db, 'rise', pass_idx, stop_idx, 'stop');   % 左侧
                                actual_Ffc2 = interp_cross(freq, magdb, thr_6db, 'fall', pass_idx, stop_idx, 'stop');   % 右侧
                            case '带阻'
                                actual_Ffc1 = interp_cross(freq, magdb, thr_6db, 'fall', pass_idx, stop_idx, 'stop');   % 左侧
                                actual_Ffc2 = interp_cross(freq, magdb, thr_6db, 'rise', pass_idx, stop_idx, 'stop');   % 右侧
                            otherwise
                                % 兜底：在 magdb >= thr_6db 区域取首末点
                                idx_ge = find(magdb >= thr_6db);
                                if ~isempty(idx_ge)
                                    actual_Ffc1 = freq(idx_ge(1)); actual_Ffc2 = freq(idx_ge(end));
                                end
                        end
                
                        % 兜底粗索引（若 interp_cross 未找到）
                        if isnan(actual_Ffc1)
                            idx = find(magdb >= thr_6db, 1, 'first'); if ~isempty(idx), actual_Ffc1 = freq(idx); end
                        end
                        if isnan(actual_Ffc2)
                            idx = find(magdb >= thr_6db, 1, 'last');  if ~isempty(idx), actual_Ffc2 = freq(idx); end
                        end
                    end
                catch
                    actual_Ffc1 = NaN; actual_Ffc2 = NaN;
                end


                % --- 计算实际 Rp  ---
                try
                    if exist('pass_idx','var') && any(pass_idx)
                        mag_pass = magdb(pass_idx);
                        % % 以 "最大下限相对于 0 dB" 表示
                        actual_Rp = - min(mag_pass);

                        % 还可以以通带峰-峰纹波， peak-to-peak ripple in dB (>=0) 表示
                        % actual_Rp = max(mag_pass) - min(mag_pass); 

                    else
                        actual_Rp = NaN;
                    end
                catch
                    actual_Rp = NaN;
                end

                % --- 计算实际 Rs (阻带最小衰减) ---
                try
                    if exist('stop_idx','var') && any(stop_idx)
                        mag_stop = magdb(stop_idx);
                        % mag_stop 中的最大值（一般是接近 0 或较大的一项）对应最小衰减
                        max_mag_stop = max(mag_stop);
                        actual_Rs = -max_mag_stop; % positive attenuation in dB
                    else
                        actual_Rs = NaN;
                    end
                catch
                    actual_Rs = NaN;
                end


                % 若希望用设定值set_fp1、set_fst1等而不是actual_fp1、actual_fst1等来定义"期望区间"magdb(mag_pass)、magdb(mag_stop)从而
                % 计算Rp/Rs（上面两个try...end已实现）。可以把下面"尝试使用实际的响应计算Rp,Rs"部分注释或者删除。
                % ----------------- 尝试使用实际的响应计算Rp,Rs：初步基于设定值，必要时用 actual 细化 -----------------
                % 先用设定值构造初步通带/阻带索引（与原逻辑类似）  
                Nyq = Fs/2;
                clip = @(x) max(0.0001, min(Nyq, double(x)));
                switch lower(ftype)
                    case '低通'
                        pass_idx0 = (freq <= clip(set_fp1));
                        stop_idx0 = (freq >= clip(set_fst1));
                    case '高通'
                        pass_idx0 = (freq >= clip(set_fp1));
                        stop_idx0 = (freq <= clip(set_fst1));
                    case '带通'
                        pass_idx0 = (freq >= clip(set_fp1) & freq <= clip(set_fp2));
                        stop_idx0 = (freq <= clip(set_fst1)) | (freq >= clip(set_fst2));
                    case '带阻'
                        pass_idx0 = (freq <= clip(set_fp1)) | (freq >= clip(set_fp2));
                        stop_idx0 = (freq >= clip(set_fst1) & freq <= clip(set_fst2));
                    otherwise
                        pass_idx0 = (freq <= clip(set_fp1));
                        stop_idx0 = (freq >= clip(set_fst1));
                end
                
                % 初步度量（以 pass_idx0 / stop_idx0 为准）
                try
                    if any(pass_idx0)
                        mag_pass0 = magdb(pass_idx0);
                        Rp_prelim = max(mag_pass0) - min(mag_pass0);
                    else
                        Rp_prelim = NaN;
                    end
                    if any(stop_idx0)
                        mag_stop0 = magdb(stop_idx0);
                        Rs_prelim = -max(mag_stop0);
                    else
                        Rs_prelim = NaN;
                    end
                catch
                    Rp_prelim = NaN; Rs_prelim = NaN;
                end
                
                % 尝试用 actual 边界细化：要求 actual 非 NaN 且在 (0,Nyq) 范围内
                % 以及边界顺序合理（如 actual_fp1 < actual_fp2 对带通）
                use_refined = false;
                try
                    switch lower(ftype)
                        case '低通'
                            if (~isnan(actual_fp1) && actual_fp1 > 0 && actual_fp1 < Nyq) && (~isnan(actual_fst1) && actual_fst1 > 0 && actual_fst1 < Nyq)
                                pass_idx_ref = (freq <= actual_fp1);
                                stop_idx_ref = (freq >= actual_fst1); 
                                use_refined = true;
                            end
                        case '高通'
                            if (~isnan(actual_fp1) && actual_fp1 > 0 && actual_fp1 < Nyq) && (~isnan(actual_fst1) && actual_fst1 > 0 && actual_fst1 < Nyq)
                                pass_idx_ref = (freq >= actual_fp1);
                                stop_idx_ref = (freq <= actual_fst1);
                                use_refined = true;
                            end
                        case '带通'
                            if (~isnan(actual_fp1) && ~isnan(actual_fp2) && actual_fp1>0 && actual_fp2>actual_fp1 && actual_fp2<Nyq) && (~isnan(actual_fst1) && ~isnan(actual_fst2) && actual_fst1>0 && actual_fst2>actual_fst1 && actual_fst2<Nyq)
                                pass_idx_ref = (freq >= actual_fp1 & freq <= actual_fp2);
                                stop_idx_ref = (freq <= actual_fst1) | (freq >= actual_fst2);
                                use_refined = true;
                            end
                        case '带阻'
                            if (~isnan(actual_fp1) && ~isnan(actual_fp2) && actual_fp1>0 && actual_fp2>actual_fp1 && actual_fp2<Nyq) && (~isnan(actual_fst1) && ~isnan(actual_fst2) && actual_fst1>0 && actual_fst2>actual_fst1 && actual_fst2<Nyq)
                                pass_idx_ref = (freq <= actual_fp1) | (freq >= actual_fp2);
                                stop_idx_ref = (freq >= actual_fst1 & freq <= actual_fst2);
                                use_refined = true;
                            end
                    end
                catch
                    use_refined = false;
                end
                
                % 如果 refined 可用，再次计算 Rp/Rs（并做对比或选择）
                if use_refined
                    try
                        if any(pass_idx_ref)
                            mag_pass_ref = magdb(pass_idx_ref);

                            % 可以以通带峰-峰纹波， peak-to-peak ripple in dB (>=0) 表示
                            % Rp_ref = max(mag_pass_ref) - min(mag_pass_ref);

                            % 可以以 "最大下限相对于 0 dB" 表示
                            Rp_ref = - min(mag_pass_ref);

                        else
                            Rp_ref = NaN;
                        end
                        if any(stop_idx_ref)
                            mag_stop_ref = magdb(stop_idx_ref);
                            Rs_ref = -max(mag_stop_ref);
                        else
                            Rs_ref = NaN;
                        end
                    catch
                        Rp_ref = NaN; Rs_ref = NaN;
                    end
                else
                    Rp_ref = NaN; Rs_ref = NaN;
                end
                
                % 最终选择：优先用 refined（如果合理），否则用初步值（或者两者都写出来供 UI 对比）
                if ~isnan(Rp_ref)
                    actual_Rp = Rp_ref;
                else
                    actual_Rp = Rp_prelim;
                end
                if ~isnan(Rs_ref)
                    actual_Rs = Rs_ref;
                else
                    actual_Rs = Rs_prelim;
                end
                % ----------------- 尝试使用实际的响应计算Rp,Rs：结束 -----------------






                % 若某些 crossing 未被 interp 找到，尝试用粗索引法兜底（保守取）
                % 兜底：避免把 DC (0 Hz) 作为边缘返回
                minPosIdx = find(freq > 0, 1, 'first');
                if isempty(minPosIdx), minPosFreq = 0; else; minPosFreq = freq(minPosIdx); end
                
                if isnan(actual_fp1)
                    idx = find(magdb >= thr_Rp & freq > minPosFreq, 1, 'last');
                    if ~isempty(idx)
                        actual_fp1 = freq(idx);
                    end
                end

                if isnan(actual_fp2)
                    idx = find(magdb >= thr_Rp, 1, 'first'); if ~isempty(idx), actual_fp2 = freq(idx); end
                end
                if isnan(actual_fst1)
                    idx = find(magdb <= thr_Rs, 1, 'first'); if ~isempty(idx), actual_fst1 = freq(idx); end
                end
                if isnan(actual_fst2)
                    idx = find(magdb <= thr_Rs, 1, 'last'); if ~isempty(idx), actual_fst2 = freq(idx); end
                end




            end  % 实际技术指标计算结束
            
        catch ME
            % 计算失败则保留 NaN（并不抛错，保证 UI 不崩）
            warning('onFilterMetrics:calcFail','计算实际技术指标失败：%s', ME.message);
        end



        % ----  10 行（增加 Ffc1、Ffc2），非适用项用 '-' 显示 ----
        % allItems 顺序必须与列构造一致：
        % fp1, fp2, Ifc1(-3dB), Ifc2(-3dB), Ffc1(-6dB), Ffc2(-6dB), fst1, fst2, Rp, Rs
        allItems = {'fp1(Hz)','fp2(Hz)','Ifc1(-3dB,Hz)','Ifc2(-3dB,Hz)','Ffc1(-6dB,Hz)','Ffc2(-6dB,Hz)','fst1(Hz)','fst2(Hz)','Rp(dB)','As(dB)'};
        
        % setValsAll / actValsAll 对应上面的顺序
        setValsAll = { set_fp1, set_fp2, set_Ifc1, set_Ifc2, set_Ffc1, set_Ffc2, set_fst1, set_fst2, set_Rp, set_Rs };
        actValsAll = { actual_fp1, actual_fp2, actual_Ifc1, actual_Ifc2, actual_Ffc1, actual_Ffc2, actual_fst1, actual_fst2, actual_Rp, actual_Rs };
        
        % Helper: mark by indices (更新为 10 个索引)
        IDX.fp1 = 1; IDX.fp2 = 2; IDX.Ifc1 = 3; IDX.Ifc2 = 4;
        IDX.Ffc1 = 5; IDX.Ffc2 = 6;
        IDX.fst1 = 7; IDX.fst2 = 8; IDX.Rp = 9; IDX.Rs = 10;


        % 读取设计方法 / 原型 / 窗类型 / 阶数（稳健读取）
        try designMethodStr = handles.ddDesignMethod.Value; catch; designMethodStr = ''; end
        try protoName = handles.ddIIRProto.Value; catch; protoName = ''; end
        try windowName = handles.ddWindow.Value; catch; windowName = ''; end
        try firOptMethod = handles.ddFIRMethod.Value; catch; firOptMethod = ''; end
        
        % 读取阶数（IIR / FIR），若取不到则视为自动（<=0）
        try iirOrderVal = round(double(handles.edtIIROrder.Value)); catch; iirOrderVal = -1; end
        try firOrderVal = round(double(handles.edtFIROrder.Value)); catch; firOrderVal = -1; end
        
        % 默认全部不显示（false） - index order now 1..10
        applicable = false(1,10);

        
        % 规范化字符串便于比较 (防止大小写/空格差异)
        ftype_n = lower(strtrim(ftype));
        proto_n = lower(strtrim(protoName));
        wind_n  = lower(strtrim(windowName));
        % firm_n  = lower(strtrim(firOptMethod));
        
        % -------- IIR 情况 --------
        if strcmpi(designMethodStr, 'IIR')
            if iirOrderVal <= 0
                % 自动估阶：按规则显示（低/高显示 fp1,fst1,Rp,Rs；带通/带阻显示全部）
                switch ftype_n
                    case {'低通','高通'}
                        applicable([IDX.fp1, IDX.fst1, IDX.Rp, IDX.Rs]) = true;
                    case {'带通','带阻'}
                        applicable(:) = true;
                    otherwise
                        applicable(:) = true;
                end
                % 另外：对于自动估阶（iirOrderVal <= 0）并且 proto 为 Butterworth，
                % 我们也希望把 fc 显示出来（因为设置值显示 buttord 的 Wn）
                if any(strcmpi(proto_n,{'butterworth','maxflat'}))
                    if any(strcmp(ftype_n,{'带通','带阻'}))
                        applicable([IDX.Ifc1, IDX.Ifc2]) = true;
                    else
                        applicable(IDX.Ifc1) = true;
                    end
                end

            else
                % 用户自定阶数：依据不同原型与滤波类型显示不同子集
                switch ftype_n
                    case {'低通','高通'}
                        switch proto_n
                            case 'butterworth'
                                applicable([IDX.fp1, IDX.Ifc1]) = true; % 低通/高通 只显示 Ifc1
                            case 'chebyshev i'
                                applicable([IDX.fp1, IDX.Rp]) = true;
                            case 'chebyshev ii'
                                applicable([IDX.fst1, IDX.Rs]) = true;
                            case 'elliptic'
                                applicable([IDX.fp1, IDX.Rp, IDX.Rs]) = true;
                            case 'yule-walker'
                                applicable([IDX.fp1, IDX.fst1, IDX.Rp, IDX.Rs]) = true;
                            case 'maxflat'
                                applicable([IDX.fp1, IDX.Ifc1]) = true; 
                            otherwise
                                applicable([IDX.fp1, IDX.Rp, IDX.Rs]) = true;
                        end
                    case {'带通','带阻'}
                        switch proto_n
                            case 'butterworth'
                                applicable([IDX.fp1, IDX.fp2, IDX.Ifc1, IDX.Ifc2]) = true;
                            case 'chebyshev i'
                                applicable([IDX.fp1, IDX.fp2, IDX.Rp]) = true;
                            case 'chebyshev ii'
                                applicable([IDX.fst1, IDX.fst2, IDX.Rs]) = true;
                            case 'elliptic'
                                applicable([IDX.fp1, IDX.fp2, IDX.Rp, IDX.Rs]) = true;
                            case 'yule-walker'
                                applicable([IDX.fp1, IDX.fp2, IDX.fst1, IDX.fst2, IDX.Rp, IDX.Rs]) = true;
                            case 'maxflat'
                                applicable([IDX.fp1, IDX.fp2, IDX.Ifc1, IDX.Ifc2]) = true; 
                                
                            otherwise
                                applicable(:) = true;
                        end
                    case {'多带/高级'}
                        applicable(:) = false;
                
                    otherwise
                        applicable(:) = true;
                end
            end

        
        % -------- FIR 窗函数法 或 FIR 优化设计法 或 FIR频率采样法--------
        elseif any(strcmpi(designMethodStr, {'FIR窗函数法','FIR优化设计法','FIR频率采样法'}))
            isFIRWindow = strcmpi(designMethodStr, 'FIR窗函数法');
            isFIROpt    = strcmpi(designMethodStr, 'FIR优化设计法');
            isFIRFnc    = strcmpi(designMethodStr, 'FIR频率采样法');
            simpleWindows = {'rectwin','triang','hann','hamming','blackman'};
        
            if isFIRWindow
                if firOrderVal <= 0
                    % FIR 窗自动估阶：只有 Kaiser 才显示完整的 fp/fst/Rp/Rs；简单窗只显示 fp（或 fp1,fp2）
                    % 自动估阶：只有 Kaiser 才显示 Ffc（-6dB），简单窗自动估阶一般不提供 Ffc
                    if any(strcmpi(wind_n, simpleWindows))
                        if any(strcmp(ftype_n, {'带通','带阻'}))
                            applicable([IDX.fp1, IDX.fp2]) = true;
                        else
                            applicable(IDX.fp1) = true;
                        end
                        % 不显示 Ffc（-6dB）除非为 Kaiser（自动）
                    elseif strcmpi(wind_n, 'kaiser')
                        if any(strcmp(ftype_n, {'带通','带阻'}))
                            applicable(:) = true;
                            % Kaiser 自动估阶时显示 Ffc1/Ffc2（自动计算得出设定值）
                            applicable([IDX.Ffc1, IDX.Ffc2]) = true;
                        else
                            applicable([IDX.fp1, IDX.fst1, IDX.Rp, IDX.Rs, IDX.Ffc1]) = true;
                        end
                    else
                        % 兜底：显示全部
                        applicable(:) = true;
                    end
                else
                    % FIR 窗 手动阶数：简单窗只显示 fp（或 fp1,fp2）；Kaiser 显示 fp1,Rp,Rs（低/高），带通/带阻显示 fp1,fp2,Rp,Rs
                    % 用户指定阶数：简单窗把 fp 当作 Ffc
                    if any(strcmpi(wind_n, simpleWindows))
                        if any(strcmp(ftype_n, {'带通','带阻'}))
                            applicable([IDX.fp1, IDX.fp2, IDX.Ffc1, IDX.Ffc2]) = true;
                        else
                            applicable([IDX.fp1, IDX.Ffc1]) = true;
                        end
                    elseif strcmpi(wind_n, 'kaiser')
                        if any(strcmp(ftype_n, {'带通','带阻'}))
                            applicable([IDX.fp1, IDX.fp2, IDX.Ffc1, IDX.Ffc2, IDX.Rp, IDX.Rs]) = true;
                        else
                            applicable([IDX.fp1, IDX.Ffc1, IDX.Rp, IDX.Rs]) = true;
                        end
                    else
                        applicable(:) = true;
                    end
                end
        
            elseif isFIROpt || isFIRFnc
                % FIR 优化设计法（Parks-McClellan / Cplx-Parks-McClellan / firls / fircls）
                % FIR频率采样法同样适用
                % 自动估阶与手动阶数在规则上相同
                if any(strcmp(ftype_n, {'带通','带阻'}))
                    applicable(:) = true;
                elseif any(strcmp(ftype_n, {'低通','高通'}))
                    applicable([IDX.fp1, IDX.fst1, IDX.Rp, IDX.Rs]) = true;
                elseif strcmp(ftype_n, {'多带/高级'})
                    applicable(:) = false;
                   
                end

            else
                % 兜底：全部显示
                applicable(:) = true;
            end
        
         % -------- 陷波 或 峰值滤波--------
        elseif any(strcmpi(designMethodStr, {'陷波','峰值滤波'}))
            applicable(:) = false;

        % -------- FIRintfilt插值 滤波--------
        elseif strcmpi(designMethodStr, 'FIRintfilt插值')
            applicable(:) = false;

        % -------- FIRgaussdesign脉冲整形 滤波--------
        elseif strcmpi(designMethodStr, 'FIRgaussdesign脉冲整形')
            applicable(:) = false;

        % -------- FIRrcosdesign脉冲整形 滤波--------
        elseif strcmpi(designMethodStr, 'FIRrcosdesign脉冲整形')
            applicable(:) = false;

        % -------- Savitzky-Golay 滤波--------
        elseif strcmpi(designMethodStr, 'Savitzky-Golay')
            applicable(:) = false;



            
        else
            % 未识别方法：兜底显示全部
            applicable(:) = true;
        end
        
        % 兼容性保护：如果 table 控件不存在，保守全部显示
        if ~isprop(handles,'filterMetricsComponents') || ...
           ~isfield(handles.filterMetricsComponents,'tbl') || ...
           isempty(handles.filterMetricsComponents.tbl) || ...
           ~isvalid(handles.filterMetricsComponents.tbl)
            applicable(:) = true;
        end
        

        
        % 构造表格（10 行固定）
        nShow = 10;
        tblData = cell(nShow, 3);
        for k = 1:nShow
            tblData{k,1} = allItems{k};
            if applicable(k)
                switch k
                    case {IDX.fp1, IDX.fp2, IDX.Ifc1, IDX.Ifc2, IDX.Ffc1, IDX.Ffc2, IDX.fst1, IDX.fst2}
                        try
                            tblData{k,2} = fmtFreqWithPi(setValsAll{k}, Fs);
                        catch
                            tblData{k,2} = '-';
                        end
                        try
                            tblData{k,3} = fmtFreqWithPi(actValsAll{k}, Fs);
                        catch
                            tblData{k,3} = '-';
                        end
                    case {IDX.Rp, IDX.Rs}
                        try
                            tblData{k,2} = fmtDb(setValsAll{k});
                        catch
                            tblData{k,2} = '-';
                        end
                        try
                            tblData{k,3} = fmtDb(actValsAll{k});
                        catch
                            tblData{k,3} = '-';
                        end
                    otherwise
                        tblData{k,2} = '-';
                        tblData{k,3} = '-';
                end
            else
                tblData{k,2} = '-';
                tblData{k,3} = '-';
            end
        end

        % ---- 强制把 tblData 中所有单元转换为字符（char），避免 uitable 强制类型转换导致显示异常）
        for ii = 1:size(tblData,1)
            for jj = 1:size(tblData,2)
                v = tblData{ii,jj};
                if isnumeric(v)
                    % 例如数值 0 被放进来时，转换为字符串
                    tblData{ii,jj} = num2str(v);
                elseif isstring(v)
                    tblData{ii,jj} = char(v);
                elseif ischar(v)
                    % already ok
                else
                    % 兜底：把其它类型转换为字符串
                    try
                        tblData{ii,jj} = char(string(v));
                    catch
                        tblData{ii,jj} = '-';
                    end
                end
            end
        end

        % 更新 uitable（固定 10 行）
        try
            handles.filterMetricsComponents.tbl.Data = tblData;
            handles.filterMetricsComponents.tbl.ColumnName = {'技术指标','设定值','实际值'};
        catch ME
            warning('onFilterMetrics:updateTblFail','更新指标表失败：%s', ME.message);
        end

        % ---- （技术指标显示与否决定块 结束） ----
    

        % 表格底部注释（多行 / 分点显示）
        noteText = sprintf(['注：\n' ...
                            '1. 数字角频率：ω = (2 * f / Fs) · π。\n' ...
                            '2. Ifc1(-3dB) 、 Ifc2(-3dB)为 IIR(Butterworth、maxflat) 幅值响应为 −3 dB 处的频率。\n' ...
                            '3. Ffc1(-6dB) 、 Ffc2(-6dB)为 FIR 窗函数法（Rectwin/Triang/Hann/Hamming/Blackman/Kaiser）的归一化增益为 -6 dB 处的频率。\n' ...
                            '4. 若某项不适用则以 "-" 表示。']);
        % 更新 label 文本（已保证 handles.filterMetricsComponents.lblNote 存在）
        if isfield(handles.filterMetricsComponents,'lblNote') && ~isempty(handles.filterMetricsComponents.lblNote) && isvalid(handles.filterMetricsComponents.lblNote)
            handles.filterMetricsComponents.lblNote.Text = noteText;
        else
            try
                lblN = uilabel(handles.filterMetricsFig, 'Text', noteText, 'Position', [10 12 880 80], 'HorizontalAlignment','left', 'WordWrap','on');
                handles.filterMetricsComponents.lblNote = lblN;
            catch
                % 若无法创建则忽略（兼容性保护）
            end
        end

        
        % -------------------------------------------------------------
        % ------------------------ 辅助函数部分 ------------------------
        % -------------------------------------------------------------
        % 辅助：线性插值计算 crossing 位置（索引 idx 表示 crossing 在 idx->idx+1）
        
        function fcross = interp_cross(freq, magdb, thr, direction, pass_mask, stop_mask, prefer)
            % Enhanced interp_cross with pass/stop proximity preference.
            % Signature:
            %   fcross = interp_cross(freq, magdb, thr, direction)
            %   fcross = interp_cross(freq, magdb, thr, direction, pass_mask)
            %   fcross = interp_cross(freq, magdb, thr, direction, pass_mask, stop_mask)
            %   fcross = interp_cross(..., prefer)  where prefer is 'pass' (default) or 'stop'
            %
            % Behavior summary:
            %  - Collect all crossing candidates via linear interpolation.
            %  - For each candidate check "后续稳定性" (L 点) or minimal width;标记 stable/un-stable。
            %  - If pass_mask/stop_mask provided, compute proximity to pass and stop regions.
            %  - Select candidate according to:
            %       1) prefer stable candidates (stable==true)
            %       2) among those, choose one with minimal proximity to the preferred region
            %       3) if none stable, relax to nearest-to-preferred among all candidates
            %  - Backward-compatible fallbacks are maintained.
            %
            % Notes:
            %  - pass_mask / stop_mask must be same length as freq (logical vector). If you pass
            %    a sliced freq (e.g. freq(startIdx:end)) you must pass correspondingly sliced masks.
            %  - prefer: 'pass' (default) chooses candidate nearest to pass region; 'stop' chooses
            %    candidate nearest to stop region.
            %
            fcross = NaN;
            try
                if isempty(freq) || isempty(magdb)
                    return;
                end
                freq = freq(:); magdb = magdb(:);
                N = numel(freq);
                if N < 2
                    return;
                end
        
                % normalize inputs
                if nargin < 7 || isempty(prefer)
                    prefer = 'pass';
                end
                if nargin < 6
                    stop_mask = [];
                end
                if nargin < 5
                    pass_mask = [];
                end
                have_pass = ~isempty(pass_mask) && numel(pass_mask)==N && any(pass_mask);
                have_stop = ~isempty(stop_mask) && numel(stop_mask)==N && any(stop_mask);
        
                % params (tunable)
                min_contig = max(3, round(0.001 * N));   % at least 0.1% points or 3
                min_width_Hz = max(1, (freq(end)-freq(1)) * 0.0005);
                L = min_contig;
                epsv = eps;
        
                % detect raw crossing candidate indices
                if strcmpi(direction,'fall')
                    candIdxs = find(magdb(1:end-1) > thr & magdb(2:end) <= thr);
                else
                    candIdxs = find(magdb(1:end-1) < thr & magdb(2:end) >= thr);
                end
        
                % build candidates (linear interpolation)
                candidates = struct('idx',{},'f',[]);
                for ii = candIdxs.'
                    y1 = magdb(ii); y2 = magdb(ii+1);
                    x1 = freq(ii); x2 = freq(ii+1);
                    if abs(y2-y1) < epsv
                        c = x1;
                    else
                        c = x1 + (thr - y1) * (x2 - x1) / (y2 - y1);
                    end
                    if isfinite(c) && c > 0
                        candidates(end+1).idx = ii; %#ok<AGROW>
                        candidates(end).f = c;
                    end
                end
        
                % fallback to original segment-based logic if no linear-candidate found
                if isempty(candidates)
                    if strcmpi(direction,'fall'), mask = (magdb <= thr); else; mask = (magdb >= thr); end
                    d = diff([0; mask; 0]);
                    starts = find(d==1);
                    if ~isempty(starts)
                        s = starts(1);
                        if s <= 1
                            fcross = freq(s);
                        else
                            y1 = magdb(s-1); y2 = magdb(s); x1 = freq(s-1); x2 = freq(s);
                            if abs(y2-y1) < epsv
                                fcross = x1;
                            else
                                fcross = x1 + (thr-y1)*(x2-x1)/(y2-y1);
                            end
                        end
                    else
                        fcross = NaN;
                    end
                    return;
                end
        
                % prepare pass/stop frequency arrays if present
                if have_pass
                    pass_freqs = freq(pass_mask);
                else
                    pass_freqs = [];
                end
                if have_stop
                    stop_freqs = freq(stop_mask);
                else
                    stop_freqs = [];
                end
        
                % evaluate each candidate: stability + proximities
                evals = struct('f',{},'stable',{},'p_to_pass',{},'p_to_stop',{},'origIdx',{});
                for k = 1:numel(candidates)
                    idx = candidates(k).idx;
                    c = candidates(k).f;
                    % stability check: after crossing should remain on the threshold side for L points
                    startChk = idx+1;
                    endChk = min(N, idx + L);
                    if startChk <= endChk
                        if strcmpi(direction,'fall')
                            stable = all(magdb(startChk:endChk) <= thr);
                        else
                            stable = all(magdb(startChk:endChk) >= thr);
                        end
                    else
                        stable = false;
                    end
                    segWidth = freq(min(N, idx+L)) - freq(max(1, idx-L));
                    if ~(stable || segWidth >= min_width_Hz)
                        stableFlag = false;
                    else
                        stableFlag = true;
                    end
        
                    % proximity measures (distance to nearest pass/stop freq)
                    p_pass = Inf; p_stop = Inf;
                    if ~isempty(pass_freqs)
                        p_pass = min(abs(pass_freqs - c));
                    end
                    if ~isempty(stop_freqs)
                        p_stop = min(abs(stop_freqs - c));
                    end
        
                    evals(end+1).f = c; %#ok<AGROW>
                    evals(end).stable = stableFlag;
                    evals(end).p_to_pass = p_pass;
                    evals(end).p_to_stop = p_stop;
                    evals(end).origIdx = idx;
                end
        
                % selection strategy:
                % prefer stable candidates; among them choose minimal proximity to 'prefer' region
                pickIdx = [];
                stable_idxs = find([evals.stable]);
                if ~isempty(stable_idxs)
                    if strcmpi(prefer,'stop') && ~isempty(stop_freqs)
                        [~,Rel] = min([evals(stable_idxs).p_to_stop]);
                        pickIdx = stable_idxs(Rel);
                    elseif strcmpi(prefer,'pass') && ~isempty(pass_freqs)
                        [~,Rel] = min([evals(stable_idxs).p_to_pass]);
                        pickIdx = stable_idxs(Rel);
                    else
                        % prefer stable but no region info -> first stable
                        pickIdx = stable_idxs(1);
                    end
                else
                    % no stable candidates: choose nearest to preferred region if available, else first candidate
                    if strcmpi(prefer,'stop') && ~isempty(stop_freqs)
                        [~,Rel] = min([evals.p_to_stop]);
                        pickIdx = Rel;
                    elseif strcmpi(prefer,'pass') && ~isempty(pass_freqs)
                        [~,Rel] = min([evals.p_to_pass]);
                        pickIdx = Rel;
                    else
                        pickIdx = 1;
                    end
                end
        
                if ~isempty(pickIdx) && pickIdx>=1 && pickIdx<=numel(evals)
                    fcross = evals(pickIdx).f;
                    return;
                end
        
            catch
                fcross = NaN;
                return;
            end
        end

        % ---- 格式化显示 Hz 与 数字角频率(π)，保持 6 行，非适用显示 '-' ----
        % helper: 把频率 (Hz) -> "xxx Hz (yyyπ)" 字符串
        function s = fmtFreqWithPi(valHz, Fs_local)
            % valHz: 数值或可转为数的类型
            if isempty(valHz)
                s = '-'; return;
            end
            if ~isnumeric(valHz)
                v = str2double(valHz);
            else
                v = double(valHz);
            end
            if isempty(v) || isnan(v) || ~isfinite(v)
                s = '-'; return;
            end
            if ~isempty(Fs_local) && ~isnan(Fs_local) && Fs_local > 0
                % 归一化到 π 单位： W/pi = 2*f/Fs
                W_over_pi = 2 * v / double(Fs_local);
                % 显示：Hz (W/π π) 例如 "1250 Hz (0.200π)"
                s = sprintf('%.6g Hz (%.4gπ)', v, W_over_pi);
            else
                s = sprintf('%.6g Hz', v);
            end
        end
        
        % helper: 把 dB (Rp, Rs) -> "xx dB" 或 '-' 
        function s = fmtDb(valDb)
            if isempty(valDb)
                s = '-'; return;
            end
            if ~isnumeric(valDb)
                v = str2double(valDb);
            else
                v = double(valDb);
            end
            if isempty(v) || isnan(v) || ~isfinite(v)
                s = '-';
            else
                s = sprintf('%.4g dB', v);
            end
        end

    end

    %% ---- 显示/复用 "滤波器单位冲激响应" 窗口（只绘制当前 S.filter_b / S.filter_a） ---- 
    function onImpulseResponse(S, handles, fig_GUI)
    % 传入的 handle类 S, handles; 主界面 fig_GUI
    % 对 S 的对象内容有 "读" 操作，无 "写" 操作
    % 对 handles 的对象内容有 "读/写" 操作
    % fig_GUI 用于uialert_safe()在主界面弹提醒窗口
    
        % 检查是否存在已设计的滤波器参数
        if isempty(S.filter_b) || isempty(S.filter_a)
            uialert_safe(fig_GUI, '请先设计滤波器。', '操作错误');
            setStatus(handles,'查看单位冲激响应失败：无滤波器参数');
            return;
        end
    
        % 若已存在并有效，则提到最前面并复用
        try
            figI = handles.impulseFig;
            if ~isempty(figI) && isvalid(figI)
                try createCenteredFigure(figI); catch; end
            else
                % 创建复用 uifigure 窗口并保存句柄
                figI = createCenteredUIFigure('Name', '滤波器单位冲激响应', 'Position', [260 140 900 560]);
                figI.Resize = 'on';
                handles.impulseFig = figI;
    
                % 创建组件容器并保存（一个 axes + 说明 label）
                comps = struct();
                comps.ax = uiaxes(figI, 'Position', [40 80 820 420]);
                comps.ax.Box = 'on';
                comps.ax.XGrid = 'on';
                comps.ax.YGrid = 'on';
                comps.lbl = uilabel(figI, 'Text', '', 'Position', [20 20 860 40], 'HorizontalAlignment', 'right', 'WordWrap', 'on');
                handles.impulseComponents = comps;
            end
        catch ME
            % 若创建/复用窗口失败，则提示但不崩溃
            warning('onImpulseResponse:WindowCreateFailed', '创建/复用单位冲激响应窗口失败: %s', ME.message);
            uialert_safe(fig_GUI, ['无法打开单位冲激响应窗口: ' ME.message], '错误');
            return;
        end
    
        % 绘制：只绘制当前滤波器参数的单位冲激响应（覆盖旧图）
        axImp = handles.impulseComponents.ax;
        try
            cla(axImp);
            b = S.filter_b(:).'; a = S.filter_a(:).';
            % 基本健壮性检查
            if any(~isfinite(b)) || any(~isfinite(a))
                error('滤波器系数包含非有限值');
            end
    
            % 检查稳定性（若非稳定，警告并限制样本数）
            poles = roots(a);
            unstable = any(abs(poles) >= 1);
            order = max(length(b)-1, length(a)-1);
            % 自适应样点数（可根据需要调整上下限）
            Nimp = max(256, 4*order);
            Nimp = min(Nimp, 8192); % 上限以防内存/绘图卡顿
    
            if unstable
                % 若不稳定，缩短样点数并提示
                Nimp = min(Nimp, 512);
                % 计算冲激响应
                [h, t] = impz(b, a, Nimp, S.fs);  % t 单位为秒
                uialert_safe(fig_GUI, '警告：当前滤波器可能不稳定。绘制已限制样点数以防发散。', '警告',"Icon","warning");
            else

                % 计算冲激响应（优先使用 impz 的显式 n）
                [h, t] = impz(b, a, [], S.fs);  % t 单位为秒
            end
    

            % 在绘图前：
            if ~isreal(h)
                % 解析信号：默认绘制幅度（可改为 real/imag）
                plotData = abs(h);
                plotYLabel = '|h| (复数信号幅度)';
            else
                plotData = h;
                plotYLabel = '振幅';
            end
            % 使用 plotData 替代原有 h 进行绘图，并把 plotYLabel 写到 ylabel
            % 若数据点很多，使用线图；否则使用 stem
            if numel(h) <= 2000
                stem(axImp, t, plotData, 'filled');
            else
                plot(axImp, t, plotData);
            end
            grid(axImp, 'on');
            title(axImp, '滤波器单位冲激响应 (当前滤波器)');
            xlabel(axImp, '时间 (s)');
            ylabel(axImp, plotYLabel);
            xlim(axImp, [0, t(end)]);
            nOrder = order;
            handles.impulseComponents.lbl.Text = sprintf('采样率: %d Hz, 滤波器阶数: %d, 样点数: %d', S.fs, nOrder, numel(h));
            drawnow;pause(0.01);
        catch ME
            cla(axImp);
            title(axImp, '单位冲激响应绘制错误');
            text(axImp, 0.5, 0.5, '绘制失败', 'HorizontalAlignment', 'center');
            setStatus(handles,sprintf('onImpulseResponse 绘制错误: %s', ME.message));
            fprintf('onImpulseResponse 绘制错误: %s\n', ME.message);
        end
    end

    %% ---- 显示/复用 "滤波器单位阶跃响应" 窗口（只绘制当前 S.filter_b / S.filter_a） ---- 
    function onStepResponse(S, handles, fig_GUI)
    % 传入的 handle类 S, handles; 主界面 fig_GUI
    % 对 S 的对象内容有 "读" 操作，无 "写" 操作
    % 对 handles 的对象内容有 "读/写" 操作
    % fig_GUI 用于uialert_safe()在主界面弹提醒窗口

        % 检查是否存在已设计的滤波器系数
        if  ~isprop(S, 'filter_b') || isempty(S.filter_b) || ~isprop(S, 'filter_a') || isempty(S.filter_a)
            if exist('uialert_safe', 'file')
                uialert_safe(fig_GUI, '未找到已设计的滤波器系数，请先点击 "设计滤波器"。', '无滤波器');
            else
                uialert(fig_GUI, '未找到已设计的滤波器系数，请先点击 "设计滤波器"。', '无滤波器');
            end
            return;
        end

        % 检查采样率 S.fs 是否存在（stepz 需要 fs）
        if ~isprop(S,'fs') || isempty(S.fs) || ~(isnumeric(S.fs) && S.fs>0)
            if exist('uialert_safe','file')
                uialert_safe(fig_GUI, '请先在设置中指定采样率 S.fs（必须）以使用 stepz。', '缺少采样率');
            else
                uialert(fig_GUI, '请先在设置中指定采样率 S.fs（必须）以使用 stepz。', '缺少采样率');
            end
            return;
        end
    
        % 复用已存在窗口（优先复用）
        if isprop(handles, 'stepRespFig') && ~isempty(handles.stepRespFig) && isvalid(handles.stepRespFig)
            figS = handles.stepRespFig;
            figS.Visible = 'on';
            try createCenteredFigure(figS); catch; end
        else
            % 创建 uifigure 窗口并保存句柄
            figS = createCenteredUIFigure('Name', '滤波器单位阶跃响应', 'Position', [300 160 900 560]);
            figS.Resize = 'on';
            handles.stepRespFig = figS;
    
            % 创建组件容器并保存
            comps = struct();
            comps.ax = uiaxes(figS, 'Position', [50 90 800 420]);
            comps.ax.Box = 'on';
            comps.ax.XGrid = 'on';
            comps.ax.YGrid = 'on';
            comps.lbl = uilabel(figS, 'Text', '', 'Position', [20 20 860 40], 'HorizontalAlignment', 'right', 'WordWrap', 'on');
            handles.stepRespComponents = comps;
        end
    
        % 绘制：只绘制当前滤波器的单位阶跃响应
        axSR = handles.stepRespComponents.ax;
        try
            cla(axSR);
    
            b = S.filter_b(:).'; a = S.filter_a(:).';
            % 基本健壮性检查
            if any(~isfinite(b)) || any(~isfinite(a))
                error('滤波器系数包含非有限值');
            end

            % 检查稳定性（若非稳定，警告并限制样本数）
            poles = roots(a);
            unstable = any(abs(poles) >= 1);
            order = max(length(b)-1, length(a)-1);
            % 自适应样点数（可根据需要调整上下限）
            Nstep = max(256, 4*order);
            Nstep = min(Nstep, 8192); % 上限以防内存/绘图卡顿
    
            if unstable
                % 若不稳定，缩短样点数并提示
                Nstep = min(Nstep, 512);
                % 计算阶跃响应
                [h_vals, t_vals] = stepz(b, a, Nstep, S.fs);
                uialert_safe(fig_GUI, '警告：当前滤波器可能不稳定。绘制已限制样点数以防发散。', '警告',"Icon","warning");
            else
                % 仅用 stepz 计算：h (样点), t (以秒为单位，间隔 1/S.fs)。（优先使用 stepz 的显式 n）
                [h_vals, t_vals] = stepz(b, a, [], S.fs);
            end
            
            % 在绘图前：
            if ~isreal(h_vals)
                % 解析信号：默认绘制幅度（可改为 real/imag）
                plotData = abs(h_vals);
                plotYLabel = '|h| (复数信号幅度)';
            else
                plotData = h_vals;
                plotYLabel = '振幅';
            end
            % 使用 plotData 替代原有 h_vals 进行绘图，并把 plotYLabel 写到 ylabel 
            % 若数据点很多，使用线图；否则使用 stem
            if numel(h_vals) <= 2000
                stem(axSR, t_vals, plotData, 'filled');
            else
                plot(axSR, t_vals, plotData);
            end
            grid(axSR, 'on');
            title(axSR, '滤波器单位阶跃响应 (stepz)');
            xlabel(axSR, '时间 (s)');
            ylabel(axSR, plotYLabel);
            
    
            % 底部说明：采样率与滤波器阶数
            nOrder = max(length(b)-1, length(a)-1);
            handles.stepRespComponents.lbl.Text = sprintf('采样率: %d Hz, 滤波器阶数: %d, 绘制点数: %d', S.fs, nOrder, numel(h_vals));

        catch ME
            cla(axSR);
            title(axSR, '单位阶跃响应绘制错误');
            text(axSR, 0.5, 0.5, '绘制失败', 'HorizontalAlignment', 'center');
            setStatus(handles,sprintf('onStepResponse 绘制错误: %s', ME.message));
            fprintf('onStepResponse 绘制错误: %s\n', ME.message);
        end
    end

    %% ---- 显示/复用"滤波器群延迟"窗口（只绘制当前 S.filter_b / S.filter_a） ---- 
    function onGroupDelay(S, handles, fig_GUI)
    % 传入的 handle类 S, handles; 主界面 fig_GUI
    % 对 S 的对象内容有 "读" 操作，无 "写" 操作
    % 对 handles 的对象内容有 "读/写" 操作
    % fig_GUI 用于uialert_safe()在主界面弹提醒窗口

        % 显示/复用"滤波器群延迟"窗口，仅绘制当前 S.filter_b / S.filter_a 的群延迟
        % 保护检查：必须存在已设计滤波器系数
        if  ~isprop(S, 'filter_b') || isempty(S.filter_b) || ~isprop(S, 'filter_a') || isempty(S.filter_a)
            % 使用你项目中安全的提示函数（保持与其它处相同的风格）
            if exist('uialert_safe', 'file')
                uialert_safe(fig_GUI, '未找到已设计的滤波器系数，请先点击 "设计滤波器"。', '无滤波器');
            else
                uialert(fig_GUI, '未找到已设计的滤波器系数，请先点击 "设计滤波器"。', '无滤波器');
            end
            return;
        end
    
        % 复用已存在窗口（优先复用，不新建多个）
        if isprop(handles, 'groupDelayFig') && ~isempty(handles.groupDelayFig) && isvalid(handles.groupDelayFig)
            figG = handles.groupDelayFig;
            figG.Visible = 'on';
            try createCenteredFigure(figG); catch; end
        else
            % 创建 uifigure 窗口并保存句柄
            figG = createCenteredUIFigure('Name', '滤波器群延迟', 'Position', [260 140 900 560]);
            figG.Resize = 'on';
            handles.groupDelayFig = figG;
    
            % 创建组件容器结构并保存
            comps = struct();
            comps.ax = uiaxes(figG, 'Position', [40 80 820 420]);
            comps.ax.Box = 'on';
            comps.ax.XGrid = 'on';
            comps.ax.YGrid = 'on';
            comps.lbl = uilabel(figG, 'Text', '', 'Position', [20 20 860 40], 'HorizontalAlignment', 'right', 'WordWrap', 'on');
            handles.groupDelayComponents = comps;
        end
    
        % 绘制：只绘制当前滤波器的群延迟（清空 axes）
        axGrpDelay = handles.groupDelayComponents.ax;
        plotSettings = handles.plotSettings;  % 获取绘图参数
        try
            cla(axGrpDelay);
            b = S.filter_b(:).'; a = S.filter_a(:).';

            nfft_filt = max(1, plotSettings.filterSpecNFFT);
            % 使用 grpdelay，生成频率向量（0..fs）
            if strcmp(plotSettings.specFreqSide, 'double')
                [gd, f] = grpdelay(b, a, nfft_filt, 'whole', S.fs);
            else
                [gd, f] = grpdelay(b, a, nfft_filt, S.fs);
            end

            % 归一化频率（如果选了归一化显示）
            if isfield(plotSettings,'specFreqNormalized') && plotSettings.specFreqNormalized
                f = f / S.fs *2; % 2*pi*f/fs；横坐标为归一化频率 (xπ rad/sample)
            end

            % 绘图：处理 log 轴
            axes(axGrpDelay);
            if strcmpi(plotSettings.specFreqScale,'log')
                f_plot = f;
                gd_plot = gd;
                % 去掉 0 频点以避免 log(0)
                if any(f_plot==0)
                    idx0 = f_plot==0;
                    f_plot(idx0) = [];
                    gd_plot(idx0,:) = [];
                end 
                plot(axGrpDelay, f_plot, gd_plot);
                set(axGrpDelay,'XScale','log');
            else
                plot(axGrpDelay, f, gd);
                set(axGrpDelay,'XScale','linear');
            end
            grid(axGrpDelay,'on');
            title(axGrpDelay, '滤波器群延迟(当前滤波器)');
            xlabel(axGrpDelay, getSpecXLabel(plotSettings));
            ylabel(axGrpDelay, '群延迟 (样点)');
            if plotSettings.specFreqNormalized
                if strcmpi(plotSettings.specFreqSide,'double'), xlim(axGrpDelay,[0,2]); else; xlim(axGrpDelay,[0,1]); end
            else
                if strcmpi(plotSettings.specFreqSide,'double'), xlim(axGrpDelay,[0,S.fs]); else; xlim(axGrpDelay,[0,S.fs/2]); end
            end

            % 更新底部说明（示例：显示当前采样率与滤波器阶数）
            nOrder = max(length(b)-1, length(a)-1);
            handles.groupDelayComponents.lbl.Text = sprintf('采样率: %d Hz, 滤波器阶数: %d', S.fs, nOrder);
        catch ME
            cla(axGrpDelay);
            title(axGrpDelay, '群延迟绘制错误');
            text(axGrpDelay, 0.5, 0.5, '群延迟绘制失败', 'HorizontalAlignment', 'center');
            setStatus(handles,sprintf('onGroupDelay 绘制错误: %s', ME.message));
            fprintf('onGroupDelay 绘制错误: %s\n', ME.message);
        end
    
    end

    %% ---- 显示/复用"滤波器相位延迟"窗口（只绘制当前 S.filter_b / S.filter_a） ---- 
    function onPhaseDelay(S, handles, fig_GUI)
