            nfft_filt = max(1, plotSettings.filterSpecNFFT);
            % 使用 grpdelay，生成频率向量（0..fs）
            if strcmp(plotSettings.specFreqSide, 'double')
                [phi,freq] = phasedelay(b, a, nfft_filt, 'whole', S.fs);
            else
                [phi,freq] = phasedelay(b, a, nfft_filt, S.fs);
            end

            % 归一化频率（如果选了归一化显示）
            if isfield(plotSettings,'specFreqNormalized') && plotSettings.specFreqNormalized
                freq = freq / S.fs *2; % 2*pi*f/fs；横坐标为归一化频率 (xπ rad/sample)
            end

            % 绘图：处理 log 轴
            axes(axPD);
            if strcmpi(plotSettings.specFreqScale,'log')
                f_plot = freq;
                phi_plot = phi;
                % 去掉 0 频点以避免 log(0)
                if any(f_plot==0)
                    idx0 = f_plot==0;
                    f_plot(idx0) = [];
                    phi_plot(idx0,:) = [];
                end 
                plot(axPD, f_plot, phi_plot);
                set(axPD,'XScale','log');
            else
                plot(axPD, freq, phi);
                set(axPD,'XScale','linear');
            end
            grid(axPD,'on');
            title(axPD, '滤波器相位延迟 (当前滤波器)');
            xlabel(axPD, getSpecXLabel(plotSettings));
            if isfield(plotSettings,'specFreqNormalized') && plotSettings.specFreqNormalized
                ylabel(axPD, '相位延迟 (采样)');
            else
                ylabel(axPD, '相位延迟 (rad / Hz)');
            end
            if plotSettings.specFreqNormalized
                if strcmpi(plotSettings.specFreqSide,'double'), xlim(axPD,[0,2]); else; xlim(axPD,[0,1]); end
            else
                if strcmpi(plotSettings.specFreqSide,'double'), xlim(axPD,[0,S.fs]); else; xlim(axPD,[0,S.fs/2]); end
            end
      
            % 更新底部说明（示例：显示当前采样率与滤波器阶数）
            nOrder = max(length(b)-1, length(a)-1);
            handles.phaseDelayComponents.lbl.Text = sprintf('采样率: %d Hz, 滤波器阶数: %d', S.fs, nOrder);
        catch ME
            cla(axPD);
            title(axPD, '相位延迟绘制错误');
            text(axPD, 0.5, 0.5, '绘制失败', 'HorizontalAlignment', 'center');
            setStatus(handles,sprintf('onPhaseDelay 绘制错误: %s', ME.message));
            fprintf('onPhaseDelay 绘制错误: %s\n', ME.message);
        end
    end

    %% ---- 显示/复用 "滤波器零极点图" 窗口（只绘制当前 S.filter_b / S.filter_a） ---- 
    function onPoleZeroPlot(S, handles, fig_GUI)
    % 传入的 handle类 S, handles; 主界面 fig_GUI
    % 对 S 的对象内容有 "读" 操作，无 "写" 操作
    % 对 handles 的对象内容有 "读/写" 操作
    % fig_GUI 用于uialert_safe()在主界面弹提醒窗口

    % 说明：
    % - 使用 zplane 优先绘制（若可用），失败时退回手工绘制
    % - 采用方案：默认视区仍保持以单位圆/附近为主（uiDefaultCap），但对
    %   超出视区的零/极在边界处标注其模长，避免"完全丢失"信息
    % - 关键替换区域：lim 的计算与超出范围(root)的边界标注

        % 检查是否存在已设计的滤波器系数
        if  ~isprop(S, 'filter_b') || isempty(S.filter_b) || ~isprop(S, 'filter_a') || isempty(S.filter_a)
            if exist('uialert_safe', 'file')
                uialert_safe(fig_GUI, '未找到已设计的滤波器系数，请先点击 "设计滤波器"。', '无滤波器');
            else
                uialert(fig_GUI, '未找到已设计的滤波器系数，请先点击 "设计滤波器"。', '无滤波器');
            end
            return;
        end
    
        % 复用已存在窗口（优先复用）
        if isprop(handles, 'pzFig') && ~isempty(handles.pzFig) && isvalid(handles.pzFig)
            figPZ = handles.pzFig;
            figPZ.Visible = 'on';
            try createCenteredFigure(figPZ); catch; end
        else
            % 创建 uifigure 窗口并保存句柄
            figPZ = createCenteredUIFigure('Name', '滤波器零极点图', 'Position', [280 160 700 560]);
            figPZ.Resize = 'on';
            handles.pzFig = figPZ;
    
            % 创建 axes 和辅助组件
            comps = struct();
            comps.ax = uiaxes(figPZ, 'Position', [40 80 620 420]);
            comps.ax.Box = 'on';
            comps.ax.XGrid = 'on';
            comps.ax.YGrid = 'on';
            comps.lbl = uilabel(figPZ, 'Text', '', 'Position', [20 20 660 40], 'HorizontalAlignment', 'right','WordWrap','on');
            handles.pzComponents = comps;
        end
    
        % 绘制：只绘制当前滤波器的零极点（清空 axes）
        axPZ = handles.pzComponents.ax;
        try
            cla(axPZ);
    
            b = S.filter_b(:).'; a = S.filter_a(:).';
            % 计算零与极（列向量）
            z = roots(b);
            p = roots(a);
            z = z(:); p = p(:);
    
            % === 优先使用 zplane 绘制到指定轴（若支持） ===
            
            try
                % 注意：不同 MATLAB 版本/工具箱组合对 zplane 的签名支持不同，
                % 这里尝试 zplane(z,p,AX)；若失败会进入 catch 回退。
                [hz, hp, hunit] = zplane(z, p, axPZ);
                % 尝试美化标记（若返回句柄）
                if ~isempty(hz)
                    try set(hz, 'Marker', 'o', 'MarkerSize', 8, 'LineWidth', 1.2,'MarkerEdgeColor', 'm'); catch; end
                end
                if ~isempty(hp)
                    try set(hp, 'Marker', 'x', 'MarkerSize', 8, 'LineWidth', 1.5,'MarkerEdgeColor', 'g'); catch; end
                end
                if exist('hunit','var') && ~isempty(hunit)
                    try set(hunit, 'LineStyle', '--', 'LineWidth', 0.8); catch; end
                end
                drawSucceeded = true;
            catch zplaneME
                % 若 zplane 绘制到 uiaxes 失败（不同版本/兼容性问题），记录并退回手工绘制
                fprintf('zplane 绘制失败，回退到手工绘制。错误：%s\n', zplaneME.message);
                drawSucceeded = false;
            end
    
            % === fallback：如果 zplane 不可用或失败，用手工绘制逻辑 ===
            if ~drawSucceeded
                % 绘制单位圆
                t = linspace(0, 2*pi, 400);
                unitx = cos(t); unity = sin(t);
                hold(axPZ, 'on');
    
                % 单位圆
                plot(axPZ, unitx, unity, '--', 'LineWidth', 0.8);
    
                % 绘制零点（o）与极点（x）
                if ~isempty(z)
                    plot(axPZ, real(z), imag(z), 'o', 'MarkerSize', 8, 'LineWidth', 1.2,'MarkerEdgeColor', 'm');
                end
                if ~isempty(p)
                    plot(axPZ, real(p), imag(p), 'x', 'MarkerSize', 8, 'LineWidth', 1.5,'MarkerEdgeColor', 'y');
                end
                hold(axPZ, 'off');
            end
    
            % === 计算视区 lim（默认聚焦单位圆/附近），并对超出范围的根做边界标注 ===
            try
                allRoots = [z; p];
                if isempty(allRoots)
                    rmax = 0;
                else
                    rmax = max(abs(allRoots));
                    if ~isfinite(rmax) || isnan(rmax)
                        rmax = 0;
                    end
                end
    
                % 默认视区：至少覆盖单位圆并留 10% 空白
                defaultLim = max(1.2, 1.1 * rmax);
    
                % uiDefaultCap 为默认 UI 最大显示范围（聚焦常见单位圆附近）
                % 若想改变默认聚焦（更倾向显示更大范围），可把 uiDefaultCap 提高
                uiDefaultCap = 3;
                lim = min(defaultLim, uiDefaultCap);
    
            catch
                lim = 1.2;
            end
    
            % 设置等比坐标与网格
            axis(axPZ, 'equal');
            grid(axPZ, 'on');
            xlabel(axPZ, '实部');
            ylabel(axPZ, '虚部');
            title(axPZ, '滤波器零极点图 (当前滤波器)');
    
            % 设置主视区（覆盖单位圆并留白）
            xlim(axPZ, [-lim lim]);
            ylim(axPZ, [-lim lim]);
    
            % === 对接近或超出边界的根做标注（分别区分零点/极点） ===
            try
                % 标注阈值选为 0.95*lim（接近边缘或超出都会标注）
                if ~isempty(allRoots)
                    % 分别查找零点与极点中接近/超出边界的索引
                    z_oob_idx = find(abs(z) > lim * 0.95);
                    p_oob_idx = find(abs(p) > lim * 0.95);
                    
                    % 小偏移用于文本，避免与标记完全重叠
                    txtOffset = 0.01 * lim;

                    hold(axPZ, 'on');
                    % 零点（标为洋红色圆环 'o'，文本前缀 z|）
                    for ii = 1:numel(z_oob_idx)
                        rt = z(z_oob_idx(ii));
                        ang = angle(rt);
                        r = abs(rt);
                        xb = cos(ang) * lim;
                        yb = sin(ang) * lim;
                        % 在边界上画标记（圆形，空心）
                        plot(axPZ, xb, yb, 'o', 'MarkerSize', 8, 'LineWidth', 1.2, ...
                             'MarkerEdgeColor', 'm', 'MarkerFaceColor', 'none');
                        % 文本显示真实模长并标注为零点
                        text(axPZ, xb+txtOffset, yb+txtOffset, sprintf(' |z|=%.3g', r), 'FontSize', 9, ...
                             'HorizontalAlignment', 'left', 'VerticalAlignment', 'bottom', 'Color', 'm');
                    end

                    % 极点（标为红色叉 'x'，文本前缀 p|）
                    for ii = 1:numel(p_oob_idx)
                        rt = p(p_oob_idx(ii));
                        ang = angle(rt);
                        r = abs(rt);
                        xb = cos(ang) * lim;
                        yb = sin(ang) * lim;
                        % 在边界上画标记（叉形）
                        plot(axPZ, xb, yb, 'x', 'MarkerSize', 8, 'LineWidth', 1.5, ...
                             'Color', 'g');
                        % 文本显示真实模长并标注为极点
                        text(axPZ, xb+txtOffset, yb+txtOffset, sprintf(' |p|=%.3g', r), 'FontSize', 9, ...
                             'HorizontalAlignment', 'left', 'VerticalAlignment', 'bottom', 'Color', 'g');
                    end
                    hold(axPZ, 'off');
                end
            catch annME
                % 注释失败不影响主流程
                fprintf('零极点边界注释失败：%s\n', annME.message);
            end

            % 底部说明：采样率与阶数、零极点数
            nOrder = max(length(b)-1, length(a)-1);
            handles.pzComponents.lbl.Text = sprintf('"o"表示零点，"x"表示极点\n 采样率: %d Hz, 滤波器阶数: %d, 零点数: %d, 极点数: %d', S.fs, nOrder, numel(z), numel(p));
        catch ME
            cla(axPZ);
            title(axPZ, '零极点绘制错误');
            text(axPZ, 0.5, 0.5, '绘制失败', 'HorizontalAlignment', 'center');
            setStatus(handles,sprintf('onPoleZeroPlot 绘制错误: %s', ME.message));
            fprintf('onPoleZeroPlot 绘制错误: %s\n', ME.message);
        end
    
    end

    %% ---- "保存图像"按钮回调（严格模态参数设置窗口） ----
    function onOpenSaveFiguresDialog(~, ~)
        % 严格模态窗口（N行6列），实现用户提出的全部复选框/联动逻辑
        dlg_savefig = createCenteredUIFigure('Name','保存图像设置','WindowStyle','modal','Position',[400 240 660 520]);
    
        gl_savefig = uigridlayout(dlg_savefig, [10, 6]);
        % 行高/列宽
        gl_savefig.RowHeight = {'fit', '1x', '1x', '1x', '1x', '1x', '1x', '1x', '1x', '1x'};
        gl_savefig.ColumnWidth = {120, '1x', '1x', 120, '1x', '1x'};
        gl_savefig.Padding = [8 8 8 8];
    
        % ---------------- 1行 [1 6] 文本说明区域 ----------------
        lblEx = uilabel(gl_savefig,'FontWeight','bold');
        lblEx.Text = sprintf([...
            '请选择要保存的图像。注：（1）保存时只会保存被勾选项。（2）若某项无数据，此项不能被勾选。\n' ]); 
        lblEx.WordWrap='on'; lblEx.Layout.Row=1; lblEx.Layout.Column=[1 6];

        % ---------------- 2行 主复选框：保存所有图像 ----------------
        saveAllCb = uicheckbox(gl_savefig, 'Text', '保存所有图像', 'Value', false);
        saveAllCb.Layout.Row = 2; saveAllCb.Layout.Column = [1 6];
    
        % Rest cells 2..6 作为占位（或你可放路径选择选项）
        % ---------------- 3行：保存原始信号图像 ----------------
        lblSaveOrigSignalFig = uilabel(gl_savefig, 'Text', '保存原始信号图像：', 'HorizontalAlignment', 'left');
        lblSaveOrigSignalFig.Layout.Row = 3; lblSaveOrigSignalFig.Layout.Column = 1;
        origTimeCb = uicheckbox(gl_savefig, 'Text','时域波形','Value', false);
        origTimeCb.Layout.Row = 3; origTimeCb.Layout.Column = 2;
        origSpecCb = uicheckbox(gl_savefig, 'Text','幅频特性','Value', false);
        origSpecCb.Layout.Row = 3; origSpecCb.Layout.Column = 3;
    
        % ---------------- 4行：保存加噪信号图像 ----------------
        lblSaveNoisyFig = uilabel(gl_savefig, 'Text', '保存加噪信号图像：', 'HorizontalAlignment', 'left');
        lblSaveNoisyFig.Layout.Row = 4; lblSaveNoisyFig.Layout.Column = 1;
        noisyTimeCb = uicheckbox(gl_savefig, 'Text','时域波形','Value', false);
        noisyTimeCb.Layout.Row = 4; noisyTimeCb.Layout.Column = 2;
        noisySpecCb = uicheckbox(gl_savefig, 'Text','幅频特性','Value', false);
        noisySpecCb.Layout.Row = 4; noisySpecCb.Layout.Column = 3;
    
        % ---------------- 5行：保存滤波后信号图像 ----------------
        lblSaveFilteredFig = uilabel(gl_savefig, 'Text', '保存滤波后信号图像：', 'HorizontalAlignment', 'left');
        lblSaveFilteredFig.Layout.Row = 5; lblSaveFilteredFig.Layout.Column = 1;
        filtTimeCb = uicheckbox(gl_savefig, 'Text','时域波形','Value', false);
        filtTimeCb.Layout.Row = 5; filtTimeCb.Layout.Column = 2;
        filtSpecCb = uicheckbox(gl_savefig, 'Text','幅频特性','Value', false);
        filtSpecCb.Layout.Row = 5; filtSpecCb.Layout.Column = 3;
    
        % ---------------- 6行：保存信号比较分析图像 ----------------
        saveCompareCb = uicheckbox(gl_savefig, 'Text', '保存信号比较分析图像', 'Value', false);
        saveCompareCb.Layout.Row = 6; saveCompareCb.Layout.Column = [2 6];
    
        % ---------------- 7/8/9行：滤波器分析复选框（7个） ----------------
        lblSaveFilterFig = uilabel(gl_savefig, 'Text','保存滤波器分析图像：','HorizontalAlignment','left');
        lblSaveFilterFig.Layout.Row = 7; lblSaveFilterFig.Layout.Column = 1;
        filtMagCb = uicheckbox(gl_savefig,'Text','幅频特性','Value', false); filtMagCb.Layout.Row = 7; filtMagCb.Layout.Column = 2;
        filtPhaseCb = uicheckbox(gl_savefig,'Text','相频特性','Value', false); filtPhaseCb.Layout.Row = 7; filtPhaseCb.Layout.Column = 3;
        filtImpCb = uicheckbox(gl_savefig,'Text','单位冲激响应','Value', false); filtImpCb.Layout.Row = 8; filtImpCb.Layout.Column = 2;
        filtStepCb = uicheckbox(gl_savefig,'Text','单位阶跃响应','Value', false); filtStepCb.Layout.Row = 8; filtStepCb.Layout.Column = 3;
        filtGroupCb = uicheckbox(gl_savefig,'Text','群延迟','Value', false); filtGroupCb.Layout.Row = 9; filtGroupCb.Layout.Column = 2;
        filtPhaseDelayCb = uicheckbox(gl_savefig,'Text','相位延迟','Value', false); filtPhaseDelayCb.Layout.Row = 9; filtPhaseDelayCb.Layout.Column = 3;
        filtPZCb = uicheckbox(gl_savefig,'Text','零极点图','Value', false); filtPZCb.Layout.Row = 9; filtPZCb.Layout.Column = 4;
    
        % ---------------- 按钮行（第10行）：保存 / 取消 ----------------
        btnSave = uibutton(gl_savefig,'push','Text','保存','ButtonPushedFcn',@onDlgSave);
        btnSave.Layout.Row = 10; btnSave.Layout.Column = [1 3];
        btnCancel = uibutton(gl_savefig,'push','Text','取消','ButtonPushedFcn',@(s,e) delete(dlg_savefig));
        btnCancel.Layout.Row = 10; btnCancel.Layout.Column = [4 6];
    
        % ------------------ 根据 S 的状态设置 Enable 与 初始勾选 ------------------
        % 原始信号：只有在 S.currentSignal 非空时启用
        if isprop(S,'currentSignal') && ~isempty(S.currentSignal)
            origTimeCb.Enable = 'on'; origSpecCb.Enable = 'on';
            origTimeCb.Value = true; origSpecCb.Value = true;
        else
            origTimeCb.Enable = 'off'; origSpecCb.Enable = 'off';
        end
    
        % 加噪信号：只有在 S.noisy 非空时启用
        if isprop(S,'noisy') && ~isempty(S.noisy)
            noisyTimeCb.Enable = 'on'; noisySpecCb.Enable = 'on';
            noisyTimeCb.Value = true; noisySpecCb.Value = true;
        else
            noisyTimeCb.Enable = 'off'; noisySpecCb.Enable = 'off';
        end
    
        % 滤波后信号：检查 S.filteredHistory 或 S.filtered
        if (isprop(S,'filteredHistory') && ~isempty(S.filteredHistory)) || (isprop(S,'filtered') && ~isempty(S.filtered))
            filtTimeCb.Enable = 'on'; filtSpecCb.Enable = 'on';
            filtTimeCb.Value = true; filtSpecCb.Value = true;
            saveCompareCb.Enable = 'on'; % compare 图需要原始 + 滤波后都存在后才能启用，稍后再检查
        else
            filtTimeCb.Enable = 'off'; filtSpecCb.Enable = 'off';
            saveCompareCb.Enable = 'off';
        end
    
        % 比较图：需要 S.currentSignal 非空 且 有滤波后数据
        if isprop(S,'currentSignal') && ~isempty(S.currentSignal) && ...
           ((isprop(S,'filteredHistory') && ~isempty(S.filteredHistory)) || (isprop(S,'filtered') && ~isempty(S.filtered)))
            saveCompareCb.Value = true; saveCompareCb.Enable = 'on';
        else
            saveCompareCb.Enable = 'off';
        end
    
        % 滤波器分析：检查 filter_b 和 filter_a
        if isprop(S,'filter_b') && isprop(S,'filter_a') && ~isempty(S.filter_b) && ~isempty(S.filter_a)
            % 幅/相 默认勾选，其他默认不勾
            filtMagCb.Enable = 'on'; filtPhaseCb.Enable = 'on';
            filtMagCb.Value = true; filtPhaseCb.Value = true;
            filtImpCb.Enable = 'on'; filtStepCb.Enable = 'on';
            filtGroupCb.Enable = 'on'; filtPhaseDelayCb.Enable = 'on'; filtPZCb.Enable = 'on';
            % 其余（imp/step/group/phase/pz）初始都为 false
            filtImpCb.Value = false; filtStepCb.Value = false; filtGroupCb.Value = false; filtPhaseDelayCb.Value = false; filtPZCb.Value = false;
        else
            % 全部灰显
            filtMagCb.Enable = 'off'; filtPhaseCb.Enable = 'off'; filtImpCb.Enable = 'off';
            filtStepCb.Enable = 'off'; filtGroupCb.Enable = 'off'; filtPhaseDelayCb.Enable = 'off'; filtPZCb.Enable = 'off';
        end
    
        % ------------------ 联动逻辑实现（回调） ------------------
        % 如果"保存所有图像"被勾选：把可用的全部复选框都勾上，Enable 保持 'on'
        saveAllCb.ValueChangedFcn = @(src,ev) onSaveAllToggled(src.Value);
        function onSaveAllToggled(val)
            if val
                % 把所有 Enable=='on' 的复选框设为 Value = true
                cbs = {origTimeCb, origSpecCb, noisyTimeCb, noisySpecCb, filtTimeCb, filtSpecCb, saveCompareCb, ...
                       filtMagCb, filtPhaseCb, filtImpCb, filtStepCb, filtGroupCb, filtPhaseDelayCb, filtPZCb};
                for ii = 1:numel(cbs)
                    try
                        if strcmpi(cbs{ii}.Enable,'on')
                            cbs{ii}.Value = true;
                            cbs{ii}.Enable = 'on'; % ensure still operable
                        end
                    catch
                    end
                end
            else
                % 取消"保存所有图像"的情形：
                % 如果其他所有复选框都处于被勾选状态 -> 同时取消勾选其他所有复选框
                % 否则只取消主复选框
                allChecked = true;
                cbs = {origTimeCb, origSpecCb, noisyTimeCb, noisySpecCb, filtTimeCb, filtSpecCb, saveCompareCb, ...
                       filtMagCb, filtPhaseCb, filtImpCb, filtStepCb, filtGroupCb, filtPhaseDelayCb, filtPZCb};
                for ii = 1:numel(cbs)
                    try
                        if strcmpi(cbs{ii}.Enable,'on')
                            if ~cbs{ii}.Value
                                allChecked = false; break;
                            end
                        end
                    catch
                    end
                end
                if allChecked
                    % 取消所有可用复选框
                    for ii = 1:numel(cbs)
                        try
                            if strcmpi(cbs{ii}.Enable,'on')
                                cbs{ii}.Value = false;
                            end
                        catch
                        end
                    end
                else
                    % 仅取消主复选框（其它保持）
                end
            end
        end
    
        % 任何子复选框被取消时，如果主复选框为 true，则自动取消主复选框
        subCbs = {origTimeCb, origSpecCb, noisyTimeCb, noisySpecCb, filtTimeCb, filtSpecCb, saveCompareCb, ...
                  filtMagCb, filtPhaseCb, filtImpCb, filtStepCb, filtGroupCb, filtPhaseDelayCb, filtPZCb};
        for ii = 1:numel(subCbs)
            try
                subCbs{ii}.ValueChangedFcn = @(src,ev) onSubCbChanged(src);
            catch
            end
        end
        function onSubCbChanged(src)
            try
                if saveAllCb.Value && ~src.Value
                    % 若主复选框为 true，但有任一子复选框被取消 -> 主复选框取消
                    saveAllCb.Value = false;
                end
            catch
            end
        end
    
        % ------------------ 保存回调：收集选择并调用保存函数 ------------------
        function onDlgSave(~,~)
            % 收集选择到结构体
            sel = struct();
            sel.save_all = saveAllCb.Value;
            sel.orig_time = origTimeCb.Value && strcmpi(origTimeCb.Enable,'on');
            sel.orig_spec = origSpecCb.Value && strcmpi(origSpecCb.Enable,'on');
            sel.noisy_time = noisyTimeCb.Value && strcmpi(noisyTimeCb.Enable,'on');
            sel.noisy_spec = noisySpecCb.Value && strcmpi(noisySpecCb.Enable,'on');
            sel.filt_time = filtTimeCb.Value && strcmpi(filtTimeCb.Enable,'on');
            sel.filt_spec = filtSpecCb.Value && strcmpi(filtSpecCb.Enable,'on');
            sel.save_compare = saveCompareCb.Value && strcmpi(saveCompareCb.Enable,'on');
            sel.filt_mag = filtMagCb.Value && strcmpi(filtMagCb.Enable,'on');
            sel.filt_phase = filtPhaseCb.Value && strcmpi(filtPhaseCb.Enable,'on');
            sel.filt_imp = filtImpCb.Value && strcmpi(filtImpCb.Enable,'on');
            sel.filt_step = filtStepCb.Value && strcmpi(filtStepCb.Enable,'on');
            sel.filt_group = filtGroupCb.Value && strcmpi(filtGroupCb.Enable,'on');
            sel.filt_phasedelay = filtPhaseDelayCb.Value && strcmpi(filtPhaseDelayCb.Enable,'on');
            sel.filt_pz = filtPZCb.Value && strcmpi(filtPZCb.Enable,'on');
    
            % 路径选择
            path = uigetdir('','选择保存图像的文件夹');
            if isequal(path,0)
                % 用户取消路径选择 -> 不关闭对话框，返回
                uialert_safe(dlg_savefig,'取消：未选择保存位置','提示');
                return;
            end
    
            % 关闭对话框（保存开始后关闭）
            delete(dlg_savefig);
            drawnow;
    
            % 调用保存函数（只保存选中项）
            try 
                saveSelectedFigures(S, handles, fig_GUI, sel, path);
            catch ME
                uialert_safe(fig_GUI, ['保存图像时出错: ' ME.message], '保存错误');
                setStatus(handles, ['保存失败: ' ME.message]);
            end
        end
    
        % 阻塞，直到对话框关闭
        uiwait(dlg_savefig);
    end

    %% ---- 保存勾选的图像 ----
    function saveSelectedFigures(S, handles, fig_GUI, sel, path)
    % 传入的 handle类 S, handles; 主界面 fig_GUI
    % 对 S 的对象内容有 "读" 操作，无 "写" 操作
    % 对 handles 的对象内容有 "读/写" 操作
    % fig_GUI 用于uialert_safe()在主界面弹提醒窗口
    % sel: struct of booleans (见onOpenSaveFiguresDialog())
    % path: 保存文件夹路径

        % % 检查是否存在滤波结果（历史或单次）
        % if (isempty(S.filteredHistory) || numel(S.filteredHistory) == 0) && isempty(S.filtered)
        %     uialert_safe(fig_GUI,'请先完成至少一次滤波操作。','提示');
        %     setStatus(handles,'保存失败：请先完成滤波操作');
        %     return;
        % end
    
        % 检查至少有一项被勾选
        if ~any(struct2array(rmfield(sel,'save_all'))) && ~sel.save_all
            uialert_safe(fig_GUI,'未选择任何图像。','提示');
            setStatus(handles,'保存取消：未选择任何图像'); 
            return;
        end
    
        % --- 确定时间维 tdim（优先 S.timeDim，否则推断） ---
        if  ~isempty(S.timeDim) && S.timeDim==round(S.timeDim) && S.timeDim>=1
            tdim = S.timeDim;
            useTimeDim = true;
        else
            template = [];
            if isprop(S,'currentSignal') && ~isempty(S.currentSignal)
                template = S.currentSignal;
            elseif isprop(S,'filtered') && ~isempty(S.filtered)
                template = S.filtered;
            elseif isprop(S,'filteredHistory') && ~isempty(S.filteredHistory)
                template = S.filteredHistory{end};
            end
            if ~isempty(template)
                tdim = find(size(template)~=1,1,'first');
                if ~isempty(tdim) && tdim>=1
                    useTimeDim = true;
                end
            else
                tdim = 1; useTimeDim = false;
            end
        end
    
        setStatus(handles,'正在保存选中图像...');
    
        % 控制每张图一次绘制的通道数（避免图像爆炸）
        maxPlotChannels = 4; % 可修改或改为 GUI 可调
    
        % 读取绘图设置
        plotSettings = handles.plotSettings;
    
    
        try
            % --------------------------- 1) 保存原始（加噪前）时域与频域 —— 支持多通道/ND via to2DtimeMajor ---------------------------
            if sel.save_all || sel.orig_time || sel.orig_spec
                if ~isempty(S.currentSignal)
                    [A2, ~] = to2DtimeMajor(S.currentSignal, tdim, false);
                    A2 = fillNonfinite(A2,1);
        
                    N_A = size(A2,1);
                    nchA = size(A2,2);
                    chList = 1:min(nchA, maxPlotChannels);
        
                    % 时域图：用 plotTimeWave 统一绘制（会根据 plotSettings.signalPlotMode 选择 plot/stem）
                    if sel.save_all || sel.orig_time
                        fig = createCenteredFigure('Visible','off','Position',[100,100,900,600]);
                        if ~isreal(A2)
                            pdata = abs(A2); 
                            plotYLabel = '|y| (复数信号幅度)';
                            plotAbsY = true;
                        else 
                            pdata = A2; 
                            plotAbsY = false;
                            plotYLabel = '振幅';
                        end
                        ax = gca(fig);
                        tt = (0:N_A-1)/S.fs;
                        plotTimeWave(ax, tt, pdata, plotSettings, chList, '原始');
                        title(ax, '加噪前时域波形（原始）');
                        xlabel(ax, '时间 (s)');
                        ylabel(ax, plotYLabel);
                        saveas(fig, fullfile(path, '加噪前时域波形.png'));
                        close(fig);
                    end

                    % 频域图：使用 computeSpecForPlot + plotSpectrum（遵循 plotSettings.specFreqSide 等）
                    if sel.save_all || sel.orig_spec
                        [freqA, magA] = computeSpecForPlot(A2, S.fs, plotSettings);
                        fig = createCenteredFigure('Visible','off','Position',[100,100,900,600]);
                        ax = gca(fig);
                        plotSpectrum(ax, freqA, magA, plotSettings, chList, '原始', true);
                        title(ax, '加噪前频域波形（原始）');
                        % 设置 xlim（按归一化与单/双边）
                        if plotSettings.specFreqNormalized
                            if strcmpi(plotSettings.specFreqSide,'double')
                                xlim(ax, [0, 2]);
                            else
                                xlim(ax, [0, 1]);
                            end
                        else
                            if strcmpi(plotSettings.specFreqSide,'double')
                                xlim(ax, [0, S.fs]);
                            else
                                xlim(ax, [0, S.fs/2]);
                            end
                        end
                        saveas(fig, fullfile(path, '加噪前频域波形.png'));
                        close(fig);
                    end
                end
            end

            % --------------------------- 2) 保存加噪后（若存在）时域与频域 ---------------------------
            if sel.save_all || sel.noisy_time || sel.noisy_spec
                if ~isempty(S.noisy)
                    [N2, ~] = to2DtimeMajor(S.noisy, tdim, false);
                    N2 = fillNonfinite(N2,1);
        
                    Nn = size(N2,1);
                    chListN = 1:min(size(N2,2), maxPlotChannels);
        
                    % 时域
                    if sel.save_all || sel.noisy_time
                        fig = createCenteredFigure('Visible','off','Position',[100,100,900,600]);
                        if plotAbsY
                            pdata = abs(N2); 
                        else 
                            pdata = N2; 
                        end
                        ax = gca(fig);
                        tt = (0:Nn-1)/S.fs;
                        plotTimeWave(ax, tt, pdata, plotSettings, chListN, '加噪');
                        title(ax, '加噪后时域波形');
                        xlabel(ax, '时间 (s)');
                        ylabel(ax, plotYLabel);
                        saveas(fig, fullfile(path, '加噪后时域波形.png'));
                        close(fig);
                    end

                    % 频域（遵循 settings）
                    if sel.save_all || sel.noisy_spec
                        [freqN, magN] = computeSpecForPlot(N2, S.fs, plotSettings);
                        fig = createCenteredFigure('Visible','off','Position',[100,100,900,600]);
                        ax = gca(fig);
                        plotSpectrum(ax, freqN, magN, plotSettings, chListN, '加噪', true);
                        title(ax, '加噪后频域波形');
                        % 设置 xlim（按归一化与单/双边）
                        if plotSettings.specFreqNormalized
                            if strcmpi(plotSettings.specFreqSide,'double')
                                xlim(ax, [0, 2]);
                            else
                                xlim(ax, [0, 1]);
                            end
                        else
                            if strcmpi(plotSettings.specFreqSide,'double')
                                xlim(ax, [0, S.fs]);
                            else
                                xlim(ax, [0, S.fs/2]);
                            end
                        end
                        saveas(fig, fullfile(path, '加噪后频域波形.png'));
                        close(fig);
                    end
                end
            end

            % --------------------------- 3) 保存每次滤波后（历史或单次）---------------------------
            if sel.save_all || sel.filt_time || sel.filt_spec
                if ~isempty(S.filteredHistory) && numel(S.filteredHistory) > 0
                    filtList = S.filteredHistory;
                else
                    filtList = { S.filtered };
                end
        
                for k = 1:numel(filtList)
                    yk_raw = filtList{k};
                    [Yk2, ~] = to2DtimeMajor(yk_raw, tdim, false);
                    Yk2 = fillNonfinite(Yk2,1);
        
                    Nk = size(Yk2,1);
                    chListK = 1:min(size(Yk2,2), maxPlotChannels);
                    tt = (0:Nk-1)/S.fs;
        
                    % 时域
                    if sel.save_all || sel.filt_time
                        fig = createCenteredFigure('Visible','off','Position',[100,100,900,600]);
                        if ~isreal(Yk2)
                            pdata = abs(Yk2); 
                            plotYLabel2 = '|y| (复数信号幅度)';
                        else 
                            pdata = Yk2; 
                            plotYLabel2 = '振幅';
                        end
                        ax = gca(fig);
                        plotTimeWave(ax, tt, pdata, plotSettings, chListK, sprintf('第%d次滤波', k));
                        title(sprintf('滤波后时域波形-第%d次滤波', k));
                        xlabel('时间 (s)');
                        ylabel(plotYLabel2);
                        saveas(fig, fullfile(path, sprintf('滤波后时域波形-第%d次滤波.png', k)));
                        close(fig);
                    end

                    % 频域（computeSpecForPlot + plotSpectrum）
                    if sel.save_all || sel.filt_spec
                        [freqK, magK] = computeSpecForPlot(Yk2, S.fs, plotSettings);
                        fig = createCenteredFigure('Visible','off','Position',[100,100,900,600]);
                        ax = gca(fig);
                        plotSpectrum(ax, freqK, magK, plotSettings, chListK, sprintf('第%d次滤波', k), true);
                        title(ax, sprintf('滤波后频域波形-第%d次滤波', k));
                        % 设置 xlim（按归一化与单/双边）
                        if plotSettings.specFreqNormalized
                            if strcmpi(plotSettings.specFreqSide,'double')
                                xlim(ax, [0, 2]);
                            else
                                xlim(ax, [0, 1]);
                            end
                        else
                            if strcmpi(plotSettings.specFreqSide,'double')
                                xlim(ax, [0, S.fs]);
                            else
                                xlim(ax, [0, S.fs/2]);
                            end
                        end
                        saveas(fig, fullfile(path, sprintf('滤波后频域波形-第%d次滤波.png', k)));
                        close(fig);
                    end
                end
            end

            % ------------ 4) 保存滤波器幅频/相频特性、单位冲激响应、单位阶跃响应、群延迟、相位延迟、零极点图（针对每次设计的滤波器历史）---------------
            if sel.save_all || any([sel.filt_mag, sel.filt_phase, sel.filt_imp, sel.filt_step, sel.filt_group, sel.filt_phasedelay, sel.filt_pz])
                % --------------------------- 保存：滤波器幅频/相频特性 ---------------------------
                if ~isempty(S.filterHistory) && numel(S.filterHistory) > 0
                    filtHistList = S.filterHistory;
                else
                    filtHistList = {};
                    if isprop(S,'filter_b') && isprop(S,'filter_a') && ~isempty(S.filter_b) && ~isempty(S.filter_a)
                        filtHistList{1} = struct('b', S.filter_b, 'a', S.filter_a);
                    end
                end
        
                nfft_filt = max(1, plotSettings.filterSpecNFFT);
                for k = 1:numel(filtHistList)
                    bh = filtHistList{k}.b;
                    ah = filtHistList{k}.a;
        
                    if strcmpi(plotSettings.specFreqSide,'double')
                        [H,w] = freqz(bh, ah, nfft_filt, 'whole', S.fs);
                    else
                        [H,w] = freqz(bh, ah, nfft_filt, S.fs);
                    end
        
                    % 归一化频率（如果选了归一化显示）
                    if isfield(plotSettings,'specFreqNormalized') && plotSettings.specFreqNormalized
                        w = w / S.fs *2; % 2*pi*f/fs；横坐标为归一化频率 (xπ rad/sample)
                    end
        
                    % 幅频图
                    if sel.save_all || sel.filt_mag
                        fig = createCenteredFigure('Visible','off','Position',[100,100,800,600]);
                        H_Res = H;
                        w_Res = w;
                        % 计算幅值并按模式处理
                        if strcmpi(plotSettings.specMagMode,'dB')
                            mag_plot = 20*log10(abs(H_Res) + eps);
                        else
                            mag_plot = abs(H_Res);
                        end
                        % 归一化幅值
                        if isfield(plotSettings,'specMagNormalized') && plotSettings.specMagNormalized
                            mv = max(mag_plot(:));
                            if mv ~= 0
                                mag_plot = mag_plot / mv;
                            end
                        end
                        % 绘图：处理 log 轴
                        ax = gca(fig);
                        if strcmpi(plotSettings.specFreqScale,'log')
                            % 去掉 0 频点以避免 log(0)
                            if any(w_Res==0)
                                idx0 = w_Res==0;
                                w_Res(idx0) = [];
                                mag_plot(idx0,:) = [];
                            end 
                            plot(ax, w_Res, mag_plot); 
                            set(ax,'XScale','log');
                        else
                            plot(ax, w_Res, mag_plot);
                            set(ax,'XScale','linear');
                        end
                
                        grid(ax,'on'); 
                        title(ax, sprintf('滤波器幅频特性-第%d次滤波', k));
                        xlabel(ax, getSpecXLabel(plotSettings));
                        ylabel(ax, getSpecYLabel(plotSettings));
                        % xlim 根据归一化与单/双边设置
                        if plotSettings.specFreqNormalized
                            if strcmpi(plotSettings.specFreqSide,'double')
                                xlim(ax,[0,2]);
                            else
                                xlim(ax,[0,1]);
                            end
                        else
                            if strcmpi(plotSettings.specFreqSide,'double')
                                xlim(ax,[0,S.fs]);
                            else
                                xlim(ax,[0,S.fs/2]);
                            end
                        end
                        saveas(fig, fullfile(path, sprintf('滤波器幅频特性-第%d次滤波.png', k)));
                        close(fig);
                    end

                    % 相频图
                    if sel.save_all || sel.filt_phase
                        fig = createCenteredFigure('Visible','off','Position',[100,100,800,600]);
                        H_Pha = H;
                        w_Pha = w;
                        % 相位 rad
                        phase = unwrap(angle(H_Pha));
            
                        % 绘图：处理 log 轴
                        ax = gca(fig);
                        if strcmpi(plotSettings.specFreqScale,'log')
                            % 去掉 0 频点以避免 log(0)
                            if any(w_Pha==0)
                                idx0 = w_Pha==0;
                                w_Pha(idx0) = [];
                                phase(idx0,:) = [];
                            end 
                            plot(ax, w_Pha, phase);
                            set(ax,'XScale','log');
                        else
                            plot(ax, w_Pha, phase);
                            set(ax,'XScale','linear');
                        end
                        grid(ax,'on');
                        title(ax, sprintf('滤波器相频特性-第%d次滤波', k));
                        xlabel(ax, getSpecXLabel(plotSettings));
                        ylabel(ax, '相位 (rad)');
                        % xlim 根据归一化与单/双边设置
                        if plotSettings.specFreqNormalized
                            if strcmpi(plotSettings.specFreqSide,'double')
                                xlim(ax,[0,2]);
                            else
                                xlim(ax,[0,1]);
                            end
                        else
                            if strcmpi(plotSettings.specFreqSide,'double')
                                xlim(ax,[0,S.fs]);
                            else
                                xlim(ax,[0,S.fs/2]);
                            end
                        end
                        saveas(fig, fullfile(path, sprintf('滤波器相频特性-第%d次滤波.png', k)));
                        close(fig);
                    end

                    % --------------------------- 保存：单位冲激响应 （与幅/相/群同命名规则） ---------------------------
                    if sel.save_all || sel.filt_imp
                        try
                            fig = createCenteredFigure('Visible','off','Position',[100,100,800,600]);
                            bh = S.filterHistory{k}.b;
                            ah = S.filterHistory{k}.a;
                            
                            % 基本健壮性检查
                            if any(~isfinite(bh)) || any(~isfinite(ah))
                                error('滤波器系数包含非有限值');
                            end
                            
                            % 检查稳定性（若非稳定，警告并限制样本数）
                            poles = roots(ah);
                            unstable = any(abs(poles) >= 1);
                            order = max(length(bh)-1, length(ah)-1);
                            % 自适应样点数（可根据需要调整上下限）
                            Nimp = max(256, 4*order);
                            Nimp = min(Nimp, 8192); % 上限以防内存/绘图卡顿
                            if unstable
                                % 若不稳定，缩短样点数并提示
                                Nimp = min(Nimp, 512);
                                % 计算冲激响应（优先使用 impz 的显式 n）
                                [h, t] = impz(bh, ah, Nimp, S.fs);  % t 单位为秒
                                uialert_safe(fig_GUI, '警告：当前滤波器可能不稳定。单位冲激响应 绘制已限制样点数以防发散。', '警告',"Icon","warning");
                            else
                
                                % 计算冲激响应（优先使用 impz 的显式 n）
                                [h, t] = impz(bh, ah, [], S.fs);  % t 单位为秒
                            end
                            % 在绘图前：
                            if ~isreal(h)
                                % 解析信号：默认绘制幅度（可改为 real/imag）
                                plotData = abs(h);
                                plotYLabel = '|h| (复数信号幅度)';
                            else
                                plotData = h;
                                plotYLabel = '振幅';
                            end
                            % 使用 plotData 替代原有 h 进行绘图，并把 plotYLabel 写到 ylabel
                            % 若数据点很多，使用线图；否则使用 stem
                            if numel(h) <= 2000
                                stem(t, plotData, 'filled');
                            else
                                plot(t, plotData, 'LineWidth', 1);
                            end
                            
            
                            grid on;
                            title(sprintf('滤波器单位冲激响应-第%d次滤波', k));
                            xlabel('时间 (s)');
                            ylabel(plotYLabel);
                            xlim([0, t(end)]);
                            saveas(fig, fullfile(path, sprintf('滤波器单位冲激响应-第%d次滤波.png', k)));
                            close(fig);
                        catch ME
                            warning('onSaveAllFigures:SaveImpulseFailed', '保存第%d次滤波器单位冲激响应失败: %s', k, ME.message);
                        end
                    end
                    
                    % ---------------------------  保存单位阶跃响应（每次滤波，仅使用 stepz） ---------------------------
                    if sel.save_all || sel.filt_step
                        try
                            fig = createCenteredFigure('Visible','off','Position',[100,100,800,600]);
                            bh = S.filterHistory{k}.b(:).';
                            ah = S.filterHistory{k}.a(:).';
                        
                            % 确保有采样率
                            if ~isprop(S,'fs') || isempty(S.fs) || ~(isnumeric(S.fs) && S.fs>0)
                                warning('onSaveAllFigures:NoFs', '未定义 S.fs，跳过第%d次滤波的阶跃响应保存（stepz 需要 fs）。', k);
                            else
                                % 基本健壮性检查
                                if any(~isfinite(bh)) || any(~isfinite(ah))
                                    error('滤波器系数包含非有限值');
                                end
                    
                                % 检查稳定性（若非稳定，警告并限制样本数）
                                poles = roots(ah);
                                unstable = any(abs(poles) >= 1);
                                order = max(length(bh)-1, length(ah)-1);
                                % 自适应样点数（可根据需要调整上下限）
                                Nstep = max(256, 4*order);
                                Nstep = min(Nstep, 8192); % 上限以防内存/绘图卡顿
                        
                                if unstable
                                    % 若不稳定，缩短样点数并提示
                                    Nstep = min(Nstep, 512);
                                    % 计算阶跃响应
                                    [h_vals, t_vals] = stepz(bh, ah, Nstep, S.fs);
                                    uialert_safe(fig_GUI, '警告：当前滤波器可能不稳定。单位阶跃响应 绘制已限制样点数以防发散。', '警告',"Icon","warning");
                                else
                                    % 仅用 stepz 计算：h (样点), t (以秒为单位，间隔 1/S.fs)。（优先使用 stepz 的显式 n）
                                    [h_vals, t_vals] = stepz(bh, ah, [], S.fs);
                                end
                                % 在绘图前：
                                if ~isreal(h_vals)
                                    % 解析信号：默认绘制幅度（可改为 real/imag）
                                    plotData = abs(h_vals);
                                    plotYLabel = '|h| (复数信号幅度)';
                                else
                                    plotData = h_vals;
                                    plotYLabel = '振幅';
                                end
                                % 使用 plotData 替代原有 h_vals 进行绘图，并把 plotYLabel 写到 ylabel
                                % 若数据点很多，使用线图；否则使用 stem
                                if numel(h_vals) <= 2000
                                    stem(t_vals, plotData, 'filled');
                                else
                                    plot(t_vals, plotData);
                                end
                                grid on;
                                xlabel('时间 (s)');
                                ylabel(plotYLabel);
                                xlim([0, t_vals(end)]);
                                title(sprintf('滤波器单位阶跃响应-第%d次滤波', k));
                        
                                saveas(fig, fullfile(path, sprintf('滤波器单位阶跃响应-第%d次滤波.png', k)));
                                close(fig);
                            end
                        catch ME
                            warning('onSaveAllFigures:SaveStepRespFailed', '保存第%d次滤波器单位阶跃响应失败: %s', k, ME.message);
                        end
                    end

                    % --------------------------- 保存群延迟（与幅/相同命名规则）---------------------------
                    if sel.save_all || sel.filt_group
                        try
                            if strcmpi(plotSettings.specFreqSide,'double')
                                [gd, fgd] = grpdelay(bh, ah, nfft_filt, 'whole', S.fs);
                            else
                                [gd, fgd] = grpdelay(bh, ah, nfft_filt, S.fs);
                            end
                            % 归一化频率（如果选了归一化显示）
                            if isfield(plotSettings,'specFreqNormalized') && plotSettings.specFreqNormalized
                                fgd = fgd / S.fs *2; % 2*pi*f/fs；横坐标为归一化频率 (xπ rad/sample)
                            end
                        
                            fig = createCenteredFigure('Visible','off','Position',[100,100,800,600]);
                            % 绘图：处理 log 轴
                            ax = gca(fig);
                            if strcmpi(plotSettings.specFreqScale,'log')
                                fgd_plot = fgd;
                                gd_plot = gd;
                                % 去掉 0 频点以避免 log(0)
                                if any(fgd_plot==0)
                                    idx0 = fgd_plot==0;
                                    fgd_plot(idx0) = [];
                                    gd_plot(idx0,:) = [];
                                end 
                                plot(ax, fgd_plot, gd_plot);
                                set(ax,'XScale','log');
                            else
                                plot(ax, fgd, gd);
                                set(ax,'XScale','linear');
                            end
                            grid(ax,'on');
                            title(ax, sprintf('滤波器群延迟-第%d次滤波', k));
                            xlabel(ax, getSpecXLabel(plotSettings));
                            ylabel('群延迟 (样点)');
                            % xlim 根据归一化与单/双边设置
                            if plotSettings.specFreqNormalized
                                if strcmpi(plotSettings.specFreqSide,'double')
                                    xlim(ax,[0,2]);
                                else
                                    xlim(ax,[0,1]);
                                end
                            else
                                if strcmpi(plotSettings.specFreqSide,'double')
                                    xlim(ax,[0,S.fs]);
                                else
                                    xlim(ax,[0,S.fs/2]);
                                end
                            end
                            saveas(fig, fullfile(path, sprintf('滤波器群延迟-第%d次滤波.png', k)));
                            close(fig);
                        catch ME
                            warning('onSaveAllFigures:SaveGroupDelayFailed', '保存第%d次滤波器群延迟失败: %s', k, ME.message);
                        end
                    end

                    % ---------------------------  保存相位延迟——每次滤波 ---------------------------
                    if sel.save_all || sel.filt_phasedelay
                        try
                            if strcmpi(plotSettings.specFreqSide,'double')
                                [phi,freq] = phasedelay(bh, ah, nfft_filt,'whole', S.fs);
                            else
                                [phi,freq] = phasedelay(bh, ah, nfft_filt, S.fs);
                            end
                            % 归一化频率（如果选了归一化显示）
                            if isfield(plotSettings,'specFreqNormalized') && plotSettings.specFreqNormalized
                                freq = freq / S.fs *2; % 2*pi*f/fs；横坐标为归一化频率 (xπ rad/sample)
                            end
                                
                            fig = createCenteredFigure('Visible','off','Position',[100,100,800,600]);
                            % 绘图：处理 log 轴
                            ax = gca(fig);
                            if strcmpi(plotSettings.specFreqScale,'log')
                                freq_plot = freq;
                                phi_plot = phi;
                                % 去掉 0 频点以避免 log(0)
                                if any(freq_plot==0)
                                    idx0 = freq_plot==0;
                                    freq_plot(idx0) = [];
                                    phi_plot(idx0,:) = [];
                                end 
                                plot(ax, freq_plot, phi_plot);
                                set(ax,'XScale','log');
                            else
                                plot(ax, freq, phi);
                                set(ax,'XScale','linear');
                            end
                            grid(ax,'on');
                            title(ax, sprintf('滤波器相位延迟-第%d次滤波', k));
                            xlabel(ax, getSpecXLabel(plotSettings));
                            if isfield(plotSettings,'specFreqNormalized') && plotSettings.specFreqNormalized
                                ylabel(ax, '相位延迟 (采样)');
                            else
                                ylabel(ax, '相位延迟 (rad / Hz)');
                            end
                            % xlim 根据归一化与单/双边设置
                            if plotSettings.specFreqNormalized
                                if strcmpi(plotSettings.specFreqSide,'double')
                                    xlim(ax,[0,2]);
                                else
                                    xlim(ax,[0,1]);
                                end
                            else
                                if strcmpi(plotSettings.specFreqSide,'double')
                                    xlim(ax,[0,S.fs]);
                                else
                                    xlim(ax,[0,S.fs/2]);
                                end
                            end
                            saveas(fig, fullfile(path, sprintf('滤波器相位延迟-第%d次滤波.png', k)));
                            close(fig);
                        catch ME
                            warning('onSaveAllFigures:SavePhasePerHzFailed', '保存第%d次滤波器相位延迟(radians/Hz)失败: %s', k, ME.message);
                        end
                    end
        
                    % --------------------------- 保存零极点图（每次滤波） ---------------------------
                    if sel.save_all || sel.filt_pz
                        try
                            % 假设 S.filterHistory{k}.b / .a 保存了第 k 次的系数
                            bh = S.filterHistory{k}.b(:).';
                            ah = S.filterHistory{k}.a(:).';
            
                            % 创建离线 figure/axes（用于保存）
                            fig = createCenteredFigure('Visible','off','Position',[100,100,800,600]);
                            ax = axes(fig);
                            hold(ax, 'on');
                            cla(ax);
            
                            % 计算零与极
                            z = roots(bh); p = roots(ah);
                            z = z(:); p = p(:);
            
                            % 先尝试使用 zplane 在指定 axes 上绘制（优先）
                            
                            try
                                % zplane 在多数 MATLAB 版本上支持 (Z,P,AX)
                                [hz, hp, hunit] = zplane(z, p, ax);
                                % 美化返回的句柄（若有）
                                if exist('hz','var') && ~isempty(hz)
                                    try set(hz, 'Marker', 'o', 'MarkerSize', 8, 'LineWidth', 1.2,'MarkerEdgeColor', 'm'); catch; end
                                end
                                if exist('hp','var') && ~isempty(hp)
                                    try set(hp, 'Marker', 'x', 'MarkerSize', 8, 'LineWidth', 1.5,'MarkerEdgeColor', 'g'); catch; end
                                end
                                if exist('hunit','var') && ~isempty(hunit)
                                    try set(hunit, 'LineStyle', '--', 'LineWidth', 0.8); catch; end
                                end
                                drawSucceeded = true;
                            catch zplaneME
                                % zplane 到指定 axes 失败则回退（兼容性保护）
                                fprintf('zplane 绘制失败（保存图），回退到手工绘制。错误：%s\n', zplaneME.message);
                                drawSucceeded = false;
                            end
            
                            % fallback：手工绘制单位圆与零极点（若 zplane 不可用）
                            if ~drawSucceeded
                                t = linspace(0,2*pi,400);
                                plot(ax, cos(t), sin(t), '--', 'LineWidth', 0.8);  % 单位圆
                                if ~isempty(z)
                                    plot(ax, real(z), imag(z), 'o', 'MarkerSize', 8, 'LineWidth', 1.2, 'Color', 'm');
                                end
                                if ~isempty(p)
                                    plot(ax, real(p), imag(p), 'x', 'MarkerSize', 8, 'LineWidth', 1.5, 'Color', 'g');
                                end
                            end
            
                            % 计算自适应范围（与 GUI onPoleZeroPlot 一致的方案）
                            allRoots = [z; p];
                            if isempty(allRoots)
                                rmax = 0;
                            else
                                rmax = max(abs(allRoots));
                                if ~isfinite(rmax) || isnan(rmax)
                                    rmax = 0;
                                end
                            end
                            defaultLim = max(1.2, 1.1 * rmax);
                            uiDefaultCap = 3;            % 默认 UI 最大显示范围（如需改统一修改 GUI 与保存处）
                            lim = min(defaultLim, uiDefaultCap);
            
                            % 设置坐标、网格与标题
                            axis(ax, 'equal');
                            grid(ax, 'on');
                            xlabel(ax, '实部');
                            ylabel(ax, '虚部');
                            title(ax, sprintf('滤波器零极点图-第%d次滤波', k));
            
                            % 设置主视区（覆盖单位圆并留白）
                            xlim(ax, [-lim lim]);
                            ylim(ax, [-lim lim]);
            
                            % 对接近或超出边界的根分别注释（零点/极点区分）
                            try
                                if ~isempty(allRoots)
                                    % 零点与极点中接近/超出的索引（阈值 0.95*lim）
                                    z_oob_idx = find(abs(z) > lim * 0.95);
                                    p_oob_idx = find(abs(p) > lim * 0.95);
            
                                    % 小偏移用于文本，避免与标记完全重叠
                                    txtOffset = 0.01 * lim;
            
                                    hold(ax, 'on');
                                    % 零点：洋红色空心圆 + 文本 "z|<模长>"
                                    for ii = 1:numel(z_oob_idx)
                                        rt = z(z_oob_idx(ii));
                                        ang = angle(rt);
                                        r = abs(rt);
                                        xb = cos(ang) * lim;
                                        yb = sin(ang) * lim;
                                        plot(ax, xb, yb, 'o', 'MarkerSize', 8, 'LineWidth', 1.2, ...
                                             'MarkerEdgeColor', 'm', 'MarkerFaceColor', 'none');
                                        text(ax, xb+txtOffset, yb+txtOffset, sprintf('|z|=%.3g', r), ...
                                             'FontSize', 9, 'HorizontalAlignment', 'left', 'VerticalAlignment', 'bottom', 'Color', 'm');
                                    end
            
                                    % 极点：绿色叉 + 文本 "p|<模长>"
                                    for ii = 1:numel(p_oob_idx)
                                        rt = p(p_oob_idx(ii));
                                        ang = angle(rt);
                                        r = abs(rt);
                                        xb = cos(ang) * lim;
                                        yb = sin(ang) * lim;
                                        plot(ax, xb, yb, 'x', 'MarkerSize', 8, 'LineWidth', 1.5, 'Color', 'g');
                                        text(ax, xb+txtOffset, yb+txtOffset, sprintf('|p|=%.3g', r), ...
                                             'FontSize', 9, 'HorizontalAlignment', 'left', 'VerticalAlignment', 'bottom', 'Color', 'g');
                                    end
                                    hold(ax, 'off');
                                end
                            catch annME
                                fprintf('保存零极点图时边界注释失败：%s\n', annME.message);
                            end
            
                            hold(ax, 'off');
            
                            % 保存并关闭
                            saveas(fig, fullfile(path, sprintf('滤波器零极点图-第%d次滤波.png', k)));
                            close(fig);
                        catch ME
                            warning('onSaveAllFigures:SavePZFailed', '保存第%d次滤波器零极点图失败: %s', k, ME.message);
                        end
                    end
                end
            end

            % --------------------------- 5) 保存比较窗口（如果存在）---------------------------
            if sel.save_all || sel.save_compare
                if isprop(handles,'figCompare') && ~isempty(handles.figCompare) && isvalid(handles.figCompare)
                    saveas(handles.figCompare, fullfile(path, '信号比较分析.png'));
                else
                    showCompareFigure(S, handles, fig_GUI, false);
                    saveas(handles.figCompare, fullfile(path, '信号比较分析.png'));
                    close(handles.figCompare);
                end
            end

            setStatus(handles,sprintf('图像已保存到: %s', path));
            uialert_safe(fig_GUI, sprintf('图像已保存到: %s', path), '保存成功', 'Icon', 'success');
    
        catch ME
            uialert_safe(fig_GUI, ['保存图像失败: ' ME.message], '保存错误');
            setStatus(handles,['保存失败: ' ME.message]);
            fprintf('调试点84：保存所有图像失败：%s\n', ME.message);
        end
    end

    %% ---- “保存非加载音频”按钮回调：保存录制或生成或加噪或导入的音频 ----
    function onSaveOrigGen(~,~)
        % 选择要保存的音频（优先：已加噪 -> 生成信号 -> 录制信号 -> 导入工作区信号）
        if handles.cbAddNoise.Value && isprop(S,'noiseConfirmed') && S.noiseConfirmed && ~isempty(S.noisy)
            audio_to_save = S.noisy;
            desc = '加噪后的音频';
        elseif strcmp(handles.ddDataSource.Value,'多频正弦') && ~isempty(S.multiToneSignal)
            audio_to_save = S.multiToneSignal;
            desc = '生成的多频正弦';
        elseif strcmp(handles.ddDataSource.Value,'音频信号') && isprop(S,'hasRecorded') && S.hasRecorded && ~isempty(S.audioSignal)
            audio_to_save = S.audioSignal;
            desc = '录制的音频';
        elseif strcmp(handles.ddDataSource.Value,'导入工作区数据') && isprop(S,'wsSignal') && ~isempty(S.wsSignal)
            %  支持保存从 workspace 导入的信号
            audio_to_save = S.wsSignal;
            desc = '导入的工作区信号';
        else
            uialert_safe(fig_GUI,'当前没有可保存的音频（请检查是否已录制/生成/加噪/导入）。','保存错误');
            setStatus(handles,'保存失败：无可保存音频');
            return;
        end
    
        % ===  保存前范围检查（兼容向量/矩阵/多声道） ===
        audio_to_save = double(audio_to_save);
        
        % 把行向量转换为列向量，保证 samples x channels
        if isvector(audio_to_save)
            audio_to_save = audio_to_save(:);  % 变为 N x 1
        end
        
        % 如果是高维（>2）尝试 squeeze 成 2D，否则报错返回
        if ndims(audio_to_save) > 2
            tmp = squeeze(audio_to_save);
            if ismatrix(tmp)
                audio_to_save = tmp;
            else
                uialert_safe(fig_GUI, '音频数据维度超过2维，无法保存。请转换为 samples x channels 的二维矩阵。', '保存错误');
                setStatus(handles,'保存失败：音频维度不支持');
                fprintf('调试点74：保存失败：音频维度不支持\n');
                return;
            end
        end
        
        % 检查包含 NaN / Inf
        if ~all(isfinite(audio_to_save), 'all')
            uialert_safe(fig_GUI, '音频包含 NaN 或 Inf，无法保存。', '保存错误');
            setStatus(handles,'保存失败：音频包含 NaN/Inf');
            fprintf('调试点74：保存失败：音频包含 NaN/Inf\n');
            return;
        end
        
        % 按通道查找是否有超过 1 的通道（samples x channels -> max over rows）
        channel_max = max(abs(audio_to_save), [], 1);   % 1 x C 向量
        
        % 仅对超过 1 的通道做缩放（保留 0.99 余量）
        over = channel_max > 1;
        if any(over)
            scale = ones(1, size(channel_max, 2));        % 默认不缩放
            scale(over) = 1 ./ channel_max(over);      % 仅对超限通道设缩放因子
            audio_to_save = audio_to_save .* scale;           % 隐式扩展：samples x channels .* 1 x channels
            setStatus(handles,'警告：部分声道幅度超过范围，已按通道调整');
            fprintf('调试点74：警告：部分声道幅度超过范围，已按通道调整\n');
        end
        % === 结束保存前检查 ===
    
        % 选择保存文件名（多格式）
        [file, path] = uiputfile( ...
            {'*.wav', 'WAV文件 (*.wav)'; ...
             '*.mp3', 'MP3文件 (*.mp3)'; ...
             '*.flac','FLAC文件 (*.flac)'; ...
             '*.m4a','M4A文件 (*.m4a)'; ...
             '*.*','所有文件'}, ...
             ['保存 ' desc ' 为']);
        if isequal(file,0), return; end
        filename = fullfile(path, file);
    
        try
            [~,~,ext] = fileparts(filename);
            switch lower(ext)
                case '.wav'
                    audiowrite(filename, audio_to_save, S.fs);
                case '.mp3'
                    audiowrite(filename, audio_to_save, S.fs, 'Quality', 95);
                case '.flac'
                    audiowrite(filename, audio_to_save, S.fs);
                case '.m4a'
                    audiowrite(filename, audio_to_save, S.fs, 'BitRate', 128);
                otherwise
                    if isempty(ext), filename = [filename '.wav']; end
                    audiowrite(filename, audio_to_save, S.fs);
            end
            setStatus(handles,sprintf('已保存 %s: %s', desc, filename));
            uialert(fig_GUI, sprintf('已保存 %s: %s', desc, filename), '保存成功', 'Icon', 'success');

        catch ME
            uialert_safe(fig_GUI, ['保存失败：' ME.message], '保存错误');
            setStatus(handles,['保存失败：', ME.message]);
            fprintf('调试点75：保存录制或生成或加噪或导入的音频\n');
        end
    end

    %% ---- “保存滤波后音频”按钮回调 ----
    function onSaveFiltered(~,~)
        if isempty(S.filtered)
            uialert_safe(fig_GUI,'没有滤波后音频可保存。','保存错误');
            setStatus(handles,'保存失败：无滤波后音频');
            return;
        end
        
        % ===  保存前范围检查（兼容向量/矩阵/多声道） ===
        audio_to_save = double(S.filtered);
        
        % 把行向量转换为列向量，保证 samples x channels
        if isvector(audio_to_save)
            audio_to_save = audio_to_save(:);  % 变为 N x 1
        end
        
        % 如果是高维（>2）尝试 squeeze 成 2D，否则报错返回
        if ndims(audio_to_save) > 2
            tmp = squeeze(audio_to_save);
            if ismatrix(tmp)
                audio_to_save = tmp;
            else
                uialert_safe(fig_GUI, '音频数据维度超过2维，无法保存。请转换为 samples x channels 的二维矩阵。', '保存错误');
                setStatus(handles,'保存失败：音频维度不支持');
                fprintf('调试点76：保存失败：音频维度不支持\n');
                return;
            end
        end
        
        % 检查包含 NaN / Inf
        if ~all(isfinite(audio_to_save), 'all')
            uialert_safe(fig_GUI, '音频包含 NaN 或 Inf，无法保存。', '保存错误');
            setStatus(handles,'保存失败：音频包含 NaN/Inf');
            fprintf('调试点76：保存失败：音频包含 NaN/Inf\n');
            return;
        end
        
        % 按通道查找是否有超过 1 的通道（samples x channels -> max over rows）
        channel_max = max(abs(audio_to_save), [], 1);   % 1 x C 向量
        
        % 仅对超过 1 的通道做缩放（保留 0.99 余量）
        over = channel_max > 1;
        if any(over)
            scale = ones(1, size(channel_max, 2));        % 默认不缩放
            scale(over) = 1 ./ channel_max(over);      % 仅对超限通道设缩放因子
            audio_to_save = audio_to_save .* scale;           % 隐式扩展：samples x channels .* 1 x channels
            setStatus(handles,'警告：部分声道幅度超过范围，已按通道调整');
            fprintf('调试点76：警告：部分声道幅度超过范围，已按通道调整\n');
        end
        % === 结束保存前检查 ===
        
        % 提供多种格式选项
        [file, path] = uiputfile(...
            {'*.wav', 'WAV文件 (*.wav)';
             '*.mp3', 'MP3文件 (*.mp3)';
             '*.flac', 'FLAC文件 (*.flac)';
             '*.m4a', 'M4A文件 (*.m4a)';
             '*.*', '所有文件'}, ...
            '保存为');
        
        if isequal(file, 0)
            return;
        end
        
        filename = fullfile(path, file);
        
        try
            % 根据文件扩展名确定保存选项
            [~, ~, ext] = fileparts(filename);
            
            switch lower(ext)
                case '.wav'
                    audiowrite(filename, audio_to_save, S.fs);
                case '.mp3'
                    % MP3格式 - 使用'Quality'参数而不是'BitRate'
                    % Quality范围0-100，100表示最高质量
                    audiowrite(filename, audio_to_save, S.fs, 'Quality', 95);
                case '.flac'
                    audiowrite(filename, audio_to_save, S.fs);
                case '.m4a'
                    % M4A/AAC格式
                    audiowrite(filename, audio_to_save, S.fs, 'BitRate', 128);
                otherwise
                    % 默认保存为WAV格式
                    if isempty(ext)
                        filename = [filename '.wav'];
                    end
                    audiowrite(filename, audio_to_save, S.fs);
            end
            
            % --- 用每个通道的最大幅度替换原来的单一 max_val 提示 ---
            % 准备通道信息字符串（例如 "ch1: 0.98; ch2: 1.20"）
            chCount = numel(channel_max);
            channel_cells = arrayfun(@(v,i) sprintf('ch%d: %.2f', i, v), channel_max, 1:chCount, 'UniformOutput', false);
            channel_info = strjoin(channel_cells, '; ');
    
            if any(over)
                setStatus(handles, sprintf('已保存：%s (已归一化，原各通道最大幅度：%s)', filename, channel_info));
                uialert(fig_GUI, sprintf('已保存：%s (已归一化)\n原各通道最大幅度：%s', filename, channel_info), '保存成功', 'Icon', 'success');
            else
                setStatus(handles, sprintf('已保存：%s (各通道最大幅度：%s)', filename, channel_info));
                uialert(fig_GUI, sprintf('已保存：%s\n各通道最大幅度：%s', filename, channel_info), '保存成功', 'Icon', 'success');
            end

        catch ME
            uialert_safe(fig_GUI, ['保存失败：' ME.message], '保存错误');
            setStatus(handles,['保存失败：', ME.message]);
            fprintf('调试点77：保存滤波后的音频失败\n');
        end
    end

    %% ---- “导出数据到工作区”按钮回调 ----
    function onExportDataToWorkspace(~,~)
        % 只读取 S / handles，不做任何写回（不更改主流程数据）
        try
            % 先检查是否有可导出的任何数据
            hasAny = false;
            if isprop(S,'currentSignal') && ~isempty(S.currentSignal), hasAny = true; end
            if isprop(S,'audioSignal') && ~isempty(S.audioSignal), hasAny = true; end
            if isprop(S,'wsSignal') && ~isempty(S.wsSignal), hasAny = true; end
            if isprop(S,'noisy') && ~isempty(S.noisy), hasAny = true; end
            if isprop(S,'filtered') && ~isempty(S.filtered), hasAny = true; end
            if isprop(S,'filteredHistory') && ~isempty(S.filteredHistory), hasAny = true; end
    
            if ~hasAny
                uialert_safe(fig_GUI, '没有可导出的数据（请先加载/生成/导入/滤波/加噪）。', '导出失败');
                setStatus(handles,'导出失败：无数据');
                return;
            end
    
            % 询问用户希望导出的 workspace 变量名（默认 exportedDSP）
            try
                % ansName = inputdlg({'Workspace 变量名（将创建为 struct）:'}, '导出到工作区', 1, {'exportedDSP'});
                prompt = {'Workspace 变量名（将创建为 struct）:'};
                dlgtitle = '导出数据到工作区';
                fieldsize = [1 50];
                definput = {'exportedDSP'};
                ansName = inputdlg(prompt,dlgtitle,fieldsize,definput);
                if isempty(ansName), setStatus(handles,'导出取消'); 
                    return; 
                end
                varname = ansName{1};
                % 确保为合法变量名
                varname = matlab.lang.makeValidName(varname);
            catch
                % 回退默认变量名
                varname = 'exportedDSP';
            end
    

            % --- 构造导出结构体（全部为副本 / 只读） ---
            exportData = struct();
    
            % 元数据
            % --- 自动检测当前主文件名（带扩展名）及其完整路径，若失败则回退为 'unknown_gui' / '' ---
            try
                guiFile = 'unknown_gui';
                guiFilePath = ''; % 默认空路径
            
                % 优先：mfilename('fullpath')（注意：通常返回不含扩展名的完整路径/文件名）
                ffull = mfilename('fullpath');
                if isempty(ffull)
                    % 在某些情形 mfilename 返回 ''（脚本、App Designer 回调等），尝试取编辑器当前激活文件
                    try
                        ffull = matlab.desktop.editor.getActiveFilename(); % 返回完整路径（含扩展名）或 ''
                    catch
                        ffull = '';
                    end
                end
            
                if ~isempty(ffull)
                    % fileparts 能处理带或不带扩展名的路径
                    [fpath, fname, ext] = fileparts(ffull);
                    if isempty(ext)
                        % mfilename 可能不带扩展，补回 .m
                        ext = '.m';
                    end
                    guiFile = [fname ext];
                    if ~isempty(fpath)
                        guiFilePath = fullfile(fpath, [fname ext]);
                    else
                        % 若 fpath 为空（极少见），把 guiFilePath 置为 guiFile（相对名）
                        guiFilePath = guiFile;
                    end
                else
                    % 回退：从调用栈取定义该回调/函数的文件名（通常含完整路径）
                    st = dbstack('-completenames');
                    if ~isempty(st)
                        try
                            fileOnStack = st(end).file; % 完整路径（含扩展）
                            [fpath, fname, ext] = fileparts(fileOnStack);
                            if isempty(ext), ext = '.m'; end
                            guiFile = [fname ext];
                            guiFilePath = fullfile(fpath, [fname ext]);
                        catch
                            guiFile = 'unknown_gui';
                            guiFilePath = '';
                        end
                    else
                        guiFile = 'unknown_gui';
                        guiFilePath = '';
                    end
                end
            catch
                guiFile = 'unknown_gui';
                guiFilePath = '';
            end
            
            exportData.meta = struct( ...
                'export_time', char(datetime("now",'Format','yyyy-MM-dd HH:mm:ss')), ... 
                'matlab_version', version, ...
                'gui_file_name', guiFile, ...
                'gui_file_path', guiFilePath, ...
                'signalSource_ui_selection', '' ...
            );


            % ---------- 新增：写入数据源相关的原始采样率及元信息（只读，不修改 S） ----------
            % 记录 UI 上当前选择（已存在）
            try exportData.meta.signalSource_ui_selection = handles.ddDataSource.Value; catch; end

            % 方便外部解析的统一字段：exportData.signalSource （包含 type + details）
            exportData.signalSource = struct();
            try
                srcVal = '';
                if isprop(handles,'ddDataSource'), srcVal = handles.ddDataSource.Value; end
            catch
                srcVal = '';
            end

            switch srcVal
                case '音频信号'
                    exportData.signalSource.type = 'audio_signal';
                    % 优先取原始导入/文件的采样率字段（S.audioFs）,而不是当前 S.fs（可能被重采样）
                    exportData.signalSource.originalSamplingRate = [];
                    if isprop(S,'audioOrigFs') && ~isempty(S.audioOrigFs)
                        exportData.signalSource.originalSamplingRate = double(S.audioOrigFs);
                    end
                    exportData.signalSource.file_name = '';
                    exportData.signalSource.file_path = '';
                    if isprop(S,'audioFileName'), exportData.signalSource.file_name = S.audioFileName; end
                    if isprop(S,'audioFilePath'), exportData.signalSource.file_path = S.audioFilePath; end
                    exportData.signalSource.loadedFromFile = false;
                    if isprop(S,'loadedFromFile'), exportData.signalSource.loadedFromFile = logical(S.loadedFromFile); end
                    exportData.signalSource.hasRecorded = false;
                    if isprop(S,'hasRecorded'), exportData.signalSource.hasRecorded = logical(S.hasRecorded); end
                    exportData.signalSource.audioOrignalSignal = [];
                    if isprop(S,'audioOrignalSignal') && ~isempty(S.audioOrignalSignal)
                        exportData.signalSource.audioOrignalSignal = S.audioOrignalSignal;
                    end

                case '多频正弦'
                    exportData.signalSource.type = 'multi_tone';
                    exportData.signalSource.originalSamplingRate = [];
                    if isprop(S,'mtOrigFs') && ~isempty(S.mtOrigFs)
                        exportData.signalSource.originalSamplingRate = double(S.mtOrigFs);
                    end
                    exportData.signalSource.N = [];
                    if isprop(S,'mtN') && ~isempty(S.mtN)
                        exportData.signalSource.N = double(S.mtN);
                    else
                        % 退路：若没有 mtN，就用信号长度
                        if isprop(S,'multiToneOrignalSignal') && ~isempty(S.multiToneOrignalSignal)
                            exportData.signalSource.N = numel(S.multiToneOrignalSignal);
                        end
                    end
                    exportData.signalSource.freqs = [];
                    if isprop(S,'mtFreqs'), exportData.signalSource.freqs = S.mtFreqs; end
                    exportData.signalSource.amps = [];
                    if isprop(S,'mtAmps'), exportData.signalSource.amps = S.mtAmps; end
                    exportData.signalSource.multiToneOrignalSignal = [];
                    if isprop(S,'multiToneOrignalSignal') && ~isempty(S.multiToneOrignalSignal)
                        exportData.signalSource.multiToneOrignalSignal = S.multiToneOrignalSignal;
                    end


                case '导入工作区数据'
                    exportData.signalSource.type = 'workspace_import';
                    exportData.signalSource.originalSamplingRate = [];
                    if isprop(S,'wsOrigFs') && ~isempty(S.wsOrigFs)
                        exportData.signalSource.originalSamplingRate = double(S.wsOrigFs);
                    end
                    exportData.signalSource.var_name = '';
                    if isprop(S,'wsVarName'), exportData.signalSource.var_name = S.wsVarName; end
                    exportData.signalSource.time_var = '';
                    if isprop(S,'wsTimeVarName'), exportData.signalSource.time_var = S.wsTimeVarName; end
                    exportData.signalSource.fromWorkspaceOrignalSignal = [];
                    if isprop(S,'fromWorkspaceOrignalSignal') && ~isempty(S.fromWorkspaceOrignalSignal)
                        exportData.signalSource.fromWorkspaceOrignalSignal = S.fromWorkspaceOrignalSignal;
                    end
                otherwise
                    exportData.signalSource.type = 'unknown';
            end
            % -----------------------------------------------------------------

            % 是否有效重采样
            exportData.hasResampled = false;
            if isprop(S,'hasResampled'), exportData.hasResampled = logical(S.hasResampled); end
                           

            % 采样率（当前 S.fs）
            exportData.currentSamplingRate = [];
            if isprop(S,'fs') && isnumeric(S.fs) && ~isempty(S.fs)
                exportData.currentSamplingRate = double(S.fs);
            end
    
            % 不同来源的数据（均以列向量保存副本）
            exportData.currentAudioSignal = [];
            exportData.currentMultiToneSignal = [];
            exportData.currentFromWorkspaceSignal = [];
            if isprop(S,'currentSignal') && ~isempty(S.currentSignal)
                currentSignal = S.currentSignal;
                switch srcVal
                    case '音频信号'
                        exportData.currentAudioSignal = currentSignal;
                    case '多频正弦'
                        exportData.currentMultiToneSignal = currentSignal;
                    case '导入工作区数据'
                        exportData.currentFromWorkspaceSignal = currentSignal;
                    otherwise
                end
            end
    
            % 标记是否为已确认的噪声
            exportData.noiseConfirmed = false;
            if isprop(S,'noiseConfirmed') && S.noiseConfirmed
                exportData.noiseConfirmed = true;
            end
            % 加噪后的数据（如果有）
            exportData.noisiedSignal = [];
            if isprop(S,'noisy') && ~isempty(S.noisy)
                exportData.noisiedSignal = S.noisy;
            end
        
    
            % 当前使用的数据
            exportData.currentUseSignal = struct();
            if isprop(S,'currentSignal') && ~isempty(S.currentSignal)
                exportData.currentUseSignal.currentUseSourceSignal = S.currentSignal;
            else
                exportData.currentUseSignal.currentUseSourceSignal = [];
            end
            if isprop(S,'noisy') && ~isempty(S.noisy)
                exportData.currentUseSignal.currentUseNoisiedSignal = S.noisy;
            else
                exportData.currentUseSignal.currentUseNoisiedSignal = [];
            end

            % 当前（或最近一次）滤波后 / 滤波结果
            exportData.filteredCurrent = [];
            if isprop(S,'filtered') && ~isempty(S.filtered)
                exportData.filteredCurrent = S.filtered;
            end
    
            % 顶层滤波器参数（主流程最后写入的 b/a 等）
            exportData.filter = struct();
            if isprop(S,'filter_b') && ~isempty(S.filter_b)
                exportData.filter.b = S.filter_b(:).';
            end
            if isprop(S,'filter_a') && ~isempty(S.filter_a)
                exportData.filter.a = S.filter_a(:).';
            end
            % 可能存在的 sos （按字段保存 if present）
            if isprop(S,'filter_sos') && ~isempty(S.filter_sos)
                exportData.filter.sos = S.filter_sos;
            end
    
            % 导出每次有效滤波的历史（按主流程保存的 S.filteredHistory 与 S.filterHistory）
            if isprop(S,'filteredHistory') && ~isempty(S.filteredHistory)
                % copy cell array (不改原结构)
                exportData.filteredHistory = S.filteredHistory;
            else
                exportData.filteredHistory = {};
            end
            if isprop(S,'filterHistory') && ~isempty(S.filterHistory)
                exportData.filterHistory = S.filterHistory; % each element expected struct('b',b,'a',a)
            else
                exportData.filterHistory = {};
            end
    
            % 继续滤波相关：基准与临时试验（若存在）
            exportData.continueFilter = struct();
            if isprop(S,'continueFilterBase') && ~isempty(S.continueFilterBase)
                exportData.continueFilter.base = S.continueFilterBase;
            else
                exportData.continueFilter.base = [];
            end
            if isprop(S,'continueTempLatest') && ~isempty(S.continueTempLatest)
                exportData.continueFilter.latestTemp = S.continueTempLatest;
            else
                exportData.continueFilter.latestTemp = [];
            end
            exportData.continueFilter.count = 0;
            if isprop(S,'continueFilterCount')
                exportData.continueFilter.count = S.continueFilterCount;
            end
            exportData.continueFilter.max = [];
            if isprop(S,'continueFilterMax')
                exportData.continueFilter.max = S.continueFilterMax;
            end
    
            % 把 GUI 中设计参数等"辅助信息"一起导出（如果存在）
            extras = struct();
            if isprop(handles,'yuleWalkParams'), extras.yuleWalkParams = handles.yuleWalkParams; end
            if isprop(handles,'maxflatParams'), extras.maxflatParams = handles.maxflatParams; end
            if isprop(handles,'fir2Params'), extras.fir2Params = handles.fir2Params; end
            if isprop(handles,'firpmParams'), extras.firpmParams = handles.firpmParams; end
            if isprop(handles,'cfirpmParams'), extras.cfirpmParams = handles.cfirpmParams; end
            if isprop(handles,'firlsParams'), extras.firlsParams = handles.firlsParams; end
            if isprop(handles,'firclsParams'), extras.firclsParams = handles.firclsParams; end
            if isprop(handles,'fircls1Params'), extras.fircls1Params = handles.fircls1Params; end
            if isprop(handles,'notchPeakFilters'), extras.notchPeakFilters = handles.notchPeakFilters; end
            if isprop(handles,'intfiltParams'), extras.intfiltParams = handles.intfiltParams; end
            if isprop(handles,'gaussdesignParams'), extras.gaussdesignParams = handles.gaussdesignParams; end
            if isprop(handles,'rcosdesignParams'), extras.rcosdesignParams = handles.rcosdesignParams; end
            if isprop(handles,'sgolayParams'), extras.sgolayParams = handles.sgolayParams; end
            % if isprop(handles,'multiBandParams'), extras.multiBandParams = handles.multiBandParams; end
            exportData.extras = extras;
    
            % 最后写入 base workspace（不会修改 S 或 handles）
            assignin('base', varname, exportData);
    
            % 更新 GUI 状态
            setStatus(handles,sprintf('已导出数据到工作区变量: %s', varname));
            % 使用 'success' 图标（如果支持）
            uialert(fig_GUI, sprintf('导出完成：已创建变量 ''%s'' （结构体）。', varname), '导出成功', 'Icon', 'success');


        catch ME
            % 出错但不更改 S
            warning('onExportWorkspace:Failed','导出到工作区发生错误：%s', ME.message);
            setStatus(handles,['导出失败：', ME.message]);
            uialert(fig_GUI, ['导出失败：', ME.message], '错误');
        end
    end
   
    %% ---- 获取当前绘图模式。'plot' 或 'stem'（仅针对信号的时域/频谱图）
    function mode = getSignalPlotMode(handles)
        % 返回 'plot' 或 'stem'（仅针对信号的时域/频谱图）
        try
            mode = handles.plotSettings.signalPlotMode;
            if isempty(mode), mode = 'plot'; end
        catch
            mode = 'plot';
        end
    end

    %% ---- 更新设计方法提示标签并同步状态栏 ---- 
    function updateDesignLabel(S, handles)
    % 传入的 handle类 S, handles
    % 对 S 的对象内容有 "读" 操作，无 "写" 操作
    % 对 handles 的对象内容有 "读/写" 操作

    % UPDATEDESIGNLABEL 更新设计方法提示标签并同步状态栏
    %   updateDesignLabel(S, handles)
    %
    % 说明：本函数只负责生成一条描述性字符串 msg，统一设置
    %       handles.lblDesignSelected.Text = msg; 并调用 setStatus(handles,msg)。
    
        % --- 建立短名便于阅读 ---
        method    = handles.ddDesignMethod.Value;
        iirProto  = handles.ddIIRProto.Value;
        iirOrder  = round(double(handles.edtIIROrder.Value));
        winName   = handles.ddWindow.Value;
        firOrder  = round(double(handles.edtFIROrder.Value));
        firMethod = handles.ddFIRMethod.Value;

        % IIR
        if strcmpi(method, 'IIR')
            if ~isprop(S, 'actualIIROrder') && iirOrder <= 0
                msg = sprintf('当前选择：IIR - %s (阶数自动估算)', iirProto);
            elseif isprop(S, 'actualIIROrder') && iirOrder <= 0
                msg = sprintf('当前选择：IIR - %s (自动估算阶数 %d)', iirProto, S.actualIIROrder);
            else
                msg = sprintf('当前选择：IIR - %s (自定义阶数 %d)', iirProto, iirOrder);
            end
    
        % FIR 窗函数法
        elseif strcmpi(method, 'FIR窗函数法')
            % 特殊：Kaiser 在自动估算时只提阶数（原有逻辑）
            if ~isprop(S, 'actualFIROrder') && firOrder <= 0 && strcmpi(winName, 'Kaiser')
                msg = sprintf('当前选择：FIR窗函数法 - %s(阶数自动估算)', winName);
            elseif isprop(S, 'actualFIROrder') && firOrder <= 0 && strcmpi(winName, 'Kaiser')
                msg = sprintf('当前选择：FIR窗函数法 - %s (自动估算阶数 %d, 抽头数 %d) ', ...
                              winName, S.actualFIROrder, S.actualFIROrder + 1);
            else
                msg = sprintf('当前选择：FIR窗函数法 - %s (自定义阶数 %d, 抽头数 %d) ', ...
                              winName, firOrder, firOrder + 1);
            end
    
        % FIR 频率采样法（always custom order in your snippet）
        elseif strcmpi(method, 'FIR频率采样法')
            msg = sprintf('当前选择：FIR频率采样法 (自定义阶数 %d, 抽头数 %d)', firOrder, firOrder + 1);
    
        % FIR 优化设计法
        elseif strcmpi(method, 'FIR优化设计法')
            % 当方法为 Parks-McClellan 且阶数 <=0 时，用 S.actualFIROrder 做自动估算分支
            if ~isprop(S, 'actualFIROrder') && firOrder <= 0 && strcmpi(firMethod, 'Parks-McClellan')
                msg = sprintf('当前选择：FIR优化设计法 - %s (阶数自动估算)', firMethod);
            elseif isprop(S, 'actualFIROrder') && firOrder <= 0 && strcmpi(firMethod, 'Parks-McClellan')
                msg = sprintf('当前选择：FIR优化设计法 - %s (自动估算阶数 %d, 抽头数 %d)', ...
                              firMethod, S.actualFIROrder, S.actualFIROrder + 1);
            else
                msg = sprintf('当前选择：FIR优化设计法 - %s (自定义阶数 %d, 抽头数 %d)', ...
                              firMethod, firOrder, firOrder + 1);
            end
    
        % 陷波
        elseif strcmp(method, '陷波')
            % 先判断字段是否存在
            if ~isprop(handles, 'NotchOrder')
                msg = sprintf('当前选择：%s', method);
            else
                % 字段存在，判断是否为有效对象
                if isobject(handles.NotchOrder) && isvalid(handles.NotchOrder)
                    % 对象有效，获取Value并判断
                    if handles.NotchOrder.Value > 0
                        msg = sprintf('当前选择：%s (自定义阶数 %d)', method, handles.NotchOrder.Value);
                    else
                        msg = sprintf('当前选择：%s', method);
                    end
                else
                    % 对象无效或不是对象
                    msg = sprintf('当前选择：%s', method);
                end
            end
        
        % 峰值滤波
        elseif strcmp(method, '峰值滤波')
            if ~isprop(handles, 'PeakOrder')
                msg = sprintf('当前选择：%s', method);
            else
                if isobject(handles.PeakOrder) && isvalid(handles.PeakOrder)
                    if handles.PeakOrder.Value > 0
                        msg = sprintf('当前选择：%s (自定义阶数 %d)', method, handles.PeakOrder.Value);
                    else
                        msg = sprintf('当前选择：%s', method);
                    end
                else
                    msg = sprintf('当前选择：%s', method);
                end
            end

        else
            % 兜底：若以后拓展新方法，可在此处显示 method 名称
            msg = sprintf('当前选择：%s', method);
        end
    
        % --- 应用到界面 ---
        try
            handles.lblDesignSelected.Text = msg;
        catch
            % 兼容旧代码中可能的命名差异（例如你在其它地方把 lblDesignSelected 名为 lblDesignSelected）
            warning('无法直接设置 handles.lblDesignSelected.Text，请检查句柄字段名。');
        end
        
        % --- 准备传给 setStatus 的字符串（去掉 "当前选择：" 前缀） ---
        prefix = '当前选择：';
        if strncmp(msg, prefix, numel(prefix))
            statusMsg = strtrim(msg(numel(prefix)+1:end));  % 去掉前缀并修剪空格
        else
            statusMsg = msg; % 若没有前缀则直接使用原 msg
        end
    
        % --- 更新状态栏（不带前缀） --- 
        try
            setStatus(handles,statusMsg);
        catch
            % 静默忽略 setStatus 错误（保持原行为）
        end

    end

    %% ---- 备注文本更新 ----
    function updateNote(S, handles)
    % 传入的 handle类 S, handles
    % 对 S 的对象内容有 "读" 操作，无 "写" 操作
    % 对 handles 的对象内容有 "读/写" 操作

        lines = {};  % 创建变量 lines
    
        % 采样率
        lines{end+1} = sprintf('采样率: %d Hz', S.fs);
        if isempty(S.currentSignal)
            lines{end+1} = '音频: 未加载';
        else
            dur = length(S.currentSignal)/S.fs;
            lines{end+1} = sprintf('音频: 已加载，时长 %.2f s', dur);
        end
      
        % 录音模式
        lines{end+1} = sprintf('录音模式: %s', handles.ddRecMode.Value);
        if strcmp(handles.ddRecMode.Value,'定时录音')
            lines{end+1} = sprintf('定时录音时长: %.2f s', handles.edtRecDuration.Value);
        end
    
        % 仿真噪声
        if S.addNoise
            lines{end+1} = sprintf('噪声仿真: 已启用');
        else
            lines{end+1} = '噪声仿真: 未启用';
        end
            
        % 添加绘图模式信息
        plotMode = getSignalPlotMode(handles);
        lines{end+1} = sprintf('绘图模式推荐plot。stem绘图耗时较长。当前选择: %s', plotMode);
   
        lines{end+1} = sprintf('如果需要链式滤波，请点击"继续滤波"按钮。在本轮滤波情况下，可以重复设计应用滤波器，只有点击"继续滤波"按钮才会将最近一次滤波作为有效滤波提交，然后进入下一轮滤波。');

        % 滤波器信息
        method = handles.ddDesignMethod.Value;
        f1v = handles.edtPb1.Value;
        f2v = handles.edtPb2.Value;
        ftype = handles.ddType.Value;

        % ------------------ IIR设计法备注信息显示 ------------------
        if strcmpi(method,'IIR')
            proto = handles.ddIIRProto.Value;
            ord = round(double(handles.edtIIROrder.Value));
    
            lines{end+1} = sprintf('IIR中阶数建议先自动估算，然后据此自定义特定需求的阶数');
            lines{end+1} = sprintf('IIR中阶数设置: 除Yule-Walher、maxflat外，阶数输入 ≤ 0 时将自动估算，当前输入值：%d',ord);
           
            if  ~isprop(S, 'actualIIROrder') && ord <= 0 
                lines{end+1} = sprintf( '滤波器: IIR - %s (%s, 阶数自动估算)', proto, ftype );
                lines{end+1} = sprintf('Rp = %.2f dB, As = %.2f dB', handles.edtRp.Value, handles.edtRs.Value);
                if any(strcmp(ftype,{'带通','带阻'}))
                    lines{end+1} = sprintf('通带截止: fp1=%.0f Hz, fp2=%.0f Hz', f1v, f2v);
                    lines{end+1} = sprintf('阻带截止: fst1=%.0f Hz, fst2=%.0f Hz', handles.edtSb1.Value, handles.edtSb2.Value);
                elseif any(strcmp(ftype,{'低通','高通'})) 
                    lines{end+1} = sprintf('通带截止: fp=%.0f Hz ', f1v);
                    lines{end+1} = sprintf('阻带截止: fst=%.0f Hz ', handles.edtSb1.Value);
                end
            elseif isprop(S, 'actualIIROrder') && ord <= 0 
                lines{end+1} = sprintf('滤波器: IIR - %s (%s, 自动估算阶数 n=%d)', proto, ftype, S.actualIIROrder );
                if any(strcmp(ftype,{'带通','带阻'}))
                    lines{end+1} = sprintf('通带截止: fp1=%.0f Hz, fp2=%.0f Hz', f1v, f2v);
                    lines{end+1} = sprintf('阻带截止: fst1=%.0f Hz, fst2=%.0f Hz', handles.edtSb1.Value, handles.edtSb2.Value);
                elseif any(strcmp(ftype,{'低通','高通'})) 
                    lines{end+1} = sprintf('通带截止: fp=%.0f Hz ', f1v);
                    lines{end+1} = sprintf('阻带截止: fst=%.0f Hz ', handles.edtSb1.Value);
                end
            else
                lines{end+1} = sprintf('滤波器: IIR - %s (%s, 自定义阶数 n=%d)', proto, ftype, ord);
                
                switch proto
                    case 'Butterworth'
                        if any(strcmp(ftype,{'带通','带阻'}))
                            lines{end+1} = sprintf('通带截止: fp1=%.0f Hz, fp2=%.0f Hz', f1v, f2v);
                        elseif any(strcmp(ftype,{'低通','高通'})) 
                            lines{end+1} = sprintf('通带截止: fp1=%.0f Hz ', f1v);
                        end
                    case 'Chebyshev I'
                        lines{end+1} = sprintf('通带最大衰减 Rp = %.2f dB', handles.edtRp.Value);
                        if any(strcmp(ftype,{'带通','带阻'}))
                            lines{end+1} = sprintf('通带截止: fp1=%.0f Hz, fp2=%.0f Hz', f1v, f2v);
                        elseif any(strcmp(ftype,{'低通','高通'})) 
                            lines{end+1} = sprintf('通带截止: fp1=%.0f Hz ', f1v);
                        end
                    case 'Chebyshev II'
                        lines{end+1} = sprintf('阻带最小衰减 As = %.2f dB', handles.edtRs.Value);
                        if any(strcmp(ftype,{'带通','带阻'}))
                            lines{end+1} = sprintf('阻带截止: fst1=%.0f Hz, fst2=%.0f Hz', handles.edtSb1.Value, handles.edtSb2.Value);
                        elseif any(strcmp(ftype,{'低通','高通'})) 
                            lines{end+1} = sprintf('阻带截止: fst1=%.0f Hz ', handles.edtSb1.Value);
                        end
                    case 'Elliptic'
                        lines{end+1} = sprintf('Rp = %.2f dB, As = %.2f dB', handles.edtRp.Value, handles.edtRs.Value);
                        if any(strcmp(ftype,{'带通','带阻'}))
                            lines{end+1} = sprintf('通带截止: fp1=%.0f Hz, fp2=%.0f Hz', f1v, f2v);
                        elseif any(strcmp(ftype,{'低通','高通'})) 
                            lines{end+1} = sprintf('通带截止: fp1=%.0f Hz ', f1v);
                        end
                    case 'Yule-Walker'
                        if any(strcmp(ftype,{'带通','带阻'}))
                            lines{end+1} = sprintf('通带截止: fp1=%.0f Hz, fp2=%.0f Hz', f1v, f2v);
                            lines{end+1} = sprintf('阻带截止: fst1=%.0f Hz, fst2=%.0f Hz', handles.edtSb1.Value, handles.edtSb2.Value);
                        elseif any(strcmp(ftype,{'低通','高通'})) 
                            lines{end+1} = sprintf('通带截止: fp=%.0f Hz ', f1v);
                            lines{end+1} = sprintf('阻带截止: fst=%.0f Hz ', handles.edtSb1.Value);
                        elseif strcmp(ftype,'多带/高级')
                            try
                                multiBand_params = handles.yuleWalkParams;                    
                                nyq = S.fs/2;
                                order = multiBand_params.n;
                                freq  = multiBand_params.f;
                                f_norm = multiBand_params.f / nyq; % 归一化到 [0 1]
                                amp = multiBand_params.m; 

                                lines{end+1} = sprintf('IIR - Yule-Walker - 用户设置的多带滤波参数：');
                                lines{end+1} = sprintf('滤波器阶数 N = %d', order);
                                lines{end+1} = sprintf('f = %s ', mat2str(freq));
                                lines{end+1} = sprintf('f_norm(π) = %s ', mat2str(f_norm, 4));
                                lines{end+1} = sprintf('m = %s ', mat2str(amp));
                            catch
                            end
                        end

                    case 'maxflat'
                        lines{end+1} = sprintf('广义巴特沃斯（maxflat）支持滤波类型为：低通、高通、多带/高级。');
                        lines{end+1} = sprintf('广义巴特沃斯（maxflat）在非"多带/高级"滤波类型下，分子分母系数阶数由 IIR阶数 输入框设为相同阶数。若需要分子分母系数阶数不同，需要在"多带/高级"滤波类型下点击"多带 / 高级滤波参数"按钮设置。');
                        if any(strcmp(ftype,{'低通','高通'})) 
                            lines{end+1} = sprintf('通带截止: fp=%.0f Hz ', f1v);
                        elseif strcmp(ftype,'多带/高级')
                            try
                                nyq = S.fs/2;
                                if isprop(handles,'fircls1Params')
                                   maxflatParams = handles.maxflatParams;
                                end 
                                lines{end+1} = 'IIR-maxflat - 用户设置的多带/高级滤波参数：';
                                if isfield(maxflatParams,'maxflat_FilterType') && ~isempty(maxflatParams.maxflat_FilterType)
                                    lines{end+1} = sprintf('  滤波类型: %s ', maxflatParams.maxflat_FilterType);
                                end 
                                if isfield(maxflatParams,'maxflat_n') && ~isempty(maxflatParams.maxflat_n)
                                    order_n = round(double(maxflatParams.maxflat_n));
                                    lines{end+1} = sprintf('  分子阶数n = %d ', order_n);
                                end 
                                if isfield(maxflatParams,'maxflat_m') && ~isempty(maxflatParams.maxflat_m)
                                    order_m = round(double(maxflatParams.maxflat_m));
                                    lines{end+1} = sprintf('  分母阶数m = %d ', order_m);
                                end 

                                if isfield(maxflatParams,'maxflat_fn') && ~isempty(maxflatParams.maxflat_fn)
                                    lines{end+1} = sprintf('  截止频率fn(Hz) = %g ', double(maxflatParams.maxflat_fn));
                                    try lines{end+1} = sprintf('  fn_norm(π) = %s', mat2str(double(maxflatParams.maxflat_fn)./nyq,4)); catch; end
                                end 
                                
                                if isfield(maxflatParams,'maxflat_sym') && ~isempty(maxflatParams.maxflat_sym)
                                    lines{end+1} = sprintf('  是否勾选对称性约束（1 表示勾选；0 表示未勾选）：%d ', double(maxflatParams.maxflat_sym));
                                end 

                                if isfield(maxflatParams,'maxflat_designflag') && ~isempty(maxflatParams.maxflat_designflag)
                                    lines{end+1} = sprintf('  designDisplay = %s', mat2str(maxflatParams.maxflat_designflag));
                                end

                            catch
                            end
                        end

                end
            end

        % ------------------ FIR窗函数法备注信息显示 ------------------
        elseif strcmpi(method,'FIR窗函数法')
            ord = round(double(handles.edtFIROrder.Value));
            wnd = handles.ddWindow.Value;
            lines{end+1} = sprintf('FIR 窗函数法阶数建议先使用Kaiser自动估算，然后据此自定义特定需求的阶数');
            if strcmpi(wnd,'Kaiser')
                lines{end+1} = sprintf('FIR窗函数法-Kaiser窗的阶数设置: 阶数输入 ≤ 0 时将自动估算，当前输入值：%d',ord);
            end
            if  ~isprop(S, 'actualFIROrder') && ord <= 0 && strcmpi(wnd,'Kaiser')
                lines{end+1} = sprintf('滤波器: FIR 窗函数法 (%s, 阶数将自动估算, 窗 %s)', ftype, wnd);
            elseif isprop(S, 'actualFIROrder') && ord <= 0 && strcmpi(wnd,'Kaiser')
                lines{end+1} = sprintf('滤波器: FIR 窗函数法 (%s, 阶数 %d(抽头数 %d) (自动估算), 窗 %s)', ftype, S.actualFIROrder, S.actualFIROrder+1, wnd);
            else
               lines{end+1} = sprintf('滤波器: FIR 窗函数法 (%s, 阶数 %d(抽头数 %d), 窗 %s)', ftype, ord, ord+1, wnd);
            end 

            if any(strcmp(ftype,{'带通','带阻'})) 
                if  strcmpi(wnd,'Kaiser')
                    lines{end+1} = sprintf('Rp = %.2f dB, As = %.2f dB', handles.edtRp.Value, handles.edtRs.Value);
                    if ord <= 0 
                        lines{end+1} = sprintf('通带截止: fp1=%.0f Hz, fp2=%.0f Hz', f1v, f2v);
                        lines{end+1} = sprintf('阻带截止: fst1=%.0f Hz, fst2=%.0f Hz', handles.edtSb1.Value, handles.edtSb2.Value);
                    elseif ord > 0 
                        lines{end+1} = sprintf('通带截止: fp1=%.0f Hz, fp2=%.0f Hz', f1v, f2v);
                    end
                else
                    lines{end+1} = sprintf('通带截止: fp1=%.0f Hz, fp2=%.0f Hz', f1v, f2v);
                end
            elseif any(strcmp(ftype,{'低通','高通'})) 
                 if  strcmpi(wnd,'Kaiser')
                     lines{end+1} = sprintf('Rp = %.2f dB, As = %.2f dB', handles.edtRp.Value, handles.edtRs.Value);
                    if ord <= 0 
                        lines{end+1} = sprintf('通带截止: fp=%.0f Hz', f1v);
                        lines{end+1} = sprintf('阻带截止: fst=%.0f Hz', handles.edtSb1.Value);
                    elseif ord > 0 
                        lines{end+1} = sprintf('通带截止: fp=%.0f Hz', f1v);
                    end
                else
                    lines{end+1} = sprintf('通带截止: fp=%.0f Hz', f1v);
                end
            end

        % ------------------ FIR优化设计法备注信息显示 ------------------
        elseif strcmpi(method,'FIR优化设计法') 
            ord = round(double(handles.edtFIROrder.Value));
            firMethod = handles.ddFIRMethod.Value;
            if any(strcmp(ftype,{'低通','高通','带通','带阻'}))
                lines{end+1} = sprintf('FIR 优化设计法阶数建议先使用Parks-McClellan自动估算，然后据此自定义特定需求的阶数');
               
                if strcmpi(firMethod, 'Parks-McClellan')
                    lines{end+1} = sprintf('对于FIR 优化设计法中Parks-McClellan的阶数设置: 阶数输入 ≤ 0 时将自动估算，当前输入值：%d',ord);
                end
    
                if  ~isprop(S, 'actualFIROrder') && ord <= 0 && strcmpi(firMethod, 'Parks-McClellan')
    
                    lines{end+1} = sprintf('滤波器: FIR 优化设计法 (%s, 阶数将自动估算, 方法 %s)', ftype, firMethod);
                elseif isprop(S, 'actualFIROrder') && ord <= 0 && strcmpi(firMethod, 'Parks-McClellan')
                    lines{end+1} = sprintf('滤波器: FIR 优化设计法 (%s, 阶数 %d(抽头数 %d) (自动估算), 当前输入方法 %s)', ftype, S.actualFIROrder, S.actualFIROrder+1, firMethod);
                else
                    lines{end+1} = sprintf('滤波器: FIR 优化设计法 (%s, 阶数 %d(抽头数 %d), 方法 %s)', ftype, ord, ord+1 ,firMethod);
                end 
    
                lines{end+1} = sprintf('Rp = %.2f dB, As = %.2f dB', handles.edtRp.Value, handles.edtRs.Value);
                if any(strcmp(ftype,{'带通','带阻'}))
                    lines{end+1} = sprintf('通带截止: fp1=%.0f Hz, fp2=%.0f Hz', f1v, f2v);
                    lines{end+1} = sprintf('阻带截止: fst1=%.0f Hz, fst2=%.0f Hz', handles.edtSb1.Value, handles.edtSb2.Value);
                elseif any(strcmp(ftype,{'低通','高通'}))
                    lines{end+1} = sprintf('通带截止: fp=%.0f Hz', f1v);
                    lines{end+1} = sprintf('阻带截止: fst=%.0f Hz', handles.edtSb1.Value);
                end

            elseif strcmp(ftype,'多带/高级')
                    if  ~isprop(S, 'actualFIROrder') && ord <= 0 && strcmpi(firMethod, 'Parks-McClellan')
        
                        lines{end+1} = sprintf('滤波器: FIR 优化设计法 (%s, 阶数将自动估算, 方法 %s)', ftype, firMethod);
                    elseif isprop(S, 'actualFIROrder') && ord <= 0 && strcmpi(firMethod, 'Parks-McClellan')
                        lines{end+1} = sprintf('滤波器: FIR 优化设计法 (%s, 阶数 %d(抽头数 %d) (自动估算), 当前输入方法 %s)', ftype, S.actualFIROrder, S.actualFIROrder+1, firMethod);
                    else
                        lines{end+1} = sprintf('对于FIR 优化设计法 - Parks-McClellan，"多带 / 高级"下支持自动估算阶数；阶数小于等于0时，点击"多带 / 高级滤波参数"按钮将会打开不同于阶数大于0时的参数设置窗口。');
                        lines{end+1} = sprintf('滤波器: FIR 优化设计法 (%s, 阶数 %d(抽头数 %d), 方法 %s)', ftype, ord, ord+1 ,firMethod);
                    end 

                    nyq = S.fs/2;
                    try
        
                        switch handles.ddFIRMethod.Value
                            case {'Parks-McClellan'}
                                % 情况 1：用户显式指定阶数 (ord > 0) -> 显示当前使用的 multiBand 参数
                                if ord > 0
                                    
                                    lines{end+1} = 'Parks-McClellan - 用户显式指定阶数 (ord > 0) 多带参数：';
                                    params = handles.firpmParams;
                                
                                    % show reported FIR order (可能 newFIROrder/save)
                                    if isfield(params,'newFIROrder') && ~isempty(params.newFIROrder)
                                        lines{end+1} = sprintf('  保存的阶数 (newFIROrder)：%d (抽头数 %d)', double(params.newFIROrder), double(params.newFIROrder)+1);
                                    else
                                        lines{end+1} = sprintf('  使用的阶数 (UI 输入)：%d (抽头数 %d)', ord, ord+1);
                                    end
                                
                                    % method / selMode
                                    if isfield(params,'method') && ~isempty(params.method)
                                        lines{end+1} = sprintf('  method = %s', char(params.method));
                                    end
                                    if isfield(params,'selMode') && ~isempty(params.selMode)
                                        lines{end+1} = sprintf('  selMode = %s', char(params.selMode));
                                    end
                                
                                    % frequency vector f (Hz) and normalized f (0..1 relative to nyq)
                                    if isfield(params,'f') && ~isempty(params.f)
                                        try
                                            fvals = double(params.f(:))';
                                            lines{end+1} = sprintf('  f(Hz) = %s', mat2str(fvals));
                                            if isfield(params,'nyq') && ~isempty(params.nyq) && params.nyq > 0
                                                fnorm = fvals ./ double(params.nyq);
                                                lines{end+1} = sprintf('  f_norm(π) = %s', mat2str(fnorm,4));
                                            elseif isfield(params,'f_norm') && ~isempty(params.f_norm)
                                                lines{end+1} = sprintf('  f_norm(π) = %s', mat2str(double(params.f_norm(:)') ,4));
                                            end
                                        catch
                                        end
                                    end
                                
                                    % amplitude vector a (if present)
                                    if isfield(params,'a') && ~isempty(params.a)
                                        try
                                            lines{end+1} = sprintf('  a = %s', mat2str(params.a));
                                        catch
                                        end
                                    end
                                
                                    % fresp info (if used)
                                    if isfield(params,'fresp') && ~isempty(params.fresp)
                                        try
                                            fr = params.fresp;
                                            % indicatives
                                            if isfield(fr,'A') && ~isempty(fr.A)
                                                lines{end+1} = sprintf('  fresp: 提供了 A (%d 项)', numel(fr.A));
                                            else
                                                lines{end+1} = '  fresp: 无显式 A (使用自定义函数或由 report 提供估计)';
                                            end
                                            if isfield(fr,'paramStyle') && ~isempty(fr.paramStyle)
                                                lines{end+1} = sprintf('  fresp.paramStyle = %s', char(fr.paramStyle));
                                            end
                                            if isfield(fr,'paramName') && ~isempty(fr.paramName)
                                                lines{end+1} = sprintf('  fresp.paramName = %s', char(fr.paramName));
                                            end
                                            if isfield(fr,'symm') && ~isempty(fr.symm)
                                                lines{end+1} = sprintf('  fresp.symmetry (report.SYM) = %s', char(fr.symm));
                                            end
                                            if isfield(fr,'report') && ~isempty(fr.report)
                                                lines{end+1} = '  fresp 校验报告已保存 (params.fresp.report)，可在调试时查看 report 字段。';
                                                % 若 report 包含 GF/DH/消息，显示简短摘要
                                                rpt = fr.report;
                                                if isfield(rpt,'GF') && isfield(rpt,'DH') && ~isempty(rpt.GF) && ~isempty(rpt.DH)
                                                    try
                                                        % 尝试从 report 推断 Nyq 处估计幅值
                                                        estNyq = interp1(rpt.GF, rpt.DH, 1, 'linear', 'extrap');
                                                        if ~isempty(estNyq) && isfinite(estNyq)
                                                            lines{end+1} = sprintf('    (report: 估计 Nyquist 处幅值 = %.6g)', estNyq);
                                                        end
                                                    catch
                                                    end
                                                end
                                                if isfield(rpt,'messages') && ~isempty(rpt.messages)
                                                    % 仅提示有 messages，避免长文本占位
                                                    lines{end+1} = sprintf('    (report.messages 含 %d 条提示/警告)', numel(rpt.messages));
                                                end
                                            end
                                        catch
                                        end
                                    end
                                
                                    % weights
                                    if isfield(params,'w') && ~isempty(params.w)
                                        try lines{end+1} = sprintf('  w = %s', mat2str(params.w)); catch; end
                                    end
                                
                                    % lgrid
                                    if isfield(params,'lgrid') && ~isempty(params.lgrid)
                                        try lines{end+1} = sprintf('  lgrid = %s', mat2str(params.lgrid)); catch; end
                                    end
                                
                                    % odd symmetry / hilbert / differentiator
                                    if isfield(params,'oddType') && ~isempty(params.oddType)
                                        try lines{end+1} = sprintf('  oddType = %s', char(params.oddType)); catch; end
                                    end
                                    if isfield(params,'hilbert_return') && ~isempty(params.hilbert_return)
                                        try lines{end+1} = sprintf('  hilbert_return = %s', char(params.hilbert_return)); catch; end
                                    end
                                
                                    % output option
                                    if isfield(params,'outputOpt') && ~isempty(params.outputOpt)
                                        try lines{end+1} = sprintf('  outputOpt = %s', char(params.outputOpt)); catch; end
                                    end
                                
                                    % 额外提示：若存在 estimatedAmpAtNyq（由 validate 得到）
                                    if isfield(params,'estimatedAmpAtNyq') && ~isempty(params.estimatedAmpAtNyq)
                                        try lines{end+1} = sprintf('  估计 Nyquist 处幅值 (from validate) = %.6g', double(params.estimatedAmpAtNyq)); catch; end
                                    end
                                   
                                % 情况 2：ord <= 0 -> 使用 firpmord 自动估阶，显示历史/比较参数（paramsHistory / paramsCal）
                                else
                                    lines{end+1} = 'Parks-McClellan - (阶数 <= 0，使用 firpmord 自动估阶)';
                
                                    % 显示用户保存的历史参数（最近一次）
                                    if isprop(handles, 'firpmMBPaHistory') && ~isempty(handles.firpmMBPaHistory)
                                        phis = handles.firpmMBPaHistory;
                                        lines{end+1} = '  保存的多带参数历史（最近一次）：';
                                        try
                                            if isfield(phis,'f'), lines{end+1} = sprintf('    f(Hz) = %s', mat2str(double(phis.f(:)'))); end
                                            if isfield(phis,'a'), lines{end+1} = sprintf('    a = %s', mat2str(phis.a)); end
                                            if isfield(phis,'w'), lines{end+1} = sprintf('    w = %s', mat2str(phis.w)); end
                                            if isfield(phis,'dev'), lines{end+1} = sprintf('    dev = %s', mat2str(phis.dev)); end
                                        catch
                                            lines{end+1} = '    (历史参数存在但无法完整显示)';
                                        end
                                    end
                
                                    % 显示 firpmord 计算得到的参数对比（若存在）
                                    if isprop(handles, 'firpmMBPaCal') && ~isempty(handles.firpmMBPaCal)
                                        pcal = handles.firpmMBPaCal;
                                        lines{end+1} = '  firpmord 计算的参数 (对比)：';
                                        try
                                            if isfield(pcal,'f'), lines{end+1} = sprintf('    f_cal(Hz) = %s', mat2str(double(pcal.f(:)'))); end
                                            if isfield(pcal,'a'), lines{end+1} = sprintf('    a_cal = %s', mat2str(pcal.a)); end
                                            if isfield(pcal,'w'), lines{end+1} = sprintf('    w_cal = %s', mat2str(pcal.w)); end
                                            if isfield(pcal,'dev'), lines{end+1} = sprintf('    dev_cal = %s', mat2str(pcal.dev)); end
                                        catch
                                            lines{end+1} = '    (firpmord 计算参数存在但无法完整显示)';
                                        end
                                    end
                                end

                            case {'Cplx-Parks-McClellan'}
                                % ----- Robust display for Cplx-Parks-McClellan multi-band / advanced params -----
                                nyq = max(1e-6, S.fs/2); % local nyquist（防止除0）
                                ord = round(double(handles.edtFIROrder.Value));
                                % Friendly header
                                lines{end+1} = 'Cplx-Parks-McClellan - 用户设置的多带/高级滤波参数：';
                                lines{end+1} = sprintf('  FIR 阶数: %d (抽头数 %d)', ord, ord+1);
                            
                                % pick active params (current saved)
                                params = handles.cfirpmParams;
                        
                                % Helper: pick frequency field (try multiple common names)
                                if isfield(params,'fHz') && ~isempty(params.fHz)
                                    freq = params.fHz;
                                elseif isfield(params,'f') && ~isempty(params.f)
                                    freq = params.f;
                                else
                                    freq = [];
                                end
                           
                                % Frequency display
                                if ~isempty(freq)
                                    lines{end+1} = sprintf('  f (Hz) = %s', mat2str(freq));
                                    try
                                        lines{end+1} = sprintf('  f_norm(π) = %s', mat2str(double(freq)./nyq,4));
                                    catch
                                    end
                                end
                    
                                % fresp description (could be function handle, string, or cell)
                                if isfield(params,'fresp') && ~isempty(params.fresp)
                                    fr = params.fresp;
                                    if isa(fr,'function_handle')
                                        lines{end+1} = sprintf('  fresp: function handle -> %s', func2str(fr));
                                    elseif ischar(fr) || isstring(fr)
                                        lines{end+1} = sprintf('  fresp: %s', char(fr));
                                    elseif iscell(fr)
                                        lines{end+1} = sprintf('  fresp: cell (%d elements)', numel(fr));
                                    else
                                        lines{end+1} = '  fresp: (自定义/复杂对象)';
                                    end
                                end
                    
                                % amplitude / amp / a
                                if isfield(params,'a') && ~isempty(params.a)
                                    lines{end+1} = sprintf('  a (幅值向量) = %s', mat2str(params.a));
                                elseif isfield(params,'amp') && ~isempty(params.amp)
                                    lines{end+1} = sprintf('  amp (幅值向量) = %s', mat2str(params.amp));
                                end
                    
                                % weight / w
                                if isfield(params,'w') && ~isempty(params.w)
                                    lines{end+1} = sprintf('  w (权重) = %s', mat2str(params.w));
                                end
                    
                                % sym / lgrid / output / lgrid (常见额外选项)
                                if isfield(params,'sym') && ~isempty(params.sym)
                                    lines{end+1} = sprintf('  sym = %s', mat2str(params.sym));
                                end
                                if isfield(params,'lgrid') && ~isempty(params.lgrid)
                                    lines{end+1} = sprintf('  lgrid = %s', mat2str(params.lgrid));
                                end
                                if isfield(params,'output') && ~isempty(params.output)
                                    lines{end+1} = sprintf('  output = %s', mat2str(params.output));
                                end
                    
                                % debug / skip_stage2 / finalArgs 等可选参数（如存在则显示）
                                if isfield(params,'debug') && ~isempty(params.debug)
                                    lines{end+1} = sprintf('  debug = %s', mat2str(params.debug));
                                end
                                if isfield(params,'skip_stage2') && ~isempty(params.skip_stage2)
                                    lines{end+1} = sprintf('  skip_stage2 = %s', mat2str(params.skip_stage2));
                                end

                                % brief history hint if available
                                if isprop(handles,'cfirpmParamsHistory') && ~isempty(handles.cfirpmParamsHistory)
                                    lines{end+1} = sprintf('  已保存参数历史: %d 条（最近一次为当前）', numel(handles.cfirpmParamsHistory));
                                end
                                

                            case {'最小二乘(firls)'}
                                multiBand_params = handles.firlsParams;
                                freq  = multiBand_params.f;
                                f_norm = multiBand_params.f / nyq;
                                a = multiBand_params.a; 
                                lines{end+1} = sprintf('最小二乘(firls) - 用户设置的多带滤波参数：');
                                lines{end+1} = sprintf('f(Hz) = %s ', mat2str(freq));
                                lines{end+1} = sprintf('f_norm(π) = %s ', mat2str(f_norm, 4));
                                lines{end+1} = sprintf('a = %s ', mat2str(a));
                                if isfield(multiBand_params, 'w') && ~isempty(multiBand_params.w)
                                    w = multiBand_params.w;
                                    lines{end+1} = sprintf('w = %s ', mat2str(w));
                                end
                                if isfield(multiBand_params,'oddSymmetric') && ~isempty(multiBand_params.oddSymmetric) && multiBand_params.oddSymmetric
                                    if isfield(multiBand_params,'oddType') && ~isempty(multiBand_params.oddType)
                                        lines{end+1} = sprintf('已选择设计奇对称滤波器：%s ', multiBand_params.oddType);
                                    end
                                end

                            case {'约束最小二乘(fircls)'}
                                multiBand_params = handles.firclsParams;
                                freq  = multiBand_params.f;
                                f_norm = multiBand_params.f / nyq;
                                amp = multiBand_params.amp; up = multiBand_params.up; lo = multiBand_params.lo;
                                lines{end+1} = sprintf('约束最小二乘(fircls) - 用户设置的多带滤波参数：');
                                lines{end+1} = sprintf('  f = %s ', mat2str(freq));
                                lines{end+1} = sprintf('  f_norm(π) = %s ', mat2str(f_norm, 4));
                                lines{end+1} = sprintf('  amp = %s ', mat2str(amp));
                                lines{end+1} = sprintf('  up = %s ', mat2str(up));
                                lines{end+1} = sprintf('  lo = %s ', mat2str(lo));
                                if isfield(multiBand_params,'designflag') && ~isempty(multiBand_params.designflag)
                                    lines{end+1} = sprintf('  designflag = %s', mat2str(multiBand_params.designflag));
                                end

                            
                            case {'约束最小二乘1(fircls1)'}
                                % fircls1 参数保存在 handles.fircls1Params（由 openFircls1AdvancedWindow onConfirm 保存）
                                if isprop(handles,'fircls1Params')
                                    fircls1Params = handles.fircls1Params;
                                end

                                lines{end+1} = '约束最小二乘1(fircls1) - 用户设置的多带/高级滤波参数：';
                                % 显示 (用户) 输入的阶数（优先显示当前界面上的值）
                                ord = round(double(handles.edtFIROrder.Value));
                                lines{end+1} = sprintf('  FIR 阶数: %d (抽头数 %d)', ord, ord+1);
                           
                                % 基本必填项：fo, dp, ds
                                if isfield(fircls1Params,'fircls1_fo') && ~isempty(fircls1Params.fircls1_fo)
                                    lines{end+1} = sprintf('  fo (Hz) = %g', double(fircls1Params.fircls1_fo));
                                    try lines{end+1} = sprintf('  fo_norm(π) = %s', mat2str(double(fircls1Params.fircls1_fo)./nyq,4)); catch; end
                                end
                                if isfield(fircls1Params,'fircls1_dp') && ~isempty(fircls1Params.fircls1_dp)
                                    lines{end+1} = sprintf('  dp = %g', double(fircls1Params.fircls1_dp));
                                end
                                if isfield(fircls1Params,'fircls1_ds') && ~isempty(fircls1Params.fircls1_ds)
                                    lines{end+1} = sprintf('  ds = %g', double(fircls1Params.fircls1_ds));
                                end

                                % 可选模式：使用 ft 或使用 L2 (wp,ws,k)
                                if isfield(fircls1Params,'fircls1_use_ft') && fircls1Params.fircls1_use_ft && isfield(fircls1Params,'fircls1_ft') && ~isempty(fircls1Params.fircls1_ft)
                                    lines{end+1} = sprintf('  使用 ft (Hz) = %s', mat2str(fircls1Params.fircls1_ft));
                                    try lines{end+1} = sprintf('  ft_norm(π) = %s', mat2str(double(fircls1Params.fircls1_ft)./nyq,4)); catch; end
                                elseif isfield(fircls1Params,'fircls1_use_L2') && fircls1Params.fircls1_use_L2
                                    % L2 参数： fp / fs / k
                                    fpv = NaN; fsv = NaN; kv = NaN;
                                    try fpv = double(fircls1Params.fircls1_fp); catch; end
                                    try fsv = double(fircls1Params.fircls1_fs); catch; end
                                    try kv  = double(fircls1Params.fircls1_k);  catch; end
                                    if ~isnan(fpv) || ~isnan(fsv)
                                        lines{end+1} = sprintf('  使用 L2 参数: fp=%g Hz, fs=%g Hz, k=%g', fpv, fsv, kv);
                                        try lines{end+1} = sprintf('  fp_norm(π)=%s; fs_norm(π)=%s', mat2str(fpv./nyq,4), mat2str(fsv./nyq,4)); catch; end
                                    end
                                end

                                % 其它辅助字段
                                if isfield(fircls1Params,'fircls1_FirType') && ~isempty(fircls1Params.fircls1_FirType)
                                    lines{end+1} = sprintf('  FirType = %s', char(fircls1Params.fircls1_FirType));
                                end
                                if isfield(fircls1Params,'fircls1_designDisplay') && ~isempty(fircls1Params.fircls1_designDisplay)
                                    lines{end+1} = sprintf('  designDisplay = %s', mat2str(fircls1Params.fircls1_designDisplay));
                                end
                              
                        end % handles.ddFIRMethod.Value不同方法显示结束
                    
                    catch 
                        % catch ME
                        % uialert_safe(fig_GUI, sprintf('显示失败：%s', ME.message),'显示失败'); 
                    end
                    
            end % FIR优化设计法备注信息显示结束

        % ------------------ FIR频率采样法备注信息显示 ------------------
        elseif strcmpi(method,'FIR频率采样法') 
            ord = round(double(handles.edtFIROrder.Value));
            lines{end+1} = sprintf('滤波器: FIR 频率采样法 (%s, 阶数 %d(抽头数 %d))', ftype, ord, ord+1);
            if any(strcmp(ftype,{'低通','高通','带通','带阻'}))
                
                if any(strcmp(ftype,{'带通','带阻'}))
                    lines{end+1} = sprintf('通带截止: fp1=%.0f Hz, fp2=%.0f Hz', handles.edtPb1.Value, handles.edtPb2.Value);
                    lines{end+1} = sprintf('阻带截止: fst1=%.0f Hz, fst2=%.0f Hz', handles.edtSb1.Value, handles.edtSb2.Value);
                elseif any(strcmp(ftype,{'低通','高通'}))
                    lines{end+1} = sprintf('通带截止: fp=%.0f Hz', handles.edtPb1.Value);
                    lines{end+1} = sprintf('阻带截止: fst=%.0f Hz', handles.edtSb1.Value);
                end
            elseif strcmp(ftype,'多带/高级')
                try
                    multiBand_params = handles.fir2Params;                    
                    nyq = S.fs/2;
                    freq  = multiBand_params.f;
                    f_norm = multiBand_params.f / nyq; % 归一化到 [0 1]
                    amp = multiBand_params.m; 
                    lines{end+1} = sprintf('FIR频率采样法 - 用户设置的多带滤波参数：');
                    lines{end+1} = sprintf('f(Hz) = %s ', mat2str(freq));
                    lines{end+1} = sprintf('f_norm(π) = %s ', mat2str(f_norm, 4));
                    lines{end+1} = sprintf('m = %s ', mat2str(amp));
                    % npt/lap参数显示
                    if isfield(multiBand_params,'npt')
                        npt = multiBand_params.npt ;
                        lines{end+1} = sprintf('npt = %s ', mat2str(npt));
                        if isfield(multiBand_params,'lap')
                            lap = multiBand_params.lap ;
                            lines{end+1} = sprintf('lap = %s ', mat2str(lap));
                        end
                    end
                    % 窗 / KaiserBeta显示
                    if isfield(multiBand_params,'windowName')
                        windowName = multiBand_params.windowName ;
                        lines{end+1} = sprintf('window：%s ', windowName);
                        if isfield(multiBand_params,'kaiserBeta')
                            KaiserBeta = multiBand_params.kaiserBeta ;
                            lines{end+1} = sprintf('kaiserBeta：%s ', mat2str(KaiserBeta));
                        end
                    end
                catch
                end

            end % FIR频率采样法滤波类型分支结束

        % ------------------ 陷波 / 峰值滤波备注信息显示 ------------------
        elseif strcmp(method, '陷波') || strcmp(method, '峰值滤波')
            % 优先显示 handles.notchPeakParams（由 onNotchPeakParams 保存）
            if isprop(handles, 'notchPeakParams') && ~isempty(handles.notchPeakParams)
                try
                    p = handles.notchPeakParams; % 结构体，参考 onNotchPeakParams 保存逻辑
                    % 基本行：方法 + 类型标签（single/multi/comb）
                    typeLabel = '';
                    if isfield(p,'typeLabel') && ~isempty(p.typeLabel)
                        typeLabel = sprintf(' - %s', p.typeLabel);
                    elseif isfield(p,'type') && ~isempty(p.type)
                        typeLabel = sprintf(' - %s', p.type);
                    end
                    lines{end+1} = sprintf('当前选择：%s%s', method, typeLabel);

                    % 阶数 —— comb 情况不显示阶数 N
                    if isfield(p,'order') && ~isempty(p.order) && ~(isfield(p,'type') && strcmpi(p.type,'comb'))
                        lines{end+1} = sprintf('  滤波器阶数 N = %d', p.order);
                    end

                    % 中心频率（单个或向量）
                    if isfield(p,'f') && ~isempty(p.f)
                        fvals = double(p.f);
                        if isvector(fvals) && isscalar(fvals)
                            lines{end+1} = sprintf('  中心频率 f = %.2f Hz', fvals);
                        else
                            % 向量显示，保持简洁：最多显示前 10 个，其他用 "..." 省略
                            maxShow = 10;
                            if numel(fvals) <= maxShow
                                lines{end+1} = sprintf('  中心频率 f = %s Hz', mat2str(fvals));
                            else
                                lines{end+1} = sprintf('  中心频率 f (前 %d 个) = %s ...', maxShow, mat2str(fvals(1:maxShow)));
                            end
                        end
                    end

                    % 带宽 / Q 显示（bwMode: 'bw' or 'Q'; bwValue 存原始数值）
                    if isfield(p,'bwMode') && isfield(p,'bwValue') && ~isempty(p.bwValue)
                        if strcmpi(p.bwMode,'Q')
                            lines{end+1} = sprintf('  带宽模式: Q = %g', double(p.bwValue));
                        else
                            lines{end+1} = sprintf('  带宽模式: bw = %.3f Hz', double(p.bwValue));
                        end
                    end

                    % comb 特殊字段：useAb / ab
                    if isfield(p,'type') && strcmpi(p.type,'comb')
                        if isfield(p,'useAb') && p.useAb
                            if isfield(p,'ab') && ~isempty(p.ab)
                                lines{end+1} = sprintf('  梳状滤波: 设置衰减 ab = %.2f dB', double(p.ab));
                            else
                                lines{end+1} = sprintf('  梳状滤波: 设置衰减 ab (未提供具体值)');
                            end
                        end
                        % 显示近似的 Ncomb（若 f(1) 可用且 S.fs 存在）
                        if isfield(p,'f') && ~isempty(p.f) && exist('S','var') && isprop(S,'fs')
                            fcomb = double(p.f(1));
                            if isfinite(fcomb) && fcomb > 0
                                Ncomb_real = S.fs / fcomb;
                                Ncomb = max(1, round(Ncomb_real));
                                lines{end+1} = sprintf('  梳状滤波: 近似滤波器阶数 N = %d (fs/f = %.3f)', Ncomb, Ncomb_real);
                            end
                        end
                    end

                    % 若保存了 handles.notchPeakFilters（设计后系数），显示节数/合并方式提示
                    if isprop(handles, 'notchPeakFilters') && ~isempty(handles.notchPeakFilters)
                        nf = handles.notchPeakFilters;
                        if isfield(nf,'K')
                            lines{end+1} = sprintf('  已设计并保存 %d 节滤波器（供 onApplyFilter 使用）', nf.K);
                        end
                        if isfield(nf,'mode')
                            lines{end+1} = sprintf('  实际保存的模式: %s', nf.mode);
                        end
                        % 若 useCombinedForApply 字段存在，提示用户应用方式
                        if isfield(nf,'useCombinedForApply')
                            if nf.useCombinedForApply
                                lines{end+1} = '  onApplyFilter 时将使用合并传递函数（combined）';
                            else
                                lines{end+1} = '  onApplyFilter 时将逐节应用（逐段 SOS / cascade）';
                            end
                        end
                    end

                    % 若存在历史，简要提示最近一次设置的类型/时间（不打印巨量历史）
                    if isprop(handles,'notchPeakParamsHistory') && ~isempty(handles.notchPeakParamsHistory)
                        try
                            histN = numel(handles.notchPeakParamsHistory);
                            lines{end+1} = sprintf('  已保存参数组历史: %d 条（使用 onNotchPeakParams 设置）', histN);
                        catch
                        end
                    end

                catch ME
                    % 若解析出现错误则退回到稳健的回退显示（避免抛错影响 GUI）
                    warning('updateNote:notchPeakDisplayFailed','显示 陷波/峰值 参数失败: %s', ME.message);
                    % 回退到简单显示（尽量保持原来行为）
                    if isprop(handles, 'NotchOrder') && isobject(handles.NotchOrder) && isvalid(handles.NotchOrder) && handles.NotchOrder.Value > 0
                        lines{end+1} = sprintf('当前选择：%s (自定义阶数 %d)', method, handles.NotchOrder.Value);
                    else
                        lines{end+1} = sprintf('当前选择：%s', method);
                    end
                end

            else
                % fallback：保持你原来的简单逻辑（兼容旧句柄）
                if strcmp(method,'陷波')
                    if isprop(handles, 'NotchOrder') && isobject(handles.NotchOrder) && isvalid(handles.NotchOrder) && handles.NotchOrder.Value > 0
                        lines{end+1} = sprintf('当前选择：%s (自定义阶数 %d)', method, handles.NotchOrder.Value);
                    else
                        lines{end+1} = sprintf('当前选择：%s', method);
                    end
                else % 峰值
                    if isprop(handles, 'PeakOrder') && isobject(handles.PeakOrder) && isvalid(handles.PeakOrder) && handles.PeakOrder.Value > 0
                        lines{end+1} = sprintf('当前选择：%s (自定义阶数 %d)', method, handles.PeakOrder.Value);
                    else
                        lines{end+1} = sprintf('当前选择：%s', method);
                    end
                end
            end

        % ------------------ intfilt 插值滤波备注信息显示 ------------------    
        elseif strcmpi(method,'FIRintfilt插值') 

            lines{end+1} = sprintf('滤波器: FIR intfilt插值 (%s)', ftype);
            lines{end+1} = sprintf('点击"多带 / 滤波参数"按钮设置 FIRintfilt插值 滤波器参数');
            lines{end+1} = '';
            if strcmp(ftype,'多带/高级')
                try
                    params = handles.intfiltParams;                    
                    intfilt_l = double(params.intfilt_l);
                    intfilt_mode = params.intfilt_mode;
                    intfilt_filterLength = double(params.intfilt_filterLength);
                    if strcmp(intfilt_mode,'bandlimited')
                        intfilt_p = double(params.intfilt_p ); 
                        intfilt_alpha =  double(params.intfilt_alpha) ;
                    else
                        intfilt_n = double(params.intfilt_n);
                    end
                    intfilt_compensate = double(params.intfilt_compensate);

                    lines{end+1} = sprintf('FIRintfilt插值 - 用户设置的滤波参数：');
                    lines{end+1} = sprintf('  上采样因子 l = %g ', intfilt_l);
                    lines{end+1} = sprintf('  插值方式：%s ',intfilt_mode);
                    lines{end+1} = sprintf('  滤波器阶数（长度） = %g ', intfilt_filterLength);
                    if strcmp(intfilt_mode,'bandlimited')
                        lines{end+1} = sprintf('  非零样本数 p = %g ', intfilt_p);  
                        lines{end+1} = sprintf('  过渡带宽度的倒数 alpha = %g ', intfilt_alpha);  
                    else
                        lines{end+1} = sprintf('  拉格朗日多项式的阶数 n = %g ', intfilt_n);  
                    end
                    lines{end+1} = sprintf('  是否选择补偿相位（1 表示补偿相位；0 表示不补偿相位）：%g ', intfilt_compensate);  
              

                catch
                end
            end

        % ------------------ FIRgaussdesign脉冲整形 滤波备注信息显示 ------------------    
        elseif strcmpi(method,'FIRgaussdesign脉冲整形') 

            lines{end+1} = sprintf('滤波器: FIR gaussdesign脉冲整形 (%s)', ftype);
            lines{end+1} = sprintf('点击"多带 / 滤波参数"按钮设置 FIRgaussdesign脉冲整形 滤波器参数');
            lines{end+1} = '';
            if strcmp(ftype,'多带/高级')
                try
                    params = handles.gaussdesignParams;  
                    gauss_bt = double(params.bt);
                    gauss_span = double(params.span);
                    gauss_sps = double(params.sps);
                    gauss_appType = params.appType;
                    gauss_filtLen = double(params.filtLen);
                    gauss_groupDelaySamples = double(params.groupDelaySamples);

                    lines{end+1} = sprintf('FIRgaussdesign脉冲整形 - 用户设置的滤波参数：');
                    lines{end+1} = sprintf('  3dB 带宽-符号时间乘积 bt = %g ', gauss_bt);
                    lines{end+1} = sprintf('  符号数量 span  = %g ',gauss_span);
                    lines{end+1} = sprintf('  每符号采样数 sps = %g ', gauss_sps);
                    if strcmpi(gauss_appType,'tx')
                        lines{end+1} = sprintf('  滤波器应用：发射端滤波');
                    elseif strcmpi(gauss_appType,'rx')
                        lines{end+1} = sprintf('  滤波器应用：接收端滤波');
                    else
                        lines{end+1} = sprintf('  滤波器应用：常规滤波');
                    end
                    
                    lines{end+1} = sprintf('  滤波器长度：%g ', gauss_filtLen);
                    lines{end+1} = sprintf('  滤波器群延迟：%g ', gauss_groupDelaySamples);
                    if isfield(params,'h') && ~isempty(params.h)
                        lines{end+1} = sprintf('  滤波器系数： %s ', mat2str(params.h,4));
                    end

                    if isfield(params,'upfirdnMode') && ~isempty(params.upfirdnMode)
                        if strcmpi(params.upfirdnMode,'keep')
                            lines{end+1} = sprintf('  发射端滤波输出长度与裁切：保留原长');
                        else
                            lines{end+1} = sprintf('  发射端滤波输出长度与裁切：裁切延迟');
                        end
                    end

                    if isfield(params,'autoAlignMode') && ~isempty(params.autoAlignMode)
                        if strcmpi(params.autoAlignMode,'autointerp')
                            lines{end+1} = sprintf('  接收端滤波自动对齐方式：自动插值');
                        else
