    lblNyq = uilabel(gl_cfirpm,'Text',sprintf('Nyq：%d Hz', nyq),'FontWeight','bold'); lblNyq.Layout.Row=2; lblNyq.Layout.Column=[4 6];
    lblN = uilabel(gl_cfirpm,'Text','滤波器阶数 N:','FontWeight','bold'); lblN.Layout.Row=3; lblN.Layout.Column=1;
