    lblParamStyle = uilabel(gl_cfirpm, 'Text', '自定义频率响应函数传参风格:', 'FontWeight', 'bold');
    lblParamStyle.Layout.Row = 8; lblParamStyle.Layout.Column = 1;
    lblParamStyle.Visible = 'off';
    lblParamStyle.Enable = 'off';
    
    % 单选组：Name-Value / Positional / Both（互斥），初始隐藏且禁用
