    rbParamPositional = uiradiobutton(bgParamStyle, 'Text', 'Positional', 'Position', [110 6 120 20]);
    rbParamBoth = uiradiobutton(bgParamStyle, 'Text', 'Both', 'Position', [210 6 120 20]);
