    bgParamStyle.SelectionChangedFcn = @(bg, evt) onParamStyleChanged(evt);
    
    % 第9行：两个名称输入（标签 + 文本框），初始隐藏且禁用
    lblUserFrespAName = uilabel(gl_cfirpm, 'Text', '频率响应函数幅值向量传参Name:', 'FontWeight','bold');
    lblUserFrespAName.Layout.Row = 9; lblUserFrespAName.Layout.Column = 1;
    lblUserFrespAName.Visible = 'off'; lblUserFrespAName.Enable = 'off';
    
    edtUserFrespAName = uieditfield(gl_cfirpm, 'text', 'Value', '', 'Enable', 'off');
    edtUserFrespAName.Layout.Row = 9; edtUserFrespAName.Layout.Column = [2 3];
    edtUserFrespAName.Placeholder = '例：A 或 a 或 amp';
    edtUserFrespAName.Visible = 'off';
    
    lblUserFrespDName = uilabel(gl_cfirpm, 'Text', '群延迟偏移传参Name:', 'FontWeight','bold');
    lblUserFrespDName.Layout.Row = 9; lblUserFrespDName.Layout.Column = 4;
    lblUserFrespDName.Visible = 'off'; lblUserFrespDName.Enable = 'off';
    
    edtUserFrespDName = uieditfield(gl_cfirpm, 'text', 'Value', '', 'Enable', 'off');
    edtUserFrespDName.Layout.Row = 9; edtUserFrespDName.Layout.Column = [5 6];
    edtUserFrespDName.Placeholder = '例：D 或 d 或 delay';
    edtUserFrespDName.Visible = 'off';


    % 幅值向量 a（与 fresp 二选一）
    lblA = uilabel(gl_cfirpm,'Text','幅值向量 a (若选用 a):','FontWeight','bold'); lblA.Layout.Row=10; lblA.Layout.Column=1;lblA.Enable = 'off';
    edtA = uieditfield(gl_cfirpm,'text','Enable','off'); edtA.Layout.Row=10; edtA.Layout.Column=[2 6];
    edtA.Placeholder = '例：0,0,1,1,0,0 (长度 = length(f))';

    % 权重 w（可选）
    cbW = uicheckbox(gl_cfirpm,'Text','权重向量 w:','Value',false,'FontWeight','bold'); cbW.Layout.Row=11; cbW.Layout.Column=1;
    edtW = uieditfield(gl_cfirpm,'text','Enable','off'); edtW.Layout.Row=11; edtW.Layout.Column=[2 6];
    edtW.Placeholder = '例：1,1,1 (长度 = 带数, 即length(f)/2)';

    % sym 可选
    cbSym = uicheckbox(gl_cfirpm,'Text','对称性约束 sym:','Value',false,'FontWeight','bold'); cbSym.Layout.Row=12; cbSym.Layout.Column=1;
    ddSym = uidropdown(gl_cfirpm,'Items',{'none','even','odd','real'},'Value','none','Enable','off'); ddSym.Layout.Row=12; ddSym.Layout.Column=[2 3];

    % ------------------ debug 与 skip_stage2 ------------------
    % 启用 debug 复选框（第11行第1列）与 debug 下拉（第11行第2-3列）
    cbEnableDebug = uicheckbox(gl_cfirpm, 'Text', '启用 debug:', 'Value', false, 'FontWeight', 'bold');
    cbEnableDebug.Layout.Row = 13; cbEnableDebug.Layout.Column = 1;
    ddDebug = uidropdown(gl_cfirpm, 'Items', {'trace','plots','both','off'}, 'Value', 'off', 'Enable', 'off', 'Tooltip', '启用 debug 后选择 debug 模式（传递给 cfirpm）');
    ddDebug.Layout.Row = 13; ddDebug.Layout.Column = [2 3];
    % 复选框回调：控制下拉启用
    cbEnableDebug.ValueChangedFcn = @(src,evt) setEnableIf(src, ddDebug);
    
    % skip_stage2 复选框（第4-6列）
    cbSkipStage2 = uicheckbox(gl_cfirpm, 'Text', '禁用第二阶段优化算法 (skip_stage2)', 'Value', false, 'FontWeight', 'bold', 'Tooltip', '勾选后会在设计时传入 skip_stage2');
    cbSkipStage2.Layout.Row = 13; cbSkipStage2.Layout.Column = [4 6];


    % 替换原 lblLgrid 为复选框形式，使 lgrid 成为可选项
    cbLgrid = uicheckbox(gl_cfirpm,'Text','频率网格密度 lgrid:','Value',false,'FontWeight','bold');
    cbLgrid.Layout.Row = 12; cbLgrid.Layout.Column = 4;
    edtLgrid = uieditfield(gl_cfirpm,'numeric','Value',25,'Limits',[1 1e6],'RoundFractionalValues','on','Enable','off'); edtLgrid.Layout.Row=12; edtLgrid.Layout.Column=[5 6];
    % cbLgrid 的回调控制 edtLgrid 是否可编辑
    cbLgrid.ValueChangedFcn = @(src,evt) setEnableIf(src, edtLgrid);

    % 输出参数
    lblOutput = uilabel(gl_cfirpm,'Text','输出参数:','FontWeight','bold'); lblOutput.Layout.Row=14; lblOutput.Layout.Column=1;
    ddOutput = uidropdown(gl_cfirpm,'Items',{'b','b, delta','b, delta, res'},'Value','b'); ddOutput.Layout.Row=14; ddOutput.Layout.Column=[2 3];

    % OK / Cancel
    btnOK = uibutton(gl_cfirpm,'push','Text','确认','ButtonPushedFcn',@(btn,event) onConfirm()); btnOK.Layout.Row=15; btnOK.Layout.Column=[1 3];
    btnCancel = uibutton(gl_cfirpm,'push','Text','取消','ButtonPushedFcn',@(btn,event) onCancel()); btnCancel.Layout.Row=15; btnCancel.Layout.Column=[4 6];

    % 回调逻辑：fresp 切换、按钮选择、自检
    userFrespFile = '';
    ddFresp.ValueChangedFcn = @(src,evt) onFrespChanged(src);
    btnChooseFresp.ButtonPushedFcn = @(src,evt) chooseUserFresp();
    cbW.ValueChangedFcn = @(src,evt) setEnableIf(src, edtW);
    cbSym.ValueChangedFcn = @(src,evt) setEnableIf(src, ddSym);

    % 阻塞直到 dlg_cfirpm 被关闭
    uiwait(dlg_cfirpm);

    % ---------------- 回调：当频率响应函数变化 ----------------
    function onFrespChanged(src)
        val = src.Value;

        % 对内置 fresp，根据具体函数显示额外输入
        lblA.Enable = 'off';
        edtA.Enable = 'off';
        cbGroupDelay.Enable = 'on';
        if cbGroupDelay.Value
            edtGroupDelay.Enable = 'on';
        else
            edtGroupDelay.Enable = 'off';
        end
       
    
        % 规格化名称（去掉可能的 '@'，小写化以便比较）
        if ischar(val) && startsWith(val,'@')
            frespName = lower(strrep(val,'@',''));
        else
            frespName = lower(val);
        end

        % 根据 val 动态展示额外参数（复用 lblFrespExtra / edtFrespExtra）
        switch frespName
            case 'multiband'
                lblFrespExtra.Text = 'multiband幅值向量 amb:';
                edtFrespExtra.Placeholder = '例：0,0,1,1,0,0  （长度需等于 f 的节点数）';
                lblFrespExtra.Visible = 'on';
                edtFrespExtra.Visible = 'on';
                edtFrespExtra.Enable = 'on';
                edtFrespExtra.Value = ''; % 不强行填入
                edtFrespExtra.Tooltip = '';

                % 非 user_defined_function：隐藏 user-defined A 控件
                btnChooseFresp.Enable = 'off'; % 禁用 选择自定义频率响应函数按钮
                btnShowFrespReport.Enable = 'off';  % 禁用"fresp 校验报告"按钮
                cbUserFrespA.Visible = 'off';
                edtUserFrespA.Visible = 'off';
                edtUserFrespA.Enable = 'off';
                cbUserFrespA.Value = false; % 可选：重置为未选中

                % 隐藏 hilbfilt 的返回选项（如果存在）
                if exist('bgHilbReturn','var') && isvalid(bgHilbReturn)
                    bgHilbReturn.Visible = 'off';
                    bgHilbReturn.Enable = 'off';
                end

            case 'differentiator'
                lblFrespExtra.Text = 'differentiator采样率 fs(Hz):';
                edtFrespExtra.Placeholder = sprintf('默认 %g', S.fs);
                edtFrespExtra.Value = sprintf('%g', S.fs);
                
                lblFrespExtra.Visible = 'on';
                edtFrespExtra.Visible = 'on';
                edtFrespExtra.Enable = 'on';
                edtFrespExtra.Tooltip = '';
    
                % 非 user_defined_function：隐藏 user-defined A 控件
                btnChooseFresp.Enable = 'off'; % 禁用 选择自定义频率响应函数按钮
                btnShowFrespReport.Enable = 'off';  % 禁用"fresp 校验报告"按钮
                cbUserFrespA.Visible = 'off';
                edtUserFrespA.Visible = 'off';
                edtUserFrespA.Enable = 'off';
                cbUserFrespA.Value = false; % 可选：重置为未选中
            
                % 隐藏 hilbfilt 的返回选项（如果存在）
                if exist('bgHilbReturn','var') && isvalid(bgHilbReturn)
                    bgHilbReturn.Visible = 'off';
                    bgHilbReturn.Enable = 'off';
                end

            case 'hilbfilt'
                % 文本标签
                lblFrespExtra.Text = '应用滤波器返回结果:';
                lblFrespExtra.Visible = 'on';
            
                % 隐藏 / 禁用 edtFrespExtra（hilbfilt 不使用该文本框）
                edtFrespExtra.Visible = 'off';
                edtFrespExtra.Enable = 'off';
            
                % 显示单选组（如果创建了）
                if exist('bgHilbReturn','var') && isvalid(bgHilbReturn)
                    bgHilbReturn.Visible = 'on';
                    bgHilbReturn.Enable = 'on';
                    % % 恢复默认选择（若需要）
                    % try
                    %     rbHilbAnalytic.Value = true;
                    % catch
                    % end
                end
            
                % 禁用自定义 fresp 相关控件（与其它内置 fresp 保持一致）
                btnChooseFresp.Enable = 'off';
                btnShowFrespReport.Enable = 'off';
                cbUserFrespA.Visible = 'off';
                edtUserFrespA.Visible = 'off';
                edtUserFrespA.Enable = 'off';
                cbUserFrespA.Value = false;

            case 'invsinc'
                lblFrespExtra.Text = 'invsinc增益 ainvsinc:';
                edtFrespExtra.Placeholder = '默认 1';
                edtFrespExtra.Value = '1';
                
                lblFrespExtra.Visible = 'on';
                edtFrespExtra.Visible = 'on';
                edtFrespExtra.Enable = 'on';
                edtFrespExtra.Tooltip = '避免产生 ainvsinc * f = ±1, ±2, ...';
     
                % 非 user_defined_function：隐藏 user-defined A 控件
                btnChooseFresp.Enable = 'off'; % 禁用 选择自定义频率响应函数按钮
                btnShowFrespReport.Enable = 'off';  % 禁用"fresp 校验报告"按钮
                cbUserFrespA.Visible = 'off';
                edtUserFrespA.Visible = 'off';
                edtUserFrespA.Enable = 'off';
                cbUserFrespA.Value = false; % 可选：重置为未选中

                % 隐藏 hilbfilt 的返回选项（如果存在）
                if exist('bgHilbReturn','var') && isvalid(bgHilbReturn)
                    bgHilbReturn.Visible = 'off';
                    bgHilbReturn.Enable = 'off';
                end

            case 'user_defined_function'
                % 如果选择 user_defined_function 且 inputSel 为 "频率响应函数fresp"
              
                % 启用选择自定义按钮
                btnChooseFresp.Enable = 'on';
                
                % 启用"fresp 校验报告"按钮
                btnShowFrespReport.Enable = 'on';

                % 显示 user-defined A 相关控件
                cbUserFrespA.Visible = 'on';
                cbUserFrespA.Enable = 'on';
                % 若复选框已勾选则启用输入框
                if cbUserFrespA.Value
                    edtUserFrespA.Enable = 'on';
                else
                    edtUserFrespA.Enable = 'off';
                end
                edtUserFrespA.Visible = 'on';
        
                % 隐藏用于内置 fresp 的额外输入
                lblFrespExtra.Visible = 'off';
                edtFrespExtra.Visible = 'off';
                edtFrespExtra.Enable = 'off';
        
                % 隐藏 hilbfilt 的返回选项（如果存在）
                if exist('bgHilbReturn','var') && isvalid(bgHilbReturn)
                    bgHilbReturn.Visible = 'off';
                    bgHilbReturn.Enable = 'off';
                end

            otherwise
                % 其它 fresp 不显示额外参数
                lblFrespExtra.Visible = 'off';
                edtFrespExtra.Visible = 'off';
                edtFrespExtra.Enable = 'off';

                % 非 user_defined_function：隐藏 user-defined A 控件
                btnChooseFresp.Enable = 'off'; % 禁用 选择自定义频率响应函数按钮
                btnShowFrespReport.Enable = 'off';  % 禁用"fresp 校验报告"按钮
                cbUserFrespA.Visible = 'off';
                edtUserFrespA.Visible = 'off';
                edtUserFrespA.Enable = 'off';
                cbUserFrespA.Value = false; % 可选：重置为未选中

                % 隐藏 hilbfilt 的返回选项（如果存在）
                if exist('bgHilbReturn','var') && isvalid(bgHilbReturn)
                    bgHilbReturn.Visible = 'off';
                    bgHilbReturn.Enable = 'off';
                end

        end
        % 当 user_defined_function 相关选项改变时，更新第8/9行显示与使能
        updateParamUI();
    end

    % ---------------- 回调：当输入参数选择变化 ----------------
    % 新的 SelectionChanged 回调：接收 evt（事件结构）
    function onInputSelChanged(evt)
        % evt.NewValue 为被选中的 radiobutton 对象
        val = evt.NewValue.Text;  % '频率响应函数fresp' 或 '幅值向量a'
    
        if strcmpi(val,'幅值向量a')
            % 用户选择使用幅值向量 a
            lblFresp.Enable = 'off'; 
            ddFresp.Enable = 'off';        % 保持原逻辑
            btnChooseFresp.Enable = 'off';
            lblA.Enable = 'on';
            edtA.Enable = 'on';
           
            % 禁用"fresp 校验报告"按钮
            btnShowFrespReport.Enable = 'off';

            % 群延迟禁用（并取消选中）
            cbGroupDelay.Value = false;
            cbGroupDelay.Enable = 'off';
            edtGroupDelay.Enable = 'off';
    
            % 隐藏并禁用额外 fresp 输入
            lblFrespExtra.Visible = 'off';
            edtFrespExtra.Visible = 'off';
            edtFrespExtra.Enable = 'off';
            % 隐藏 hilbfilt 的返回选项（如果存在）
            if exist('bgHilbReturn','var') && isvalid(bgHilbReturn)
                bgHilbReturn.Visible = 'off';
                bgHilbReturn.Enable = 'off';
            end

            % 非 user_defined_function：隐藏 user-defined A 控件
            cbUserFrespA.Visible = 'off';
            edtUserFrespA.Visible = 'off';
            edtUserFrespA.Enable = 'off';
            cbUserFrespA.Value = false; % 可选：重置为未选中



        else
            % 用户选择 "频率响应函数fresp"
            lblFresp.Enable = 'on'; 
            ddFresp.Enable = 'on';
            lblA.Enable = 'off';
            edtA.Enable = 'off';
            
            % 恢复群延迟复选框可用性
            cbGroupDelay.Enable = 'on';
            if cbGroupDelay.Value
                edtGroupDelay.Enable = 'on';
            else
                edtGroupDelay.Enable = 'off';
            end
    
            % 若 ddFresp 没有可选值或为空，则隐藏额外输入并禁用选择文件按钮
            if isempty(ddFresp.Value)
                btnChooseFresp.Enable = 'off';
                % 禁用"fresp 校验报告"按钮
                btnShowFrespReport.Enable = 'off';
                lblFrespExtra.Visible = 'off';
                edtFrespExtra.Visible = 'off';
                edtFrespExtra.Enable = 'off';
                % 隐藏 hilbfilt 的返回选项（如果存在）
                if exist('bgHilbReturn','var') && isvalid(bgHilbReturn)
                    bgHilbReturn.Visible = 'off';
                    bgHilbReturn.Enable = 'off';
                end
                return;
            end
    
            % 根据当前选择的 fresp 决定额外输入的显示与启用
            frespSel = ddFresp.Value;
            if ischar(frespSel) && strcmpi(frespSel,'user_defined_function')
                % 启用"fresp 校验报告"按钮
                btnShowFrespReport.Enable = 'on';
                
                % 显示 user-defined A 相关控件
                cbUserFrespA.Visible = 'on';
                cbUserFrespA.Enable = 'on';
                % 若复选框已勾选则启用输入框
                if cbUserFrespA.Value
                    edtUserFrespA.Enable = 'on';
                else
                    edtUserFrespA.Enable = 'off';
                end
                edtUserFrespA.Visible = 'on';
        
                % 隐藏用于内置 fresp 的额外输入
                lblFrespExtra.Visible = 'off';
                edtFrespExtra.Visible = 'off';
                edtFrespExtra.Enable = 'off';
                % 隐藏 hilbfilt 的返回选项（如果存在）
                if exist('bgHilbReturn','var') && isvalid(bgHilbReturn)
                    bgHilbReturn.Visible = 'off';
                    bgHilbReturn.Enable = 'off';
                end

                % 启用选择自定义按钮
                btnChooseFresp.Enable = 'on';
                lblA.Enable = 'off';
                edtA.Enable = 'off';
        
                cbGroupDelay.Enable = 'on';
                if cbGroupDelay.Value
                    edtGroupDelay.Enable = 'on';
                else
                    edtGroupDelay.Enable = 'off';
                end

            else
                % 内置函数或带 @ 的内置函数：禁用选择文件按钮
                btnChooseFresp.Enable = 'off';
                % 禁用"fresp 校验报告"按钮
                btnShowFrespReport.Enable = 'off';

                % 规格化名称（去掉可能的 '@'，小写化以便比较）
                if ischar(frespSel) && startsWith(frespSel,'@')
                    frespName = lower(strrep(frespSel,'@',''));
                else
                    frespName = lower(frespSel);
                end
    
                switch frespName
                    case 'multiband'
                        lblFrespExtra.Text = 'multiband幅值向量 amb:';
                        edtFrespExtra.Placeholder = '例：0 0 1 1 0 0 （长度需等于 f 的节点数）';
                        % 保留用户已输入的值（若为空不强制填充）
                        lblFrespExtra.Visible = 'on';
                        edtFrespExtra.Visible = 'on';
                        edtFrespExtra.Enable = 'on';
    
                        % 隐藏 hilbfilt 的返回选项（如果存在）
                        if exist('bgHilbReturn','var') && isvalid(bgHilbReturn)
                            bgHilbReturn.Visible = 'off';
                            bgHilbReturn.Enable = 'off';
                        end

                    case 'differentiator'
                        lblFrespExtra.Text = 'differentiator采样率 fs(Hz):';
                        edtFrespExtra.Placeholder = sprintf('默认 %g', S.fs);
                        % 如果当前为空则预置默认 "S.fs"
                        
                        edtFrespExtra.Value = sprintf('%g', S.fs);
                        
                        lblFrespExtra.Visible = 'on';
                        edtFrespExtra.Visible = 'on';
                        edtFrespExtra.Enable = 'on';
    
                         % 隐藏 hilbfilt 的返回选项（如果存在）
                        if exist('bgHilbReturn','var') && isvalid(bgHilbReturn)
                            bgHilbReturn.Visible = 'off';
                            bgHilbReturn.Enable = 'off';
                        end

                    case 'hilbfilt'
                        % 文本标签
                        lblFrespExtra.Text = '应用滤波器返回结果:';
                        lblFrespExtra.Visible = 'on';
                    
                        % 隐藏 / 禁用 edtFrespExtra（hilbfilt 不使用该文本框）
                        edtFrespExtra.Visible = 'off';
                        edtFrespExtra.Enable = 'off';
                    
                        % 显示单选组（如果创建了）
                        if exist('bgHilbReturn','var') && isvalid(bgHilbReturn)
                            bgHilbReturn.Visible = 'on';
                            bgHilbReturn.Enable = 'on';
                            % 恢复默认选择（若需要）
                            % try
                            %     rbHilbAnalytic.Value = true;
                            % catch
                            % end
                        end
                    

                    case 'invsinc'
                        lblFrespExtra.Text = 'invsinc增益 ainvsinc:';
                        edtFrespExtra.Placeholder = '默认 1';
                        edtFrespExtra.Value = '1';
                        
                        lblFrespExtra.Visible = 'on';
                        edtFrespExtra.Visible = 'on';
                        edtFrespExtra.Enable = 'on';
                        edtFrespExtra.Tooltip = '避免产生 ainvsinc * f = ±1, ±2, ...';
    
                        % 隐藏 hilbfilt 的返回选项（如果存在）
                        if exist('bgHilbReturn','var') && isvalid(bgHilbReturn)
                            bgHilbReturn.Visible = 'off';
                            bgHilbReturn.Enable = 'off';
                        end

                    otherwise
                        % 其它 fresp 不需要额外参数：隐藏并禁用
                        lblFrespExtra.Visible = 'off';
                        edtFrespExtra.Visible = 'off';
                        edtFrespExtra.Enable = 'off';

                        % 隐藏 hilbfilt 的返回选项（如果存在）
                        if exist('bgHilbReturn','var') && isvalid(bgHilbReturn)
                            bgHilbReturn.Visible = 'off';
                            bgHilbReturn.Enable = 'off';
                        end
                end
            end
        end
        % 当 user_defined_function 相关选项改变时，更新第8/9行显示与使能
        updateParamUI();
    end

    function setEnableIf(src, ctrl)
        if src.Value
            ctrl.Enable = 'on';
        else
            ctrl.Enable = 'off';
        end
    end

    function chooseUserFresp()
        [f,p] = uigetfile('*.m','选择自定义频率响应函数 (.m) 文件', pwd);
        if isequal(f,0); return; end
        userFrespFile = fullfile(p,f);
        btnChooseFresp.Text = sprintf('已选: %s', f);
    end

    % ---------------- 回调：当 user_defined_function 相关选项改变时，更新第8/9行显示与使能 ----------------
    function updateParamUI()
        % 判断是否处于 fresp 模式 & user_defined_function & inputSel == '频率响应函数fresp'
        isFrespMode = strcmpi(getInputSel(), '频率响应函数fresp');
        isUserFresp = ischar(ddFresp.Value) && strcmpi(ddFresp.Value, 'user_defined_function');
    
        showControls = isFrespMode && isUserFresp;
        % 显示/隐藏第8行
        if showControls
            lblParamStyle.Visible = 'on';
            bgParamStyle.Visible = 'on';
            % 仅当 cbUserFrespA 或 cbGroupDelay 任一被勾选时才启用单选组
            if (exist('cbUserFrespA','var') && cbUserFrespA.Value) || (exist('cbGroupDelay','var') && cbGroupDelay.Value)
                bgParamStyle.Enable = 'on';
                lblParamStyle.Enable = 'on';
            else
                % 禁用并回滚为 Positional（默认）
                bgParamStyle.Enable = 'off';
                lblParamStyle.Enable = 'off';
                rbParamPositional.Value = true;
            end
    
            % 第9行是否显示（和第8行一起显示，但输入是否启用由单选组决定）
            lblUserFrespAName.Visible = 'on'; edtUserFrespAName.Visible = 'on';
            lblUserFrespDName.Visible = 'on'; edtUserFrespDName.Visible = 'on';
            % 默认禁用 name 编辑框 — 仅当对应 checkbox 勾选且传参风格为 Name-Value or Both 时启用
            lblUserFrespAName.Enable = 'off';
            edtUserFrespAName.Enable = 'off';
            lblUserFrespDName.Enable = 'off';
            edtUserFrespDName.Enable = 'off';
    
            % 启用/禁用根据各自 checkbox + param style
            selText = bgParamStyle.SelectedObject.Text;
            if exist('cbUserFrespA','var') && cbUserFrespA.Value
                if strcmpi(selText,'Name-Value') || strcmpi(selText,'Both')
                    lblUserFrespAName.Enable = 'on';
                    edtUserFrespAName.Enable = 'on';
                else
                    lblUserFrespAName.Enable = 'off';
                    edtUserFrespAName.Enable = 'off';
                    edtUserFrespAName.Value = '';
                end
            else
                lblUserFrespAName.Enable = 'off';
                edtUserFrespAName.Enable = 'off';
                edtUserFrespAName.Value = '';
            end
    
            if exist('cbGroupDelay','var') && cbGroupDelay.Value
                if strcmpi(selText,'Name-Value') || strcmpi(selText,'Both')
                    lblUserFrespDName.Enable = 'on';
                    edtUserFrespDName.Enable = 'on';
                else
                    lblUserFrespDName.Enable = 'off';
                    edtUserFrespDName.Enable = 'off';
                    edtUserFrespDName.Value = '';
                end
            else
                lblUserFrespDName.Enable = 'off';
                edtUserFrespDName.Enable = 'off';
                edtUserFrespDName.Value = '';
            end
    
        else
            % 隐藏全部
            lblParamStyle.Visible = 'off'; lblParamStyle.Enable = 'off';
            bgParamStyle.Visible = 'off'; bgParamStyle.Enable = 'off';
            % 保持 Positional 默认
            rbParamPositional.Value = true;
    
            lblUserFrespAName.Visible = 'off'; edtUserFrespAName.Visible = 'off';
            lblUserFrespDName.Visible = 'off'; edtUserFrespDName.Visible = 'off';
            lblUserFrespAName.Enable = 'off';lblUserFrespDName.Enable = 'off';
            edtUserFrespAName.Enable = 'off'; edtUserFrespDName.Enable = 'off';
            edtUserFrespAName.Value = ''; edtUserFrespDName.Value = '';
        end
    end
    
    % 当单选组变化时（用于启/禁 name fields）
    function onParamStyleChanged(evt)
        % evt.NewValue.Text 包含 'Name-Value' / 'Positional' / 'Both'
        % 让统一函数决定 enable 状态
        updateParamUI();
    end
    
    % 更换 cbUserFrespA / cbGroupDelay 的回调：保留原有 setEnableIf 行为再 updateParamUI
    function onUserFrespAChanged(src, evt)
        setEnableIf(src, edtUserFrespA); % 保持原 edtUserFrespA 行为
        updateParamUI();
    end
    
    function onGroupDelayCheckboxChanged(src, evt)
        setEnableIf(src, edtGroupDelay);
        updateParamUI();
    end
    
    function showCfirpmFrespReport()
        % showCfirpmFrespReport - 在 cfirpm 模态窗口显示 user-defined fresp 的校验报告并绘图
        %
        % 依赖/约定（约定你的 onConfirm/validate 流程会把 report 放到 cfirpmFrespValidated.report
        % 或者放到 btnShowFrespReport.UserData）:
        %   report.GF    - 归一化频率向量（与 validateFresp.testGF 一致，单位：-1..1）
        %   report.DH    - 在 GF 上的期望响应（列向量）
        %   report.DW    - 在 GF 上的每点权重（可选）
        %   report.messages / report.errors - 文本信息（cell array）
        %   report.frespName - fresp 名称（可选）
        %   report.nyq   - （可选）Nyquist（Hz），若存在则同时显示 Hz 横轴
        %
        % 兼容性：如果找不到 cfirpmFrespValidated 或 btnShowFrespReport.UserData，会友好提示。
        
        %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
        %%%%%%%%%%%%%%%%%%%%%%%%%%  fresp 校验报告按钮前导校验 %%%%%%%%%%%%%%%%%%%%%%%%
        % 严格解析并校验参数，按要求返回 params 结构或通过 uialert_safe 提示并返回
        if ~exist('nyq','var')
            if exist('S','var') && isprop(S,'fs')
                nyq = S.fs/2;
            else
                uialert_safe(dlg_cfirpm, '缺少 Nyquist (nyq) 信息，无法验证 differentiator 的频率范围。', '参数错误');
                return;
            end
        end
        % 容差与最小值定义
        tol = 1e-10;
        minWeightVal = 1e-10;
        inputSel = getInputSel(); % '频率响应函数fresp' 或 '幅值向量a'
        frespVal = ddFresp.Value;

        % ============================ (1) 读取并解析频率向量 f ============================
        ftxt = edtF.Value;
        fStr = strtrim(edtF.Value);
        if contains(fStr, '[') || contains(fStr, ']')
            uialert(dlg_cfirpm,'频率向量 f 解析失败，请不要在输入中包含方括号"["或"]"，直接输入数字列表（用半角逗号或空格分隔）。','参数错误'); 
            return; 
        end
        try
            fvec = str2num(['[', ftxt, ']']); %#ok<ST2NM>
        catch
            uialert_safe(dlg_cfirpm, '无法解析频率向量 f，请用逗号或空格分隔数字列表。', '参数错误');
            return;
        end
    
        % 基本类型与非空校验
        if isempty(fvec) || ~isnumeric(fvec)
            uialert_safe(dlg_cfirpm, '频率向量 f 不能为空且必须为数值向量。', '参数错误');
            return;
        end
        fvec = double(fvec(:))'; % 行向量
    
        % 实数 / 有限 / 非 NaN / 非 Inf
        if ~isreal(fvec) || any(~isfinite(fvec)) || any(isnan(fvec))
            uialert_safe(dlg_cfirpm, '频率向量 f 必须为有限的实数值，不允许包含 NaN 或 Inf。', '参数错误');
            return;
        end
    
        % 长度至少 2
        if numel(fvec) < 2
            uialert_safe(dlg_cfirpm, '频率向量 f 的长度必须 >= 2。', '参数错误');
            return;
        end
    
        % nyq（半采样率）存在性保护（有时上下文提供）
        if ~exist('nyq','var')
            % 尝试从 S（若存在）读取
            if exist('S','var') && isprop(S,'fs')
                nyq = S.fs/2;
            else
                % 若上下文没有 nyq，仍需报错（频率范围检查需要 nyq）
                uialert_safe(dlg_cfirpm, '缺少 Nyquist (nyq) 信息，无法验证频率范围。', '参数错误');
                return;
            end
        end
    
        % 数值范围校验：必须在 [-nyq, nyq]
        if any(fvec < -nyq - tol) || any(fvec > nyq + tol)
            uialert_safe(dlg_cfirpm, sprintf('频率值必须在 [-%g, %g] 范围内。', nyq, nyq), '参数错误');
            return;
        end
    
        % 相邻元素不能完全相同（允许微小差异 >= tol）
        diffs = diff(fvec);
        if any(abs(diffs) < tol)
            uialert_safe(dlg_cfirpm, sprintf('频率向量中相邻元素差值过小（< %g），请检查重复或几乎相同的采样点。', tol), '参数错误');
            return;
        end
    
        % 严格单调递增检验（f(k) < f(k+1)，容差 tol）
        if any(diffs <= tol)
            uialert_safe(dlg_cfirpm, sprintf('频率向量 f 必须严格单调递增（相邻差值应 > %g）。', tol), '参数错误');
            return;
        end
    
        % 长度奇偶性校验：必须为偶数
        if mod(numel(fvec), 2) ~= 0
            uialert_safe(dlg_cfirpm, '频率向量 f 的元素个数必须为偶数（与 cfirpm 要求一致）。', '参数错误');
            return;
        end
    
        % ------------------- 计算归一化频率 f_norm（以便直接传入 cfirpm） -------------------
        % 注意：fvec 单位为 Hz（GUI 输入），nyq = Fs/2
        f_norm = fvec / nyq;   % 现在 f_norm 的有效范围应在 [-1, 1]
        if any(f_norm < -1 - tol) || any(f_norm > 1 + tol)
            uialert_safe(dlg_cfirpm, sprintf('归一化频率 f_norm 出界：所有元素应在 [-1,1]（基于 Nyquist=%g）。', nyq), '参数错误');
            return;
        end
        % 若后续需要传入 cfirpm，使用 f_norm 作为 edges（cfirpm 要求 -1..1）
        % ------------------------------------------------------------------------


        % ============================ (2) 读取其它选项：group_delay 等 ============================
        % group_delay
        if exist('cbGroupDelay','var') && cbGroupDelay.Value
            dVal = double(edtGroupDelay.Value);
            if ~isfinite(dVal)
                uialert_safe(dlg_cfirpm, '群延迟偏移 d 必须为有限数值。', '参数错误');
                return;
            end
        end
    
        % ============================ (3) 权重向量 w 的深度校验（如勾选） ============================
        Wvec = [];
        if exist('cbW','var') && cbW.Value
            WStr = strtrim(edtW.Value);
            if contains(WStr, '[') || contains(WStr, ']')
                uialert(dlg_cfirpm,'权重向量 w 解析失败，请不要在输入中包含方括号"["或"]"，直接输入数字列表（用半角逗号或空格分隔）。','参数错误'); 
                return; 
            end
            try
                Wvec = str2num(['[', edtW.Value, ']']); %#ok<ST2NM>
            catch
                uialert_safe(dlg_cfirpm, '无法解析权重向量 w。', '参数错误');
                return;
            end
            if isempty(Wvec) || ~isnumeric(Wvec)
                uialert_safe(dlg_cfirpm, '权重向量 w 必须为数值向量。', '参数错误');
                return;
            end
            Wvec = double(Wvec(:))';
            % 元素必须为有限正实数（>= minWeightVal）
            if any(~isfinite(Wvec)) || any(Wvec < minWeightVal)
                uialert_safe(dlg_cfirpm, sprintf('权重向量 w 的元素必须为有限正数，且 >= %g。', minWeightVal), '参数错误');
                return;
            end
            % 长度必须等于带数（numBands = length(f)/2）
            nbands = numel(fvec)/2;
            if numel(Wvec) ~= nbands
                uialert_safe(dlg_cfirpm, sprintf('权重向量 w 长度应等于带数 (%d)。', nbands), '参数错误');
                return;
            end
        end

        % ============================(4.0) 若频率响应函数为 user_defined_function 且勾选"频率响应函数幅值向量A"，处理可选的幅值向量 A ============================
        if strcmpi(inputSel, '频率响应函数fresp') && ischar(frespVal) && strcmpi(frespVal, 'user_defined_function')
            % 如果用户勾选了 cbUserFrespA，则必须解析并校验 edtUserFrespA
            if exist('cbUserFrespA','var') && cbUserFrespA.Value
                AStr = strtrim(edtUserFrespA.Value);
                if isempty(AStr)
                    uialert_safe(dlg_cfirpm, '已勾选 "频率响应函数幅值向量A"，但未输入任何值。请填写幅值向量或取消勾选。', '参数错误');
                    return;
                end
                if contains(AStr, '[') || contains(AStr, ']')
                    uialert_safe(dlg_cfirpm, '幅值向量 A 解析失败，请不要在输入中包含方括号 "[" 或 "]"，直接输入数字列表（用半角逗号或空格分隔）。', '参数错误');
                    return;
                end
                try
                    userFrespAvec = str2num(['[', edtUserFrespA.Value, ']']); %#ok<ST2NM>
                catch
                    uialert_safe(dlg_cfirpm, '无法解析幅值向量 A，请用逗号或空格分隔数字列表。', '参数错误');
                    return;
                end
                if isempty(userFrespAvec) || ~isnumeric(userFrespAvec)
                    uialert_safe(dlg_cfirpm, '幅值向量 A 必须为数值向量。', '参数错误');
                    return;
                end
                userFrespAvec = double(userFrespAvec(:))';
                % 长度校验（需要与 f 的节点数匹配）
                if exist('fvec','var')
                    if numel(userFrespAvec) ~= numel(fvec)
                        uialert_safe(dlg_cfirpm, '幅值向量 A 的长度必须等于频率向量 f 的长度（节点匹配）。', '参数错误');
                        return;
                    end
                end
                % 元素合法性
                if ~isreal(userFrespAvec) || any(~isfinite(userFrespAvec))
                    uialert_safe(dlg_cfirpm, '幅值向量 A 必须为有限的实数值。', '参数错误');
                    return;
                end
                % 校验通过
                user_fresp_A = userFrespAvec;
            else
                % 未勾选复选框：**不进行校验且不在 params 中写入该字段**
                % do nothing
            end
        end


        % ------------------ 新增：根据用户选择校验并写入自定义 fresp 参数名 ------------------
        % 记录 param 风格（只有在 user_defined_function 且 inputSel == '频率响应函数fresp' 时有意义）
        if strcmpi(getInputSel(), '频率响应函数fresp') && ischar(ddFresp.Value) && strcmpi(ddFresp.Value, 'user_defined_function')
            % 先确认单选组是否被启用（即至少有一个 checkbox 勾选）
            if isprop(bgParamStyle,'Enable') && strcmpi(bgParamStyle.Enable,'on')
                % 写入风格（字符串：'Name-Value' / 'Positional' / 'Both'）
                paramStyleStr = bgParamStyle.SelectedObject.Text;
                % 只有当风格不是 Positional 时才需要对名称字段进行校验并保存（且对应的 checkbox 被勾选）
                if strcmpi(paramStyleStr,'Name-Value') || strcmpi(paramStyleStr,'Both')
                    % 幅值向量 A 名称
                    if exist('cbUserFrespA','var') && cbUserFrespA.Value
                        nameA = strtrim(edtUserFrespAName.Value);
                        if isempty(nameA)
                            uialert_safe(dlg_cfirpm, '已选择 Name-Value/Both 风格并勾选幅值向量 A，请填写 A 的参数名称（例如 A 或 a）。', '参数缺失');
                            return;
                        end
                        % 使用 MATLAB 的 isvarname 验证合法变量名
                        if ~isvarname(nameA)
                            uialert_safe(dlg_cfirpm, sprintf('幅值向量 A 的参数名 "%s" 不是合法的 MATLAB 标识符。请使用字母或下划线开头，仅包含字母数字下划线。', nameA), '参数名非法');
                            return;
                        end
                        user_fresp_A_name = nameA;
                    end
                    % 群延迟 d 名称
                    if exist('cbGroupDelay','var') && cbGroupDelay.Value
                        nameD = strtrim(edtUserFrespDName.Value);
                        if isempty(nameD)
                            uialert_safe(dlg_cfirpm, '已选择 Name-Value/Both 风格并勾选群延迟偏移 d，请填写 d 的参数名称（例如 D 或 d）。', '参数缺失');
                            return;
                        end
                        if ~isvarname(nameD)
                            uialert_safe(dlg_cfirpm, sprintf('群延迟 d 的参数名 "%s" 不是合法的 MATLAB 标识符。请使用字母或下划线开头，仅包含字母数字下划线。', nameD), '参数名非法');
                            return;
                        end
                        user_fresp_d_name = nameD;
                    end
                else
                    % Positional：不检查、不保存名称字段（确保变量不存在）
                    if exist('user_fresp_A_name','var'), clear user_fresp_A_name; end
                    if exist('user_fresp_d_name','var'), clear user_fresp_d_name; end
                end
        
                % 记录最终的风格（仅当 group 可用）
                user_fresp_param_style = paramStyleStr;
            else
                % 单选组被禁用或不可见：等于 Positional（不保存名称）
                user_fresp_param_style = 'Positional';
            end
        else
            % 非 user_defined_function 模式：不写入这些字段
        end            

        % ============================ (4) 用户自定义频率响应函数校验（若选择频率响应函数fresp） ============================
        if strcmpi(inputSel, '频率响应函数fresp') && ischar(frespVal) && strcmpi(frespVal, 'user_defined_function')
            N = FIROrder;
            % user_defined_function 的 m 文件检查（若选择）
            % ------------------ 对 user_defined_function 使用 validateFresp 进行严格校验 ------------------
            
                % 必须有文件路径
                if ~exist('userFrespFile','var') || isempty(userFrespFile) || ~exist(userFrespFile,'file')
                    uialert_safe(dlg_cfirpm, '已选择 user_defined_function，但未选择有效的 .m 文件。', '参数错误');
                    return;
                end
            
                % 解析文件名，临时把其目录加入路径以便 str2func 可以找到函数
                [userDir, userBase, userExt] = fileparts(userFrespFile);
                if isempty(userExt)
                    uialert_safe(dlg_cfirpm, '所选自定义 fresp 文件必须是 .m 文件。', '参数错误');
                    return;
                end
            
                % 解析文件所在目录并临时加入路径（若需要）
                if ~isempty(userDir)
                    try
                        addpath(userDir);
                        addedPath = true;
                    catch MEadd
                        uialert_safe(dlg_cfirpm, sprintf('无法将自定义 fresp 所在目录加入 MATLAB 路径：%s', MEadd.message), '路径错误');
                        return;
                    end
                else
                    addedPath = false;
                end
        
                % 构造函数句柄（假设 .m 文件名即函数名）
                try
                    fh = str2func(userBase);
                catch
                    errorMsg = sprintf('无法将文件 "%s" 转为函数句柄。请确保文件名（不含扩展）为有效的 MATLAB 函数名。', userFrespFile);
                    uialert_safe(dlg_cfirpm, errorMsg, 'fresp 文件错误');
                    if addedPath, rmpath(userDir); end
                    return;
                end
        
                % validateFresp 需要归一化到 [-1,1] 的频率向量 f_norm（validateFresp 文档要求）
                % 我们在 onConfirm 里用 nyq 已经存在（fvec 校验通过），因此：
                f_norm = fvec / nyq;

                % --- 统一准备 Warg（可安全传入 validateFresp） ---
                if exist('Wvec','var') && ~isempty(Wvec)
                    Warg = Wvec;
                else
                    Warg = ones(1, length(fvec)/2);  
                end

                % user_defined_function 可选设置 幅度向量A（向量，长度 = nf_pos 节点数）
                % ---------- 幅值向量 A 的处理（使用用户指定的 Name 或回退到 'a'） ----------
                % --- 统一准备 fresp_args 和 fresp_nv_pairs ---   
                fresp_args = {};
                fresp_nv_pairs = {}; % 用于存放尾部的 Name-Value 对（例如 'a', a）
                useNameValue = false;
                
                if exist('user_fresp_param_style','var') && ~isempty(user_fresp_param_style)
                    styleStr = user_fresp_param_style;
                    useNameValue = any(strcmpi(styleStr, {'Name-Value','Both'}));
                end
                
                if exist('user_fresp_A','var') && ~isempty(user_fresp_A)
                    % frespAarg = user_fresp_A;
                    if useNameValue
                        % 获取用户在 GUI 中填写的名称（优先），合法性检查，否则回退默认 'a'
                        nameA = 'a';
                        if exist('user_fresp_A_name','var') && ischar(user_fresp_A_name) && ~isempty(strtrim(user_fresp_A_name))
                            cand = strtrim(user_fresp_A_name);
                            if isvarname(cand)
                                nameA = cand;
                            else
                                % 非法标识符，警告并使用默认 'a'
                                try
                                    uialert_safe(dlg_cfirpm, sprintf('用户指定的幅值向量 A 名称 "%s" 不是合法的 MATLAB 标识符，已使用默认名称 ''a''。', cand), '参数警告');
                                catch
                                    % 如果 uialert_safe 本身不可用则静默继续
                                end
                                nameA = 'a';
                            end
                        end
                        % 将 Name-Value 对追加到 fresp_nv_pairs
                        fresp_nv_pairs = [fresp_nv_pairs, {nameA, user_fresp_A}];
                    else
                        fresp_args{end+1} = user_fresp_A;
                    end
                end
                
                % group_delay 仅在 fresp 模式下有效（如果存在且非 0 则传入）
                % ---------- 群延迟 d 的处理（使用用户指定的 Name 或回退到 'd'） ----------
                if exist('dVal','var') && ~isempty(dVal) && dVal ~= 0
                    if useNameValue
                        nameD = 'd';
                        if exist('user_fresp_d_name','var') && ischar(user_fresp_d_name) && ~isempty(strtrim(user_fresp_d_name))
                            candD = strtrim(user_fresp_d_name);
                            if isvarname(candD)
                                nameD = candD;
                            else
                                try
                                    uialert_safe(dlg_cfirpm, sprintf('用户指定的群延迟 d 名称 "%s" 不是合法的 MATLAB 标识符，已使用默认名称 ''d''。', candD), '参数警告');
                                catch
                                end
                                nameD = 'd';
                            end
                        end
                        fresp_nv_pairs = [fresp_nv_pairs, {nameD, dVal}];
                    else
                        fresp_args{end+1} = dVal;
                    end
                end
                
                % 传递 W、frespAarg（若存在），并先以 ThrowOnError=false 调用以收集 messages
                try
                    if useNameValue
                        result = validateFresp(fh, f_norm, N, 'W', Warg, 'ThrowOnError', false, 'ExtraArgs', fresp_nv_pairs);
                    else
                        result = validateFresp(fh, f_norm, N, 'W', Warg, 'ThrowOnError', false, 'ExtraArgs', fresp_args);
                    end
                    report.GF = result.testGF;
                    report.DH = result.dh_test;
                    report.DW = result.dw_test;
                    report.messages = result.messages;
                    report.frespName = result.frespName;
                    report.nyq = nyq;  % <--- 重要：把 nyq 写入 report 以便 showCfirpmFrespReport 能显示 Hz 注释
                    % 可选：report.errors = ... 若有捕获到的错误信息
                    cfirpmFrespValidated.report = report;   
                    % 另外备份到按钮 UserData 便于回退：
                    if exist('btnShowFrespReport','var') 
                        btnShowFrespReport.UserData = report;
                    end
                    % % 同时（可选）写到 base workspace 以便调试：
                    % assignin('base','cfirpm_userfresp_report', report);

                catch ME
                    % validateFresp 本身抛出的异常（非 ThrowOnError=false 下的逻辑错误）
                    uialert_safe(dlg_cfirpm, sprintf('校验自定义 fresp 时出错：%s', ME.message), '校验失败');
                    if addedPath, rmpath(userDir); end
                    return;
                end
        
                % 清理临时添加的路径
                if exist('addedPath','var') && addedPath
                    try rmpath(userDir); catch; end
                end
            % ------------------ end user_defined_function 校验块 ------------------
        end

        %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
        %%%%%%%%%%%%%%%%%%%%%%%%%%  fresp 校验报告 %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
        % 特性：
        %   - 单一 HTML 区块内按类别分组显示消息：=== Messages ===, === Warnings ===, === Errors ===
        %   - Errors 字体为红色，Warnings 字体为黄色/金色，Messages 字体为黑色
        %   - 显示区域背景为纯白 (#ffffff)
        %   - 兼容回退：若 uihtml 不可用，显示纯文本并在浏览器中打开彩色 HTML
        
        try
            % ====== 1) 读取 report（优先级：cfirpmFrespValidated -> btnShowFrespReport.UserData -> base workspace 回退） ======
            rpt = [];
            if exist('cfirpmFrespValidated','var') && isstruct(cfirpmFrespValidated) && isfield(cfirpmFrespValidated,'report')
                rpt = cfirpmFrespValidated.report;
            end
            if isempty(rpt) && exist('btnShowFrespReport','var') && isprop(btnShowFrespReport,'UserData') && ~isempty(btnShowFrespReport.UserData)
                rpt = btnShowFrespReport.UserData;
            end
            if isempty(rpt)
                try
                    if evalin('base','exist(''cfirpm_userfresp_report'',''var'')')
                        rpt = evalin('base','cfirpm_userfresp_report');
                    end
                catch
                end
            end
        
            if isempty(rpt)
                uialert(dlg_cfirpm, '当前没有可显示的 user-defined fresp 校验报告。请先运行 fresp 校验并确保结果已保存。', '无报告');
                return;
            end
        
            % ====== 2) 从 report.messages 中分类（Errors / Warnings / Messages） ======
            msgs_all = {};
            if isfield(rpt,'messages') && ~isempty(rpt.messages)
                msgs_all = rpt.messages(:);
            end
        
            fatal_msgs = {};
            warn_msgs  = {};
            other_msgs = {};
            for k = 1:numel(msgs_all)
                m = char(msgs_all{k});
                mtrim = strtrim(m);
                if startsWith(mtrim,'FATAL:','IgnoreCase',true)
                    txt = strtrim(regexprep(mtrim,'^FATAL:\s*','', 'once', 'ignorecase'));
                    fatal_msgs{end+1} = txt; %#ok<AGROW>
                elseif startsWith(mtrim,'WARN:','IgnoreCase',true)
                    txt = strtrim(regexprep(mtrim,'^WARN:\s*','', 'once', 'ignorecase'));
                    warn_msgs{end+1} = txt; %#ok<AGROW>
                else
                    other_msgs{end+1} = mtrim; %#ok<AGROW>
                end
            end
        
            % ====== 3) 生成 HTML（分三节，背景纯白） ======
            % 颜色定义（你可以按需改 hex 值）
            fatalColor = '#ff0000';   % red
            warnColor  = '#d18b00';   % dark yellow / gold (在白底上更可读)
            msgColor   = '#000000';   % black
            sectionTitleColor = '#222222';
        
            % build each section HTML block (preserve order inside each class)
            makeListHTML = @(cellarr, color, prefix) ...
                sprintf('<div class="section-list">%s</div>', ...
                    strjoin(arrayfun(@(i) sprintf('<div class="line" style="color:%s">%s</div>', color, esc(sprintf('%s%s', prefix, cellarr{i}))), ...
                                     1:numel(cellarr), 'UniformOutput', false), ''));
        
            % Messages section
            if isempty(other_msgs)
                msgsHTML = '<div class="line muted">(none)</div>';
            else
                tmp = other_msgs;
                msgsHTML = '';
                for ii = 1:numel(tmp)
                    msgsHTML = [msgsHTML, sprintf('<div class="line" style="color:%s">%s</div>', msgColor, esc(tmp{ii}))]; %#ok<AGROW>
                end
            end
        
            % Warnings section
            if isempty(warn_msgs)
                warnsHTML = '<div class="line muted">(none)</div>';
            else
                warnsHTML = '';
                for ii = 1:numel(warn_msgs)
                    warnsHTML = [warnsHTML, sprintf('<div class="line" style="color:%s"><strong>WARN: %s</strong></div>', warnColor, esc(warn_msgs{ii}))]; %#ok<AGROW>
                end
            end
        
            % Errors section
            if isempty(fatal_msgs)
                errsHTML = '<div class="line muted">(none)</div>';
            else
                errsHTML = '';
                for ii = 1:numel(fatal_msgs)
                    errsHTML = [errsHTML, sprintf('<div class="line" style="color:%s"><strong>FATAL: %s</strong></div>', fatalColor, esc(fatal_msgs{ii}))]; %#ok<AGROW>
                end
            end
        
            % Compose full HTML with white background and monospace font, three titled blocks separated
            html = ['<!doctype html><html><head><meta charset="utf-8">' ...
                '<style>' ...
                'body{background-color:#ffffff; margin:8px; color:#000; font-size:13px;' ...
                'font-family: "Consolas", "Courier New", "Menlo", "DejaVu Sans Mono", monospace; -webkit-font-smoothing:antialiased; -moz-osx-font-smoothing:grayscale;}' ...
                '.report-wrap{display:flex; flex-direction:column; gap:10px;}' ...
                '.section{border:1px solid #ddd; padding:8px; border-radius:6px; background:#ffffff;}' ...
                '.section-title{font-weight:700; color:' sectionTitleColor '; margin-bottom:6px; font-size:13px;}' ...
                '.line{white-space:pre-wrap; word-wrap:break-word; font-size:12px; margin:2px 0; font-family:inherit;}' ...
                '.muted{color:#777777; font-style:italic}' ...
                '</style></head><body>' ...
                '<div class="report-wrap">' ...
                    '<div class="section"><div class="section-title">=== Messages ===</div>' msgsHTML '</div>' ...
                    '<div class="section"><div class="section-title">=== Warnings ===</div>' warnsHTML '</div>' ...
                    '<div class="section"><div class="section-title">=== Errors ===</div>' errsHTML '</div>' ...
                '</div></body></html>'];

        
            % ====== 4) 创建窗口与布局（上：绘图；中：单一 HTML 区；下：按钮） ======
            previewFig = createCenteredUIFigure('Name','cfirpm: user-defined fresp 校验报告','Position',[240 120 1100 740],'WindowStyle','modal');
            gl_cfirpmrpt = uigridlayout(previewFig,[3,1]);
            gl_cfirpmrpt.RowHeight = {'3x','2x',50};
            gl_cfirpmrpt.Padding = [10 8 10 8];
        
            % 绘图区
            ax_cfirpmrpt = uiaxes(gl_cfirpmrpt);
            ax_cfirpmrpt.Layout.Row = 1; ax_cfirpmrpt.Layout.Column = 1;
            ax_cfirpmrpt.Title.String = 'user-defined fresp: test GF 与期望响应 (归一化 -1..1)';
            ax_cfirpmrpt.XLabel.String = 'Normalized frequency (×Nyquist)';
            ax_cfirpmrpt.YLabel.String = 'Response';
            ax_cfirpmrpt.Box = 'on';
            hold(ax_cfirpmrpt,'on');
        
            % 写临时 HTML 文件
            tmp = [tempname(), '.html'];
            fid = fopen(tmp,'w','n','UTF-8');
            if fid == -1
                error('无法创建临时 HTML 文件：%s', tmp);
            end
            fwrite(fid, html, 'char');
            fclose(fid);
        
            % 尝试创建 uihtml 并加载该文件（R2025b 支持）
            htmlOK = false;
            try
                hHtml = uihtml(gl_cfirpmrpt);
                hHtml.Layout.Row = 2; hHtml.Layout.Column = 1;
                hHtml.HTMLSource = tmp;
                htmlOK = true;
            catch
                htmlOK = false;
            end
        
            % 若 uihtml 不可用 -> 在 GUI 内用纯文本回退并在默认浏览器打开 HTML
            if ~htmlOK
                ta = uitextarea(gl_cfirpmrpt, 'Editable', 'off');
                ta.Layout.Row = 2; ta.Layout.Column = 1;
                % 用纯文本回退（按分组合并显示）
                backupLines = {};
                backupLines{end+1} = '=== Messages ===';
                if isempty(other_msgs)
                    backupLines{end+1} = '(none)';
                else
                    backupLines = [backupLines; other_msgs];
                end
                backupLines{end+1} = ''; backupLines{end+1} = '=== Warnings ===';
                if isempty(warn_msgs)
                    backupLines{end+1} = '(none)';
                else
                    backupLines = [backupLines; warn_msgs];
                end
                backupLines{end+1} = ''; backupLines{end+1} = '=== Errors ===';
                if isempty(fatal_msgs)
                    backupLines{end+1} = '(none)';
                else
                    backupLines = [backupLines; fatal_msgs];
                end
                ta.Value = backupLines;
        
                % 打开浏览器显示彩色 HTML（非阻塞）
                try
                    web(tmp,'-browser');
                    uialert(previewFig, '内嵌 HTML 预览不可用，已在系统浏览器打开彩色报告。GUI 内显示为纯文本回退。', '回退说明');
                catch
                    uialert(previewFig, '无法在浏览器打开彩色 HTML，GUI 内已显示为纯文本回退。', '回退说明');
                end
            end
        
            % 底部按钮
            btnPanel = uigridlayout(gl_cfirpmrpt,[1,2]);
            btnPanel.Layout.Row = 3; btnPanel.Layout.Column = 1;
            btnPanel.RowHeight = {40};
            btnPanel.ColumnWidth = {'1x','1x'};
        
            btnExport = uibutton(btnPanel,'push','Text','导出到工作区',...
                'ButtonPushedFcn', @(s,e) exportReportToWorkspace(previewFig, rpt));
            btnExport.Layout.Row = 1; btnExport.Layout.Column = 1;
        
            btnClose = uibutton(btnPanel,'push','Text','关闭','ButtonPushedFcn',@(s,e) close(previewFig));
            btnClose.Layout.Row = 1; btnClose.Layout.Column = 2;
        
            % ====== 5) 绘图（如有 GF/DH） ======
            if isfield(rpt,'GF') && ~isempty(rpt.GF) && isfield(rpt,'DH') && ~isempty(rpt.DH)
                GF = rpt.GF(:);
                DH = rpt.DH(:);
                L = min(numel(GF),numel(DH));
                GF = GF(1:L); DH = DH(1:L);
                if any(imag(DH) ~= 0)
                    plot(ax_cfirpmrpt, GF, abs(DH), '-o', 'DisplayName','|DH|','LineWidth',1.4,'MarkerSize',4);
                    plot(ax_cfirpmrpt, GF, real(DH), '--', 'DisplayName','real(DH)','LineWidth',1);
                    plot(ax_cfirpmrpt, GF, imag(DH), ':', 'DisplayName','imag(DH)','LineWidth',1);
                else
                    plot(ax_cfirpmrpt, GF, DH, '-o', 'DisplayName','DH (real)','LineWidth',1.4,'MarkerSize',4);
                end
                if isfield(rpt,'DW') && ~isempty(rpt.DW)
                    DW = rpt.DW(:);
                    minL = min(numel(DW), numel(GF));
                    DW = DW(1:minL);
                    yyaxis(ax_cfirpmrpt,'right');
                    stairs(ax_cfirpmrpt, GF(1:minL), DW, 'DisplayName','DW (weights)','LineWidth',1.2);
                    ax_cfirpmrpt.YLabel.String = 'Response / Weight';
                    yyaxis(ax_cfirpmrpt,'left');
                end
                legend(ax_cfirpmrpt,'show');
                grid(ax_cfirpmrpt,'on');
            else
                text(ax_cfirpmrpt,0.5,0.5,'字段 report 中未包含 GF/DH 信息，无法绘制示意图。','HorizontalAlignment','center');
            end
        
        catch ME
            try
                uialert(dlg_cfirpm, sprintf('显示报告时发生错误：%s', ME.message), '显示错误');
            catch
            end
            fprintf(2, 'showCfirpmFrespReport exception:\n%s\n', getReport(ME));
        end
    end
        
    % helper to escape HTML special chars
    function s = esc(str)
        s = strrep(str,'&','&amp;');
        s = strrep(s,'<','&lt;');
        s = strrep(s,'>','&gt;');
        s = strrep(s,'"','&quot;');
        s = strrep(s,'''','&#39;');
    end

    % helper: 导出 report 到 base workspace
    function exportReportToWorkspace(previewFig, report)
        try
            assignin('base','cfirpm_userfresp_report', report);
            uialert(previewFig, '已把报告导出到 base 工作区变量 ''cfirpm_userfresp_report''。', '导出成功', "Icon", "success");
        catch
            uialert(previewFig, '导出失败：无法写入 base 工作区。', '导出失败');
        end
    end

    % helper：统一读取当前输入选择（返回 '频率响应函数fresp' 或 '幅值向量a'）
    function sel = getInputSel()
        if exist('bgInputSel','var') && isvalid(bgInputSel) && ~isempty(bgInputSel.SelectedObject)
            sel = bgInputSel.SelectedObject.Text;
        else
            % 兜底：若控件不存在或不可用，回退到原来的默认
            sel = '频率响应函数fresp';
        end
    end

    function onCancel()
        params = [];
        try close(dlg_cfirpm); catch;delete(dlg_cfirpm); end
    
    end

    function onConfirm()
        % 严格解析并校验参数，按要求返回 params 结构或通过 uialert_safe 提示并返回
        if ~exist('nyq','var')
            if exist('S','var') && isprop(S,'fs')
                nyq = S.fs/2;
            else
                uialert_safe(dlg_cfirpm, '缺少 Nyquist (nyq) 信息，无法验证 differentiator 的频率范围。', '参数错误');
                return;
            end
        end
        % 容差与最小值定义
        tol = 1e-10;
        minWeightVal = 1e-10;
        inputSel = getInputSel(); % '频率响应函数fresp' 或 '幅值向量a'
        frespVal = ddFresp.Value;

        % ============================ (1) 读取并解析频率向量 f ============================
        ftxt = edtF.Value;
        fStr = strtrim(edtF.Value);
        if contains(fStr, '[') || contains(fStr, ']')
            uialert(dlg_cfirpm,'频率向量 f 解析失败，请不要在输入中包含方括号"["或"]"，直接输入数字列表（用半角逗号或空格分隔）。','参数错误'); 
            return; 
        end
        try
            fvec = str2num(['[', ftxt, ']']); %#ok<ST2NM>
        catch
            uialert_safe(dlg_cfirpm, '无法解析频率向量 f，请用逗号或空格分隔数字列表。', '参数错误');
            return;
        end
    
        % 基本类型与非空校验
        if isempty(fvec) || ~isnumeric(fvec)
            uialert_safe(dlg_cfirpm, '频率向量 f 不能为空且必须为数值向量。', '参数错误');
            return;
        end
        fvec = double(fvec(:))'; % 行向量
    
        % 实数 / 有限 / 非 NaN / 非 Inf
        if ~isreal(fvec) || any(~isfinite(fvec)) || any(isnan(fvec))
            uialert_safe(dlg_cfirpm, '频率向量 f 必须为有限的实数值，不允许包含 NaN 或 Inf。', '参数错误');
            return;
        end
    
        % 长度至少 2
        if numel(fvec) < 2
            uialert_safe(dlg_cfirpm, '频率向量 f 的长度必须 >= 2。', '参数错误');
            return;
        end
    
        % nyq（半采样率）存在性保护（有时上下文提供）
        if ~exist('nyq','var')
            % 尝试从 S（若存在）读取
            if exist('S','var') && isprop(S,'fs')
                nyq = S.fs/2;
            else
                % 若上下文没有 nyq，仍需报错（频率范围检查需要 nyq）
                uialert_safe(dlg_cfirpm, '缺少 Nyquist (nyq) 信息，无法验证频率范围。', '参数错误');
                return;
            end
        end
    
        % 数值范围校验：必须在 [-nyq, nyq]
        if any(fvec < -nyq - tol) || any(fvec > nyq + tol)
            uialert_safe(dlg_cfirpm, sprintf('频率值必须在 [-%g, %g] 范围内。', nyq, nyq), '参数错误');
            return;
        end
    
        % 相邻元素不能完全相同（允许微小差异 >= tol）
        diffs = diff(fvec);
        if any(abs(diffs) < tol)
            uialert_safe(dlg_cfirpm, sprintf('频率向量中相邻元素差值过小（< %g），请检查重复或几乎相同的采样点。', tol), '参数错误');
            return;
        end
    
        % 严格单调递增检验（f(k) < f(k+1)，容差 tol）
        if any(diffs <= tol)
            uialert_safe(dlg_cfirpm, sprintf('频率向量 f 必须严格单调递增（相邻差值应 > %g）。', tol), '参数错误');
            return;
        end
    
        % 长度奇偶性校验：必须为偶数
        if mod(numel(fvec), 2) ~= 0
            uialert_safe(dlg_cfirpm, '频率向量 f 的元素个数必须为偶数（与 cfirpm 要求一致）。', '参数错误');
            return;
        end
    
        % ------------------- 计算归一化频率 f_norm（以便直接传入 cfirpm） -------------------
        % 注意：fvec 单位为 Hz（GUI 输入），nyq = Fs/2
        f_norm = fvec / nyq;   % 现在 f_norm 的有效范围应在 [-1, 1]
        if any(f_norm < -1 - tol) || any(f_norm > 1 + tol)
            uialert_safe(dlg_cfirpm, sprintf('归一化频率 f_norm 出界：所有元素应在 [-1,1]（基于 Nyquist=%g）。', nyq), '参数错误');
            return;
        end
        % 若后续需要传入 cfirpm，使用 f_norm 作为 edges（cfirpm 要求 -1..1）
        % ------------------------------------------------------------------------




        % ============================ (2) 读取其它选项：sym / lgrid / group_delay / 输出形式 等 ============================
        % sym
        if exist('cbSym','var') && cbSym.Value
            symVal = ddSym.Value; % 例如 'even'/'odd'/'real'/'none' 等
        end
    
        % lgrid
        if exist('cbLgrid','var') && ~cbLgrid.Value
            lgridVal = []; % 未启用
        else
            % 强制为正整数
            try
                lgridValTmp = round(double(edtLgrid.Value));
            catch
                lgridValTmp = NaN;
            end
            if isempty(lgridValTmp) || ~isfinite(lgridValTmp) || lgridValTmp < 1
                uialert_safe(dlg_cfirpm, '频率网格密度 lgrid 必须为大于等于 1 的正整数。', '参数错误');
                return;
            end
            lgridVal = double(lgridValTmp);
        end
    
        % group_delay
        if exist('cbGroupDelay','var') && cbGroupDelay.Value
            dVal = double(edtGroupDelay.Value);
            if ~isfinite(dVal)
                uialert_safe(dlg_cfirpm, '群延迟偏移 d 必须为有限数值。', '参数错误');
                return;
            end
        end
    
        % 输出类型
        if exist('ddOutput','var')
            outputVal = ddOutput.Value;
        else
            outputVal = 'b';
        end
    
        % ============================ (3) 权重向量 w 的深度校验（如勾选） ============================
        Wvec = [];
        if exist('cbW','var') && cbW.Value
            WStr = strtrim(edtW.Value);
            if contains(WStr, '[') || contains(WStr, ']')
                uialert(dlg_cfirpm,'权重向量 w 解析失败，请不要在输入中包含方括号"["或"]"，直接输入数字列表（用半角逗号或空格分隔）。','参数错误'); 
                return; 
            end
            try
                Wvec = str2num(['[', edtW.Value, ']']); %#ok<ST2NM>
            catch
                uialert_safe(dlg_cfirpm, '无法解析权重向量 w。', '参数错误');
                return;
            end
            if isempty(Wvec) || ~isnumeric(Wvec)
                uialert_safe(dlg_cfirpm, '权重向量 w 必须为数值向量。', '参数错误');
                return;
            end
            Wvec = double(Wvec(:))';
            % 元素必须为有限正实数（>= minWeightVal）
            if any(~isfinite(Wvec)) || any(Wvec < minWeightVal)
                uialert_safe(dlg_cfirpm, sprintf('权重向量 w 的元素必须为有限正数，且 >= %g。', minWeightVal), '参数错误');
                return;
            end
            % 长度必须等于带数（numBands = length(f)/2）
            nbands = numel(fvec)/2;
            if numel(Wvec) ~= nbands
                uialert_safe(dlg_cfirpm, sprintf('权重向量 w 长度应等于带数 (%d)。', nbands), '参数错误');
                return;
            end
        end

        % ============================(4.0) 若频率响应函数为 user_defined_function 且勾选"频率响应函数幅值向量A"，处理可选的幅值向量 A ============================
        if strcmpi(inputSel, '频率响应函数fresp') && ischar(frespVal) && strcmpi(frespVal, 'user_defined_function')
            % 如果用户勾选了 cbUserFrespA，则必须解析并校验 edtUserFrespA
            if exist('cbUserFrespA','var') && cbUserFrespA.Value
                AStr = strtrim(edtUserFrespA.Value);
                if isempty(AStr)
                    uialert_safe(dlg_cfirpm, '已勾选 "频率响应函数幅值向量A"，但未输入任何值。请填写幅值向量或取消勾选。', '参数错误');
                    return;
                end
                if contains(AStr, '[') || contains(AStr, ']')
                    uialert_safe(dlg_cfirpm, '幅值向量 A 解析失败，请不要在输入中包含方括号 "[" 或 "]"，直接输入数字列表（用半角逗号或空格分隔）。', '参数错误');
                    return;
                end
                try
                    userFrespAvec = str2num(['[', edtUserFrespA.Value, ']']); %#ok<ST2NM>
                catch
                    uialert_safe(dlg_cfirpm, '无法解析幅值向量 A，请用逗号或空格分隔数字列表。', '参数错误');
                    return;
                end
                if isempty(userFrespAvec) || ~isnumeric(userFrespAvec)
                    uialert_safe(dlg_cfirpm, '幅值向量 A 必须为数值向量。', '参数错误');
                    return;
                end
                userFrespAvec = double(userFrespAvec(:))';
                % 长度校验（需要与 f 的节点数匹配）
                if exist('fvec','var')
                    if numel(userFrespAvec) ~= numel(fvec)
                        uialert_safe(dlg_cfirpm, '幅值向量 A 的长度必须等于频率向量 f 的长度（节点匹配）。', '参数错误');
                        return;
                    end
                end
                % 元素合法性
                if ~isreal(userFrespAvec) || any(~isfinite(userFrespAvec))
                    uialert_safe(dlg_cfirpm, '幅值向量 A 必须为有限的实数值。', '参数错误');
                    return;
                end
                % 校验通过
                user_fresp_A = userFrespAvec;
            else
                % 未勾选复选框：**不进行校验且不在 params 中写入该字段**
                % do nothing
            end
        end

        % ------------------ 新增：根据用户选择校验并写入自定义 fresp 参数名 ------------------
        % 记录 param 风格（只有在 user_defined_function 且 inputSel == '频率响应函数fresp' 时有意义）
        if strcmpi(getInputSel(), '频率响应函数fresp') && ischar(ddFresp.Value) && strcmpi(ddFresp.Value, 'user_defined_function')
            % 先确认单选组是否被启用（即至少有一个 checkbox 勾选）
            if isprop(bgParamStyle,'Enable') && strcmpi(bgParamStyle.Enable,'on')
                % 写入风格（字符串：'Name-Value' / 'Positional' / 'Both'）
                paramStyleStr = bgParamStyle.SelectedObject.Text;
                % 只有当风格不是 Positional 时才需要对名称字段进行校验并保存（且对应的 checkbox 被勾选）
                if strcmpi(paramStyleStr,'Name-Value') || strcmpi(paramStyleStr,'Both')
                    % 幅值向量 A 名称
                    if exist('cbUserFrespA','var') && cbUserFrespA.Value
                        nameA = strtrim(edtUserFrespAName.Value);
                        if isempty(nameA)
                            uialert_safe(dlg_cfirpm, '已选择 Name-Value/Both 风格并勾选幅值向量 A，请填写 A 的参数名称（例如 A 或 a）。', '参数缺失');
                            return;
                        end
                        % 使用 MATLAB 的 isvarname 验证合法变量名
                        if ~isvarname(nameA)
                            uialert_safe(dlg_cfirpm, sprintf('幅值向量 A 的参数名 "%s" 不是合法的 MATLAB 标识符。请使用字母或下划线开头，仅包含字母数字下划线。', nameA), '参数名非法');
                            return;
                        end
                        user_fresp_A_name = nameA;
                    end
                    % 群延迟 d 名称
                    if exist('cbGroupDelay','var') && cbGroupDelay.Value
                        nameD = strtrim(edtUserFrespDName.Value);
                        if isempty(nameD)
                            uialert_safe(dlg_cfirpm, '已选择 Name-Value/Both 风格并勾选群延迟偏移 d，请填写 d 的参数名称（例如 D 或 d）。', '参数缺失');
                            return;
                        end
                        if ~isvarname(nameD)
                            uialert_safe(dlg_cfirpm, sprintf('群延迟 d 的参数名 "%s" 不是合法的 MATLAB 标识符。请使用字母或下划线开头，仅包含字母数字下划线。', nameD), '参数名非法');
                            return;
                        end
                        user_fresp_d_name = nameD;
                    end
                else
                    % Positional：不检查、不保存名称字段（确保变量不存在）
                    if exist('user_fresp_A_name','var'), clear user_fresp_A_name; end
                    if exist('user_fresp_d_name','var'), clear user_fresp_d_name; end
                end
        
                % 记录最终的风格（仅当 group 可用）
                user_fresp_param_style = paramStyleStr;
            else
                % 单选组被禁用或不可见：等于 Positional（不保存名称）
                user_fresp_param_style = 'Positional';
            end
        else
            % 非 user_defined_function 模式：不写入这些字段
        end


        % ============================ (4) 用户自定义频率响应函数校验（若选择频率响应函数fresp） ============================
        user_fresp_file = '';
        if strcmpi(inputSel, '频率响应函数fresp') && ischar(frespVal) && strcmpi(frespVal, 'user_defined_function')
            N = FIROrder;
            % user_defined_function 的 m 文件检查（若选择）
            % ------------------ 对 user_defined_function 使用 validateFresp 进行严格校验 ------------------
        
            % 必须有文件路径
            if ~exist('userFrespFile','var') || isempty(userFrespFile) || ~exist(userFrespFile,'file')
                uialert_safe(dlg_cfirpm, '已选择 user_defined_function，但未选择有效的 .m 文件。', '参数错误');
                return;
            end
        
            % 解析文件名，临时把其目录加入路径以便 str2func 可以找到函数
            [userDir, userBase, userExt] = fileparts(userFrespFile);
            if isempty(userExt)
                uialert_safe(dlg_cfirpm, '所选自定义 fresp 文件必须是 .m 文件。', '参数错误');
                return;
            end
        
            % 解析文件所在目录并临时加入路径（若需要）
            if ~isempty(userDir)
                try
                    addpath(userDir);
                    addedPath = true;
                catch MEadd
                    uialert_safe(dlg_cfirpm, sprintf('无法将自定义 fresp 所在目录加入 MATLAB 路径：%s', MEadd.message), '路径错误');
                    return;
                end
            else
                addedPath = false;
            end
    
            % 构造函数句柄（假设 .m 文件名即函数名）
            try
                fh = str2func(userBase);
            catch
                errorMsg = sprintf('无法将文件 "%s" 转为函数句柄。请确保文件名（不含扩展）为有效的 MATLAB 函数名。', userFrespFile);
                uialert_safe(dlg_cfirpm, errorMsg, 'fresp 文件错误');
                if addedPath, rmpath(userDir); end
                return;
            end
    
            % validateFresp 需要归一化到 [-1,1] 的频率向量 f_norm（validateFresp 文档要求）
            % 我们在 onConfirm 里用 nyq 已经存在（fvec 校验通过），因此：
            f_norm = fvec / nyq;

            % --- 统一准备 Warg（可安全传入 validateFresp） ---
            if exist('Wvec','var') && ~isempty(Wvec)
                Warg = Wvec;
            else
                Warg = ones(1, length(fvec)/2);  
            end
              
            % user_defined_function 可选设置 幅度向量A（向量，长度 = nf_pos 节点数）
            % ---------- 幅值向量 A 的处理（使用用户指定的 Name 或回退到 'a'） ----------
            % --- 统一准备 fresp_args 和 fresp_nv_pairs ---   
            fresp_args = {};
            fresp_nv_pairs = {}; % 用于存放尾部的 Name-Value 对（例如 'a', a）
            useNameValue = false;

            if exist('user_fresp_param_style','var') && ~isempty(user_fresp_param_style)
                styleStr = user_fresp_param_style;
                useNameValue = any(strcmpi(styleStr, {'Name-Value','Both'}));
            end

            if exist('user_fresp_A','var') && ~isempty(user_fresp_A)
                % frespAarg = user_fresp_A;
                if useNameValue
                    % 获取用户在 GUI 中填写的名称（优先），合法性检查，否则回退默认 'a'
                    nameA = 'a';
                    if exist('user_fresp_A_name','var') && ischar(user_fresp_A_name) && ~isempty(strtrim(user_fresp_A_name))
                        cand = strtrim(user_fresp_A_name);
                        if isvarname(cand)
                            nameA = cand;
                        else
                            % 非法标识符，警告并使用默认 'a'
                            try
                                uialert_safe(dlg_cfirpm, sprintf('用户指定的幅值向量 A 名称 "%s" 不是合法的 MATLAB 标识符，已使用默认名称 ''a''。', cand), '参数警告');
                            catch
                                % 如果 uialert_safe 本身不可用则静默继续
                            end
                            nameA = 'a';
                        end
                    end
                    % 将 Name-Value 对追加到 fresp_nv_pairs
                    fresp_nv_pairs = [fresp_nv_pairs, {nameA, user_fresp_A}];
                else
                    fresp_args{end+1} = user_fresp_A;
                end
            end

            % group_delay 仅在 fresp 模式下有效（如果存在且非 0 则传入）
            % ---------- 群延迟 d 的处理（使用用户指定的 Name 或回退到 'd'） ----------
            if exist('dVal','var') && ~isempty(dVal) && dVal ~= 0
                if useNameValue
                    nameD = 'd';
                    if exist('user_fresp_d_name','var') && ischar(user_fresp_d_name) && ~isempty(strtrim(user_fresp_d_name))
                        candD = strtrim(user_fresp_d_name);
                        if isvarname(candD)
                            nameD = candD;
                        else
                            try
                                uialert_safe(dlg_cfirpm, sprintf('用户指定的群延迟 d 名称 "%s" 不是合法的 MATLAB 标识符，已使用默认名称 ''d''。', candD), '参数警告');
                            catch
                            end
                            nameD = 'd';
                        end
                    end
                    fresp_nv_pairs = [fresp_nv_pairs, {nameD, dVal}];
                else
                    fresp_args{end+1} = dVal;
                end
            end

            % 传递 W、frespAarg（若存在），并先以 ThrowOnError=false 调用以收集 messages
            try
                if useNameValue
                    result = validateFresp(fh, f_norm, N, 'W', Warg, 'ThrowOnError', false, 'ExtraArgs', fresp_nv_pairs);
                else
                    result = validateFresp(fh, f_norm, N, 'W', Warg, 'ThrowOnError', false, 'ExtraArgs', fresp_args);
                end
            catch ME
                % validateFresp 本身抛出的异常（非 ThrowOnError=false 下的逻辑错误）
                uialert_safe(dlg_cfirpm, sprintf('校验自定义 fresp 时出错：%s', ME.message), '校验失败');
                if addedPath, rmpath(userDir); end
                return;
            end
    
            % 处理返回结果：高亮 FATAL/WARN 并决定是否继续
            % result.messages 是 cell array，每条以 'FATAL: ' 或 'WARN: ' 前缀或 'OK: ' 等形式
            msgs = {};
            if isfield(result,'messages') && ~isempty(result.messages)
                msgs = result.messages;
            end
    
            % 收集 FATAL / WARN
            fatal_msgs = msgs(startsWith(msgs, 'FATAL:'));
            warn_msgs  = msgs(startsWith(msgs, 'WARN:'));
    
            if ~isempty(fatal_msgs)
                % 如果有致命问题 — 不允许继续，显示友好提示并返回
                summary = strjoin(fatal_msgs, '\n\n');
                uialert_safe(dlg_cfirpm, sprintf('自定义 fresp 校验发现致命错误，无法继续：\n\n%s', summary), '自定义 fresp 校验失败');
                if addedPath, rmpath(userDir); end
                return;
            elseif ~isempty(warn_msgs)
                % 只有 WARN — 展示给用户，允许继续或取消
                % 高亮 WARN 信息（这里用 uiconfirm 提示）
                warnSummary = strjoin(warn_msgs, '\n\n');
                prompt = sprintf('自定义 fresp 校验返回警告：\n\n%s\n\n是否仍然继续使用该函数？', warnSummary);
                choice = uiconfirm(dlg_cfirpm, prompt, '自定义 fresp 警告', 'Options', {'继续','取消'}, 'DefaultOption', 2, 'CancelOption', 2, "Icon","warning");
                if strcmp(choice,'取消')
                    if addedPath, rmpath(userDir); end
                    return;
                end
                % 如果用户选择继续，则可以（可选）再次以 ThrowOnError=true 进行严格调用以确保后续 cfirpm 调用直接失败并被捕获
                try
                    if useNameValue
                        validateFresp(fh, f_norm, N, 'W', Warg, 'ThrowOnError', true, 'ExtraArgs', fresp_nv_pairs);
                    else
                        validateFresp(fh, f_norm, N, 'W', Warg, 'ThrowOnError', true, 'ExtraArgs', fresp_args);
                    end
                catch ME2
                    % validateFresp 抛出异常时，显示友好错误（说明细节），并阻止继续
                    uialert_safe(dlg_cfirpm, sprintf('再次严格校验自定义 fresp 时出错：%s', ME2.message), '自定义 fresp 校验失败');
                    if addedPath, rmpath(userDir); end
                    return;
                end
            else
                % 无警告或致命信息，继续（可选再做一次 ThrowOnError=true 以保证没有潜在问题）
                try
                    if useNameValue
                        validateFresp(fh, f_norm, N, 'W', Warg, 'ThrowOnError', true, 'ExtraArgs', fresp_nv_pairs);
                    else
                        validateFresp(fh, f_norm, N, 'W', Warg, 'ThrowOnError', true, 'ExtraArgs', fresp_args);
                    end
                catch ME3
                    uialert_safe(dlg_cfirpm, sprintf('自定义 fresp 的严格校验失败：%s', ME3.message), '自定义 fresp 校验失败');
                    if addedPath, rmpath(userDir); end
                    return;
                end
            end
    
            % 校验通过：记录用户选择的 fresp 文件路径到 params
            user_fresp_file = userFrespFile;
            supports_regular_namevalue = result.detectParamStyle.supports_regular_namevalue;
        
            % 清理临时添加的路径
            if exist('addedPath','var') && addedPath
                try rmpath(userDir); catch; end
            end
            % ------------------ end user_defined_function 校验块 ------------------
        end
    


        % ============================ (5) 预置频率响应函数的参数及其校验（按 fresp） ============================
        % 仅在用户选择 fresp 且非 user_defined_function 时处理
        if strcmpi(inputSel, '频率响应函数fresp') && exist('frespVal','var') && ischar(frespVal) && ~isempty(frespVal) && ~strcmpi(frespVal, 'user_defined_function')
            % 规格化 fresp 名称（去掉 '@'）
            if startsWith(frespVal, '@')
                frespName = strrep(frespVal, '@', '');
            else
                frespName = frespVal;
            end
    
            % 检查预定义函数在当前 MATLAB 环境可用性（非严格依赖，但提示）
            if ~isempty(frespName)
                % 对于cfirpm内置函数，exist 可能返回 >0
                is_predefined_frespFunction_exist = ~isempty(which(frespName)) ||  ~isempty(which(['cfirpm>', frespName]));
                if ~is_predefined_frespFunction_exist
                    % 不是必须 fatal error，但提示并确认
                    warnMsg = sprintf('未能在当前 MATLAB 路径中找到 fresp 函数 ''%s''。请确认该函数在你的 MATLAB 版本中可用。是否继续？', frespName);
                    choice = uiconfirm(dlg_cfirpm, warnMsg, 'fresp 函数未找到', 'Options', {'继续','取消'}, 'DefaultOption', 2, 'CancelOption', 2, "Icon","error");
                    if strcmp(choice, '取消')
                        return;
                    end
                end
            end
    
            % 统一归一化频率到 [-1,1]（相对于 nyq）
            f_norm = fvec / nyq;

            % 共用：若用户显式设置了 sym，需要确保与频率向量兼容
            if exist('symVal','var') && ~isempty(symVal) && ~strcmpi(symVal,'none')
                % 当用户选择了 symmetry（even/odd/real），频带边缘必须只在非负半域（cfirpm 要求）
                if any(f_norm < -tol)
                    uialert_safe(dlg_cfirpm, sprintf('当你选择对称性 ''%s'' 时，频带边缘必须只在非负频率区间[0 %g]。请移除负频率或将对称性设为 ''none''。', symVal,nyq), '参数错误');
                    return;
                end
            end

            % 特殊 fresp 的额外要求
            switch lower(frespName)
               case {'lowpass','highpass'}
                    % 与 cfirpm/lowpass & cfirpm/highpass 保持一致的校验：
                    % Le == 4 -> 所有边界应为非负（half-domain 写法）
                    % Le == 6 -> F(3)*F(4) <= 0（中间两项需跨越 0）
                    Le = numel(f_norm);
                    if ~(Le == 4 || Le == 6)
                        uialert_safe(dlg_cfirpm, sprintf('@%s 要求频率向量元素个数为 4 或 6（半域或跨零写法）。', frespName), '参数错误');
                        return;
                    end
                    if Le == 4
                        if any(f_norm < -tol)
                            uialert_safe(dlg_cfirpm, sprintf('@%s 在 4 元素模式下要求所有频率边界为非负（>=0）。', frespName), '参数错误');
                            return;
                        end
                    else
                        if f_norm(3) * f_norm(4) > tol
                            uialert_safe(dlg_cfirpm, sprintf('@%s 在 6 元素模式下要求 f(3) 与 f(4) 跨越 0（包含 DC）。', frespName), '参数错误');
                            return;
                        end
                    end


                case {'bandpass','bandstop'}
                    % bandpass / bandstop -> 基本合法性检查：偶数长度且 >=4
                    Le = numel(f_norm);
                    if mod(Le,2) ~= 0 || Le < 4
                        uialert_safe(dlg_cfirpm, sprintf('@%s 要求频率向量元素个数为偶数且 >= 4（带对形式）。', frespName), '参数错误');
                        return;
                    end

                    % 当用户指定 symmetry 时，band edges 不能包含负值（cfirpm 要求）
                    if exist('symVal','var') && ~isempty(symVal) && ~strcmpi(symVal, 'none')
                        if any(f_norm < -tol)
                            uialert_safe(dlg_cfirpm, sprintf('选择对称性 ''%s'' 时，@%s 的频带边缘必须仅在非负区间 [0, nyq]。', symVal, frespName), '参数错误');
                            return;
                        end
                    end

                    % 额外检查：检测相邻带定义是否逻辑正确（没有倒置/重合）
                    for kk = 1:2:Le-2
                        if f_norm(kk+1) >= f_norm(kk+2) - tol
                            uialert_safe(dlg_cfirpm, sprintf('@%s 的带定义出现重叠或未递增：边对索引 %d-%d 与 %d-%d。请修正 f。', ...
                                frespName, kk, kk+1, kk+2, kk+3), '参数错误');
                            return;
                        end
                    end

                    % （可选）在这里不强制要求跨零或包含零；cfirpm 内部会根据 mags 自动处理

                case 'allpass'
                    % --------------------------
                    % allpass: 轻量校验与用户提示（不需要复杂数值校验）
                    % -------------------------
                    % 1) 提示关于相位/对称性的语义（allpass 使用非线性相位项）
                    % allpass.m 没有实现 'defaults' 查询，因此 cfirpm 会把默认 symmetry 置为 'none'
                    if exist('symVal','var') && ~isempty(symVal) && ~strcmpi(symVal, 'none')
                        warnMsg = ['你为设计选择了 @allpass，同时选择了对称性选项（' symVal '）。', newline, ...
                                   '注意：allpass 会加入非线性相位项，cfirpm 在没有 fresp 默认值时通常将 symmetry 设为 ''none''。', newline, ...
                                   '如果你仍要强制对称性，请确保你理解其对频率域/相位的影响。是否继续？'];
                        choice = uiconfirm(dlg_cfirpm, warnMsg, 'allpass 与对称性提示', 'Options', {'继续','取消'}, 'DefaultOption', 2, 'CancelOption', 2, "Icon","warning");
                        if strcmp(choice, '取消')
                            return;
                        end
                    end

                    % 2) 权重提示：allpass 返回 DW = ones(size(GF))（未使用传入 W）
                    if exist('Wvec','var') && ~isempty(Wvec)
                        warnMsg = ['你为滤波器定义了权重向量 w，但 @allpass 内部使用固定权重（DW = ones(size(GF))），', ...
                                   '传入的 w 将不会影响 allpass 的目标响应。是否继续？'];
                        choice = uiconfirm(dlg_cfirpm, warnMsg, 'allpass 权重提示', 'Options', {'继续','取消'}, 'DefaultOption', 1, 'CancelOption', 2, "Icon","question");
                        if strcmp(choice, '取消')
                            return;
                        end
                    end
                    % 不需要额外参数；通过校验，函数会正常返回并由外层写入 params



                case 'multiband'
                    % 解析 amb
                    try
                        AmbStr = strtrim(edtFrespExtra.Value); 
                        if contains(AmbStr, '[') || contains(AmbStr, ']')
                            uialert(dlg_cfirpm,'multiband幅值向量 amb 解析失败，请不要在输入中包含方括号"["或"]"，直接输入数字列表（用半角逗号或空格分隔）。','参数错误'); 
                            return; 
                        end
                        ambVec = str2num(['[', edtFrespExtra.Value, ']']); %#ok<ST2NM>
                    catch
                        uialert_safe(dlg_cfirpm, '无法解析 multiband 幅值向量 amb。请用逗号或空格分隔数字列表。', '参数错误');
                        return;
                    end
                    if isempty(ambVec) || ~isnumeric(ambVec)
                        uialert_safe(dlg_cfirpm, 'multiband 幅值向量 amb 不能为空且必须为数值向量。', '参数错误');
                        return;
                    end
                    ambVec = double(ambVec(:))';
                    % amb 长度必须等于 f 长度
                    if numel(ambVec) ~= numel(fvec)
                        uialert_safe(dlg_cfirpm, 'multiband 幅值向量 amb 的长度必须等于频率向量 f 的长度（节点匹配）。', '参数错误');
                        return;
                    end
                    % amb 元素必须为有限实数
                    if ~isreal(ambVec) || any(~isfinite(ambVec))
                        uialert_safe(dlg_cfirpm, 'multiband 幅值向量 amb 必须为有限的实数值。', '参数错误');
                        return;
                    end
                    params_amb = ambVec;


                case 'differentiator'
                    % --------------------------
                    % differentiator 专用严格校验
                    % --------------------------
                    % 将频率归一化到相对于 nyq 的 [-1,1] 空间（f_norm）

                    f_norm = fvec / nyq;   % 归一化（与 cfirpm 的调用约定一致）
                    
                    % 长度检查：只允许 2 或 4
                    Le = numel(f_norm);
                    if ~(Le == 2 || Le == 4)
                        uialert_safe(dlg_cfirpm, '@differentiator 要求频率向量 f 的元素个数为 2 或 4（半域或跨零写法）。', '参数错误');
                        return;
                    end
                    
                    % Le==2：所有边界必须严格为正（不能包含 0 或负值）
                    if Le == 2
                        if any(f_norm <= tol)
                            uialert_safe(dlg_cfirpm, '@differentiator 在 2 元素模式下要求两个边界均为正（不能包含 0 或负值）。', '参数错误');
                            return;
                        end
                    else
                        % Le==4：中间两项必须跨越 0（F(2)*F(3) <= 0）
                        if f_norm(2) * f_norm(3) > tol
                            uialert_safe(dlg_cfirpm, '@differentiator 的 4 元素 f 要求 f(2) 与 f(3) 跨越 0（中间必须经过 DC）。', '参数错误');
                            return;
                        end
                        % 若中间边界非常接近0，提醒用户注意 1/GF 权重问题
                        if abs(f_norm(2)) <= tol || abs(f_norm(3)) <= tol
                            warnMsg = ['检测到 f 的中间边界接近或等于 0。differentiator 在计算带权重时使用 1/frequency，' ...
                                       '若频率网格上包含 0 会导致除以 0 的数值问题。建议把边界稍微移开 0（例如改为 ±eps），是否继续？'];
                            choice = uiconfirm(dlg_cfirpm, warnMsg, '可能的数值问题', 'Options', {'继续','取消'}, 'DefaultOption', 2, 'CancelOption', 2, "Icon","warning");
                            if strcmp(choice, '取消')
                                return;
                            end
                        end
                    end
                    
                    % 解析 edtFrespExtra：尝试解析 Fs (采样率)
                    params_fs = [];
                    if exist('edtFrespExtra','var') && ~isempty(strtrim(edtFrespExtra.Value))
                        try
                            % 解析 fs（标量，正数）
                            fs_val = str2double(strtrim(edtFrespExtra.Value));
                            if isempty(fs_val) || isnan(fs_val) || ~isfinite(fs_val) || fs_val <= 0
                                uialert_safe(dlg_cfirpm, sprintf('differentiator 采样率 fs 必须为正数（标量，默认为 S.fs 即 %g）。', S.fs), '参数错误');
                                return;
                            end
                            %  检查 differentiator 采样率 fs 与 S.fs 是否相等
                             
                            if ~isempty(fs_val) && isprop(S,'fs') && fs_val ~= S.fs
                                prompt = sprintf('注意：differentiator 在设计时使用 fs=%g，但当前信号/处理采样率为 %g。请确认是否继续？', fs_val, S.fs);
                                choice = uiconfirm(dlg_cfirpm, prompt, '采样率不一致', 'Options', {'继续','自动调整并继续','取消'}, 'DefaultOption', 2, 'CancelOption', 3, "Icon","warning");
                                if strcmpi(choice, '取消')
                                    return;
                                elseif strcmpi(choice,'自动调整并继续')
                                    edtFrespExtra.Value = sprintf('%g', S.fs);
                                    fs_val = S.fs;
                                else
                                     % 继续，仍然使用当前differentiator采样率
                                end
                            end
                         
                            params_fs = double(fs_val);
                        catch
                        end
                    end 
                    
                    
                    % 检查 sym 与 DC 在过渡带的约束
                    if exist('symVal','var') && ~isempty(symVal)
                        symEffective = lower(symVal);
                    else
                        % 默认逻辑：delay==0 -> 'odd'，否则 'real'（与 differentiator.m 中 defaults 行为一致）
                        if exist('dVal','var') && dVal == 0
                            symEffective = 'odd';
                        else
                            symEffective = 'real';
                        end
                    end
                    
                    if strcmpi(symEffective, 'odd')
                        % odd 对称要求频带边界为非负，且 DC 必须位于过渡带
                        if any(f_norm < -tol)
                            uialert_safe(dlg_cfirpm, '对于 ''odd'' 对称，频率边界必须在非负区间（0..nyq）。', '参数错误');
                            return;
                        end
                        if Le == 2
                            % 2 元素模式下确保首边界 > 0（使 DC 留在过渡带）
                            if f_norm(1) <= tol
                                uialert_safe(dlg_cfirpm, '使用 ''odd'' 对称并采用 2 元素 f 时，首个边界应 > 0（确保 DC 在过渡带）。', '参数错误');
                                return;
                            end
                        else
                            % 4 元素模式下保证 0 在过渡带（已通过 f(2)*f(3) 检查，但再做显式保护）
                            if ~(f_norm(2) <= 0 + tol && f_norm(3) >= 0 - tol) && ~(f_norm(2) >= 0 - tol && f_norm(3) <= 0 + tol)
                                % 如果不显式跨零，提醒并阻止
                                uialert_safe(dlg_cfirpm, '对于 ''odd'' 对称，4 元素形式必须使 DC（0）位于两个带之间的过渡带。请调整 f 以满足该条件。', '参数错误');
                                return;
                            end
                        end
                    end
                    
                    % 额外数值风险检测：权重中使用 1/GF，会在 GF 接近 0 时数值不稳
                    % 在 GUI 层做粗略检查：若任何带覆盖了 0 或包含非常接近 0 的边界，提示用户
                    riskDetected = false;
                    riskMsgs = {};
                    % 检查每个带 [f(2k-1), f(2k)] 是否包含 0
                    for k = 1:2:Le-1
                        lo = min(f_norm(k), f_norm(k+1));
                        hi = max(f_norm(k), f_norm(k+1));
                        if lo <= tol && hi >= -tol
                            % 区间跨越或包含 0
                            % 但 differentiator 允许 DC 在过渡带，而不允许 DC 在通带
                            % 这里我们只检测"可能包含 0"的情形并提示
                            riskDetected = true;
                            riskMsgs{end+1} = sprintf('频带 [%g, %g] 可能包含或接近 0（DC），在该带上权重使用 1/frequency 可能导致数值不稳。', lo, hi); %#ok<AGROW>
                        end
                    end
                    if riskDetected
                        warnSummary = sprintf('%s\n', riskMsgs{:});
                        prompt = sprintf('检测到可能的数值风险（权重包含 1/f）：\n\n%s\n建议：将 DC 保持在过渡带，或微调带边界以避免在权重计算中出现 0；是否继续？', warnSummary);
                        choice = uiconfirm(dlg_cfirpm, prompt, 'differentiator 数值风险', 'Options', {'继续','取消'}, 'DefaultOption', 2, 'CancelOption', 2, "Icon","warning");
                        if strcmp(choice, '取消')
                            return;
                        end
                    end
                         

                case 'hilbfilt'
                    % 针对 hilbfilt 的严格校验（增强）
                
                    % 归一化频率到 [-1,1] 中的 [ -1 .. 1 ] 相对 Nyquist (f_norm in [-1,1])
                    f_norm = fvec / nyq;
            
                    % hilbfilt 只接受长度 2 或 4 的 F（见 MATLAB 内置 hilbfilt.m）
                    if ~(numel(f_norm) == 2 || numel(f_norm) == 4)
                        uialert_safe(dlg_cfirpm, '@hilbfilt 要求频率向量 f 的元素个数为 2 或 4（对应半域或跨零对称定义）。', '参数错误');
                        return;
                    end
            
                    % 情形 1：两个边界（半域写法） -> 要求都为正（>0）
                    if numel(f_norm) == 2
                        if any(f_norm <= tol)
                            uialert_safe(dlg_cfirpm, '当使用 2 元素的 f（半域写法）时，两个频率边界必须为正（>0），以符合 hilbfilt 的约束。', '参数错误');
                            return;
                        end
                    else
                        % 情形 2：四个边界（跨零写法） -> 中间两项必须跨越 0
                        if f_norm(2) * f_norm(3) > tol
                            uialert_safe(dlg_cfirpm, '当使用 4 元素的 f（跨零写法）时，f(2) 与 f(3) 必须跨越 0（即乘积 <= 0）。', '参数错误');
                            return;
                        end
                    end
            
                    % 对称性（sym）与 DC 在过渡带的关系校验
                    % Determine effective symmetry: if user explicitly set symVal use it;
                    % otherwise follow hilbfilt 的 defaults 行为（delay==0 => 'odd'，否则 'real'）
                    if exist('symVal','var') && ~isempty(symVal)
                        symEffective = lower(symVal);
                    else
                        if exist('dVal','var') && dVal == 0
                            symEffective = 'odd';
                        else
                            symEffective = 'real';
                        end
                    end
            
                    % 如果使用 odd 对称，则要求频带边界在非负区间且 DC 必须位于过渡带
                    if strcmpi(symEffective, 'odd')
                        % odd 要求 f 全为非负（上层已有对 sym 的非负检查，但这里加严）
                        if any(f_norm < -tol)
                            uialert_safe(dlg_cfirpm, sprintf('当选择对称性 ''odd'' 时，频率向量 f 必须在 [0, %g] 范围内（Hz）。', nyq), '参数错误');
                            return;
                        end
                        % 对于半域 (2 元素) 情形，确保第一个边界大于 0（以把 DC 留在过渡带）
                        if numel(f_norm) == 2
                            if f_norm(1) <= tol
                                uialert_safe(dlg_cfirpm, '对于 ''odd'' 对称且使用 2 元素的 f，首个边界应 > 0（确保 DC 在过渡带，而非通带）。', '参数错误');
                                return;
                            end
                        else
                            % 对于 4 元素情形且请求 odd（不常见），确保没有把 0 放入通带（粗略检查）
                            if any(abs(f_norm) <= tol)
                                uialert_safe(dlg_cfirpm, '使用 ''odd'' 对称时，请勿把 0 作为带边（DC 必须在过渡带）。请调整 f 以使 DC 在过渡区。', '参数错误');
                                return;
                            end
                        end
                    end
            
                    % 防止用户误把 "额外 fresp 参数" 放到 edtFrespExtra（hilbfilt 不接受 amb/ainvsinc 之类）
                    if exist('edtFrespExtra','var') && ~isempty(strtrim(edtFrespExtra.Value))
                        % 给用户确认（warn），因为 edtFrespExtra 常用于其他 fresp 的额外参数
                        warnMsg = ['你在 "额外参数" 中填入了内容，但 @hilbfilt 仅接受可选的 group_delay（请通过 group delay 字段填写）。', ...
                                   newline, '是否继续？'];
                        choice = uiconfirm(dlg_cfirpm, warnMsg, 'hilbfilt 额外参数提示', 'Options', {'继续','取消'}, 'DefaultOption', 2, 'CancelOption', 2);
                        if strcmp(choice, '取消')
                            return;
                        end
                    end
                    % 通过所有检查后继续（注意：对权重 w 的带数一致性检查你前面已做）
                    
                    % --- 处理 hilbfilt 返回选项（仅在 inputSel 为 fresp 且 fresp == hilbfilt 时） ---
                    % 确认单选组可用并有选择
                    if ~(exist('bgHilbReturn','var') && isvalid(bgHilbReturn) && ~isempty(bgHilbReturn.SelectedObject))
                        uialert_safe(dlg_cfirpm, '请选择 "应用滤波器返回结果"（返回解析信号 或 仅filter后信号）。', '参数缺失');
                        return;
                    end
                    selectedTag = bgHilbReturn.SelectedObject.Tag;
                    if strcmpi(selectedTag, 'analytic')
                        params_hilbfilt_return = 'analytic';   
                    else
                        params_hilbfilt_return = 'filtered';
                    end
                      

                case 'invsinc'
                    % 归一化频率到 [-1,1]（基于 nyq）
                    f_norm = fvec / nyq;
                
                    % invsinc 要求 F 长度为 4 或 6（在 invsinc.m：Le==4 或 Le==6）
                    Le = numel(f_norm);
                    if ~(Le == 4 || Le == 6)
                        uialert_safe(dlg_cfirpm, '@invsinc 要求频率向量 f 的元素个数为 4 或 6（半域或跨零多带写法）。', '参数错误');
                        return;
                    end
                    
                    % Le==4: 要求所有边界非负（>=0）
                    if Le == 4
                        if any(f_norm < -tol)
                            uialert_safe(dlg_cfirpm, '@invsinc 在 4 元素模式下要求所有频率边界为非负（>= 0）。', '参数错误');
                            return;
                        end
                    else
                        % Le==6: 中间两项需跨越 0 (F(3)*F(4) <= 0)
                        if f_norm(3) * f_norm(4) > tol
                            uialert_safe(dlg_cfirpm, '@invsinc 在 6 元素模式下要求 f(3) 与 f(4) 跨越 0（含 DC）。', '参数错误');
                            return;
                        end
                    end
                
                    % 解析 edtFrespExtra（sinc_arg A, 可选 delay D）
                    params_ainvsinc = [];  % will write to params if set
                    if exist('edtFrespExtra','var') && ~isempty(strtrim(edtFrespExtra.Value))
                        try
                            % 解析 ainvsinc（标量）
                            ai_val = str2double(strtrim(edtFrespExtra.Value));
                            if isempty(ai_val) || isnan(ai_val) || ~isfinite(ai_val)
                                uialert_safe(dlg_cfirpm, 'invsinc 增益 ainvsinc 必须为有效数值（标量，默认 1）。', '参数错误');
                                return;
                            end
                            params_ainvsinc = double(ai_val);
                        catch
                            uialert_safe(dlg_cfirpm, '解析 invsinc 参数时出错。', '参数错误');
                            return;
                        end
                    end
                    
                    % ---- 额外数值安全校验与零点检测 ----
                    ai = params_ainvsinc;
                    
                    % 不希望 ai 为 NaN/Inf，之前已检查，但再确认
                    if any(~isfinite(ai))  || isempty(ai)
                        uialert_safe(dlg_cfirpm, 'invsinc 的 ainvsinc 必须为有限值。', '参数错误');
                        return;
                    end
                    
                    % ai == 0 意味着 sinc(0 * f) == sinc(0) == 1 => 1./sinc = 1 常数（通常不是预期）
                    if ai == 0
                        choice = uiconfirm(dlg_cfirpm, '你设置 ainvsinc = 0，这会使通带目标响应恒等于 1（1./sinc(0)=1），通常这不是 invsinc 的典型用途。是否继续？', ...
                            'invsinc 参数提示', 'Options', {'继续','取消'}, 'DefaultOption', 2, 'CancelOption', 2, "Icon","warning");
                        if strcmp(choice, '取消')
                            return;
                        end
                    end
                    
                    % 我们检查对"候选通带区间"（按 CFIRPM 约定，区间为 f(1:2), f(3:4), ...）
                    % 在这些区间中，若存在非零整数 k 使得 k ∈ [ai * f_lo, ai * f_hi]，则 sinc(ai * f) 在该区间内有零点 -> 可能导致 1./sinc 发散
                    badFound = false;
                    badList = {};
                    % 采样阈值：若 sinc 的绝对值在通带样点上低于这个阈值，认为不安全
                    samp_threshold = 1e-6;
                    % 在每个候选带内做粗略整数检测 + 细化数值采样
                    for jj = 1:2:Le-1
                        fl = f_norm(jj);
                        fh = f_norm(jj+1);
                        lo = min(fl, fh); hi = max(fl, fh);
                        % 如果区间非常小，继续但注意
                        if hi - lo < eps
                            % very narrow, still check
                        end
                        % scaled range
                        a = ai * lo;
                        b = ai * hi;
                        rmin = min(a,b); rmax = max(a,b);
                        % find any integer n in [ceil(rmin), floor(rmax)] excluding 0
                        nlo = ceil(rmin);
                        nhi = floor(rmax);
                        nIntersect = [];
                        for n = nlo:nhi
                            if n ~= 0
                                nIntersect(end+1) = n; %#ok<AGROW>
                            end
                        end
                        if ~isempty(nIntersect)
                            badFound = true;
                            badList{end+1} = sprintf('区间 [%g, %g] (归一化) 可能包含 sinc 零点，对应整数 k=%s', lo, hi, mat2str(nIntersect)); %#ok<AGROW>
                            continue; % 已有整数，不必做采样
                        end
                        % 若未检测到整数，做数值采样检查（更稳妥）
                        % 在该区间内等距取 11 个点（端点已包含），计算 sinc(ai * f) 的最小绝对值
                        sample_pts = linspace(lo, hi, 11);
                        svals = sinc(ai * sample_pts); % MATLAB sinc is sin(pi*x)/(pi*x); 但 invsinc 使用 MATLAB 的 sinc
                        % 注意：MATLAB 的 sinc(x) 实现等价 sin(pi*x)/(pi*x)
                        if min(abs(svals)) < samp_threshold
                            badFound = true;
                            minval = min(abs(svals));
                            badList{end+1} = sprintf('区间 [%g, %g] 数值检查：min(|sinc|) = %.3e (< %.1e)。可能存在数值不稳定。', lo, hi, minval, samp_threshold); %#ok<AGROW>
                        end
                    end
                    
                    if badFound
                        % 给出建议并要求用户确认
                        msg = ['检测到在某些候选通带区间内 sinc(ai * f) 可能为 0 或非常接近 0，' ...
                               '这会导致 invsinc 的目标响应 1./sinc(...) 在这些频率上发散或数值不稳定。\n\n' ...
                               '问题摘要：\n' sprintf('%s\n', badList{:}) ...
                               '\n建议（任选其一）：\n' ...
                               '  • 改变 ainvsinc（例如从 1 改为 0.9 或 1.1），以避免整数倍零点；\n' ...
                               '  • 稍微调整通带边界使其避开零点频率；\n' ...
                               '  • 增大 lgrid（例如从 25 -> 80/100），以提高优化网格分辨率；\n' ...
                               '  • 或者使用显式的幅值向量 a（若适用），绕开 invsinc 特殊形状。\n\n' ...
                               '是否仍然继续？'];
                        
                        choice = uiconfirm(dlg_cfirpm, msg, 'invsinc 数值风险', 'Options', {'继续','取消'}, 'DefaultOption', 2, 'CancelOption', 2, "Icon","warning");
                        if strcmp(choice, '取消')
                            return;
                        end
                    end
                                        

                otherwise
                    % 其它函数无需额外强制校验
            end
        end
    


        % ============================ (6) 幅值向量 a 的深度校验（若选择） ============================
        % 若选择幅值向量 a 路径，则解析 a 并校验
        Avec = [];
        if strcmpi(inputSel, '幅值向量a')
            AStr = strtrim(edtA.Value);
            if contains(AStr, '[') || contains(AStr, ']')
                uialert(dlg_cfirpm,'幅值向量 a 解析失败，请不要在输入中包含方括号"["或"]"，直接输入数字列表（用半角逗号或空格分隔）。','参数错误'); 
                return; 
            end
            try
                Avec = str2num(['[', edtA.Value, ']']); %#ok<ST2NM>
            catch
                uialert_safe(dlg_cfirpm, '无法解析幅值向量 a。', '参数错误');
                return;
            end
            if isempty(Avec) || ~isnumeric(Avec)
                uialert_safe(dlg_cfirpm, '幅值向量 a 必须为数值向量。', '参数错误');
                return;
            end
            Avec = double(Avec(:))';
            % 长度必须与 f 匹配
            if numel(Avec) ~= numel(fvec)
                uialert_safe(dlg_cfirpm, '幅值向量 a 的长度必须等于频率向量 f 的长度（节点匹配）。', '参数错误');
                return;
            end
            % 元素必须为实数且有限
            if ~isreal(Avec) || any(~isfinite(Avec))
                uialert_safe(dlg_cfirpm, '幅值向量 a 必须为有限的实数值。', '参数错误');
                return;
            end
            % ------------------- a 在 DC/Nyquist 端点的额外提示 -------------------
            if ~isempty(Avec)
                % DC (0 Hz) 检查：若用户选择 odd symmetry，则应该保证 DC 对应幅值为 0（或 DC 在过渡带）
                idx_dc = find(abs(fvec) < tol);
                if ~isempty(idx_dc) && exist('symVal','var') && strcmpi(symVal, 'odd')
                    if any(abs(Avec(idx_dc)) > sqrt(eps))
                        uialert_safe(dlg_cfirpm, '在 ''odd'' 对称下，幅值向量 a 在 DC (0 Hz) 处必须为 0 或确保 DC 在过渡带。', '参数错误');
                        return;
                    end
                end
                % Nyquist 检查已做提示（奇数阶情况下）
            end
            % ------------------------------------------------------------------------

        else
            % 若未选择 a，确保 fresp 有意义（互斥校验）
            if ~(strcmpi(inputSel,'频率响应函数fresp'))
                uialert_safe(dlg_cfirpm, '必须在"幅值向量 a"与"频率响应函数 fresp"之间选择其一。', '参数错误');
                return;
            end
        end
    

    
        % ============================ (7) sym 与频率向量的兼容性校验（若启用 sym） ============================
        if exist('symVal','var') && ~strcmpi(symVal, 'none')
            symLower = lower(symVal);
            if ismember(symLower, {'even','odd','real'})
                % 首先检查 f 是否都为非负
                if any(fvec < -tol)
                    uialert_safe(dlg_cfirpm, sprintf('当选择对称性 ''%s'' 时，频带边缘必须只在非负频率区间[0 %g]。请移除负频率或将对称性设为 ''none''。', symVal, nyq), '参数错误');
                    return;
                end
            end
        end
    
    
        % ============================ (8) 参数间依赖关系与综合校验（轻量检查） ============================
        % 确保频带定义合理（最简单检查：每一对 [f(2k-1), f(2k)] 是一个带，且下一个带的起始频率 > 当前带的结束频率）
        nf = numel(fvec);
        nb = nf / 2;
        for k = 1:nb-1
            end_k = fvec(2*k);
            start_k1 = fvec(2*k+1);
            if start_k1 <= end_k + tol
                uialert_safe(dlg_cfirpm, sprintf('频带定义有重叠或未严格分离：第 %d 个带结束 %g，下一带开始 %g。请修正 f 向量。', k, end_k, start_k1), '参数错误');
                return;
            end
        end
    
    
        % ============================ (9) 保存 debug / skip_stage2（仅在启用时写入） ============================
        % 注意：只在用户勾选"启用 debug"时才把 debug 字段写入 params
        if exist('cbEnableDebug','var') && isvalid(cbEnableDebug) && cbEnableDebug.Value
            debugOptVal  = ddDebug.Value; % 'trace' / 'plots' / 'both' / 'off'
            if strcmpi(debugOptVal, 'off')
            % 如果你希望在启用时仍然传入 'off'，删除下面这两行
            debugOptVal = [];
            end
        else
            debugOptVal = [];
        end
        
        % skip_stage2（仅在勾选时写入 true）
        if exist('cbSkipStage2','var') && isvalid(cbSkipStage2) && cbSkipStage2.Value
            skipStage2Flag = true;
        else
            skipStage2Flag = false;
        end


        % ------------------- Nyquist 端点与奇数阶 N 的联动检查 -------------------
        % 如果用户选择了奇数阶 N，而且边界中有等于 +/- nyq 的点且目标在这些点非零，
        % 则 cfirpm 内部会把 N 递增 1。GUI 层应提示用户或让其确认。
        N = FIROrder;
        if exist('N','var') && mod(N,2) == 1
            % 查找是否包含正/负 Nyquist
            idx_nyq_pos = find(abs(fvec - nyq) < tol);
            idx_nyq_neg = find(abs(fvec + nyq) < tol);
            idx_nyq = [idx_nyq_pos, idx_nyq_neg];
            if ~isempty(idx_nyq)
                % 如果用户是通过幅值向量 a 定义目标，则检查 a 在这些端点是否近似为 0
                nonzero_at_nyq = false;
                if exist('Avec','var') && ~isempty(Avec)
                    if any(abs(Avec(idx_nyq)) > sqrt(eps))
                        nonzero_at_nyq = true;
                    end
                else
                    % 若使用 fresp 路径，无法直接读取 a；仅给出警告
                    nonzero_at_nyq = true; % 保守处理：提示用户
                end
                if nonzero_at_nyq
                    prompt = sprintf(['你选择了奇数阶（N = %d），并且频率向量包含 Nyquist (±%g Hz)。\n'...
                        'cfirpm 在此情况下会自动把阶数加 1 以确保 Nyquist 增益为 0，或强制修改设计以满足约束。\n'...
                        '是否继续并允许自动调整阶数？'], N, nyq);
                    choice = uiconfirm(dlg_cfirpm, prompt, 'Nyquist 与阶数冲突', 'Options', {'允许自动调整','取消'}, 'DefaultOption', 1, 'CancelOption', 2, "Icon","warning");
                    if strcmpi(choice, '取消')
                        return;
                    else
                        % 允许继续：记录提醒信息（可在后续调用处显示），但 GUI 不直接改写 FIROrder
                        % optional: params.note = 'User allowed auto-increment of odd N due to Nyquist non-zero';
                    end
                end
            end
        end
        % ------------------------------------------------------------------------



        % ============================ (10) 成功 -> 构造并返回 params 结构 ============================
        params = struct();
        params.fHz = fvec;
        params.f_norm = f_norm;                 % 归一化频率 -1..1（直接可用于 cfirpm）
        params.FIROrder = FIROrder;                  % FIROrder（便利记录）
        params.output = outputVal;
        params.InputSel = getInputSel();
    
        if exist('Avec','var') && ~isempty(Avec); params.a = Avec; else; if isfield(params,'a'), params = rmfield(params,'a'); end; end
        if exist('Wvec','var') && ~isempty(Wvec); params.w = Wvec; else; if isfield(params,'w'), params = rmfield(params,'w'); end; end
        if exist('frespVal','var') && ~isempty(frespVal); params.fresp = frespVal; else; if isfield(params,'fresp'), params = rmfield(params,'fresp'); end; end
        if exist('user_fresp_file','var') && ~isempty(user_fresp_file); params.user_fresp_file = user_fresp_file; else; if isfield(params,'user_fresp_file'), params = rmfield(params,'user_fresp_file'); end; end
        if exist('symVal','var') && ~isempty(symVal); params.sym = symVal; else; if isfield(params,'sym'), params = rmfield(params,'sym'); end; end
        if exist('lgridVal','var') && ~isempty(lgridVal);  params.lgrid = lgridVal; else; if isfield(params,'lgrid'), params = rmfield(params,'lgrid'); end; end
        if exist('dVal','var') && (dVal ~= 0);   params.group_delay = dVal; else; if isfield(params,'group_delay'), params = rmfield(params,'group_delay'); end; end
        if exist('debugOptVal','var') && ~isempty(debugOptVal);   params.debugOpt = debugOptVal; else; if isfield(params,'debugOpt'), params = rmfield(params,'debugOpt'); end; end
        if exist('skipStage2Flag','var') && skipStage2Flag;   params.skip_stage2 = skipStage2Flag; else; if isfield(params,'skip_stage2'), params = rmfield(params,'skip_stage2'); end; end
        % 附加 spec 特定参数（若存在）
        if exist('params_amb','var'); params.amb = params_amb; else; if isfield(params,'amb'), params = rmfield(params,'amb'); end; end
        if exist('params_fs','var'); params.differentiator_fs = params_fs;  else; if isfield(params,'differentiator_fs'), params = rmfield(params,'differentiator_fs'); end; end
        if exist('params_ainvsinc','var'); params.ainvsinc = params_ainvsinc; else; if isfield(params,'ainvsinc'), params = rmfield(params,'ainvsinc'); end; end
        if exist('user_fresp_A','var'); params.user_fresp_A  = user_fresp_A; end
        
        if exist('user_fresp_param_style','var') && ~isempty(user_fresp_param_style)
            params.user_fresp_param_style = user_fresp_param_style;
        else
            if isfield(params,'user_fresp_param_style'), params = rmfield(params,'user_fresp_param_style'); end
        end
        if exist('user_fresp_A_name','var') && ~isempty(user_fresp_A_name)
            params.user_fresp_A_name = user_fresp_A_name;
        else
            if isfield(params,'user_fresp_A_name'), params = rmfield(params,'user_fresp_A_name'); end
        end
        if exist('user_fresp_d_name','var') && ~isempty(user_fresp_d_name)
            params.user_fresp_d_name = user_fresp_d_name;
        else
            if isfield(params,'user_fresp_d_name'), params = rmfield(params,'user_fresp_d_name'); end
        end
        if exist('supports_regular_namevalue','var') && ~isempty(supports_regular_namevalue)
            params.user_fresp_use_nv = supports_regular_namevalue;
        else
            if isfield(params,'user_fresp_use_nv'), params = rmfield(params,'user_fresp_use_nv'); end
        end
        % --- 将 hilbfilt 返回选项写入 params ---
        if exist('params_hilbfilt_return','var') && ~isempty(params_hilbfilt_return)
            params.hilbfilt_return = params_hilbfilt_return;
        else
            if isfield(params,'hilbfilt_return'), params = rmfield(params,'hilbfilt_return'); end
        end

          
        % 结束 uiwait 并关闭对话框
        try
            if isvalid(dlg_cfirpm)
                uiresume(dlg_cfirpm); 
                delete(dlg_cfirpm); 
            end
        catch
            try delete(dlg_cfirpm); catch; end
        end

    end   % onConfirm 结束
    
end

%% ---- firls最小二乘法 "多带 / 高级滤波参数设置" 窗口（严格模态） ---- 
function params = openFirlsMultiBandWindow(parentFig, handles, S, FIROrder)
    FIR_Opt_Design_Method = handles.ddFIRMethod.Value;     
    params = [];
    nyq = max(1e-6, S.fs/2);   
    
    % 创建模态窗口
    dlg_firls = createCenteredUIFigure('Name','多带滤波参数设置','Position',[500 280 710 650],'WindowStyle','modal');
    gl_firls = uigridlayout(dlg_firls,[8,6]);
    gl_firls.RowHeight = {'fit','1x','1x','1x','1x','1x',40,'1x'};
    gl_firls.ColumnWidth = {120,'1x','1x',120,'1x','1x'};
    gl_firls.Padding = [10 10 10 10];

    try FIR_Opt_Method = handles.ddFIRMethod.Value; catch;  end

    % 说明文本（示例/格式提示），新增对奇对称选项的说明
    ExplanatoryText = sprintf(['%s参数设置说明（详细信息请参阅MATLAB帮助文档）：\n\n' ...
        '1. 滤波器阶数n：由 FIR阶数 输入框设置（阶数越高，过渡带越陡峭）。\n\n' ...
        '2. 频率向量f：使用 Hz 输入，要求按频带边缘升序排列；元素个数须为偶数。（程序在设计滤波器时将会归一化以符合firls()函数要求）\n' ...
        '例如：阻带1_start(0), 阻带1_end, 通带_start, 通带_end, 阻带2_start, 阻带2_end(Nyq)\n\n' ...
        '3. 幅值向量a：定义每个频带的理想幅值。与f的频带一一对应，长度 = length(f)。\n' ...
        '例如：阻带1_start(0)_amp, 阻带1_end_amp, 通带_start_amp, 通带_end_amp, 阻带2_start_amp, 阻带2_end(Nyq)_amp\n\n' ...
        '4. 权重向量w：控制每个频带的逼近精度。长度 = length(f)/2, 权重默认为 1 。\n' ...
        '例如：阻带1_w, 通带_w, 阻带2_w \n\n' ...
        '5. 设计奇对称滤波器（可选）：勾选后可选择 "hilbert" 或 "differentiator" 两种类型（互斥）。若不勾选，该选项不会被校验或保存。\n\n' ...
        '6. 输入各个参数向量时，不要加方括号[]，使用半角逗号或空格分隔。\n\n' ...
        '7. 退出设置窗口后，设置好的参数可以在下方参数显示栏查看。'],FIR_Opt_Method);
    lblIntro = uilabel(gl_firls,'Text',ExplanatoryText);
    lblIntro.Layout.Row = 1; lblIntro.Layout.Column = [1 6];
    lblIntro.WordWrap = 'on';

    FIR_Opt_Method_Text = sprintf('FIR 优化设计法 - %s', FIR_Opt_Method);
    lblFIR_Opt_Method = uilabel(gl_firls,'Text',FIR_Opt_Method_Text,'FontWeight','bold'); lblFIR_Opt_Method.Layout.Row = 2; lblFIR_Opt_Method.Layout.Column = [1 3];
    Nyq_Text = sprintf('Nyq：%d Hz', nyq);
    lblNyq = uilabel(gl_firls,'Text',Nyq_Text,'FontWeight','bold'); lblNyq.Layout.Row = 2; lblNyq.Layout.Column = [4 6];

    lblN = uilabel(gl_firls,'Text','滤波器阶数 n:','FontWeight','bold'); lblN.Layout.Row = 3; lblN.Layout.Column = 1;
    try firOrderVal = round(double(handles.edtFIROrder.Value)); catch;  firOrderVal = FIROrder; end
    Filter_N_Text = sprintf('%d', firOrderVal);
    lblN_Text = uilabel(gl_firls,'Text',Filter_N_Text,'FontWeight','bold'); lblN_Text.Layout.Row = 3; lblN_Text.Layout.Column = [2 6];

    % 频率
    lblF = uilabel(gl_firls,'Text','频率向量 f (Hz):','FontWeight','bold'); lblF.Layout.Row = 4; lblF.Layout.Column = 1;
    edtF = uieditfield(gl_firls,'text'); edtF.Layout.Row = 4; edtF.Layout.Column = [2 6];
    edtF.Placeholder = sprintf('例：0, %d, %d, %d, %d, %d （以 0 开始并以 Nyq 结束，元素个数须为偶数）', round(nyq/20), round(nyq/10), round(nyq/5), round(nyq/2), nyq);

    % 幅值 a
    lblA = uilabel(gl_firls,'Text','幅值向量 a:','FontWeight','bold'); lblA.Layout.Row = 5; lblA.Layout.Column = 1;
    edtA = uieditfield(gl_firls,'text'); edtA.Layout.Row = 5; edtA.Layout.Column = [2 6];
    edtA.Placeholder = '例：0, 0, 1, 1, 0, 0  (与频带个数对应)';

    % 权重复选框（默认不勾选）+ 权重输入框（默认禁用）
    chkW = uicheckbox(gl_firls,'Text','权重向量 w(可选):','FontWeight','bold','Value',false);
    chkW.Layout.Row = 6; chkW.Layout.Column = 1;

    edtW = uieditfield(gl_firls,'text','Enable','off'); edtW.Layout.Row = 6; edtW.Layout.Column = [2 6];
    edtW.Placeholder = '例：10 1 10 (长度 = length(f)/2)';

    % 当复选框变化时启用/禁用 edtW
    chkW.ValueChangedFcn = @(src,event) onWCheck(src, edtW);

    % ------------------ 新增：奇对称设计复选 + 单选按钮（互斥） ------------------
    chkOdd = uicheckbox(gl_firls,'Text','设计奇对称滤波器:','FontWeight','bold','Value',false);
    chkOdd.Layout.Row = 7; chkOdd.Layout.Column = 1;

    bgOdd = uibuttongroup(gl_firls,'Title','','SelectionChangedFcn',@(bg,event) onOddTypeChanged(bg,event), 'Enable','off');
    bgOdd.Layout.Row = 7; bgOdd.Layout.Column = [2 3];
    % 两个互斥的单选按钮
    rbHilb = uiradiobutton(bgOdd,'Text','hilbert','Tag','hilbert');
    rbHilb.Position = [10 10 120 20];
    rbDiff = uiradiobutton(bgOdd,'Text','differentiator','Tag','differentiator');
    rbDiff.Position = [90 10 120 20];

    % 当复选框变化时启用/禁用 bgOdd（单选按钮组）
    chkOdd.ValueChangedFcn = @(src,event) onOddCheck(src, bgOdd);

    % -----------------------------------------------------------------------

    % --- 新增：hilbfilt 返回选项 ---
    lblHilbReturn = uilabel(gl_firls,'Text','应用滤波器返回结果:','FontWeight','bold','Visible','off'); 
    lblHilbReturn.Layout.Row = 7; lblHilbReturn.Layout.Column = 4;
    bgHilbReturn = uibuttongroup(gl_firls, 'Title','','Visible','off');
    bgHilbReturn.Layout.Row = 7; bgHilbReturn.Layout.Column = [5 6];
    % 在组内创建两个互斥的单选按钮
    rbHilbAnalytic = uiradiobutton(bgHilbReturn, 'Text', '返回解析信号', 'Position', [10 10 120 20],'Tag','analytic');
    rbHilbFiltered = uiradiobutton(bgHilbReturn, 'Text', '仅filter后信号', 'Position', [110 10 120 20],'Tag','filtered');
    % 默认选择"返回解析信号"
    rbHilbAnalytic.Value = true;


    % 按钮：确认 / 取消
    btnOK = uibutton(gl_firls,'push','Text','确认','ButtonPushedFcn',@(src,event) onConfirm());
    btnOK.Layout.Row = 8; btnOK.Layout.Column = [1 3];
    btnCancel = uibutton(gl_firls,'push','Text','取消','ButtonPushedFcn',@(src,event) (delete(dlg_firls)));
    btnCancel.Layout.Row = 8; btnCancel.Layout.Column = [4 6];

    % 阻塞直到 dlg_firls 被关闭
    uiwait(dlg_firls);

    % 回调：启用/禁用权重输入
    function onWCheck(src, edt)
        if src.Value
            edt.Enable = 'on';
        else
            edt.Value = '';
            edt.Enable = 'off';
        end
    end

    function onOddTypeChanged(bg,event)
        if strcmpi(bgOdd.SelectedObject.Tag,'hilbert')
            lblHilbReturn.Visible = 'on';
            lblHilbReturn.Enable = 'on';
            bgHilbReturn.Visible = 'on';
            bgHilbReturn.Enable = 'on';  
        else
            lblHilbReturn.Visible = 'off';
            lblHilbReturn.Enable = 'off';
            bgHilbReturn.Visible = 'off';
            bgHilbReturn.Enable = 'off';  
        end
    end

    % 回调：启用/禁用奇对称单选组
    function onOddCheck(src, bg)
        if src.Value
            bg.Enable = 'on';
            % default select hilbert
            bg.SelectedObject = rbHilb;
            if strcmpi(bgOdd.SelectedObject.Tag,'hilbert')
                lblHilbReturn.Visible = 'on';
                lblHilbReturn.Enable = 'on';
                bgHilbReturn.Visible = 'on';
                bgHilbReturn.Enable = 'on';  
            end
        else
            bg.Enable = 'off';
            % default select hilbert
            bg.SelectedObject = rbHilb;
            lblHilbReturn.Visible = 'off';
            lblHilbReturn.Enable = 'off';
            bgHilbReturn.Visible = 'off';
            bgHilbReturn.Enable = 'off';  
        end
    end

    % firls内部确认回调（做严格校验）
    % ---- 强化校验版 onConfirm （使用 firchk_core）----
    function onConfirm()
        try
            % ---------------- 1) 解析并校验阶数 n ----------------
            try
                nRaw = handles.edtFIROrder.Value;
            catch
                nRaw = FIROrder;
            end
            if isempty(nRaw) || ~isnumeric(nRaw)
                uialert(dlg_firls,'滤波器阶数 n 无效，请输入整数。','参数错误'); return;
            end
            N = double(nRaw);
            if N < 0 || ~isfinite(N)
                uialert(dlg_firls,'滤波器阶数 n 必须是非负有限值。','参数错误'); return;
            end
            % 强制为整数（向最近整数取整），并提示如果有改变
            N_round = round(N);
            if N_round ~= N
                uialert(dlg_firls,sprintf('滤波器阶数 n 将被四舍五入到最近的整数 %d。', N_round),'注意');
            end
            N = N_round;

            % ---------------- 2) 解析并校验频率向量 f（Hz） ----------------
            fstr = strtrim(edtF.Value);
            if contains(fstr, '[') || contains(fstr, ']')
                uialert(dlg_firls,'频率 f 解析失败：请不要包含方括号"["或"]"。','参数错误'); return;
            end
            f = str2num(['[', fstr, ']']); %#ok<ST2NM>
            if isempty(f) || ~isnumeric(f)
                uialert(dlg_firls,'频率 f 解析失败，请按示例输入（半角逗号或空格分隔的数字）。','参数错误'); return;
            end
            if any(isnan(f)) || any(isinf(f))
                uialert(dlg_firls,'频率向量包含 NaN 或 Inf，请检查输入。','参数错误'); return;
            end
            if any(diff(f) <= 0)
                uialert(dlg_firls,'频率必须严格升序排列，不能有重复或非递增项。','参数错误'); return;
            end
            if mod(length(f),2) ~= 0 || length(f) < 4
                uialert(dlg_firls,'频率向量 f 必须为偶数个，并且至少 4 项（成对出现）。','参数错误'); return;
            end

            % 归一化频率供 firchk/firls 内部使用（Nyq -> 1）
            Fn = double(f(:)) / double(nyq);  % normalized to [0,1], column

            % ---------------- 3) 解析并校验幅值向量 a ----------------
            astr = strtrim(edtA.Value);
            if contains(astr, '[') || contains(astr, ']')
                uialert(dlg_firls,'幅值 a 解析失败：请不要包含方括号"["或"]"。','参数错误'); return;
            end
            a = str2num(['[', astr, ']']); %#ok<ST2NM>
            if isempty(a) || ~isnumeric(a)
                uialert(dlg_firls,'幅值 a 解析失败，请按示例输入（半角逗号或空格分隔的数字）。','参数错误'); return;
            end
            if length(a) ~= length(f)
                uialert(dlg_firls,'幅值 a 的长度应等于 length(f)。','参数错误'); return;
            end
            if any(isnan(a)) || any(isinf(a))
                uialert(dlg_firls,'幅值向量包含 NaN 或 Inf，请检查输入。','参数错误'); return;
            end

            % ---------------- 4) 权重向量 w（可选） ----------------
            willSaveW = false;
            weight = [];
            if chkW.Value
                wstr = strtrim(edtW.Value);
                if contains(wstr, '[') || contains(wstr, ']')
                    uialert(dlg_firls,'权重 w 解析失败：请不要包含方括号"["或"]"。','参数错误'); return;
                end
                w = str2num(['[', wstr, ']']); %#ok<ST2NM>
                if isempty(w) || ~isnumeric(w)
                    uialert(dlg_firls,'已选择使用权重，但权重解析失败，请检查输入。','参数错误'); return;
                end
                if length(w) ~= length(f)/2
                    uialert(dlg_firls,'权重 w 的长度应等于 length(f)/2。','参数错误'); return;
                end
                if any(~isfinite(w)) || any(w < 0)
                    uialert(dlg_firls,'权重向量必须为非负有限数（建议使用正数）。','参数错误'); return;
                end
                weight = double(w(:));
                willSaveW = true;
            end

            % ---------------- 5) 奇对称 (Hilbert / Differentiator) ----------------
            willSaveOdd = false;
            oddType = '';
            filtypeNum = 0; % 0 => even-symmetric (type I/II), 1 => odd-symmetric (type III/IV)
            differFlag = false;
            if chkOdd.Value
                sel = bgOdd.SelectedObject;
                if isempty(sel)
                    uialert(dlg_firls,'已选择设计奇对称滤波器，但未选择类型（hilbert 或 differentiator）。','参数错误'); return;
                end
                oddType = lower(sel.Tag);
                if ~any(strcmp(oddType, {'hilbert','differentiator'}))
                    uialert(dlg_firls,'奇对称类型无效，请选择 hilbert 或 differentiator。','参数错误'); return;
                end
                willSaveOdd = true;
                filtypeNum = 1;
                if strcmpi(oddType,'differentiator')
                    differFlag = true;
                    % 如果有频带在 0 开始，给出提示（firls 会对 0 做近似处理，但可能导致拟合靠近低频失真）
                    if any(Fn(1:2:end) == 0) || Fn(1)==0
                        warnMsg = sprintf(['注意：你选择了 differentiator 且包含以 0 为边界的频带。' ...
                            ' 在设计中，low-frequency 处可能存在数值奇异性。建议将起始频率从 0 略微调整为小正值（如 1e-6*Nyq）。是否继续？']);
                        choice = uiconfirm(dlg_firls, warnMsg, '注意', 'Options', {'继续','取消'}, 'DefaultOption', 2, 'CancelOption', 2, "Icon","warning");
                        if strcmp(choice, '取消')
                            return;
                        end
                        % 不强制退出，继续让 firchk_core 去处理；若需强制用户修改，可 return 并提示
                    end
                end
                % --- 处理 hilbert 返回选项（仅在勾选"设计奇对称滤波器" 且 选择 hilbert 时） --- 
                if strcmpi(oddType,'hilbert') 
                    % 确认单选组可用并有选择
                    if ~(exist('bgHilbReturn','var') && isvalid(bgHilbReturn) && ~isempty(bgHilbReturn.SelectedObject))
                        uialert_safe(dlg_firls, '请选择 "应用滤波器返回结果"（返回解析信号 或 仅filter后信号）。', '参数缺失');
                        return;
                    end
                    if strcmpi(bgHilbReturn.SelectedObject.Tag,'analytic')
                        params_hilbert_return = 'analytic';   
                    else
                        params_hilbert_return = 'filtered';
                    end 
                end
            end

            % ---------------- 6) 使用 firchk_core 进行更严格的约束检查/自动调整 ----------------
            % 调用提供的 firchk_core（在 MATLAB 环境下会调用系统 firchk）
            [N_adj, errMsg, warnMsg] = firchk_core(N, Fn(end), a(:), filtypeNum);
            if ~isempty(errMsg)
                uialert(dlg_firls, ['阶数/频率/幅值检查失败：' errMsg], '参数错误'); return;
            end
            if ~isempty(warnMsg)
                prompt = sprintf('firchk 警告：%s', warnMsg);
                choice = uiconfirm(dlg_firls, prompt, '警告', 'Options', {'继续','取消'}, 'DefaultOption', 1, 'CancelOption', 2, "Icon","warning");
                if strcmpi(choice, '取消')
                    return;
                end
            end
            if N_adj ~= N
                prompt = sprintf(['注意：输入阶数 n=%d 会被调整为 %d 以满足 FIR 设计约束（由 firchk 建议）。\n'...
                     '是否自动调整：是（推荐，将自动修改FIR 阶数输入框的值）、否（保持当前阶数不变）。'], N, N_adj);
                choice = uiconfirm(dlg_firls, prompt, '信息', 'Options', {'是','否'}, 'DefaultOption', 1, 'CancelOption', 2, "Icon","info");
                if strcmpi(choice, '否')
                 
                else
                    handles.edtFIROrder.Value = N_adj;
                end
            end

            % ---------------- 7) 额外安全校验（常见陷阱） ----------------
            % 防止全0或单一值幅度导致无意义设计
            if all(a == 0)
                uialert(dlg_firls,'幅值 a 全为 0，会产生零滤波器，请检查是否输入错误。','参数错误'); return;
            end

            % 权重默认行为：如果未勾选则由 firls 内部使用 ones，若勾选则保存
            % 将校验后的参数组装到 p（保留 f 为 Hz，外部模块按需归一化）
            p = struct();
            p.method = FIR_Opt_Design_Method;
            p.f = f(:)';        % 保留为 Hz（和你的现有界面一致）
            p.a = a(:)';

            p.newFIROrder =   handles.edtFIROrder.Value;
            
            if willSaveW
                p.w = weight(:)';
            end
            if willSaveOdd
                p.oddSymmetric = true;
                p.oddType = oddType;
                if exist('params_hilbert_return','var') && ~isempty(params_hilbert_return)
                    p.hilbert_return = params_hilbert_return;
                end
            end

            % 写回主界面 handles（保持原行为）
            % try
            %     % guidata(parentFig, handles);
            % catch
            %     % 失败不阻塞保存 p
            % end

            % 成功保存 -> 关闭窗口并提示
            params = p;

        
            % 结束 uiwait 并关闭对话框
            try
                if isvalid(dlg_firls)
                    uiresume(dlg_firls); 
                    delete(dlg_firls); 
                end
            catch
                try delete(dlg_firls); catch; end
            end

        catch ME
            % 捕获任何未预见的异常（GUI 层友好呈现）
            uialert(dlg_firls, ['参数解析/校验出错：' ME.message], '错误');
        end
    end

end

%% ---- fircls约束最小二乘法 "多带 / 高级滤波参数设置" 窗口（严格模态） ---- 
function params = openFirclsMultiBandWindow(parentFig, handles, S, FIROrder)
    FIR_Opt_Design_Method = handles.ddFIRMethod.Value;     
    params = [];
    nyq = max(1e-6, S.fs/2);   
    
    % 创建模态窗口
    dlg_fircls = createCenteredUIFigure('Name','多带滤波参数设置','Position',[480 230 750 720],'WindowStyle','modal');
    gl_fircls = uigridlayout(dlg_fircls,[9,6]);
    gl_fircls.RowHeight = {'fit','1x','1x','1x','1x','1x','1x','1x','1x'};
    gl_fircls.ColumnWidth = {120,'1x','1x',120,'1x','1x'};
    gl_fircls.Padding = [10 10 10 10];

   
    try FIR_Opt_Method = handles.ddFIRMethod.Value; catch;  end

    % 说明文本（示例/格式提示）
    ExplanatoryText = sprintf(['%s参数设置说明（详细信息请参阅MATLAB帮助文档）：\n\n' ...
        '1. 滤波器阶数n：由 FIR阶数 输入框设置（阶数越高，过渡带越陡峭）。\n\n' ...
        '2. 频率向量f：使用 Hz 输入，要求以 0 开始、以 Nyq 结束；按升序排列。（程序在设计滤波器时将会归一化以符合fircls()函数要求）\n' ...
        '例如：0, %d, %d, %d(Nyq) 。它定义了三个频带：[0, %d]，[%d, %d]和 [%d, %d]\n\n' ...
        '3. 理想幅值amp：定义每个频带的理想幅值，长度 = length(f)-1。\n' ...
        '例如：0, 1, 0 。它定义了三个频带的理想幅值：[0, %d]为0，[%d, %d]为1， [%d, %d]为0\n\n' ...
        '4. 幅值响应上限up和下限lo：定义了滤波器频率响应在每个频带内允许的上边界和下边界，与 amp具有相同的长度。\n' ...
        '例如up：0.01, 1.02, 0.01 。它定义各频带幅值上限：阻带[0, %d]<0.01, 通带[%d, %d]<1.02, 阻带[%d, %d]<0.01\n' ...
        '例如lo：-0.01, 0.98, -0.01 。它定义各频带幅值下限：阻带[0, %d]>-0.01, 通带[%d, %d]>0.98, 阻带[%d, %d]>-0.01  \n\n' ...
        '5. 滤波器设计显示选项 designflag：指定为下列值之一：' ...
        '\n trace：以文本形式显示设计中使用的设计表格' ...
        '\n plots：绘制滤波器的幅度、群延迟、零点和极点图' ...
        '\n both：同时显示文本表格和图形\n\n' ...
        '6. 输入各个参数向量时，不要加方括号[]，使用半角逗号或空格分隔。\n\n' ...
        '7. 退出设置窗口后，设置好的参数可以在下方参数显示栏查看。'],FIR_Opt_Method,round(nyq/10), round(nyq/5), nyq, ...
        round(nyq/10),round(nyq/10),round(nyq/5),round(nyq/5),nyq, ...
        round(nyq/10),round(nyq/10),round(nyq/5),round(nyq/5),nyq, ...
        round(nyq/10),round(nyq/10),round(nyq/5),round(nyq/5),nyq, ...
        round(nyq/10),round(nyq/10),round(nyq/5),round(nyq/5),nyq);

    lblIntro = uilabel(gl_fircls,'Text',ExplanatoryText);
    lblIntro.Layout.Row = 1; lblIntro.Layout.Column = [1 6];
    lblIntro.WordWrap = 'on';
    
    FIR_Opt_Method_Text = sprintf('FIR 优化设计法 - %s', FIR_Opt_Method);
    lblFIR_Opt_Method = uilabel(gl_fircls,'Text',FIR_Opt_Method_Text,'FontWeight','bold'); lblFIR_Opt_Method.Layout.Row = 2; lblFIR_Opt_Method.Layout.Column = [1 3];
    Nyq_Text = sprintf('Nyq：%d Hz', nyq);
    lblNyq = uilabel(gl_fircls,'Text',Nyq_Text,'FontWeight','bold'); lblNyq.Layout.Row = 2; lblNyq.Layout.Column = [4 6];

    lblN = uilabel(gl_fircls,'Text','滤波器阶数 n:','FontWeight','bold'); lblN.Layout.Row = 3; lblN.Layout.Column = 1;
    try firOrderVal = round(double(handles.edtFIROrder.Value)); catch;  end
    Filter_N_Text = sprintf('%d', firOrderVal);
    lblN_Text = uilabel(gl_fircls,'Text',Filter_N_Text,'FontWeight','bold'); lblN_Text.Layout.Row = 3; lblN_Text.Layout.Column = [2 6];



    lblF = uilabel(gl_fircls,'Text','频率向量 f (Hz)：','FontWeight','bold'); lblF.Layout.Row = 4; lblF.Layout.Column = 1;
    edtF = uieditfield(gl_fircls,'text'); edtF.Layout.Row = 4; edtF.Layout.Column = [2 6];
    edtF.Placeholder = sprintf('例：0, %d, %d, %d （以 0 开始并以 Nyq 结束）', round(nyq/10), round(nyq/5), nyq);

    lblAmp = uilabel(gl_fircls,'Text','理想幅值 amp:','FontWeight','bold'); lblAmp.Layout.Row = 5; lblAmp.Layout.Column = 1;
    edtAmp = uieditfield(gl_fircls,'text'); edtAmp.Layout.Row = 5; edtAmp.Layout.Column = [2 6];
    edtAmp.Placeholder = '例：0, 1, 0 （长度 = length(f)-1）';

    lblUp = uilabel(gl_fircls,'Text','频带上界 up:','FontWeight','bold'); lblUp.Layout.Row = 6; lblUp.Layout.Column = 1;
    edtUp = uieditfield(gl_fircls,'text'); edtUp.Layout.Row = 6; edtUp.Layout.Column = [2 6];
    edtUp.Placeholder = '例：0.01, 1.02, 0.01 （长度 = length(f)-1）';

    lblLo = uilabel(gl_fircls,'Text','频带下界 lo:','FontWeight','bold'); lblLo.Layout.Row = 7; lblLo.Layout.Column = 1;
    edtLo = uieditfield(gl_fircls,'text'); edtLo.Layout.Row = 7; edtLo.Layout.Column = [2 6];
    edtLo.Placeholder = '例：-0.01, 0.98, -0.01 （长度 = length(f)-1）';

    % 滤波器设计显示（可选）
    cbDesignDisp = uicheckbox(gl_fircls,'Text','滤波器设计显示:','Value',false,'FontWeight','bold');
    cbDesignDisp.Layout.Row = 8; cbDesignDisp.Layout.Column = 1;
    ddDesignDisp = uidropdown(gl_fircls,'Items',{'trace','plots','both'},'Value','both','Enable','off');
    ddDesignDisp.Layout.Row = 8; ddDesignDisp.Layout.Column = [2 3];
        
    % cbDesignDisp 回调：启用/禁用 ddDesignDisp
    cbDesignDisp.ValueChangedFcn = @(src,~) setEnableDesignDisp(src, ddDesignDisp);


    % 按钮：确认 / 取消
    btnOK = uibutton(gl_fircls,'push','Text','确认','ButtonPushedFcn',@(src,event) onConfirm());
    btnOK.Layout.Row = 9; btnOK.Layout.Column = [1 3];
    btnCancel = uibutton(gl_fircls,'push','Text','取消','ButtonPushedFcn',@(src,event) (delete(dlg_fircls)));
    btnCancel.Layout.Row = 9; btnCancel.Layout.Column = [4 6];

    % 阻塞直到 dlg_firls 被关闭
    uiwait(dlg_fircls);

    % 滤波器设计显示 cbDesignDisp 回调
    function setEnableDesignDisp(src, DesignDisp)
        if src.Value
            DesignDisp.Enable = 'on';
        else
            DesignDisp.Enable = 'off';
        end
    end

    % fircls 优化设计法内部确认回调（做严格校验） 
    function onConfirm()
        try
            % ------------------ 基本频率解析与校验（保留并强化） ------------------
            fstr = strtrim(edtF.Value);
            if contains(fstr, '[') || contains(fstr, ']')
                uialert(dlg_fircls,'频率 f 解析失败，请不要在输入中包含方括号"["或"]"，直接输入数字列表（用半角逗号或空格分隔）。','参数错误'); 
                return; 
            end
            f = str2num(['[', fstr, ']']); %#ok<ST2NM>
            if isempty(f), uialert(dlg_fircls,'频率 f 解析失败，请按示例输入（半角逗号或空格分隔的数字列表）。','参数错误'); 
                return; 
            end
            if ~isnumeric(f) 
                uialert(dlg_fircls,'频率不是有效的数值向量。','参数错误'); return;
            end
            if any(isnan(f)) || any(isinf(f))
                uialert(dlg_fircls,'频率向量包含 NaN 或 Inf，请检查输入。','参数错误'); return;
            end
            % 数值范围检查
            if any(f < 0) || any(f > nyq), uialert(dlg_fircls,sprintf('频率必须在 [0, %.1f] Hz 内。', nyq),'参数错误'); 
                return; 
            end
            if any(diff(f) <= 0), uialert(dlg_fircls,'频率必须严格升序排列，不能有重复或非递增项。','参数错误'); 
                return; 
            end
    
            % 至少要有一个带（f 长度 >= 2）
            if length(f) < 2
                uialert(dlg_fircls,'频率向量 f 至少要包含两个点（起点与终点），以定义至少一个频带。','参数错误');
                return;
            end
    
            % 容差（用于避免浮点误差导致的误判）
            tol = 1e-9;
    
            % f 必须从 0 开始并以 nyq 结束
            if abs(f(1)-0) > 1e-6 || abs(f(end)-nyq) > 1e-6
                uialert(dlg_fircls,sprintf(' f 要求以 0 开始并以 Nyq (%.1f) 结束。', nyq),'参数错误'); return;
            end
    
            % ------------------ amp/up/lo 解析与基本长度检查（保留并强化） ------------------
            if contains(strtrim(edtAmp.Value), '[') || contains(strtrim(edtAmp.Value), ']')
                uialert(dlg_fircls,'幅值 amp 解析失败，请不要在输入中包含方括号"["或"]"，直接输入数字列表（用半角逗号或空格分隔）。','参数错误'); 
                return; 
            end
            if contains(strtrim(edtUp.Value), '[') || contains(strtrim(edtUp.Value), ']')
                uialert(dlg_fircls,'频带上界 up 解析失败，请不要在输入中包含方括号"["或"]"，直接输入数字列表（用半角逗号或空格分隔）。','参数错误'); 
                return;
             end
            if contains(strtrim(edtLo.Value), '[') || contains(strtrim(edtLo.Value), ']')
                uialert(dlg_fircls,'频带下界 lo 解析失败，请不要在输入中包含方括号"["或"]"，直接输入数字列表（用半角逗号或空格分隔）。','参数错误'); 
                return;
            end
            amp = str2num(['[', strtrim(edtAmp.Value), ']']); %#ok<ST2NM>
            up = str2num(['[', strtrim(edtUp.Value), ']']); %#ok<ST2NM>
            lo = str2num(['[', strtrim(edtLo.Value), ']']); %#ok<ST2NM>
    
            if isempty(amp), uialert(dlg_fircls,'幅值 amp 解析失败，请按示例输入（半角逗号或空格分隔的数字列表）。','参数错误'); return; end
            if isempty(up), uialert(dlg_fircls,'频带上界 up 解析失败，请按示例输入（半角逗号或空格分隔的数字列表）。','参数错误'); return; end
            if isempty(lo), uialert(dlg_fircls,'频带下界 lo 解析失败，请按示例输入（半角逗号或空格分隔的数字列表）。','参数错误'); return; end
    
            if length(amp) ~= length(f)-1, uialert(dlg_fircls,'amp 的长度必须等于 length(f)-1。','参数错误'); return; end
            if length(up) ~= length(f)-1, uialert(dlg_fircls,'up 的长度必须等于 length(f)-1。','参数错误'); return; end
            if length(lo) ~= length(f)-1, uialert(dlg_fircls,'lo 的长度必须等于 length(f)-1。','参数错误'); return; end
    
            % 元素为数字、实数、有限值
            if any(~isfinite(amp)) || any(~isreal(amp))
                uialert(dlg_fircls,'amp 包含非有限或非实数值，请检查输入。','参数错误'); return;
            end
            if any(~isfinite(up)) || any(~isreal(up))
                uialert(dlg_fircls,'up 包含非有限或非实数值，请检查输入。','参数错误'); return;
            end
            if any(~isfinite(lo)) || any(~isreal(lo))
                uialert(dlg_fircls,'lo 包含非有限或非实数值，请检查输入。','参数错误'); return;
            end
    
            % -------- 检查：每个位置上 up 必须大于或等于对应的 amp（up >= amp） --------
            badIdx_up_amp = find( up < amp - tol );  % up < amp -> 错误（允许极小 tol）
            if ~isempty(badIdx_up_amp)
                maxShow = min(10, numel(badIdx_up_amp));
                lines = arrayfun(@(k) sprintf('索引 %d: up=%.6g, amp=%.6g', k, up(k), amp(k)), ...
                                 badIdx_up_amp(1:maxShow), 'UniformOutput', false);
                if numel(badIdx_up_amp) > maxShow
                    lines{end+1} = sprintf('... 另有 %d 个索引不满足 up>=amp', numel(badIdx_up_amp)-maxShow);
                end
                msg = strjoin(lines, newline);
                uialert(dlg_fircls, sprintf('参数错误：up 的每个条目应大于或等于 amp 的对应元素。出错位置：\n%s', msg), '参数错误');
                return;
            end
            % -------- 检查：每个位置上 lo 必须小于或等于对应的 amp（lo <= amp） --------
            badIdx_lo_amp = find( lo > amp + tol );  % lo > amp -> 错误（允许极小 tol）
            if ~isempty(badIdx_lo_amp)
                maxShow = min(10, numel(badIdx_lo_amp));
                lines = arrayfun(@(k) sprintf('索引 %d: lo=%.6g, amp=%.6g', k, lo(k), amp(k)), ...
                                 badIdx_lo_amp(1:maxShow), 'UniformOutput', false);
                if numel(badIdx_lo_amp) > maxShow
                    lines{end+1} = sprintf('... 另有 %d 个索引不满足 lo<=amp', numel(badIdx_lo_amp)-maxShow);
                end
                msg = strjoin(lines, newline);
                uialert(dlg_fircls, sprintf('参数错误：lo 的每个条目应小于或等于 amp 的对应元素。出错位置：\n%s', msg), '参数错误');
                return;
            end
            % -------- 检查：每个位置上 up 必须严格大于对应的 lo（up > lo） --------
            badIdx_up_lo = find( up <= lo + tol );   % up <= lo -> 错误（允许极小 tol）
            if ~isempty(badIdx_up_lo)
                maxShow = min(10, numel(badIdx_up_lo));
                lines = arrayfun(@(k) sprintf('索引 %d: up=%.6g, lo=%.6g', k, up(k), lo(k)), ...
                                 badIdx_up_lo(1:maxShow), 'UniformOutput', false);
                if numel(badIdx_up_lo) > maxShow
                    lines{end+1} = sprintf('... 另有 %d 个索引不满足 up>lo', numel(badIdx_up_lo)-maxShow);
                end
                msg = strjoin(lines, newline);
                uialert(dlg_fircls, sprintf('参数错误：up 的每个元素必须大于 lo 的对应元素。出错位置：\n%s', msg), '参数错误');
                return;
            end
    
            % ------------------ FIR 阶数检查（增强） ------------------
            try
                firOrderVal = round(double(handles.edtFIROrder.Value));
            catch
                uialert(dlg_fircls,'无法读取滤波器阶数，请检查 FIR 阶数输入框。','参数错误'); return;
            end
            if ~isfinite(firOrderVal) || firOrderVal < 3
                uialert(dlg_fircls,'滤波器阶数 n 必须为大于等于 3 的整数。','参数错误'); return;
            end
    
            % % -------- ADDED/ENHANCED CHECK: 高频端 Fs/2 (Nyq) 增益为非零时要求偶阶（MATLAB fircls 特性） --------
            % % 如果最后一个频带的理想幅值在 Nyq（Fs/2）处非零，则 fircls 要求阶数为偶数
            % if abs(amp(end)) > tol
            %     if mod(firOrderVal,2) ~= 0
            %         uialert(dlg_fircls,sprintf(['检测到在 Nyq (%.1f Hz) 处的理想幅值 amp(end)=%.6g 非零。\n' ...
            %             '根据 fircls 的要求，当 Fs/2 处增益非零时，滤波器阶数 n 必须为偶数。请把阶数设置为偶数（例如 %d 或 %d）。'], ...
            %             nyq, amp(end), firOrderVal-1, firOrderVal+1), '参数错误');
            %         return;
            %     end
            % end
    
            % ------------------ ADDED: 额外调用 firchk_core 进行更严格的规则检查（可用则调用） ------------------
            % 使用归一化频率向量 be（和 fircls 内部一致，f/nyq -> [0 1]）
            be = f / nyq;
            try
                % firchk signature in MATLAB: [n,msg1,msg2,msgobj] = firchk(N,Fend,A)
                [n_chk, msg1, msg2, msgobj] = firchk_core(firOrderVal, be(end), amp);
                if ~isempty(msg1)
                    % 致命错误：阻止继续
                    uialert(dlg_fircls, sprintf('firchk 校验失败：%s', getString(msgobj)), '参数错误');
                    return;
                end
                if ~isempty(msg2)
                    % 非致命警告：给用户提示但允许继续（与原 fircls 行为一致） 
                    prompt = sprintf('firchk 警告：%s', getString(msgobj));
                    choice = uiconfirm(dlg_fircls, prompt, '警告', 'Options', {'继续','取消'}, 'DefaultOption', 1, 'CancelOption', 2, "Icon","warning");
                    if strcmpi(choice, '取消')
                        return;
                    end
                end

                if n_chk ~= firOrderVal
                    prompt = sprintf(['注意：输入阶数 n=%d 会被调整为 %d 以满足 FIR 设计约束（由 firchk 建议）。\n'...
                         '是否自动调整：是（推荐，将自动修改FIR 阶数输入框的值）、否（保持当前阶数不变）。'], firOrderVal, n_chk);
                    choice = uiconfirm(dlg_fircls, prompt, '信息', 'Options', {'是','否'}, 'DefaultOption', 1, 'CancelOption', 2, "Icon","info");
                    if strcmpi(choice, '否')
                     
                    else
                        handles.edtFIROrder.Value = n_chk;
                    end
                end

            catch chkME
                % 如果系统中 firchk 不可用或调用失败，则不致命，继续，但记录（不中断）
                % 这只是保险机制，通常在 R2025b 中应该可用
                % 记录到命令行（不打断 GUI）
          
            end
    
            % 设计显示（trace/plots/both），保持原逻辑
            designflagVal = [];
            if cbDesignDisp.Value
                designflagVal = ddDesignDisp.Value;
                if ~any(strcmpi(designflagVal,{'trace','plots','both'}))
                    uialert(dlg_fircls,'设计显示选项无效。','参数错误');
                    return;
                end
            end
    
            % ------------------ 一切通过 -> 打包参数并写回主界面 ------------------
            params = struct();
            params.method = FIR_Opt_Design_Method;
            params.f = f;
            params.amp = amp;
            params.up = up;
            params.lo = lo;
            params.n = firOrderVal;    % 新增：把阶数也放入 params，便于主界面使用

            params.newFIROrder = handles.edtFIROrder.Value;

            if exist('designflagVal','var') && ~isempty(designflagVal)
                params.designflag = designflagVal;
            end
    
            % guidata(parentFig, handles);  % 把参数写回主界面 handles
            % 成功保存 -> 关闭窗口并提示
                
            % 结束 uiwait 并关闭对话框
            try
                if isvalid(dlg_fircls)
                    uiresume(dlg_fircls); 
                    delete(dlg_fircls); 
                end
            catch
                try delete(dlg_fircls); catch; end
            end

        catch ME
            uialert(dlg_fircls, ['参数解析/校验出错：' ME.message], '错误');
        end
    end
    
end

%% ---- 约束最小二乘1(fircls1) "多带 / 高级滤波参数设置" 窗口（严格模态） ---- 
function params = openFircls1AdvancedWindow(parentFig, handles, S, FIROrder)
    % 约束最小二乘1(fircls1) 多带/高级参数设置（严格模态）
    params = []; nyq = max(1e-6, S.fs/2);
    dlg_fircls1 = createCenteredUIFigure('Name','约束最小二乘1(fircls1) 滤波参数设置窗口','Position',[400 170 900 800],...
                   'WindowStyle','modal');
    gl_fircls1 = uigridlayout(dlg_fircls1,[11,6]); 
    gl_fircls1.RowHeight = {'fit','1x','1x','1x','1x','1x','1x','1x','1x','1x','1x'};
    gl_fircls1.ColumnWidth = {'fit','1x','1x','fit','1x','1x'}; 
    gl_fircls1.Padding = [10 10 10 10];
    
    lblEx = uilabel(gl_fircls1);
    lblEx.Text = sprintf([...
        '约束最小二乘1(fircls1) 参数设置说明（详细信息请参阅MATLAB帮助文档）：\n\n' ...
        '1. 必须项：截止频率 fo(Hz)、通带纹波 dp、阻带纹波 ds。\n' ...
        '可选项：频带边缘 ft(Hz)；L2 加权函数边缘 fp(Hz)/fs(Hz)/k（同时启用）；滤波器设计显示选项 designDisplay。（设计时将会把 Hz 归一化以符合fircls1输入参数要求）\n\n' ...
        '2. 截止频率 fo(Hz)：介于 0 和 Nyq 之间的实数正标量，其中 Nyq 对应于奈奎斯特频率。\n\n' ...
        '3. 通带纹波 dp：实数正标量。通带纹波是通带内幅度相对于 1 的最大偏差。\n\n' ...
        '4. 阻带纹波 ds：实数正标量。阻带纹波是阻带内幅度相对于 0 的最大偏差。\n\n' ...
        '5. （可选）频带边缘频率 ft(Hz)：介于 0 和 Nyq 之间的实数正标量，其中 Nyq 对应于奈奎斯特频率。\n\n' ...
        '6. （可选）L2 加权函数的通带边缘频率 fp(Hz)：实数标量。fp的值必须位于通带边缘，对于低通滤波器 fp < fo，对于高通滤波器 fp > fo。\n\n' ...
        '7. （可选）L2 加权函数的通带边缘频率 fs(Hz)：实数标量。fs的值必须位于阻带边缘，对于低通滤波器 fs > fo，对于高通滤波器 fs < fo。\n\n' ...
        '8. （可选）通带与阻带设计 L2 误差比 k：实数标量。考虑到由边缘频率 fp和 fs得到的通带和阻带设计 L2 误差 e_p和 e_s，k的值为：k = e_p / e_s。\n\n' ...
        '9. （可选）滤波器设计显示选项 designDisplay：可指定为以下选项之一："trace"、"plots"、"both"。\n\n' ...
        '10. 退出设置窗口后，设置好的参数可以在下方参数显示栏查看。\n' ]); 
    lblEx.WordWrap='on'; lblEx.Layout.Row=1; lblEx.Layout.Column=[1 6];
    
    % 顶部信息：方法、Nyq、阶数
    try FIR_Opt_Method = handles.ddFIRMethod.Value; catch;  end
    FIR_Opt_Method_Text = sprintf('FIR 优化设计法 - %s', FIR_Opt_Method);
    lblMethod_fircls1 = uilabel(gl_fircls1,'Text',FIR_Opt_Method_Text,'FontWeight','bold'); lblMethod_fircls1.Layout.Row=2; lblMethod_fircls1.Layout.Column=[1 3];
    lblNyq = uilabel(gl_fircls1,'Text',sprintf('Nyq：%d Hz', nyq),'FontWeight','bold'); lblNyq.Layout.Row=2; lblNyq.Layout.Column=[4 6];
    lblN = uilabel(gl_fircls1,'Text','滤波器阶数 N:','FontWeight','bold'); lblN.Layout.Row=3; lblN.Layout.Column=1;
    lblN_Text = uilabel(gl_fircls1,'Text',sprintf('%d', FIROrder),'FontWeight','bold'); lblN_Text.Layout.Row=3; lblN_Text.Layout.Column=[2 6];

    lblType_fircls1 = uilabel(gl_fircls1,'Text','滤波类型:','FontWeight','bold'); lblType_fircls1.Layout.Row=4; lblType_fircls1.Layout.Column=1;
    ddFirType = uidropdown(gl_fircls1,'Items',{'低通','高通'},'Value','低通'); ddFirType.Layout.Row=4; ddFirType.Layout.Column=[2 3];
    
    lblFO = uilabel(gl_fircls1,'Text','截止频率 fo(Hz):','FontWeight','bold'); lblFO.Layout.Row=4; lblFO.Layout.Column=4;
    edtFO = uieditfield(gl_fircls1,'numeric','Value',nyq/10,'Limits',[1e-6 nyq],'Tooltip','设置截止频率(Hz)'); edtFO.Layout.Row=4; edtFO.Layout.Column=[5 6];
    
    lblDP = uilabel(gl_fircls1,'Text','通带纹波 dp:','FontWeight','bold'); lblDP.Layout.Row=5; lblDP.Layout.Column=1;
    edtDP = uieditfield(gl_fircls1,'numeric','Value',0.02,'Limits',[0 eps+1]); edtDP.Layout.Row=5; edtDP.Layout.Column=[2 3];
    lblDS = uilabel(gl_fircls1,'Text','阻带纹波 ds:','FontWeight','bold'); lblDS.Layout.Row=5; lblDS.Layout.Column=4;
    edtDS = uieditfield(gl_fircls1,'numeric','Value',0.008,'Limits',[0 eps+1]); edtDS.Layout.Row=5; edtDS.Layout.Column=[5 6];
    
    chkFT = uicheckbox(gl_fircls1,'Text','频带边缘频率 ft(Hz):','FontWeight','bold','Value',false);
    chkFT.Layout.Row=6; chkFT.Layout.Column=1;
    edtFT = uieditfield(gl_fircls1,'numeric','AllowEmpty',true,'Value',[],'Limits',[1e-6 nyq],'Enable','off');
    edtFT.Layout.Row=6; edtFT.Layout.Column=[2 3];
    % 将原来的简单回调替换为专用回调（互斥逻辑在 onChkFTChanged 中实现）
    chkFT.ValueChangedFcn = @onChkFTChanged;  % %% MOD: 专用回调

    chkL2 = uicheckbox(gl_fircls1,'Text','启用L2 加权函数的边缘频率设置','FontWeight','bold','Value',false);
    chkL2.Layout.Row=7; chkL2.Layout.Column=[1 3];
    lblFP = uilabel(gl_fircls1,'Text','L2 通带边缘 fp(Hz):','FontWeight','bold'); lblFP.Layout.Row=8; lblFP.Layout.Column=1;
    edtFP = uieditfield(gl_fircls1,'numeric','AllowEmpty',true,'Value',[],'Limits',[1e-6 nyq],'Enable','off'); edtFP.Layout.Row=8; edtFP.Layout.Column=[2 3];
    lblFS_Fircls1Advanced = uilabel(gl_fircls1,'Text','L2 阻带边缘 fs(Hz):','FontWeight','bold'); lblFS_Fircls1Advanced.Layout.Row=8; lblFS_Fircls1Advanced.Layout.Column=4;
    edtFS = uieditfield(gl_fircls1,'numeric','AllowEmpty',true,'Value',[],'Limits',[1e-6 nyq],'Enable','off'); edtFS.Layout.Row=8; edtFS.Layout.Column=[5 6];
    lblK = uilabel(gl_fircls1,'Text','通带/阻带 L2 误差比 k:','FontWeight','bold'); lblK.Layout.Row=9; lblK.Layout.Column=1;
    edtK = uieditfield(gl_fircls1,'numeric','Value',1,'Limits',[0 1e6],'Enable','off'); edtK.Layout.Row=9; edtK.Layout.Column=[2 3];
    % 将原来的简单绑定替换为专用回调（互斥逻辑在 onChkL2Changed 中实现）
    chkL2.ValueChangedFcn = @onChkL2Changed;  % %% MOD: 专用回调
    setEnableL2(false); % 初始禁用

    % 保留显示选项的回调（不变）
    chkDisplay = uicheckbox(gl_fircls1,'Text','滤波器设计显示:','FontWeight','bold','Value',false); chkDisplay.Layout.Row=10; chkDisplay.Layout.Column=1;
    ddDisplay = uidropdown(gl_fircls1,'Items',{'trace','plots','both'},'Value','both','Enable','off'); ddDisplay.Layout.Row=10; ddDisplay.Layout.Column=[2 3];

    % 默认禁用 L2 三项
    edtFP.Enable='off'; edtFS.Enable='off'; edtK.Enable='off';

    % chkDisplay 回调：控制下拉启/禁（保持原有实现）
    chkDisplay.ValueChangedFcn = @(s,e) setEnableFromCheck(ddDisplay,s.Value);
    
    % 按钮
    btnConfirm = uibutton(gl_fircls1,'push','Text','确认','ButtonPushedFcn',@onConfirm); btnConfirm.Layout.Row=11; btnConfirm.Layout.Column=[1 3];
    btnCancel  = uibutton(gl_fircls1,'push','Text','取消','ButtonPushedFcn',@(s,e) close(dlg_fircls1)); btnCancel.Layout.Row=11; btnCancel.Layout.Column=[4 6];
    
    uiwait(dlg_fircls1);

    % -----------------（新增：互斥回调）-----------------
    function onChkFTChanged(src, ~)
        % 当用户切换 chkFT 时触发（即时互斥 L2 设置）
        if src.Value
            % 如果勾选 ft，则立即取消并禁用 L2 复选框与 L2 输入
            try
                chkL2.Value = false;
            catch
            end
            chkL2.Enable = 'off';
            % 确保 L2 的输入被禁用并恢复默认（复用 setEnableL2 逻辑）
            setEnableL2(false);
            % 激活 ft 输入框
            edtFT.Enable = 'on';
        else
            % 当取消勾选 ft：启用 L2 复选框（但不自动勾选）
            chkL2.Enable = 'on';
            % 禁用并清空 ft 输入框（复用 setEnableFromCheck）
            setEnableFromCheck(edtFT, false);
        end
    end

    function onChkL2Changed(src, ~)
        % 当用户切换 chkL2 时触发（即时互斥 ft 设置）
        if src.Value
            % 若启用 L2，则取消并禁用 ft 复选框与 ft 输入
            try
                chkFT.Value = false;
            catch
            end
            chkFT.Enable = 'off';
            setEnableFromCheck(edtFT, false); % 关闭并清空 ft 输入
            % 启用 L2 的三个输入项
            setEnableL2(true);
        else
            % 取消 L2：恢复 ft 复选框的使能（不自动勾选）
            chkFT.Enable = 'on';
            setEnableL2(false); % 禁用
        end
    end
    % -----------------（新增结束）-----------------


    % helper
    function setEnableFromCheck(edt,val)
        try
            if val
                edt.Enable='on';
            else
                edt.Enable='off';
                % if isprop(edt,'AllowEmpty')&&edt.AllowEmpty
                %     edt.Value=[];
                % else
                %     edt.Value=NaN;
                % end
            end
        catch
        end
    end

    function setEnableL2(val)
        if val
            lblFP.Enable = 'on';
            lblFS_Fircls1Advanced.Enable = 'on';
            lblK.Enable = 'on';
            edtFP.Enable='on'; edtFS.Enable='on'; edtK.Enable='on';
        else
            lblFP.Enable = 'off';
            lblFS_Fircls1Advanced.Enable = 'off';
            lblK.Enable = 'off';
            edtFP.Enable='off'; edtFS.Enable='off'; edtK.Enable='off';
            % try
            %     if isprop(edtFP,'AllowEmpty')&&edtFP.AllowEmpty
            %         edtFP.Value=[];
            %     else
            %         edtFP.Value=NaN;
            %     end
            %     if isprop(edtFS,'AllowEmpty')&&edtFS.AllowEmpty
            %         edtFS.Value=[];
            %     else
            %         edtFS.Value=NaN;
            %     end
            %     edtK.Value=1;
            % catch
            % end
        end
    end
    
    function onConfirm(~,~)
        % 读取并基础转换（保持原 UI 名称）
        fircls1_fo_hz = double(edtFO.Value);
        fircls1_dp = double(edtDP.Value);
        fircls1_ds = double(edtDS.Value);

        % 读取阶数与滤波器类型（用于高/低通相关校验）
        try
            fir_order = round(double(handles.edtFIROrder.Value));
        catch
            fir_order = [];
        end
        fir_type_raw = ddFirType.Value; % 例如 '低通' / '高通' 或 'low'/'high'

        % 判断是否高通（兼容英文/中文首字）
        isHigh = false;
        if ischar(fir_type_raw) || isStringScalar(fir_type_raw)
            s_fir_type_raw = char(fir_type_raw);
            if ~isempty(s_fir_type_raw) && (lower(s_fir_type_raw(1))=='h' || contains(lower(s_fir_type_raw),'高'))
                isHigh = true;
            end
        end

        % ---------- 基本数值校验（fo / dp / ds） ----------
        if isempty(fircls1_fo_hz) || ~isfinite(fircls1_fo_hz) || ~(fircls1_fo_hz>0) || fircls1_fo_hz>=nyq
            uialert(dlg_fircls1, sprintf('截止频率 fo 必须为有限数，且在 (0, Nyq=%g) 范围内（Hz）。', nyq), '参数错误');
            return;
        end
        if isempty(fircls1_dp) || ~isfinite(fircls1_dp) || ~(fircls1_dp>0)
            uialert(dlg_fircls1, '通带纹波 dp 必须为有限正数。','参数错误');
            return;
        end
        if isempty(fircls1_ds) || ~isfinite(fircls1_ds) || ~(fircls1_ds>0)
            uialert(dlg_fircls1, '阻带纹波 ds 必须为有限正数。','参数错误');
            return;
        end
        if fircls1_dp >= 1
            uialert(dlg_fircls1, '通带纹波 dp 应小于 1（dp >= 1 将导致不合理的幅度规格）。','参数错误');
            return;
        end
        if fircls1_ds >= 1
            uialert(dlg_fircls1, '阻带纹波 ds 应小于 1（ds >= 1 将导致不合理的幅度规格）。','参数错误');
            return;
        end

        % ---------- 阶数校验（高通必须为偶数；最小阶数限制） ----------
        if isempty(fir_order) || ~isfinite(fir_order) || fir_order < 3
            uialert(dlg_fircls1, '滤波器阶数应为大于等于 3 的有限整数。','参数错误');
            return;
        end
        fir_order = round(fir_order);
        if isHigh
            % matlab 文档：highpass case order must be even; original fircls1 increments order by one if not even
            if mod(fir_order,2) ~= 0
                uialert(dlg_fircls1, '高通滤波器要求阶数为偶数。请将阶数修改为偶数并重试。','参数错误');
                return;
            end
        end

        % ---------- 互斥保护（GUI 回调中已有，但再次保险） ----------
        if chkFT.Value && chkL2.Value
            uialert(dlg_fircls1, '不能同时设置 频带边缘 ft 与 启用 L2 加权函数 的边界设置。请仅选择其中一项。','参数错误');
            return;
        end

        % ---------- 频率归一化（符合 fircls1 的 0..1 规范，1 对应 Nyq） ----------
        W0 = fircls1_fo_hz / nyq;   % 在 fircls1 中 W0 必须在 (0,1)
        tol = eps(max([abs(W0),1])); % 相对容忍度

        if ~(isfinite(W0) && W0>0 && W0<1)
            uialert(dlg_fircls1, '归一化后截止频率 W0 必须位于 (0,1)。请检查采样参数或 fo。','参数错误');
            return;
        end

        % ---------- ft（边缘频率 WT）校验（若选择） ----------
        if chkFT.Value
            fircls1_ft_hz = double(edtFT.Value);
            if isempty(fircls1_ft_hz) || ~isfinite(fircls1_ft_hz) || ~(fircls1_ft_hz>0) || fircls1_ft_hz>=nyq
                uialert(dlg_fircls1, sprintf('频带边缘 ft 必须为有限数，且在 (0, Nyq=%g) 范围内（Hz）。', nyq),'参数错误');
                return;
            end
            WT = fircls1_ft_hz / nyq;
            if abs(WT - W0) <= 10*tol
                uialert(dlg_fircls1, '频带边缘 ft 不得与截止频率 fo 相等（或数值太接近）。','参数错误');
                return;
            end
        else
            WT = [];
            fircls1_ft_hz = [];
        end

        % ---------- L2 加权函数边界（若启用） ----------
        useL2 = chkL2.Value;
        if useL2
            fircls1_fp_hz = double(edtFP.Value);
            fircls1_fs_hz = double(edtFS.Value);
            fircls1_k = double(edtK.Value);

            if isempty(fircls1_fp_hz) || ~isfinite(fircls1_fp_hz) || ~(fircls1_fp_hz>0) || fircls1_fp_hz>=nyq || ...
               isempty(fircls1_fs_hz) || ~isfinite(fircls1_fs_hz) || ~(fircls1_fs_hz>0) || fircls1_fs_hz>=nyq
                uialert(dlg_fircls1, 'L2 加权的边界 fp/fs 必须为有限数且在 (0, Nyq) 范围内。','参数错误');
                return;
            end
            if abs(fircls1_fp_hz - fircls1_fs_hz) <= eps(max([abs(fircls1_fp_hz),abs(fircls1_fs_hz),1]))
                uialert(dlg_fircls1, 'L2 加权的 fp 与 fs 不应相等（或数值太接近）。','参数错误');
                return;
            end
            if isempty(fircls1_k) || ~isfinite(fircls1_k) || ~(fircls1_k>0)
                uialert(dlg_fircls1, 'L2 误差比 k 必须为有限正数。','参数错误');
                return;
            end

            WP = fircls1_fp_hz / nyq;
            WS = fircls1_fs_hz / nyq;

            if ~(WP>0 && WP<1 && WS>0 && WS<1)
                uialert(dlg_fircls1, 'L2 加权的归一化边界 WP/WS 必须位于 (0,1)。','参数错误');
                return;
            end

            % 根据低通/高通，强制 WP < W0 < WS 或 WS < W0 < WP（与 fircls1 文档一致）
            if isHigh
                if ~( (WS < W0) && (W0 < WP) )
                    uialert(dlg_fircls1, '高通滤波器的 L2 边界必须满足 fs < fo < fp（即 WS < W0 < WP）。','参数错误');
                    return;
                end
            else
                if ~( (WP < W0) && (W0 < WS) )
                    uialert(dlg_fircls1, '低通滤波器的 L2 边界必须满足 fp < fo < fs（即 WP < W0 < WS）。','参数错误');
                    return;
                end
            end
        else
            fircls1_fp_hz = []; fircls1_fs_hz = []; fircls1_k = [];
            WP = []; WS = [];
        end

        % ---------- 额外的可选可行性检测（温和提示） ----------
        % 经验性检查：若规格给出非常窄的过渡带或非常小的 dp/ds，可能不存在给定阶数的解
        % 我们提示用户，但不强制阻止设计（允许用户继续）
        try
            % 计算最小归一化过渡带宽的近似（与阶数成反比，规则化判断）
            approx_min_trans = 2/(fir_order+1); % 经验性的阈值（仅用于提示）
            trans_candidates = [];
            if useL2
                trans_candidates = [trans_candidates, abs(W0 - WP), abs(WS - W0)];
            end
            if ~isempty(WT)
                trans_candidates = [trans_candidates, abs(W0 - WT)];
            end
            if ~isempty(trans_candidates)
                min_trans = min(trans_candidates);
                if min_trans < approx_min_trans
                    % 不是必须 fatal error，但提示并确认
                    warnMsg = sprintf(['注意：归一化过渡带 (%0.4g) 非常窄，相对于所选阶数 N=%d 可能无法找到满足 dp/ds 的滤波器。是否继续？\n' ...
                        '建议增加阶数或放宽 dp/ds。'], min_trans, fir_order);
                    choice = uiconfirm(dlg_fircls1, warnMsg, '可行性警告', 'Options', {'继续','取消'}, 'DefaultOption', 2, 'CancelOption', 2, "Icon","warning");
                    if strcmp(choice, '取消')
                        return;
                    end
                end
            end
        catch
            % 不影响后续
        end

        % ---------- 设计显示选项 ----------
        if chkDisplay.Value
            fircls1_designDisplay = ddDisplay.Value;
        end

        % ---------- 成功 -> 构造并返回 params 结构 ----------
        params = struct();
        params.FirMethod = 'fircls1';
        params.fircls1_FirType = ddFirType.Value;
        params.fircls1_fo = fircls1_fo_hz;
        params.fircls1_dp = fircls1_dp;
        params.fircls1_ds = fircls1_ds;
        params.fircls1_order = fir_order; % 将阶数一并写回参数
        params.fircls1_use_ft = logical(chkFT.Value);
        params.fircls1_use_L2 = logical(chkL2.Value);
        if exist('fircls1_ft_hz','var') && ~isempty(fircls1_ft_hz); params.fircls1_ft = fircls1_ft_hz; end
        if exist('fircls1_fp_hz','var') && ~isempty(fircls1_fp_hz); params.fircls1_fp = fircls1_fp_hz; end
        if exist('fircls1_fs_hz','var') && ~isempty(fircls1_fs_hz); params.fircls1_fs = fircls1_fs_hz; end
        if exist('fircls1_k','var') && ~isempty(fircls1_k); params.fircls1_k = fircls1_k; end
        if exist('fircls1_designDisplay','var') && ~isempty(fircls1_designDisplay); params.fircls1_designDisplay = fircls1_designDisplay; end

             
        % 结束 uiwait 并关闭对话框
        try
            if isvalid(dlg_fircls1)
                uiresume(dlg_fircls1); 
                delete(dlg_fircls1); 
            end
        catch
            try delete(dlg_fircls1); catch; end
        end
    end
    
end

%% ---- intfilt "多带 / 高级滤波参数设置" 窗口（严格模态） ---- 
function params = openIntfiltAdvancedWindow(parentFig, handles, S)
    params = [];
    nyq = max(1e-6, S.fs/2);

    % 严格模态窗口
    dlg_intfilt = createCenteredUIFigure('Name','intfilt插值滤波参数设置窗口','Position',[450 260 750 650], ...
                   'WindowStyle','modal');
    gl_intfilt = uigridlayout(dlg_intfilt,[8,6]);
    gl_intfilt.RowHeight = {'fit','1x','1x',40,'1x','1x',40,'1x'};
    gl_intfilt.ColumnWidth = {'fit','1x','1x','fit','1x','1x'};
    gl_intfilt.Padding = [8 8 8 8];
    gl_intfilt.RowSpacing = 6;
    gl_intfilt.ColumnSpacing = 6;

    % (a) 第1行 [1 6] 显示说明文本
    lblEx = uilabel(gl_intfilt,'Text',sprintf(['intfilt 插值参数设置说明（详细信息请参阅MATLAB帮助文档）：\n\n' ...
        '1. 上采样因子 l：样本数，指定为正整数标量。intfilt设计一个线性相位 FIR 滤波器，用于处理一个每 l个样本中插入了 l-1个连续零值的序列。\n\n' ...
        '2. 非零样本数 p：指定为正整数标量。intfilt设计一个线性相位 FIR 滤波器，该滤波器使用最近的 2*p个非零样本执行带限插值。\n\n' ...
        '3. 过渡带宽度的倒数 alpha：指定为标量。alpha与滤波器的过渡带宽成反比，并且也影响阻带中无关区域的宽度。' ...
        '指定 alpha允许您指定输入信号占用的奈奎斯特区间的比例。这对于要插值的信号是有益的，因为它允许您在不影响插值的情况下增加过渡带宽，' ...
        '并且对于给定的 l和 p能获得更好的阻带衰减。如果将 alpha设为 1，则假定信号占用整个奈奎斯特区间。将 alpha设为小于 1 的值，' ...
        '允许在阻带中存在无关区域。例如，如果输入占用一半奈奎斯特区间，则可将 alpha设为 0.5。\n\n' ...
        '4. 拉格朗日多项式的阶数 n：指定为正整数标量。该 FIR 滤波器对每 l个样本中插入了 l-1个连续零值的序列执行 n 阶拉格朗日多项式插值。如果 n和 l均为偶数，则设计的滤波器不是线性相位的。\n\n' ...
        '5. 输出滤波器系数 b: 以向量形式返回。b的元素是一个 FIR 滤波器的系数。如果指定了 alpha，则假设原始信号的带限为奈奎斯特频率的 alpha倍。' ...
        'b的长度为 2*l*p-1。 对于 n 阶拉格朗日多项式插值，当 n 为偶数时，b的长度为 (n+1)*l；当 n 为奇数时，长度为 (n+1)*l-1。\n\n' ...
        '6. 请选择插值方式并设置对应参数。带限插值需要设置 p, alpha；拉格朗日插值需要设置阶数。\n\n' ...
        '7. 退出设置窗口后，设置好的参数可以在下方参数显示栏查看。\n']));
    lblEx.WordWrap = 'on';
    lblEx.Layout.Row = 1; lblEx.Layout.Column = [1 6];

    % (b) 第2行[1 3] 设计方法（只读）
    lblMethod_intfilt_Text = uilabel(gl_intfilt,'Text','设计方法:','HorizontalAlignment','left','FontWeight','bold'); lblMethod_intfilt_Text.Layout.Row = 2; lblMethod_intfilt_Text.Layout.Column = 1;
    lblMethod_intfilt = uilabel(gl_intfilt,'Text','FIRintfilt插值','HorizontalAlignment','left','FontWeight','bold'); lblMethod_intfilt.Layout.Row = 2; lblMethod_intfilt.Layout.Column = [2 3];

    % (c) 第2行[4 6] Nyq 显示
    lblNyq_Text = uilabel(gl_intfilt,'Text','Nyq (Hz):','HorizontalAlignment','left','FontWeight','bold'); lblNyq_Text.Layout.Row = 2; lblNyq_Text.Layout.Column = 4;
    lblNyq = uilabel(gl_intfilt,'Text',num2str(nyq),'HorizontalAlignment','left','FontWeight','bold'); lblNyq.Layout.Row = 2; lblNyq.Layout.Column = [5 6];

    % (d) 第3行：上采样因子 l (必填)
    edtL_Text = uilabel(gl_intfilt,'Text','上采样因子 l:','HorizontalAlignment','left','FontWeight','bold'); edtL_Text.Layout.Row = 3; edtL_Text.Layout.Column = 1;
    edtL = uieditfield(gl_intfilt,'numeric','Value',2,'Limits',[1,1e6],'RoundFractionalValues',true);
    edtL.Layout.Row = 3; edtL.Layout.Column = [2 3];

    % (e) 第4行 插值方式 单选（带限 / 拉格朗日）
    bg_Text = uilabel(gl_intfilt,'Text','插值方式:','HorizontalAlignment','left','FontWeight','bold'); bg_Text.Layout.Row = 4; bg_Text.Layout.Column = 1;
    bg = uibuttongroup(gl_intfilt,'SelectionChangedFcn',@(bg,evt) onInterpModeChanged(bg,evt));
    bg.Layout.Row = 4; bg.Layout.Column = [2 6];
    rbBand = uiradiobutton(bg,'Text','带限插值','Position',[10 10 120 20],'FontWeight','bold');
    rbLagr = uiradiobutton(bg,'Text','拉格朗日插值','Position',[140 10 120 20],'FontWeight','bold');
    % 默认带限
    bg.SelectedObject = rbBand;

    % (f) 第5行 非零样本数 p:
    edtP_Text = uilabel(gl_intfilt,'Text','非零样本数 p:','HorizontalAlignment','left','FontWeight','bold'); edtP_Text.Layout.Row = 5; edtP_Text.Layout.Column = 1;
    edtP = uieditfield(gl_intfilt,'numeric','Value',2,'Limits',[1 1e6],'RoundFractionalValues',true);
    edtP.Layout.Row = 5; edtP.Layout.Column = [2 3];

    % (g) 第5行4列 alpha:
    edtAlpha_Text = uilabel(gl_intfilt,'Text','过渡带宽度的倒数 alpha:','HorizontalAlignment','left','FontWeight','bold'); edtAlpha_Text.Layout.Row = 5; edtAlpha_Text.Layout.Column = 4;
    edtAlpha = uieditfield(gl_intfilt,'numeric','Value',1,'Limits',[0.01 1],'RoundFractionalValues',false);
    edtAlpha.Layout.Row = 5; edtAlpha.Layout.Column = [5 6];

    % (h) 第6行 Lagrange 多项式阶数 n:
    edtN_Text = uilabel(gl_intfilt,'Text','拉格朗日多项式的阶数 n:','HorizontalAlignment','left','FontWeight','bold'); edtN_Text.Layout.Row = 6; edtN_Text.Layout.Column = 1;
    edtN = uieditfield(gl_intfilt,'numeric','Value',1,'Limits',[0 500],'RoundFractionalValues',true);
    edtN.Layout.Row = 6; edtN.Layout.Column = [2 3];

    % (i) 第7行 是否补偿相位延迟 单选
    bgDelay_Text = uilabel(gl_intfilt,'Text','应用滤波器时是否补偿相位延迟:','HorizontalAlignment','left','FontWeight','bold'); bgDelay_Text.Layout.Row = 7; bgDelay_Text.Layout.Column = 1;
    bgDelay = uibuttongroup(gl_intfilt,'SelectionChangedFcn',[]); bgDelay.Layout.Row = 7; bgDelay.Layout.Column = [2 6];
    rbDelayYes = uiradiobutton(bgDelay,'Text','是','Position',[10 10 120 20],'FontWeight','bold'); rbDelayNo = uiradiobutton(bgDelay,'Text','否','Position',[140 10 120 20],'FontWeight','bold');
    bgDelay.SelectedObject = rbDelayYes;  % 默认是

    % (j) 第8行 确认按钮 (左)
    btnOk = uibutton(gl_intfilt,'push','Text','确认','ButtonPushedFcn',@(btn,evt) onConfirm());
    btnOk.Layout.Row = 8; btnOk.Layout.Column = [1 3];

    % (k) 第8行 取消按钮 (右)
    btnCancel = uibutton(gl_intfilt,'push','Text','取消','ButtonPushedFcn',@(~,~) close(dlg_intfilt));
    btnCancel.Layout.Row = 8; btnCancel.Layout.Column = [4 6];


    onInterpModeChanged(bg, struct('NewValue', bg.SelectedObject)); % 初始化一次

    % 阻塞直到 dlg_intfilt 被关闭
    uiwait(dlg_intfilt);

    % 初始：当选择 带限 插值 -> 禁用 n；当选择 Lagrange -> 禁用 p,alpha
    function onInterpModeChanged(bg,evt)
        if evt.NewValue == rbBand
            % 带限插值
            edtN.Enable = 'off';
            edtP.Enable = 'on'; edtAlpha.Enable = 'on';
            edtN_Text.Enable = 'off';
            edtP_Text.Enable = 'on';
            edtAlpha_Text.Enable = 'on';
        else
            % 拉格朗日
            edtN.Enable = 'on';
            edtP.Enable = 'off'; edtAlpha.Enable = 'off';
            edtN_Text.Enable = 'on';
            edtP_Text.Enable = 'off';
            edtAlpha_Text.Enable = 'off';
        end
    end

    % 确认回调：校验并返回 params
    function onConfirm()
        % 1) 基本校验 l
        lval = round(double(edtL.Value));
        if isempty(lval) || ~isfinite(lval) || lval <= 0
            uialert(dlg_intfilt,'上采样因子 l 必须为正整数。','参数错误');
            return;
        end

        % Prepare vars
        pval = []; aval = []; nval = []; mode = '';

        % 2) 根据模式校验具体参数
        if bg.SelectedObject == rbBand
            mode = 'bandlimited';
            % p
            ptmp = double(edtP.Value);
            if isempty(ptmp) || ~isfinite(ptmp)
                uialert(dlg_intfilt,'非零样本数 p 必须为有限数值。','参数错误'); return;
            end
            pval = round(ptmp);
            if pval <= 0
                uialert(dlg_intfilt,'非零样本数 p 必须为正整数。','参数错误'); return;
            end

            % alpha
            aval = double(edtAlpha.Value);
            if isempty(aval) || ~isfinite(aval)
                uialert(dlg_intfilt,'alpha 必须为有限数值。','参数错误'); return;
            end
            % 根据 intfilt 文档，alpha 表示占 Nyquist 的比例，逻辑上应 >0 且 <=1
            if ~(aval > 0 && aval <= 1)
                uialert(dlg_intfilt,'alpha 必须在区间 (0, 1] 内（表示信号占 Nyquist 的比例）。','参数错误'); return;
            end

            % 计算滤波器长度（bandlimited）：length = 2*l*p - 1
            filtlen = 2 * lval * pval - 1;

        else
            mode = 'lagrange';
            % n
            ntmp = double(edtN.Value);
            if isempty(ntmp) || ~isfinite(ntmp)
                uialert(dlg_intfilt,'拉格朗日多项式阶数 n 必须为有限数值。','参数错误'); return;
            end
            nval = round(ntmp);
            if nval < 0
                uialert(dlg_intfilt,'拉格朗日多项式阶数 n 必须为非负整数。','参数错误'); return;
            end

            % 计算滤波器长度（Lagrange）：
            % 若 n 为偶数， len = (n+1)*l
            % 若 n 为奇数，  len = (n+1)*l - 1
            if mod(nval,2) == 0
                filtlen = (nval + 1) * lval;
            else
                filtlen = (nval + 1) * lval - 1;
            end

            % 文档说明：若 n 和 l 均为偶数，则滤波器**不是线性相位**，需要提醒用户确认。 
            if mod(nval,2) == 0 && mod(lval,2) == 0
                choice = uiconfirm(dlg_intfilt, ...
                    ['注意：n 和 l 同为偶数，产生的滤波器**不是线性相位**，这通常不是期望的行为。' newline ...
                    '是否确认继续？'], ...
                    '相位特性警告', 'Options', {'继续','取消'}, 'DefaultOption', 2, "Icon","warning");
                if strcmp(choice,'取消'), return; end
            end
        end

        % 3) 滤波器长度安全性检测（防止 OOM / 超长计算）
        % 设定两个阈值：警告阈值 warnLen（例如 10001 taps），阻断阈值 blockLen（例如 1e6 taps）
        warnLen = 10001;   % 超过此长度给用户显式警告（可能很慢/内存大）
        blockLen = 1e6;    % 超过此长度直接阻断并要求用户修改参数

        if filtlen > blockLen
            uialert(dlg_intfilt, sprintf(['计算出的滤波器长度为 %d taps，远超安全上限（%d）。' ...
                ' 请减小 p 或 l 或 n（Lagrange）后重试。'], filtlen, blockLen), '滤波器过大',"Icon","warning");
            return;
        elseif filtlen > warnLen
            choice = uiconfirm(dlg_intfilt, ...
                sprintf(['计算出的滤波器长度为 %d taps，设计与应用可能非常慢或耗尽内存。是否继续？' ...
                '\n（建议：将 p 或 l 或 n 缩小以减少滤波器长度）'], filtlen), ...
                '大滤波器警告', 'Options', {'继续','取消'}, 'DefaultOption', 2, "Icon","warning");
            if strcmp(choice,'取消'), return; end
        end

        % 4) 最后构造 params 并关闭
        params = struct();
        params.intfilt_method = 'intfilt';
        params.intfilt_l = lval;
        params.intfilt_mode = mode;
        params.intfilt_filterLength = filtlen; % 保存计算结果，便于后续显示/调试
        if strcmp(mode,'bandlimited')
            params.intfilt_p = pval; params.intfilt_alpha = aval;
        else
            params.intfilt_n = nval;
        end
        params.intfilt_compensate = (bgDelay.SelectedObject == rbDelayYes);

             
        % 结束 uiwait 并关闭对话框
        try
            if isvalid(dlg_intfilt)
                uiresume(dlg_intfilt); 
                delete(dlg_intfilt); 
            end
        catch
            try delete(dlg_intfilt); catch; end
        end
    end
end

%% ---- gaussdesign "多带 / 高级滤波参数设置" 窗口（严格模态） ---- 
function params = openGaussdesignAdvancedWindow(parentFig, handles, S)
    % 返回 params 结构或空（当用户取消）
    params = [];
    nyq = max(1e-6, S.fs/2);

    % 严格模态窗口
    dlg_gauss = createCenteredUIFigure('Name','gaussdesign脉冲整形滤波参数设置窗口','Position',[500 200 810 700],'WindowStyle','modal');
    % 使用 uiwait模式实现严格模态阻塞
    gl_gauss = uigridlayout(dlg_gauss,[9 6]);
    gl_gauss.Padding = [10 10 10 10];
    gl_gauss.RowSpacing = 10;
    gl_gauss.ColumnSpacing = 6;
    % 行高/列宽允许自动伸缩
    gl_gauss.RowHeight =  {'fit','1x','1x','1x','1x',40,40,40,'1x'};
    gl_gauss.ColumnWidth =  {150,'1x','1x',150,'1x','1x'};

    % 第1行说明文本（跨 1..6）
    lblNote = uilabel(gl_gauss,'Text',sprintf(['gaussdesign 脉冲整形滤波参数说明（详细信息请参阅MATLAB帮助文档）：\n\n' ...
        '1. 3dB 带宽-符号时间乘积 bt：指定为正实数标量。3 dB 单边带宽的单位为赫兹，符号时间的单位为秒。bt 值越小，生成的脉冲宽度越大。' ...
        '设计折中建议：推荐值：0.3 – 0.5；常用"折中默认"是 0.35 或 0.4。0.35–0.4 在频谱与时域之间常是较稳妥的折中选择，适合多数仿真与原型开发场景。\n\n' ...
        '2. 符号数量 span：指定为正整数标量，默认为3。\n\n' ...
        '3. 每符号采样数 sps：每个符号周期的采样数（过采样因子），指定为正整数标量。\n\n' ...
        '4. 输出FIR 滤波器系数 h：高斯脉冲整形滤波器的 FIR 系数，以行向量形式返回。系数经过归一化，使得标称通带增益始终为 1。\n\n' ...
        '5. 滤波器应用：发射端滤波会使用upfirdn(x, b, sps)对数据进行上采样和滤波；接收端滤波会使用upfirdn(r, b, 1, sps)接收的信号进行滤波和下采样以进行匹配滤波；常规滤波会根据选择使用filter/filtfilt/fftfilt/my_filtfilt进行滤波，但推荐优先使用filtfilt进行滤波，在短信号或 filtfilt/fftfilt 失败时回退 filter 并提示。\n\n' ...
        '6. 发射端滤波输出长度与裁切：上采样后用 upfirdn 滤波，会产生 d 个采样点的前置延迟，通常需要把输出前 d 个样点裁切（或在发送前 pad）以保证符号对齐。这里提供"保留原长""裁切延迟"两种方式。\n\n' ...
        '7. 接收端滤波自动对齐方式：接收端（rx）使用 upfirdn(x, b, 1, sps) 做滤波+下采样时，输出到符号采样点的符号级延迟 = d/sps（可能是非整数符号延迟），若需要精确符号对齐，需注意是否为整数；若为非整数则需额外的分数延迟补偿。这里提供"自动插值""分数延迟"两种方式。\n\n' ...
        '8. 退出设置窗口后，设置好的参数可以在下方参数显示栏查看。\n']));
    lblNote.Layout.Row = 1;
    lblNote.Layout.Column = [1 6];
    lblNote.WordWrap = 'on';

    % 第2行 左：设计方法 文本；右：Nyq 显示
    % 设计方法（显示文本）
    lblMethod_gauss = uilabel(gl_gauss,'Text',sprintf('设计方法：%s', handles.ddDesignMethod.Value),'FontWeight','bold');
    lblMethod_gauss.Layout.Row = 2; lblMethod_gauss.Layout.Column = [1 3];

    % Nyq 显示
    lblNyq = uilabel(gl_gauss,'Text',sprintf('Nyq：%.1f Hz', nyq),'HorizontalAlignment','left','FontWeight','bold'); lblNyq.Layout.Row=2; lblNyq.Layout.Column = [4 6];


    % 第3行 bt 输入
    lblBT = uilabel(gl_gauss,'Text','3dB 带宽-符号时间乘积 bt:','HorizontalAlignment','left','FontWeight','bold');
    lblBT.Layout.Row = 3; lblBT.Layout.Column = 1;
    edtBT = uieditfield(gl_gauss,'numeric','Value',0.3,'Limits',[eps Inf],'LowerLimitInclusive','on');
    edtBT.Layout.Row = 3; edtBT.Layout.Column = [2 3];

    % 第4行 span 输入（默认为 3）
    lblSpan = uilabel(gl_gauss,'Text','符号数量 span:','HorizontalAlignment','left','FontWeight','bold');
    lblSpan.Layout.Row = 4; lblSpan.Layout.Column = 1;
    edtSpan = uieditfield(gl_gauss,'numeric','Value',3,'Limits',[1 1e6],'RoundFractional','on');
    edtSpan.Layout.Row = 4; edtSpan.Layout.Column = [2 3];

    % 第5行 sps 输入（默认为 2）
    lblSps = uilabel(gl_gauss,'Text','每符号采样数 sps:','HorizontalAlignment','left','FontWeight','bold');
    lblSps.Layout.Row = 5; lblSps.Layout.Column = 1;
    edtSps = uieditfield(gl_gauss,'numeric','Value',2,'Limits',[1 1e6],'RoundFractional','on');
    edtSps.Layout.Row = 5; edtSps.Layout.Column = [2 3];

    %  滤波器应用 单选（发射端/接收端/常规）
    lblApp = uilabel(gl_gauss,'Text','滤波器应用:','HorizontalAlignment','left','FontWeight','bold');
    lblApp.Layout.Row = 6; lblApp.Layout.Column = 1;
    bgApp = uibuttongroup(gl_gauss);
    bgApp.Layout.Row = 6; bgApp.Layout.Column = [2 6];
    rbTx = uiradiobutton(bgApp,'Text','发射端滤波','Position',[10 10 120 20]);
    rbRx = uiradiobutton(bgApp,'Text','接收端滤波','Position',[140 10 120 20]);
    rbGen = uiradiobutton(bgApp,'Text','常规滤波','Position',[270 10 120 20]);
    rbTx.Value = true;

    % ----------------- upfirdn 输出长度与裁切（仅在发射端滤波时可用） -----------------
    lblUpfirdn = uilabel(gl_gauss,'Text','发射端滤波输出长度与裁切:','HorizontalAlignment','left','FontWeight','bold');
    lblUpfirdn.Layout.Row = 7; lblUpfirdn.Layout.Column = 1;
    bgUpfirdn = uibuttongroup(gl_gauss,'Title','','SelectionChangedFcn',@(src,event) []);
    bgUpfirdn.Layout.Row = 7; bgUpfirdn.Layout.Column = [2 6];
    rbKeep = uiradiobutton(bgUpfirdn,'Text','保留原长','Position',[10 10 120 20]);
    rbTrim = uiradiobutton(bgUpfirdn,'Text','裁切延迟','Position',[140 10 120 20]);
    rbKeep.Value = true;

    % ----------------- 自动对齐方式（仅在接收端滤波时可用） -----------------
    lblAutoAlign = uilabel(gl_gauss,'Text','接收端滤波自动对齐方式:','HorizontalAlignment','left','FontWeight','bold');
    lblAutoAlign.Layout.Row = 8; lblAutoAlign.Layout.Column = 1;
    bgAlign = uibuttongroup(gl_gauss,'Title','','SelectionChangedFcn',@(src,event) []);
    bgAlign.Layout.Row = 8; bgAlign.Layout.Column = [2 6];
    rbAlignInterp = uiradiobutton(bgAlign,'Text','自动插值','Position',[10 10 120 20]);
    rbAlignFrac   = uiradiobutton(bgAlign,'Text','分数延迟','Position',[140 10 120 20]);
    % 默认选项（虽然通常在非启用状态），便于后面读取
    rbAlignInterp.Value = true;



    % 保留为按钮区域（确认/取消）
    % 确认按钮
    btnConfirm = uibutton(gl_gauss,'push','Text','确认', 'ButtonPushedFcn', @(~,~) onConfirm());
    btnConfirm.Layout.Row = 9; btnConfirm.Layout.Column = [1 3];
    % 取消按钮
    btnCancel = uibutton(gl_gauss,'push','Text','取消','ButtonPushedFcn', @(~,~) onCancel());
    btnCancel.Layout.Row = 9; btnCancel.Layout.Column = [4 6];

    % 当应用选择改变时，更新第7/第8行控件的启用状态
    bgApp.SelectionChangedFcn = @(bg,event) updateEnableState();

    % 初始启用状态（基于默认 rbTx.Value = true）
    updateEnableState();

    uiwait(dlg_gauss);

    function updateEnableState()
        % 如果选择接收端滤波，则启用"自动对齐方式"，否则禁用
        if rbRx.Value
            bgAlign.Enable = 'on';
            lblAutoAlign.Enable = 'on';
            % 确保至少有一个选中（可见时设默认）
            if ~(rbAlignInterp.Value || rbAlignFrac.Value)
                rbAlignInterp.Value = true;
            end
        else
            bgAlign.Enable = 'off';
            lblAutoAlign.Enable = 'off';
        end

        % 如果选择发射端滤波，则启用"upfirdn 输出长度与裁切"，否则禁用
        if rbTx.Value
            bgUpfirdn.Enable = 'on';
            lblUpfirdn.Enable = 'on';
            if ~(rbKeep.Value || rbTrim.Value)
                rbKeep.Value = true;
            end
        else
            bgUpfirdn.Enable = 'off';
            lblUpfirdn.Enable = 'off';
        end
    end

    function onConfirm()
        % 读取并严格校验（增强版）
        btVal   = edtBT.Value;
        spanVal = edtSpan.Value;
        spsVal  = edtSps.Value;

        % 强制把数值转为 double / integer（界面上已经做了 RoundFractional='on'，
        % 这里再次严格验证，保证稳定）
        btVal = double(btVal);
        spanVal = double(spanVal);
        spsVal = double(spsVal);

        % ----- 基本类型与范围校验（参照 gaussdesign 的 validateattributes） -----
        % bt: numeric scalar, nonempty, nonnan, real, positive
        if ~(isnumeric(btVal) && isscalar(btVal) && ~isnan(btVal) && isfinite(btVal) && isreal(btVal) && (btVal > 0))
            msg = 'bt 必须为正实数标量（numeric scalar, real, finite, > 0）。';
            if exist('uialert_safe','file'), uialert_safe(dlg_gauss,msg,'参数错误'); else; uialert(dlg_gauss,msg,'参数错误'); end
            return;
        end

        % span, sps: numeric scalar, positive integer
        if ~(isnumeric(spanVal) && isscalar(spanVal) && ~isnan(spanVal) && isfinite(spanVal) && isreal(spanVal) && (spanVal > 0) && (mod(spanVal,1)==0))
            msg = 'span 必须为正整数标量。';
            if exist('uialert_safe','file'), uialert_safe(dlg_gauss,msg,'参数错误'); else; uialert(dlg_gauss,msg,'参数错误'); end
            return;
        end
        if ~(isnumeric(spsVal) && isscalar(spsVal) && ~isnan(spsVal) && isfinite(spsVal) && isreal(spsVal) && (spsVal > 0) && (mod(spsVal,1)==0))
            msg = 'sps 必须为正整数标量。';
            if exist('uialert_safe','file'), uialert_safe(dlg_gauss,msg,'参数错误'); else; uialert(dlg_gauss,msg,'参数错误'); end
            return;
        end

        % ----- 合法性与安全性附加校验 -----
        % 1) 保证滤波器阶数（sps*span）为偶数（gaussdesign 要求）
        sps_span = spsVal * spanVal;
        if mod(sps_span,2) ~= 0
            msg = 'sps * span 必须为偶数（滤波器阶数必须为偶数）。';
            if exist('uialert_safe','file'), uialert_safe(dlg_gauss,msg,'参数错误'); else; uialert(dlg_gauss,msg,'参数错误'); end
            return;
        end

        % 2) 防止过大的滤波器长度导致内存 / 计算问题
        %    这里与 uieditfield 的 Limits 保持一致（界面已设 1..1e6）
        %    允许用户控制此阈值；若需要更严格可改为 1e5 或更小
        MAX_TAPS = 1e6; % 可调整
        filtLen = sps_span + 1;
        if filtLen <= 0 || filtLen > MAX_TAPS
            msg = sprintf('请求的滤波器长度为 %d taps（sps*span+1）。为避免内存/计算问题，请将其限制到 1..%d 范围内。', filtLen, MAX_TAPS);
            if exist('uialert_safe','file'), uialert_safe(dlg_gauss,msg,'参数错误',"Icon","warning"); else; uialert(dlg_gauss,msg,'参数错误'); end
            return;
        end

        % 3) 防止极端 bt 值（非常接近 0 ）或异常巨大值导致数值问题或不合预期
        %    这里给出合理警告/拒绝阈值（可根据需要放宽/收紧）
        MIN_BT = realmin * 10; % 极端接近 0 的数会导致非物理行为
        MAX_BT = 1e3;          % 非常大的 bt 也没有实际意义（可根据应用调整）
        if btVal < MIN_BT || btVal > MAX_BT
            msg = sprintf('bt 的值（%.3g）异常：建议 bt 在 (%.3g, %.0f) 范围内。请检查是否输入错误。', btVal, MIN_BT, MAX_BT);
            if exist('uialert_safe','file')
                uialert_safe(dlg_gauss,msg,'参数警告',"Icon","warning");
            else
                uialert(dlg_gauss,msg,'参数警告');
            end
            % 在此选择拒绝还是接受：为安全起见，这里拒绝继续，强制用户修正
            return;
        end

        % 4) 额外检查：sps 过小会导致采样不足（例如 sps=1 仍被允许，但用户应知）
        if spsVal < 2
            choice = uiconfirm(dlg_gauss, ...
                sprintf(['注意：sps < 2 可能导致过采样不足。是否继续？' ...
                '\n（建议：将 sps 设为 >= 2 ）']), ...
                '参数建议', 'Options', {'继续','取消'}, 'DefaultOption', 2);
            if strcmp(choice,'取消'), return; end
            
        end

        % 应用类型
        if rbTx.Value, appType = 'tx';
        elseif rbRx.Value, appType = 'rx';
        else ;appType = 'gen';
        end

        % ----- 与新增控件相关的校验与保存 -----
        % 自动对齐（仅在接收端启用时保存）
        if strcmp(appType,'rx')
            % bgAlign 已启用
            if rbAlignInterp.Value
                autoAlignMode = 'autointerp';
            elseif rbAlignFrac.Value
                autoAlignMode = 'fracdelay';
            else
                % 正常不应到达此处；再做防护
                msg = '请选择自动对齐方式（自动插值 或 分数延迟）。';
                if exist('uialert_safe','file'), uialert_safe(dlg_gauss,msg,'参数错误'); else; uialert(dlg_gauss,msg,'参数错误'); end
                return;
            end
        else
            autoAlignMode = []; % 不保存
        end

        % upfirdn 输出长度与裁切（仅在发射端启用时保存）
        if strcmp(appType,'tx')
            if rbKeep.Value
                upfirdnMode = 'keep'; % 保留原长
            elseif rbTrim.Value
                upfirdnMode = 'trim'; % 裁切延迟
            else
                msg = '请选择 upfirdn 输出长度与裁切 选项（保留原长 或 裁切延迟）。';
                if exist('uialert_safe','file'), uialert_safe(dlg_gauss,msg,'参数错误'); else; uialert(dlg_gauss,msg,'参数错误'); end
                return;
            end
        else
            upfirdnMode = []; % 不保存
        end

        % ----- 校验通过：尝试构造 params 并在 GUI 层面预先生成系数，以便尽早捕获运行时错误 -----
        params = struct();
        params.bt   = btVal;
        params.span = spanVal;
        params.sps  = spsVal;
        params.filtLen = filtLen;
        
        params.appType = appType; % 'tx'|'rx'|'gen'
        % 条件性保存新增字段（只在启用时保存）
        if ~isempty(autoAlignMode), params.autoAlignMode = autoAlignMode; end
        if ~isempty(upfirdnMode),  params.upfirdnMode = upfirdnMode; end


        % 尝试在 GUI 层面调用 gaussdesign（或局部实现）生成系数，捕获错误并提示
        % 这样可以在 GUI 阶段就发现数值/维度问题，而不是等到批量设计时报错
        try
            % 优先使用已加载的 gaussdesign（如果在搜索路径上），否则调用内置实现 gaussdesignImpl
            if exist('gaussdesign','file') == 2
                h_test = gaussdesign(btVal, spanVal, spsVal);
            else
                h_test = gaussdesignImpl(btVal, spanVal, spsVal);
            end
            % 简单检查返回值格式
            if ~(isnumeric(h_test) && isvector(h_test))
                msg = '生成的滤波器系数格式不正确（期望为数值行/列向量）。';
                if exist('uialert_safe','file'), uialert_safe(dlg_gauss,msg,'运行时错误'); else; uialert(dlg_gauss,msg,'运行时错误'); end
                return;
            end
            % 将测试得到的系数保存到 params（可供后续显示/回显）
            params.h = double(h_test(:).'); % 保持行向量
            
            L = length(double(h_test(:).'));
            % gaussdesign 保证 L = sps*span + 1，且 sps*span 为偶数 => L-1 为偶数 => d 为整数
            groupDelaySamples = (L-1)/2; % 群延迟（以采样点计），应为整数
            params.groupDelaySamples = groupDelaySamples;
         
        catch ME
            % 捕获并把可读错误信息反馈给用户
            msg = sprintf('在尝试生成高斯滤波器系数时出错：\n%s', ME.message);
            if exist('uialert_safe','file'), uialert_safe(dlg_gauss,msg,'运行时错误'); else; uialert(dlg_gauss,msg,'运行时错误'); end
            return;
        end

        % 校验全部通过，关闭窗口并返回 params
 
        % 结束 uiwait 并关闭对话框
        try
            if isvalid(dlg_gauss)
                uiresume(dlg_gauss); 
                delete(dlg_gauss); 
            end
        catch
            try delete(dlg_gauss); catch; end
        end
    end

    function onCancel()
        params = [];
        try
            close(dlg_gauss);
        catch
            delete(dlg_gauss);
        end
    end

end

%% ---- rcosdesign "多带 / 高级滤波参数设置" 窗口（严格模态） ---- 
function params = openRcosdesignAdvancedWindow(parentFig, handles, S)
    params = [];
    nyq = max(1e-6, S.fs/2);

    % 严格模态窗口
    dlg_rcos = createCenteredUIFigure('Name','rcosdesign脉冲整形滤波参数设置窗口','Position',[420 210 850 750],'WindowStyle','modal');
    gl_rcos = uigridlayout(dlg_rcos,[10,6]);
    gl_rcos.Padding = [8 8 8 8];
    gl_rcos.RowSpacing = 8; gl_rcos.ColumnSpacing = 6;
    % 行列高度/宽度可按需调整（这里使用自动 fit）
    gl_rcos.RowHeight =  {'fit','1x','1x','1x','1x',40,40,40,40,'1x'};
    gl_rcos.ColumnWidth = {150,'1x','1x',150,'1x','1x'};

    % 第1行说明文本（跨1-6）
    lblNote = uilabel(gl_rcos, 'Text', sprintf(['rcosdesign 脉冲整形滤波参数说明（详细信息请参阅MATLAB帮助文档）：\n' ...
        '1. 滚降因子 beta：指定为不大于 1 的非负实数标量值。滚降因子确定滤波器的多余的带宽。零滚降对应于矩形滤波器，单位滚降则对应于纯升余弦滤波器。β 常用区间（约 0.20–0.35）。\n\n' ...
        '2. 符号数量 span：指定为正整数标量。\n\n' ...
        '3. 每符号采样数 sps：每个符号的采样数（过采样因子），指定为正整数标量。\n\n' ...
        '4. 升余弦窗的形状 shape："sqrt" (默认) 、"normal"\n\n' ...
        '5. 输出FIR 滤波器系数 b：升余弦滤波器系数，以行向量形式返回。\n\n' ...
        '6. 滤波器应用：发射端滤波会使用upfirdn(x, b, sps)对数据进行上采样和滤波；接收端滤波会使用upfirdn(r, b, 1, sps)接收的信号进行滤波和下采样以进行匹配滤波；常规滤波会根据选择使用filter/filtfilt/fftfilt/my_filtfilt进行滤波，但推荐优先使用filtfilt进行滤波，在短信号或 filtfilt/fftfilt 失败时回退 filter 并提示。\n\n' ...
        '7. 发射端滤波输出长度与裁切：上采样后用 upfirdn 滤波，会产生 d 个采样点的前置延迟，通常需要把输出前 d 个样点裁切（或在发送前 pad）以保证符号对齐。这里提供"保留原长""裁切延迟"两种方式。\n\n' ...
        '8. 接收端滤波自动对齐方式：接收端（rx）使用 upfirdn(x, b, 1, sps) 做滤波+下采样时，输出到符号采样点的符号级延迟 = d/sps（可能是非整数符号延迟），若需要精确符号对齐，需注意是否为整数；若为非整数则需额外的分数延迟补偿。这里提供"自动插值""分数延迟"两种方式。\n\n' ...
        '9. 退出设置窗口后，设置好的参数可以在下方参数显示栏查看。\n']));
    lblNote.Layout.Row = 1; lblNote.Layout.Column = [1 6];
    lblNote.WordWrap = 'on';

    % 第2行 左：设计方法 文本；右：Nyq 显示
    % 设计方法（显示文本）
    lblMethod_rcos = uilabel(gl_rcos,'Text',sprintf('设计方法：%s', handles.ddDesignMethod.Value),'FontWeight','bold');
    lblMethod_rcos.Layout.Row = 2; lblMethod_rcos.Layout.Column = [1 3];

    % Nyq 显示
    lblNyq = uilabel(gl_rcos,'Text',sprintf('Nyq：%.1f Hz', nyq),'HorizontalAlignment','left','FontWeight','bold'); lblNyq.Layout.Row=2; lblNyq.Layout.Column = [4 6];


    % 第3行 滚降因子 beta
    lblBeta = uilabel(gl_rcos,'Text','滚降因子 beta:','HorizontalAlignment','left','FontWeight','bold');
    lblBeta.Layout.Row = 3; lblBeta.Layout.Column = 1;
    edtBeta = uieditfield(gl_rcos,'numeric','Value',0.25,'Limits',[0 1]);
    edtBeta.Layout.Row = 3; edtBeta.Layout.Column = [2 3];

    % 第4行 符号数量 span（默认6）
    lblSpan = uilabel(gl_rcos,'Text','符号数量 span:','HorizontalAlignment','left','FontWeight','bold');
    lblSpan.Layout.Row = 4; lblSpan.Layout.Column = 1;
    edtSpan = uieditfield(gl_rcos,'numeric','Value',6,'Limits',[1 1024],'RoundFractionalValues','on');
    edtSpan.Layout.Row = 4; edtSpan.Layout.Column = [2 3];

    % 第5行 sps（默认4）
    lblSps = uilabel(gl_rcos,'Text','每符号采样数 sps:','HorizontalAlignment','left','FontWeight','bold');
    lblSps.Layout.Row = 5; lblSps.Layout.Column = 1;
    edtSps = uieditfield(gl_rcos,'numeric','Value',4,'Limits',[1 1024],'RoundFractionalValues','on');
    edtSps.Layout.Row = 5; edtSps.Layout.Column = [2 3];

    % 第6行 升余弦窗形状 单选（平方根/普通）
    lblShape = uilabel(gl_rcos,'Text','升余弦窗的形状:','HorizontalAlignment','left','FontWeight','bold');
    lblShape.Layout.Row = 6; lblShape.Layout.Column = 1;
    bgShape = uibuttongroup(gl_rcos);
    bgShape.Layout.Row = 6; bgShape.Layout.Column = [2 3];
    rbSqrt = uiradiobutton(bgShape,'Text','平方根','Position',[10 10 120 20]);
    rbNormal = uiradiobutton(bgShape,'Text','普通','Position',[140 10 120 20]);
    rbSqrt.Value = true; % 默认平方根

    % 第7行 滤波器应用 单选（发射端/接收端/常规）
    lblApp = uilabel(gl_rcos,'Text','滤波器应用:','HorizontalAlignment','left','FontWeight','bold');
    lblApp.Layout.Row = 7; lblApp.Layout.Column = 1;
    bgApp = uibuttongroup(gl_rcos);
    bgApp.Layout.Row = 7; bgApp.Layout.Column = [2 6];
    rbTx = uiradiobutton(bgApp,'Text','发射端滤波','Position',[10 10 120 20]);
    rbRx = uiradiobutton(bgApp,'Text','接收端滤波','Position',[140 10 120 20]);
    rbGen = uiradiobutton(bgApp,'Text','常规滤波','Position',[270 10 120 20]);
    rbTx.Value = true;

    % ----------------- upfirdn 输出长度与裁切（仅在发射端滤波时可用） -----------------
    lblUpfirdn = uilabel(gl_rcos,'Text','发射端滤波输出长度与裁切:','HorizontalAlignment','left','FontWeight','bold');
    lblUpfirdn.Layout.Row = 8; lblUpfirdn.Layout.Column = 1;
    bgUpfirdn = uibuttongroup(gl_rcos,'Title','','SelectionChangedFcn',@(src,event) []);
    bgUpfirdn.Layout.Row = 8; bgUpfirdn.Layout.Column = [2 6];
    rbKeep = uiradiobutton(bgUpfirdn,'Text','保留原长','Position',[10 10 120 20]);
    rbTrim = uiradiobutton(bgUpfirdn,'Text','裁切延迟','Position',[140 10 120 20]);
    rbKeep.Value = true;

    % ----------------- 自动对齐方式（仅在接收端滤波时可用） -----------------
    lblAutoAlign = uilabel(gl_rcos,'Text','接收端滤波自动对齐方式:','HorizontalAlignment','left','FontWeight','bold');
    lblAutoAlign.Layout.Row = 9; lblAutoAlign.Layout.Column = 1;
    bgAlign = uibuttongroup(gl_rcos,'Title','','SelectionChangedFcn',@(src,event) []);
    bgAlign.Layout.Row = 9; bgAlign.Layout.Column = [2 6];
    rbAlignInterp = uiradiobutton(bgAlign,'Text','自动插值','Position',[10 10 120 20]);
    rbAlignFrac   = uiradiobutton(bgAlign,'Text','分数延迟','Position',[140 10 120 20]);
    % 默认选项（虽然通常在非启用状态），便于后面读取
    rbAlignInterp.Value = true;

    % 确认/取消按钮
    btnOK = uibutton(gl_rcos,'push','Text','确认','ButtonPushedFcn',@onConfirm);
    btnOK.Layout.Row = 10; btnOK.Layout.Column = [1 3];
    btnCancel = uibutton(gl_rcos,'push','Text','取消','ButtonPushedFcn',@onCancel);
    btnCancel.Layout.Row = 10; btnCancel.Layout.Column = [4 6];

    % 当应用选择改变时，更新第7/第8行控件的启用状态
    bgApp.SelectionChangedFcn = @(bg,event) updateEnableState();

    % 初始启用状态（基于默认 rbTx.Value = true）
    updateEnableState();

    uiwait(dlg_rcos); % 阻塞直到窗口关闭

    function updateEnableState()
        % 如果选择接收端滤波，则启用"自动对齐方式"，否则禁用
        if rbRx.Value
            bgAlign.Enable = 'on';
            lblAutoAlign.Enable = 'on';
            % 确保至少有一个选中（可见时设默认）
            if ~(rbAlignInterp.Value || rbAlignFrac.Value)
                rbAlignInterp.Value = true;
            end
        else
            bgAlign.Enable = 'off';
            lblAutoAlign.Enable = 'off';
        end

        % 如果选择发射端滤波，则启用"upfirdn 输出长度与裁切"，否则禁用
        if rbTx.Value
            bgUpfirdn.Enable = 'on';
            lblUpfirdn.Enable = 'on';
            if ~(rbKeep.Value || rbTrim.Value)
                rbKeep.Value = true;
            end
        else
            bgUpfirdn.Enable = 'off';
            lblUpfirdn.Enable = 'off';
        end
    end

    function onConfirm(~,~)
        % 读取值（保留原有读取）
        betaVal = double(edtBeta.Value);
        spanVal = double(edtSpan.Value);
        spsVal  = double(edtSps.Value);

        % --------- 基础数值校验（范围 / 有穷 / 非 NaN） ---------
        if ~isfinite(betaVal) || isnan(betaVal)
            uialert(dlg_rcos,'滚降因子 beta 必须为有限数。','参数错误'); 
            return;
        end
        if betaVal < 0 || betaVal > 1
            uialert(dlg_rcos,'滚降因子 beta 必须在 [0,1]。','参数错误'); 
            return;
        end

        if ~isfinite(spanVal) || isnan(spanVal)
            uialert(dlg_rcos,'符号数量 span 必须为有限数。','参数错误'); 
            return;
        end
        if ~isfinite(spsVal) || isnan(spsVal)
            uialert(dlg_rcos,'每符号采样数 sps 必须为有限数。','参数错误'); 
            return;
        end

        % 强制为整数（UI 已经设置 RoundFractionalValues，但在此再严格检查）
        spanVal = round(spanVal);
        spsVal  = round(spsVal);

        if spanVal <= 0
            uialert(dlg_rcos,'符号数量 span 必须为正整数。','参数错误'); 
            return;
        end
        if spsVal <= 0
            uialert(dlg_rcos,'每符号采样数 sps 必须为正整数。','参数错误'); 
            return;
        end

        % 限制单个参数不要太大（防止意外分配或长时间计算）
        % 这里的阈值可以按你的应用场景调整（提示：若你有集群或更大内存可放宽）
        MAX_SINGLE = 1e5;    % 单个参数上限（保守提示）
        if spanVal > MAX_SINGLE || spsVal > MAX_SINGLE
            uialert(dlg_rcos,sprintf('参数过大（span=%d, sps=%d）。这可能导致内存或长时间计算问题。请减小参数。', ...
                spanVal, spsVal),'性能/资源风险',"Icon","warning");
            return;
        end

        % --------- 复合校验：滤波器阶数（必须为整数且为偶数） ---------
        filterOrder = spsVal * spanVal;
        if ~isfinite(filterOrder) || isnan(filterOrder)
            uialert(dlg_rcos,'计算得到的滤波器阶数无效。请检查 span 与 sps。','参数错误'); 
            return;
        end

        % 检查是不是整数（数值误差容忍）
        if abs(filterOrder - round(filterOrder)) > 1e-9
            uialert(dlg_rcos,'滤波器阶数 sps*span 必须为整数。请检查输入。','参数错误'); 
            return;
        end
        filterOrder = round(filterOrder);

        % 官方约束：必须为偶数（rcosdesign 要求 filterOrder 为偶数）
        if mod(filterOrder,2) ~= 0
            uialert(dlg_rcos,'滤波器阶数 sps*span 必须为偶数。请调整参数。','参数错误'); 
            return;
        end

        % 二次资源风险检查：最终 filter length = filterOrder + 1
        finalLen = filterOrder + 1;
        MAX_TAPS = 5e5; % 总 taps 上限（可按需调整）
        if finalLen > MAX_TAPS
            uialert(dlg_rcos, sprintf('滤波器系数向量长度（%d）过大，可能导致内存不足或长时间计算。请减小 span 或 sps。', finalLen), '性能/资源风险',"Icon","warning");
            return;
        end

        % shape
        if rbSqrt.Value, shapeStr = 'sqrt'; else; shapeStr = 'normal'; end

        % 应用类型
        if rbTx.Value, appType = 'tx';
        elseif rbRx.Value, appType = 'rx';
        else ;appType = 'gen';
        end

        % ----- 与新增控件相关的校验与保存 -----
        % 自动对齐（仅在接收端启用时保存）
        if strcmp(appType,'rx')
            % bgAlign 已启用
            if rbAlignInterp.Value
                autoAlignMode = 'autointerp';
            elseif rbAlignFrac.Value
                autoAlignMode = 'fracdelay';
            else
                % 正常不应到达此处；再做防护
                msg = '请选择自动对齐方式（自动插值 或 分数延迟）。';
                if exist('uialert_safe','file'), uialert_safe(dlg_rcos,msg,'参数错误'); else; uialert(dlg_rcos,msg,'参数错误'); end
                return;
            end
        else
            autoAlignMode = []; % 不保存
        end

        % upfirdn 输出长度与裁切（仅在发射端启用时保存）
        if strcmp(appType,'tx')
            if rbKeep.Value
                upfirdnMode = 'keep'; % 保留原长
            elseif rbTrim.Value
                upfirdnMode = 'trim'; % 裁切延迟
            else
                msg = '请选择 upfirdn 输出长度与裁切 选项（保留原长 或 裁切延迟）。';
                if exist('uialert_safe','file'), uialert_safe(dlg_rcos,msg,'参数错误'); else; uialert(dlg_rcos,msg,'参数错误'); end
                return;
            end
        else
            upfirdnMode = []; % 不保存
        end

        % 生成测试系数（检测是否能正确生成）
        try
            htest = rcosdesign(betaVal, spanVal, spsVal, shapeStr);
            if ~(isnumeric(htest) && isvector(htest))
                uialert(dlg_rcos,'生成的滤波器系数格式不正确（期望数值向量）。','运行时错误'); 
                return;
            end
        catch ME
            uialert(dlg_rcos,sprintf('生成滤波器系数失败：%s', ME.message),'运行时错误'); 
            return;
        end

        % 构造 params 并返回（保留原来行为）
        params = struct();
        params.beta = betaVal;
        params.span = spanVal;
        params.sps  = spsVal;
        params.shape = shapeStr;
        params.appType = appType; % 'tx'|'rx'|'gen'
        params.filtLen = spanVal*spsVal + 1;
        params.h = double(htest(:).');
        % 条件性保存新增字段（只在启用时保存）
        if ~isempty(autoAlignMode), params.autoAlignMode = autoAlignMode; end
        if ~isempty(upfirdnMode),  params.upfirdnMode = upfirdnMode; end


        L = length(double(htest(:).'));
        % gaussdesign 保证 L = sps*span + 1，且 sps*span 为偶数 => L-1 为偶数 => d 为整数
        groupDelaySamples = (L-1)/2; % 群延迟（以采样点计），应为整数
        params.groupDelaySamples = groupDelaySamples;

        % 结束 uiwait 并关闭对话框
        try
            if isvalid(dlg_rcos)
                uiresume(dlg_rcos); 
                delete(dlg_rcos); 
            end
        catch
            try delete(dlg_rcos); catch; end
        end
    end

    function onCancel(~,~)
        params = [];
        try close(dlg_rcos); catch; delete(dlg_rcos); end
    end

end

%% ---- Savitzky-Golay "多带 / 高级滤波参数设置" 窗口（严格模态） ---- 
function params = openSgolayAdvancedWindow(parentFig, handles, S)
    params = [];
    nyq = max(1e-6, S.fs/2);

    % 严格模态窗口 & 指定大小
    dlg_sg = createCenteredUIFigure('Name','Savitzky-Golay滤波参数设置窗口','Position',[450 230 750 700], ...
                      'WindowStyle','modal');
    gl_sgolay = uigridlayout(dlg_sg,[9,6]);
    gl_sgolay.RowHeight =  {'fit','1x','1x',40,'1x','1x',40,'1x','1x'};
    gl_sgolay.ColumnWidth = {'fit','1x','1x','fit','1x','1x'};
    gl_sgolay.Padding = [8 8 8 8];
    gl_sgolay.RowSpacing = 6;
    gl_sgolay.ColumnSpacing = 6;

    % (a) 说明文本
    lblEx = uilabel(gl_sgolay,'Text', sprintf(['Savitzky-Golay 参数设置说明（详细信息请参阅MATLAB帮助文档）：\n\n' ...
        '1. 多项式阶数 m：指定为非负整数。m的值必须小于 fl。如果 m = fl – 1，则设计的滤波器不产生平滑效果。\n\n' ...
        '2. 帧长度 fl：指定为正奇数。fl的值必须大于 m。\n\n' ...
        '3. （可选）加权向量 w：指定为实正向量；默认为ones(fl,1)。加权向量的长度与 fl相同，用于执行最小二乘最小化。\n\n' ...
        '4. 加权向量 w 支持自定义加权向量：可以输入和 帧长度fl 长度相同的数值向量（如 [1, 1, 1, 1...]，长度 = length(fl)）或表达式（如 hamming(fl)、chebwin(fl,10)）。加权向量 w 同时提供了一些预置的加权向量表达式，可以选择期望的加权向量表达式。\n\n' ...
        '5. 输出的时变 FIR 滤波器系数 b：指定为 fl行 × fl列的矩阵。在平滑滤波器实现中（例如 sgolayfilt），最后的 (fl-1)/2行（每一行都是一个 FIR 滤波器）' ...
        '应用于信号的启动瞬态阶段，而开头的 (fl-1)/2行应用于信号的结束瞬态阶段。中心行应用于信号的稳态部分。\n\n' ...
        '6. 输出微分滤波器矩阵 g：指定为一个矩阵。g的每一列都是一个阶数为 p-1的微分滤波器，其中 p是列索引。给定一个长度为 fl的信号 x，' ...
        '您可以使用公式 xp((fl+1)/2) = (factorial(p)) * g(:, p+1)'' * x来估计其中间值的第 p阶导数 xp。\n\n' ...
        '7. 滤波器应用：可选择 平滑滤波器 或 微分滤波器；微分滤波器需指定微分阶数 Diff_N。\n\n' ...
        '8. 短信号处理：用于"平滑滤波器"时信号长度小于fl的处理，有两种处理方式选择：端点镜像填充，局部最小二乘拟合。\n\n' ...
        '9. 输入"加权向量 w" 数值向量时，需要加方括号[]，使用半角逗号或空格分隔各元素，如 [1, 1, 1, 1...]，长度 = length(fl)。\n\n' ...
        '10. 退出设置窗口后，设置好的参数可以在下方参数显示栏查看\n']));
    lblEx.Layout.Row = 1; lblEx.Layout.Column = [1 6];
    lblEx.WordWrap = 'on';

    % (b)  设计方法（显示文本）
    lblMethod_sgolay = uilabel(gl_sgolay,'Text',sprintf('设计方法：%s', handles.ddDesignMethod.Value),'FontWeight','bold');
    lblMethod_sgolay.Layout.Row = 2; lblMethod_sgolay.Layout.Column = [1 3];

    % (c)  Nyq 显示
    lblNyq = uilabel(gl_sgolay,'Text',sprintf('Nyq：%.1f Hz', nyq),'HorizontalAlignment','left','FontWeight','bold'); lblNyq.Layout.Row=2; lblNyq.Layout.Column = [4 6];


    % (d) 多项式阶数 m
    edtM_Text = uilabel(gl_sgolay,'Text','多项式阶数 m:','HorizontalAlignment','left','FontWeight','bold'); edtM_Text.Layout.Row=3; edtM_Text.Layout.Column = 1;
    edtM = uieditfield(gl_sgolay,'numeric','Value',4,'Limits',[0,100],'RoundFractionalValues',true);
    edtM.Layout.Row = 3; edtM.Layout.Column = [2 3];

    % (e) 帧长度 fl
    edtFL_Text = uilabel(gl_sgolay,'Text','帧长度 fl:','HorizontalAlignment','left','FontWeight','bold'); edtFL_Text.Layout.Row=3; edtFL_Text.Layout.Column = 4;
    edtFL = uieditfield(gl_sgolay,'numeric','Value',21,'Limits',[3,9999],'RoundFractionalValues',true);
    edtFL.Layout.Row = 3; edtFL.Layout.Column = [5 6];

    % (f) 权重复选（位于第4行第1列）
    cbW = uicheckbox(gl_sgolay,'Text','加权向量 w:','Value',false,'FontWeight','bold');
    cbW.Layout.Row = 4; cbW.Layout.Column = 1;
    % 当勾选权重复选框时启用/禁用单选组；并设置默认模式为自定义（便于用户编辑）
    cbW.ValueChangedFcn = @(s,e) onWeightCheckboxChanged(s.Value);

    % (f.1) 单选按钮组：自定义 / 预置（默认禁用，只有当 cbW 被勾选时可用）
    bgWMode = uibuttongroup(gl_sgolay,'SelectionChangedFcn',@onWModeChanged);
    bgWMode.Layout.Row = 4; bgWMode.Layout.Column = [2 6]; % 占据两列（视觉合并）
    % 在 buttongroup 内放两个单选按钮（互斥）
    rbWCustom = uiradiobutton(bgWMode,'Text','自定义加权向量','Position',[10 10 120 20],'FontWeight','bold');
    rbWPreset = uiradiobutton(bgWMode,'Text','使用预置加权向量','Position',[295 10 120 20],'FontWeight','bold');
    % 初始禁用整个按钮组（由 cbW 控制）
    bgWMode.Enable = 'off';

    % (f.2) 自定义加权向量输入（文本框）
    edtW = uieditfield(gl_sgolay,'text','Value',''); % 用户输入数值列表或表达式（如 hamming(fl)）
    edtW.Layout.Row = 5; edtW.Layout.Column = [2 3];
    edtW.Enable = 'off';
    edtW.Placeholder = '例：chebwin(fl,10)';

    % (f.3) 预置加权向量下拉（仅当选择预置时启用）
    % 扩展更多预置：ones, hamming, hann, blackman, rectwin, bartlett
    ddPreset = uidropdown(gl_sgolay);
    ddPreset.Layout.Row = 5; ddPreset.Layout.Column = [4 6];
    % 把 ddPreset 的 items 扩展为包含上面支持的预置名（覆盖原定义或确保一致）
    ddPreset.Items = {'ones','hamming','hann','blackman','rectwin','bartlett','chebwin','tukey','kaiser','gauss'};
    ddPreset.Value = 'ones';
    ddPreset.Enable = 'off';
    ddPreset.ValueChangedFcn = @onPresetChanged;


    % ddPreset 已定义，下面创建最多 3 个参数的 label + numeric field + dropdown（可选）
    % 我们创建三组（paramLbl1..3, numParam1..3, choiceParam1..3），初始均不可见
    paramLbl1 = uilabel(gl_sgolay,'Text','','HorizontalAlignment','left'); paramLbl1.Visible='off';
    paramLbl1.Layout.Row = 6; paramLbl1.Layout.Column = 1;
    numParam1 = uieditfield(gl_sgolay,'numeric','Visible','off'); numParam1.Layout.Row=6; numParam1.Layout.Column = 2;
    choiceParam1 = uidropdown(gl_sgolay,'Items',{},'Visible','off'); choiceParam1.Layout.Row=6; choiceParam1.Layout.Column = 2;

    paramLbl2 = uilabel(gl_sgolay,'Text','','HorizontalAlignment','left'); paramLbl2.Visible='off';
    paramLbl2.Layout.Row = 6; paramLbl2.Layout.Column = 3;
    numParam2 = uieditfield(gl_sgolay,'numeric','Visible','off'); numParam2.Layout.Row=6; numParam2.Layout.Column = 4;
    choiceParam2 = uidropdown(gl_sgolay,'Items',{},'Visible','off'); choiceParam2.Layout.Row=6; choiceParam2.Layout.Column = 4;

    paramLbl3 = uilabel(gl_sgolay,'Text','','HorizontalAlignment','left'); paramLbl3.Visible='off';
    paramLbl3.Layout.Row = 6; paramLbl3.Layout.Column = 5;
    numParam3 = uieditfield(gl_sgolay,'numeric','Visible','off'); numParam3.Layout.Row=6; numParam3.Layout.Column = 6;
    choiceParam3 = uidropdown(gl_sgolay,'Items',{},'Visible','off'); choiceParam3.Layout.Row=6; choiceParam3.Layout.Column = 6;

    % 为预置窗口函数建立元数据（name / 参数个数 / 参数配置）
    % params{i} = struct('name','r','type','numeric'/'choice','default',val, 'choices',{})
    presetMeta = struct( ...
        'ones',    struct('nparams',0,'params',{{}}), ...
        'hamming', struct('nparams',0,'params',{{}}), ...
        'hann',    struct('nparams',0,'params',{{}}), ...
        'blackman',struct('nparams',0,'params',{{}}), ...
        'rectwin', struct('nparams',0,'params',{{}}), ...
        'bartlett',struct('nparams',0,'params',{{}}), ...
        'chebwin', struct('nparams',1,'params',{{struct('name','r (衰减 dB)','symbol','r','type','numeric','default',60)}}), ...
        'tukey',   struct('nparams',1,'params',{{struct('name','r (形状 0-1)','symbol','r','type','numeric','default',0.5)}}), ...
        'kaiser',  struct('nparams',1,'params',{{struct('name','beta','symbol','beta','type','numeric','default',3.0)}}), ...
        'gauss',   struct('nparams',1,'params',{{struct('name','alpha','symbol','alpha','type','numeric','default',2.5)}}) ...
    );




    % (g) 滤波器应用 单选按钮组（平滑 / 微分）
    bgApply_Text = uilabel(gl_sgolay,'Text','滤波器应用:','HorizontalAlignment','left','FontWeight','bold'); bgApply_Text.Layout.Row = 7; bgApply_Text.Layout.Column = 1;
    bgApply = uibuttongroup(gl_sgolay,'SelectionChangedFcn',@onApplySelChanged);
    bgApply.Layout.Row = 7; bgApply.Layout.Column = [2 3];
    rbSmooth = uiradiobutton(bgApply,'Text','平滑滤波器','Position',[10 10 120 20],'FontWeight','bold');
    rbDiff   = uiradiobutton(bgApply,'Text','微分滤波器','Position',[140 10 120 20],'FontWeight','bold');
    % 默认平滑
    bgApply.SelectedObject = rbSmooth;

    % (h)  微分阶数 diff_N
    edtDiffN_Text = uilabel(gl_sgolay,'Text','微分阶数 diff_N:','HorizontalAlignment','left','FontWeight','bold'); edtDiffN_Text.Layout.Row = 8; edtDiffN_Text.Layout.Column = 4;
    edtDiffN = uieditfield(gl_sgolay,'numeric','Value',1,'Limits',[0,10],'RoundFractionalValues',true);
    edtDiffN.Layout.Row = 8; edtDiffN.Layout.Column = [5 6];
    % 默认平滑 -> 禁用 diff_N
    edtDiffN.Enable = 'off';
    edtDiffN_Text.Enable = 'off';

    % (新增)： 短信号处理 标签 与 下拉
    lblShortText = uilabel(gl_sgolay,'Text','短信号处理:','HorizontalAlignment','left','FontWeight','bold'); lblShortText.Layout.Row = 8; lblShortText.Layout.Column = 1;
    ddShortMethod = uidropdown(gl_sgolay,'Items',{'端点镜像填充','局部最小二乘拟合'},'Value','端点镜像填充');
    ddShortMethod.Layout.Row = 8; ddShortMethod.Layout.Column = [2 3];

    % (i)(j)  确认 / 取消
    btnConfirm = uibutton(gl_sgolay,'push','Text','确认','ButtonPushedFcn',@onConfirm);
    btnConfirm.Layout.Row = 9; btnConfirm.Layout.Column = [1 3];
    btnCancel = uibutton(gl_sgolay,'push','Text','取消','ButtonPushedFcn',@(s,e) close(dlg_sg));
    btnCancel.Layout.Row = 9; btnCancel.Layout.Column = [4 6];

    % 阻塞直到窗口关闭（严格模态）
    uiwait(dlg_sg);

    % ----------------- 交互回调实现 -----------------
    function onWeightCheckboxChanged(flag)
        % cbW 勾选控制：当勾选才允许选择自定义/预置模式
        if flag
            bgWMode.Enable = 'on';
            % 默认选自定义（便于直接输入）
            bgWMode.SelectedObject = rbWCustom;
            edtW.Enable = 'on';
            ddPreset.Enable = 'off';
        else
            bgWMode.Enable = 'off';
            % 禁用输入与下拉
            edtW.Enable = 'off';
            ddPreset.Enable = 'off';
        end
    end

    function onWModeChanged(~,~)
        % 单选切换：控制 edtW 与 ddPreset 的启用状态（仅当 cbW=true 且 bgWMode.enable='on' 时有效）
        if strcmp(bgWMode.Enable,'off')
            % 若按钮组被禁用，确保输入都禁用
            edtW.Enable = 'off';
            ddPreset.Enable = 'off';
            return;
        end
        if bgWMode.SelectedObject == rbWCustom
            edtW.Enable = 'on';
            ddPreset.Enable = 'off';
        else
            edtW.Enable = 'off';
            ddPreset.Enable = 'on';
        end
    end

    function onApplySelChanged(~,~)
        if bgApply.SelectedObject == rbSmooth
            ddShortMethod.Enable = 'on';
            lblShortText.Enable = 'on';
            edtDiffN.Enable = 'off';
            edtDiffN_Text.Enable = 'off';

        else
            ddShortMethod.Enable = 'off';
            lblShortText.Enable = 'off';
            edtDiffN.Enable = 'on';
            edtDiffN_Text.Enable = 'on';
        end
    end

    % 小辅助：优先调用 uialert_safe（若存在），否则回退到 uialert
    function showAlert(parent, msg, titleStr)
        if exist('uialert_safe','file') == 2
            uialert_safe(parent, msg, titleStr);
        else
            uialert(parent, msg, titleStr);
        end
    end

    % 回调：当用户切换预置时显示/隐藏对应的参数输入项并放到用户指定的位置
    function onPresetChanged(src,~)
        sel = src.Value;
        % 隐藏所有先（清理）
        paramLbl1.Visible='off'; numParam1.Visible='off'; choiceParam1.Visible='off';
        paramLbl2.Visible='off'; numParam2.Visible='off'; choiceParam2.Visible='off';
        paramLbl3.Visible='off'; numParam3.Visible='off'; choiceParam3.Visible='off';

        % 默认不展示任何参数
        meta = [];
        if isfield(presetMeta, sel)
            meta = presetMeta.(sel);
        end
        if isempty(meta) || meta.nparams == 0
            return;
        end

        % 根据用户指定的布局规则把参数放到网格的不同列
        nparams = meta.nparams;
        paramsSpec = meta.params;

        if nparams == 1
            % 用户要求：第6行4列显示标签，第6行[5 6]为输入框
            p = paramsSpec{1};
            paramLbl1.Text = sprintf('%s (%s):', p.name, p.symbol);
            paramLbl1.Layout.Row = 6; paramLbl1.Layout.Column = 4;
            if strcmp(p.type,'numeric')
                numParam1.Value = p.default;
                numParam1.Visible = 'on';
                numParam1.Layout.Row = 6; numParam1.Layout.Column = [5 6];
                choiceParam1.Visible = 'off';
            else
                choiceParam1.Items = p.choices;
                choiceParam1.Value = p.default;
                choiceParam1.Visible = 'on';
                choiceParam1.Layout.Row = 6; choiceParam1.Layout.Column = [5 6];
                numParam1.Visible = 'off';
            end
            paramLbl1.Visible = 'on';
        elseif nparams == 2
            % 用户要求：(1) 参数1 在第6行1列标签, 第6行[2 3] 为输入
            % (2) 参数2 在第6行4列标签, 第6行[5 6] 为输入
            p1 = paramsSpec{1}; p2 = paramsSpec{2};
            % param1
            paramLbl1.Text = sprintf('%s (%s):', p1.name, p1.symbol);
            paramLbl1.Layout.Row = 6; paramLbl1.Layout.Column = 1; paramLbl1.Visible = 'on';
            if strcmp(p1.type,'numeric')
                numParam1.Value = p1.default; numParam1.Layout.Row=6; numParam1.Layout.Column=[2 3]; numParam1.Visible='on'; choiceParam1.Visible='off';
            else
                choiceParam1.Items = p1.choices; choiceParam1.Value=p1.default; choiceParam1.Layout.Row=6; choiceParam1.Layout.Column=[2 3]; choiceParam1.Visible='on'; numParam1.Visible='off';
            end
            % param2
            paramLbl2.Text = sprintf('%s (%s):', p2.name, p2.symbol);
            paramLbl2.Layout.Row = 6; paramLbl2.Layout.Column = 4; paramLbl2.Visible = 'on';
            if strcmp(p2.type,'numeric')
                numParam2.Value = p2.default; numParam2.Layout.Row=6; numParam2.Layout.Column=[5 6]; numParam2.Visible='on'; choiceParam2.Visible='off';
            else
                choiceParam2.Items = p2.choices; choiceParam2.Value=p2.default; choiceParam2.Layout.Row=6; choiceParam2.Layout.Column=[5 6]; choiceParam2.Visible='on'; numParam2.Visible='off';
            end
        elseif nparams == 3
            % 用户要求：(1) 参数1 label col1, 输入 col2
            % (2) 参数2 label col3, 输入 col4
            % (3) 参数3 label col5, 输入 col6
            p1 = paramsSpec{1}; p2 = paramsSpec{2}; p3 = paramsSpec{3};
            % p1
            paramLbl1.Text = sprintf('%s (%s):', p1.name, p1.symbol);
            paramLbl1.Layout.Row=6; paramLbl1.Layout.Column=1; paramLbl1.Visible='on';
            if strcmp(p1.type,'numeric')
                numParam1.Value=p1.default; numParam1.Layout.Row=6; numParam1.Layout.Column=2; numParam1.Visible='on'; choiceParam1.Visible='off';
            else
                choiceParam1.Items=p1.choices; choiceParam1.Value=p1.default; choiceParam1.Layout.Row=6; choiceParam1.Layout.Column=2; choiceParam1.Visible='on'; numParam1.Visible='off';
            end
            % p2
            paramLbl2.Text = sprintf('%s (%s):', p2.name, p2.symbol);
            paramLbl2.Layout.Row=6; paramLbl2.Layout.Column=3; paramLbl2.Visible='on';
            if strcmp(p2.type,'numeric')
                numParam2.Value=p2.default; numParam2.Layout.Row=6; numParam2.Layout.Column=4; numParam2.Visible='on'; choiceParam2.Visible='off';
            else
                choiceParam2.Items=p2.choices; choiceParam2.Value=p2.default; choiceParam2.Layout.Row=6; choiceParam2.Layout.Column=4; choiceParam2.Visible='on'; numParam2.Visible='off';
            end
            % p3
            paramLbl3.Text = sprintf('%s (%s):', p3.name, p3.symbol);
            paramLbl3.Layout.Row=6; paramLbl3.Layout.Column=5; paramLbl3.Visible='on';
            if strcmp(p3.type,'numeric')
                numParam3.Value=p3.default; numParam3.Layout.Row=6; numParam3.Layout.Column=6; numParam3.Visible='on'; choiceParam3.Visible='off';
            else
                choiceParam3.Items=p3.choices; choiceParam3.Value=p3.default; choiceParam3.Layout.Row=6; choiceParam3.Layout.Column=6; choiceParam3.Visible='on'; numParam3.Visible='off';
            end
        end
    end

    % ----------------- 确认回调：校验并返回 params（含加权向量新逻辑） -----------------
    function onConfirm(~,~)
        try
            % 基本读取
            mVal = round(double(edtM.Value));
            flVal = round(double(edtFL.Value));

            % 基本校验（与之前保持一致）
            if ~isfinite(mVal) || mVal < 0
                showAlert(dlg_sg,'多项式阶数 m 必须为非负整数。','参数错误');
                return;
            end
            if ~isfinite(flVal) || flVal < 3
                showAlert(dlg_sg,'帧长度 fl 必须为大于等于 3 的正整数。','参数错误');
                return;
            end
            if mod(flVal,2) == 0
                showAlert(dlg_sg,'帧长度 fl 必须是奇数。','参数错误');
                return;
            end
            if flVal <= mVal
                showAlert(dlg_sg,'帧长度 fl 必须大于 多项式阶数 m。','参数错误');
                return;
            end

            % m = fl-1 情形：弹出确认（允许继续或取消）
            if mVal == flVal - 1
                choice = uiconfirm(dlg_sg, ...
                    sprintf('注意：当 m = fl - 1 时，设计得到的 Savitzky-Golay 系数不会产生平滑效果（相当于逐点插值/拟合）。是否继续？' ), ...
                    '参数警告', 'Options', {'继续','取消'}, 'DefaultOption', 2, "Icon","warning");
                if strcmp(choice,'取消'), return; end
            end

            % ----- 权重相关校验：仅当 cbW 被勾选时才校验 -----
            useW = false;
            Wvec = [];
            w_preset_choice = ''; % 若使用预置记录其字符串
            if cbW.Value
                % 按当前单选模式校验：自定义 or 预置
                if bgWMode.SelectedObject == rbWCustom
                    % 自定义：解析 edtW 的表达式或数值列表
                    wstr = strtrim(edtW.Value);

                    try

                        if isempty(wstr)
                            error('请在自定义加权向量输入框中输入权重向量或表达式。');
                        end
              

                        % 在本地函数作用域提供 fl 便于表达式使用（例如 'hamming(fl)'）
                        fl = flVal; %#ok<NASGU>
                        % 使用 eval（在当前函数作用域），允许数列或包含函数调用的表达式
                        Wvec_tmp = eval(wstr);
                        if isempty(Wvec_tmp) || ~isnumeric(Wvec_tmp) || ~isvector(Wvec_tmp)
                            error('解析得到的权重不是数值向量。');
                        end
                        Wvec_tmp = double(Wvec_tmp(:));
                        if numel(Wvec_tmp) ~= flVal
                            error('权重向量长度必须等于 fl（%d）。', flVal);
                        end
                        if any(~isreal(Wvec_tmp))
                            error('权重向量必须为实数。');
                        end
                        if any(Wvec_tmp <= 0)
                            error('权重向量中的所有元素必须严格为正（>0）。');
                        end
                        Wvec = Wvec_tmp;
                        useW = true;
                    catch ME
                        showAlert(dlg_sg, ...
                            ['解析自定义加权向量失败，请输入长度为 fl 的正实向量，或使用可评估的表达式（例如 ''hamming(fl)''）。' newline ...
                             '解析错误：' ME.message], '权重错误');
                        return;
                    end
                else
                    % 预置：用内部 mapping 根据 flVal 生成向量（不再依赖 base workspace）
                    presetStr = ddPreset.Value;
                    try
                        % 读取可能的额外参数（如果这些控件是可见的则读取）
                        % 注意：根据 onPresetChanged, 若为 numeric 则对应 numParamX.Visible='on'
                        % 若为 choice 则 choiceParamX.Visible='on'
                        readParam = @(n) deal( ...
                            (n==1)*(numParam1.Visible && ~isempty(numParam1.Value)) .* double(numParam1.Value) + 0*0, ...
                            (n==2)*(numParam2.Visible && ~isempty(numParam2.Value)) .* double(numParam2.Value) + 0*0, ...
                            (n==3)*(numParam3.Visible && ~isempty(numParam3.Value)) .* double(numParam3.Value) + 0*0 ...
                        ); % 这里只是占位式帮助说明，下面我们按 preset 分支单独读取

                        switch presetStr
                            case 'ones'
                                Wvec_tmp = ones(flVal,1);
                            case 'hamming'
                                Wvec_tmp = hamming(flVal);
                            case 'hann'
                                Wvec_tmp = hann(flVal);
                            case 'blackman'
                                Wvec_tmp = blackman(flVal);
                            case 'rectwin'
                                Wvec_tmp = rectwin(flVal);
                            case 'bartlett'
                                Wvec_tmp = bartlett(flVal);
                            case 'chebwin'
                                % 需要 r 参数（numeric）: 从 numParam1 / numParam2 / numParam3 中读取（哪个可见就用哪个）
                                if numParam1.Visible
                                    rVal = double(numParam1.Value);
                                elseif numParam2.Visible
                                    rVal = double(numParam2.Value);
                                elseif numParam3.Visible
                                    rVal = double(numParam3.Value);
                                else
                                    error('预置 chebwin 需要参数 r，但未检测到参数输入。');
                                end
                                chebwin_rVal = rVal;
                                Wvec_tmp = chebwin(flVal, rVal);

                            case 'tukey'
                                if numParam1.Visible
                                    rVal = double(numParam1.Value);
                                else
                                    error('预置 tukey 需要参数 r，但未检测到参数输入。');
                                end
                                tukey_rVal = rVal;
                                Wvec_tmp = tukeywin(flVal, rVal);
                            case 'kaiser'
                                if numParam1.Visible
                                    betaVal = double(numParam1.Value);
                                else
                                    error('预置 kaiser 需要参数 beta，但未检测到参数输入。');
                                end
                                kaiser_betaVal = betaVal;
                                Wvec_tmp = kaiser(flVal, betaVal);
                            case 'gauss'
                                if numParam1.Visible
                                    alphaVal = double(numParam1.Value);
                                else
                                    error('预置 gauss 需要参数 alpha，但未检测到参数输入。');
                                end
                                gauss_alphaVal = alphaVal;
                                Wvec_tmp = gausswin(flVal, alphaVal);
                            otherwise
                                error('未知的预置选项：%s', presetStr);
                        end
                        % 接着做原来的有效性检查
                        if isempty(Wvec_tmp) || ~isnumeric(Wvec_tmp) || ~isvector(Wvec_tmp)
                            error('预置表达式没有返回有效的向量。');
                        end
                        Wvec_tmp = double(Wvec_tmp(:));
                        if numel(Wvec_tmp) ~= flVal
                            error('预置加权向量的结果长度必须等于 fl（%d）。', flVal);
                        end
                        if any(~isreal(Wvec_tmp)) || any(Wvec_tmp <= 0)
                            error('预置加权向量必须产生正的实数向量。');
                        end
                        Wvec = Wvec_tmp;
                        useW = true;
                        w_preset_choice = presetStr;
                    catch ME
                        showAlert(dlg_sg, ...
                            ['解析预置加权向量失败，请检查所选项是否有效及其参数。' newline '解析错误：' ME.message], '权重错误');
                        return;
                    end
                end
            end % cbW.Value

            % ----- diff_N 的校验（仅当选择微分滤波器时） -----
            if bgApply.SelectedObject == rbSmooth
                filterTypeTmp = 'smooth';
                diffN_tmp = [];
            else
                filterTypeTmp = 'diff';
                diffN_tmp = round(double(edtDiffN.Value));
                if isempty(diffN_tmp) || diffN_tmp < 0
                    showAlert(dlg_sg,'微分阶数 diff_N 必须为非负整数。','参数错误');
                    return;
                end
                if diffN_tmp > mVal
                    showAlert(dlg_sg,sprintf('微分阶数 diff_N (%d) 不能大于多项式阶数 m (%d)。', diffN_tmp, mVal),'参数错误');
                    return;
                end
            end

            % 其他安全校验（如 fl 过大）
            if flVal > 1e5
                showAlert(dlg_sg,'帧长度 fl 太大，可能导致内存或性能问题。请减小 fl。','参数错误');
                return;
            end

            % --- 所有校验通过 -> 构造 params 并保存 ---
            params = struct();
            params.m = mVal;
            params.fl = flVal;
            if useW
                % 若是自定义，保存数值向量；若是预置，也保存解析得到的数值向量与预置名
                params.w = Wvec;
                if ~isempty(w_preset_choice)
                    params.w_preset = w_preset_choice;
                    switch w_preset_choice
                        case 'chebwin'
                            params.chebwin_rVal = chebwin_rVal;
                        case 'tukey'
                            params.tukey_rVal = tukey_rVal;
                        case 'kaiser'
                            params.kaiser_betaVal = kaiser_betaVal;
                        case 'gauss'
                            params.gauss_alphaVal = gauss_alphaVal;
                        otherwise

                    end
                end
            end

            params.filterType = filterTypeTmp;
            if strcmp(filterTypeTmp,'diff')
                params.diff_N = diffN_tmp;
            end
            if bgApply.SelectedObject == rbSmooth
                % 新增：短信号处理方法保存（将中文选项映射为内部短名称）
                if strcmp(ddShortMethod.Value, '端点镜像填充')
                    params.shortSignalMethod = 'pad';
                else
                    % '局部最小二乘拟合'
                    params.shortSignalMethod = 'ls';
                end
            end
                 
            % 结束 uiwait 并关闭对话框
            try
                if isvalid(dlg_sg)
                    uiresume(dlg_sg); 
                    delete(dlg_sg); 
                end
            catch
                try delete(dlg_sg); catch; end
            end

        catch ME
            showAlert(dlg_sg, ['保存失败：' ME.message], '错误');
        end
    end

end







%% ---- 常规滤波路径 ----
function [y, aborted] = applyNormalFilter(S, x_use, useFcn, fig_GUI)
% applyNormalFilter  执行常规滤波路径（封装原 try 内的逻辑）
% 返回:
%   y       - 滤波后的结果（若 aborted==true，则 y 可能为空）
%   aborted - 如果内部决定直接退出（相当于原代码的 return），则为 true

aborted = false;
y = [];

% 确定 time dim（优先 S.timeDim）
useTimeDim = false;
if  ~isempty(S.timeDim) && S.timeDim==round(S.timeDim) && S.timeDim>=1
    tdim = S.timeDim;
    useTimeDim = true;
end

switch lower(useFcn)
    case 'filter'
        if useTimeDim
            y = filter(S.filter_b, S.filter_a, x_use, [], tdim);
        else
            y = filter(S.filter_b, S.filter_a, x_use);
        end

    case 'filtfilt'
        % 如果指定了 time-dim，则先把任意维重排为 [N x channels]
        if useTimeDim
            [X2, restoreFcn] = to2DtimeMajor(x_use, tdim); %#ok<NASGU>
            % 直接调用 filtfilt（不做 NaN/Inf 预处理；让 MATLAB 抛出任何异常）
            y2 = filtfilt(S.filter_b, S.filter_a, X2);
            % 还原维度/类型
            y = restoreFcn(y2);
        else
            % 没有指定 time-dim：直接对原始 x_use 使用 filtfilt（让 MATLAB 抛出任何异常）
            y = filtfilt(S.filter_b, S.filter_a, x_use);
        end

    case 'fftfilt'
        % ---------- 支持 N 维输入的 fftfilt（通过 to2DtimeMajor） ----------
        % 1) 要求为 FIR（a == 1）
        if ~(isscalar(S.filter_a) && S.filter_a == 1)
            uialert_safe(fig_GUI,'fftfilt(b, x)只支持FIR滤波器（分母系数应为1），请更换滤波函数（filter/filtfilt）后重试','应用错误');
            aborted = true; return;
        end

        % 2) 准备输入与系数（保留 origClass 以便恢复）
        origClass = class(x_use);
        X_proc = x_use;
        if ~isa(X_proc, 'double')
            X_proc = double(X_proc); % fftfilt 要求数值计算为 double 更稳健
        end
        b_for = S.filter_b;
        if ~isa(b_for, 'double')
            b_for = double(b_for);
        end

        % 3) 分两种情况：已显式指定时间维（useTimeDim） 或 未指定（自动处理2D/ND）
        if useTimeDim
            % 用户已指定 time-dim：使用 to2DtimeMajor 将其移到第一维
            [X2, restoreFcn] = to2DtimeMajor(X_proc, tdim);
            if ~isa(X2,'double'), X2 = double(X2); end

            channels = size(X2,2);
            % b 的列数检查（允许向量或单列或与 channels 匹配）
            if ~ (isvector(b_for) || size(b_for,2) == channels || size(b_for,2) == 1)
                uialert_safe(fig_GUI, sprintf('滤波器系数维度与通道数不匹配：数据通道=%d，滤波器列=%d', channels, size(b_for,2)), '应用错误');
                aborted = true; return;
            end

            % 调用 fftfilt 并还原
            y2 = fftfilt(b_for, X2);
            try
                y_dbl = restoreFcn(y2);
            catch ME
                uialert_safe(fig_GUI, sprintf('fftfilt: 还原维度失败：%s', ME.message), '应用错误');
                aborted = true; return;
            end
        else
            % 未显式指定 time-dim：
            if ndims(X_proc) > 2
                % 自动推断首个非单例维作为 time-dim（与其它工具函数一致）
                inferred_tdim = find(size(X_proc) ~= 1, 1, 'first');
                if isempty(inferred_tdim)
                    inferred_tdim = 1;
                end
                [X2, restoreFcn] = to2DtimeMajor(X_proc, inferred_tdim);
                if ~isa(X2,'double'), X2 = double(X2); end

                channels = size(X2,2);
                if ~ (isvector(b_for) || size(b_for,2) == channels || size(b_for,2) == 1)
                    uialert_safe(fig_GUI, sprintf('滤波器系数维度与通道数不匹配：数据通道=%d，滤波器列=%d', channels, size(b_for,2)), '应用错误');
                    aborted = true; return;
                end

                y2 = fftfilt(b_for, X2);
                try
                    y_dbl = restoreFcn(y2);
                catch ME
                    uialert_safe(fig_GUI, sprintf('fftfilt: 还原维度失败：%s', ME.message), '应用错误');
                    aborted = true; return;
                end
            else
                % 原 2D/向量 情形：保持原语义，直接调用 fftfilt
                channels = size(X_proc,2);
                if ~ (isvector(b_for) || size(b_for,2) == channels || size(b_for,2) == 1)
                    uialert_safe(fig_GUI, sprintf('滤波器系数维度与通道数不匹配：数据通道=%d，滤波器列=%d', channels, size(b_for,2)), '应用错误');
                    aborted = true; return;
                end
                y_dbl = fftfilt(b_for, X_proc);
            end
        end

        % 4) 尝试恢复原始数据类型（保持原逻辑）
        try
            if ~strcmp(origClass,'double')
                y = cast(y_dbl, origClass);
            else
                y = y_dbl;
            end
        catch
            y = y_dbl;
            warning('fftfilt:无法将结果转换为原始数据类型 %s，结果保留为 double。', origClass);
        end

    case 'my_filtfilt'
        if useTimeDim
            y = my_filtfilt(S.filter_b, S.filter_a, x_use, tdim);
        else
            y = my_filtfilt(S.filter_b, S.filter_a, x_use);
        end

    otherwise
        error('applyNormalFilter:UnknownFilterFunction','未识别的滤波函数 %s', useFcn);
end

end

%% ----- 对输入信号 x_use 应用脉冲整形滤波（通用）。适用于 gaussdesign / rcosdesign 等产生的 FIR 脉冲整形滤波器-----
function [y, errMsg] = applyShapingFilter(b, a, p_params, x_use, S, handles, fig_GUI)
% applyShapingFilter  对输入信号 x_use 应用脉冲整形滤波（通用）
%
% 用途：
%  - 适用于 gaussdesign / rcosdesign 等产生的 FIR 脉冲整形滤波器
%  - 支持三种应用模式：'tx'（发射端，上采样 + upfirdn）、'rx'（接收端，滤波 + 下采样）、'gen'（常规）
%  - 对 frac shift 支持两种补偿：'autointerp' (插值) 或 'fracdelay' (短 FIR 分数延迟)
%  - 对 upfirdn 输出长度支持 'keep'（尽量保留原长）或 'trim'（裁切延迟/默认）
%
% 输入：
%  - b, a       : 滤波器系数（标量 / 向量 / 矩阵 ），a 一般为 1
%  - p_params   : 参数结构（来自 handles.gaussdesignParams 或 handles.rcosdesignParams）
%                 必须包含至少字段：sps（正整数）, appType ('tx'|'rx'|'gen')
%                 可含字段：upfirdnMode ('keep'|'trim'), autoAlignMode ('autointerp'|'fracdelay')
%  - x_use      : 要滤波的信号 ；向量 | 矩阵 | N 维数组
%  - S          : 传入主函数的 S
%  - handles    : 传入主函数的 handles
%  - fig_GUI    : GUI figure handle，用于 uialert/uialert_safe 的第一个参数（可以传 []）
%  
% 输出：
%  - y          : 滤波后输出（若出错返回 []）
%  - errMsg     : 错误信息字符串；为空表示成功
%
% 返回约定：若发生错误，函数会用 uialert_safe / uialert 向用户提示并把 errMsg 返回，y 返回 []。
%
% 使用示例：
%  % gauss:
%  [y, err] = applyShapingFilter(S.filter_b, S.filter_a, handles.gaussdesignParams, x_use, S, handles, fig_GUI) 
%  % rcos:
%  [y, err] = applyShapingFilter(S.filter_b, S.filter_a, handles.rcosdesignParams, x_use, S, handles, fig_GUI) 
%
%  在原代码中替换：
%    （原来长分支处） -> 调用此函数并检查 errMsg 是否为空；若非空则 return。
%
%  兼容性：R2025b 应当无问题；若项目有自定义 uialert_safe，会优先调用。

    y = [];
    errMsg = '';

    % ----- 初始校验 -----
    if nargin < 7 || isempty(fig_GUI)
        fig_GUI = [];
    end

    % params 存在性
    if isempty(p_params)
        uialert_safe(fig_GUI, '请先通过 多带 / 高级滤波参数 设置滤波器参数。', '参数缺失');
        errMsg = 'params_missing';
        return;
    end

    % b 合法性
    if isempty(b) || ~isnumeric(b) || ~(isvector(b) || ismatrix(b))
        uialert_safe(fig_GUI, '滤波器系数 b 无效。', '参数错误');
        errMsg = 'invalid_b';
        return;
    end

    % sps 校验
    if ~isfield(p_params,'sps') || ~(isnumeric(p_params.sps) && isscalar(p_params.sps) && p_params.sps>=1)
        uialert_safe(fig_GUI, '参数 sps 无效。', '参数错误');
        errMsg = 'invalid_sps';
        return;
    end
    sps = double(p_params.sps);

    % x_use 存在性与类型
    if ~exist('x_use','var') || isempty(x_use)
        uialert_safe(fig_GUI, '未提供要滤波的输入信号 x_use。', '参数缺失');
        errMsg = 'missing_x';
        return;
    end
    if ~isnumeric(x_use)
        uialert_safe(fig_GUI, '输入信号 x_use 必须为数值向量或矩阵。', '参数错误');
        errMsg = 'invalid_x';
        return;
    end

    % ----------------- 新增：支持任意 time-dim（复用 to2DtimeMajor） -----------------
    % 说明：我们优先使用 p_params.tdim（如果用户显式传入），否则使用 S.timeDim（若存在），否则默认 1。

    % 决定 time-dim
    useTimeDim = false;
    if  ~isempty(S.timeDim) && S.timeDim==round(S.timeDim) && S.timeDim>=1
        tdim = S.timeDim;
        useTimeDim = true;
    else
        tdim = find(size(x_use)~=1,1,'first');
        if ~isempty(tdim) && tdim>=1
            useTimeDim = true;
        end
    end

    if useTimeDim
        try
            [X2, restoreFcn] = to2DtimeMajor(x_use, tdim); % X2: [N x channels]
        catch ME
            uialert_safe(fig_GUI, sprintf('重排输入到 time-major 失败：%s', ME.message), '参数错误');
            errMsg = 'to2D_fail';
            return;
        end
    else
        % 未指定 timeDim：只在 x_use 为向量或 2D 矩阵时按列处理（保持与标准路径一致）
        if ndims(x_use) > 2
            uialert_safe(fig_GUI, 'FIR脉冲整形滤波：输入为多维数组但未指定 S.timeDim。请设置 S.timeDim 或使用常规滤波路径。', '参数缺失');
            return;
        else
            % --- 针对向量/矩阵的鲁棒处理（为行向量做特殊处理） ---
            origSize = size(x_use);
            if isvector(x_use)
                % 若为向量，强制为列向量以便 upsample/filter 按列工作
                wasRow = isrow(x_use);
                X2 = x_use(:);  % [N x 1]
        
                % 生成恢复函数：保证最终输出维度与原始 x_use 一致（如果原为行向量则恢复为行）
                if wasRow
                    % Y2 是 [N*l x 1]，恢复为 1 x (N*l)
                    restoreFcn = @(Y2) reshape(Y2.', origSize);
                else
                    % 原为列向量，恢复为 (N*l) x 1
                    restoreFcn = @(Y2) reshape(Y2, origSize);
                end
            else
                % 已是 2D 矩阵（N x channels），保持原样处理并简单恢复
                X2 = x_use;
                restoreFcn = @(Y2) reshape(Y2, size(x_use));
            end
        end
    end

    % L 与 d（以采样点计）——更稳健地支持 b 为列向量或矩阵
    try
        if isvector(b)
            L = numel(b);
        else
            % b 作为滤波器系数矩阵时，滤波器长度应为第一维
            L = size(b,1);
        end
        d = (L - 1) / 2; % gauss/rcos 通常保证为整数，但保留浮点处理
    catch ME
        uialert_safe(fig_GUI, sprintf('滤波器长度计算失败：%s', ME.message), '参数错误');
        errMsg = 'length_err';
        return;
    end

    % 主分支：tx / rx / gen
    try
        if isfield(p_params,'appType') && strcmp(p_params.appType,'tx')
            % ---------------- 发射端：上采样并滤波 ----------------
            % X2 是 [N x channels]
            % 检查 b 与 channels 的兼容性（若 b 是矩阵）
            channels = size(X2,2);
            if ~isvector(b) && size(b,2) ~= 1 && size(b,2) ~= channels
                uialert_safe(fig_GUI, sprintf('滤波器系数维度与通道数不匹配：数据通道=%d，滤波器列=%d', channels, size(b,2)), '应用错误');
                errMsg = 'b_channel_mismatch';
                return;
            end

            y_tmp = upfirdn(X2, b, sps); % 返回 [N_up x channels]

            % 期望输出长度（按每符号 sps）
            origN = size(X2,1);
            desired_len = sps * origN;
            Ntmp = size(y_tmp,1);

            if isfield(p_params,'upfirdnMode') && strcmp(p_params.upfirdnMode,'keep')
                % 保留原长：居中裁切或尾端填零
                if Ntmp >= desired_len
                    startIdx = floor((Ntmp - desired_len)/2) + 1;
                    y2 = y_tmp(startIdx : startIdx + desired_len - 1, :);
                else
                    y2 = zeros(desired_len, size(y_tmp,2));
                    y2(1:Ntmp,:) = y_tmp;
                    uialert_safe(fig_GUI,'上采样滤波输出长度小于期望长度，已在末尾填零以保留原长。','运行提示');
                end
            else
                % 默认：裁切群延迟 d 个采样（注意 d 以样点计）
                if d < size(y_tmp,1)
                    y2 = y_tmp(d+1:end,:);
                else
                    uialert_safe(fig_GUI,'发射端滤波后数据长度太短，无法补偿群延迟。','运行错误');
                    errMsg = 'tx_length_short';
                    return;
                end
            end

            % 恢复回原始维度/类型
            try
                y = restoreFcn(y2);
            catch ME
                uialert_safe(fig_GUI,sprintf('恢复输出形状失败：%s',ME.message),'运行错误');
                errMsg = 'restore_fail';
                return;
            end

        elseif isfield(p_params,'appType') && strcmp(p_params.appType,'rx')
            % ---------------- 接收端：滤波并下采样 ----------------
            channels = size(X2,2);
            if ~isvector(b) && size(b,2) ~= 1 && size(b,2) ~= channels
                uialert_safe(fig_GUI, sprintf('滤波器系数维度与通道数不匹配：数据通道=%d，滤波器列=%d', channels, size(b,2)), '应用错误');
                errMsg = 'b_channel_mismatch';
                return;
            end

            y_tmp = upfirdn(X2, b, 1, sps); % [N_up x channels]

            % 下采样对应的符号级群延迟（符号单位）
            shift_sym = d / sps;
            intShift = floor(shift_sym);
            fracShift = shift_sym - intShift;

            if intShift >= size(y_tmp,1)
                uialert_safe(fig_GUI,'接收端滤波后数据长度太短，无法补偿群延迟。','运行错误');
                errMsg = 'rx_length_short';
                return;
            end

            % 移除整数符号延迟（在采样点级）
            y_dec = y_tmp(intShift+1:end,:); % 仍是采样点级 long vector

            if fracShift ~= 0
                % 存在分数延迟，根据用户选择的 autoAlignMode 补偿
                if isfield(p_params,'autoAlignMode') && strcmp(p_params.autoAlignMode,'autointerp')
                    try
                        y2 = applyFracInterpShift(y_dec, -fracShift); % 负号表示提前补偿
                    catch ME
                        uialert_safe(fig_GUI, sprintf('自动插值对齐失败：%s\n已采用近似移位。', ME.message), '运行警告');
                        y2 = y_dec;
                    end

                elseif isfield(p_params,'autoAlignMode') && strcmp(p_params.autoAlignMode,'fracdelay')
                    try
                        Nfir = 41; % 可调整
                        h_frac = fracDelayFIR(fracShift, Nfir);
                        pad = (Nfir-1)/2;
                        % 对每列滤波并去掉滤波器引入的前置延迟
                        y_filtered = filter(h_frac, 1, [y_dec; zeros(pad, size(y_dec,2))]);
                        y2 = y_filtered(pad+1 : pad + size(y_dec,1), :);
                    catch ME
                        uialert_safe(fig_GUI, sprintf('分数延迟补偿失败：%s\n已采用近似移位。', ME.message), '运行警告');
                        y2 = y_dec;
                    end

                else
                    uialert_safe(fig_GUI, sprintf('未识别的自动对齐模式（%s），已采用近似补偿。', string(p_params.autoAlignMode)), '参数警告');
                    y2 = y_dec;
                end

                % 提示用户已经尝试补偿
                uialert_safe(fig_GUI, sprintf('检测到非整数符号延迟（%.3f 符号），已按 "%s" 模式尝试补偿。', shift_sym, p_params.autoAlignMode), '延迟提示');

            else
                % 无分数延迟，直接返回下采样结果
                y2 = y_dec;
            end

            % 现在 y2 是 [N_out x channels]（采样点级）。恢复回原形状（time-dim 被替换为符号级长度）
            try
                y = restoreFcn(y2);
            catch ME
                uialert_safe(fig_GUI,sprintf('恢复输出形状失败：%s',ME.message),'运行错误');
                errMsg = 'restore_fail';
                return;
            end

        else
            % ---------------- 常规滤波（gen） ----------------
            % 直接复用 applyNormalFilter，它已经支持 S.timeDim / 多维
            try 
                % useFcn 由 caller 或 handles 指定（尝试读取）
                try useFcn = handles.ddFilterFunction.Value; catch; end

                [y_tmp, aborted] = applyNormalFilter(S, x_use, useFcn, fig_GUI);
                if aborted
                    errMsg = 'gen_aborted';
                    y = [];
                    return;
                else
                    y = y_tmp;
                end
            catch ME
                uialert_safe(fig_GUI,sprintf('常规滤波失败：%s',ME.message),'运行错误');
                errMsg = 'gen_filter_error2';
                return;
            end
        end

    catch ME_app
        uialert_safe(fig_GUI,sprintf('滤波应用过程中出错：%s', ME_app.message),'运行错误');
        errMsg = 'app_exception';
        return;
    end

    % 成功返回（errMsg 保持为空）
    return;
end

% applyShapingFilter()中有使用。用于 gaussdesign / rcosdesign 等产生的 FIR 脉冲整形滤波器的应用部分。自动对齐方式 方法 A：自动插值（基于插值移动，速度快、简单）
function y_shifted = applyFracInterpShift(y_in, shift)
% applyFracInterpShift 通过插值把序列在样点域上按 shift（采样为单位）进行移动
% y_in: 列向量或矩阵（每列独立处理）， shift: 可以是正/负小数
% 注意：若 shift 为正，表示输出点相对于输入点向右移动（延迟）；若为负，表示向左移动（提前）
    [N, C] = size(y_in);
    n = (1:N).';
    % 目标采样点：t_out = n + shift
    t_out = n + shift;
    y_shifted = zeros(size(y_in));
    for c = 1:C
        % 使用 pchip 插值并允许外推（填零）
        ycol = y_in(:,c);
        % 为避免 NaN，使用 interp1 并对超出范围处采用线性外推
        y_shifted(:,c) = interp1(n, ycol, t_out, 'pchip', 0);
    end
end

% applyShapingFilter()中有使用。用于 gaussdesign / rcosdesign 等产生的 FIR 脉冲整形滤波器的应用部分。自动对齐方式 方法 B：基于 FIR 的分数延迟（更精确，稍慢） 
function h = fracDelayFIR(mu, N)
% fracDelayFIR 设计窗函数切割的 sinc 分数延迟滤波器（线性相位）
% mu: 期望延迟量（以采样为单位），0<=mu<1 表示要向右延迟 mu 个采样；
%     若要提前（advance）可传入负值 e.g. mu = -0.25
% N: 奇数滤波器长度（如 41）
    if mod(N,2)==0
        error('N must be odd');
    end
    M = (N-1)/2;
    n = -M:M;
    % sinc 基函数（注意 mu 的符号：h[n] = sinc(n - mu)）
    h = sinc(n - mu);
    % 窗函数（Hamming）
    w = hamming(N);
    h = h .* w';
    % 归一化直流（或单位群延迟量）
    h = h / sum(h);
end

%% ---- 自定义滤波函数 my_filtfilt  前向-后向零相位滤波 ---- 
function y = my_filtfilt(b,a,x,varargin)
% MY_FILTFILT  前向-后向零相位滤波（不使用 filter/filtfilt）
%   y = my_filtfilt(b,a,x)
%   y = my_filtfilt(b,a,x,dim)
%   - b,a : 滤波器分子/分母系数（向量）
%   - x   : 输入信号（向量/矩阵/N维数组）。按列（即 time dim 的其余展平维）分别处理。
%   - dim : （可选）指定运算维度（time dimension）。若不提供，使用 x 的首个非单例维。
%   - y   : 输出，与 x 的尺寸和数据类型尽量保持一致（使用 to2DtimeMajor/restoreFn 恢复）
%
% 实现思路：
%   1) 使用 to2DtimeMajor 将 time dim 移到第一维并 reshape -> [N x channels]
%   2) 对每一列做镜像填充、因果 IIR、反转再因果 IIR（近似 filtfilt）
%   3) 使用 restoreFn 将结果恢复为原始形状并尽量恢复原数据类型
%

% --- 参数检查 ---
if ~(nargin == 3 || nargin == 4)
    error('Usage: y = my_filtfilt(b,a,x) or y = my_filtfilt(b,a,x,dim)');
end

% optional dim
if nargin == 4
    dim = varargin{1};
    if ~(isnumeric(dim) && isscalar(dim) && dim==round(dim) && dim>=1)
        error('my_filtfilt:InvalidDim','dim must be a positive integer scalar.');
    end
else
    % choose first non-singleton dimension
    s = size(x);
    nz = find(s ~= 1, 1, 'first');
    if isempty(nz)
        dim = 1;
    else
        dim = nz;
    end
end

% --- normalize a if needed ---
if isempty(a) || isempty(b)
    error('my_filtfilt:EmptyCoeffs','Filter coefficients must be non-empty.');
end

if a(1) ~= 1
    b = b / a(1);
    a = a / a(1);
end

nb = numel(b);
na = numel(a);
ncoef = max(nb,na);
padlen_default = 3*(ncoef-1);  % filtfilt-like default

% --- move time dim to first and reshape to [N x channels] ---
[X2, restoreFn] = to2DtimeMajor(x, dim);

% convert to double for filtering calculations (better numeric stability)
X2d = double(X2);
[Nrows, Ncols] = size(X2d);

% compute padlen adapted to signal length
padlen = padlen_default;
if padlen >= Nrows
    padlen = max(1, Nrows-1);
end

% preallocate output
Y2 = zeros(size(X2d));

% iir direct-form solver (runs on vin [L x M] and returns vout [L x M])
    function vout = iir_direct(bc, ac, vin)
        L = size(vin,1);
        M = size(vin,2);
        vout = zeros(L, M);
        % naive sample-by-sample (clear and robust)
        for n = 1:L
            % numerator part: sum_{k=1..nb} bc(k) * vin(n-(k-1))
            for k = 1:nb
                idx = n - (k-1);
                if idx >= 1
                    vout(n,:) = vout(n,:) + bc(k) * vin(idx,:);
                end
            end
            % denominator (feedback) part: for k=2..na use past outputs
            for k = 2:na
                idx = n - (k-1);
                if idx >= 1
                    vout(n,:) = vout(n,:) - ac(k) * vout(idx,:);
                end
            end
        end
    end

% --- 对每列（channel）处理（但利用矩阵化以减少循环） ---
for c = 1:Ncols
    xc = X2d(:,c);  % column vector of length Nrows

    % 构造镜像填充（左右各 padlen）
    % 注意 padlen <= Nrows-1 保证索引有效
    % 左侧反射：取 xc(2:padlen+1) 的反转并做 2*xc(1)-...
    if padlen >= 1
        left_idx_end = min(Nrows, padlen+1); % 安全取值（理论上 padlen < Nrows）
        if left_idx_end >= 2
            left_idx = 2:left_idx_end;
            left_reflect = 2*xc(1) - xc(left_idx(end:-1:1));
            % 若 left_reflect 长度 < padlen（当信号非常短时），用重复第一个值填充
            if numel(left_reflect) < padlen
                left_reflect = [left_reflect; repmat(left_reflect(end), padlen-numel(left_reflect), 1)];
            end
        else
            left_reflect = repmat(xc(1), padlen, 1);
        end

        % 右侧反射
        right_idx_start = max(1, Nrows - padlen);
        if right_idx_start <= Nrows-1
            right_idx = (Nrows-1) : -1 : right_idx_start;
            right_reflect = 2*xc(end) - xc(right_idx);
            if numel(right_reflect) < padlen
                right_reflect = [right_reflect; repmat(right_reflect(end), padlen-numel(right_reflect), 1)];
            end
        else
            right_reflect = repmat(xc(end), padlen, 1);
        end
    else
        left_reflect = [];
        right_reflect = [];
    end

    xp = [left_reflect; xc; right_reflect];  % 长度 L = Nrows + 2*padlen

    % 前向因果滤波
    yf = iir_direct(b,a,xp);

    % 反转并再次滤波
    yr = yf(end:-1:1,:);
    zf = iir_direct(b,a,yr);

    % 反转回并移除填充，取中间部分
    yfull = zf(end:-1:1,:);
    ycol = yfull(padlen+1 : padlen+Nrows, :);

    Y2(:,c) = ycol;
end

% --- 恢复为原始 shape & 尝试恢复数据类型（使用 restoreFn） ---
try
    y = restoreFn(Y2);
catch ME
    % 若 restore 抛出与复数/整数转换相关的错误，给出更友好的信息并重抛
    if contains(ME.identifier, 'ComplexToInteger') || contains(ME.identifier, 'ComplexToLogical')
        rethrow(ME);
    end
end

end

%% ---- 用 tf 合并多个并联传递函数为一个传递函数, 用于 陷波 / 峰值滤波器设计时 ---- 
function [b_all, a_all] = combine_parallel_filters_tf(b_in, a_in)
% COMBINE_PARALLEL_FILTERS_TF  用 tf 合并多个并联传递函数
%   [b_all,a_all] = combine_parallel_filters_tf(b_in,a_in)
%
% 输入:
%   b_in, a_in - cell arrays of numerator/denominator coefficient vectors,
%                或者矩阵（每一行是一个多项式系数向量）
% 输出:
%   b_all, a_all - 合并后的分子/分母系数（行向量）
%
% 说明:
%   该函数**仅**使用 Control System Toolbox 的 tf 对象进行相加，
%   推荐当心数值问题或阶数非常高时的稳定性（但 tf 通常处理得较好）。
%
% 示例:
%   b = {[0.5 0.2], [1 0], [0.1]};
%   a = {[1 -0.8], [1 -0.5], [1 -0.2]};
%   [b_all,a_all] = combine_parallel_filters_tf(b,a);

% --- 校验并标准化输入为 cell array ---
if ~iscell(b_in)
    if ismatrix(b_in) && size(b_in,1) > 0
        b_cell = cell(1,size(b_in,1));
        for k = 1:size(b_in,1)
            b_cell{k} = trim_poly(b_in(k,:));
        end
    else
        error('b_in must be a cell array or a matrix with each row a numerator.');
    end
else
    b_cell = b_in;
end

if ~iscell(a_in)
    if ismatrix(a_in) && size(a_in,1) > 0
        a_cell = cell(1,size(a_in,1));
        for k = 1:size(a_in,1)
            a_cell{k} = trim_poly(a_in(k,:));
        end
    else
        error('a_in must be a cell array or a matrix with each row a denominator.');
    end
else
    a_cell = a_in;
end

N = numel(b_cell);
if numel(a_cell) ~= N
    error('Number of numerators and denominators must match.');
end

% --- 用 tf 相加 (并联) ---
% 初始化为零系统
H = tf(0,1);
for k = 1:N
    bk = trim_poly(b_cell{k});
    ak = trim_poly(a_cell{k});
    % 若传入为标量 0 或常数, 确保是行向量
    if isempty(bk), bk = 0; end
    if isempty(ak), ak = 1; end
    H = H + tf(bk, ak);
end

% 提取系数向量
[b_all, a_all] = tfdata(H, 'v');  % 返回行向量

% 数值清理与归一化（使 a_all(1) == 1）
tol = 1e-12;
if all(abs(a_all) < tol)
    % 全为0的异常情况
    a_all = 1;
    b_all = 0;
    return;
end

% 去除前导近零系数
idx = find(abs(a_all) > tol, 1, 'first');
if ~isempty(idx) && idx > 1
    a_all = a_all(idx:end);
    % 对应地对 b_all 做尾部对齐（保持多项式阶次一致）
    b_all = b_all(max(1, length(b_all) - length(a_all) + 1) : end);
end

% 归一化
if abs(a_all(1) - 1) > tol
    b_all = b_all / a_all(1);
    a_all = a_all / a_all(1);
end

% 再次去除任何可能的前导近零
b_all = trim_poly(b_all);
a_all = trim_poly(a_all);
end

%% 辅助：去除前导近零并返回行向量, 用于 陷波 / 峰值滤波器设计时combine_parallel_filters_tf()函数
function p = trim_poly(p)
    if isempty(p)
        p = 0;
        return;
    end
    p = p(:).'; 
    tol = 1e-12;
    idx = find(abs(p) > tol, 1, 'first');
    if isempty(idx)
        p = 0;
    else
        p = p(idx:end);
    end
end

%% 辅助：多项式归一化并修剪, 用于 陷波 / 峰值滤波器设计时
function [b_out, a_out] = normalize_and_trim(b_in, a_in)
    b = trim_poly(b_in);
    a = trim_poly(a_in);
    tol = 1e-12;
    if all(abs(a) < tol)
        a_out = 1;
        b_out = 0;
        return;
    end
    % 将 a 的首系数标准化为 1
    if abs(a(1)-1) > tol
        b = b / a(1);
        a = a / a(1);
    end
    % 再次修剪
    b_out = trim_poly(b);
    a_out = trim_poly(a);
end

%% ---- 严格校验用于 firpm 的用户自定义 fresp ---- 
function report = validate_fresp_for_firpm(fresp, order, F, varargin)
% VALIDATE_FRESP_FOR_FIRPM  严格校验用户提供的 fresp 以供 firpm 使用
% （兼容性增强版 — 在 defaults 调用中增加 positional 回退；
%  对 defaults 返回更严格解析；对 DH/DW 增加诊断并用容差判断 DW）
%
% 用法：
%   report = validate_fresp_for_firpm(fresp, order, F)
%   report = validate_fresp_for_firpm(fresp, order, F, W)
%   report = validate_fresp_for_firpm(fresp, order, F, W, P1, P2, ...)
%
% 输入：
%   fresp  - 按照 firpm 接受的形式提供的频率响应函数，函数句柄或单元格：
%            @myfresp  或 {@myfresp, P1, P2, ...}
%   order  - FIR 滤波器阶数（标量整数，>= 0）
%   F      - 频带边界向量（单调，位于 [0, 1]，长度 >= 2）
%   W      - 可选的权重向量（每个带一个权重），可以为空 []
%   P1...  - 可选的额外参数，会传递给 fresp
%
% 输出（report 结构体）：
%   report.ok                               - 如果通过所有检查则为 true
%   report.SYM                              - 从 defaults 获得的 'even' / 'odd'（若未指定则为 'even'）
%   report.GF                               - 使用的频率网格
%   report.DH                               - 在 GF 上评估得到的期望响应
%   report.DW                               - 在 GF 上评估得到的优化权重
%   report.messages (cell)                  - 包含信息的单元格数组
%   report.warnings (struct array)
%   report.warnings_messages (cell, legacy)
%   report.errors                           - 检测到的错误列表（若无则为空）
%   report.AargStyle                        - 检测 A 参数的传参风格
%   report.AargInfo                         - 检测 A 参数的传参风格过程信息
% 
% 该函数具有防御性设计：它会捕获调用 fresp 时的异常并返回可操作的诊断信息。


% -------------------------
% 初始化消息容器
% -------------------------
msgs = {};    % 普通信息 / 成功消息（字符串 cell）
warns_msgs = {};   % 兼容：仅字符串形式的警告（legacy）
warns_struct = struct('type',{},'message',{}); % 新：结构化 warnings
errs = {};

% helper 函数：统一添加结构化 warning，并保留 messages 形式
function addWarning(wtype, wmsg)
    warns_msgs{end+1} = wmsg;
    s.type = wtype;
    s.message = wmsg;
    warns_struct(end+1) = s; 
end

% 替换原来的 report 初始化，增加 AargStyle 与 AargInfo 字段以记录检测结果
report = struct('ok',false,'messages',{{}},...
                'warnings',warns_struct,'warnings_messages',{{}},...
                'errors',{{}}, 'SYM','','GF',[],'DH',[],'DW',[], ...
                'AargStyle','unknown','AargInfo',struct());

% ---- 解析 fresp 输入（兼容 positional / Name-Value / nested cell） ----
if isempty(fresp)
    errs{end+1} = 'fresp is empty.';
    report.errors = errs; report.messages = msgs; report.warnings = warns_struct; report.warnings_messages = warns_msgs; return;
end

if iscell(fresp)
    fh = fresp{1};
    % extraArgs 可能是一个 cell 列表（positional 或 Name-Value）
    extraArgs = fresp(2:end);

    % 规范化：若 extraArgs 是单元素且该元素本身是 cell（常见于 {@f, {'A',A}} 的传法），则展开一次
    if isscalar(extraArgs) && iscell(extraArgs{1})
        extraArgs = extraArgs{1};
    end

    % 如果用户传入 struct（不常见但支持），将其转换为 Name-Value 对序列：
    % e.g. struct('A',A,'DiffFlag',1) -> {'A',A,'DiffFlag',1}
    if isscalar(extraArgs) && isstruct(extraArgs{1})
        s = extraArgs{1};
        fn = fieldnames(s);
        flat = cell(1, 2*numel(fn));
        for ii = 1:numel(fn)
            flat{2*ii-1} = fn{ii};
            flat{2*ii}   = s.(fn{ii});
        end
        extraArgs = flat;
        addWarning('fresp-struct-converted', 'fresp contained a single struct argument; converted to Name-Value pairs for validation.');
    end
else
    fh = fresp;
    extraArgs = {};
end

% ---------- 新增：检测 A 参数的传参风格 ----------
% 使用 detectFirpmFrespAStyle 来判断被测 fresp 中 A 的签名方式
try
    [aStyle, aInfo] = detectFirpmFrespAStyle(fh);
    report.AargStyle = aStyle;
    report.AargInfo  = aInfo;
    msgs{end+1} = sprintf('Detected fresp A-argument style: %s', aStyle);
    % 如果检测过程中有诊断信息，把关键字段加入 messages/warnings 便于追踪
    if isfield(aInfo,'nvTriedKeys') && ~isempty(aInfo.nvTriedKeys)
        msgs{end+1} = sprintf('  tried Name-Value keys: %s', strjoin(aInfo.nvTriedKeys, ', '));
    end
    if isfield(aInfo,'posErr') && ~isempty(aInfo.posErr)
        warns_msgs{end+1} = sprintf('A-positional-detect-info: %s', char(aInfo.posErr));
        addWarning('A-detect-positional-err', char(aInfo.posErr));
    end
    if isfield(aInfo,'nvErrs') && ~isempty(aInfo.nvErrs)
        % 保留逐键错误摘要为 warnings（供进一步诊断）
        for ii=1:numel(aInfo.nvErrs)
            if ~isempty(aInfo.nvErrs{ii})
                addWarning('A-detect-name_value-err', sprintf('key %s: %s', aInfo.nvTriedKeys{min(ii,numel(aInfo.nvTriedKeys))}, char(aInfo.nvErrs{ii})));
            end
        end
    end

    % 若检测到 'both'，明确告知位置参数优先（与大多数 fresp 约定）
    if strcmpi(aStyle,'both')
        msgs{end+1} =  'Both positional and Name-Value A detected; positional value will be treated as taking precedence in validation (consistent with many fresp implementations).';
    end
catch ME_detect
    % 检测器异常不会中断主流程，只记录 warning
    report.AargStyle = 'unknown';
    report.AargInfo = struct('error', ME_detect.message);
    addWarning('A-detect-failed', sprintf('detectFirpmFrespAStyle threw: %s', ME_detect.message));
end
% ---------- end A-arg detection ----------

if ~isa(fh,'function_handle') && ~(ischar(fh) || isstring(fh))
    errs{end+1} = 'fresp must be a function handle or cell where first element is a function handle/name.';
    report.errors = errs; report.messages = msgs; report.warnings = warns_struct; report.warnings_messages = warns_msgs; return;
end
try
    fh_handle = func2str(fh);
catch
    fh_handle = '';
end

% ---- 对 order 和 F 的基本检查 ----
if ~(isnumeric(order) && isscalar(order) && order >= 0 && isfinite(order))
    errs{end+1} = 'order must be a nonnegative finite scalar.';
end
if ~(isnumeric(F) && isvector(F) && all(isfinite(F)))
    errs{end+1} = 'F must be a finite numeric vector.';
else
    F = F(:).';  % 转为行向量
    if any(F < 0) || any(F > 1)
        errs{end+1} = 'All entries of F must be in [0, 1] (1 == Nyquist).';
    end
    if any(diff(F) < 0)
        errs{end+1} = 'F must be monotonically non-decreasing (ascending).';
    end
    if numel(F) < 2
        errs{end+1} = 'F must contain at least two frequency points.';
    end
    % 检查至少存在一个非零宽度的频带（奇偶配对）
    nonzeroBand = false;
    for k = 1:2:(numel(F)-1)
        if F(k+1) > F(k)
            nonzeroBand = true; break;
        end
    end
    if ~nonzeroBand
        errs{end+1} = 'No band has non-zero width: at least one pair F(k)<F(k+1) for odd k is required.';
    end
end

% 解析可选的 W（权重），如果作为 varargin{1} 提供
W = [];
extraCallArgs = {};
if ~isempty(varargin)
    % 如果第一个额外参数看起来像权重向量（长度==numBands），则接受它
    first = varargin{1};
    nbands = floor(numel(F)/2);
    if isnumeric(first) && isvector(first) && numel(first) == nbands
        W = first(:).';
        extraCallArgs = varargin(2:end);
    else
        extraCallArgs = varargin;
    end
end
if isempty(W)
    % 默认权重向量（每带为 1），与 firpm 的行为一致
    nbands = floor(numel(F)/2);
    W = ones(1, nbands);
end
% 验证 W 的有效性
if ~(isnumeric(W) && isvector(W) && all(isfinite(W)) && all(W >= 0))
    errs{end+1} = 'W (weights) must be a numeric nonnegative finite vector with one entry per band.';
end

if ~isempty(errs)
    report.errors = errs; report.messages = msgs; report.warnings = warns_struct; report.warnings_messages = warns_msgs; return;
end

% ---- 构建合理的 GF（频率网格） ----
LGRID = 16;
GF = [];
totalBW = max(1e-12, F(end) - F(1));
for k = 1:2:(numel(F)-1)
    a = F(k); b = F(k+1);
    span = max(0, b - a);
    if span == 0
        continue;
    end
    pts = max(3, ceil(LGRID * max(1, order) * span / max(0.01,totalBW)));
    if k < numel(F)-1
        g = linspace(a, b, pts+1); g = g(1:end-1);
    else
        g = linspace(a, b, pts);
    end
    GF = [GF, g];
end
GF = unique(GF);
if isempty(GF)
    errs{end+1} = 'Constructed frequency grid GF is empty (no pass/stop bands found).';
    report.errors = errs; report.messages = msgs; report.warnings = warns_struct; report.warnings_messages = warns_msgs; return;
end

% 先将 GF 存入 report
report.GF = GF;
msgs{end+1} = sprintf('Constructed GF with %d points on [%.6g, %.6g].', numel(GF), GF(1), GF(end));

% ---- defaults 调用（cell -> positional 回退），记录 warnings 为结构化 ----
SYM = '';
defaultsCallForm = 'none';
try
    % 在进行 defaults 调用前，构造 defaultsCell 和 positional 参数组（你原来的代码已做）
    defaultsCell = [{order, F, [], W}, extraArgs{:}, extraCallArgs{:}];
    
    % 根据检测到的 A-arg 风格优先尝试相应的 defaults 调用形式
    try
        if isfield(report,'AargStyle') && strcmpi(report.AargStyle,'positional')
            % 优先尝试 positional-style defaults（因为检测表明 A 多为位置参数）
            try
                out = feval(fh, 'defaults', order, F, [], W, extraArgs{:}, extraCallArgs{:});
                defaultsCallForm = 'positional';
                msgs{end+1} = 'fresp(''defaults'', ...) succeeded using positional-style call (preferred based on A-arg detection).';
            catch ME_pospref
                % 失败则回退到 cell-style
                out = feval(fh, 'defaults', defaultsCell);
                defaultsCallForm = 'cell';
                msgs{end+1} = 'fresp(''defaults'', ...) succeeded using cell-style call after positional fallback.';
            end
        else
            % 默认：先尝试 cell-style（原行为）；若失败再尝试 positional
            try
                out = feval(fh, 'defaults', defaultsCell);
                defaultsCallForm = 'cell';
                msgs{end+1} = 'fresp(''defaults'', ...) succeeded using cell-style call.';
            catch ME_cellpref
                out = feval(fh, 'defaults', order, F, [], W, extraArgs{:}, extraCallArgs{:});
                defaultsCallForm = 'positional';
                addWarning('defaults-fallback', 'fresp(''defaults'', ...) cell-style failed; positional-style fallback succeeded.');
            end
        end
    catch ME_defaults_outer
        % 保留你原先对两种都失败时的处理（记录 warning 并假设 'even'）
        addWarning('defaults-failed', sprintf(['fresp(''defaults'',...) failed for attempted forms.\n' ...
                                             'Error: %s\nProceeding with default ''even''.'], ME_defaults_outer.message));
        out = [];
        defaultsCallForm = 'none';
    end

    % 解析返回值 out（若有）
    if exist('out','var') && ~isempty(out)
        % 优先支持字符串、然后 cell（取第一个元素）
        if ischar(out) || isstring(out)
            s = lower(strtrim(char(out)));
            if any(strcmp(s,{'even','odd'}))
                SYM = s;
            else
                addWarning('defaults-unexpected', sprintf('fresp(''defaults'',...) returned unexpected string ''%s''; assuming ''even''.', s));
                SYM = 'even';
            end
        elseif iscell(out) && ~isempty(out)
            firstOut = out{1};
            if ischar(firstOut) || isstring(firstOut)
                s = lower(strtrim(char(firstOut)));
                if any(strcmp(s,{'even','odd'}))
                    SYM = s;
                else
                    addWarning('defaults-unexpected-cell', sprintf(['fresp(''defaults'',...) returned cell with first element ''%s'' not in {''even'',''odd''}; ' ...
                                                                 'assuming ''even''.'], char(firstOut)));
                    SYM = 'even';
                end
            else
                addWarning('defaults-nonstring-cell', 'fresp(''defaults'',...) returned a cell whose first element is not a string; assuming ''even''.');
                SYM = 'even';
            end
        else
            addWarning('defaults-nonstring', 'fresp(''defaults'',...) did not return a string/cell; assuming ''even''.');
            SYM = 'even';
        end
    else
        % out empty -> assume even (如原实现)
        SYM = 'even';
        if strcmp(defaultsCallForm,'none')
            % already recorded failure messages above
        else
            addWarning('defaults-empty', 'fresp(''defaults'',...) returned empty; assuming ''even''.');
        end
    end

    % 若 SYM 非 'none'，并且 F 包含负频率则记录错误（firpm 要求 F in [0,1]，但保留此检查）
    if ~isempty(SYM) && ~strcmpi(SYM,'none') && any(F < 0)
        errs{end+1} = sprintf('fresp returned SYM="%s" but frequency vector F contains negative frequencies. When SYM~=''none'', F should contain only non-negative frequencies.', SYM);
    end
catch ME
    % 外层保险（通常不会到这里）
    addWarning('defaults-unexpected-error', sprintf('Unexpected error while calling fresp(''defaults'',...): %s\nProceeding assuming ''even''.', ME.message));
    SYM = 'even';
end
report.SYM = SYM;

if ~isempty(errs)
    report.errors = errs; report.messages = msgs; report.warnings = warns_struct; report.warnings_messages = warns_msgs; return;
end

% ---- 在 GF 上调用 fresp 获取 DH/DW（更详尽诊断） ----
DH = []; DW = [];
% 主调用时将额外参数展开（支持 Name-Value 风格）
callArgs = [{order, F, GF, W}, extraArgs{:}, extraCallArgs{:}];

try
    [DH, DW] = feval(fh, callArgs{:});
    msgs{end+1} = 'Primary fresp call returned without error.';
catch ME_main
    addWarning('fresp-main-error', sprintf('Primary fresp call (with W) threw error: %s', ME_main.message));
    % 备用尝试：不带 W（有些自定义 fresp 采用此签名）
    try
        callArgs2 = [{order, F, GF}, extraArgs{:}, extraCallArgs{:}];
        out2 = feval(fh, callArgs2{:});
        msgs{end+1} = 'Alternate fresp call without W succeeded; attempting to parse outputs.';
        % 解析 out2 可能的形式
        if iscell(out2)
            if numel(out2) >= 2
                DH = out2{1}; DW = out2{2};
            elseif isscalar(out2)
                DH = out2{1}; DW = [];
            end
        elseif isnumeric(out2)
            % 如果是矩阵，尝试把前两列解释为 DH/DW
            if ismatrix(out2) && size(out2,2) >= 2
                DH = out2(:,1); DW = out2(:,2);
            else
                DH = out2; DW = [];
            end
        else
            % 未知格式
            error('Alternate fresp call returned unsupported format.');
        end
    catch ME_alt
        errs{end+1} = sprintf('Calling fresp(N,F,GF,W,...) failed: %s\nAlternate attempt (without W) also failed: %s', ME_main.message, ME_alt.message);
        report.errors = errs; report.messages = msgs; report.warnings = warns_struct; report.warnings_messages = warns_msgs; return;
    end
end

% ---- 验证并标准化 DH,DW ----
% 兼容：如果 DH 或 DW 是 cell 单元素则尝试取出
if iscell(DH) && isscalar(DH)
    DH = DH{1};
    msgs{end+1} = 'DH was a 1-element cell; extracted first element.';
end
if iscell(DW) && isscalar(DW)
    DW = DW{1};
    msgs{end+1} = 'DW was a 1-element cell; extracted first element.';
end

% 将 DH/DW 转为列向量（统一形状）
try DH = DH(:); catch, errs{end+1} = 'Failed to reshape DH to a column vector (unexpected type/shape).'; end
try DW = DW(:); catch, end

msgs{end+1} = sprintf('After normalization: numel(GF) = %d, numel(DH) = %d, numel(DW) = %d.', numel(GF), numel(DH), numel(DW));

% 基本匹配检查
if numel(DH) ~= numel(GF)
    errs{end+1} = sprintf('Length(DH) = %d does not match length(GF) = %d.', numel(DH), numel(GF));
end
if isempty(DW)
    addWarning('dw-missing', 'DW not returned by fresp (treated as missing). firpm may proceed but weights per grid point are recommended.');
else
    if numel(DW) ~= numel(GF)
        errs{end+1} = sprintf('Length(DW) = %d does not match length(GF) = %d.', numel(DW), numel(GF));
    end
end

% DW 数值检查（使用容差以避免数值误判）
if ~isempty(DW)
    % 容差：基于 DW 最大绝对值与 1 的较大者
    tol = eps(max(max(abs(DW)),1));
    if any(~isreal(DW))
        errs{end+1} = 'DW (optimization weights) must be real-valued.';
    end
    if any(~isfinite(DW))
        errs{end+1} = 'DW contains NaN or Inf entries.';
    end
    if any(DW < -tol)
        % 允许微小负数在 -tol 内出现
        errs{end+1} = 'DW contains negative entries beyond numerical tolerance; weights must be non-negative.';
    end
    if all(DW <= tol)
        errs{end+1} = 'DW is (nearly) all zeros; at least some positive weight required.';
    end
end

% DH 数值检查
if any(~isfinite(real(DH))) || any(~isfinite(imag(DH)))
    errs{end+1} = 'DH contains NaN or Inf (real or imaginary part).';
end

% 记录 DH/DW/GF
report.DH = DH;
report.DW = DW;
report.GF = GF;

% 完成
if isempty(errs)
    report.ok = true;
    msgs{end+1} = sprintf('fresp appears valid for use with firpm. Function: %s. defaults-call-form: %s', fh_handle, defaultsCallForm);
else
    report.ok = false;
end

% 在最终返回 report 之前（在函数末尾，设置 report 字段）
% 将 aInfo 中有价值的部分拷贝到 report.AargInfo（如果存在）
if isfield(report,'AargInfo') && ~isempty(report.AargInfo)
    ainf = report.AargInfo;
    % 只保留若干可打印字段（安全）
    keep = struct();
    if isfield(ainf,'nvTriedKeys'), keep.nvTriedKeys = ainf.nvTriedKeys; end
    if isfield(ainf,'posOk'), keep.posOk = ainf.posOk; end
    if isfield(ainf,'nvOk'),  keep.nvOk  = ainf.nvOk;  end
    if isfield(ainf,'posErr') && ~isempty(ainf.posErr), keep.posErr = ainf.posErr; end
    if isfield(ainf,'nvErrs') && ~all(cellfun(@isempty, ainf.nvErrs)), keep.nvErrs = ainf.nvErrs; end
    report.AargInfo = keep;
end

report.messages = [msgs, {'Validation completed.'}];
report.warnings = warns_struct;              % 结构化 warnings（推荐新接口）
report.warnings_messages = warns_msgs;       % 兼容旧 GUI（原先为 cell）
report.errors = errs;
end

% 检测 firpm 的 fresp 中 A 的传参风格
function [style, info] = detectFirpmFrespAStyle(frespInput)
% DETECTFIRPMFRESPASTYLE  检测 firpm 的 fresp 中 A 的传参风格
%
% [style, info] = detectFirpmFrespAStyle(frespInput)
%
% 输入 frespInput：
%   - function handle (例如 @firpm_fresp_example)
%   - 函数名称字符串 (例如 'firpm_fresp_example')
%   - cell 数组（firpm 风格）：{@fresp, extra1, extra2, ...}
%
% 返回：
%   style - 字符串：'positional'|'namevalue'|'both'|'none'|'unknown'
%   info  - 结构体，包含诊断信息：
%       .posOk/.nvOk (logical) 表示相应调用是否成功
%       .posErr/.nvErr (string) 为失败时捕获的错误信息（posErr 为位置参数总体错误，nvErrs 为逐键错误）
%       .nvErrs (cell) - 每个尝试键对应的错误信息（字符串）
%       .nvTriedKeys (cell) - 实际尝试的 Name-Value 键
%       .triedPos/.triedNV (logical) 表示是否做了对应的尝试
%       .callableName (string) 被测函数的名字（若能解析）
%
% 示例：
%   % 1) 直接传函数句柄（假设函数在路径上）
%   style = detectFirpmFrespAStyle(@firpm_fresp_example);
%   disp(style);
% 
%   % 2) 传入 cell（如 firpm 风格）
%   style = detectFirpmFrespAStyle({@firpm_fresp_example, [0 0 1 1]});    % 位置参数风格
%   disp(style);
% 
%   style = detectFirpmFrespAStyle({@firpm_fresp_example, 'A', [0 0 1 1]}); % Name-Value 风格
%   disp(style);
% 
% 说明（检测策略）：
%   1) 若输入是 cell（带额外参数），优先静态解析 cell 中的额外项：
%        - 如果 cell{2} 存在且不是字符串 -> 很可能是位置参数传入 A（positional）。
%        - 若 cell 中包含键 'A' / 'a' / 'amp' / 'amplitude'（不区分大小写） -> 存在 name-value 传入。
%      若解析能判定，则直接返回相应结果（也可能返回 'both'）。
%   2) 若输入仅为函数句柄或名字符串，函数会尝试实际调用：
%        - 以安全的合成网格与权值，分别尝试调用 fresp(..., A) 与 fresp(..., key, A)
%          对于 Name-Value，会循环尝试候选键直到成功。
%        - 若调用成功（返回合适长度的 DH/DW），则判定为相应风格。
%   3) 若两种调用都失败，则返回 'none'（未检测到 A）或 'unknown'（无法判定）。
%
% 注意：动态检测会实际调用 fresp，请在可控环境下运行（多数 fresp 是快速且无副作用的）。
%
% 兼容性：R2025b 及更高版本应该正常工作.

% ---- 初始化输出 ----
style = 'unknown';
info = struct( ...
    'posOk', false, 'nvOk', false, ...
    'posErr', "", 'nvErr', "", ...
    'nvErrs', {{ }}, 'nvTriedKeys', {{ }}, ...
    'triedPos', false, 'triedNV', false, ...
    'callableName', "" );

% ---- 候选 Name-Value 键（不区分大小写） ----
% 原处替换为（示例，可继续增补）
candidateKeys = { ...
  'a', 'amp', 'amp_vec', 'a_vec', 'a_vecs', 'amplitude', 'amplitudes', ...
  'amplitude_vec', 'amplitude_vector', 'amplitudevector', 'av', 'avec', ...
  'a_value', 'A_vec', 'A_val', 'Avalue', 'gain', 'gains', 'ampl', 'ampl_vec' ...
};
% 为保险起见，把列表标准化为小写并去重
candidateKeys = unique(lower(candidateKeys));

% ---- 解析输入类型 ----
fh = [];
extraFromCell = {};
if iscell(frespInput)
    if isempty(frespInput)
        style = 'none';
        return;
    end
    fh = frespInput{1};
    if length(frespInput) >= 2
        extraFromCell = frespInput(2:end);
    end
elseif isa(frespInput, 'function_handle') || ischar(frespInput) || isstring(frespInput)
    fh = frespInput;
else
    error('detectFirpmFrespAStyle:BadInput', 'frespInput must be a function handle, function name, or a cell like {@fresp, ...}.');
end

% 解析可读名称
try
    if isa(fh,'function_handle')
        info.callableName = func2str(fh);
    else
        info.callableName = char(fh);
    end
catch
    info.callableName = '';
end

% ---- 如果是 cell 且含额外项，先做静态检查（快速判定） ----
posA = false;
nvA  = false;
if ~isempty(extraFromCell)
    % 若第一个额外参数不是字符串/char/string，则很有可能是位置参数 A
    firstExtra = extraFromCell{1};
    if ~(ischar(firstExtra) || (isstring(firstExtra) && isscalar(firstExtra)))
        posA = true;
    end
    % 扫描 Name-Value 键（匹配 candidateKeys）
    i = 1;
    while i <= numel(extraFromCell)
        kv = extraFromCell{i};
        if ischar(kv) || (isstring(kv) && isscalar(kv))
            kvl = char(kv);
            for k = 1:length(candidateKeys)
                if strcmpi(kvl, candidateKeys{k})
                    % 确保后面有对应值
                    if i+1 <= numel(extraFromCell)
                        nvA = true;
                    end
                    break;
                end
            end
            i = i + 2;
        else
            i = i + 1;
        end
    end
    % 决策：若能明确（posA/nvA），直接返回
    if posA && nvA
        style = 'both';
        info.posOk = true; info.nvOk = true;
        return;
    elseif posA
        style = 'positional';
        info.posOk = true;
        return;
    elseif nvA
        style = 'namevalue';
        info.nvOk = true;
        return;
    end
    % 否则继续走动态尝试
end

% ---- 为动态尝试构建安全的合成参数 ----
% 这些值尽量简单、短小并满足常见 fresp 的参数形状要求
N  = 8;                              % 小阶数
F  = [0 0.3 0.4 1];                  % 典型成对边界（长度为偶数）
GF = linspace(0,1,20);               % 网格（长度 >= 1）
W  = [1 1];                          % 两个带的权重
A  = (1:length(F)) + 0.12345;        % 标识性幅度向量（长度 = length(F))

% ---- 尝试位置参数调用 fresp(N,F,GF,W,A) ----
try
    info.triedPos = true;
    % 优先尝试标准两输出 [DH,DW] = fresp(...)
    try
        [DH, DW] = feval(fh, N, F, GF, W, A);
    catch
        % 若直接两输出失败，尝试单输出然后解析
        out = feval(fh, N, F, GF, W, A);
        if iscell(out) && numel(out) >= 2
            DH = out{1}; DW = out{2};
        else
            DH = out;
            try
                [~, DW] = feval(fh, N, F, GF, W, A);
            catch
                DW = [];
            end
        end
    end

    % 验证 DH/DW 的尺寸合理性（必须与 GF 尺寸兼容）
    if isnumeric(DH) && numel(DH) == numel(GF)
        info.posOk = true;
    else
        % 只要返回的是数值且长度 >=1 也认为尝试成功（许多 fresp 返回列向量或复数）
        if isnumeric(DH) && numel(DH) >= 1
            info.posOk = true;
        else
            info.posOk = false;
            info.posErr = "positional returned unexpected DH shape/type.";
        end
    end
catch MEpos
    info.posOk = false;
    info.posErr = sprintf('%s: %s', class(MEpos), MEpos.message);
end

% ---- 尝试 Name-Value 调用 fresp(N,F,GF,W, key, A) ----
% 依次尝试 candidateKeys 中的每个键（直到成功）
info.nvErrs = cell(1, numel(candidateKeys));
info.nvTriedKeys = {};
for k = 1:numel(candidateKeys)
    keyName = candidateKeys{k};
    try
        info.triedNV = true;
        info.nvTriedKeys{end+1} = keyName; 
        % 先尝试两输出形式
        try
            [DH2, DW2] = feval(fh, N, F, GF, W, keyName, A);
        catch
            % 退到单输出解析
            out2 = feval(fh, N, F, GF, W, keyName, A);
            if iscell(out2) && numel(out2) >= 2
                DH2 = out2{1}; DW2 = out2{2};
            else
                DH2 = out2;
                try
                    [~, DW2] = feval(fh, N, F, GF, W, keyName, A);
                catch
                    DW2 = [];
                end
            end
        end

        % 验证
        if isnumeric(DH2) && numel(DH2) == numel(GF)
            info.nvOk = true;
            % 记录成功并跳出循环
            info.nvErr = "";
            info.nvErrs{k} = "";
            break;
        else
            if isnumeric(DH2) && numel(DH2) >= 1
                info.nvOk = true;
                info.nvErrs{k} = "";
                break;
            else
                info.nvOk = false;
                info.nvErrs{k} = "namevalue returned unexpected DH shape/type.";
            end
        end
    catch MEnv
        info.nvOk = false;
        info.nvErrs{k} = sprintf('%s: %s', class(MEnv), MEnv.message);
    end
end

% 如果没有尝试任何键（不该发生，但保险处理）
if isempty(info.nvTriedKeys)
    info.triedNV = false;
end

% ---- 根据尝试结果给出最终结论 ----
if info.posOk && info.nvOk
    style = 'both';
elseif info.posOk
    style = 'positional';
elseif info.nvOk
    style = 'namevalue';
else
    % 如果两个都没成功，但两个尝试都没有进行（极少数情况），设置 unknown 或 none
    if ~info.triedPos && ~info.triedNV
        style = 'unknown';
    else
        % 两个尝试都做了但都失败 —— 多数意味着该 fresp 不接受 A，或需要不同的调用
        style = 'none';
    end
end

end

%% ---- 严格校验用于 cfirpm 的用户自定义 fresp (修正版) ---- 
% 变更清单（简要）
% - 严格增序：把 issorted(f) 改为 if any(diff(f) <= 0)，确保没有重复边界（这是 
%   firpm/cfirpm 的真实要求）。
% - 对称性插值修正：修复原来错误地把"索引"作为频率用于 interp1 的 bug；现在用真实的
%   频率值 gf_pos / abs(gf_neg) 做插值，并根据 sym 类型（even/odd/real）选择比较方式，
%   计算粗略相对误差并在较大差异时 warn。
% - dw 检查更直观：如果存在负值立即 fatal，如果所有权重都非正（<=0）也 fatal；同时
%   对复杂数权重给 warn。移除了原先容易混淆的 eps/realmin 组合判断。
% - ThrowOnError 更灵活：允许 0/1 或 true/false 输入（并转换为 logical）。
% - 保留并谨慎联调了 defaults 的 cell/positional 两种尝试、dh/dw 的 cell-to-vector 
%   兼容、GFpoints 默认策略与超大值 warn，以及最终的返回结构与 msgs 收集机制。
%
% - 使用 detect_cfirpmFresp_param_style()检测传参风格 (Name-Value 或者 Positional)

function result = validateFresp(frespInput, f, N, varargin)
% validateFresp  严格校验用于 cfirpm 的用户自定义 fresp
%
% 用法:
%   result = validateFresp(frespInput, f, N)
%   result = validateFresp(frespInput, f, N, W)
%   result = validateFresp(..., Name,Value)
%   result = validateFresp(..., 'W', W, 'ExtraArgs', {param1, param2, param3, ...}, ...)
%
% 必选:
%   frespInput  - function handle 或 函数名字符串，例如 @myfresp 或 'myfresp'
%   f           - 频率向量 (必须为实数，严格递增，偶数长度，范围 [-1,1])
%   N           - 滤波器阶数 (非负整数)
%
% 可选 Name-Value:
%   'W'           - band weights (长度应为 length(f)/2)
%   'ThrowOnError'- true/false 或 1/0 (默认 true). 如果为 true, 在发现错误时抛出 MException
%   'GFpoints'    - 网格点数，用于测试常规 fresp 调用（默认 = max(512, 16*N+128))
%   'ExtraArgs'   - cell array，传给 fresp 的额外参数
%
% 返回 (结构体):
%   result.isValid     - true/false
%   result.messages    - cell array 的诊断信息
%   result.symDefault  - fresp('defaults',...) 返回的 sym (如果可用)
%   result.testGF      - 用于测试的频率网格
%   result.dh_test     - fresp 在 testGF 上返回的 dh（如果可用）
%   result.dw_test     - fresp 在 testGF 上返回的 dw（如果可用）
%   result.frespName   - 解析出的 fresp 名称/描述
%   result.detectParamStyle  - 解析出的传参风格 (Name-Value 或者 Positional)

% 说明: 本函数默认在发现致命问题时抛出错误（ThrowOnError = true）。
%

% ------------- 参数解析 -------------
p = inputParser;
p.FunctionName = mfilename;
addRequired(p,'frespInput');
addRequired(p,'f',@(x)isnumeric(x) && isvector(x));
addRequired(p,'N',@(x)isnumeric(x) && isscalar(x) && isfinite(x) && x>=0);
addParameter(p,'W',[],@(x)isnumeric(x) && isvector(x));
% Accept logical or numeric 0/1 for ThrowOnError
addParameter(p,'ThrowOnError',true,@(x)islogical(x) || (isnumeric(x) && isscalar(x) && (x==0 || x==1)));
addParameter(p,'GFpoints',[],@(x)isnumeric(x) && isscalar(x) && x>0);
addParameter(p,'ExtraArgs',{},@(x)iscell(x));
parse(p,frespInput,f,N,varargin{:});
W = p.Results.W;
throwOnError = logical(p.Results.ThrowOnError);
GFpoints = p.Results.GFpoints;
extraArgs = p.Results.ExtraArgs;

msgs = {}; % 收集信息/错误
isValid = true;

% helper for error handling
    function fatal(msg)
        msgs{end+1} = ['FATAL: ' msg];
        isValid = false;
        if throwOnError
            err = MException('validateFresp:Fatal', msg);
            err = addCause(err, MException('validateFresp:Context', strjoin(msgs, '\n')));
            throw(err);
        end
    end

    function warn(msg)
        msgs{end+1} = ['WARN: ' msg];
    end

    function info(msg)
        msgs{end+1} = ['OK: ' msg];
    end

% ------------- 1) 校验 f -------------
if isempty(f)
    fatal('Frequency vector f is empty.');
end
if ~isreal(f)
    fatal('Frequency vector f must be real-valued.');
end
if any(isnan(f)) || any(isinf(f))
    fatal('Frequency vector f contains NaN or Inf.');
end
% STRICT monotonic increasing check (fix: use diff <= 0 to enforce strictness)
if any(diff(f) <= 0)
    fatal('Frequency vector f must be strictly increasing (no repeated edges).');
end
if mod(length(f),2) ~= 0
    fatal('Frequency vector f must have even length.');
end
if any(f < -1) || any(f > 1)
    fatal('Frequency vector f elements must be in [-1, 1].');
end
info('Frequency vector f passes basic shape/range checks.');

% ------------- 2) 校验 N -------------
if ~(isfinite(N) && N==floor(N) && N>=0)
    fatal('N (filter order) must be a non-negative integer.');
end
info(sprintf('Filter order N = %d OK.', N));

% ------------- 3) 校验 W（若提供） -------------
nbands = length(f)/2;
if ~isempty(W)
    if length(W) ~= nbands
        fatal(sprintf('W length mismatch: expected %d (one weight per band), got %d.', nbands, length(W)));
    end
    if any(~isfinite(W)) 
        fatal('All weights in W must be finite.');
    end
    if any(W <= 0)
        fatal('All weights in W must be strictly positive.');
    end
    info('Band weights W OK.');
end

% ------------- 4) 解析并检查 fresp 可调用性 -------------
frespName = '';
fh = [];
if isa(frespInput,'function_handle')
    fh = frespInput;
    fd = functions(fh);
    if isfield(fd,'file') && ~isempty(fd.file)
        frespName = fd.function; % 名称
        % 检查文件是否在路径上（anonymous 函数没有文件）
        if ~strcmp(fd.type,'anonymous') && exist(fd.file,'file')~=2 && exist(fd.function,'file')~=2
            % 可能 Matlab 内部函数或未在路径
            warn(sprintf('Function handle refers to file "%s" which is not found on MATLAB path; functions() type=%s. If this is a nested/anonymous function it may be okay.', fd.file, fd.type));
        end
    else
        frespName = func2str(fh);
    end
elseif ischar(frespInput) || isstring(frespInput)
    frespName = char(frespInput);
    % 检查是否在路径上或内建
    if exist(frespName,'file')==2 || exist(frespName,'builtin')==5
        try
            fh = str2func(frespName);
        catch
            fatal(sprintf('Cannot convert string "%s" to function handle.', frespName));
        end
    else
        fatal(sprintf('Specified fresp "%s" not found on MATLAB path. Ensure file is in current folder or added to path.', frespName));
    end
else
    fatal('frespInput must be a function handle or a function name (string).');
end
info(['Resolved fresp as: ' frespName]);

% ------------------ 插入): 检测 fresp 的传参形式 ------------------
% 尝试调用 detect_cfirpmFresp_param_style 来探测 fresp 接受的参数风格
detectRes = [];
try
    if exist('detect_cfirpmFresp_param_style','file') == 2 || exist('detect_cfirpmFresp_param_style','file') == 6
        detectRes = detect_cfirpmFresp_param_style(fh);
        % 将检测结果追加到 msgs（便于调试/显示）
        msgs{end+1} = sprintf('INFO: detect_cfirpmFresp_param_style executed; recommendation: %s', ...
                              tryGetField(detectRes,'recommendation','(no recommendation)'));
        % 将各重要布尔字段也记录成 diagnostic messages
        fieldsToShow = {'supports_defaults_positional','supports_defaults_namevalue', ...
                        'supports_regular_positional','supports_regular_namevalue'};
        for k = 1:numel(fieldsToShow)
            fld = fieldsToShow{k};
            try
                val = detectRes.(fld);
                msgs{end+1} = sprintf('INFO: detect.%s = %d', fld, double(logical(val)));
            catch
                % ignore missing fields
            end
        end
        info('Parameter-style detection completed.');
    else
        msgs{end+1} = 'WARN: detect_cfirpmFresp_param_style not found on MATLAB path; skipping param-style detection.';
    end
catch ME
    % 不让 detect 的错误影响主流程：仅记录 warn
    msgs{end+1} = sprintf('WARN: detect_cfirpmFresp_param_style threw an error: %s', ME.message);
end


% ------------- 5) 检查 fresp('defaults',...) -------------
symVal = '';
try
    % prepare cell-style defaults arg (官方推荐形式)
    defaultsCell = {N, f, [], W};
    if ~isempty(extraArgs)
        defaultsCell = [defaultsCell, extraArgs];
    end

    % FIRST attempt: cell-form (recommended by MathWorks docs)
    try
        out = fh('defaults', defaultsCell);
        defaultsCallForm = 'cell';
    catch ME_cell
        % SECOND attempt: positional-form fallback (some user fresp 实现使用此形式)
        try
            if ~isempty(extraArgs)
                out = fh('defaults', N, f, [], W, extraArgs{:});
            else
                out = fh('defaults', N, f, [], W);
            end
            defaultsCallForm = 'positional';
            warn('fresp(''defaults'',...) cell-style call failed but positional-style succeeded. Accepting positional fallback; consider supporting cell-style (recommended).');
        catch ME_pos
            % 两种都失败 -> 记录两次异常信息，但不致命（保留原来行为）
            warn(sprintf('Calling fresp(''defaults'',...) failed: cell error: %s; positional error: %s', ME_cell.message, ME_pos.message));
            out = [];
            defaultsCallForm = 'none';
        end
    end

    % 解析返回值 out（若有）
    if exist('out','var') && ~isempty(out)
        if ischar(out) || isstring(out)
            symVal = char(out);
        elseif iscell(out) && ~isempty(out) && (ischar(out{1}) || isstring(out{1}))
            symVal = char(out{1});
            warn('fresp(''defaults'',...) did not return a char/string directly but a cell; using first element as sym.');
        else
            warn('fresp(''defaults'',...) did not return a char/string. cfirpm may still work if fresp handles defaults differently.');
        end
    end

    if ~isempty(symVal)
        allowed = {'none','even','odd','real'};
        if ~ismember(lower(symVal), allowed)
            warn(sprintf('sym returned by fresp(''defaults'',...) = "%s" is not one of the expected values. Expected one of %s.', symVal, strjoin(allowed,', ')));
        else
            info(sprintf('fresp defaults sym = "%s" (via %s-style call).', symVal, defaultsCallForm));
            % If sym ~= 'none', f must not contain negative freqs
            if ~strcmpi(symVal,'none') && any(f < 0)
                fatal(sprintf('fresp returned sym="%s" but frequency vector f contains negative frequencies. When sym ~= ''none'', f should contain only non-negative frequencies.', symVal));
            end
        end
    end

catch ME
    % 这个外层 catch 仅为保险：保留原有行为（将错误作为 warn）
    warn(sprintf('Calling fresp(''defaults'',...) failed with unexpected error: %s', ME.message));
end


% ------------- 6) 常规调用测试：生成 GF 并调用 fresp -------------
% 生成测试网格 GF（保证在 f(1)..f(end) 上均匀）
if isempty(GFpoints)
    GFpoints = max(512, 16*N + 128);
end
% 若 GFpoints 极大，给出警示（防止 GUI 卡死）
if GFpoints > 100000
    warn(sprintf('GFpoints = %d is very large; this may be slow. Consider lowering GFpoints.', GFpoints));
end
info(sprintf('Using GFpoints = %d to build test grid on [%.6g, %.6g].', GFpoints, f(1), f(end)));
gf = linspace(f(1), f(end), GFpoints).';


% 调用 fresp: [dh, dw] = fresp(N, f, gf, W, extraArgs...)
dh = [];
dw = [];
try
    info('Attempting fresp call with signature: fh(N, f, gf, W, extraArgs...)');
    if isempty(W)
        [dh, dw] = fh(N, f, gf, [], extraArgs{:});
    else
        [dh, dw] = fh(N, f, gf, W, extraArgs{:});
    end
    info('Primary fresp call returned without throwing.');
catch ME
    warn(sprintf('Primary fresp call threw error: %s', ME.message));
    % 一些 fresp 可能返回只有 dh（不返回 dw），或以不同签名实现
    % 尝试捕获多种返回形式
    try
        tmp = fh(N, f, gf); % 再试一次不传 W
        if iscell(tmp)
            if numel(tmp) >= 2
                dh = tmp{1}; dw = tmp{2};
            elseif isscalar(tmp)
                dh = tmp{1};
            end
        else
            % 如果返回向量，假设是 dh
            dh = tmp;
        end
        warn(['Primary fresp call failed but alternative call returned something: ' ME.message]);
    catch ME2
        fatal(['Calling fresp(N,f,gf,...) failed: ' ME.message]);
    end
end

% ----- 在验证 dh/dw 之前：统一形状（兼容 row/col 返回）并记录原始尺寸 -----
% 记录并规范 dh
if exist('dh','var') && ~isempty(dh)
    origDhSize = size(dh);
    % 如果是 cell 且单元素，尝试取第一个元素
    if iscell(dh) && isscalar(dh)
        dh = dh{1};
        info('dh was a 1-element cell; extracted first element.');
    end
    % 将 dh 变为列向量（方便后续 length/gf 比较）
    dh = dh(:);
    info(sprintf('dh original size %dx%d -> normalized to %dx%d.', origDhSize(1), origDhSize(2), size(dh,1), size(dh,2)));
else
    % dh 为空将在后面被 fatal 捕获（保持原逻辑）
end

% 记录并规范 dw（若存在）
if exist('dw','var') && ~isempty(dw)
    origDwSize = size(dw);
    if iscell(dw) && isscalar(dw)
        dw = dw{1};
        info('dw was a 1-element cell; extracted first element.');
    end
    dw = dw(:);
    % guard origDwSize reporting if defined
    try
        info(sprintf('dw original size %dx%d -> normalized to %dx%d.', origDwSize(1), origDwSize(2), size(dw,1), size(dw,2)));
    catch
        % ignore if origDwSize not set
    end
end


% 验证 dh
if isempty(dh)
    fatal('fresp did not return desired response dh when called on a test grid.');
end
if ~isvector(dh) || length(dh) ~= length(gf)
    fatal(sprintf('dh must be a vector with same length as test GF (%d). Received length %d.', length(gf), length(dh)));
end
if any(isnan(dh)) || any(isinf(dh))
    fatal('dh contains NaN or Inf.');
end
info('dh returned by fresp OK.');

% 验证 dw
if isempty(dw)
    warn('fresp did not return dw (weights per grid point). cfirpm expects dh and dw; proceed but this may be problematic.');
else
    if ~isvector(dw) || length(dw) ~= length(gf)
        fatal(sprintf('dw must be a vector with same length as test GF (%d). Received length %d.', length(gf), length(dw)));
    end
    if any(isnan(dw)) || any(isinf(dw))
        fatal('dw contains NaN or Inf.');
    end
    if ~isreal(dw)
        warn('dw contains complex values; expecting real-valued weights.');
    end
    % Simplified and clearer weight checks
    if any(dw < 0)
        fatal('dw contains negative values; weights must be non-negative.');
    end
    if all(dw <= 0)
        fatal('All values in dw are <= 0. Expect positive weights at least somewhere.');
    end
    info('dw returned by fresp OK.');
end

% ------------- 7) 额外一致性检查（非必须但建议） -------------
% 若 sym == 'even' 或 'odd' 等约束存在，可做一些简单约束检查（例如 dh 对称性）
if ~isempty(symVal) && ~strcmpi(symVal,'none')
    % 对称性检查 (修正：修复原代码中使用"索引作为频率"的 bug)
    % 只做温和的粗检：在 gf 同时覆盖负/正频率时比较对应对称点的相对误差
    if any(gf < 0) && any(gf > 0)
        try
            % 提取正频率段和负频率段及对应 dh
            gf_pos = gf(gf >= 0);
            gf_neg = gf(gf <= 0); % 负端含 0
            dh_pos = dh(gf >= 0);
            dh_neg = dh(gf <= 0);

            if ~isempty(gf_pos) && ~isempty(gf_neg)
                % 将正频率的 dh 插值到 |gf_neg| 点（对应负频率的绝对值）
                % 注意：用频率值而非索引作为插值自变量（修正 bug）
                dh_pos_interp_at_neg = interp1(gf_pos, dh_pos, abs(gf_neg), 'linear', NaN);

                % 根据 sym 类型选择比较方式
                switch lower(symVal)
                    case 'even'
                        % even -> dh(-w) ~= dh(w) (实值偶对称假设)
                        compareRef = dh_pos_interp_at_neg;
                        compareTarget = dh_neg;
                    case 'odd'
                        % odd -> dh(-w) ~= -dh(w)
                        compareRef = -dh_pos_interp_at_neg;
                        compareTarget = dh_neg;
                    case 'real'
                        % real (一般指实值或共轭对称) -> dh(-w) ~= conj(dh(w))
                        compareRef = conj(dh_pos_interp_at_neg);
                        compareTarget = dh_neg;
                    otherwise
                        compareRef = dh_pos_interp_at_neg;
                        compareTarget = dh_neg;
                end

                validIdx = ~isnan(compareRef) & ~isnan(compareTarget);
                if any(validIdx)
                    % 计算最大相对误差（温和检验）
                    numer = abs(compareTarget(validIdx) - compareRef(validIdx));
                    denom = max(abs(compareTarget(validIdx)), eps);
                    relerr = max(numer ./ denom);
                    info(sprintf('sym = %s reported by fresp; coarse symmetry relerr = %.3g', symVal, relerr));
                    % 仅在非常离谱时发出警告
                    if relerr > 1e-2 % 1% as粗略阈值，可视情形调整
                        warn(sprintf('Symmetry coarse-check relerr = %.3g (sym=%s). This may indicate inconsistency between reported sym and dh.', relerr, symVal));
                    end
                end
            end
        catch ME
            % 如果对称性检查失败，不致命；仅记录 warn
            warn(['Symmetry coarse-check failed: ' ME.message]);
        end
    end
end

% ------------- 8) 总结并返回 -------------
result.isValid = isValid;
result.messages = msgs;
result.symDefault = symVal;
result.testGF = gf;
result.dh_test = dh;
result.dw_test = dw;
result.frespName = frespName;
result.detectParamStyle = detectRes;

if ~isValid && ~throwOnError
    % 如果不抛出错误但标记为无效，返回错误信息
    warning('validateFresp:ValidationFailed', 'Validation detected issues. See result.messages for details.');
end

end

% Helper nested function to safely fetch field string
function out = tryGetField(s, fieldName, defaultVal)
    out = defaultVal;
    try
        if isstruct(s) && isfield(s,fieldName)
            tmp = s.(fieldName);
            if ischar(tmp) || isstring(tmp)
                out = char(tmp);
            else
                out = mat2str(tmp);
            end
        end
    catch
    end
end

function result = detect_cfirpmFresp_param_style(fresp)
% DETECT_CFIRPMFRESP_PARAM_STYLE  检测一个 cfirpm-style fresp 函数接受哪种传参形式
%
%   result = detect_cfirpmFresp_param_style(fresp)
%
% 输入:
%   fresp - 函数句柄或函数名字符串 (例如 @cfirpm_fresp_example 或 'cfirpm_fresp_example')
%
% 输出 result (结构体):
%   .supports_defaults_positional  - bool: 'defaults' 调用下接受位置参数 (cell 中位置参数)
%   .supports_defaults_namevalue   - bool: 'defaults' 调用下接受名-值对
%   .supports_regular_positional   - bool: 常规调用 (N,f,gf,W,...) 接受位置参数
%   .supports_regular_namevalue    - bool: 常规调用接受名-值对
%   .supports_positional           - bool: 任一位置参数支持
%   .supports_namevalue            - bool: 任一名值对支持
%   .notes                         - cell array of diagnostic messages
%
% 说明:
%   - 函数会对 'defaults' 分支与常规调用各做一次位置式 & 名-值式尝试。
%   - 使用 try/catch 捕获错误，且会对返回值类型做基本校验（'defaults' 期望字符输出，
%     常规调用期望向量输出 dh，dw）。
%   - 该检测是启发式的：如果 fresp 的实现依赖非常严格的输入（比如需要特殊的 f 向量长度）
%     可能需要你提供更贴近真实情况的样本参数来做检测（可按需要修改本函数内的样本）。
%
% 示例:
%   r = detect_cfirpmFresp_param_style(@cfirpm_fresp_example);
%   disp(r)
% 
% 改进_V1：名-值对试探支持多种常见别名组合，并记录成功变体
% 
% 改进_V2：对 位置参数 与 名-值对 尝试不同子集（包括最小子集，例如只传 'a'），并记录成功变体
%


if nargin < 1
    error('需要传入 fresp 函数句柄或函数名。');
end

% 规范化 fresp 为函数句柄
if ischar(fresp) || isstring(fresp)
    frespHandle = str2func(char(fresp));
elseif isa(fresp, 'function_handle')
    frespHandle = fresp;
else
    error('fresp 必须是函数句柄或函数名字符串。');
end

% 返回结构体初始化
result = struct();
result.supports_defaults_positional = false;
result.supports_defaults_namevalue  = false;
result.supports_regular_positional  = false;
result.supports_regular_namevalue   = false;
result.supports_positional = false;
result.supports_namevalue  = false;
result.notes = {};
result.successful_defaults_nv_variants = {}; % 记录成功的 defaults 名-值变体
result.successful_regular_nv_variants  = {}; % 记录成功的 regular 名-值变体
result.successful_regular_positional_variants = {}; % 记录成功的常规位置参数变体

% -----------------------
% 样本参数（根据需要可调整）
sampleN = 10;
sample_f = [-1 0 0.5 1];
sample_W = [];
sample_gf = linspace(-1,1,64)';

% 语义与示例值
canonical_names = {'type','a','d','fc','trans'};
canonical_values = {'lowpass', [], 0, 0.4, 0.05};

% 常见别名集合（可扩展）
name_variants.type  = {'type','Type','filterType','ftype','filtertype'};
name_variants.a     = {'A','a','Amp','amp','amplitude','Amplitude','gain','Gain'};
name_variants.d     = {'d','D','delay','Delay','groupdelay','GroupDelay'};
name_variants.fc    = {'fc','Fc','f0','F0','cutoff','cutoff_freq','cutoffFreq','cutoff_frequency','frequency','freq'};
name_variants.trans = {'trans','Trans','transition','transitionWidth','transWidth','trans_width','transition_width'};

% orderedKeys 用于固定输出顺序
orderedKeys = {'type','a','d','fc','trans'};

% -----------------------
% 1) defaults 分支 - 位置参数试探（保留原逻辑）
pos_cell_full = {'lowpass', [], 0, 0.4, 0.05};
for k = 1:numel(pos_cell_full)
    Cpos = {sampleN, sample_f, [], sample_W};
    for ii = 1:k
        Cpos{end+1} = pos_cell_full{ii};
    end
    try
        out = feval(frespHandle, 'defaults', Cpos);
        if ischar(out) || isstring(out)
            result.supports_defaults_positional = true;
            result.notes{end+1} = 'defaults: 支持位置参数调用并返回字符串。';
        else
            result.supports_defaults_positional = true;
            result.notes{end+1} = 'defaults: 支持位置参数调用并返回非字符串（视为成功）。';
        end
    catch ME
        result.notes{end+1} = sprintf('defaults-positional: 失败 -> %s', ME.message);
    end
end

% -----------------------
% 2) defaults 分支 - 名值对试探（尝试不同子集：单键/双键/三键/全部）
try
    % 构造一个"语义键-变体首选名称"映射，便于生成名值对
    semantic_keys = canonical_names; % {'type','a','d','fc','trans'}
    default_map = containers.Map(semantic_keys, canonical_values);

    % 生成候选名（对每个语义先取别名列表的首项用于组合构造）
    candidate_names_map = containers.Map();
    for k = 1:numel(semantic_keys)
        sem = semantic_keys{k};
        if isfield(name_variants, sem)
            candidate_names_map(sem) = name_variants.(sem);
        else
            candidate_names_map(sem) = {sem};
        end
    end

    % 组合尝试策略：先试单键，然后双键，然后三键，最后全部（以保证最小子集优先）
    maxTries = 500;
    tried = 0;
    success_count = 0;

    % 尝试顺序：单键 -> 双键 -> 三键 -> 全部
    nCan = numel(semantic_keys);
    triedSets = 0;
    for kset = 1:min(3, nCan) % 1..3（优先最小子集）
        comb = nchoosek(1:nCan, kset);
        for row = 1:size(comb,1)
            if tried >= maxTries, break; end
            selIdx = comb(row,:);
            selKeys = semantic_keys(selIdx);
            try_defaults_with_semantics(selKeys);
            triedSets = triedSets + 1;
        end
        if tried >= maxTries, break; end
    end
    % 最后尝试全部（如果仍有配额）
    if tried < maxTries
        try_defaults_with_semantics(semantic_keys);
    end

    if success_count == 0
        result.notes{end+1} = 'defaults-namevalue: 未检测到成功的名-值子集（包含最小子集尝试）。';
    end

catch ME
    result.notes{end+1} = sprintf('defaults-namevalue: 主流程异常 -> %s', ME.message);
end

% -----------------------
% 3) 常规调用 - 位置参数试探
% ========== 新增：位置参数子集试探 ==========
tailKeys = orderedKeys; % {'type','a','d','fc','trans'}
% 从 default_map/ canonical_values 获取示例值
tailVals = cell(1,numel(tailKeys));
for k = 1:numel(tailKeys)
    tailVals{k} = default_map(tailKeys{k}); % 例如 'lowpass', [], 0, 0.4, 0.05
end

maxPosTries = 500;
posTried = 0;
posSuccess = 0;

% 1) 前缀式尝试：k = 1..numTail
for k = 1:numel(tailKeys)
    if posTried >= maxPosTries, break; end
    tailToSend = tailVals(1:k); % 前 k 个
    args = [ {sampleN, sample_f, sample_gf, sample_W}, tailToSend ];
    posTried = posTried + 1;
    try
        [dh,dw] = feval(frespHandle, args{:});
        if isnumeric(dh) && isnumeric(dw)
            posSuccess = posSuccess + 1;
            result.supports_regular_positional = true;
            result.notes{end+1} = sprintf('regular-positional (prefix %d): 成功，tailKeys=%s', k, strjoin(tailKeys(1:k), ','));
            result.successful_regular_positional_variants{end+1} = tailKeys(1:k);
        end
    catch ME
        result.notes{end+1} = sprintf('regular-positional (prefix %d): 失败 -> %s', k, ME.message);
    end
end

% 2) 带占位的选择性位置尝试（单索引/双索引/三索引）
% 先定义希望尝试的索引子集（优先单索引，确保至少尝试 'a' 单键）
candidateIndexSets = {};
nTail = numel(tailKeys);
% 单索引（优先把 'a' 单索引放前面）
% 找到 'a' 的索引
aIdx = find(strcmpi(tailKeys,'a'),1);
if ~isempty(aIdx)
    candidateIndexSets{end+1} = aIdx;
end
% 其他单索引
for i = 1:nTail
    if i==aIdx, continue; end
    candidateIndexSets{end+1} = i;
end
% 双索引/三索引（按组合生成，但限制总数以免爆炸）
for k = 2:3
    C = nchoosek(1:nTail,k);
    for r = 1:size(C,1)
        candidateIndexSets{end+1} = C(r,:);
    end
end

% 循环尝试每个索引子集
for s = 1:numel(candidateIndexSets)
    if posTried >= maxPosTries, break; end
    idxSet = candidateIndexSets{s};
    maxPosIndex = max(idxSet);
    % 构建 tail 占位 cell 长度 = maxPosIndex
    tailCell = repmat({[]}, 1, maxPosIndex);
    for ii = idxSet
        tailCell{ii} = tailVals{ii}; % 用示例值填充要传的位置
    end
    args = [ {sampleN, sample_f, sample_gf, sample_W}, tailCell ];
    posTried = posTried + 1;
    try
        [dh,dw] = feval(frespHandle, args{:});
        if isnumeric(dh) && isnumeric(dw)
            posSuccess = posSuccess + 1;
            result.supports_regular_positional = true;
            % 记录成功变体（用 tailKeys 名称表示）
            succKeys = tailKeys(idxSet);
            result.notes{end+1} = sprintf('regular-positional (sparse %s): 成功', strjoin(succKeys, ','));
            result.successful_regular_positional_variants{end+1} = succKeys;
        end
    catch ME
        result.notes{end+1} = sprintf('regular-positional (sparse %s): 失败 -> %s', strjoin(tailKeys(idxSet),','), ME.message);
    end
end

% 记录尝试数量等
result.notes{end+1} = sprintf('regular-positional: 尝试 %d 次，成功 %d 次。', posTried, posSuccess);
% ========== 位置参数子集试探结束 ==========

% -----------------------
% 4) 常规调用 - 名值对试探（尝试不同子集：单键/双键/三键/全部）
try
    maxTries = 800;
    tried = 0;
    success_count = 0;

    % Try single-key, two-key, three-key sets first (ensures minimal attempts like 'a' only)
    for kset = 1:min(3, numel(semantic_keys))
        comb = nchoosek(1:numel(semantic_keys), kset);
        for row = 1:size(comb,1)
            if tried >= maxTries, break; end
            selKeys = semantic_keys(comb(row,:));
            try_regular_with_semantics(selKeys);
        end
        if tried >= maxTries, break; end
    end
    % 最后尝试全部（若仍有配额）
    if tried < maxTries
        try_regular_with_semantics(semantic_keys);
    end

    if success_count == 0
        result.notes{end+1} = 'regular-namevalue: 未检测到成功的名-值子集（包含最小子集尝试）。';
    end

catch ME
    result.notes{end+1} = sprintf('regular-namevalue: 主流程异常 -> %s', ME.message);
end

% -----------------------
% 汇总与推荐
result.supports_positional = result.supports_defaults_positional || result.supports_regular_positional;
result.supports_namevalue  = result.supports_defaults_namevalue  || result.supports_regular_namevalue;

if result.supports_regular_positional && ~result.supports_regular_namevalue
    result.recommendation = '常规调用推荐使用位置参数调用 (positional)。（探测结果可能不准确，仅供参考）';
elseif result.supports_regular_namevalue && ~result.supports_regular_positional
    result.recommendation = '常规调用推荐使用名-值对调用 (name-value)。（探测结果可能不准确，仅供参考）';
elseif result.supports_regular_namevalue && result.supports_regular_positional
    result.recommendation = '常规调用时该 fresp 同时支持位置参数与名-值对；两者皆可。（探测结果可能不准确，仅供参考）';
else
    result.recommendation = '未检测到明显支持的传参形式；函数可能需要特殊参数或存在其它实现细节。';
end


% helper 函数：构造并尝试 defaults 调用（nv_keys: cell of semantic names）
function ok = try_defaults_with_semantics(nv_keys)
    ok = false;
    % 对每个语义，循环其别名变体的首 few 个（避免太多）
    % 为了提高命中率，考虑别名的前 2 项（如果存在）
    aliasChoices = cell(1, numel(nv_keys));
    for ii_k = 1:numel(nv_keys)
        semK = nv_keys{ii_k};
        variantsList = candidate_names_map(semK);
        % take up to first 2 variants (更广泛可调整)
        takeN = min(2, numel(variantsList));
        aliasChoices{ii_k} = variantsList(1:takeN);
    end
    % 现在对 aliasChoices 做笛卡尔积（嵌套循环，不用递归以清楚记录）
    % 简单实现：逐一枚举组合（如果 nv_keys 很大，这里会爆炸，但我们限制 nv_keys 长度）
    idx = ones(1, numel(nv_keys));
    limits = cellfun(@numel, aliasChoices);
    doneLoop = false;
    while ~doneLoop
        % 构造 nv_map（以 canonical keys 为基础；但只把选中语义替换为选中别名）
        nv_map = containers.Map();
        for kk = 1:numel(semantic_keys)
            nv_map(semantic_keys{kk}) = default_map(semantic_keys{kk});
        end
        % 对当前组合，替换相应键名（把选中的别名作为键）
        for kk = 1:numel(nv_keys)
            semK = nv_keys{kk};
            chosenAlias = aliasChoices{kk}{idx(kk)};
            % find canonical value
            val = default_map(semK);
            % add as chosenAlias (note: Map 支持不同键名)
            nv_map(chosenAlias) = val;
            % remove canonical key if present to avoid duplicates in ordering later
            if nv_map.isKey(semK)
                nv_map.remove(semK);
            end
        end
        % flatten nv_map into ordered nv_cell_try (preferring orderedKeys)
        fieldsNow = nv_map.keys;
        nv_cell_try = {};
        for ok_i = 1:numel(orderedKeys)
            keyWanted = orderedKeys{ok_i};
            % find a key in fieldsNow that matches canonical or variant
            foundKey = '';
            for fk = 1:numel(fieldsNow)
                fkey = fieldsNow{fk};
                if strcmpi(fkey, keyWanted) || isKey(name_variants, keyWanted) && any(strcmp(name_variants.(keyWanted), fkey))
                    foundKey = fkey;
                    break;
                end
            end
            if ~isempty(foundKey)
                nv_cell_try{end+1} = foundKey; %#ok<AGROW>
                nv_cell_try{end+1} = nv_map(foundKey); %#ok<AGROW>
            end
        end
        % 最后把剩余 fieldsNow 中未列出的也追加上（保障不丢信息）
        for fk = 1:numel(fieldsNow)
            fkey = fieldsNow{fk};
            if ~any(strcmp(fkey, nv_cell_try(1:2:end)))
                nv_cell_try{end+1} = fkey; %#ok<AGROW>
                nv_cell_try{end+1} = nv_map(fkey); %#ok<AGROW>
            end
        end

        % 构造 defaults 的第二个参数（cell）
        Cnv = {sampleN, sample_f, [], sample_W};
        for tt = 1:numel(nv_cell_try), Cnv{end+1} = nv_cell_try{tt}; end

        % 尝试调用
        tried = tried + 1;
        try
            out = feval(frespHandle, 'defaults', Cnv);
            % 如果未报错则视为成功（并做类型提示）
            if ischar(out) || isstring(out)
                result.supports_defaults_namevalue = true;
                msg = sprintf('defaults: 名-值变体成功（%s）', strjoin(nv_cell_try(1:2:end), ','));
                result.notes{end+1} = msg;
                result.successful_defaults_nv_variants{end+1} = nv_cell_try;
                success_count = success_count + 1;
                ok = true;
            else
                result.supports_defaults_namevalue = true;
                result.notes{end+1} = sprintf('defaults: 名-值变体成功但返回类型非字符串（%s）', strjoin(nv_cell_try(1:2:end), ','));
                result.successful_defaults_nv_variants{end+1} = nv_cell_try;
                success_count = success_count + 1;
                ok = true;
            end
        catch MEinner
            result.notes{end+1} = sprintf('defaults-namevalue(%s): 失败 -> %s', strjoin(nv_cell_try(1:2:end), ','), MEinner.message);
        end
        if tried >= maxTries
            doneLoop = true;
            break;
        end
        % advance indices (cartesian product)
        carry = 1;
        for ii_idx = numel(idx):-1:1
            if carry == 0, break; end
            idx(ii_idx) = idx(ii_idx) + 1;
            if idx(ii_idx) > limits(ii_idx)
                idx(ii_idx) = 1;
                carry = 1;
                if ii_idx == 1
                    doneLoop = true;
                end
            else
                carry = 0;
            end
        end
    end % while
end % nested function

% helper: 尝试常规名值子集 (nv_semantics: cell of semantic names)
function ok = try_regular_with_semantics(nv_semantics)
    ok = false;
    % alias choices (take first up to 2 variants)
    aliasChoices = cell(1, numel(nv_semantics));
    for ii_k = 1:numel(nv_semantics)
        semK = nv_semantics{ii_k};
        variantsList = candidate_names_map(semK);
        takeN = min(2, numel(variantsList));
        aliasChoices{ii_k} = variantsList(1:takeN);
    end
    % cartesian product enumerator similar to defaults helper
    idx = ones(1, numel(nv_semantics));
    limits = cellfun(@numel, aliasChoices);
    doneLoop = false;
    while ~doneLoop
        % build nv_map with canonical base then apply alias selections
        nv_map = containers.Map();
        for kk = 1:numel(semantic_keys)
            nv_map(semantic_keys{kk}) = default_map(semantic_keys{kk});
        end
        for kk = 1:numel(nv_semantics)
            semK = nv_semantics{kk};
            chosenAlias = aliasChoices{kk}{idx(kk)};
            val = default_map(semK);
            nv_map(chosenAlias) = val;
            if nv_map.isKey(semK), nv_map.remove(semK); end
        end
        % flatten into ordered nv_cell_try
        fieldsNow = nv_map.keys;
        nv_cell_try = {};
        for ok_i = 1:numel(orderedKeys)
            keyWanted = orderedKeys{ok_i};
            for fk = 1:numel(fieldsNow)
                fkey = fieldsNow{fk};
                if strcmpi(fkey, keyWanted) || (isfield(name_variants, keyWanted) && any(strcmp(name_variants.(keyWanted), fkey)))
                    nv_cell_try{end+1} = fkey; %#ok<AGROW>
                    nv_cell_try{end+1} = nv_map(fkey); %#ok<AGROW>
                    break;
                end
            end
        end
        % add remaining fields
        for fk = 1:numel(fieldsNow)
            fkey = fieldsNow{fk};
            if ~any(strcmp(fkey, nv_cell_try(1:2:end)))
                nv_cell_try{end+1} = fkey; %#ok<AGROW>
                nv_cell_try{end+1} = nv_map(fkey); %#ok<AGROW>
            end
        end

        % build args: N,f,gf,W, nv_cell_try...
        args = [{sampleN, sample_f, sample_gf, sample_W}, nv_cell_try];
        tried = tried + 1;
        try
            [dh, dw] = feval(frespHandle, args{:});
            if (isnumeric(dh) || islogical(dh)) && (isnumeric(dw) || islogical(dw))
                result.supports_regular_namevalue = true;
                msg = sprintf('regular: 名-值变体成功（%s）', strjoin(nv_cell_try(1:2:end), ','));
                result.notes{end+1} = msg;
                result.successful_regular_nv_variants{end+1} = nv_cell_try;
                success_count = success_count + 1;
                ok = true;
            else
                result.supports_regular_namevalue = true;
                result.notes{end+1} = sprintf('regular: 名-值变体返回非标准类型（%s）', strjoin(nv_cell_try(1:2:end), ','));
                result.successful_regular_nv_variants{end+1} = nv_cell_try;
                success_count = success_count + 1;
                ok = true;
            end
        catch MEinner
            result.notes{end+1} = sprintf('regular-namevalue(%s): 失败 -> %s', strjoin(nv_cell_try(1:2:end), ','), MEinner.message);
        end

        if tried >= maxTries
            doneLoop = true;
            break;
        end
        % advance indices
        carry = 1;
        for ii_idx = numel(idx):-1:1
            if carry == 0, break; end
            idx(ii_idx) = idx(ii_idx) + 1;
            if idx(ii_idx) > limits(ii_idx)
                idx(ii_idx) = 1;
                carry = 1;
                if ii_idx == 1
                    doneLoop = true;
                end
            else
                carry = 0;
            end
        end
    end % while
end % nested

end

%% ---- 增添"高通"滤波类型的广义巴特沃斯滤波器设计(my_maxflat) ---- 
function varargout = my_maxflat(n, varargin)
%MY_MAXFLAT 兼容 maxflat 的接口并支持高通选项 'high'
% 用法示例（和 maxflat 兼容）：
%   [b,a] = my_maxflat(n,m,Wn)
%   b = my_maxflat(n,'sym',Wn)
%   [b,a,b1,b2] = my_maxflat(n,m,Wn)
%   [b,a,b1,b2,sos,g] = my_maxflat(n,m,Wn)
%   [___] = my_maxflat(n,m,Wn,designflag)
% 额外支持（把 Wn 解释为高通截止）：
%   [b,a] = my_maxflat(n,m,Wn,'high')
%   b = my_maxflat(n,'sym',Wn,'high')
%   [b,a,b1,b2,sos,g] = my_maxflat(n,m,Wn,'both','high')
%
% 注意：
%   - Wn 的定义与 maxflat 一致，范围 [0,1]，1 对应 pi rad/sample。
%   - 对于 'sym' 模式，仅返回 b（线性相位 FIR），若同时请求其他输出会报错。
%   - 该函数内在调用 MATLAB 自带 maxflat 以保持行为一致。
%
% 示例一：设计高通
% n = 10; m = 2; Wn_hp = 0.2;   % Wn_hp 表示高通截止（归一化）
% [b_hp, a_hp] = my_maxflat(n, m, Wn_hp, 'high');
% freqz(b_hp, a_hp);
% 
% 示例二：设计对称线性相位 FIR 高通
% n = 10; Wn_hp = 0.5;
% b_hp = my_maxflat(n, 'sym', Wn_hp, 'high');
% freqz(b_hp,1);
% 
% 示例三：保持原样低通（不传 'high'）
% [b,a] = my_maxflat(10,2,0.2);  % 等同于 maxflat(10,2,0.2)
% freqz(b,a);
% 
% ---------- 参数解析 ----------
if nargin < 2
    error('my_maxflat: not enough input arguments.');
end

% 默认值
isSym = false;
designflag = [];
isHigh = false;

% parse varargin to find:
% - 'sym' or numeric m
% - Wn (next arg)
% - optional designflag in {'trace','plots','both'}
% - optional 'high' anywhere
args = varargin(:);
% find 'high' occurrences and remove them from args, set flag
idxHigh = find(cellfun(@(x) ischar(x) && strcmpi(x,'high'), args));
if ~isempty(idxHigh)
    isHigh = true;
    args(idxHigh) = [];
end

% now detect 'sym' or m
if isempty(args)
    error('my_maxflat: missing arguments after parsing.');
end

if ischar(args{1}) && strcmpi(args{1},'sym')
    isSym = true;
    if numel(args) < 2
        error('my_maxflat: missing Wn for ''sym'' form.');
    end
    Wn = args{2};
    rest = args(3:end);
else
    % expect m and Wn at least
    if numel(args) < 2
        error('my_maxflat: expected m and Wn (or ''sym'') in arguments.');
    end
    m = args{1};
    Wn = args{2};
    rest = args(3:end);
end

% rest may contain designflag
if ~isempty(rest)
    for ii = 1:numel(rest)
        if ischar(rest{ii}) && any(strcmpi(rest{ii},{'trace','plots','both'}))
            designflag = lower(rest{ii});
            break;
        end
    end
end

% validate Wn
if ~isnumeric(Wn) || ~isscalar(Wn) || Wn < 0 || Wn > 1
    error('my_maxflat: Wn must be a scalar in [0,1].');
end

% If 'high' requested, map to complementary lowpass cutoff
if isHigh
    Wn_lp = 1 - Wn;   % 互补截止
else
    Wn_lp = Wn;
end

% ---------- 调用内置 maxflat 设计低通原型 ----------
try
    if isSym
        if isempty(designflag)
            b_lp = maxflat(n, 'sym', Wn_lp);
        else
            b_lp = maxflat(n, 'sym', Wn_lp, designflag);
        end
        % sym 模式只会返回 b
        a_lp = []; b1_lp = []; b2_lp = []; sos_lp = []; g_lp = [];
    else
        % call with full outputs to keep convenience
        if isempty(designflag)
            [b_lp, a_lp, b1_lp, b2_lp, sos_lp, g_lp] = maxflat(n, m, Wn_lp);
        else
            [b_lp, a_lp, b1_lp, b2_lp, sos_lp, g_lp] = maxflat(n, m, Wn_lp, designflag);
        end
    end
catch ME
    rethrow(ME);
end

% ---------- 若为高通，则把低通原型进行 z -> -z 变换 ----------
if isHigh
    if isSym
        % 对称 FIR 的情况：只变换 b_lp
        k = 0:length(b_lp)-1;
        b_out = b_lp .* ((-1).^k);
        % 返回数量限制：'sym' 只能返回 b
        if nargout > 1
            error('my_maxflat: ''sym'' form only returns numerator b (cannot request more outputs).');
        end
        varargout{1} = b_out;
        return;
    else
        % 非 sym：有 b,a,b1,b2,... 等
        k_b = 0:length(b_lp)-1;
        b_out = b_lp .* ((-1).^k_b);

        k_a = 0:length(a_lp)-1;
        a_out = a_lp .* ((-1).^k_a);

        % b1, b2 也相同变换（若存在）
        if ~isempty(b1_lp)
            k_b1 = 0:length(b1_lp)-1;
            b1_out = b1_lp .* ((-1).^k_b1);
        else
            b1_out = [];
        end
        if ~isempty(b2_lp)
            k_b2 = 0:length(b2_lp)-1;
            b2_out = b2_lp .* ((-1).^k_b2);
        else
            b2_out = [];
        end

        % stability check (极点)
        poles_hp = roots(a_out);
        if any(abs(poles_hp) >= 1)
            warning('my_maxflat: transformed highpass has poles on/outside unit circle -> potential instability.');
        end

        % 生成 sos,g（使用 tf2sos）
        try
            [sos_out, g_out] = tf2sos(b_out, a_out);
        catch
            % 如果 tf2sos 不可用或出错，返回空并发出警告
            warning('my_maxflat: tf2sos failed (Signal Processing Toolbox 可能不可用)。sos,g 将为空。');
            sos_out = [];
            g_out = [];
        end

        % 归一化（使在 omega=pi 处增益为 1），仅当 freqz 可用且增益非零
        try
            Hpi = freqz(b_out, a_out, pi);  % 频率为 pi 的复值响应
            if abs(Hpi) > 0
                b_out = b_out / abs(Hpi);
                % 重新计算 sos,g（如果之前成功）
                try
                    [sos_out, g_out] = tf2sos(b_out, a_out);
                catch
                    % 忽略
                end
            else
                warning('my_maxflat: highpass gain at omega=pi is zero, skip normalization.');
            end
        catch
            % 若 freqz 不可用则跳过归一化（保守处理）
        end

        % 根据请求的输出数目打包返回
        switch nargout
            case 0
                % 没有输出，什么也不返回（与 MATLAB 风格一致）
            case 1
                varargout{1} = b_out;
            case 2
                varargout{1} = b_out;
                varargout{2} = a_out;
            case 3
                varargout{1} = b_out;
                varargout{2} = a_out;
                varargout{3} = b1_out; % 可能为空
            case 4
                varargout{1} = b_out;
                varargout{2} = a_out;
                varargout{3} = b1_out;
                varargout{4} = b2_out;
            case 5
                varargout{1} = b_out;
                varargout{2} = a_out;
                varargout{3} = b1_out;
                varargout{4} = b2_out;
                varargout{5} = sos_out;
            case 6
                varargout{1} = b_out;
                varargout{2} = a_out;
                varargout{3} = b1_out;
                varargout{4} = b2_out;
                varargout{5} = sos_out;
                varargout{6} = g_out;
            otherwise
                error('my_maxflat: supports at most 6 outputs like maxflat.');
        end
        return;
    end
else
    % ---------- 非 high（正常调用 maxflat 返回的原样输出） ----------
    % 如果是 sym 已在上面处理过，当前是非 sym 且非 high
    switch nargout
        case 0
            % 无需返回，函数已在内部用 maxflat 绘图或输出（若 designflag 指定）
        case 1
            varargout{1} = b_lp;
        case 2
            varargout{1} = b_lp;
            varargout{2} = a_lp;
        case 3
            varargout{1} = b_lp;
            varargout{2} = a_lp;
            varargout{3} = b1_lp;
        case 4
            varargout{1} = b_lp;
            varargout{2} = a_lp;
            varargout{3} = b1_lp;
            varargout{4} = b2_lp;
        case 5
            varargout{1} = b_lp;
            varargout{2} = a_lp;
            varargout{3} = b1_lp;
            varargout{4} = b2_lp;
            varargout{5} = sos_lp;
        case 6
            varargout{1} = b_lp;
            varargout{2} = a_lp;
            varargout{3} = b1_lp;
            varargout{4} = b2_lp;
            varargout{5} = sos_lp;
            varargout{6} = g_lp;
        otherwise
            error('my_maxflat: supports at most 6 outputs like maxflat.');
    end
    return;
end

end

%% ---- 用于广义巴特沃斯滤波器设计的工具：生成滤波器设计参数表格(MATLAB自带的函数) ---- 
function table = spec_table(Z,P,SYMM)
%
% table = spec_table(Z,P,SYMM);
%
% General Butterworth Filter Design
% This program decides how many zeros should lie at 
% z = -1 and how many should contribute to the passband
%
% Z : total number of zeros
% P : total number of poles
%
% % Example:
%
%   Z = 10; P = 2; 
%   table = spec_table(Z,P);
%
%  Ivan Selesnick, Rice University,
%  September 1995.
%  see: Generalized Digital Butterworth Filter Design

%  required subprograms : choose.m

if (Z <= P) 
    table = [Z 0 P 0 1];
    return
else
    table = [];
end

%Fo = (1/2)^2;   % value of mag squared at half-mag freq.
Fo = 1/2;   % value of mag squared at half-mag freq.
if SYMM
    Fo = sqrt(Fo);
end

%%%%%%% begin with all zeros at z = -1 %%%%%%%
L = Z;
N = P;
if N > 0
    if mod(N,2)==0
        c = 0;			% N even
    else
        c = choose(L-1,N);	% N odd
    end
    %%%%%%% construct polynomial for checking boundary %%%%%%
    Y = zeros(1,L+1);
    for i = 0:N
        Y(i+1) = choose(L,i)*(1-Fo)*(-1)^i;
    end
    for i = N+1:L
        Y(i+1) = choose(L,i)*(-1)^i;
    end
    Y(N+1) = Y(N+1) - c*Fo;
    Y = Y(L+1:-1:1);
    %%% extract appropriate root %%%
    r = specroot(Y);
    wo_max = acos(1-2*r);

    table = [Z, 0, P, 0, wo_max/pi];
end

%%%%%%%% first order case %%%%%%
if (Z==1) && (P==0)
    % In this case, we cannot use second generalization because it requires
    % Z > P+1, so we can only use first generalization. Therefore, using
    % Selesnick's notation, L = 1, N = 0, M = 0, F(x) = (1-x)
    % In this section we choose boundary value c=0. If we first calculate c
    % using the cutoff frequency and then try to come up the limit for wo,
    % we will have the same limit.
    
    r = 1-Fo;
    wo_max = acos(1-2*r);
    
    table = [1, 0, 0, 0, wo_max/pi];
end

%%%%%%%%% go through each and check %%%%%%%%%
for M = 1:Z-P-1
    L = Z-M;
%     k = M-1:-1:0;
%     R = [0, choose(M+N-k-1,N).*choose(L-N+k-1,k)];
%     T = [choose(M+N-k-2,N-1).*choose(L-N+k,k), 0];
    k = M+L:-1:0;
        GR = choose(M+N-k-1,M-1).*choose(M+L-1,k).*(-1).^k;
        GT = choose(M+N-k-1,M-1).*choose(M+L-1,k-1).*(-1).^(k-1);
    AGR = GR(M+L+1-N:M+L+1);
    AGT = GT(M+L+1-N:M+L+1);

    %%% ------- wo_max ---------------------------------- %%%
        if mod(N,2)==0
                c = (L-N)/(M+N);  % N even
        else
                c = (L-N)/N;      % N odd
        end
        Y = [zeros(1,M+L-N), Fo*AGR+c*Fo*AGT]-GR-c*GT;
    %%%%%%% extract appropriate root %%%
        r = specroot(Y);
        if isempty(r)
          error(message('signal:maxflat:UnableToDesign'))
        end        
        wo_max = acos(1-2*r);

        %%% ------- wo_min ---------------------------------- %%%
        if mod(N,2)==0
                c = -1;		% N even
        Y = [zeros(1,M+L-N), Fo*AGR+c*Fo*AGT]-GR-c*GT;
        else
%             c = inf; % N odd
        Y = [zeros(1,M+L-N), Fo*AGT]-GT;
        end
        %%%%%%% extract appropriate root %%%
        r = specroot(Y);
        if isempty(r)
          error(message('signal:maxflat:UnableToDesign'))
        end
        
        wo_min = acos(1-2*r);
        
    table = [table; [L,M,N, wo_min/pi, wo_max/pi]];
end

if N > 0
    M = Z-P;
    L = Z-M;
    table = [table; [L,M,N, table(Z-P,5), 1]];
end
end

function a = choose(n,k)
%
% a = choose(n,k)
% BINOMIAL COEFFICIENTS
%
% allowable inputs:
%   n : integer, k : integer
%   n : integer vector, k : integer
%   n : integer, k : integer vector
%   n : integer vector, k : integer vector (of equal dimension)
%

nv = n;
kv = k;
if (isscalar(nv)) && (length(kv) > 1)
    nv = nv * ones(size(kv));
elseif (length(nv) > 1) && (isscalar(kv))
    kv = kv * ones(size(nv));
end
a = nv;
for i = 1:length(nv)
   n = nv(i);
   k = kv(i);
   if n >= 0
      if k >= 0
         if n >= k
            c = prod(1:n)/(prod(1:k)*prod(1:n-k));
         else
            c = 0;
        end
     else
        c = 0;
     end
   else
      if k >= 0
         c = (-1)^k * prod(1:k-n-1)/(prod(1:k)*prod(1:-n-1));
      else
         if n >= k
            c = (-1)^(n-k)*prod(1:-k-1)/(prod(1:n-k)*prod(1:-n-1));
         else
            c = 0;
         end
      end
   end
   a(i) = c;
end
end

function r = specroot(Y)
r = roots(Y);
r = r(imag(r)==0);
[temp,i] = min(abs(r-0.5)); %#ok
r = r(i);
%  other alternatives:
%SN = 1e-5;
%r = newton(Y,[SN 1-SN]);
%f = @(x,p) polyval(p,x);
%r = fzero(f,.5,optimset('TolX',eps,'Display','off'),Y);
end
   
%% ----- 用于firls/fircls滤波器设计的工具,在firls/fircls"多带/高级滤波器"校验时使用(非MATLAB自带的函数，但在 MATLAB 运行时会委托系统 firchk 或者 本地化的 firchk_local 做完整校验) ---- 
function [N, msg1, msg2, msgObj] = firchk_core(N, Fend, a, exception)
% firchk_core  - firchk wrapper with fallback to firchk_local and safe checks.
% Usage (same as system firchk):
%   [N,msg1,msg2,msgObj] = firchk_core(N,Fend,A)
%   [N,msg1,msg2,msgObj] = firchk_core(N,Fend,A,exception)
%
% Behavior:
% - If system firchk exists, call it and return its outputs.
% - Else if firchk_local exists (user-provided local copy), call it.
% - Else perform a safe, limited check:
%     * validate N, Fend, A
%     * if even-symmetric (exception==false) and Fend==1 and a(end)~=0 and odd N:
%           produce warning msg2 and set N = N+1
% - This implementation intentionally avoids try/catch and codegen pragmas.

narginchk(3,4);
if nargin == 3
    exception = false;
end

% initialize outputs
msg1 = '';
msg2 = '';
if coder.target('MATLAB')
    msgObj = [];
else
    msgObj = zeros(0,1);
end

% Validate basic arguments (mirrors built-in basic checks)
if isempty(N) || length(N) > 1 || ~isnumeric(N) || ~isreal(N) || N ~= round(N) || N <= 0
    [msg1, msgObj] = constructErrorObj("error", 'signal:firchk:NeedRealPositiveOrder');
    return;
end
if isempty(Fend) || ~isnumeric(Fend) || ~isfinite(Fend) || ~isscalar(Fend)
    [msg1, msgObj] = constructErrorObj("error", 'signal:firchk:InvalidFend');
    return;
end
if Fend < 0 || Fend > 1
    [msg1, msgObj] = constructErrorObj("error", 'signal:firchk:InvalidFendRange');
    return;
end
if isempty(a) || ~isnumeric(a) || any(~isfinite(a))
    [msg1, msgObj] = constructErrorObj("error", 'signal:firchk:InvalidA');
    return;
end

% --- MATLAB execution: try system firchk first, else firchk_local if present ---
if coder.target('MATLAB')
    has_system_firchk = (exist('firchk', 'file') == 2) || (exist('firchk', 'builtin') == 5);
    has_local_firchk  = (exist('firchk_local', 'file') == 2);

    if has_system_firchk
        % call system firchk and directly forward outputs
        [N_out, msg1_out, msg2_out, msgObj_out] = firchk(N, Fend, a, exception);
        N = N_out;
        msg1 = msg1_out;
        msg2 = msg2_out;
        msgObj = msgObj_out;
        return;
    end

    if ~has_system_firchk && has_local_firchk
        % call user-provided local copy (must match signature)
        [N_out, msg1_out, msg2_out, msgObj_out] = firchk_local(N, Fend, a, exception);
        N = N_out;
        msg1 = msg1_out;
        msg2 = msg2_out;
        msgObj = msgObj_out;
        
        return;
    end

    % neither system nor local firchk found: record a warning and continue to fallback checks
    if ~has_system_firchk && ~has_local_firchk
        % Use a human-readable warn message stored in msg2 and msgObj empty
        msg2 = '未检测到系统 firchk，也未检测到 firchk_local；使用受限本地校验实现（可能与系统行为略有差异）。';
        % msgObj remains as [] (for MATLAB)
    end
end

% ----------------- Fallback (limited) checks -----------------
% Core behavior: if even-symmetric (exception==false) and Fend==1 and a(end) !=0
% and N is odd, then warn and increment N. This mirrors the essential check
% in MATLAB's firchk.

% Note: Accept scalar 'a' (documented behavior of firchk)
% Determine amplitude at the last point
amp_at_end = a(end);

if (amp_at_end ~= 0) && (Fend == 1) && (rem(N,2) == 1) && (~exception)
    [msg2_local, msgObj_local] = constructErrorObj("warning", 'signal:firchk:NeedZeroGain');
    % Append to existing msg2 if present
    if isempty(msg2)
        msg2 = msg2_local;
    else
        msg2 = sprintf('%s\n%s', msg2, msg2_local);
    end
    if isempty(msgObj) || isequal(msgObj, zeros(0,1))
        msgObj = msgObj_local;
    else
        % if msgObj already had content, keep it and ignore local msgObj
    end
    N = N + 1;
end

% return with potentially adjusted N, msg1 (possibly empty), msg2 (possibly set), msgObj set accordingly
end

function [msg, msgobj] = constructErrorObj(errorType, varargin)
% constructErrorObj : constructs the required error/warning message object.
% Accepts same error identifiers as MATLAB's firchk uses.

    if coder.target('MATLAB')
        msgobj = message(varargin{:});
        msg = getString(msgobj);
    elseif errorType == "error"
        msgobj = [];
        msg = '';
        coder.internal.error(varargin{:});
        return;
    elseif errorType == "warning"
        msgobj = [];
        msg = '';
        coder.internal.warning(varargin{:});
        return;
    else
        msgobj = [];
        msg = '';
    end
end

%% ----- showFrespExample - 在模态 uifigure 中用 Prism (可离线内嵌) 显示带行号/复制/折叠的源码预览。用于firpm/cfirpm "多带/高级滤波器"查看示例频率响应函数 -----
function showFrespExample(parent, targetFuncName, offlineFolder, preferEditor)
% SHOWFRESPEXAMPLE 使用 Prism 高亮（可内嵌离线资源）或 MATLAB 编辑器预览 .m 文件
%
% 用法：
%   showFrespExample()                                % 使用默认设置（preferEditor = true）
%   showFrespExample(parent)                          % parent = UIFigure 句柄（可选）
%   showFrespExample(parent, 'firpm_fresp_example')  % 指定目标函数名
%   showFrespExample(parent, targetFuncName, offlineFolder)
%   showFrespExample(parent, targetFuncName, offlineFolder, preferEditor)
%
% 说明：
%   SHOWFRESPEXAMPLE() 打开默认示例函数（'firpm_fresp_example.m'）的预览。
%   默认情况下，函数会先尝试在 MATLAB 编辑器中打开该文件；若无法打开，则使用应用内的 HTML 预览。
%
%   当在完整 MATLAB 桌面环境中运行时，会优先使用编辑器；在部署的 App 或无编辑器的环境中，会降级为内嵌 HTML 预览。
%
% 输入参数：
%   parent         - （可选）用于模态窗口和 uialert 的 UIFigure 句柄。可为 []。
%
%   targetFuncName - （可选）要预览的 MATLAB 函数或脚本名（字符串或 char，不带 '.m'）。
%                    默认：'firpm_fresp_example'。
%
%   offlineFolder  - （可选）包含 Prism.js 离线资源的文件夹路径（如 prism.css、prism-core.min.js、插件文件）。
%                    默认：位于此 .m 文件同目录下名为 'matlab_prism_offline' 的子文件夹。
%
%   preferEditor   - （可选）逻辑标志，指示是否优先尝试在 MATLAB 编辑器中打开文件。
%                    true （默认） - 先尝试 edit，若成功则直接返回。
%                    false          - 跳过编辑器尝试，总是使用应用内 HTML 预览。
%
% 输出参数：
%   无。该函数要么：
%     - 在 MATLAB 编辑器中打开目标文件（如果可用且首选），要么
%     - 弹出一个模态 uifigure，显示 Prism 高亮的 HTML 源码预览。
%
% 示例：
%   % 在 App Designer 的按钮回调中（优先编辑器）：
%   showFrespExample([], 'firpm_fresp_example');
%   showFrespExample(app.UIFigure, 'firpm_fresp_example');
%
%   % 强制在应用内显示 HTML 预览（例如部署的应用）：
%   showFrespExample(app.UIFigure, 'firpm_fresp_example', [], false);
%   showFrespExample(app.UIFigure, 'firpm_fresp_example', fullfile(fileparts(mfilename('fullpath')),'matlab_prism_offline'), false);
%
%   % 命令行使用：
%   showFrespExample();
%
% 说明与注意事项：
% - 如果作为独立文件使用，默认会在此 .m 文件所在目录下查找 'matlab_prism_offline' 子文件夹以获取离线 Prism 资源。
% - 当提供 parent 时，parent 应为 uifigure 句柄，以便正确调用 uialert(parent,...)。
% - 若 preferEditor==true（默认），函数会先尝试用 edit 打开目标 .m 文件；若成功则直接返回，不使用内嵌预览。
% - 若编辑器无法打开（例如运行在无桌面环境或已部署的应用），函数会退回到内嵌 HTML 预览。将 preferEditor 设为 false 可跳过编辑器尝试。
% - 设计时注重鲁棒性：若发现离线资源会优先内嵌，否则回退至 CDN。
%
% 参见： edit, uihtml, uifigure, fileread, which

% ----- defaults & param handling -----
if nargin < 1, parent = []; end
if nargin < 2 || isempty(targetFuncName), targetFuncName = 'firpm_fresp_example'; end

% Determine default offlineFolder: matlab_prism_offline next to this .m file
st = dbstack('-completenames');
if numel(st) >= 1 && ~isempty(st(1).file)
    currentFolder = fileparts(st(1).file);
else
    currentFolder = pwd;
end
if nargin < 3 || isempty(offlineFolder)
    offlineFolder = fullfile(currentFolder, 'matlab_prism_offline');
end

% preferEditor default = true
if nargin < 4 || isempty(preferEditor)
    preferEditor = true;
end

% ----- 首先（可选）尝试在 MATLAB 编辑器中打开（若用户希望并且可用） -----
if logical(preferEditor)
    try
        % 如果 edit 成功，就直接返回（不关闭 parent，以免误关闭主 GUI）
        edit(targetFuncName);
        return;
    catch MEedit
        % 编辑器打开失败（例如没有安装桌面 MATLAB 或运行环境限制），继续使用 HTML 预览
        fprintf(2, '无法在 MATLAB 编辑器中直接打开 "%s"：%s\n将尝试使用内置 HTML 预览。\n', targetFuncName, MEedit.message);
    end
end

% ----- choose alert function (prefer project-provided uialert_safe) -----
alertFn = @(p,msg,t) uialert_safe(p, msg, t);


% ----- read target .m file ----- 
funcPath = which(targetFuncName);
if isempty(funcPath)
    alertFn(parent, sprintf('未能在 MATLAB 路径中找到函数 "%s.m"。', targetFuncName), '函数未找到');
    return;
end
try
    srcText = fileread(funcPath);
catch ME
    alertFn(parent, sprintf('无法读取文件 "%s"：%s', funcPath, ME.message), '读取失败');
    return;
end

% ----- resource list (same as previously) -----
localFiles = { ...
    'prism.css',                   'css_theme'; ...
    'prism-core.min.js',           'js_core'; ...
    'prism-matlab.min.js',         'js_matlab'; ...
    'plugins/line-numbers/prism-line-numbers.min.js', 'js_ln'; ...
    'plugins/line-numbers/prism-line-numbers.min.css', 'css_ln'; ...
    'plugins/toolbar/prism-toolbar.min.js',           'js_toolbar'; ...
    'plugins/toolbar/prism-toolbar.min.css',          'css_toolbar'; ...
    'plugins/copy-to-clipboard/prism-copy-to-clipboard.min.js', 'js_copy' ...
    };

% find & load resources (recursive fallback & auto copy to expected paths)
[resources, useOffline, missing] = loadPrismResources(offlineFolder, localFiles);

% compose HTML (inline if offline, else CDN)
html = buildHtmlWithInlineAssets(srcText, funcPath, ...
    { getFieldOr(resources,'css_theme'), getFieldOr(resources,'css_ln'), getFieldOr(resources,'css_toolbar') }, ...
    { getFieldOr(resources,'js_core'), getFieldOr(resources,'js_matlab'), getFieldOr(resources,'js_ln'), getFieldOr(resources,'js_toolbar'), getFieldOr(resources,'js_copy') }, ...
    useOffline);

% write temp file & present via uihtml
htmlFile = [tempname '.html'];
fid = fopen(htmlFile, 'w', 'n', 'UTF-8');
if fid == -1
    alertFn(parent, sprintf('无法创建临时 HTML 文件：%s', htmlFile), '文件错误');
    return;
end
fwrite(fid, html, 'char');
fclose(fid);

% create modal uifigure if parent not provided
if isempty(parent) || ~isvalid(parent)
    previewFig = createCenteredUIFigure('Name', [targetFuncName ' — 源码预览 (Prism)'], 'Position', [200 150 1024 761], 'WindowStyle', 'modal');
else
    previewFig = createCenteredUIFigure('Name', [targetFuncName ' — 源码预览 (Prism)'], 'Position', [200 150 1024 760], 'WindowStyle', 'modal');
end

hHtml = uihtml(previewFig);
try
    hHtml.HTMLSource = htmlFile;
catch
    hHtml.URL = ['file://' htmlFile];
end
hHtml.Position = [8 8 previewFig.Position(3)-16 previewFig.Position(4)-16];

end

% helper subfunctions (kept local to file)
function v = getFieldOr(s, field)
    if isstruct(s) && isfield(s, field) && ~isempty(s.(field)), v = s.(field); else v = ''; end
end

function [resources, useOffline, missing] = loadPrismResources(offlineFolder, localFiles)
    resources = struct(); resolvedPaths = struct(); missing = {}; missingReasons = {};
    for k = 1:size(localFiles,1)
        relName = localFiles{k,1}; key = localFiles{k,2};
        expectedPath = fullfile(offlineFolder, relName);
        if isfile(expectedPath)
            foundPath = expectedPath;
        else
            [~, fname, fext] = fileparts(relName);
            matches = dir(fullfile(offlineFolder, '**', [fname fext]));
            if ~isempty(matches)
                foundPath = fullfile(matches(1).folder, matches(1).name);
            else
                foundPath = '';
            end
        end
        if isempty(foundPath)
            missing{end+1} = relName; %#ok<AGROW>
            continue;
        end
        try
            txt = fileread(foundPath);
            resources.(key) = txt; resolvedPaths.(key) = foundPath;
            % attempt copy to expected path if found elsewhere
            if ~strcmp(foundPath, expectedPath)
                try
                    expParent = fileparts(expectedPath);
                    if ~exist(expParent,'dir'), mkdir(expParent); end
                    copyfile(foundPath, expectedPath);
                    resolvedPaths.(key) = expectedPath;
                catch
                    % ignore copy failure
                end
            end
        catch
            missing{end+1} = relName; %#ok<AGROW>
        end
    end
    useOffline = isempty(missing);
end

function html = buildHtmlWithInlineAssets(srcText, srcPath, cssParts, jsParts, inlineFlag)
    % (Same composition as earlier; for brevity assume identical to previous implementation)
    % Implemented here to keep single-file. Use the version you previously had.
    codeHtml = htmlEscapeForPre(srcText);
    if inlineFlag
        cssJoined = strjoin(cssParts(~cellfun(@isempty, cssParts)), newline);
        jsJoined = strjoin(jsParts(~cellfun(@isempty, jsParts)), newline);
        head = sprintf('<style>\n%s\n</style>\n', cssJoined);
        foot = sprintf('<script>\n%s\n</script>\n<script>document.addEventListener("DOMContentLoaded", function(){ if(window.Prism){ Prism.highlightAll(); } });</script>', jsJoined);
    else
        version = '1.30.0';
        head = sprintf(['<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/prism/%s/themes/prism.css">', ...
                        '<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/prism/%s/plugins/line-numbers/prism-line-numbers.min.css">', ...
                        '<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/prism/%s/plugins/toolbar/prism-toolbar.min.css">'], version, version, version);
        foot = sprintf(['<script src="https://cdnjs.cloudflare.com/ajax/libs/prism/%s/components/prism-core.min.js"></script>', ...
                        '<script src="https://cdnjs.cloudflare.com/ajax/libs/prism/%s/plugins/autoloader/prism-autoloader.min.js"></script>', ...
                        '<script>Prism.plugins.autoloader.languages_path="https://cdnjs.cloudflare.com/ajax/libs/prism/%s/components/";</script>', ...
                        '<script src="https://cdnjs.cloudflare.com/ajax/libs/prism/%s/plugins/line-numbers/prism-line-numbers.min.js"></script>', ...
                        '<script src="https://cdnjs.cloudflare.com/ajax/libs/prism/%s/plugins/toolbar/prism-toolbar.min.js"></script>', ...
                        '<script src="https://cdnjs.cloudflare.com/ajax/libs/prism/%s/plugins/copy-to-clipboard/prism-copy-to-clipboard.min.js"></script>'], version, version, version, version, version, version);
    end

    customCss = ['<style>', newline, ...
        'body{margin:10px; font-family: Consolas, "Courier New", monospace; background:#fff; color:#000;}', newline, ...
        '.container{border:1px solid #ddd; border-radius:8px; overflow:hidden;}', newline, ...
        '.header{padding:8px 12px; background:#f8f8f8; border-bottom:1px solid #eee; display:flex; justify-content:space-between}', newline, ...
        '.controls{display:flex; gap:8px}', newline, '.btn{font-size:12px;padding:6px 10px;border-radius:4px;}','</style>', newline];
    head = [head, customCss];

    customJs = [...
        '<script>document.addEventListener("DOMContentLoaded", function(){try{var pre=document.querySelector("pre"); if(!pre) return; var btn=document.createElement("button"); btn.className="btn"; btn.textContent="折叠/展开"; btn.onclick=function(){ pre.style.display = (pre.style.display === "none") ? "" : "none"; }; var controls = document.querySelector(".controls"); if(controls) controls.insertBefore(btn, controls.firstChild);}catch(e){}});</script>'];

    html = ['<!doctype html><html><head><meta charset="utf-8">', sprintf('<title>Preview: %s</title>', htmlEscapeAttr(srcPath)), head, '</head><body>', ...
            '<div class="container">', sprintf('<div class="header"><div class="filename">%s</div><div class="controls"></div></div>', htmlEscapeAttr(srcPath)), ...
            '<div style="padding:12px; overflow:auto;">', sprintf('<pre class="line-numbers"><code class="language-matlab">%s</code></pre>', codeHtml), ...
            '</div></div>', foot, customJs, '</body></html>'];
end

function out = htmlEscapeForPre(s)
    if isempty(s), out = ''; return; end
    s = regexprep(s, '\r\n', '\n'); s = regexprep(s, '\r', '\n');
    s = strrep(s, '&', '&amp;'); s = strrep(s, '<', '&lt;'); s = strrep(s, '>', '&gt;');
    out = s;
end

function s = htmlEscapeAttr(x)
    s = x; s = strrep(s, '&', '&amp;'); s = strrep(s, '<', '&lt;'); s = strrep(s, '>', '&gt;'); s = strrep(s, '"', '&quot;');
end

%% 用于将数据中的Nan/inf等非有限数值转为有限数值。支持向量 / 矩阵 / N 维数组、保留原始数据类型与维度、对复数分量分别插值。
function Y = fillNonfinite(X, tdim, opts)
% fillNonfinite  Replace NaN/Inf (nonfinite) values in X with finite ones.
%
% Y = fillNonfinite(X)
% Y = fillNonfinite(X, [])
% Y = fillNonfinite(X, tdim)
% Y = fillNonfinite(X, [], opts)
% Y = fillNonfinite(X, tdim, opts)
%
% Inputs
%   X     - input array (vector / matrix / N-D array). May be real or complex.
%   tdim  - time dimension (positive integer). Works like to2DtimeMajor's tdim.
%   opts  - (optional) struct or string specifying behavior:
%           opts.method: 'interp' (default), 'previous', 'next', 'mean',
%                        'median', 'zero', 'value'
%           opts.replaceValue: numeric scalar used with 'value' or fallback
%           opts.strict: logical, forwarded to to2DtimeMajor (default false)
%
% Output
%   Y     - same size / class as X, with non-finite entries replaced.
%
% Notes / behavior:
%  - The function reshapes X to [N x channels] using your to2DtimeMajor, fills
%    along rows (time), then restores original shape/class.
%  - Default 'interp' performs linear interpolation along time for each
%    channel. For endpoints, it uses the nearest valid endpoint value.
%  - If a channel has zero valid points, it is filled with opts.replaceValue
%    (default 0 for numeric, false for logical).
%  - For integer classes the results are rounded and clipped to valid range.
%  - Works with complex arrays by interpolating real and imaginary parts
%    independently.
% 
%  - 默认方法 'interp' 在存在至少两个有效点时效果最好；两端会用最近的有效端点填充（不会外推不合理值）。
%  - 如果你的信号包含突发异常（大片 NaN/Inf），你可能愿意用 'previous' 或 'next'，或使用 replaceValue 指定特定值。
%  - 本函数对 integer 类型会四舍五入并裁剪到合法区间，避免越界错误；对 logical 类型会把非零视为 true（写回时以逻辑值返回）。
%  - 已考虑复数情况（实部和虚部分别插值/填充）。
%  - 函数内部通过 to2DtimeMajor 做 reshape/restore。
%  - 快速早退：在任何处理前检查整个 X 是否全为有限值；如果是，就直接 Y = X; return，避免任何维度变换和类型转换，显著加快常见情形（无 NaN/Inf）。
%  - 按列惰性处理：把数据 reshape 为 [N x channels] 后，仅对包含非有限值的通道（columns）进行填补；不需要的列保持原样，减少循环工作量。
%
%  Example:
%   % 简单矩阵
%   X = [1 NaN 3; Inf 5 6; NaN NaN 9];
%   % 假设时间维是第 1 维（行），每列为一个通道
%   Y = fillNonfinite(X, 1);
%   % 使用前向填充
%   Y_prev = fillNonfinite(X,1, struct('method','previous'));
%   % 使用常数替换
%   Y_val = fillNonfinite(X,1, struct('method','value','replaceValue',-1));
%
% Requires: the to2DtimeMajor function in the same path.
%
% Optimized: early return when no non-finite values; per-column lazy processing.

 
% Allow tdim to be optional: if omitted or empty, pick first non-singleton dim.
% If still not found (scalar input), warn and fall back to 1.
if nargin < 2 || isempty(tdim)
    szx = size(X);
    tdim = find(szx ~= 1, 1, 'first');   % first non-singleton dim
    if isempty(tdim) || tdim < 1
        warning('fillNonfinite:NoNonSingletonDim', ...
            'fillNonfinite: input appears scalar (no non-singleton dimension). Falling back to tdim = 1.');
        tdim = 1;
    end
end

% --- minimal tdim validation (keeps function safe) ---
if ~(isnumeric(tdim) && isscalar(tdim) && isfinite(tdim) && tdim==round(tdim) && tdim>=1)
    error('fillNonfinite:InvalidTimeDim','tdim must be a positive integer scalar.');
end

% --- default opts ---
defaultOpts = struct(...
    'method','interp', ...
    'replaceValue',0, ...
    'strict', false ...
    );

if nargin < 3 || isempty(opts)
    opts = defaultOpts;
else
    if ischar(opts) || isstring(opts)
        % shorthand: method string
        opts = struct('method',char(opts), 'replaceValue', defaultOpts.replaceValue, 'strict', false);
    else
        % merge provided struct with defaults
        fn = fieldnames(defaultOpts);
        for k = 1:numel(fn)
            if ~isfield(opts, fn{k})
                opts.(fn{k}) = defaultOpts.(fn{k});
            end
        end
    end
end

% validate method
validMethods = {'interp','previous','next','mean','median','zero','value'};
opts.method = validatestring(opts.method, validMethods);

origClass = class(X);

% --- QUICK PATH: if there are no non-finite values, return input immediately ---
% This avoids any costly reshape/permute/cast when not necessary.
% Use isfinite + any(...,'all') to avoid creating huge intermediate column vectors.
if ~any(~isfinite(X),'all')
    % nothing to do
    Y = X;
    return;
end

% warn user that non-finite values were found and will be replaced
nNonfinite = nnz(~isfinite(X));
warning('fillNonfinite:NonfiniteDetected', ...
    'fillNonfinite: input contains %d non-finite value(s) (NaN/Inf); these will be replaced using opts.method="%s".', ...
    nNonfinite, opts.method);

% --- slow path: there is at least one non-finite -> proceed with processing ---
% Use to2DtimeMajor to move tdim -> first dim and get restoreFn
[X2, restoreFn] = to2DtimeMajor(X, tdim, struct('strict', logical(opts.strict)));

% Work on double for numeric interpolation; handle complex separately
isComplex = ~isreal(X2);
N = size(X2,1);
channels = size(X2,2);

Xproc = double(X2);  % double copy for processing

% Precompute default replacement based on original class
if islogical(X)
    defaultReplace = false;
else
    defaultReplace = double(opts.replaceValue);
end

% Helper to cast entire matrix back to original class
function out = castBackMatrix(inMat)
    if isa(X, 'double')
        out = inMat;
        return;
    end
    if isa(X, 'single')
        out = single(inMat);
        return;
    end
    if isinteger(X)
        % round and clip to integer range
        className = origClass;
        mi = double(intmin(className));
        ma = double(intmax(className));
        inMat = round(inMat);
        inMat(inMat < mi) = mi;
        inMat(inMat > ma) = ma;
        out = cast(inMat, className);
        return;
    end
    if islogical(X)
        % threshold at 0.5
        out = inMat ~= 0;
        out = cast(out, 'logical');
        return;
    end
    % fallback: try cast, if fails keep double
    try
        out = cast(inMat, origClass);
    catch
        out = inMat;
    end
end

% Determine which columns actually contain any non-finite values (work on reduced set)
finiteMaskMat = isfinite(Xproc);         % [N x channels] logical
colsNeedFix = any(~finiteMaskMat, 1);    % 1 x channels logical
idxCols = find(colsNeedFix);

% If for some reason none need fixing (shouldn't happen because of earlier check), just restore
if isempty(idxCols)
    Y = restoreFn(castBackMatrix(Xproc));
    return;
end

% Prepare output matrix starting from original doubled data
Xfilled = Xproc;  % we'll only modify bad columns

% function to process a single column vector (double)
    function colOut = fillSingleColumn(col, method)
        finiteMask = isfinite(col);
        nFinite = nnz(finiteMask);
        switch method
            case 'interp'
                if nFinite == 0
                    col(:) = defaultReplace;
                elseif nFinite == 1
                    col(:) = col(finiteMask);
                else
                    idxFinite = find(finiteMask);
                    valFinite = col(idxFinite);
                    idxMissing = find(~finiteMask);
                    interpVals = interp1(idxFinite, valFinite, idxMissing, 'linear', NaN);
                    col(idxMissing) = interpVals;
                    if any(isnan(col))
                        firstIdx = idxFinite(1);
                        lastIdx = idxFinite(end);
                        col(1:firstIdx-1) = col(firstIdx);
                        col(lastIdx+1:end) = col(lastIdx);
                    end
                end

            case 'previous'
                if nFinite == 0
                    col(:) = defaultReplace;
                else
                    lastVal = [];
                    for ii = 1:N
                        if finiteMask(ii)
                            lastVal = col(ii);
                        else
                            if ~isempty(lastVal)
                                col(ii) = lastVal;
                            else
                                col(ii) = defaultReplace;
                            end
                        end
                    end
                end

            case 'next'
                if nFinite == 0
                    col(:) = defaultReplace;
                else
                    nextVal = [];
                    for ii = N:-1:1
                        if finiteMask(ii)
                            nextVal = col(ii);
                        else
                            if ~isempty(nextVal)
                                col(ii) = nextVal;
                            else
                                col(ii) = defaultReplace;
                            end
                        end
                    end
                end

            case 'mean'
                if nFinite == 0
                    col(:) = defaultReplace;
                else
                    col(~finiteMask) = mean(col(finiteMask),'omitnan');
                end

            case 'median'
                if nFinite == 0
                    col(:) = defaultReplace;
                else
                    col(~finiteMask) = median(col(finiteMask),'omitnan');
                end

            case 'zero'
                col(~finiteMask) = 0;

            case 'value'
                col(~finiteMask) = defaultReplace;

            otherwise
                col(~finiteMask) = defaultReplace;
        end
        colOut = col;
    end

% Process only the required columns
if isComplex
    % real + imag separately, only on needed columns
    realPart = real(Xproc);
    imagPart = imag(Xproc);
    for k = idxCols
        realPart(:,k) = fillSingleColumn(realPart(:,k), opts.method);
        imagPart(:,k) = fillSingleColumn(imagPart(:,k), opts.method);
    end
    Xfilled = realPart + 1i*imagPart;
else
    for k = idxCols
        Xfilled(:,k) = fillSingleColumn(Xfilled(:,k), opts.method);
    end
end

% Cast back and restore shape
Y2 = castBackMatrix(Xfilled);
Y = restoreFn(Y2);

end

%% 将数组 X 的时间维移动到第一维并 reshape 为 [N x channels]。
function [X2, restoreFn] = to2DtimeMajor(X, tdim, varargin)
% to2DtimeMajor  将数组 X 的时间维移动到第一维并重塑为 [N x channels]
%   [X2, restoreFn] = to2DtimeMajor(X, tdim)
%   [X2, restoreFn] = to2DtimeMajor(X, tdim, strict)
%   [X2, restoreFn] = to2DtimeMajor(X, tdim, opts)
%
% 说明：
%  - tdim 可以大于 ndims(X)；默认情况下会假定末尾为单例维（即补 1）。
%  - 如果第三个参数为 true（或 opts.strict==true），当 tdim > ndims(X) 时函数将报错（严格模式）。默认是 false（发出警告）。
%  - restoreFn 接受 Y2（newN x channels）并返回还原为原始形状的 Y。
%
% 本版本的鲁棒性增强：
%  - 如果恢复步骤会把复数数组强制转换为整数类，本版本会抛出错误（按请求选择严格行为）。
%  - 对整数类的转换会进行四舍五入并裁剪到合法范围后再 cast。
%  - 逻辑值通过阈值恢复（非零 -> true）。
%
% 示例：
%   X = rand(5,4);       % size = [5 4]
%   [X2, rfn] = to2DtimeMajor(X, 4);   % -> 发出警告并继续
%   % 严格模式（会报错）
%   try
%       [X2, rfn] = to2DtimeMajor(X, 4, true); % -> 报错
%   catch ME
%       disp(ME.message);
%   end
%
%   % opts 结构体用法
%   [X2, rfn] = to2DtimeMajor(X, 4, struct('strict',false)); % 与默认（发出警告）相同
%

% --- Argument validation: tdim ---
if ~(isnumeric(tdim) && isscalar(tdim) && isfinite(tdim) && tdim==round(tdim) && tdim>=1)
    error('to2DtimeMajor:InvalidTimeDim','tdim must be a positive integer scalar.');
end

% --- parse optional strict/opts argument ---
strict = false;
if ~isempty(varargin)
    arg3 = varargin{1};
    if isstruct(arg3) && isfield(arg3,'strict')
        strict = logical(arg3.strict);
    elseif islogical(arg3) || (isnumeric(arg3) && isscalar(arg3))
        strict = logical(arg3);
    else
        error('to2DtimeMajor:InvalidThirdArg', ...
              'Third argument must be a logical scalar or a struct with field ''strict''.');
    end
end

origClass = class(X);
% record original size vector (do NOT pad yet for warning check)
origSz = size(X);
% number of explicit size entries (note: size(X) returns at least 2 entries)
ndX = numel(origSz);

% --- warn or error if tdim exceeds original dimensionality ---
if tdim > ndX
    msg = sprintf(['to2DtimeMajor: requested tdim=%d is greater than the ' ...
                   'number of dimensions reported by size(X)=%d. ' ...
                   'Trailing singleton dimensions will be assumed and used. ' ...
                   'If this is unintended, call with strict=true to make this an error.'], ...
                   tdim, ndX);
    if strict
        error('to2DtimeMajor:TimeDimTooLarge', msg);
    else
        warning('to2DtimeMajor:TimeDimExceedsDims', msg);
    end
end

% --- now pad origSz so later restore knows about implied singletons ---
if numel(origSz) < tdim
    origSz = [origSz, ones(1, tdim - numel(origSz))];
end

% get size vector and ensure it has at least tdim elements (pad with ones)
sz = origSz;
nd = max(ndims(X), numel(sz)); % ndims can be less than numel(sz) in odd cases
nd_new = max(numel(sz), tdim);

% create permutation: move tdim to position 1
if tdim ~= 1
    perm = 1:nd_new;
    perm([1, tdim]) = perm([tdim, 1]);
    % For permute to work, ensure X has nd_new dimensions (pad with singleton)
    if numel(size(X)) < nd_new
        X = reshape(X, [size(X), ones(1, nd_new - numel(size(X)))]); %#ok<NVREPL>
    end
    Xp = permute(X, perm);
else
    perm = 1:nd_new;
    if numel(size(X)) < nd_new
        Xp = reshape(X, [size(X), ones(1, nd_new - numel(size(X)))]); %#ok<NVREPL>
    else
        Xp = X;
    end
end

szp = size(Xp);
N = szp(1);
% channels = product of remaining dims (if none, prod([]) -> 1)
if numel(szp) > 1
    channels = prod(szp(2:end));
else
    channels = 1;
end

% reshape into [N x channels] (works for empty, scalar, vector, matrix, nd arrays)
X2 = reshape(Xp, N, channels);

% --- restore function ---
function Y = restore(Y2)
    % Y2 is expected to be [newN x channels]
    newN = size(Y2,1);
    % rebuild shape consistent with original size origSz except replace tdim with newN
    targetSz = origSz;
    targetSz(tdim) = newN;

    % compute permuted target shape (shape after permute)
    if tdim ~= 1
        permutedTarget = targetSz(perm);
    else
        permutedTarget = targetSz;
    end

    % reshape back to permuted shape
    Yp = reshape(Y2, permutedTarget);

    % invert permutation if needed
    if tdim ~= 1
        Y = ipermute(Yp, perm);
    else
        Y = Yp;
    end

    % Attempt to cast back to original class only when meaningful.
    % For numeric/logical/integer types we try to cast; for other classes
    % we attempt cast in a try/catch (safe fallback to keep numeric type).
    try
        if ~isa(Y, origClass)
            if isCommonNumericOrLogicalClass(origClass)
                % integer class list
                intList = {'int8','int16','int32','int64', ...
                           'uint8','uint16','uint32','uint64'};
                if any(strcmp(origClass, intList))
                    % Strict behavior: do not silently drop imaginary part.
                    if ~isreal(Y)
                        error('to2DtimeMajor:ComplexToInteger', ...
                            ['Attempt to cast complex result back to integer class (%s). ' ...
                             'This is not allowed; ensure the data is real before casting.'], origClass);
                    end
                    % Round and clip to integer range
                    try
                        mi = double(intmin(origClass));
                        ma = double(intmax(origClass));
                    catch
                        mi = -inf; ma = inf;
                    end
                    Y = round(Y);
                    Y(Y < mi) = mi;
                    Y(Y > ma) = ma;
                    Y = cast(Y, origClass);
                elseif strcmp(origClass, 'logical')
                    % Convert numeric to logical by nonzero -> true
                    % If complex, still error because logical cannot represent complex
                    if ~isreal(Y)
                        error('to2DtimeMajor:ComplexToLogical', ...
                            'Attempt to cast complex result back to logical. Ensure data is real.');
                    end
                    Y = (Y ~= 0);
                    Y = cast(Y, 'logical');
                else
                    % double / single: just cast (they support complex)
                    Y = cast(Y, origClass);
                end
            else
                % best-effort: try cast but if it fails, keep numeric result
                try
                    Y = cast(Y, origClass);
                catch
                    % do nothing: keep Y as-is
                end
            end
        end
    catch
        % rethrow to preserve stack if it was intentionally an error
        lasterr = lasterror; %#ok<LERR>
        if strcmp(lasterr.identifier,'to2DtimeMajor:ComplexToInteger') || ...
           strcmp(lasterr.identifier,'to2DtimeMajor:ComplexToLogical')
            rethrow(lasterr);
        else
            % swallow unexpected casting error and keep Y unchanged
        end
    end
end

restoreFn = @restore;
end

% --- helper: detect common numeric/logical/integer classes that cast supports ---
function tf = isCommonNumericOrLogicalClass(className)
% list of typical numeric/logical classes in MATLAB
persistent commonList;
if isempty(commonList)
    commonList = {'double','single','logical', ...
                  'int8','int16','int32','int64', ...
                  'uint8','uint16','uint32','uint64'};
end
tf = any(strcmp(className, commonList));
end

%% 用于updateFilteredLegends()、updatePlotModeOnly() 将可能的嵌套图形句柄结构展开为有效的图形句柄行向量
% -------- helper: flatten a stored entry into valid graphics handles array --------
function hArr = flattenHandlesEntry(entry)
    hArr = gobjects(0);
    if isempty(entry), return; end
    % If it's a cell (each cell may contain handles), flatten
    if iscell(entry)
        % convert cell of handles to handle array
        tmp = [];
        for ii = 1:numel(entry)
            e = entry{ii};
            if isempty(e), continue; end
            if iscell(e)
                for jj = 1:numel(e)
                    tmp = [tmp, e{jj}]; %#ok<AGROW>
                end
            else
                tmp = [tmp, e(:).']; %#ok<AGROW>
            end
        end
        hCand = tmp;
    else
        % entry is numeric/handle array or single handle
        hCand = entry(:).';
    end
    % Keep only graphics handles that are valid
    keepIdx = arrayfun(@(h) isgraphics(h) && isvalid(h), hCand);
    if any(keepIdx)
        hArr = hCand(keepIdx);
    else
        hArr = gobjects(0);
    end
end

%% ----- 将uifigure放到屏幕中央 -----
function fig = createCenteredUIFigure(varargin)
% createCenteredUIFigure 兼容 uifigure 的居中创建函数
% Usage examples:
%   fig = createCenteredUIFigure('Name','My','Position',[560,500,620,280],'WindowStyle','modal');
%   fig = createCenteredUIFigure(620,280,'Name','My','WindowStyle','modal');
%   fig = createCenteredUIFigure('Position',[560,500,620,280],'MonitorIndex',2,'Name','My');
%
% Behavior:
%  - 优先尝试读取 Position（如果调用中有提供），并以其中的宽高（第三、四元素）作为对话框大小；
%  - 若没有提供 Position，也支持调用时传入两个数值（createCenteredUIFigure(w,h, ...)）作为宽高；
%  - 然后优先取鼠标所在显示器（或可透传 'MonitorIndex', k）并把窗口居中；
%  - 如果居中过程出错，就回退到用户原本给定的 Position（若有），否则再尝试使用主屏中心（mon(1,:)）；
%  - 最后仍失败则降级到 uifigure(...) 的默认创建，保证不会抛异常中断程序。


% --- 解析输入：提取 Position / MonitorIndex，并构建传递给 uifigure 的 name-value 列表 ---
origPosition = []; % 如果用户提供了 Position，保留以便回退
monitorIndex = [];
uifigArgs = {}; % name-value 对（不含 Position / MonitorIndex）

ii = 1;
% 支持第一、二个位置参数为 (width, height)
if numel(varargin) >= 2 && isnumeric(varargin{1}) && isnumeric(varargin{2}) && isscalar(varargin{1}) && isscalar(varargin{2})
    dlgW = double(varargin{1});
    dlgH = double(varargin{2});
    ii = 3;
else
    dlgW = [];
    dlgH = [];
end

while ii <= numel(varargin)
    arg = varargin{ii};
    if ischar(arg) || isStringScalar(arg)
        key = char(arg);
        % 处理可能的 Name-Value 对
        if ii+1 <= numel(varargin)
            val = varargin{ii+1};
            if strcmpi(key,'Position')
                % Position 可以是 [x y w h]
                if ~isnumeric(val) || numel(val) ~= 4
                    % 保存原样以便传递给 uifigure（也可能出错）
                    origPosition = val;
                else
                    origPosition = double(val(:))';
                    % 取宽高
                    dlgW = double(origPosition(3));
                    dlgH = double(origPosition(4));
                end
                % 不把 Position 直接加入 uifigArgs（我们会覆盖/或回退时再用）
                ii = ii + 2;
                continue;
            elseif strcmpi(key,'MonitorIndex')
                monitorIndex = val;
                ii = ii + 2;
                continue;
            else
                % 其它 Name-Value，转发
                uifigArgs(end+1:end+2) = {key, val}; %#ok<AGROW>
                ii = ii + 2;
                continue;
            end
        else
            % 单独的字符串参数（非完整 Name-Value），直接转发
            uifigArgs{end+1} = arg; %#ok<AGROW>
            ii = ii + 1;
            continue;
        end
    else
        % 非字符串参数（例如直接传入 Position 向量作为第一个参数）
        if isnumeric(arg) && numel(arg) == 4 && isempty(origPosition)
            origPosition = double(arg(:))';
            dlgW = double(origPosition(3));
            dlgH = double(origPosition(4));
            ii = ii + 1;
            continue;
        else
            % 其它位置参数直接转发
            uifigArgs{end+1} = arg; %#ok<AGROW>
            ii = ii + 1;
            continue;
        end
    end
end

% 如果仍然没有得到 dlgW/dlgH，使用一个合理默认（和你之前的 fallback 保持一致）
if isempty(dlgW) || isempty(dlgH)
    % 如果用户给了 origPosition 但解析失败（非常罕见），尝试取第三/四元素
    if ~isempty(origPosition) && numel(origPosition) >= 4
        try
            dlgW = double(origPosition(3));
            dlgH = double(origPosition(4));
        catch
            dlgW = 620; dlgH = 280;
        end
    else
        dlgW = 620; dlgH = 280;
    end
end

% --- 尝试居中计算并创建 uifigure（优先策略：鼠标所在显示器 -> monitorIndex -> mon(1)） ---
created = false;
fig = [];
try
    mon = get(0,'MonitorPositions'); % rows: [left bottom width height]
    mon = double(mon);
    if isempty(mon)
        error('MonitorPositions 为空');
    end

    % 选择显示器索引
    idx = 1;
    if ~isempty(monitorIndex)
        if ~isscalar(monitorIndex) || monitorIndex < 1 || monitorIndex > size(mon,1)
            warning('指定 MonitorIndex 无效，使用默认显示器 1。');
            monitorIndex = [];
        else
            idx = round(monitorIndex);
        end
    end

    if isempty(monitorIndex)
        % 尝试用鼠标位置选择显示器
        try
            p = get(0,'PointerLocation'); % [x y]
        catch
            p = [];
        end
        if ~isempty(p) && size(mon,1) > 0
            found = false;
            for k = 1:size(mon,1)
                left = mon(k,1); bottom = mon(k,2); w = mon(k,3); h = mon(k,4);
                if p(1) >= left && p(1) <= left + w && p(2) >= bottom && p(2) <= bottom + h
                    idx = k; found = true; break;
                end
            end
            if ~found
                idx = 1;
            end
        else
            idx = 1;
        end
    end

    % 所选显示器参数
    left = mon(idx,1); bottom = mon(idx,2); width = mon(idx,3); height = mon(idx,4);

    posX = round(left + (width - dlgW)/2);
    posY = round(bottom + (height - dlgH)/2);

    % final position
    finalPos = [posX, posY, dlgW, dlgH];

    % 创建 uifigure（将用户传入的其它 name-value 对透传，Position 由本函数设置）
    fig = uifigure(uifigArgs{:}, 'Position', finalPos);
    created = true;
catch centErr
    % 居中失败 -> 回退到用户提供的 origPosition（如果有）
    try
        if ~isempty(origPosition) && numel(origPosition) == 4
            fig = uifigure(uifigArgs{:}, 'Position', origPosition);
            created = true;
        else
            % 再尝试主屏中心（mon(1,:)，若 mon 可用）
            try
                mon2 = get(0,'MonitorPositions');
                if ~isempty(mon2)
                    left = mon2(1,1); bottom = mon2(1,2); width = mon2(1,3); height = mon2(1,4);
                    posX = round(left + (width - dlgW)/2);
                    posY = round(bottom + (height - dlgH)/2);
                    fig = uifigure(uifigArgs{:}, 'Position', [posX, posY, dlgW, dlgH]);
                    created = true;
                else
                    % 最后退回（不指定 Position）
                    fig = uifigure(uifigArgs{:});
                    created = true;
                end
            catch innerErr
                % 最后退回到不带 Position 的创建，确保不会抛异常
                fig = uifigure(uifigArgs{:});
                created = true;
            end
        end
    catch finalErr
        % 无论何种失败，尽量确保返回一个 figure，不要抛异常
            warning('createCenteredUIFigure:CenteringFailed', ...
        '无法自动居中（%s），使用默认位置创建 uifigure。', centErr.message);
        try
            fig = uifigure();
            created = true;
        catch
            % 极端情况下创建失败则抛出原始居中错误
            rethrow(centErr);
        end
    end
end

end

%% ----- 将figure放到屏幕中央 -----
function fig = createCenteredFigure(varargin)
% createCenteredFigure 兼容 figure 的居中创建函数
% 可直接替换工程中的 figure 调用： fig = figure(...); -> fig = createCenteredFigure(...);
%
% 行为摘要：
%  - 如果首个位置参数是数字/句柄（例如 figure(h)），直接调用内置 figure 并返回。
%  - 优先使用传入的 'Position' [x y w h] 的 w,h 计算居中位置并创建窗口。
%  - 若未提供 Position，则先用 Visible='off' 创建 figure，读取默认尺寸，再居中并恢复 Visible。
%  - 多重回退逻辑：居中失败 -> 回退到用户提供的 Position -> 回退到主屏中心 -> 直接调用内置 figure。
%
% 兼容的常见调用举例：
%   createCenteredFigure('Name','标题','Position',[100,100,1200,800]);
%   createCenteredFigure(handles.figCompare);   % 与 figure(handles.figCompare) 等价
%   createCenteredFigure('Visible','off','Position',[100,100,900,600]);

% ----------- 如果第一个参数是数字或句柄，直接调用内置 figure 并返回 -----------
if ~isempty(varargin) && (isnumeric(varargin{1}) || any(isgraphics(varargin{1})))
    % 直接透传给内置 figure
    fig = builtin('figure', varargin{:});
    return;
end

% ----------- 解析输入，提取 Position / Visible / Units，构造要透传的参数列表 -----------
origPosition = [];   % 如果用户提供了 Position（用于回退）
userVisible = [];    % 用户是否指定 Visible（用于还原）
uifigArgs = {};      % 透传给内置 figure 的 name-value 列表（排除 Position）
ii = 1;
while ii <= numel(varargin)
    arg = varargin{ii};
    if ischar(arg) || (isstring(arg) && isscalar(arg))
        key = char(arg);
        if ii+1 <= numel(varargin)
            val = varargin{ii+1};
            if strcmpi(key,'Position')
                if isnumeric(val) && numel(val)==4
                    origPosition = double(val(:))';
                else
                    % 非标准 Position，仍保留以便回退时传递
                    origPosition = val;
                end
                ii = ii + 2;
                continue;
            elseif strcmpi(key,'Visible')
                userVisible = val;
                % 暂不把 Visible 加入 uifigArgs（我们会在创建时处理）
                ii = ii + 2;
                continue;
            else
                % 其它 Name-Value 透传
                uifigArgs(end+1:end+2) = {key, val}; %#ok<AGROW>
                ii = ii + 2;
                continue;
            end
        else
            % 单独字符串（不完整 Name-Value），透传
            uifigArgs{end+1} = arg; %#ok<AGROW>
            ii = ii + 1;
            continue;
        end
    else
        % 非字符串参数（例如直接传入 Position 向量）
        if isnumeric(arg) && numel(arg)==4 && isempty(origPosition)
            origPosition = double(arg(:))';
            ii = ii + 1;
            continue;
        else
            uifigArgs{end+1} = arg; %#ok<AGROW>
            ii = ii + 1;
            continue;
        end
    end
end

% 如果用户提供了 Position，取出宽高用于居中
if ~isempty(origPosition) && isnumeric(origPosition) && numel(origPosition)==4
    dlgW = double(origPosition(3));
    dlgH = double(origPosition(4));
else
    dlgW = [];
    dlgH = [];
end

% 若没有尺寸，使用一个合理默认（与之前的默认保持一致）
if isempty(dlgW) || isempty(dlgH)
    dlgW = 620; dlgH = 280;
end

% ----------- 计算中心位置的函数（基于 MonitorPositions & PointerLocation） -----------
    function pos = computeCenterPos(widthPx, heightPx)
        % 返回 [x y widthPx heightPx]，若出错抛出异常
        mon = get(0,'MonitorPositions'); % rows: [left bottom width height]
        if isempty(mon)
            error('MonitorPositions 为空');
        end
        mon = double(mon);
        % 尝试找到鼠标所在显示器
        try
            p = get(0,'PointerLocation'); % [x y]
        catch
            p = [];
        end
        idx = 1;
        if ~isempty(p)
            for k = 1:size(mon,1)
                left = mon(k,1); bottom = mon(k,2); w = mon(k,3); h = mon(k,4);
                if p(1) >= left && p(1) <= left + w && p(2) >= bottom && p(2) <= bottom + h
                    idx = k; break;
                end
            end
        end
        left = mon(idx,1); bottom = mon(idx,2); w = mon(idx,3); h = mon(idx,4);
        x = round(left + (w - widthPx)/2);
        y = round(bottom + (h - heightPx)/2);
        pos = [x, y, widthPx, heightPx];
    end

% ----------- 尝试主逻辑：优先用计算的居中位置创建窗口 -----------
created = false;
fig = [];
try
    finalPos = computeCenterPos(dlgW, dlgH);
    % 如果用户明确指定 Visible='off'，保持不可见以避免闪烁；否则我们暂用 'Visible','off' 创建，
    % 在设置完位置后再把 Visible 设为用户期望的值（或默认 'on'）。
    if isempty(userVisible)
        % 未指定 Visible：我们先创建不可见以调整位置，随后设为 'on'
        tmpVisibleVal = 'off';
        finalVisibleRestore = 'on';
    else
        tmpVisibleVal = 'off';
        finalVisibleRestore = userVisible;
    end

    % 创建 figure：Position 由本函数设置，其它 name-value 对透传
    fig = builtin('figure', uifigArgs{:}, 'Position', finalPos, 'Visible', tmpVisibleVal);
    % 创建成功，恢复用户期望的 Visible（可能是 'off' 或 'on'）
    try
        fig.Visible = finalVisibleRestore;
    catch
        % 忽略无法设置 Visible 的情况
    end
    created = true;
catch centerErr
    % 居中创建失败 -> 回退路径（优先使用用户原始 Position）
    try
        if ~isempty(origPosition) && isnumeric(origPosition) && numel(origPosition)==4
            % 若用户提供了原始 Position，直接用之（并保留其它属性）
            fig = builtin('figure', uifigArgs{:}, 'Position', origPosition, 'Visible', userVisibleIfEmpty(userVisible));
            created = true;
        else
            % 再尝试主屏（mon(1,:）的居中）
            try
                mon2 = get(0,'MonitorPositions');
                if ~isempty(mon2)
                    left = mon2(1,1); bottom = mon2(1,2); w = mon2(1,3); h = mon2(1,4);
                    posX = round(left + (w - dlgW)/2);
                    posY = round(bottom + (h - dlgH)/2);
                    fig = builtin('figure', uifigArgs{:}, 'Position', [posX, posY, dlgW, dlgH], 'Visible', userVisibleIfEmpty(userVisible));
                    created = true;
                else
                    % 最后回退到直接调用（不带 Position）
                    fig = builtin('figure', uifigArgs{:});
                    created = true;
                end
            catch innerErr
                % 最后回退到直接调用（不带 Position）
                fig = builtin('figure', uifigArgs{:});
                created = true;
            end
        end
    catch finalErr
        % 极端情况下确保返回一个 figure（不要抛原始异常）
        warning('createCenteredFigure:CenteringFailed','无法居中或回退，最终使用默认 figure（错误: %s）', centerErr.message);
        try
            fig = builtin('figure');
            created = true;
        catch
            rethrow(centerErr);
        end
    end
end

end

% ----------- 辅助子函数：如果 userVisible 为空，返回 'on' 作为默认 -----------
function v = userVisibleIfEmpty(userVisible)
    if isempty(userVisible)
        v = 'on';
    else
        v = userVisible;
    end
end

%% 获取鼠标所在的显示器的尺寸
function [left, bottom, width, height, idx] = pickMonitorByPointerFirst(monitorIndex)
% PICKMONITORBYPOINTERFIRST 选择显示器：优先使用鼠标所在显示器
% 返回所选显示器的 left,bottom,width,height (像素) 以及索引 idx
% monitorIndex - (可选) 用户指定的显示器索引（1..N）
%
% 逻辑：
%   1) 尝试读取鼠标位置并找出鼠标在哪个显示器上 -> 使用该显示器
%   2) 若未找到鼠标或读取失败，则使用 monitorIndex（若有效）
%   3) 否则回退到显示器 1

    mon = get(0,'MonitorPositions');    % [left bottom width height] per row
    mon = double(mon);
    if isempty(mon)
        error('无法获取 MonitorPositions（返回为空）。');
    end

    % 默认选择第1个显示器
    idx = 1;

    % ----- 1) 优先尝试用鼠标位置确定显示器 -----
    p = [];
    try
        p = get(0,'PointerLocation');    % [x y]（像素）
    catch
        p = [];
    end

    foundByPointer = false;
    if ~isempty(p) && ~any(isnan(p))
        % 在每个显示器范围内判断鼠标是否落在其内
        for k = 1:size(mon,1)
            left_k   = mon(k,1);
            bottom_k = mon(k,2);
            w_k      = mon(k,3);
            h_k      = mon(k,4);
            if p(1) >= left_k && p(1) <= (left_k + w_k) && ...
               p(2) >= bottom_k && p(2) <= (bottom_k + h_k)
                idx = k;
                foundByPointer = true;
                break;
            end
        end
    end

    % ----- 2) 如果鼠标未能决定显示器，则尝试 monitorIndex -----
    if ~foundByPointer
        if exist('monitorIndex','var') && ~isempty(monitorIndex)
            if isscalar(monitorIndex) && monitorIndex >= 1 && monitorIndex <= size(mon,1)
                idx = round(monitorIndex);
            else
                warning('指定的 monitorIndex 无效，使用默认显示器 1。');
                idx = 1;
            end
        else
            % 未指定 monitorIndex，保持 idx = 1
            idx = 1;
        end
    end

    % ----- 返回所选显示器参数 -----
    left   = mon(idx,1);
    bottom = mon(idx,2);
    width  = mon(idx,3);
    height = mon(idx,4);
end


%% ----- 提醒弹窗 -----
function uialert_safe(parent, msg, title, varargin)
% UIALERT_SAFE 兼容并安全调用 uialert
%   uialert_safe(parent, msg, title, Name,Value,...) 会尽量使用 uialert
%   若 parent 缺失或无效，或 uialert 调用失败，则退回到 errordlg/warndlg/msgbox
%
% 示例：
%   uialert_safe(fig, "警告：...", "警告", "Icon", "warning");
%
% 该函数对 string 类型参数做了 char 转换，并尽量保留 Icon 名称以选用合适的回退对话框。

    % 防御性参数处理
    if nargin < 2
        return;
    end
    if nargin < 3
        title = '';
    end

    % 将 string -> char（兼容新旧 matlab string 类型）
    if isstring(msg),  msg = char(msg); end
    if isstring(title), title = char(title); end
    for k = 1:numel(varargin)
        if isstring(varargin{k}), varargin{k} = char(varargin{k}); end
    end

    % 帮助函数：从 Name-Value 中提取 Icon（若存在）
    function ic = extractIcon(v)
        ic = '';
        try
            for ii = 1:2:numel(v)-1
                if ischar(v{ii}) && strcmpi(v{ii}, 'Icon')
                    ic = v{ii+1};
                    return;
                end
            end
        catch
            ic = '';
        end
    end

    iconVal = extractIcon(varargin);

    % 主调用流程：优先尝试 uialert(parent,...)
    try
        if exist('parent','var') && ~isempty(parent) && isvalid(parent)
            % 直接尝试把所有参数透传给 uialert（若 uialert 存在且可用）
            try
                % 如果系统上有 uialert 函数，就调用；否则这一块会抛错并被下面捕获
                uialert(parent, msg, title, varargin{:});
                return; % 成功则返回
            catch
                % uialert 存在但调用失败（比如 parent 不是 uifigure，或传参类型不被接受）
                % 继续走回退逻辑
            end
        end

        % 如果没有有效 parent 或 uialert 无法使用，使用传统对话框作为回退
        try
            switch lower(string(iconVal))
                case 'warning'
                    warndlg(msg, title);
                case 'info'
                    helpdlg(msg, title);   % info -> helpdlg 比 msgbox 更合适
                case 'none'
                    msgbox(msg, title);
                case 'success'            % 没有内置 success 对话框，使用 msgbox
                    msgbox(msg, title);
                otherwise
                    % 默认使用 errordlg（与 uialert 默认 icon = 'error' 保持一致）
                    errordlg(msg, title);
            end
            return;
        catch
            % 回退对话框也可能失败（极少见），继续到最终打印
        end

    catch ME 
        % 捕获所有未预见的错误，下面继续回退
    end

    % 最终回退：控制台打印，保证不会抛出异常
    try
        fprintf(2, '**%s**: %s\n', title, msg);
    catch
        % 如果 fprintf 也不行（非常罕见），静默返回
    end
end
